#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0
#define MCP3008_CHANNEL  0
#define MCP3008_CE_PIN   8
#define FLAME_DIGITAL_PIN 4
#define LOG_FILE         "flame_data.csv"
#define SAMPLE_INTERVAL  1.0

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_flame_sensor(void) {
    return gpioRead(FLAME_DIGITAL_PIN);
}

static float calculate_temperature(int adc_value) {
    if (adc_value < 0) return -999.0f;
    return (float)adc_value * 0.1f;
}

static int log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature) < 0) {
        perror("fprintf(log_data)");
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

static void cleanup(void) {
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_spi_fd >= 0) { close(g_spi_fd); g_spi_fd = -1; }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_DIGITAL_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(FLAME_DIGITAL_PIN) failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(MCP3008_CE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(MCP3008_CE_PIN) failed\n");
        cleanup();
        return 1;
    }
    gpioWrite(MCP3008_CE_PIN, 1);

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,FlameDetected,Temperature\n");
        fflush(g_log_fp);
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading MCP3008 channel %d\n", MCP3008_CHANNEL);
            time_sleep(SAMPLE_INTERVAL);
            continue;
        }

        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor digital pin\n");
            time_sleep(SAMPLE_INTERVAL);
            continue;
        }

        float temperature = calculate_temperature(adc_value);

        if (log_data(flame_detected, temperature) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        time_sleep(SAMPLE_INTERVAL);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

