        if (adc_value < 0) {
            fprintf(stderr, "Error reading MCP3008 channel %d\n", MCP3008_CHANNEL);
            time_sleep(SAMPLE_INTERVAL);
            continue;
        }

        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor digital pin\n");
            time_sleep(SAMPLE_INTERVAL);
