#define LOG_FILE         "current_log.txt"
#define SAMPLE_INTERVAL  1

#define CURRENT_THRESHOLD 100.0f

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = len,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int read_adc(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static float adc_to_current(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX) {
        return -1.0f;
    }
    return (float)adc_value * 3.3f / (float)ADC_MAX;
}

static int log_data(const char *filename, float current) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Current: %.2f A\n", timestamp, current);
    fclose(fp);
    return 0;
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *fan_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME_FALLBACK);
    }
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO_LINE);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        goto cleanup;
    }

    printf("Monitoring current sensor on MCP3008 channel %d...\n", ADC_CHANNEL);

    while (program_running) {
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr, "Warning: ADC reading at extreme (%d) - sensor absent or disconnected\n", adc_value);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float current = adc_to_current(adc_value);
        if (current < 0.0f) {
            fprintf(stderr, "Error converting ADC value to current\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (log_data(LOG_FILE, current) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        if (current > CURRENT_THRESHOLD) {
            if (gpiod_line_set_value(fan_line, 1) < 0) {
                perror("Failed to set fan HIGH");
            } else {
                printf("Current %.2f A exceeds threshold, fan ON\n", current);
            }
        } else {
            if (gpiod_line_set_value(fan_line, 0) < 0) {
                perror("Failed to set fan LOW");
            } else {
                printf("Current %.2f A below threshold, fan OFF\n", current);
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

