#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/*
 * Calibration parameters for the MICS-4514 dual-element sensor.
 * Replace with values from your specific sensor calibration.
 */
#define R0_CO 10000.0f
#define R_LOAD_RESISTOR 10000.0f
#define VREF 3.3f
#define ADC_MAX 32767.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read the 16-bit raw value from the ADS1115 ADC.
 * Returns 0 on success, -1 on failure.
 */
static int read_ads1115(int handle, int16_t *raw) {
    char buf[2];

    /*
     * ADS1115 register pointer: 0x00.
     * Read 2 bytes starting at register 0x00 (conversion register).
     */
    if (i2cWriteByte(handle, 0x00) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }

    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Convert raw ADC value to CO resistance (ohms).
 * Uses the MICS-4514 dual-element sensor:
 *   R_CO = R_LOAD * (VREF - V_out) / V_out
 * where V_out is the output voltage from the sensor.
 */
static float calculate_co_resistance(int16_t raw) {
    float voltage = (float)raw / ADC_MAX * VREF;
    if (voltage <= 0.0f) {
        return 0.0f;
    }
    return R_LOAD_RESISTOR * (VREF - voltage) / voltage;
}

/*
 * Convert CO resistance to ppm using a calibrated logarithmic curve.
 * Replace the calibration curve with values from your specific sensor.
 */
static float calculate_co_ppm(float r_co) {
    if (r_co <= 0.0f) {
        return 0.0f;
    }
    float log_r = log10f(r_co);
    float log_r0 = log10f(R0_CO);
    float ppm = powf(10.0f, 1.0f - (log_r / log_r0));
    return ppm;
}

static int log_data(const char *filename, float ppm) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f ppm\n", timestamp, ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO sensor monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw;
        if (read_ads1115(i2c_handle, &raw) != 0) {
            fprintf(stderr, "Error reading from I2C device. Sensor may be disconnected.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float r_co = calculate_co_resistance(raw);
        float ppm = calculate_co_ppm(r_co);

        if (log_data(LOG_FILE, ppm) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("CO: %.2f ppm (raw=%d, R_CO=%.2f ohms)\n", ppm, raw, r_co);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

