#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define MCP3008_CS_GPIO 8
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LOG_FILE "flame_data.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_flame_sensor(void) {
    int level = gpioRead(FLAME_SENSOR_GPIO);
    if (level < 0) {
        fprintf(stderr, "Error reading flame sensor GPIO: %d\n", level);
        return -1;
    }
    return level;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (gpioWrite(MCP3008_CS_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to assert MCP3008 CS\n");
        return -1;
    }

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        gpioWrite(MCP3008_CS_GPIO, 1);
        return -1;
    }

    if (gpioWrite(MCP3008_CS_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to deassert MCP3008 CS\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float convert_to_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -999.0f;
    }
    return (float)adc_value * 0.01f;
}

static int log_data(int flame_presence, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_presence, temperature) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MCP3008_CS_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MCP3008 CS GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(MCP3008_CS_GPIO, 1);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_presence = read_flame_sensor();
        if (flame_presence < 0) {
            fprintf(stderr, "Error reading flame sensor, skipping entry.\n");
        } else {
            int adc_value = read_mcp3008(0);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading MCP3008, skipping entry.\n");
            } else {
                float temperature = convert_to_temperature(adc_value);
                if (temperature <= -998.0f) {
                    fprintf(stderr, "Error converting ADC to temperature, skipping entry.\n");
                } else {
                    if (log_data(flame_presence, temperature) < 0) {
                        fprintf(stderr, "Error logging data.\n");
                    }
                }
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

