    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_presence = read_flame_sensor();
        if (flame_presence < 0) {
            fprintf(stderr, "Error reading flame sensor, skipping entry.\n");
        } else {
            int adc_value = read_mcp3008(0);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading MCP3008, skipping entry.\n");
            } else {
                float temperature = convert_to_temperature(adc_value);
                if (temperature <= -998.0f) {
                    fprintf(stderr, "Error converting ADC to temperature, skipping entry.\n");
                } else {
                    if (log_data(flame_presence, temperature) < 0) {
                        fprintf(stderr, "Error logging data.\n");
                    }
                }
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

