#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4D
#define CO_THRESHOLD 25.0f
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static int i2c_handle = -1;
static FILE *log_fp = NULL;
static FILE *alert_fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *ox, uint16_t *red) {
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    *ox = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    *red = ((uint16_t)(buf[2] & 0xFF) << 8) | (uint16_t)(buf[3] & 0xFF);
    return 0;
}

static float calculate_co_ppm(uint16_t ox) {
    return (float)ox * 0.01f;
}

static int log_data(float co_ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
            return -1;
        }
    }

    if (fprintf(log_fp, "%s, %.2f\n", timestamp, co_ppm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

static int log_alert(float co_ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (alert_fp == NULL) {
        alert_fp = fopen(ALERT_FILE, "a");
        if (alert_fp == NULL) {
            fprintf(stderr, "Error opening alert file %s\n", ALERT_FILE);
            return -1;
        }
    }

    if (fprintf(alert_fp, "%s, %.2f\n", timestamp, co_ppm) < 0) {
        fprintf(stderr, "Error writing to alert file\n");
        return -1;
    }
    fflush(alert_fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (alert_fp != NULL) {
        fclose(alert_fp);
        alert_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t ox = 0, red = 0;

        if (read_sensor_data(&ox, &red) != 0) {
            fprintf(stderr, "Sensor read error, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float co_ppm = calculate_co_ppm(ox);

        if (log_data(co_ppm) != 0) {
            fprintf(stderr, "Logging error\n");
        }

        if (co_ppm >= CO_THRESHOLD) {
            if (log_alert(co_ppm) != 0) {
                fprintf(stderr, "Alert logging error\n");
            }
        }

        printf("CO: %.2f ppm, NO2: %u\n", co_ppm, red);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

