        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(MIC1_GPIO, PI_INPUT);
    gpioSetMode(MIC2_GPIO, PI_INPUT);

    while (running) {
        int mic1_level = read_microphone(MIC1_GPIO);
        int mic2_level = read_microphone(MIC2_GPIO);

        double avg_level = process_data(mic1_level, mic2_level);
        log_data(avg_level);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

