#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_GPIO 27
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_INTERVAL_US 1000
#define LED_ON_DURATION_MS 500
#define RMS_THRESHOLD 1000
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / 10)

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_rms(const int *samples, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return sqrt(sum_sq / num_samples);
}

static void log_event(double rms1, double rms2) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    if (fprintf(log_file, "%s,%.2f,%.2f\n", ts, rms1, rms2) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("audio_events.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int samples1[NUM_SAMPLES];
    int samples2[NUM_SAMPLES];
    int sample_idx = 0;
    int led_on = 0;

    while (running) {
        int v1 = read_mcp3008(0);
        int v2 = read_mcp3008(1);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "ADC read error, skipping window\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        samples1[sample_idx] = v1;
        samples2[sample_idx] = v2;
        sample_idx++;

        if (sample_idx >= NUM_SAMPLES) {
            double rms1 = calculate_rms(samples1, NUM_SAMPLES);
            double rms2 = calculate_rms(samples2, NUM_SAMPLES);

            log_event(rms1, rms2);

            if (rms1 > RMS_THRESHOLD || rms2 > RMS_THRESHOLD) {
                if (!led_on) {
                    gpioWrite(LED_GPIO, 1);
                    led_on = 1;
                }
                gpioDelay(LED_ON_DURATION_MS * 1000);
                gpioWrite(LED_GPIO, 0);
                led_on = 0;
            } else {
                gpioWrite(LED_GPIO, 0);
                led_on = 0;
            }
            sample_idx = 0;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

