    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("audio_events.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int samples1[NUM_SAMPLES];
    int samples2[NUM_SAMPLES];
    int sample_idx = 0;
    int led_on = 0;

    while (running) {
        int v1 = read_mcp3008(0);
        int v2 = read_mcp3008(1);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "ADC read error, skipping window\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        samples1[sample_idx] = v1;
        samples2[sample_idx] = v2;
        sample_idx++;

        if (sample_idx >= NUM_SAMPLES) {
            double rms1 = calculate_rms(samples1, NUM_SAMPLES);
            double rms2 = calculate_rms(samples2, NUM_SAMPLES);

            log_event(rms1, rms2);

            if (rms1 > RMS_THRESHOLD || rms2 > RMS_THRESHOLD) {
                if (!led_on) {
                    gpioWrite(LED_GPIO, 1);
                    led_on = 1;
                }
                gpioDelay(LED_ON_DURATION_MS * 1000);
                gpioWrite(LED_GPIO, 0);
                led_on = 0;
            } else {
                gpioWrite(LED_GPIO, 0);
                led_on = 0;
            }
            sample_idx = 0;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

