#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_PIN 17
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0f
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_A0 (4 << 12)
#define ADS1115_CONFIG_PGA_4_096V (2 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (1 << 8)
#define ADS1115_CONFIG_DR_128SPS (7 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_A0 | \
                                ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | \
                                ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115_raw(int handle) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_DEFAULT >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_DEFAULT & 0xFF;

    if (i2cWriteDevice(handle, config, 3) < 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }

    gpioDelay(10000);

    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error setting conversion register\n");
        return -1;
    }

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading conversion data\n");
        return -1;
    }

    return (int16_t)((buf[0] << 8) | buf[1]);
}

static float convert_to_current(int16_t raw) {
    const float pga_range = 4.096f;
    const float mv_per_bit = pga_range / 32768.0f;
    return (float)raw * mv_per_bit * 1000.0f;
}

static void control_led(float avg_current) {
    if (avg_current > CURRENT_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    while (running) {
        int16_t raw = read_ads1115_raw(i2c_handle);
        if (raw == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        float current = convert_to_current(raw);

        buffer[buffer_index] = current;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }

        float sum = 0.0f;
        for (int i = 0; i < buffer_count; i++) {
            sum += buffer[i];
        }
        float avg_current = sum / (float)buffer_count;

        control_led(avg_current);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(LED_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

