#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define CSV_FILENAME   "color_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_CONSEC_ERR 3

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x92
#define TCS34725_CDATAL  0x94
#define TCS34725_RDATAL  0x96
#define TCS34725_GDATAL  0x98
#define TCS34725_BDATAL  0x9A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_csv = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[WARN] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[WARN] i2cReadWordData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int sensor_init(int handle)
{
    /* Power on */
    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    time_sleep(0.003); /* 3 ms power-on delay */

    /* Enable RGBC */
    if (i2c_write_byte(handle, TCS34725_ENABLE,
                       TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    /* Integration time ~2.4 ms (ATIME = 0xFF) */
    if (i2c_write_byte(handle, TCS34725_ATIME, 0xFF) < 0)
        return -1;

    return 0;
}

static int read_sensor_data(int handle, uint16_t *clear,
                            uint16_t *red, uint16_t *green, uint16_t *blue)
{
    if (i2c_read_word(handle, TCS34725_CDATAL, clear) < 0)  return -1;
    if (i2c_read_word(handle, TCS34725_RDATAL, red)   < 0)  return -1;
    if (i2c_read_word(handle, TCS34725_GDATAL, green) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATAL, blue)  < 0)  return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t c, uint16_t r, uint16_t g, uint16_t b)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[WARN] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            c, r, g, b);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    int id = i2cReadByteData(g_i2c_handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "[ERROR] Failed to read TCS34725 ID register: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if ((id & 0xF0) != 0x40) {
        fprintf(stderr, "[ERROR] Unexpected TCS34725 ID: 0x%02X (expected 0x40-0x4F)\n", id);
        cleanup();
        return EXIT_FAILURE;
    }

    if (sensor_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[ERROR] Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file; write header if new */
    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,clear,red,green,blue\n");
        fflush(g_csv);
    }

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t c, r, g, b;
        if (read_sensor_data(g_i2c_handle, &c, &r, &g, &b) == 0) {
            consecutive_errors = 0;
            log_data(g_csv, c, r, g, b);
        } else {
            consecutive_errors++;
            fprintf(stderr, "[WARN] Sensor read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "[ERROR] %d consecutive I2C failures; aborting\n",
                        consecutive_errors);
                break;
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

