        return EXIT_FAILURE;
    }
    if ((id & 0xF0) != 0x40) {
        fprintf(stderr, "[ERROR] Unexpected TCS34725 ID: 0x%02X (expected 0x40-0x4F)\n", id);
        cleanup();
        return EXIT_FAILURE;
    }

    if (sensor_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[ERROR] Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file; write header if new */
    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,clear,red,green,blue\n");
        fflush(g_csv);
    }

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t c, r, g, b;
        if (read_sensor_data(g_i2c_handle, &c, &r, &g, &b) == 0) {
            consecutive_errors = 0;
            log_data(g_csv, c, r, g, b);
        } else {
            consecutive_errors++;
            fprintf(stderr, "[WARN] Sensor read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "[ERROR] %d consecutive I2C failures; aborting\n",
                        consecutive_errors);
                break;
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

