        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static int log_data(const char *filename, int moisture1, int moisture2) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d,%d\n", timestamp, moisture1, moisture2) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            fprintf(stderr, "Failed to create log file %s: %s\n", LOG_FILE, strerror(errno));
            close(spi_fd);
            return 1;
        }
        if (fprintf(fp, "Timestamp,Moisture1,Moisture2\n") < 0) {
            fprintf(stderr, "Failed to write header to log file: %s\n", strerror(errno));
            fclose(fp);
            close(spi_fd);
            return 1;
        }
        if (fclose(fp) != 0) {
            fprintf(stderr, "Failed to close log file after header: %s\n", strerror(errno));
            close(spi_fd);
            return 1;
        }
    } else {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
            close(spi_fd);
            return 1;
        }
    }

    printf("Moisture sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture1 = read_mcp3008(spi_fd, 0);
        int moisture2 = read_mcp3008(spi_fd, 1);

        if (moisture1 < 0 || moisture2 < 0) {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        } else {
            if (log_data(LOG_FILE, moisture1, moisture2) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return 0;
}

