#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define ADC_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define OVER_CURRENT_THRESHOLD 10.0f
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define ADC_MAX_VALUE 1023
#define VREF 3.3f
#define R_SENSOR 10000.0f
#define R_LOAD 10000.0f

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    unsigned char bits = SPI_BITS;
    unsigned char mode = SPI_MODE_0;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("SPI_IOC_MESSAGE");
            usleep(10000);
            continue;
        }
        return ((rx[1] & 0x03) << 8) | rx[2];
    }
    return -1;
}

static float adc_to_current(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) return -1.0f;
    float voltage = (float)adc_value / (float)ADC_MAX_VALUE * VREF;
    if (voltage <= 0.0f) return -1.0f;
    float resistance = (VREF - voltage) / voltage * R_LOAD;
    return (voltage - 0.5f * VREF) / resistance;
}

static int log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.3f\n", timestamp, current) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static int control_motor(int enable) {
    if (gpiod_line_set_value(motor_line, enable ? 0 : 1) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 1);
        gpiod_line_release(motor_line);
        motor_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return 1;
    }

    motor_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(motor_line, "motor_shutdown", 1) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    log_file = fopen("current_log.csv", "a");
    if (!log_file) {
        perror("fopen current_log.csv");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
        fflush(log_file);
    }

    printf("Monitoring current... Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after retries\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float current = adc_to_current(adc_value);
        if (current < 0.0f) {
            fprintf(stderr, "Invalid ADC value or conversion error\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (log_data(current) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (current > OVER_CURRENT_THRESHOLD) {
            printf("Over-current detected: %.3f A\n", current);
            if (control_motor(0) < 0) {
                fprintf(stderr, "Failed to disable motor\n");
            }
            sleep(SAMPLE_INTERVAL_SEC);
            if (control_motor(1) < 0) {
                fprintf(stderr, "Failed to re-enable motor\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

