    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.3f\n", timestamp, current) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static int control_motor(int enable) {
    if (gpiod_line_set_value(motor_line, enable ? 0 : 1) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 1);
        gpiod_line_release(motor_line);
        motor_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return 1;
    }

    motor_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(motor_line, "motor_shutdown", 1) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    log_file = fopen("current_log.csv", "a");
    if (!log_file) {
        perror("fopen current_log.csv");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
        fflush(log_file);
    }

    printf("Monitoring current... Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after retries\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float current = adc_to_current(adc_value);
        if (current < 0.0f) {
            fprintf(stderr, "Invalid ADC value or conversion error\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (log_data(current) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (current > OVER_CURRENT_THRESHOLD) {
            printf("Over-current detected: %.3f A\n", current);
            if (control_motor(0) < 0) {
                fprintf(stderr, "Failed to disable motor\n");
            }
            sleep(SAMPLE_INTERVAL_SEC);
            if (control_motor(1) < 0) {
                fprintf(stderr, "Failed to re-enable motor\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

