#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x28
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_RETRIES    3

/* MLX90817 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE_MSB 0x00
#define REG_PRESSURE_LSB 0x01
#define REG_TEMP_MSB    0x02
#define REG_TEMP_LSB    0x03
#define REG_STATUS      0x04

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address, then read `len` bytes back. */
static int i2c_read_block(int handle, uint8_t reg_msb, uint8_t reg_lsb,
                          uint8_t *buf, int len)
{
    if (i2cWriteByteData(handle, reg_msb, reg_lsb) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X%02X): %s\n",
                reg_msb, reg_lsb, pigpio_error(errno));
        return -1;
    }
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "I2C read failed (reg 0x%02X%02X): got %d of %d (%s)\n",
                reg_msb, reg_lsb, n, len, pigpio_error(errno));
        return -1;
    }
    return 0;
}

/* Read pressure in kPa. Returns 0 on success, -1 on error. */
static int read_pressure(int handle, float *pressure_kPa)
{
    uint8_t buf[2];
    if (i2c_read_block(handle, REG_PRESSURE_MSB, REG_PRESSURE_LSB, buf, 2) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *pressure_kPa = (float)raw / 100.0f;
    return 0;
}

static void get_iso8601_utc(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static int log_data(FILE *fp, float pressure)
{
    char ts[32];
    get_iso8601_utc(ts, sizeof(ts));
    if (fprintf(fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    long pos = ftell(g_log_file);
    if (pos == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    printf("MLX90817 pressure logger started. Logging to %s every %.1f s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_pressure(g_i2c_handle, &pressure) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed.\n", attempt + 1, MAX_RETRIES);
            time_sleep(0.1);
        }

        if (ok) {
            if (log_data(g_log_file, pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts; skipping sample.\n",
                    MAX_RETRIES);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

