#define ADS1115_CFG_DR_128SPS 0x0080  /* Data rate 128 SPS */

/* Config: single-shot, AIN1 vs GND, 4.096V, 128 SPS, no comparator */
#define ADS1115_CFG_MUX_AIN1 0x5000  /* AIN1 vs GND */

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit value to an ADS1115 register (pigpio i2cWriteWordData sends
 * the register address as the first byte, then the data as the second byte
 * on the wire, so we swap the bytes to match the ADS1115 wire protocol). */
static int ads1115_write_reg(uint8_t reg, uint16_t value)
{
    uint16_t swapped = ((value >> 8) & 0xFF) | ((value << 8) & 0xFF00);
    return i2cWriteWordData(i2c_handle, reg, swapped);
}

/* Read a 16-bit value from an ADS1115 register. */
static int ads1115_read_reg(uint8_t reg, uint16_t *value)
{
    int rc = i2cReadWordData(i2c_handle, reg);
    if (rc < 0)
        return rc;
    /* pigpio returns the word as (high_byte << 8) | low_byte, which matches
     * the ADS1115 wire protocol. */
    *value = (uint16_t)rc;
    return 0;
}

/* Trigger a single-shot conversion on the specified channel and read the
 * raw 16-bit result. Returns 0 on success, -1 on failure. */
static int ads1115_read_channel(uint16_t mux_config, int16_t *raw)
{
    uint16_t config = ADS1115_CFG_BASE | mux_config |
                      ADS1115_CFG_PGA_4_096V | ADS1115_CFG_DR_128SPS;

    if (ads1115_write_reg(ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    gpioDelay(10000);

    uint16_t cfg_readback = 0;
    if (ads1115_read_reg(ADS1115_REG_CONFIG, &cfg_readback) < 0)
        return -1;

    /* Bit 15 (OS) should be set when the conversion is ready. */
    if (!(cfg_readback & 0x8000))
        return -1;

    uint16_t raw_u = 0;
    if (ads1115_read_reg(ADS1115_REG_CONVERSION, &raw_u) < 0)
        return -1;

    *raw = (int16_t)raw_u;
    return 0;
}

/* Convert raw ADC counts to pressure in kPa (MLX90834: 0–100 kPa). */
static float raw_to_pressure(int16_t raw)
{
    /* 16-bit signed, 4.096 V PGA, 12-bit resolution. */
    float voltage = (raw / 32767.0f) * 4.096f;
    return voltage * 100.0f;
}

/* Convert raw ADC counts to temperature in °C (NTC: 25–85 °C, 0–100 kPa). */
static float raw_to_temperature(int16_t raw)
{
    /* 16-bit signed, 4.096 V PGA, 12-bit resolution. */
    float voltage = (raw / 32767.0f) * 4.096f;
    /* Placeholder linear approximation (NTC: R_ref = 100 kΩ, R_load = V/I). */
    float resistance = 100000.0f * (1.0f - voltage / 4.096f);
    if (resistance < 0.0f) resistance = 0.0f;
    float temperature = (resistance / 100000.0f) * 100.0f;
    if (temperature < 25.0f) temperature = 25.0f;
    if (temperature > 85.0f) temperature = 85.0f;
    return temperature;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (rc=%d).\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90834 Pressure Monitor (ADS1115 on I2C bus %d, addr 0x%02X)\n",
           I2C_BUS, ADS1115_ADDR);
    printf("Pressure threshold: %.1f kPa | LED on GPIO%d | Ctrl+C to exit\n",
           PRESSURE_THRESHOLD, LED_GPIO);

    while (!terminate) {
        int16_t raw_pressure = 0, raw_temp = 0;
        bool pressure_ok = false, temp_ok = false;

        /* Read pressure with retries */
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (ads1115_read_channel(ADS1115_CFG_MUX_AIN0, &raw_pressure) == 0) {
                pressure_ok = true;
                break;
            }
            fprintf(stderr, "Warning: pressure read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000);  /* 10 ms backoff */
        }
        if (!pressure_ok) {
            fprintf(stderr, "Error: pressure read failed after %d attempts.\n", MAX_RETRIES);
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Read temperature with retries */
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (ads1115_read_channel(ADS1115_CFG_MUX_AIN1, &raw_temp) == 0) {
                temp_ok = true;
                break;
            }
            fprintf(stderr, "Warning: temperature read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
        }
        if (!temp_ok) {
            fprintf(stderr, "Error: temperature read failed after %d attempts.\n", MAX_RETRIES);
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float pressure = raw_to_pressure(raw_pressure);
        float temperature = raw_to_temperature(raw_temp);

        printf("Pressure: %.2f kPa | Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            printf("WARNING: Pressure exceeds threshold!\n");
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

