#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define LOG_FILE "humidity_log.txt"
#define HUMIDITY_THRESHOLD 80.0
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SENDER "sender@example.com"
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_BODY "Humidity exceeded 80% threshold."

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(const char *device, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    int bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int read_mcp3208(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

float convert_to_humidity(int adc_value) {
    return (adc_value / 1023.0) * 100.0;
}

float convert_to_temperature(int adc_value) {
    return (adc_value / 1023.0) * 100.0;
}

int log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("Failed to get local time");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("Failed to flush log file");
        return -1;
    }

    return 0;
}

int send_email_alert(float humidity) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "echo \"Subject: %s\nFrom: %s\nTo: %s\n\nHumidity: %.2f%%\" | ssmtp %s",
        EMAIL_SUBJECT, EMAIL_SENDER, EMAIL_RECIPIENT, humidity, EMAIL_RECIPIENT);

    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Email command too long\n");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        perror("Failed to execute ssmtp");
        return -1;
    } else if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "ssmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    spi_fd = spi_init(SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int humidity_adc = read_mcp3208(spi_fd, 0);
        if (humidity_adc < 0) {
            fprintf(stderr, "Failed to read humidity ADC\n");
            sleep(1);
            continue;
        }

        int temperature_adc = read_mcp3208(spi_fd, 1);
        if (temperature_adc < 0) {
            fprintf(stderr, "Failed to read temperature ADC\n");
            sleep(1);
            continue;
        }

        float humidity = convert_to_humidity(humidity_adc);
        float temperature = convert_to_temperature(temperature_adc);

        if (log_data(humidity, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            if (send_email_alert(humidity) != 0) {
                fprintf(stderr, "Failed to send email alert\n");
            }
        }

        sleep(5);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

