code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         SPI_MODE_0

#define GPIO_CHIP        "gpiochip4"
#define CE0_OFFSET       8

#define ADC_CHANNEL      0
#define ADC_MAX_VALUE    4095
#define ADC_VREF         3.3f
#define ADC_RESOLUTION   4096.0f

#define LOG_FILE         "temperature_log.csv"
#define SAMPLE_PERIOD_US 1000000

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_ce0 = NULL;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        perror("gpiod_chip_open_by_name(" GPIO_CHIP ")");
        return -1;
    }

    g_ce0 = gpiod_chip_get_line(g_chip, CE0_OFFSET);
    if (!g_ce0) {
        perror("gpiod_chip_get_line(CE0)");
        gpiod_chip_close(g_chip); g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_ce0, "mcp3208-ce0", 1) < 0) {
        perror("gpiod_line_request_output(CE0)");
        gpiod_chip_close(g_chip); g_chip = NULL; g_ce0 = NULL;
        return -1;
    }

    return 0;
}

static int read_adc(uint16_t *value)
{
    if (!value) return -1;

    /* MCP3208 single-ended read: start bit + SGL/DIFF=1 + D2 D1 D0 */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((ADC_CHANNEL & 0x07) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (gpiod_line_set_value(g_ce0, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        gpiod_line_set_value(g_ce0, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_ce0, 1) < 0) {
        perror("gpiod_line_set_value(1)");
        return -1;
    }

    /* 12-bit result: bits 11..0 from rx[1] (lower 2 bits) and rx[2] (8 bits) */
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_celsius(uint16_t adc)
{
    float voltage = (float)adc * ADC_VREF / ADC_RESOLUTION;
    return (voltage - 0.5f) * 100.0f;
}

static int log_temperature(float temp_c)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&now, &tm_info)) {
        perror("localtime_r()");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log, "%s,%.2f\n", ts, temp_c) < 0) {
        perror("fprintf(log)");
        return -1;
    }

    if (fflush(g_log) != 0) {
        perror("fflush(log)");
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_ce0) {
        gpiod_line_release(g_ce0);
        g_ce0 = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(g_log, 0, SEEK_END) == 0) {
        long sz = ftell(g_log);
        if (sz == 0) {
            if (fprintf(g_log, "timestamp,temperature_celsius\n") < 0) {
                perror("fprintf(header)");
                cleanup();
                return EXIT_FAILURE;
            }
            if (fflush(g_log) != 0) {
                perror("fflush(header)");
                cleanup();
                return EXIT_FAILURE;
            }
        }
    } else {
        perror("ftell()");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Temperature logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t adc = 0;
        if (read_adc(&adc) < 0) {
            fprintf(stderr, "ADC read failed\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (adc == 0 || adc == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC at rail (%u) — sensor absent or wiring fault\n", adc);
        }

        float temp_c = adc_to_celsius(adc);

        if (temp_c < -40.0f || temp_c > 125.0f) {
            fprintf(stderr, "Warning: Temperature %.2f C out of valid range\n", temp_c);
        }

        if (log_temperature(temp_c) < 0) {
            fprintf(stderr, "Logging failed\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

