        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file);
    return 0;
}

static void check_impact(int x, int y, int z) {
    if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
        if (fprintf(log_file, "IMPACT DETECTED\n") < 0) {
            perror("Error writing impact detection to log file");
        } else {
            fflush(log_file);
        }
    }
}

