        gpioTerminate();
        return 1;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int x = read_mcp3008(0);
        int y = read_mcp3008(1);
        int z = read_mcp3008(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (log_data(x, y, z) != 0) {
            fprintf(stderr, "Error logging data\n");
