        check_impact(x, y, z);

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpioTerminate();

    return 0;
}

