#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x52
#define LOG_FILE "biometric_log.csv"
#define SAMPLE_INTERVAL_US 1000000

/* Si1172 register addresses (example placeholders; actual Si1172 registers vary) */
#define REG_PART_ID 0x00
#define REG_HW_ID 0x01
#define REG_HR_DATA 0x10
#define REG_SPO2_DATA 0x12
#define REG_CONFIG 0x20

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int hr;
    int spo2;
    int error_flag;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_reg(uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) return -1;
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int init_sensor(void) {
    uint8_t part_id = 0;
    if (i2c_read_reg(REG_PART_ID, &part_id, 1) != 0) {
        fprintf(stderr, "Error: Failed to read Part ID register.\n");
        return -1;
    }
    if (part_id != 0x11) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x11). Sensor not present?\n", part_id);
        return -1;
    }
    uint8_t hw_id = 0;
    if (i2c_read_reg(REG_HW_ID, &hw_id, 1) != 0) {
        fprintf(stderr, "Error: Failed to read HW ID register.\n");
        return -1;
    }
    printf("Si1172 detected (Part ID: 0x%02X, HW ID: 0x%02X).\n", part_id, hw_id);
    return 0;
}

static sensor_data_t read_sensor_data(void) {
    sensor_data_t data = {0, 0, 0};
    uint8_t hr_buf[2] = {0};
    uint8_t spo2_buf[2] = {0};

    if (i2c_read_reg(REG_HR_DATA, hr_buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to read HR data.\n");
        data.error_flag = 1;
        return data;
    }
    data.hr = (hr_buf[0] << 8) | hr_buf[1];

    if (i2c_read_reg(REG_SPO2_DATA, spo2_buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to read SpO2 data.\n");
        data.error_flag = 1;
        return data;
    }
    data.spo2 = (spo2_buf[0] << 8) | spo2_buf[1];

    return data;
}

static void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%d,%d,%d\n", (long)now, data.hr, data.spo2, data.error_flag);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,hr_bpm,spo2_pct,error_flag\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting data acquisition... (Ctrl+C to stop)\n");

    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

