#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x60
#define MEASURE_CMD 0x36
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("I2C write command failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_icp10125(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    int32_t raw_pressure, raw_temperature;
    float p_cal, t_cal;

    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) return -1;

    usleep(10000);

    if (i2c_read_bytes(fd, data, 6) < 0) return -1;

    raw_pressure = ((int32_t)data[0] << 16) | ((int32_t)data[1] << 8) | data[2];
    raw_temperature = ((int32_t)data[3] << 16) | ((int32_t)data[4] << 8) | data[5];

    p_cal = (float)raw_pressure / 16777216.0f * 100.0f;
    t_cal = (float)raw_temperature / 16777216.0f * 100.0f;

    *pressure = p_cal;
    *temperature = t_cal;
    return 0;
}

static void log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, pressure);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        perror("Failed to open CSV file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Pressure (Pa)\n");
        fflush(log_file);
    }

    while (running) {
        float temperature, pressure;
        if (read_icp10125(i2c_fd, &temperature, &pressure) == 0) {
            log_data(log_file, temperature, pressure);
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

