#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL_1 0
#define MCP3008_CHANNEL_2 1
#define SAMPLE_RATE 100
#define SAMPLE_INTERVAL_US (1000000 / SAMPLE_RATE)

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx_buf[3] = {0};

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
}

int apply_noise_cancellation(int sample1, int sample2, float gain1, float gain2) {
    return (int)((sample1 * gain1) + (sample2 * gain2));
}

int main(int argc, char *argv[]) {
    float gain1 = 1.0f;
    float gain2 = 1.0f;

    if (argc == 3) {
        gain1 = atof(argv[1]);
        gain2 = atof(argv[2]);
    } else if (argc != 1) {
        fprintf(stderr, "Usage: %s [gain1 gain2]\n", argv[0]);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
