        fprintf(stderr, "Error: SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI_IOC_MESSAGE failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float compensate_voltage(int adc_value, float temperature) {
    float v_out = (adc_value / (float)ADC_MAX) * 3.3f;
    float v_ref = 3.3f;
    float r_load = 10000.0f;
    float r_flame = 1000.0f;
    float r_amb = r_load / ((v_ref / v_out) - 1.0f);
    float r_flame_comp = r_flame * (1.0f + (0.01f * (temperature - 25.0f)));
    float v_flame = r_amb / (r_amb + r_flame_comp) * v_ref;
    return v_flame;
}

static void log_data(int adc_value, float voltage, float compensated_voltage,
                     float temperature, int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n",
            timestamp, adc_value, voltage, compensated_voltage, temperature,
            flame_detected);
    fflush(log_file);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error: cannot open gpiochip4: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error: cannot get GPIO line %d: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO %d as output: %s\n",
                BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && program_running) {
            if (read_mcp3008(ADC_CHANNEL, &adc_value) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying ADC read (%d/%d)...\n", retries, MAX_RETRIES);
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "Error: ADC read failed after %d retries\n", MAX_RETRIES);
            fprintf(log_file, "Error: ADC read failed after %d retries\n", MAX_RETRIES);
            fflush(log_file);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = (adc_value / (float)ADC_MAX) * 3.3f;

        float temperature = 0.0f;
        if (read_ambient_temperature(&temperature) != 0) {
            fprintf(stderr, "Warning: using default temperature\n");
        }

        float compensated_voltage = compensate_voltage(adc_value, temperature);

        int flame_detected = (compensated_voltage > 1.0f) ? 1 : 0;

        if (gpiod_line_set_value(buzzer_line, flame_detected) < 0) {
            fprintf(stderr, "Error: failed to set buzzer GPIO: %s\n", strerror(errno));
        }

        log_data(adc_value, voltage, compensated_voltage, temperature, flame_detected);

        printf("ADC: %d, Voltage: %.3f V, Compensated: %.3f V, Temp: %.2f C, Flame: %s\n",
               adc_value, voltage, compensated_voltage, temperature,
               flame_detected ? "YES" : "NO");

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

