#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define LED_PIN        17
#define WATER_THRESHOLD_HIGH 75.0f
#define WATER_THRESHOLD_LOW  70.0f
#define SAMPLE_INTERVAL_US   5000000
#define SAMPLE_DELAY_US      100000
#define JSON_FILENAME        "water_levels.json"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_json_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     * tx[0] = 0x01 (start bit)
     * tx[1] = (0x08 | channel) << 4  -> SGL/DIFF=1, D2 D1 D0 = channel
     * tx[2] = 0x00 (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

static float adc_to_percentage(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return (float)adc_value / 1023.0f * 100.0f;
}

static void control_led(float percentage)
{
    if (percentage > WATER_THRESHOLD_HIGH) {
        gpioWrite(LED_PIN, 1);
    } else if (percentage < WATER_THRESHOLD_LOW) {
        gpioWrite(LED_PIN, 0);
    }
}

static void log_to_json(float percentage)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_json_fp, "{\"timestamp\":\"%s\",\"water_level\":%.2f}\n",
            timestamp, percentage);
    fflush(g_json_fp);
}

static void cleanup(void)
{
    if (g_json_fp) {
        fprintf(g_json_fp, "]\n");
        fflush(g_json_fp);
        fclose(g_json_fp);
        g_json_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    g_json_fp = fopen(JSON_FILENAME, "w");
    if (!g_json_fp) {
        perror("fopen JSON");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_json_fp, "[\n");
    fflush(g_json_fp);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float percentage = adc_to_percentage(adc_value);
        control_led(percentage);
        log_to_json(percentage);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

