        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

float calculate_moisture_percentage(int adc_value, int min_moisture, int max_moisture) {
    if (max_moisture <= min_moisture) {
