    if (fp == NULL) {
        fprintf(stderr, "Error: popen failed: %s\n", strerror(errno));
        return -1;
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        fprintf(stderr, "%s", buffer);
    }

    int status = pclose(fp);
