    while ((opt = getopt(argc, argv, "c:a:l:m:M:t:e:p:h")) != -1) {
        switch (opt) {
            case 'c': spi_channel = atoi(optarg); break;
            case 'a': adc_channel = atoi(optarg); break;
            case 'l': min_moisture = atoi(optarg); break;
            case 'm': max_moisture = atoi(optarg); break;
            case 'M': moisture_threshold = atoi(optarg); break;
            case 't': logging_interval = atoi(optarg); break;
