                    }
                }
            }
        }

        for (int i = 0; i < logging_interval && running; i++) {
            sleep(1);
        }
    }

    fprintf(stderr, "\nExiting gracefully...\n");
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return EXIT_SUCCESS;
}

