    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int adc_value = read_mcp3008(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        } else {
            /* Convert 10-bit ADC value to moisture percentage (0% = dry, 1023 = wet) */
            float moisture_percentage = ((float)adc_value / 1023.0f) * 100.0f;
            printf("ADC Value: %4d | Moisture: %5.2f%%\n", adc_value, moisture_percentage);
        }

        /* Sleep in 1-second increments to allow prompt signal handling */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
