    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, v1, v2, v3, v4) < 0) {
        fprintf(stderr, "Error writing to CSV: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing CSV: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    g_csv = fopen(CSV_FILENAME, "a");
    if (g_csv == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", CSV_FILENAME, strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    fprintf(g_csv, "# timestamp,sensor1_v,sensor2_v,sensor3_v,sensor4_v\n");
    fflush(g_csv);

    printf("Starting data acquisition on %s (mode %d, %d Hz, %d bits).\n",
           SPI_DEVICE, SPI_MODE, SPI_SPEED_HZ, SPI_BITS);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc[NUM_SENSORS];
        int error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            adc[i] = read_mcp3008(g_spi_fd, i);
            if (adc[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                error = 1;
            }
        }

        if (error) {
            fprintf(stderr, "Sensor read error encountered; skipping sample.\n");
        } else {
            float v1 = adc_to_voltage(adc[0]);
            float v2 = adc_to_voltage(adc[1]);
            float v3 = adc_to_voltage(adc[2]);
            float v4 = adc_to_voltage(adc[3]);

            if (log_data(g_csv, v1, v2, v3, v4) < 0) {
                fprintf(stderr, "Error logging data; continuing.\n");
            }
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");

    if (g_csv != NULL) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("Data acquisition stopped.\n");
    return 0;
}

