    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register signal handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_SEC * 1000, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
