#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_FIFO_WR_PTR 0x04
#define REG_OVERFLOW_CTR 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define MODE_SPO2_RDY 0x03
#define MODE_HR_RDY 0x05
#define MODE_AUTO 0x07

#define SPO2_ADC_RANGE 4096.0f
#define HR_ADC_RANGE 1024.0f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_max30102(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read Part ID register.\n");
        return -1;
    }
    if (part_id != 0x15) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x15). Sensor not present?\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, REG_INTR_ENABLE_1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_INTR_ENABLE_1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_FIFO_WR_PTR, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_OVERFLOW_CTR, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_FIFO_RD_PTR, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_FIFO_CONFIG, 0x0F) < 0) return -1;
    if (i2c_write_reg8(fd, REG_MODE_CONFIG, MODE_AUTO) < 0) return -1;
    if (i2c_write_reg8(fd, REG_SPO2_CONFIG, 0x27) < 0) return -1;
    if (i2c_write_reg8(fd, REG_LED1_PA, 0x24) < 0) return -1;
    if (i2c_write_reg8(fd, REG_LED2_PA, 0x24) < 0) return -1;

    return 0;
}

static int read_spo2(int fd, float *spo2) {
    uint8_t status1, status2;
    if (i2c_read_reg8(fd, REG_INTR_STATUS_1, &status1) < 0) return -1;
    if (i2c_read_reg8(fd, REG_INTR_STATUS_2, &status2) < 0) return -1;

    if ((status1 & 0x01) == 0) return 1;

    uint16_t red, ir;
    if (i2c_read_reg16(fd, REG_FIFO_DATA, &red) < 0) return -1;
    if (i2c_read_reg16(fd, REG_FIFO_DATA, &ir) < 0) return -1;

    float r_ratio = (float)red / SPO2_ADC_RANGE;
    float ir_ratio = (float)ir / SPO2_ADC_RANGE;

    float spo2_val = 110.0f - 25.0f * r_ratio;
    if (spo2_val < 0.0f) spo2_val = 0.0f;
    if (spo2_val > 100.0f) spo2_val = 100.0f;

    *spo2 = spo2_val;
    return 0;
}

static int read_heart_rate(int fd, int *hr) {
    uint8_t status1, status2;
    if (i2c_read_reg8(fd, REG_INTR_STATUS_1, &status1) < 0) return -1;
    if (i2c_read_reg8(fd, REG_INTR_STATUS_2, &status2) < 0) return -1;

    if ((status1 & 0x04) == 0) return 1;

    uint16_t ir_raw;
    if (i2c_read_reg16(fd, REG_FIFO_DATA, &ir_raw) < 0) return -1;

    float ir_ratio = (float)ir_raw / HR_ADC_RANGE;
    int hr_val = (int)(60.0f / (0.0012f * ir_ratio + 0.0002f));
    if (hr_val < 0) hr_val = 0;
    if (hr_val > 200) hr_val = 200;

    *hr = hr_val;
    return 0;
}

static void log_data(float spo2, int hr) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open health_log.txt for writing.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(fp, "%s - SpO2: %.2f%%, Heart Rate: %d BPM\n", timestamp, spo2, hr);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MAX30102_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (init_max30102(i2c_fd) < 0) {
        fprintf(stderr, "Error: MAX30102 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MAX30102 initialized. Monitoring SpO2 and heart rate...\n");

    while (running) {
        float spo2;
        int hr;

        int rc = read_spo2(i2c_fd, &spo2);
        if (rc < 0) {
            fprintf(stderr, "Error: Failed to read SpO2 data.\n");
            break;
        } else if (rc == 0) {
            rc = read_heart_rate(i2c_fd, &hr);
            if (rc < 0) {
                fprintf(stderr, "Error: Failed to read heart rate data.\n");
                break;
            } else if (rc == 0) {
                if (spo2 < 95.0f || hr > 100) {
                    log_data(spo2, hr);
                }
            }
        }

        sleep(1);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    printf("\nExiting gracefully.\n");
    return 0;
}

