#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CFG  0x01
#define ADS1115_CFG_OS   0x8000
#define ADS1115_CFG_MUX_AIN0 0x4000
#define ADS1115_CFG_PGA_4_096V 0x0200
#define ADS1115_CFG_MODE_SINGLE 0x0100
#define ADS1115_CFG_DR_128SPS 0x0080
#define ADS1115_CFG_CQUE_NONE 0x0003

#define RELAY_GPIO     17
#define REED_GPIO      27
#define LOG_FILE       "/var/log/door_events.log"
#define SAMPLE_DELAY_MS 200
#define CALIB_SAMPLES   10
#define CALIB_DELAY_MS  50
#define RELAY_PULSE_MS  3000
#define REED_POLL_MS   100
#define REED_TIMEOUT_S  5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write16 to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    struct i2c_msg msgs[2] = {
        { .addr = ADS1115_ADDR, .flags = 0, .len = 1, .buf = &reg },
        { .addr = ADS1115_ADDR, .flags = I2C_M_RD, .len = 2, .buf = buf }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_read_raw(int fd, int16_t *raw) {
    uint16_t cfg = ADS1115_CFG_OS | ADS1115_CFG_MUX_AIN0 | ADS1115_CFG_PGA_4_096V |
                   ADS1115_CFG_MODE_SINGLE | ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE;
    if (i2c_write16(fd, ADS1115_REG_CFG, cfg) < 0) return -1;
    usleep(10000);
    uint16_t conv;
    if (i2c_read16(fd, ADS1115_REG_CONV, &conv) < 0) return -1;
    *raw = (int16_t)conv;
    return 0;
}

static int calibrate_sensor(int fd, float *offset, float *scale) {
    double sum = 0.0;
    int valid = 0;
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        int16_t raw;
        if (ads1115_read_raw(fd, &raw) < 0) {
            fprintf(stderr, "Calibration sample %d failed\n", i);
            continue;
        }
        sum += raw;
        valid++;
        usleep(CALIB_DELAY_MS * 1000);
    }
    if (valid == 0) {
        fprintf(stderr, "Calibration failed: no valid samples\n");
        return -1;
    }
    *offset = (float)(sum / valid);
    double sum_sq = 0.0;
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        int16_t raw;
        if (ads1115_read_raw(fd, &raw) < 0) continue;
        double d = (double)raw - *offset;
        sum_sq += d * d;
        usleep(CALIB_DELAY_MS * 1000);
    }
    *scale = (float)(sum_sq / valid);
    if (*scale < 1.0f) *scale = 1.0f;
    printf("Calibration: offset=%.2f, scale=%.2f\n", *offset, *scale);
    return 0;
}

static float convert_to_distance(int16_t raw, float offset, float scale) {
    return (float)(raw - offset) / scale;
}

static int gpio_write(int pin, int val) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", val) < 0) {
        fprintf(stderr, "Failed to write %d to %s: %s\n", val, path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_read(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    int val;
    if (fscanf(fp, "%d", &val) != 1) {
        fprintf(stderr, "Failed to read from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return val;
}

static int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, event);
    fclose(fp);
    return 0;
}

static int control_relay(int on) {
    if (gpio_write(RELAY_GPIO, on ? 1 : 0) < 0) return -1;
    if (on) {
        printf("Relay energized\n");
        if (log_event("Relay energized") < 0) return -1;
    } else {
        printf("Relay de-energized\n");
        if (log_event("Relay de-energized") < 0) return -1;
    }
    return 0;
}

static int read_reed(void) {
    int val = gpio_read(REED_GPIO);
    if (val < 0) return -1;
    return val;
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        gpio_write(RELAY_GPIO, 0);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    float offset = 0.0f, scale = 1.0f;
    if (calibrate_sensor(g_i2c_fd, &offset, &scale) < 0) {
        fprintf(stderr, "Sensor calibration failed\n");
        cleanup();
        return 1;
    }

    printf("Door lock system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }
        float distance = convert_to_distance(raw, offset, scale);
        printf("Distance: %.2f cm\n", distance);

        if (distance < 20.0f) {
            printf("Object detected! Activating relay.\n");
            if (control_relay(1) < 0) {
                fprintf(stderr, "Relay activation failed\n");
            } else {
                usleep(RELAY_PULSE_MS * 1000);
                int reed = read_reed();
                if (reed < 0) {
                    fprintf(stderr, "Reed sensor read error\n");
                } else {
                    printf("Reed sensor: %s\n", reed == 0 ? "door opened" : "door not opened");
                    if (log_event(reed == 0 ? "door opened" : "door not opened") < 0) {
                        fprintf(stderr, "Logging failed\n");
                    }
                }
                control_relay(0);
            }
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

