#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define NUM_SENSORS 3
#define LOG_FILE "soil_moisture_log.csv"
#define SAMPLE_INTERVAL_SEC 5
#define CS_PIN_BASE 8
#define CS_PIN_OFFSET 0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_lines[NUM_SENSORS];
static const int cs_pins[NUM_SENSORS] = {8, 7, 25};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    return 0;
}

static int cs_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        cs_lines[i] = gpiod_chip_get_line(chip, cs_pins[i]);
        if (!cs_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %d: %s\n",
                    cs_pins[i], strerror(errno));
            return -1;
        }
        if (gpiod_line_request_output(cs_lines[i], "soil_moisture", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %d: %s\n",
                    cs_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int read_mcp3008(int channel, int *value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_lines[channel], 0) < 0) {
        perror("gpiod_line_set_value low");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        gpiod_line_set_value(cs_lines[channel], 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_lines[channel], 1) < 0) {
        perror("gpiod_line_set_value high");
        return -1;
    }

    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
