static int log_data(int s1, int s2, int s3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        perror("localtime");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, s1, s2, s3) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (cs_lines[i]) {
            gpiod_line_release(cs_lines[i]);
            cs_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
