    if (!log_file) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            perror("fprintf header");
            cleanup();
            return 1;
        }
        fflush(log_file);
    }

