    while (running) {
        int s1 = -1, s2 = -1, s3 = -1;

        if (read_mcp3008(0, &s1) < 0) {
            fprintf(stderr, "Error reading sensor 1\n");
        }
        if (read_mcp3008(0, &s2) < 0) {
            fprintf(stderr, "Error reading sensor 2\n");
        }
        if (read_mcp3008(0, &s3) < 0) {
            fprintf(stderr, "Error reading sensor 3\n");
        }

        if (log_data(s1, s2, s3) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

