#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 0.3
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3
#define ADC_MAX_VALUE 1023

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double threshold = DEFAULT_THRESHOLD;
static int pump_duration = DEFAULT_PUMP_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (result == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", retries + 1, MAX_RETRIES, result);
        log_message("SPI transfer failed, retrying...");
        retries++;
        gpioDelay(100000);
    }
    fprintf(stderr, "SPI transfer failed after %d retries\n", MAX_RETRIES);
    log_message("SPI transfer failed after max retries");
    return -1;
}

static double calculate_voltage(int adc_value) {
    return (adc_value / (double)ADC_MAX_VALUE) * 3.0;
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write to pump GPIO %d\n", PUMP_GPIO);
        log_message("Failed to write to pump GPIO");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold < 0.0 || threshold > 1.0) {
                    fprintf(stderr, "Threshold must be between 0 and 1\n");
                    return 1;
                }
                break;
            case 'd':
                pump_duration = atoi(optarg);
                if (pump_duration <= 0) {
                    fprintf(stderr, "Pump duration must be positive\n");
                    return 1;
                }
                break;
            case 's':
                sleep_interval = atoi(optarg);
                if (sleep_interval <= 0) {
                    fprintf(stderr, "Sleep interval must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s interval]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Irrigation system started. Threshold: %.2f, Pump duration: %d seconds, Sleep interval: %d seconds\n",
           threshold, pump_duration, sleep_interval);
    log_message("Irrigation system started");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            log_message("Failed to read ADC value");
            gpioDelay(sleep_interval * 1000000);
            continue;
        }

        double voltage = calculate_voltage(adc_value);
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "ADC: %d, Voltage: %.2f V", adc_value, voltage);
        log_message(log_buffer);

        if (voltage < threshold) {
            printf("Moisture level below threshold. Activating pump for %d seconds...\n", pump_duration);
            log_message("Moisture level below threshold, activating pump");
            if (control_pump(1) == 0) {
                gpioDelay(pump_duration * 1000000);
                control_pump(0);
                log_message("Pump deactivated");
            } else {
                log_message("Failed to activate pump");
            }
        }

        gpioDelay(sleep_interval * 1000000);
    }

    printf("Shutting down...\n");
    log_message("Shutting down");
    cleanup();
    return 0;
}

