                    return 1;
                }
                break;
            case 'd':
                pump_duration = atoi(optarg);
                if (pump_duration <= 0) {
                    fprintf(stderr, "Pump duration must be positive\n");
                    return 1;
                }
                break;
            case 's':
                sleep_interval = atoi(optarg);
                if (sleep_interval <= 0) {
                    fprintf(stderr, "Sleep interval must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s interval]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Irrigation system started. Threshold: %.2f, Pump duration: %d seconds, Sleep interval: %d seconds\n",
           threshold, pump_duration, sleep_interval);
    log_message("Irrigation system started");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            log_message("Failed to read ADC value");
            gpioDelay(sleep_interval * 1000000);
            continue;
        }

        double voltage = calculate_voltage(adc_value);
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "ADC: %d, Voltage: %.2f V", adc_value, voltage);
        log_message(log_buffer);

        if (voltage < threshold) {
            printf("Moisture level below threshold. Activating pump for %d seconds...\n", pump_duration);
            log_message("Moisture level below threshold, activating pump");
            if (control_pump(1) == 0) {
                gpioDelay(pump_duration * 1000000);
                control_pump(0);
                log_message("Pump deactivated");
            } else {
                log_message("Failed to activate pump");
            }
        }

        gpioDelay(sleep_interval * 1000000);
    }

    printf("Shutting down...\n");
    log_message("Shutting down");
    cleanup();
    return 0;
}

