#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x40
#define SAMPLE_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * Main sampling loop.
     * The PCF8591 returns the result of the previous conversion on the
     * first read after a write.  We discard that so the next read
     * returns the current conversion result.
     */
    while (g_running) {
        uint8_t buf[2];

        /*
         * Write control byte:
         *   bit7=0 (auto-increment off)
         *   bit6=0 (four single-ended inputs)
         *   bit5=0 (channel 0)
         *   bit4=0 (auto-increment off)
         *   bits3-0 = 0x00 (no effect)
         */
        uint8_t ctrl = 0x00;
        if (write(fd, &ctrl, 1) != 1) {
            fprintf(stderr, "write(control byte) failed: %s\n", strerror(errno));
            goto cleanup;
        }

        /*
         * Read two bytes: the first is the previous conversion result
         * (discarded), the second is the current conversion result.
         */
        ssize_t n = read(fd, buf, 2);
        if (n != 2) {
            fprintf(stderr, "read(2 bytes) failed: got %zd bytes, %s\n",
                    n, n < 0 ? strerror(errno) : "short read");
            goto cleanup;
        }

        /* Print the 8-bit sample value */
        printf("AIN0: %u\n", (unsigned)buf[1]);
        fflush(stdout);

        /* Sleep 100 ms between samples */
        usleep(SAMPLE_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        if (close(fd) < 0) {
            fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
        }
    }
    return ret;
}

