/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* Config: single-shot, AIN0 single-ended, +/-4.096V, 128 SPS, no comparator */
#define ADS1115_CFG_BASE     0x8000  /* OS bit */
#define ADS1115_CFG_MUX_AIN0 0x4000  /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4V   0x0200  /* PGA = +/-4.096V */
#define ADS1115_CFG_DR_128   0x0080  /* 128 SPS */
#define ADS1115_CFG          (ADS1115_CFG_BASE | ADS1115_CFG_MUX_AIN0 | \
                             ADS1115_CFG_PGA_4V | ADS1115_CFG_DR_128)

#define MOTOR_SHUTDOWN_GPIO  27
#define THRESHOLD_GAUSS      500.0f
#define BUFFER_SIZE          10
#define SAMPLE_INTERVAL_US   1000000  /* 1 second */
#define ADC_MAX_VALUE        32767     /* 16-bit signed, positive range */
#define ADC_VREF             4.096f    /* PGA = +/-4.096V */

/* ----------------------------- Globals ----------------------------------- */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* ----------------------------- Data Structures --------------------------- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

/* ----------------------------- Prototypes -------------------------------- */
static int  ads1115_read_raw(int handle, int16_t *raw_out);
static float voltage_to_gauss(float voltage);
static void buffer_add(CircularBuffer *cb, float value);
static float buffer_average(const CircularBuffer *cb);
static void motor_shutdown(int gpio_pin, int state);
static void signal_handler(int signal);
static void cleanup(void);

/* ----------------------------- ADS1115 Read ------------------------------ */
static int ads1115_read_raw(int handle, int16_t *raw_out) {
    char cfg[3];
    char conv[2];
    int  rc;

    /* Write config: pointer to config register, then config bytes */
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (ADS1115_CFG >> 8) & 0xFF;
    cfg[2] = ADS1115_CFG & 0xFF;
    rc = i2cWriteDevice(handle, cfg, 3);
    if (rc < 0) {
        syslog(LOG_ERR, "I2C write config failed: %d", rc);
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Point to conversion register */
    conv[0] = ADS1115_REG_CONV;
    rc = i2cWriteDevice(handle, conv, 1);
    if (rc < 0) {
        syslog(LOG_ERR, "I2C write pointer failed: %d", rc);
        return -1;
    }

    /* Read 2 bytes (MSB first) */
    rc = i2cReadDevice(handle, conv, 2);
    if (rc < 0) {
        syslog(LOG_ERR, "I2C read conversion failed: %d", rc);
        return -1;
    }
    if (rc != 2) {
        syslog(LOG_ERR, "I2C read conversion short: %d", rc);
        return -1;
    }

    *raw_out = (int16_t)(((uint16_t)conv[0] << 8) | (uint8_t)conv[1]);
    return 0;
}

/* ----------------------------- Voltage -> Gauss --------------------------- */
static float voltage_to_gauss(float voltage) {
    /* SS49E: 0.5 V/Gauss, 0.5 V offset */
    return (voltage - 0.5f) * 1000.0f;
}

/* ----------------------------- Circular Buffer --------------------------- */
static void buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float buffer_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

