static void motor_shutdown(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d to %d", gpio_pin, state);
    }
}

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    motor_shutdown(MOTOR_SHUTDOWN_GPIO, 0);
    gpioTerminate();
    closelog();
}

/* ----------------------------- Main -------------------------------------- */
int main(void) {
    openlog("magnetic_field_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
