#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION_SEC 10
#define SAMPLE_INTERVAL_SEC 60
#define ADC_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_MAX_VALUE 1023
#define LOG_FILE "watering_events.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(handle));
        return -1;
    }

    int status = spiXfer(handle, (char *)tx, (char *)rx, 3);
    spiClose(handle);

    if (status < 0) {
        fprintf(stderr, "spiXfer failed: %s\n", pigpio_error(status));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int control_pump(int state) {
    int status = gpioWrite(PUMP_GPIO, state);
    if (status < 0) {
        fprintf(stderr, "gpioWrite(%d) failed: %s\n", PUMP_GPIO, pigpio_error(status));
        return -1;
    }
    return 0;
}

static int log_event(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen log");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s, Moisture Level: %d\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    control_pump(0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }

    if (control_pump(0) != 0) {
        fprintf(stderr, "Failed to initialize pump state\n");
        gpioTerminate();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_mcp3008(ADC_CHANNEL);

        if (moisture_level < 0) {
            fprintf(stderr, "Error reading moisture level. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (moisture_level > ADC_MAX_VALUE) {
            fprintf(stderr, "Stuck or invalid ADC value: %d. Retrying in %d seconds.\n", moisture_level, SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        printf("Moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating pump.\n");

            if (control_pump(1) != 0) {
                fprintf(stderr, "Failed to activate pump.\n");
            } else {
                if (log_event(moisture_level) != 0) {
                    fprintf(stderr, "Failed to log event.\n");
                }

                for (int i = 0; i < WATERING_DURATION_SEC && running; i++) {
                    sleep(1);
                }

                if (control_pump(0) != 0) {
                    fprintf(stderr, "Failed to deactivate pump.\n");
                }
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

