/*
 * Raspberry Pi motor speed control via MCP3008 potentiometer + PWM.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, BCM 11)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, BCM 9)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, BCM 10)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  BCM 8)
 *   MCP3008 CH0  -> potentiometer wiper
 *   Motor PWM    -> GPIO18 (BCM 18, hardware PWM0)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_pot motor_pot.c -lpigpio -lrt
 * Run:
 *   sudo ./motor_pot
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM 8) */
#define SPI_SPEED_HZ   1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */

#define PWM_GPIO       18         /* BCM 18, hardware PWM0 */
#define PWM_FREQ_HZ    1000       /* 1 kHz */
#define PWM_RANGE      1023       /* 10-bit resolution */

#define SAMPLE_US      100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI error.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED_HZ, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on GPIO18 --- */
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", PWM_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%d) failed\n", PWM_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange(%d) failed\n", PWM_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with motor stopped */
    if (gpioPWM(PWM_GPIO, 0) != 0) {
        fprintf(stderr, "gpioPWM(%d, 0) failed\n", PWM_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motor control started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, 0);
        if (adc_value < 0) {
            /* SPI error: keep previous PWM value, wait, retry */
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Map 0–1023 to 0–1023 PWM duty cycle */
        int pwm_value = adc_value;
        if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;

        if (gpioPWM(PWM_GPIO, pwm_value) != 0) {
            fprintf(stderr, "gpioPWM(%d, %d) failed\n", PWM_GPIO, pwm_value);
        }

        printf("ADC: %4d  PWM: %4d\n", adc_value, pwm_value);
        fflush(stdout);

        gpioDelay(SAMPLE_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioPWM(PWM_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

