#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define SAMPLE_INTERVAL_US 100000
#define THRESHOLD_DEFAULT 100.0
#define LED_BLINK_DURATION_US 1000000
#define LED_BLINK_ON_US 50000
#define LED_BLINK_OFF_US 50000

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x04 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static double threshold = THRESHOLD_DEFAULT;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115(int handle) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) >> 8;
    config[2] = (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) & 0xFF;

    if (i2cWriteDevice(handle, config, 3) < 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }

    gpioDelay(10000);

    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error setting conversion register\n");
        return -1;
    }

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading conversion data\n");
        return -1;
    }

    return (int16_t)((buf[0] << 8) | buf[1]);
}

static double convert_to_gauss(int16_t raw) {
    const double pga_gain = 4.096;
    const double v_ref = 3.3;
    const double mv_per_gauss = 100.0;
    double voltage = (raw / 32767.0) * v_ref;
    return (voltage / pga_gain) * mv_per_gauss;
}

static void blink_led(int gpio, int duration_us) {
    gpioWrite(gpio, 1);
    gpioDelay(LED_BLINK_ON_US);
    gpioWrite(gpio, 0);
    gpioDelay(LED_BLINK_OFF_US);
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0.0) {
            fprintf(stderr, "Invalid threshold. Using default: %.2f Gauss\n", THRESHOLD_DEFAULT);
            threshold = THRESHOLD_DEFAULT;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring magnetic field strength. Threshold: %.2f Gauss\n", threshold);

    while (running) {
        int16_t raw = read_ads1115(i2c_handle);
        if (raw < 0) {
            fprintf(stderr, "ADC read error. Retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double gauss = convert_to_gauss(raw);
        printf("Magnetic Field Strength: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED.\n");
            for (int i = 0; i < 20 && running; i++) {
                blink_led(LED_GPIO, LED_BLINK_DURATION_US);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

