#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_PUMP_TOPIC "pump_control"
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define SAMPLE_INTERVAL_SEC 60
#define SPI_RETRIES 3
#define SPI_RETRY_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc < 0 || adc > 1023) {
                syslog(LOG_ERR, "MCP3008 out-of-range value: %d", adc);
                return -1;
            }
            return adc;
        }
        syslog(LOG_WARNING, "SPI transfer failed (attempt %d/%d): %s",
               attempt + 1, SPI_RETRIES, strerror(errno));
        if (attempt < SPI_RETRIES - 1) usleep(SPI_RETRY_DELAY_US);
    }
    syslog(LOG_ERR, "MCP3008 SPI transfer failed after %d attempts", SPI_RETRIES);
    return -1;
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d: %s", PUMP_GPIO, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Pump %s", state ? "activated" : "deactivated");
    return 0;
}

static void publish_moisture(int moisture) {
    if (!mosq) return;
    char payload[16];
    snprintf(payload, sizeof(payload), "%d", moisture);
    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC, (int)strlen(payload), payload, 0, false) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture: %s", strerror(errno));
    } else {
        syslog(LOG_INFO, "Published moisture: %d", moisture);
    }
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected");
