#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define MOTOR1_PIN      17
#define MOTOR2_PIN      27
#define PWM_FREQUENCY   100
#define PWM_PERIOD_US   (1000000 / PWM_FREQUENCY)
#define NOISE_THRESHOLD 500
#define SAMPLE_DELAY_US 10000
#define LOG_FILE        "vibration_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_vibration_event(int noise_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Noise Level: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, noise_level);
    } else {
        fprintf(fp, "Timestamp error - Noise Level: %d\n", noise_level);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

static void set_motor_pwm(int pin, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int on_us  = (PWM_PERIOD_US * duty_percent) / 100;
    int off_us = PWM_PERIOD_US - on_us;

    if (on_us > 0) {
        printf("Motor on GPIO%d: %d%% (%d us on, %d us off)\n", pin, duty_percent, on_us, off_us);
        usleep(on_us);
    }
    if (off_us > 0) {
        usleep(off_us);
    }
}

static void cleanup(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int noise_level = read_mcp3008(g_spi_fd, 0);
        if (noise_level < 0) {
            fprintf(stderr, "ADC read error, skipping iteration.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        printf("Noise Level: %d\n", noise_level);

        if (noise_level > NOISE_THRESHOLD) {
            log_vibration_event(noise_level);
            set_motor_pwm(MOTOR1_PIN, 100);
            set_motor_pwm(MOTOR2_PIN, 100);
        } else {
            set_motor_pwm(MOTOR1_PIN, 0);
            set_motor_pwm(MOTOR2_PIN, 0);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    set_motor_pwm(MOTOR1_PIN, 0);
    set_motor_pwm(MOTOR2_PIN, 0);
    cleanup();
    printf("Vibration monitoring stopped.\n");
    return 0;
}

