#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SPI_BUS        "/dev/spidev0.0"
#define BH1750_ADDR    0x23
#define BH1750_CONT_H  0x10
#define BH1750_CONT_L  0x01
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL_SEC 5
#define BH1750_CONV_MS  180

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_bh1750(int fd, float *lux) {
    uint8_t cmd = BH1750_CONT_H;
    if (write(fd, &cmd, 1) != 1) return -1;
    usleep(BH1750_CONV_MS * 1000);
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -2;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int spi_read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) return -1;
    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(FILE *fp, float sound_db, float light_lux, int err) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) return -1;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, sound_db, light_lux, err) < 0) return -1;
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) { perror("ioctl i2c"); close(i2c_fd); return 1; }

    int spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) { perror("open spi"); close(i2c_fd); return 1; }
    uint8_t mode = SPI_MODE_0, bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("spi config"); close(spi_fd); close(i2c_fd); return 1;
    }

    FILE *fp = fopen("tamper_log.csv", "a");
    if (!fp) { perror("fopen"); close(spi_fd); close(i2c_fd); return 1; }

    while (running) {
        int adc = spi_read_mcp3008(spi_fd, MCP3008_CHANNEL);
        float sound_db = (adc < 0) ? -99.0f : (float)adc * 0.0048828125f * 20.0f;

        float light_lux = 0.0f;
        int bh_err = i2c_read_bh1750(i2c_fd, &light_lux);
        int err = (adc < 0) ? 1 : (bh_err != 0) ? 2 : 0;

        if (log_data(fp, sound_db, light_lux, err) != 0) {
            fprintf(stderr, "log error\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fclose(fp);
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

