/*
 * Raspberry Pi 4 Model B – Vegetronix VH400 Soil Moisture Monitor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 CE0 (channel 0)
 *   - Vegetronix VH400 soil moisture sensor on MCP3008 CH0
 *   - Relay-driven water pump on BCM GPIO 17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lrt
 *   (Requires pigpio; run as root or with appropriate permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 on SPI0 */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define MCP3008_CHANNEL  0          /* VH400 on CH0 */

#define PUMP_GPIO        17         /* BCM GPIO 17 */

#define MOISTURE_THRESHOLD 30       /* Percentage */
#define SAMPLE_INTERVAL   60       /* Seconds */
#define MAX_RETRIES       3

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Function prototypes ------------------------- */
static int  initialize_spi(void);
static int  read_mcp3008(int channel);
static void control_pump(bool activate);
static void log_data(int moisture_level);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- SPI init -------------------------------- */
static int initialize_spi(void)
{
    /*
     * pigpio spiOpen flags: bits 0-1 = mode, bit 2 = CE active-low,
     * bits 3-5 = reserved, bit 6 = –, bit 7 = –.
     * Mode 0 → bits 0-1 = 00.
     */
    uint32_t flags = SPI_FLAGS;
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, flags);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, speed %d): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(g_spi_handle));
        return -1;
    }
    return 0;
}

/* --------------------------- MCP3008 read -------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed (returned %d): %s\n",
                ret, pigpio_error(ret));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------ Pump control ----------------------------- */
static void control_pump(bool activate)
{
    if (gpioWrite(PUMP_GPIO, activate ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n",
                PUMP_GPIO, activate ? 1 : 0);
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_data(int moisture_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Moisture Level: %d%%\n", timestamp, moisture_level);
    fflush(stdout);
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is off */
    control_pump(false);

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);  /* Start with pump off */

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int moisture_level = -1;
        int retries = 0;

        /* Retry loop for SPI read */
        while (retries < MAX_RETRIES && moisture_level < 0) {
            moisture_level = read_mcp3008(MCP3008_CHANNEL);
            if (moisture_level < 0) {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Retrying SPI read (%d/%d)...\n",
                            retries, MAX_RETRIES);
                    gpioDelay(1000000);  /* 1 s backoff */
                }
            }
        }

        if (moisture_level < 0) {
            fprintf(stderr, "Error: failed to read moisture after %d retries\n",
                    MAX_RETRIES);
            /* Turn pump off on persistent failure */
            control_pump(false);
        } else {
            /* Convert 10-bit ADC value to 0-100% */
            moisture_level = (int)(((float)moisture_level / 1023.0f) * 100.0f);

            log_data(moisture_level);

            if (moisture_level < MOISTURE_THRESHOLD) {
                control_pump(true);
                printf("Moisture below threshold (%d%%). Pump activated.\n",
                       MOISTURE_THRESHOLD);
                fflush(stdout);
            } else {
                control_pump(false);
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL * 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

