#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pthread.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define PWM_CHIP 0
#define PWM_NUM 0
#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_CYCLE_NS 0
#define TRIG_PIN 23
#define ECHO_PIN 24
#define CONFIG_FILE "theremin_config.txt"

#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_VOLUME 0.0
#define MAX_VOLUME 100.0
#define MIN_FREQUENCY 200.0
#define MAX_FREQUENCY 2000.0

#define TIMEOUT_US 100000
#define LOOP_DELAY_US 10000

typedef struct {
    float min_distance;
    float max_distance;
    float min_volume;
    float max_volume;
    float min_frequency;
    float max_frequency;
} CalibrationData;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int pwm_exported = 0;
static int pwm_enabled = 0;
static CalibrationData calibration = {2.0, 400.0, 0.0, 100.0, 200.0, 2000.0};
static pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    return 0;
}

static int read_ldr(void) {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float measure_distance(void) {
    struct timespec start, end;
    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1.0;
    }
    while (1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            return -1.0;
        }
        long elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L + (end.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "HC-SR04 timeout\n");
            return -1.0;
        }
        if (gpioRead(ECHO_PIN) == 1) break;
        usleep(1);
    }
    struct timespec pulse_start, pulse_end;
    while (1) {
        if (clock_gettime(CLOCK_MONOTONIC, &pulse_start) < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            return -1.0;
        }
        while (1) {
            if (clock_gettime(CLOCK_MONOTONIC, &pulse_end) < 0) {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                return -1.0;
            }
            long elapsed_us = (pulse_end.tv_sec - pulse_start.tv_sec) * 1000000L + (pulse_end.tv_nsec - pulse_start.tv_nsec) / 1000L;
            if (elapsed_us > TIMEOUT_US) {
                fprintf(stderr, "HC-SR04 timeout\n");
                return -1.0;
            }
            if (gpioRead(ECHO_PIN) == 0) break;
            usleep(1);
        }
        long pulse_duration_us = (pulse_end.tv_sec - pulse_start.tv_sec) * 1000000L + (pulse_end.tv_nsec - pulse_start.tv_nsec) / 1000L;
        return (float)pulse_duration_us / 58.0;
    }
}

static float map_value(float x, float in_min, float in_max, float out_min, float out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

static int pwm_init(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    int fd = open(path, O_WRONLY);
    if (fd >= 0) {
        if (write(fd, "0", 1) < 0) {
            if (errno != EBUSY) {
                fprintf(stderr, "PWM export failed: %s\n", strerror(errno));
                close(fd);
                return -1;
            }
        }
        close(fd);
        pwm_exported = 1;
    } else if (errno != EBUSY) {
        fprintf(stderr, "PWM export failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM period: %s\n", strerror(errno));
        return -1;
    }
    char period_str[32];
    snprintf(period_str, sizeof(period_str), "%d", PWM_PERIOD_NS);
    if (write(fd, period_str, strlen(period_str)) < 0) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM duty cycle: %s\n", strerror(errno));
        return -1;
    }
    char duty_str[32];
    snprintf(duty_str, sizeof(duty_str), "%d", PWM_DUTY_CYCLE_NS);
    if (write(fd, duty_str, strlen(duty_str)) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM enable: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "1", 1) < 0) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    pwm_enabled = 1;
    return 0;
}

static void pwm_set_frequency(float frequency) {
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;
    float period_ns = 1000000000.0 / frequency;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM period: %s\n", strerror(errno));
        return;
    }
    char period_str[32];
    snprintf(period_str, sizeof(period_str), "%d", (int)period_ns);
    if (write(fd, period_str, strlen(period_str)) < 0) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
    }
    close(fd);
}

static void pwm_set_duty_cycle(float volume) {
    if (volume < MIN_VOLUME) volume = MIN_VOLUME;
    if (volume > MAX_VOLUME) volume = MAX_VOLUME;
    float duty_ns = map_value(volume, MIN_VOLUME, MAX_VOLUME, 0, PWM_PERIOD_NS);
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_NUM);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM duty cycle: %s\n", strerror(errno));
        return;
    }
    char duty_str[32];
    snprintf(duty_str, sizeof(duty_str), "%d", (int)duty_ns);
    if (write(fd, duty_str, strlen(duty_str)) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
    }
    close(fd);
}

static void pwm_cleanup(void) {
    if (pwm_enabled) {
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
        int fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
        pwm_enabled = 0;
    }
    if (pwm_exported) {
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
        int fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
        pwm_exported = 0;
    }
}

static int load_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Config file not found, using defaults\n");
        return 0;
    }
    if (fscanf(fp, "%f %f %f %f %f %f",
               &calibration.min_distance, &calibration.max_distance,
               &calibration.min_volume, &calibration.max_volume,
               &calibration.min_frequency, &calibration.max_frequency) != 6) {
        fprintf(stderr, "Failed to read config file, using defaults\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int save_config(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open config file for writing: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%f %f %f %f %f %f\n",
            calibration.min_distance, calibration.max_distance,
            calibration.min_volume, calibration.max_volume,
            calibration.min_frequency, calibration.max_frequency);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }
    if (pwm_init() < 0) {
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (load_config(CONFIG_FILE) < 0) {
        fprintf(stderr, "Using default calibration values\n");
    }
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIG_PIN, 0);
    usleep(100000);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    float last_distance = calibration.max_distance;
    float last_volume = calibration.max_volume;
    while (running) {
        float distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Distance measurement failed, using last valid values\n");
            usleep(LOOP_DELAY_US);
            continue;
        }
        int ldr_value = read_ldr();
        if (ldr_value < 0) {
            fprintf(stderr, "LDR read failed, using last valid values\n");
            usleep(LOOP_DELAY_US);
            continue;
        }
        float volume = map_value(ldr_value, 0, 1023, calibration.min_volume, calibration.max_volume);
        float frequency = map_value(distance, calibration.min_distance, calibration.max_distance, calibration.min_frequency, calibration.max_frequency);
        pwm_set_frequency(frequency);
        pwm_set_duty_cycle(volume);
        last_distance = distance;
        last_volume = volume;
        usleep(LOOP_DELAY_US);
    }
    pwm_cleanup();
    close(spi_fd);
    gpioTerminate();
    return 0;
}

