                fprintf(stderr, "PWM export failed: %s\n", strerror(errno));
                close(fd);
                return -1;
            }
        }
        close(fd);
        pwm_exported = 1;
    } else if (errno != EBUSY) {
        fprintf(stderr, "PWM export failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM period: %s\n", strerror(errno));
        return -1;
    }
    char period_str[32];
    snprintf(period_str, sizeof(period_str), "%d", PWM_PERIOD_NS);
    if (write(fd, period_str, strlen(period_str)) < 0) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM duty cycle: %s\n", strerror(errno));
        return -1;
    }
    char duty_str[32];
    snprintf(duty_str, sizeof(duty_str), "%d", PWM_DUTY_CYCLE_NS);
    if (write(fd, duty_str, strlen(duty_str)) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM enable: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "1", 1) < 0) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    pwm_enabled = 1;
    return 0;
}

static void pwm_set_frequency(float frequency) {
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;
    float period_ns = 1000000000.0 / frequency;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM period: %s\n", strerror(errno));
        return;
    }
    char period_str[32];
    snprintf(period_str, sizeof(period_str), "%d", (int)period_ns);
    if (write(fd, period_str, strlen(period_str)) < 0) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
    }
    close(fd);
}

static void pwm_set_duty_cycle(float volume) {
    if (volume < MIN_VOLUME) volume = MIN_VOLUME;
    if (volume > MAX_VOLUME) volume = MAX_VOLUME;
    float duty_ns = map_value(volume, MIN_VOLUME, MAX_VOLUME, 0, PWM_PERIOD_NS);
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_NUM);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM duty cycle: %s\n", strerror(errno));
        return;
    }
    char duty_str[32];
    snprintf(duty_str, sizeof(duty_str), "%d", (int)duty_ns);
    if (write(fd, duty_str, strlen(duty_str)) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
    }
    close(fd);
}

static void pwm_cleanup(void) {
    if (pwm_enabled) {
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
        int fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
        pwm_enabled = 0;
    }
    if (pwm_exported) {
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
        int fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
        pwm_exported = 0;
    }
}

static int load_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Config file not found, using defaults\n");
        return 0;
    }
    if (fscanf(fp, "%f %f %f %f %f %f",
               &calibration.min_distance, &calibration.max_distance,
               &calibration.min_volume, &calibration.max_volume,
               &calibration.min_frequency, &calibration.max_frequency) != 6) {
        fprintf(stderr, "Failed to read config file, using defaults\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int save_config(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open config file for writing: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%f %f %f %f %f %f\n",
            calibration.min_distance, calibration.max_distance,
            calibration.min_volume, calibration.max_volume,
            calibration.min_frequency, calibration.max_frequency);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }
    if (pwm_init() < 0) {
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (load_config(CONFIG_FILE) < 0) {
        fprintf(stderr, "Using default calibration values\n");
    }
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIG_PIN, 0);
    usleep(100000);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    float last_distance = calibration.max_distance;
    float last_volume = calibration.max_volume;
    while (running) {
        float distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Distance measurement failed, using last valid values\n");
            usleep(LOOP_DELAY_US);
            continue;
        }
        int ldr_value = read_ldr();
        if (ldr_value < 0) {
            fprintf(stderr, "LDR read failed, using last valid values\n");
            usleep(LOOP_DELAY_US);
            continue;
        }
        float volume = map_value(ldr_value, 0, 1023, calibration.min_volume, calibration.max_volume);
        float frequency = map_value(distance, calibration.min_distance, calibration.max_distance, calibration.min_frequency, calibration.max_frequency);
        pwm_set_frequency(frequency);
        pwm_set_duty_cycle(volume);
        last_distance = distance;
        last_volume = volume;
        usleep(LOOP_DELAY_US);
    }
    pwm_cleanup();
    close(spi_fd);
    gpioTerminate();
    return 0;
}

