                    MAX_RETRIES, errno, strerror(errno));
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive ADC errors. Sensor may be absent or bus fault.\n");
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        consecutive_errors = 0;

        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr, "Warning: ADC reading at rail (%u) — possible sensor-absent condition.\n", adc_value);
        }

        float ppm = ((float)adc_value / (float)ADC_MAX) * 100.0f;

        if (log_data(ppm) < 0) {
