#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

/* Motor 1 */
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

/* Motor 2 */
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

/* MCP3008 SPI */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 /* 1 MHz */
#define SPI_FLAGS 0        /* Mode 0, active-low CE */

/* Timing */
#define ACCELERATION_DECELERATION_TIME 2.0
#define PAUSE_TIME 5.0
#define STEP_DELAY 0.01

/* Global flag for graceful shutdown */
volatile sig_atomic_t program_running = 1;

/* Signal handler for SIGINT and SIGTERM */
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Read a single-ended channel from MCP3008 via SPI */
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4 (single-ended mode + channel select)
     * Byte 2: 0x00 (don't care, clocked out for data)
     */
    char tx_buf[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx_buf[3] = {0};

    int bytes_transferred = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (bytes_transferred != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d (transferred %d bytes)\n",
                channel, bytes_transferred);
        return -1;
    }

    /* Extract 10-bit ADC value: lower 2 bits of rx_buf[1] << 8 | rx_buf[2] */
    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

/* Map ADC value to speed (0-255) */
int map_adc_to_speed(int adc_value) {
    if (adc_value < 0) return 0;
    if (adc_value > 1023) return 255;
    return (int)((float)adc_value / 1023.0 * 255.0);
}

/* Set motor speed and direction */
void set_motor_speed(int motor_number, int speed, int direction) {
    int enable_pin, direction_pin;
    if (motor_number == 1) {
        enable_pin = MOTOR1_ENABLE;
        direction_pin = MOTOR1_DIRECTION;
    } else if (motor_number == 2) {
        enable_pin = MOTOR2_ENABLE;
        direction_pin = MOTOR2_DIRECTION;
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor_number);
        return;
    }

    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;

    if (direction == 0) {
        gpioWrite(direction_pin, 0);
    } else {
        gpioWrite(direction_pin, 1);
    }

    gpioPWM(enable_pin, speed);
}

/* Accelerate motor from 0 to target speed */
void accelerate_motor(int motor_number, int target_speed) {
    for (int speed = 0; speed <= target_speed; speed++) {
        set_motor_speed(motor_number, speed, 0);
        time_sleep(STEP_DELAY);
    }
}

/* Decelerate motor from target speed to 0 */
void decelerate_motor(int motor_number, int target_speed) {
    for (int speed = target_speed; speed >= 0; speed--) {
        set_motor_speed(motor_number, speed, 0);
        time_sleep(STEP_DELAY);
    }
}

/* Cleanup all resources */
void cleanup(int spi_handle) {
    /* Stop motors */
    set_motor_speed(1, 0, 0);
    set_motor_speed(2, 0, 0);

    /* Close SPI */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    /* Terminate pigpio */
    gpioTerminate();
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO modes */
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    /* Open SPI channel */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        /* Read potentiometers */
        int pot1_adc = read_mcp3008(spi_handle, 0);
        int pot2_adc = read_mcp3008(spi_handle, 1);

        if (pot1_adc < 0 || pot2_adc < 0) {
            fprintf(stderr, "Error: Potentiometer read failed, skipping cycle\n");
            time_sleep(PAUSE_TIME);
            continue;
        }

        int speed1 = map_adc_to_speed(pot1_adc);
        int speed2 = map_adc_to_speed(pot2_adc);

        printf("Pot1: %d (ADC %d), Pot2: %d (ADC %d) -> Motor1: %d, Motor2: %d\n",
               speed1, pot1_adc, speed2, pot2_adc, speed1, speed2);

        /* Accelerate and decelerate */
        accelerate_motor(1, speed1);
        accelerate_motor(2, speed2);

        time_sleep(ACCELERATION_DECELERATION_TIME);

        decelerate_motor(1, speed1);
        decelerate_motor(2, speed2);

        time_sleep(PAUSE_TIME);

        /* Reverse direction */
        set_motor_speed(1, speed1, 1);
        set_motor_speed(2, speed2, 0);

        time_sleep(ACCELERATION_DECELERATION_TIME);

        decelerate_motor(1, speed1);
        decelerate_motor(2, speed2);

        time_sleep(PAUSE_TIME);
    }

    /* Cleanup */
    cleanup(spi_handle);
    printf("Program terminated gracefully.\n");
    return 0;
}

