#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define NOISE_LEVEL_THRESHOLD 500
#define DEBOUNCE_DELAY_US 10000
#define CALIBRATION_DURATION_SEC 5
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_noise_level(int duration_sec) {
    long sum = 0;
    int samples = 0;
    time_t start = time(NULL);

    printf("Calibrating noise level for %d seconds...\n", duration_sec);

    while (running && (time(NULL) - start) < duration_sec) {
        int val = read_mcp3008(MCP3008_CHANNEL);
        if (val < 0) {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return -1;
        }
        sum += val;
        samples++;
        gpioDelay(10000);
    }

    if (!running) {
        fprintf(stderr, "Calibration interrupted by signal\n");
        return -1;
    }

    if (samples == 0) {
        fprintf(stderr, "No samples collected during calibration\n");
        return -1;
    }

    return (int)(sum / samples);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int noise_level = calibrate_noise_level(CALIBRATION_DURATION_SEC);
    if (noise_level < 0) {
        fprintf(stderr, "Noise level calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    printf("Noise level calibrated: %d\n", noise_level);

    int led_state = 0;
    uint32_t last_toggle_tick = 0;

    while (running) {
        int val = read_mcp3008(MCP3008_CHANNEL);
        if (val < 0) {
            fprintf(stderr, "Error reading ADC\n");
            gpioDelay(100000);
            continue;
        }

        int diff = val - noise_level;
        if (diff > NOISE_LEVEL_THRESHOLD) {
            uint32_t now = gpioTick();
            if (now - last_toggle_tick > DEBOUNCE_DELAY_US) {
                led_state = !led_state;
                gpioWrite(LED_PIN, led_state);
                last_toggle_tick = now;
            }
        } else {
            if (led_state) {
                gpioWrite(LED_PIN, 0);
                led_state = 0;
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Program terminated gracefully\n");
    return 0;
}

