#include <string.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

float voltage_to_airflow(int adc_value) {
    if (adc_value < 0) return -1.0f;
    return (float)adc_value * 0.001f;
}

void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (airflow < 0.0f) {
        fprintf(log_file, "%s, ERROR: ADC read failed\n", timestamp);
    } else {
        fprintf(log_file, "%s, %.3f\n", timestamp, airflow);
    }
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        float airflow = voltage_to_airflow(adc_value);
        log_data(airflow);
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

