#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip0"
#define GPIO_LINE_OFFSET 8
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000ULL / SAMPLE_RATE_HZ)
#define ADC_CHANNEL     0

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static FILE    *g_log_file = NULL;
static struct gpiod_line *g_gpio_line = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    g_gpio_line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!g_gpio_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(g_gpio_line, "admp401_cs", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        g_gpio_line = NULL;
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

static int read_adc(uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = 1000000,
        .bits_per_word = 8,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (gpiod_line_set_value(g_gpio_line, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        gpiod_line_set_value(g_gpio_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_gpio_line, 1) < 0) {
        perror("gpiod_line_set_value(1)");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(uint64_t timestamp_ns, int adc_value)
{
    if (fprintf(g_log_file, "%llu|%d\n", (unsigned long long)timestamp_ns, adc_value) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush");
        return -1;
    }
