#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <math.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define MCP3008_CH0 0
#define MCP3008_CH1 1
#define MCP3008_CH2 2

#define ADC_MAX 1023.0
#define VREF 3.3
#define SCALE_FACTOR 0.33

#define KALMAN_Q 0.001
#define KALMAN_R 0.01

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

float kalman_filter(float measurement, float *state, float *covariance, float Q, float R) {
    *covariance += Q;
    float k = *covariance / (*covariance + R);
    *state += k * (measurement - *state);
    *covariance = (1.0 - k) * *covariance;
    return *state;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    float x_state = 0.0, x_cov = 0.0;
    float y_state = 0.0, y_cov = 0.0;
    float z_state = 0.0, z_cov = 0.0;

    while (running) {
        int x = read_adc(MCP3008_CH0);
        int y = read_adc(MCP3008_CH1);
        int z = read_adc(MCP3008_CH2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            usleep(100000);
            continue;
        }

        float x_raw = (float)x * VREF / ADC_MAX;
        float y_raw = (float)y * VREF / ADC_MAX;
        float z_raw = (float)z * VREF / ADC_MAX;

        float x_filtered = kalman_filter(x_raw, &x_state, &x_cov, KALMAN_Q, KALMAN_R);
        float y_filtered = kalman_filter(y_raw, &y_state, &y_cov, KALMAN_Q, KALMAN_R);
        float z_filtered = kalman_filter(z_raw, &z_state, &z_cov, KALMAN_Q, KALMAN_R);

        float x_g = x_filtered * SCALE_FACTOR;
        float y_g = y_filtered * SCALE_FACTOR;
        float z_g = z_filtered * SCALE_FACTOR;

        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_g, y_g, z_g);
        fflush(stdout);

        usleep(100000);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

