#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define MIN_MAGNETIC_FIELD -100.0f
#define MAX_MAGNETIC_FIELD 100.0f
#define VOLTAGE_HIGH 3.3f
#define VOLTAGE_LOW 0.0f

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/*
 * Reads the digital state of a GPIO pin.
 * Returns 0 or 1 on success, -1 on error.
 */
static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

/*
 * Converts a digital logic state (0 or 1) to a magnetic field strength in mT.
 * HIGH (1) -> 3.3 V -> 3.3 V / 3.3 V * 100 mT = 100 mT
 * LOW  (0) -> 0.0 V -> 0.0 V / 3.3 V * 100 mT = 0 mT
 */
static float convert_to_magnetic_field(int sensor_value) {
    float voltage = (sensor_value == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
    return (voltage / VOLTAGE_HIGH) * 100.0f;
}

/*
 * Logs the magnetic field strengths to a file.
 * Returns 0 on success, -1 on error.
 */
static int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pins as inputs */
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR3_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow pull-down resistors to ensure defined logic when sensor is disconnected */
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_DOWN);

    printf("Starting magnetic field monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor data. Skipping this iteration.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float sensor1_mT = convert_to_magnetic_field(sensor1_value);
        float sensor2_mT = convert_to_magnetic_field(sensor2_value);
        float sensor3_mT = convert_to_magnetic_field(sensor3_value);

        if (sensor1_mT < MIN_MAGNETIC_FIELD || sensor1_mT > MAX_MAGNETIC_FIELD ||
            sensor2_mT < MIN_MAGNETIC_FIELD || sensor2_mT > MAX_MAGNETIC_FIELD ||
            sensor3_mT < MIN_MAGNETIC_FIELD || sensor3_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: magnetic field out of range [%.1f, %.1f] mT. Skipping log.\n",
                    MIN_MAGNETIC_FIELD, MAX_MAGNETIC_FIELD);
        } else {
            if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
                fprintf(stderr, "Error logging data. Continuing...\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

