#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_pump(int on) {
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) != 0) {
        log_event("ERROR: Failed to write pump GPIO");
        return -1;
    }
    log_event(on ? "Pump turned ON" : "Pump turned OFF");
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        log_event("ERROR: Failed to set pump GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_event("ERROR: Failed to open SPI channel");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    int pump_on = 0;
    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            log_event("ERROR: SPI read failed");
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg), "Moisture: %d%%", moisture);
            log_event(msg);

            if (moisture < MOISTURE_THRESHOLD && !pump_on) {
                if (control_pump(1) == 0) pump_on = 1;
            } else if (moisture >= MOISTURE_THRESHOLD && pump_on) {
                if (control_pump(0) == 0) pump_on = 0;
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

