#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60
#define JSON_BUFFER_SIZE 256

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static int led_gpio = LED_GPIO;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno: %s)\n", ts, message, strerror(errno));
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int parse_json(const char *json_string, bool *led_state) {
    char buffer[JSON_BUFFER_SIZE];
    strncpy(buffer, json_string, JSON_BUFFER_SIZE - 1);
    buffer[JSON_BUFFER_SIZE - 1] = '\0';

    char *token = strtok(buffer, "{}\"");
    if (token == NULL) return -1;

    bool found_led_state = false;
    while (token != NULL) {
        if (strcmp(token, "led_state") == 0) {
            token = strtok(NULL, ":");
            if (token == NULL) return -1;
            char *endptr;
            long val = strtol(token, &endptr, 10);
            if (*endptr != '\0' || val < 0 || val > 1) return -1;
            *led_state = (val == 1);
            found_led_state = true;
            break;
        }
        token = strtok(NULL, "{},");
    }

    if (!found_led_state) return -1;
    return 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker.\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        log_error("MQTT connection failed");
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != 0) {
        log_error("Unexpected disconnection");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;

    if (message->payloadlen <= 0) {
        log_error("Empty payload received");
        return;
    }

    char payload[JSON_BUFFER_SIZE];
    int len = message->payloadlen < (JSON_BUFFER_SIZE - 1) ? message->payloadlen : (JSON_BUFFER_SIZE - 1);
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    bool led_state = false;
    if (parse_json(payload, &led_state) != 0) {
        log_error("Invalid JSON format");
        return;
    }

    if (gpioWrite(led_gpio, led_state ? 1 : 0) != 0) {
        log_error("Failed to write to GPIO");
    }

    printf("Received: %s, LED State: %s\n", payload, led_state ? "ON" : "OFF");
}

static void cleanup(void) {
    if (mosq != NULL) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(led_gpio, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to install signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    if (gpioSetMode(led_gpio, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(led_gpio, 0) != 0) {
        log_error("Failed to initialize LED state");
        gpioTerminate();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mosq == NULL) {
        log_error("Failed to create MQTT client");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int reconnect_delay = 1;
    while (running) {
        int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT connect failed");
            if (reconnect_delay <= MAX_RECONNECT_DELAY) {
                sleep(reconnect_delay);
                reconnect_delay *= 2;
            } else {
                sleep(MAX_RECONNECT_DELAY);
            }
            continue;
        }

        reconnect_delay = 1;

        rc = mosquitto_loop_start(mosq);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT loop start failed");
            mosquitto_disconnect(mosq);
            sleep(1);
            continue;
        }

        while (running) {
            sleep(1);
        }

        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
    }

    cleanup();
    return 0;
}

