#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/epoll.h>
#include <linux/input.h>

#define GPIO_CHIP_PATH "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 17
#define EVENT_FILE_PATH "/dev/input/event17"
#define LOG_FILE_PATH "/var/log/vibration_shutdown.log"
#define CONSUMER_NAME "vibration-monitor"
#define EPOLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE_PATH, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }

    if (fclose(fp) != 0) {
        perror("fclose log file");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    int gpio_chip_fd = open(GPIO_CHIP_PATH, O_RDONLY);
    if (gpio_chip_fd == -1) {
        perror("open gpiochip");
        return EXIT_FAILURE;
    }

    int event_fd = open(EVENT_FILE_PATH, O_RDONLY | O_CLOEXEC);
    if (event_fd == -1) {
        perror("open event file");
        close(gpio_chip_fd);
        return EXIT_FAILURE;
    }

    int epoll_fd = epoll_create1(EPOLL_CLOEXEC);
    if (epoll_fd == -1) {
        perror("epoll_create1");
        close(event_fd);
        close(gpio_chip_fd);
        return EXIT_FAILURE;
    }

    struct epoll_event ev;
    memset(&ev, 0, sizeof(ev));
    ev.events = EPOLLIN;
    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, event_fd, &ev) == -1) {
        perror("epoll_ctl add");
        close(epoll_fd);
        close(event_fd);
        close(gpio_chip_fd);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started on GPIO17 (BCM). Press Ctrl+C to exit.\n");

    while (program_running) {
        int ready = epoll_wait(epoll_fd, &ev, 1, EPOLL_TIMEOUT_MS);
        if (ready == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("epoll_wait");
            break;
        }
        if (ready == 0) {
            continue;
        }

        struct input_event ev_data;
        ssize_t n = read(event_fd, &ev_data, sizeof(ev_data));
        if (n == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("read event");
            break;
        }
        if (n != (ssize_t)sizeof(ev_data)) {
            fprintf(stderr, "Short read on event file\n");
            continue;
        }

        if (ev_data.type == EV_KEY && ev_data.code == KEY_SUSPEND && ev_data.value == 1) {
            printf("Vibration detected! Shutting down system...\n");
            if (log_event("Vibration detected! Shutting down system...") == -1) {
                fprintf(stderr, "Failed to log event.\n");
            }
            system("sudo shutdown -h now");
            break;
        }
    }

    close(epoll_fd);
    close(event_fd);
    close(gpio_chip_fd);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

