#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BMP280_ADDR 0x76

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB_00 0x88

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

#define SEA_LEVEL_PRESSURE 101325.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(int handle) {
    uint8_t buf[24];
    if (i2cReadI2CBlockData(handle, BMP280_REG_CALIB_00, (char *)buf, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    calib.dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    calib.dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    calib.dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    calib.dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    calib.dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int init_bmp280(int handle) {
    int id = i2cReadByteData(handle, BMP280_REG_ID);
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2cWriteByteData(handle, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280\n");
        return -1;
    }
    gpioDelay(10000);
    if (read_calibration_data(handle) != 0) return -1;
    if (i2cWriteByteData(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_MEAS\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error: Failed to write CONFIG\n");
        return -1;
    }
    return 0;
}

static int read_raw_data(int handle, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t buf[6];
    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw data\n");
        return -1;
    }
    *raw_press = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    *raw_temp = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

static double compensate_temperature(int32_t raw_temp) {
    double var1 = ((double)raw_temp / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) *
                 ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * (double)calib.dig_T3;
    t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double compensate_pressure(int32_t raw_press) {
    double var1 = ((double)t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * (double)calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    var1 = ((double)calib.dig_P3 * var1 * var1 / 524288.0 + (double)calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)calib.dig_P1;
    if (var1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)calib.dig_P7) / 16.0;
    return p;
}

static double calculate_altitude(double pressure) {
    return 44330.0 * (1.0 - pow(pressure / SEA_LEVEL_PRESSURE, 0.1903));
}

static void log_data(FILE *fp, double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(fp, "%s,%.2f\n", timestamp, altitude);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BMP280_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_bmp280(i2c_handle) != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int32_t raw_temp, raw_press;
        if (read_raw_data(i2c_handle, &raw_temp, &raw_press) == 0) {
            double temp_c = compensate_temperature(raw_temp);
            double pressure = compensate_pressure(raw_press);
            double altitude = calculate_altitude(pressure);
            log_data(log_file, altitude);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }
        gpioDelay(5000000);
    }

    fprintf(stderr, "Shutting down cleanly...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

