#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define BH1750_PWR_DOWN 0x00
#define BH1750_I2C_BUS "/dev/i2c-1"

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0

#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, unsigned int *value) {
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *value = ((unsigned int)buf[0] << 8) | buf[1];
    return 0;
}

static int read_bh1750(int fd, float *lux) {
    if (i2c_write_byte(fd, BH1750_PWR_DOWN) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES_MODE) < 0) return -1;
    usleep(180000);

    unsigned int raw;
    if (i2c_read_word(fd, &raw) < 0) return -1;

    *lux = (float)raw / 1.2f;
    return 0;
}

static int read_mcp3008(int spi_fd, int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_data(const char *filename, float light, int sound) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Light: %.2f lux, Sound: %d\n", timestamp, light, sound);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(BH1750_I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", BH1750_I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    unsigned int mode = SPI_MODE_0;
    unsigned int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(unsigned int){SPI_SPEED}) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    printf("Starting environmental monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        float light = 0.0f;
        int sound = 0;
        int light_ok = 0, sound_ok = 0;

        if (read_bh1750(i2c_fd, &light) == 0) {
            light_ok = 1;
        } else {
            fprintf(stderr, "Failed to read BH1750 sensor.\n");
        }

        if (read_mcp3008(spi_fd, MCP3008_CHANNEL, &sound) == 0) {
            sound_ok = 1;
        } else {
            fprintf(stderr, "Failed to read MCP3008 channel %d.\n", MCP3008_CHANNEL);
        }

        if (light_ok || sound_ok) {
            if (log_data(LOG_FILE, light, sound) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

