#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define LOG_FILE "temperature_log.txt"
#define SPI_SPEED_HZ 500000
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_celsius(int adc_value) {
    return (adc_value * 3.3f) / 1024.0f - 0.5f;
}

static int write_mcp4725(int dac_value) {
    if (dac_value < 0 || dac_value > 4095) {
        fprintf(stderr, "Invalid DAC value: %d\n", dac_value);
        return -1;
    }

    uint8_t buf[2] = {
        (uint8_t)((dac_value >> 8) & 0x0F),
        (uint8_t)(dac_value & 0xFF)
    };

    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(int adc_value, float temp_c, int dac_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_fp, "%s, ADC: %d, Temp: %.2f C, DAC: %d\n", timestamp, adc_value, temp_c, dac_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) { close(spi_fd); spi_fd = -1; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) { cleanup(); return 1; }
    if (i2c_init() < 0) { cleanup(); return 1; }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;
        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) break;
            retries++;
            usleep(100000);
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries. Skipping sample.\n", MAX_RETRIES);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float temp_c = adc_to_celsius(adc_value);

        int dac_value = (int)((temp_c + 0.5f) / 30.0f * 4095.0f);
        if (dac_value < 0) dac_value = 0;
        if (dac_value > 4095) dac_value = 4095;

        int write_retries = 0;
        while (write_retries < MAX_RETRIES && running) {
            if (write_mcp4725(dac_value) == 0) break;
            write_retries++;
            usleep(100000);
        }

        if (write_retries >= MAX_RETRIES) {
            fprintf(stderr, "Failed to write DAC after %d retries.\n", MAX_RETRIES);
        }

        if (log_data(adc_value, temp_c, dac_value) < 0) {
            fprintf(stderr, "Logging failed.\n");
        }

        printf("ADC: %d, Temp: %.2f C, DAC: %d\n", adc_value, temp_c, dac_value);
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

