#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    /* Deactivate all relays (LOW) */
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);
    gpioTerminate();
}

int main(void) {
    unsigned relays[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int relay_count = 4;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure all relay pins as outputs, initially LOW (relays OFF) */
    for (int i = 0; i < relay_count; i++) {
        if (safe_set_mode(relays[i], PI_OUTPUT) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        if (safe_write(relays[i], 0) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < relay_count && running; i++) {
            if (safe_write(relays[i], 1) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Relay %d ON\n", i + 1);
            fflush(stdout);
            time_sleep(1.0);

            if (safe_write(relays[i], 0) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Relay %d OFF\n", i + 1);
            fflush(stdout);
            time_sleep(1.0);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

