            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Error: Failed to turn off LED\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

