/*
 * Rain sensor monitor with L298N motor control on Raspberry Pi 3 Model B+.
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0), 1 MHz, mode 0
 *   - Seeed Studio Grove Rain Sensor analog output -> MCP3008 CH0
 *   - L298N motor driver:
 *       IN1 -> GPIO17 (BCM)
 *       IN2 -> GPIO18 (BCM)
 *       ENA -> GPIO27 (BCM)  (PWM-capable)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rain rain.c -lrt -lpthread
 *
 * Run:
 *   sudo ./rain
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_MODE          0
#define SPI_BITS_PER_WORD 8

#define MCP3008_CHANNEL   0          /* ADC channel connected to rain sensor */

#define MOTOR_IN1_PIN     17         /* BCM 17 */
#define MOTOR_IN2_PIN     18         /* BCM 18 */
#define MOTOR_ENA_PIN     27         /* BCM 27 (PWM-capable) */

#define RAIN_THRESHOLD    5          /* ADC count threshold */
#define MOTOR_PWM_DUTY    150        /* 0-255 range */
#define MOTOR_PWM_RANGE   255
