 * MCP3008 single-ended read.
 * Protocol (3 bytes):
 *   tx[0] = 0x01                 (start bit)
 *   tx[1] = (0x08 | channel)<<4  (single-ended + channel)
 *   tx[2] = 0x00                 (don't care)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
