}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(int rain_level)
{
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: log file not open\n");
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time(): %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *tstruct = localtime_r(&now, &tm_buf);
    if (tstruct == NULL) {
        fprintf(stderr, "Error: localtime_r\n");
        return;
    }

