        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, Rain Level: %d\n", ts, rain_level) < 0) {
        fprintf(stderr, "Error: fprintf to log: %s\n", strerror(errno));
