    /* --- Main loop --- */
    while (g_running) {
        int rain_level = 0;

        if (mcp3008_read(MCP3008_CHANNEL, &rain_level) != 0) {
            fprintf(stderr, "Error: SPI read failed; skipping cycle\n");
