            motor_reverse();
            sleep(MOTOR_RUN_SEC);
            motor_stop();
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

