#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio17"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define GPIO_DIRECTION_PATH "/sys/class/gpio/gpio17/direction"
#define GPIO_VALUE_PATH "/sys/class/gpio/gpio17/value"
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define RETRY_DELAY_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int write_file(const char *path, const char *value) {
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s", value) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_file(const char *path, char *buffer, size_t bufsize) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (!fgets(buffer, (int)bufsize, fp)) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gpio_value(int *value) {
    char buffer[32];
    if (read_file(GPIO_VALUE_PATH, buffer, sizeof(buffer)) != 0) {
        return -1;
    }
    *value = (int)(buffer[0] - '0');
    return 0;
}

static int log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int setup_gpio(void) {
    if (write_file(GPIO_EXPORT_PATH, "17") != 0) {
        fprintf(stderr, "Failed to export GPIO17\n");
        return -1;
    }
    if (write_file(GPIO_DIRECTION_PATH, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO17 direction\n");
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    write_file(GPIO_UNEXPORT_PATH, "17");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed, exiting\n");
        return 1;
    }

    printf("Monitoring Sharp GP2Y0A21YK0F sensor on GPIO17...\n");

    while (program_running) {
        int distance;
        if (read_gpio_value(&distance) != 0) {
            fprintf(stderr, "Error reading GPIO value, retrying in %d seconds...\n", RETRY_DELAY_SEC);
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance, retrying in %d seconds...\n", RETRY_DELAY_SEC);
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    printf("GPIO unexported. Exiting.\n");
    return 0;
}

