#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define SAMPLE_INTERVAL 60
#define LOG_FILE "soil_moisture.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", handle);
        return -1;
    }

    int ret = spiXfer(handle, tx, rx, 3);
    spiClose(handle);

    if (ret != 3) {
        fprintf(stderr, "spiXfer failed: %d\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }
    return ((float)adc_value / 1023.0) * 100.0;
}

static void log_data(float moisture, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n",
            timestamp, moisture, pump_state ? "ON" : "OFF");
    fflush(log_file);
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write pump GPIO\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction failed");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture = adc_to_moisture(adc_value);
        if (moisture < 0) {
            fprintf(stderr, "Error converting ADC to moisture\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int pump_state = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
        control_pump(pump_state);
        log_data(moisture, pump_state);

        printf("Moisture: %.2f%%, Pump: %s\n", moisture, pump_state ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    control_pump(0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

