                fprintf(stderr, "Logging failed; continuing\n");
            }
            printf("Raw: %4d  B: %.2f mT\n", raw, b_field);
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    fclose(log_fp);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

