#include <linux/spi/spidev.h>
#include <errno.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_PIN        17
#define ADC_CHANNEL     0
#define VREF            5.0f
#define ADC_MAX         1023.0f
#define SAMPLE_INTERVAL 1
#define LOG_FILE        "current_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int gpio_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int gpio_init(void) {
    gpio_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (gpio_fd >= 0) {
        char buf[16];
        int len = snprintf(buf, sizeof(buf), "%d", GPIO_PIN);
        if (write(gpio_fd, buf, len) < 0) {
            fprintf(stderr, "Warning: failed to export GPIO %d: %s\n", GPIO_PIN, strerror(errno));
            close(gpio_fd); gpio_fd = -1;
        } else {
            close(gpio_fd); gpio_fd = -1;
        }
    }

    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", GPIO_PIN);
    gpio_fd = open(path, O_RDWR);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO value for writing: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_adc(int channel) {
    if (spi_fd < 0) return -1;

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_current(int adc_value) {
    if (adc_value < 0) return 0.0f;
    return ((float)adc_value / ADC_MAX) * VREF;
}

static int log_data(float current) {
    if (log_fp == NULL) return -1;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_fp, "%s,%.3f\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
        gpio_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Starting current monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        if (write(gpio_fd, "1", 1) < 0) {
            fprintf(stderr, "Error setting GPIO high: %s\n", strerror(errno));
        }
        usleep(1000);

        int adc_value = read_adc(ADC_CHANNEL);

        if (write(gpio_fd, "0", 1) < 0) {
            fprintf(stderr, "Error setting GPIO low: %s\n", strerror(errno));
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
        } else {
            float current = adc_to_current(adc_value);
            if (log_data(current) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

