#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi Zero W – MLX91211 Current Sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pi pin 1)
 *   MCP3008 VREF -> 3.3 V (Pi pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MLX91211 analog output (0–5 V)
 *   MLX91211 VDD -> 3.3 V (Pi pin 1)
 *   MLX91211 GND -> GND
 *
 * SPI0: 1 MHz, mode 0, CE0 active low.
 */

#define SPI_CHANNEL    0          /* MCP3008 on CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended CH0 */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VREF           3.3        /* Pi 5 V rail */
#define SAMPLE_US      100000     /* 100 ms */
#define LOG_FILE       "current_log.txt"
#define VOLTAGE_MIN    0.0
#define VOLTAGE_MAX    5.0

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended, channel 0)         */
/* Returns 0–1023 on success, -1 on SPI transfer error.               */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc;
}

/* ------------------------------------------------------------------ */
