#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000
#define LOG_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Debounce: read the pin DEBOUNCE_SAMPLES times spaced DEBOUNCE_DELAY_US
 * microseconds apart. Returns 0 or 1, or -1 on read error.
 */
static int debounce_read(int pin) {
    int high_count = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int v = gpioRead(pin);
        if (v < 0) {
            fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                    pin, pigpio_error(v));
            return -1;
        }
        if (v) high_count++;
        gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (high_count > DEBOUNCE_SAMPLES / 2) ? 1 : 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * B5W-DB01 has an internal pull-up; enable the external pull-up
     * so the pin is defined when the program starts.
     */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring Omron B5W-DB01 sensors on GPIO%d and GPIO%d...\n",
           SENSOR_1_PIN, SENSOR_2_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = debounce_read(SENSOR_1_PIN);
        int s2 = debounce_read(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error — exiting\n");
            break;
        }

        printf("Sensor 1: %d, Sensor 2: %d\n", s1, s2);

        if (s1 == 1 && s2 == 1) {
            printf("ALERT: Both sensors detect object\n");
        }

        gpioDelay(LOG_INTERVAL_S * 1000000);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

