#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

typedef struct {
    int channel;
    int baud;
} spi_config_t;

int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
int log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    char rx_buf[3] = {0};

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    return 100.0 - ((double)(adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
}

int log_data(double moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int spi_setup(spi_config_t config) {
    spi_handle = spiOpen(config.channel, config.baud, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d at %d baud\n", config.channel, config.baud);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_config_t spi_config = {SPI_CHANNEL, SPI_BAUD};
    if (spi_setup(spi_config) != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);

        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Warning: Failed to log data, continuing...\n");
        }

        printf("Moisture Level: %.2f%%\n", moisture_level);
        sleep(READ_DELAY);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

