/*
 * security_cam.c — Raspberry Pi 4 Model B
 *
 * Monitors an HC-SR501 PIR sensor on GPIO17 (BCM) with a 200 ms debounce
 * delay. On motion, captures a JPEG via libcamera-still and stores it in
 * /home/pi/security_cam/<value>_YYYY-MM-DDTHH:MM:SS.jpg.
 *
 * Build:  gcc -O2 -Wall -Wextra -o security_cam security_cam.c -lcamera
 * Run:    sudo ./security_cam
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/wait.h>
#include <syslog.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define PIR_GPIO          17
#define DEBOUNCE_MS       200
#define POLL_INTERVAL_US  50000   /* 50 ms */
#define CAPTURE_DIR       "/home/pi/security_cam"
#define CAPTURE_WIDTH     640
#define CAPTURE_HEIGHT    480
#define CAPTURE_TIMEOUT   1000    /* ms */
#define CAPTURE_QUALITY   85

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Construct a safe filename from the documented value and an ISO-8601
 * timestamp.  Returns 0 on success, -1 on error.
 */
static int make_filename(const char *value, char *buf, size_t buflen)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return -1;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        syslog(LOG_ERR, "localtime_r() failed");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_local) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return -1;
    }

    if (snprintf(buf, buflen, "%s_%s.jpg", value, ts) >= (int)buflen) {
        syslog(LOG_ERR, "filename truncated");
        return -1;
    }
    return 0;
}

/*
 * Ensure the capture directory exists.  Returns 0 on success, -1 on
 * error.
 */
static int ensure_dir(void)
{
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "'%s' exists but is not a directory", CAPTURE_DIR);
        return -1;
    }

    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat('%s'): %s", CAPTURE_DIR, strerror(errno));
        return -1;
    }

    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        syslog(LOG_ERR, "mkdir('%s'): %s", CAPTURE_DIR, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Fork + exec a libcamera-still capture.  Returns 0 on success, -1 on
 * error.
 */
static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        /* Child */
        char width_str[16], height_str[16], quality_str[16], timeout_str[16];
        snprintf(width_str,  sizeof(width_str),  "%d", CAPTURE_WIDTH);
        snprintf(height_str, sizeof(height_str), "%d", CAPTURE_HEIGHT);
        snprintf(quality_str, sizeof(quality_str), "%d", CAPTURE_QUALITY);
        snprintf(timeout_str, sizeof(timeout_str), "%d", CAPTURE_TIMEOUT);

        char *argv[] = {
            "libcamera-still",
            "-o", (char *)filename,
            "--width",  width_str,
            "--height", height_str,
            "--quality", quality_str,
            "--timeout", timeout_str,
            "--nopreview",
            NULL
        };

        execvp("libcamera-still", argv);
        /* If execvp returns, it failed */
        syslog(LOG_ERR, "execvp(libcamera-still): %s", strerror(errno));
        _exit(127);
    }

    /* Parent */
    int status = 0;
    if (waitpid(pid, &status, 0) != pid) {
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }

    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        syslog(LOG_ERR, "libcamera-still failed (status=%d)", status);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting security_cam (PIR=GPIO%d, dir=%s)",
           PIR_GPIO, CAPTURE_DIR);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_INPUT) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_dir() != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "gpioRead(%d) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring started (initial state=%d)", last_state);

    while (g_running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed", PIR_GPIO);
            break;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_MS * 1000); /* 200 ms debounce */

            int confirmed = gpioRead(PIR_GPIO);
            if (confirmed < 0) {
                syslog(LOG_ERR, "gpioRead(%d) failed during debounce", PIR_GPIO);
                break;
            }

            if (confirmed == current_state) {
                char filename[256];
                if (make_filename("motion", filename, sizeof(filename)) != 0) {
                    syslog(LOG_ERR, "Failed to construct filename");
                } else {
                    if (capture_image(filename) == 0) {
                        syslog(LOG_INFO, "Motion detected, captured %s", filename);
                    } else {
                        syslog(LOG_ERR, "Failed to capture image for %s", filename);
                    }
                }
            }
            last_state = confirmed;
        }

        gpioDelay(POLL_INTERVAL_US); /* 50 ms poll interval */
    }

    syslog(LOG_INFO, "Shutting down");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

