/*
 * capture_ov5647.c — Capture grayscale frames from an Arducam OV5647 CSI camera
 * module on a Raspberry Pi 3 Model B+ using the Linux V4L2 API.
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture_ov5647 capture_ov5647.c
 * Run:    ./capture_ov5647 /dev/video0
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEFAULT_CAMERA "/dev/video0"
#define MAX_FRAMES     1000
#define IMAGE_WIDTH    640
#define IMAGE_HEIGHT   480
#define IMAGE_SIZE     (IMAGE_WIDTH * IMAGE_HEIGHT)
#define FILENAME_LEN   32

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int set_format(int fd)
{
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        return -1;
    }

    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_HEIGHT) {
        fprintf(stderr, "Warning: driver did not accept %dx%d format; got %ux%u\n",
                IMAGE_WIDTH, IMAGE_HEIGHT, fmt.fmt.pix.width, fmt.fmt.pix.height);
    }
    return 0;
}

static int request_buffers(int fd, unsigned int num_buffers)
{
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        return -1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on device\n");
        return -1;
    }
    return 0;
}

static int query_buffer(int fd, unsigned int index, struct v4l2_buffer *buf)
{
    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;
    buf->index = index;

    if (xioctl(fd, VIDIOC_QUERYBUF, buf) == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed for buffer %u: %s\n",
                index, strerror(errno));
        return -1;
    }
    return 0;
}

static int map_buffer(int fd, unsigned int index, unsigned char **data, size_t *length)
{
    struct v4l2_buffer buf;
    if (query_buffer(fd, index, &buf) == -1)
        return -1;

    *data = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*data == MAP_FAILED) {
        fprintf(stderr, "mmap failed for buffer %u: %s\n", index, strerror(errno));
        *data = NULL;
        return -1;
    }
    *length = buf.length;
    return 0;
}

static int unmap_buffer(unsigned char *data, size_t length)
{
    if (data && munmap(data, length) == -1) {
        fprintf(stderr, "munmap failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int enqueue_buffer(int fd, unsigned int index)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed for buffer %u: %s\n",
                index, strerror(errno));
        return -1;
    }
    return 0;
}

static int dequeue_buffer(int fd, unsigned int *index)
{
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR)
            return -1;
        fprintf(stderr, "select() failed: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select() timeout: no frame available\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        if (errno == EAGAIN)
            return -1;
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }
    *index = buf.index;
    return 0;
}

static int save_pgm(const unsigned char *data, size_t length, int frame_number)
{
    char filename[FILENAME_LEN];
    snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_number);

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
        fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    size_t written = fwrite(data, 1, length, fp);
    if (written != length) {
        fprintf(stderr, "fwrite failed: wrote %zu of %zu bytes\n", written, length);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
