#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define UDP_PORT 5000
#define MAX_FRAME_SIZE 65500
#define NUM_BUFFERS 4

#define CLEAR(x) memset(&(x), 0, sizeof(x))

typedef struct {
    void *start;
    size_t length;
} buffer_t;

static int fd = -1;
static buffer_t buffers[NUM_BUFFERS];
static int n_buffers = 0;
static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fh, int request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    fd = open(VIDEO_DEVICE, O_RDWR, 0);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto fail;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        goto fail;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", VIDEO_DEVICE);
        goto fail;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto fail;
    }

    CLEAR(req);
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto fail;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto fail;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            goto fail;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("mmap");
            goto fail;
        }
    }

    for (int i = 0; i < n_buffers; ++i) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            goto fail;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto fail;
    }

    return 0;

fail:
    if (fd >= 0) close(fd);
    fd = -1;
    return -1;
}

static void cleanup(void) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
    }

    for (int i = 0; i < n_buffers; ++i) {
        if (buffers[i].start != NULL && buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
        }
    }

    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
}

static int send_udp_packet(const char *data, size_t data_len, const char *ip, int port) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in addr;
    CLEAR(addr);
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid IP address: %s\n", ip);
        close(sock);
        return -1;
    }

    ssize_t sent = sendto(sock, data, data_len, 0, (struct sockaddr *)&addr, sizeof(addr));
    if (sent < 0) {
        perror("sendto");
        close(sock);
        return -1;
    }

    close(sock);
    return 0;
}

static int process_frame(const char *frame, size_t frame_len, const char *ip, int port) {
    if (frame_len <= MAX_FRAME_SIZE) {
        return send_udp_packet(frame, frame_len, ip, port);
    }

    int total_fragments = (frame_len + MAX_FRAME_SIZE - 1) / MAX_FRAME_SIZE;
    for (int i = 0; i < total_fragments; ++i) {
        size_t payload_size = (i == total_fragments - 1) ? (frame_len - i * MAX_FRAME_SIZE) : MAX_FRAME_SIZE;
        char *packet = malloc(MAX_FRAME_SIZE + 4);
        if (!packet) {
            perror("malloc");
            return -1;
        }

        uint32_t header = ((uint32_t)i << 24) | ((uint32_t)total_fragments << 16) | (uint32_t)payload_size;
        memcpy(packet, &header, 4);
        memcpy(packet + 4, frame + i * MAX_FRAME_SIZE, payload_size);

        int ret = send_udp_packet(packet, payload_size + 4, ip, port);
        free(packet);
        if (ret < 0) return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <target_ip> <target_port>\n", argv[0]);
        return 1;
    }

    const char *target_ip = argv[1];
    int target_port = atoi(argv[2]);

    if (target_port <= 0 || target_port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return 1;
    }

    struct sigaction sa;
    CLEAR(sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_camera() < 0) {
        fprintf(stderr, "Failed to initialize camera\n");
        return 1;
    }

    printf("Camera initialized. Streaming to %s:%d\n", target_ip, target_port);

    int frame_index = 0;
    while (!stop_flag) {
        struct v4l2_buffer buf;
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF");
            break;
        }

        if (buf.index >= n_buffers) {
            fprintf(stderr, "Invalid buffer index\n");
            break;
        }

        char *frame = (char *)buffers[buf.index].start;
        size_t frame_len = buf.bytesused;

        if (process_frame(frame, frame_len, target_ip, target_port) < 0) {
            fprintf(stderr, "Failed to send frame %d\n", frame_index);
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }

        frame_index++;
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

