#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define WIDTH 192
#define NUM_BUFFERS 4

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_mmap_contig mmap_contig;
    struct v4l2_buffer *buffers = NULL;
    unsigned char *buffer_data = NULL;
    size_t buffer_size = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    fd = open(DEVICE_NAME, O_RDWR, 0);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = 0;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.width != WIDTH) {
        fprintf(stderr, "Warning: driver did not accept %d as width, got %u\n",
                WIDTH, fmt.fmt.pix.width);
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", DEVICE_NAME);
        goto cleanup;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("calloc");
        goto cleanup;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }

        buffers[i].length = buf.length;
        buffers[i].index = buf.index;

        mmap_contig.offset = buf.m.planes[0].m.mem_offset;
        mmap_contig.length = buf.length;

        buffer_data = mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
                           MAP_SHARED, fd, mmap_contig.offset);
        if (buffer_data == MAP_FAILED) {
            perror("mmap");
            buffer_data = NULL;
            goto cleanup;
        }
        buffers[i].m.planes[0].length = buf.length;
        buffers[i].m.planes[0].m.mem_offset = mmap_contig.offset;
        buffers[i].m.planes[0].bytesused = 0;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("fopen(" IMAGE_FILE ")");
        goto cleanup;
    }

    while (!stop_flag) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            perror("select");
            goto cleanup;
        }
        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            goto cleanup;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF");
            goto cleanup;
        }

        if (buf.index >= req.count) {
            fprintf(stderr, "Invalid buffer index %u\n", buf.index);
            goto cleanup;
        }

        if (buf.bytesused == 0) {
            fprintf(stderr, "Warning: zero bytesused from buffer %u\n", buf.index);
        }

        if (fwrite(buffer_data, 1, buf.bytesused, fp) != buf.bytesused) {
            perror("fwrite");
            goto cleanup;
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }

        break;
    }

    if (stop_flag) {
        fprintf(stderr, "Interrupted by signal\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        for (unsigned int i = 0; i < req.count; i++) {
            if (buffers && buffers[i].m.planes[0].m.mem_offset != 0) {
                munmap((void *)buffers[i].m.planes[0].m.mem_offset,
                       buffers[i].length);
            }
        }
        free(buffers);
        close(fd);
        fd = -1;
    }
    return ret;
}

