static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned pin, unsigned pud) {
    if (gpioSetPullUpDown(pin, pud) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(%u, %u) failed\n", pin, pud);
        return -1;
    }
    return 0;
}

static int safe_set_pwm(unsigned pin, unsigned duty) {
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "gpioPWM(%u, %u) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (safe_set_mode(PAN_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(TILT_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(TILT_UP, PI_INPUT) < 0 ||
        safe_set_mode(TILT_DOWN, PI_INPUT) < 0 ||
        safe_set_mode(PAN_LEFT, PI_INPUT) < 0 ||
        safe_set_mode(PAN_RIGHT, PI_INPUT) < 0) {
        return -1;
    }

    if (safe_set_pull(TILT_UP, PI_PUD_UP) < 0 ||
        safe_set_pull(TILT_DOWN, PI_PUD_UP) < 0 ||
        safe_set_pull(PAN_LEFT, PI_PUD_UP) < 0 ||
        safe_set_pull(PAN_RIGHT, PI_PUD_UP) < 0) {
        return -1;
    }

    if (gpioSetPWMfrequency(PAN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(TILT_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        return -1;
    }

    if (gpioSetPWMrange(PAN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(TILT_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        return -1;
    }

    if (safe_set_pwm(PAN_PIN, MID_PULSE) < 0 ||
        safe_set_pwm(TILT_PIN, MID_PULSE) < 0) {
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    gpioPWM(PAN_PIN, 0);
    gpioPWM(TILT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int pan_pos  = MID_PULSE;
    int tilt_pos = MID_PULSE;

    while (g_running) {
        int up    = gpioRead(TILT_UP);
        int down  = gpioRead(TILT_DOWN);
        int left  = gpioRead(PAN_LEFT);
        int right = gpioRead(PAN_RIGHT);

        if (up == 0) {
            tilt_pos += STEP;
            if (tilt_pos > MAX_PULSE) tilt_pos = MAX_PULSE;
        } else if (down == 0) {
            tilt_pos -= STEP;
            if (tilt_pos < MIN_PULSE) tilt_pos = MIN_PULSE;
        }

        if (left == 0) {
            pan_pos -= STEP;
            if (pan_pos < MIN_PULSE) pan_pos = MIN_PULSE;
        } else if (right == 0) {
            pan_pos += STEP;
            if (pan_pos > MAX_PULSE) pan_pos = MAX_PULSE;
        }

        if (safe_set_pwm(PAN_PIN, pan_pos) < 0 ||
            safe_set_pwm(TILT_PIN, tilt_pos) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        usleep(POLL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

