#define CAMERA_DEVICE "/dev/video0"
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_FORMAT V4L2_PIX_FMT_YUYV
#define CAPTURE_TIMEOUT_SEC 2
#define JPEG_QUALITY 75

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < width * height; i++) {
        int y = yuyv[i * 2];
        int u = yuyv[i * 2 + 1];
        int v = yuyv[i * 2 + 3];
        int c = y - 16;
        int d = u - 128;
        int e = v - 128;
        int r = (298 * c + 409 * e + 128) >> 8;
        int g = (298 * c - 100 * d - 208 * e + 128) >> 8;
        int b = (298 * c + 516 * d + 128) >> 8;
        if (r < 0) r = 0; if (r > 255) r = 255;
        if (g < 0) g = 0; if (g > 255) g = 255;
        if (b < 0) b = 0; if (b > 255) b = 255;
        rgb[i * 3] = (unsigned char)r;
        rgb[i * 3 + 1] = (unsigned char)g;
        rgb[i * 3 + 2] = (unsigned char)b;
    }
}

static void blur_image(unsigned char *image, int width, int height) {
    unsigned char *temp = malloc((size_t)width * height * 3);
    if (!temp) { perror("malloc"); return; }
    memcpy(temp, image, (size_t)width * height * 3);
    for (int y = 1; y < height - 1; y++) {
        for (int x = 1; x < width - 1; x++) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            for (int dy = -1; dy <= 1; dy++) {
                for (int dx = -1; dx <= 1; dx++) {
                    int nx = x + dx, ny = y + dy;
                    sum_r += temp[(ny * width + nx) * 3];
                    sum_g += temp[(ny * width + nx) * 3 + 1];
                    sum_b += temp[(ny * width + nx) * 3 + 2];
                }
            }
            image[(y * width + x) * 3] = (unsigned char)(sum_r / 9);
            image[(y * width + x) * 3 + 1] = (unsigned char)(sum_g / 9);
            image[(y * width + x) * 3 + 2] = (unsigned char)(sum_b / 9);
        }
    }
    free(temp);
}

static int encode_jpeg(const char *filename, const unsigned char *image, int width, int height) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile = NULL;
    int rc = EXIT_FAILURE;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        perror("fopen");
        goto cleanup;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (JSAMPROW)&image[cinfo.next_scanline * width * 3];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    rc = EXIT_SUCCESS;

cleanup:
    if (outfile) fclose(outfile);
    jpeg_destroy_compress(&cinfo);
    return rc;
}

