/*
 * v4l2_cam_info.c — Summarise a CSI camera's V4L2 capabilities.
 *
 * Build:  gcc -O2 -Wall -Wextra -o v4l2_cam_info v4l2_cam_info.c
 * Run:    ./v4l2_cam_info /dev/video0
 */

#include <errno.h>
#include <fcntl.h>
#include <linux/videodev2.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>

#define DEVICE_NODE_PATH "/dev/video0"
#define FOCUS_AUTO_CTRL_ID V4L2_CID_FOCUS_AUTO

static void print_capabilities(const struct v4l2_capability *cap)
{
    printf("Driver : %s\n", cap->driver);
    printf("Card   : %s\n", cap->card);
    printf("Bus    : %s\n", cap->bus_info);
    printf("Version: %u.%u.%u\n",
           (cap->version >> 16) & 0xFF,
           (cap->version >> 8)  & 0xFF,
           cap->version         & 0xFF);
}

static void print_frame_size(const struct v4l2_frmsizeenum *fse)
{
    printf("  %ux%u", fse->width, fse->height);
    if (fse->type == V4L2_FRMSIZE_TYPE_DISCRETE)
        printf(" (discrete)");
    else if (fse->type == V4L2_FRMSIZE_TYPE_STEPWISE)
        printf(" (stepwise)");
    printf("\n");
}

static void print_frame_interval(const struct v4l2_frmivalenum *fie)
{
    printf("    %u/%u", fie->denominator, fie->numerator);
    if (fie->type == V4L2_FRMIVAL_TYPE_DISCRETE)
        printf(" (discrete)");
    else if (fie->type == V4L2_FRMIVAL_TYPE_STEPWISE)
        printf(" (stepwise)");
    printf("\n");
}

static int query_capabilities(int fd, struct v4l2_capability *cap)
{
    memset(cap, 0, sizeof(*cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int enumerate_frame_sizes(int fd, unsigned int pixel_format)
{
    struct v4l2_frmsizeenum fse;
    memset(&fse, 0, sizeof(fse));
    fse.pixel_format = pixel_format;

    printf("Supported frame sizes:\n");
    for (;;) {
        fse.index++;
        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fse) < 0) {
            if (errno == EINVAL)
                break;
            fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES (index %u) failed: %s\n",
                    fse.index, strerror(errno));
            return -1;
        }
        print_frame_size(&fse);
    }
    return 0;
}

static int enumerate_frame_intervals(int fd, unsigned int pixel_format,
                                     unsigned int width, unsigned int height)
{
    struct v4l2_frmivalenum fie;
    memset(&fie, 0, sizeof(fie));
    fie.pixel_format = pixel_format;
    fie.width        = width;
    fie.height       = height;

    printf("  Frame intervals:\n");
    for (;;) {
        fie.index++;
        if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fie) < 0) {
            if (errno == EINVAL)
                break;
            fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS (index %u) failed: %s\n",
                    fie.index, strerror(errno));
            return -1;
        }
        print_frame_interval(&fie);
    }
    return 0;
}

static int query_focus_auto(int fd, struct v4l2_queryctrl *qc)
{
    memset(qc, 0, sizeof(*qc));
    qc->id = FOCUS_AUTO_CTRL_ID;
    if (ioctl(fd, VIDIOC_QUERYCTRL, qc) < 0) {
        if (errno == EINVAL) {
            fprintf(stderr, "Focus autofocus control (%u) not supported.\n",
                    FOCUS_AUTO_CTRL_ID);
            return -1;
        }
        fprintf(stderr, "VIDIOC_QUERYCTRL(%u) failed: %s\n",
                FOCUS_AUTO_CTRL_ID, strerror(errno));
        return -1;
    }
    printf("Focus autofocus: %s\n",
           qc->flags & V4L2_CTRL_FLAG_DISABLED ? "disabled" : "enabled");
    return 0;
}

int main(void)
{
    int fd = open(DEVICE_NODE_PATH, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", DEVICE_NODE_PATH, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (query_capabilities(fd, &cap) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_READWRITE)) {
        fprintf(stderr, "Device does not support read/write I/O.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Camera summary for %s:\n", DEVICE_NODE_PATH);
    print_capabilities(&cap);

    if (enumerate_frame_sizes(fd, V4L2_PIX_FMT_JPEG) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_frmsizeenum fse;
    memset(&fse, 0, sizeof(fse));
    fse.pixel_format = V4L2_PIX_FMT_JPEG;
    for (;;) {
        fse.index++;
        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fse) < 0) {
            if (errno == EINVAL)
                break;
            fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES (index %u) failed: %s\n",
                    fse.index, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }
        if (fse.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            if (enumerate_frame_intervals(fd, V4L2_PIX_FMT_JPEG,
                                          fse.width, fse.height) < 0) {
                close(fd);
                return EXIT_FAILURE;
            }
        }
    }

    struct v4l2_queryctrl qc;
    if (query_focus_auto(fd, &qc) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (close(fd) < 0)
        fprintf(stderr, "Warning: close failed: %s\n", strerror(errno));

    return EXIT_SUCCESS;
}

