    return 0;
}

static int query_focus_auto(int fd, struct v4l2_queryctrl *qc)
{
    memset(qc, 0, sizeof(*qc));
    qc->id = FOCUS_AUTO_CTRL_ID;
    if (ioctl(fd, VIDIOC_QUERYCTRL, qc) < 0) {
        if (errno == EINVAL) {
            fprintf(stderr, "Focus autofocus control (%u) not supported.\n",
                    FOCUS_AUTO_CTRL_ID);
            return -1;
        }
        fprintf(stderr, "VIDIOC_QUERYCTRL(%u) failed: %s\n",
                FOCUS_AUTO_CTRL_ID, strerror(errno));
        return -1;
    }
    printf("Focus autofocus: %s\n",
           qc->flags & V4L2_CTRL_FLAG_DISABLED ? "disabled" : "enabled");
    return 0;
}

int main(void)
{
    int fd = open(DEVICE_NODE_PATH, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", DEVICE_NODE_PATH, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (query_capabilities(fd, &cap) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_READWRITE)) {
        fprintf(stderr, "Device does not support read/write I/O.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Camera summary for %s:\n", DEVICE_NODE_PATH);
    print_capabilities(&cap);

    if (enumerate_frame_sizes(fd, V4L2_PIX_FMT_JPEG) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_frmsizeenum fse;
    memset(&fse, 0, sizeof(fse));
    fse.pixel_format = V4L2_PIX_FMT_JPEG;
    for (;;) {
        fse.index++;
        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fse) < 0) {
            if (errno == EINVAL)
                break;
            fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES (index %u) failed: %s\n",
                    fse.index, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }
        if (fse.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            if (enumerate_frame_intervals(fd, V4L2_PIX_FMT_JPEG,
                                          fse.width, fse.height) < 0) {
                close(fd);
                return EXIT_FAILURE;
            }
        }
    }

    struct v4l2_queryctrl qc;
    if (query_focus_auto(fd, &qc) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (close(fd) < 0)
        fprintf(stderr, "Warning: close failed: %s\n", strerror(errno));

    return EXIT_SUCCESS;
}

