#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE  1000
#define SERVO_MAX_PULSE  2000
#define SERVO_CENTER     1500
#define SERVO_STEP       10
#define LOOP_DELAY_US    50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_set_servo_pulsewidth(int pin, int pulsewidth) {
    if (pulsewidth < SERVO_MIN_PULSE) pulsewidth = SERVO_MIN_PULSE;
    if (pulsewidth > SERVO_MAX_PULSE) pulsewidth = SERVO_MAX_PULSE;
    return gpioServo(pin, pulsewidth);
}

int main(void) {
    int pan_pw  = SERVO_CENTER;
    int tilt_pw = SERVO_CENTER;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set button pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up resistors.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_servo_pulsewidth(PAN_SERVO_PIN, pan_pw) != 0 ||
        safe_set_servo_pulsewidth(TILT_SERVO_PIN, tilt_pw) != 0) {
        fprintf(stderr, "Error: failed to initialize servo pulsewidths.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Mount Control\n");
    printf("Pan servo: GPIO%d | Tilt servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Up: GPIO%d | Down: GPIO%d | Left: GPIO%d | Right: GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Center position: %d us\n", SERVO_CENTER);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpioRead(UP_BUTTON_PIN) == 0) {
            pan_pw += SERVO_STEP;
            safe_set_servo_pulsewidth(PAN_SERVO_PIN, pan_pw);
        }
        if (gpioRead(DOWN_BUTTON_PIN) == 0) {
            pan_pw -= SERVO_STEP;
            safe_set_servo_pulsewidth(PAN_SERVO_PIN, pan_pw);
        }
        if (gpioRead(LEFT_BUTTON_PIN) == 0) {
            tilt_pw += SERVO_STEP;
            safe_set_servo_pulsewidth(TILT_SERVO_PIN, tilt_pw);
        }
        if (gpioRead(RIGHT_BUTTON_PIN) == 0) {
            tilt_pw -= SERVO_STEP;
            safe_set_servo_pulsewidth(TILT_SERVO_PIN, tilt_pw);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

