#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <pigpio.h>
#include <jpeglib.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define JPEG_QUALITY 85
#define CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LEN 256
#define MAX_JSON_LEN 512
#define MAX_IMAGE_SIZE 65536

static volatile sig_atomic_t running = 1;
static int http_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_dir(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_jpeg(const char *filename, unsigned char **out_data, size_t *out_len) {
    int fd = open("/dev/fb0", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/fb0: %s\n", strerror(errno));
        return -1;
    }
    struct stat st;
    if (fstat(fd, &st) != 0) {
        fprintf(stderr, "Error fstat /dev/fb0: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    size_t fb_size = (size_t)st.st_size;
    unsigned char *fb_data = malloc(fb_size);
    if (!fb_data) {
        fprintf(stderr, "Error allocating %zu bytes for framebuffer\n", fb_size);
        close(fd);
        return -1;
    }
    if (read(fd, fb_data, fb_size) != (ssize_t)fb_size) {
        fprintf(stderr, "Error reading framebuffer: %s\n", strerror(errno));
        free(fb_data);
        close(fd);
        return -1;
    }
    close(fd);

    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_mem_dest(&cinfo, out_data, out_len);
    cinfo.image_width = 1280;
    cinfo.image_height = 720;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);
    JSAMPROW row[1];
    for (int i = 0; i < 720; i++) {
        row[0] = fb_data + (size_t)i * 1280 * 3;
        jpeg_write_scanlines(&cinfo, row, 1);
    }
    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    free(fb_data);
    return 0;
}

static int save_jpeg(const char *filename, const unsigned char *data, size_t len) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening '%s' for writing: %s\n", filename, strerror(errno));
        return -1;
    }
    if (fwrite(data, 1, len, fp) != len) {
        fprintf(stderr, "Error writing '%s': %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int build_json(const char *filename, const char *timestamp, int motion, int gpio, char *out, size_t out_len) {
    int ret = snprintf(out, out_len,
        "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion\": %d, \"gpio\": %d}",
        filename, timestamp, motion, gpio);
    if (ret < 0 || (size_t)ret >= out_len) {
        fprintf(stderr, "Error building JSON string\n");
        return -1;
    }
    return 0;
}

static size_t write_cb(void *contents, size_t size, size_t nmemb, void *userp) {
    (void)contents; (void)userp;
    return size * nmemb;
}

static int send_http(const char *json, const unsigned char *image, size_t image_len, const char *ip, int port) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error initializing libcurl\n");
        return -1;
    }
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error creating HTTP headers\n");
        curl_easy_cleanup(curl);
        return -1;
    }
    curl_easy_setopt(curl, CURLOPT_URL, "http://<IP>:<port>/upload");
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_cb);
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    if (http_code != 200) {
        fprintf(stderr, "HTTP request returned non-200 status: %ld\n", http_code);
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        return 1;
    }
    const char *ip = argv[1];
    int port = atoi(argv[2]);
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return 1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);
    if (ensure_dir(CAPTURE_DIR) != 0) {
        gpioTerminate();
        return 1;
    }
    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "curl_global_init() failed\n");
        gpioTerminate();
        return 1;
    }
    http_initialized = 1;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting signal handlers: %s\n", strerror(errno));
        curl_global_cleanup();
        gpioTerminate();
        return 1;
    }
    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);
    int last_state = 0;
    int debounce_count = 0;
    while (running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", PIR_GPIO);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (current_state != last_state) {
            last_state = current_state;
            debounce_count = 0;
        } else if (current_state == 1 && debounce_count == 0) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];
            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            char filename[MAX_FILENAME_LEN];
            snprintf(filename, sizeof(filename), "%s/%s.%06ld.jpg", CAPTURE_DIR, timestamp, ts.tv_nsec / 1000);
            unsigned char *image_data = NULL;
            size_t image_len = 0;
            if (capture_jpeg(filename, &image_data, &image_len) != 0) {
                fprintf(stderr, "Error capturing JPEG\n");
            } else {
                if (save_jpeg(filename, image_data, image_len) != 0) {
                    fprintf(stderr, "Error saving JPEG\n");
                }
                free(image_data);
                char json_str[MAX_JSON_LEN];
                if (build_json(filename, timestamp, 1, PIR_GPIO, json_str, sizeof(json_str)) == 0) {
                    if (send_http(json_str, image_data, image_len, ip, port) != 0) {
                        fprintf(stderr, "Error sending HTTP request\n");
                    }
                }
            }
            debounce_count = DEBOUNCE_SEC;
        }
        if (debounce_count > 0) {
            gpioDelay(1000000);
            debounce_count--;
        } else {
            gpioDelay(POLL_INTERVAL_US);
        }
    }
    printf("\nShutting down...\n");
    curl_global_cleanup();
    gpioTerminate();
    return 0;
}

