#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <poll.h>
#include <gpiod.h>

#define PIR_PIN 17
#define DEBOUNCE_MS 50
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGE_DIR "/home/pi/images"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    fclose(fp);
}

static void capture_image(void) {
    time_t rawtime;
    struct tm timeinfo;
    char filename[128];
    char command[512];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        log_message("localtime_r failed");
        return;
    }

    if (strftime(filename, sizeof(filename),
                 IMAGE_DIR "/%Y%m%d_%H%M%S_%3N.jpg", &timeinfo) == 0) {
        log_message("strftime failed");
        return;
    }

    snprintf(command, sizeof(command),
             "raspistill -o %s --width 640 --height 480 -q 85 "
             "--timeout 2000 --nopreview", filename);

    int status = system(command);
    if (status == -1) {
        log_message("system() failed to launch raspistill");
        return;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        char msg[256];
        snprintf(msg, sizeof(msg),
                 "raspistill failed with status %d", status);
        log_message(msg);
        return;
    }

    char msg[256];
    snprintf(msg, sizeof(msg), "Image captured: %s", filename);
    log_message(msg);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        log_message("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        log_message("Failed to get GPIO17 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "pir-motion") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        log_message("Failed to request falling edge events on GPIO17");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_message("Motion detection service started");

    while (running) {
        struct pollfd pfd;
        pfd.fd = gpiod_line_event_get_fd(pir_line);
        pfd.events = POLLIN;
        pfd.revents = 0;

        int pr = poll(&pfd, 1, POLL_TIMEOUT_MS);
        if (pr < 0) {
            if (errno == EINTR) continue;
            perror("poll");
            log_message("poll error");
            break;
        }
        if (pr == 0) {
            continue;
        }
        if (pfd.revents & (POLLERR | POLLNVAL)) {
            log_message("poll error event");
            continue;
        }
        if (pfd.revents & POLLIN) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(pir_line, &event) < 0) {
                perror("gpiod_line_event_read");
                log_message("Failed to read event");
                continue;
            }
            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                capture_image();
                usleep(DEBOUNCE_MS * 1000);
            }
        }
    }

    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    log_message("Motion detection service stopped");
    return EXIT_SUCCESS;
}

