static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    void *buffer = MAP_FAILED;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        goto cleanup;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        goto cleanup;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    int rv;
    for (;;) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = TIMEOUT_SEC;
        tv.tv_usec = 0;
        rv = select(fd + 1, &fds, NULL, NULL, &tv);
        if (rv == -1) {
            if (errno == EINTR) continue;
            perror("select");
            goto cleanup;
        }
        if (rv == 0) {
            fprintf(stderr, "select timeout\n");
            goto cleanup;
        }
        if (stop_flag) {
            fprintf(stderr, "Interrupted by signal\n");
            goto cleanup;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("VIDIOC_DQBUF");
            goto cleanup;
        }

        if (buf.bytesused < (unsigned int)(fmt.fmt.pix.width * fmt.fmt.pix.height * 2)) {
            fprintf(stderr, "Short frame: %u bytes, expected %d\n",
                    buf.bytesused, fmt.fmt.pix.width * fmt.fmt.pix.height * 2);
            goto cleanup;
        }
        if (buf.bytesused > (unsigned int)(fmt.fmt.pix.width * fmt.fmt.pix.height * 2)) {
            fprintf(stderr, "Frame too large: %u bytes, expected %d\n",
                    buf.bytesused, fmt.fmt.pix.width * fmt.fmt.pix.height * 2);
            goto cleanup;
        }

        fp = fopen(OUTPUT_FILE, "wb");
        if (!fp) {
            perror("fopen(" OUTPUT_FILE ")");
            goto cleanup;
        }

        size_t to_write = (size_t)buf.bytesused;
        size_t written = fwrite(buffer, 1, to_write, fp);
        if (written != to_write) {
            perror("fwrite");
            fclose(fp);
            fp = NULL;
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            perror("fflush");
            fclose(fp);
            fp = NULL;
            goto cleanup;
        }
        if (fclose(fp) != 0) {
            perror("fclose");
            fp = NULL;
            goto cleanup;
        }
        fp = NULL;

        printf("Captured %u bytes, writing to %s\n", buf.bytesused, OUTPUT_FILE);

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd != -1) {
        enum v4l2_buf_type t = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &t);
    }
    if (buffer != MAP_FAILED && buffer != NULL) {
        munmap(buffer, 4096);
    }
    if (fp) {
        fclose(fp);
    }
    if (fd != -1) {
        close(fd);
    }
    return ret;
}

