#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  17
#define TILT_SERVO_PIN 18
#define PWM_FREQUENCY  50
#define NEUTRAL_ANGLE  90
#define MIN_ANGLE      0
#define MAX_ANGLE      180
#define STEP_SIZE      5
#define DELAY_MS       100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int angle_to_pwm(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range (%d-%d).\n",
                angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return (angle * 2000 / 180) + 500;
}

static int set_servo_angle(int pin, int angle) {
    int pwm = angle_to_pwm(angle);
    if (pwm < 0) return -1;
    if (gpioServo(pin, pwm) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed.\n", pin, pwm);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE) < 0 ||
        set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE) < 0) {
        cleanup();
        return 1;
    }

    printf("Pan/Tilt Servo Control (PWM %d Hz)\n", PWM_FREQUENCY);
    printf("Arrow keys: Pan left/right, Tilt up/down. 'q' to quit.\n");

    int pan_angle  = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    while (g_running) {
        int c = getchar();
        if (c == 'q' || c == 'Q') break;

        int new_pan  = pan_angle;
        int new_tilt = tilt_angle;

        switch (c) {
            case 'a': case 'A': new_pan -= STEP_SIZE; break;
            case 'd': case 'D': new_pan += STEP_SIZE; break;
            case 'w': case 'W': new_tilt += STEP_SIZE; break;
            case 's': case 'S': new_tilt -= STEP_SIZE; break;
            default: continue;
        }

        if (new_pan < MIN_ANGLE || new_pan > MAX_ANGLE) new_pan = pan_angle;
        if (new_tilt < MIN_ANGLE || new_tilt > MAX_ANGLE) new_tilt = tilt_angle;

        if (set_servo_angle(PAN_SERVO_PIN, new_pan) < 0 ||
            set_servo_angle(TILT_SERVO_PIN, new_tilt) < 0) {
            fprintf(stderr, "Error: PWM write failed; aborting.\n");
            break;
        }

        pan_angle  = new_pan;
        tilt_angle = new_tilt;
        printf("Pan: %3d  Tilt: %3d\n", pan_angle, tilt_angle);

        gpioDelay(DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

