#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SSD1306_I2C_ADDR 0x3C

#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64
#define SSD1306_PAGES (SSD1306_HEIGHT / 8)

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define CPU_USAGE_FILE "/proc/stat"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char reg, unsigned char data) {
    unsigned char buf[2] = {reg, data};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int ssd1306_command(int fd, unsigned char cmd) {
    return i2c_write_byte(fd, 0x00, cmd);
}

static int ssd1306_data(int fd, unsigned char data) {
    return i2c_write_byte(fd, 0x40, data);
}

static int ssd1306_init(int fd) {
    if (ssd1306_command(fd, 0xAE) < 0) return -1;
    if (ssd1306_command(fd, 0xD5) < 0) return -1;
    if (ssd1306_command(fd, 0x80) < 0) return -1;
    if (ssd1306_command(fd, 0xA8) < 0) return -1;
    if (ssd1306_command(fd, 0x3F) < 0) return -1;
    if (ssd1306_command(fd, 0xD3) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0x40) < 0) return -1;
    if (ssd1306_command(fd, 0x8D) < 0) return -1;
    if (ssd1306_command(fd, 0x14) < 0) return -1;
    if (ssd1306_command(fd, 0xA1) < 0) return -1;
    if (ssd1306_command(fd, 0xC8) < 0) return -1;
    if (ssd1306_command(fd, 0xDA) < 0) return -1;
    if (ssd1306_command(fd, 0x12) < 0) return -1;
    if (ssd1306_command(fd, 0x81) < 0) return -1;
    if (ssd1306_command(fd, 0xCF) < 0) return -1;
    if (ssd1306_command(fd, 0xD9) < 0) return -1;
    if (ssd1306_command(fd, 0xF1) < 0) return -1;
    if (ssd1306_command(fd, 0xDB) < 0) return -1;
    if (ssd1306_command(fd, 0x40) < 0) return -1;
    if (ssd1306_command(fd, 0xA4) < 0) return -1;
    if (ssd1306_command(fd, 0xA6) < 0) return -1;
    if (ssd1306_command(fd, 0xAF) < 0) return -1;
    return 0;
}

static void ssd1306_clear(int fd) {
    for (int page = 0; page < SSD1306_PAGES; page++) {
        ssd1306_command(fd, 0xB0 + page);
        ssd1306_command(fd, 0x00);
        ssd1306_command(fd, 0x10);
        for (int col = 0; col < SSD1306_WIDTH; col++) {
            ssd1306_data(fd, 0x00);
        }
    }
}

static void ssd1306_draw_string(int fd, int x, int y, const char *str) {
    if (x < 0 || x >= SSD1306_WIDTH || y < 0 || y >= SSD1306_HEIGHT) return;
    int page = y / 8;
    int col_start = x;
    ssd1306_command(fd, 0xB0 + page);
    ssd1306_command(fd, 0x00 + (x & 0x0F));
    ssd1306_command(fd, 0x10 + ((x >> 4) & 0x0F));
    for (int i = 0; str[i] != '\0'; i++) {
        unsigned char c = (unsigned char)str[i];
        if (c < 32 || c > 126) c = ' ';
        c -= 32;
        for (int j = 0; j < 5; j++) {
            unsigned char byte = font5x7[c * 5 + j];
            ssd1306_data(fd, byte);
        }
        ssd1306_data(fd, 0x00);
    }
}

static int read_cpu_temp(float *temp) {
    FILE *fp = fopen(CPU_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open CPU temperature file: %s\n", strerror(errno));
        return -1;
    }
    int raw;
    if (fscanf(fp, "%d", &raw) != 1) {
        fprintf(stderr, "Failed to parse CPU temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp = (float)raw / 1000.0f;
    return 0;
}

static int read_cpu_usage(float *usage) {
    FILE *fp = fopen(CPU_USAGE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open CPU usage file: %s\n", strerror(errno));
        return -1;
    }
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Failed to parse CPU usage\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    static unsigned long long prev_user = 0, prev_nice = 0, prev_system = 0, prev_idle = 0, prev_iowait = 0, prev_irq = 0, prev_softirq = 0, prev_steal = 0, prev_guest = 0, prev_guest_nice = 0;
    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long diff_idle = idle - prev_idle;
    unsigned long long diff_total = total - prev_total;
    if (diff_total == 0) {
        *usage = 0.0f;
    } else {
        *usage = (float)(diff_total - diff_idle) / (float)diff_total * 100.0f;
    }
    prev_user = user; prev_nice = nice; prev_system = system; prev_idle = idle; prev_iowait = iowait; prev_irq = irq; prev_softirq = softirq; prev_steal = steal; prev_guest = guest; prev_guest_nice = guest_nice;
    return 0;
}

