#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define FLOW_RATE_INTERVAL 1
#define LCD_UPDATE_INTERVAL 10

#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_FUNCTIONSET 0x20
#define LCD_SETDDRAMADDR 0x80
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTDECREMENT 0x00
#define LCD_DISPLAYON 0x04
#define LCD_CURSOROFF 0x00
#define LCD_BLINKOFF 0x00
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_5x8DOTS 0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_send_nibble(uint8_t nibble) {
    uint8_t data[4];
    data[0] = nibble | (1 << 3);
    data[1] = nibble | (1 << 3);
    data[2] = nibble | (1 << 3);
    data[3] = nibble | (1 << 3);
    if (i2cWriteDevice(i2c_handle, (char *)data, 4) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
    }
    gpioDelay(1000);
}

static void lcd_send_byte(uint8_t val, uint8_t mode) {
    uint8_t high = (val & 0xF0) | mode;
    uint8_t low = ((val << 4) & 0xF0) | mode;
    lcd_send_nibble(high);
    lcd_send_nibble(low);
}

static void lcd_command(uint8_t cmd) {
    lcd_send_byte(cmd, 0);
}

static void lcd_data(uint8_t data) {
    lcd_send_byte(data, 1);
}

static void lcd_init(void) {
    gpioDelay(50000);
    lcd_send_nibble(0x30);
    gpioDelay(5000);
    lcd_send_nibble(0x30);
    gpioDelay(150);
    lcd_send_nibble(0x30);
    gpioDelay(150);
    lcd_send_nibble(0x20);
    gpioDelay(150);
    lcd_command(LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS);
    lcd_command(LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF);
    lcd_command(LCD_CLEARDISPLAY);
    gpioDelay(2000);
    lcd_command(LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT);
}

static void lcd_clear(void) {
    lcd_command(LCD_CLEARDISPLAY);
    gpioDelay(2000);
}

static void lcd_set_cursor(uint8_t col, uint8_t row) {
    uint8_t addr = (row == 0) ? 0x00 : 0x40;
    lcd_command(LCD_SETDDRAMADDR | (col + addr));
}

static void lcd_print(const char *str) {
    while (*str) {
