#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define ANEMOMETER_GPIO 17
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define LCD_ADDR 0x27
#define SAMPLE_WINDOW_MS 500
#define SAMPLE_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static int spi_fd = -1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LCD_ADDR, strerror(errno));
        close(i2c_fd); i2c_fd = -1; return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int lcd_write_byte(uint8_t data, uint8_t rs) {
    uint8_t upper = data & 0xF0;
    uint8_t lower = (data << 4) & 0xF0;
    uint8_t en = 0x04;
    uint8_t data_buf[4] = {upper | en | rs, upper | en, lower | en | rs, lower | en};
    for (int i = 0; i < 4; i++) {
        if (write(i2c_fd, &data_buf[i], 1) != 1) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            return -1;
        }
        usleep(1);
    }
    usleep(100);
    return 0;
}

static int lcd_send_command(uint8_t cmd) {
    return lcd_write_byte(cmd, 0);
}

static int lcd_send_data(uint8_t data) {
    return lcd_write_byte(data, 1);
}

static int lcd_init(void) {
    usleep(50000);
    if (lcd_send_command(0x33) < 0) return -1;
    usleep(5000);
    if (lcd_send_command(0x32) < 0) return -1;
    usleep(5000);
    if (lcd_send_command(0x28) < 0) return -1;
    if (lcd_send_command(0x0C) < 0) return -1;
    if (lcd_send_command(0x06) < 0) return -1;
    if (lcd_send_command(0x01) < 0) return -1;
    usleep(2000);
    return 0;
}

static void lcd_clear(void) {
    lcd_send_command(0x01);
    usleep(2000);
}

static void lcd_set_cursor(int row, int col) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_command(addr);
}

static void lcd_print(const char *str) {
    while (*str) {
        if (lcd_send_data((uint8_t)*str++) < 0) break;
    }
}

static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pulse_count++;
}

static double calculate_wind_speed(int pulses, int duration_ms) {
    if (duration_ms <= 0) return 0.0;
    double frequency = (double)pulses / (duration_ms / 1000.0);
    return frequency * 2.0 * 3.14159265358979323846;
}

static int read_wind_direction(void) {
    int adc = read_mcp3008(0);
    if (adc < 0) return -1;
    if (adc == 0 || adc == 1023) {
        fprintf(stderr, "Warning: ADC reading at rail (%d) - sensor absent or wiring fault\n", adc);
        return -1;
    }
    if (adc < 512) return 0;
    if (adc < 768) return 45;
    if (adc < 1023) return 90;
    return -1;
}

static void display_data(double speed, int direction) {
    char line1[20], line2[20];
    lcd_clear();
    snprintf(line1, sizeof(line1), "Speed: %.2f m/s", speed);
    snprintf(line2, sizeof(line2), "Dir: %d deg", direction);
    lcd_set_cursor(0, 0);
    lcd_print(line1);
    lcd_set_cursor(1, 0);
    lcd_print(line2);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) return 1;
    if (i2c_init() < 0) { close(spi_fd); spi_fd = -1; return 1; }
    if (lcd_init() < 0) { close(spi_fd); spi_fd = -1; close(i2c_fd); i2c_fd = -1; return 1; }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        close(spi_fd); spi_fd = -1; close(i2c_fd); i2c_fd = -1;
        return 1;
    }

    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        close(spi_fd); spi_fd = -1; close(i2c_fd); i2c_fd = -1;
        return 1;
    }

    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        close(spi_fd); spi_fd = -1; close(i2c_fd); i2c_fd = -1;
        return 1;
    }

    while (running) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        int pulses = pulse_count;
        pulse_count = 0;
        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_ms = (end.tv_sec - start.tv_sec) * 1000L + (end.tv_nsec - start.tv_nsec) / 1000000L;

        double speed = calculate_wind_speed(pulses, elapsed_ms);
        int direction = read_wind_direction();

        if (direction < 0) {
            fprintf(stderr, "Error reading wind direction\n");
        } else {
            display_data(speed, direction);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

