    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) return 1;
    if (i2c_init() < 0) { close(spi_fd); spi_fd = -1; return 1; }
    if (lcd_init() < 0) { close(spi_fd); spi_fd = -1; close(i2c_fd); i2c_fd = -1; return 1; }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        close(spi_fd); spi_fd = -1; close(i2c_fd); i2c_fd = -1;
        return 1;
    }

    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        close(spi_fd); spi_fd = -1; close(i2c_fd); i2c_fd = -1;
        return 1;
    }

    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        close(spi_fd); spi_fd = -1; close(i2c_fd); i2c_fd = -1;
        return 1;
    }

    while (running) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        int pulses = pulse_count;
        pulse_count = 0;
        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_ms = (end.tv_sec - start.tv_sec) * 1000L + (end.tv_nsec - start.tv_nsec) / 1000000L;

        double speed = calculate_wind_speed(pulses, elapsed_ms);
        int direction = read_wind_direction();

        if (direction < 0) {
            fprintf(stderr, "Error reading wind direction\n");
        } else {
            display_data(speed, direction);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

