#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define PULSES_PER_LITER 40.0
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_strobe(int handle, unsigned char data) {
    if (i2cWriteByte(handle, data) < 0) {
        fprintf(stderr, "Error: I2C write failed in strobe\n");
    }
    gpioDelay(1);
}

static void lcd_byte(int handle, unsigned char bits, int mode) {
    unsigned char high = mode | (bits & 0xF0) | (bits & 0x0F);
    unsigned char low = mode | ((bits << 4) & 0xF0) | ((bits >> 4) & 0x0F);

    lcd_strobe(handle, high);
    lcd_strobe(handle, high | 0x08);
    lcd_strobe(handle, low);
    lcd_strobe(handle, low | 0x08);
}

static void lcd_command(int handle, unsigned char cmd) {
    lcd_byte(handle, cmd, 0);
}

static void lcd_data(int handle, unsigned char data) {
    lcd_byte(handle, data, 1);
}

static void lcd_init(int handle) {
    lcd_byte(handle, 0x33, 0);
    lcd_byte(handle, 0x32, 0);
    lcd_command(handle, 0x28);
    lcd_command(handle, 0x0C);
    lcd_command(handle, 0x06);
    lcd_command(handle, 0x01);
    gpioDelay(2000);
}

static void lcd_clear(int handle) {
    lcd_command(handle, 0x01);
    gpioDelay(2000);
}

static void lcd_set_cursor(int handle, int row, int col) {
    unsigned char addr = (row == 0) ? 0x80 : 0xC0;
    lcd_command(handle, addr + col);
}

static void lcd_print(int handle, const char *str) {
    while (*str) {
        lcd_data(handle, (unsigned char)*str++);
    }
}

static void lcd_print_float(int handle, float value, int decimals) {
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "%.*f", decimals, value);
    lcd_print(handle, buffer);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        lcd_clear(i2c_handle);
        lcd_set_cursor(i2c_handle, 0, 0);
        lcd_print(i2c_handle, "Shutting down...");
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, LCD_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init(i2c_handle);
    lcd_clear(i2c_handle);

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, NULL) != 0) {
        fprintf(stderr, "Error: Failed to clear alert on GPIO%d\n", FLOW_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert on GPIO%d\n", FLOW_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int pulses = 0;
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        while (running) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
            if (elapsed >= SAMPLE_INTERVAL_SEC) break;
            pulses++;
        }

        if (!running) break;

        float flow_rate = (pulses / PULSES_PER_LITER) * 60.0;

        lcd_clear(i2c_handle);
        lcd_set_cursor(i2c_handle, 0, 0);
        lcd_print(i2c_handle, "Flow Rate:");
        lcd_set_cursor(i2c_handle, 1, 0);
        lcd_print_float(i2c_handle, flow_rate, 2);
        lcd_print(i2c_handle, " L/min");

        printf("Flow Rate: %.2f L/min (%d pulses)\n", flow_rate, pulses);

        if (pulses == 0) {
            fprintf(stderr, "Warning: No pulses detected for %d seconds. Sensor may be absent or disconnected.\n", SAMPLE_INTERVAL_SEC);
        }
    }

    cleanup();
    printf("Water flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

