#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DELAY_US 800

/* BCM pin numbers for row anodes (common anode, HIGH = on) */
static const int row_pins[] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int num_rows = sizeof(row_pins) / sizeof(row_pins[0]);

/* BCM pin numbers for column cathodes (common anode, LOW = on) */
static const int col_pins[] = {5, 6, 12, 13, 19, 16, 26, 20};
static const int num_cols = sizeof(col_pins) / sizeof(col_pins[0]);

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < num_rows; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set row pin %d as output.\n", row_pins[i]);
            return -1;
        }
        if (gpioWrite(row_pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise row pin %d LOW.\n", row_pins[i]);
            return -1;
        }
    }

    for (int i = 0; i < num_cols; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set column pin %d as output.\n", col_pins[i]);
            return -1;
        }
        if (gpioWrite(col_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialise column pin %d HIGH.\n", col_pins[i]);
            return -1;
        }
    }

    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 0);
    }
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 1);
    }
}

static void display_frame(const int frame[num_rows][num_cols]) {
    for (int row = 0; row < num_rows; row++) {
        gpioWrite(row_pins[row], 1); /* anode HIGH = on */
        for (int col = 0; col < num_cols; col++) {
            gpioWrite(col_pins[col], !frame[row][col]); /* cathode LOW = on (common anode) */
        }
        gpioDelay(DELAY_US);
        gpioWrite(row_pins[row], 0); /* turn off row */
        for (int col = 0; col < num_cols; col++) {
            gpioWrite(col_pins[col], 1); /* turn off column */
        }
    }
}

static void wave_left_to_right(int frame[num_rows][num_cols]) {
    for (int i = 0; i < num_cols; i++) {
        for (int row = 0; row < num_rows; row++) {
            frame[row][i] = 1;
        }
        display_frame(frame);
        for (int row = 0; row < num_rows; row++) {
            frame[row][i] = 0;
        }
    }
}

static void wave_right_to_left(int frame[num_rows][num_cols]) {
    for (int i = num_cols - 1; i >= 0; i--) {
        for (int row = 0; row < num_rows; row++) {
            frame[row][i] = 1;
        }
        display_frame(frame);
        for (int row = 0; row < num_rows; row++) {
            frame[row][i] = 0;
        }
    }
}

static void cleanup(void) {
    clear_matrix();
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int frame[num_rows][num_cols] = {0};

    while (running) {
        wave_left_to_right(frame);
        if (!running) break;
        wave_right_to_left(frame);
    }

    cleanup();
    return EXIT_SUCCESS;
}

