#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define DELAY_MS 150

/* BCM pin numbers for the 8x8 LED matrix */
static const unsigned int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};
static const int num_pins = 8;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[8];
static struct gpiod_line *col_lines[8];
static volatile sig_atomic_t keep_running = 1;

static void cleanup_resources(void)
{
    for (int i = 0; i < num_pins; i++) {
        if (row_lines[i])
            gpiod_line_release(row_lines[i]);
        if (col_lines[i])
            gpiod_line_release(col_lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
}

static void signal_handler(int sig)
{
    (void)sig;
    keep_running = 0;
}

static int set_all_rows_low(void)
{
    for (int i = 0; i < num_pins; i++) {
        if (gpiod_line_set_value(row_lines[i], 0) < 0) {
            fprintf(stderr, "Failed to set row line %u LOW\n", row_pins[i]);
            return -1;
        }
    }
    return 0;
}

static int set_all_cols_high(void)
{
    for (int i = 0; i < num_pins; i++) {
        if (gpiod_line_set_value(col_lines[i], 1) < 0) {
            fprintf(stderr, "Failed to set col line %u HIGH\n", col_pins[i]);
            return -1;
        }
    }
    return 0;
}

