{
    if (gpiod_line_set_value(col_lines[col], 0) < 0) {
        fprintf(stderr, "Failed to set col line %u LOW\n", col_pins[col]);
        return -1;
    }
    for (int row = 0; row < num_pins; row++) {
        if (gpiod_line_set_value(row_lines[row], 1) < 0) {
            fprintf(stderr, "Failed to set row line %u HIGH\n", row_pins[row]);
            return -1;
        }
    }
    return 0;
}

static int clear_column(int col)
{
    if (gpiod_line_set_value(col_lines[col], 1) < 0) {
        fprintf(stderr, "Failed to set col line %u HIGH\n", col_pins[col]);
        return -1;
    }
    for (int row = 0; row < num_pins; row++) {
        if (gpiod_line_set_value(row_lines[row], 0) < 0) {
            fprintf(stderr, "Failed to set row line %u LOW\n", row_pins[row]);
            return -1;
        }
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
