/*
 * VL53L3CX Multi-Target Time-of-Flight Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 *
 * NOTE: The VL53L3CX is a complex sensor with proprietary firmware.
 * This program stubs the proprietary initialization sequence and
 * demonstrates the I2C read/write primitives.  A full implementation
 * would require a deep understanding of the VL53L3CX datasheet and
 * the STMicroelectronics VL53L3CX API.  This stubs the proprietary
 * firmware download and provides a minimal I2C read loop.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l3cx vl53l3cx.c -lpigpio -lrt
 * Run:    sudo ./vl53l3cx
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Constants ----------------------------- */

#define I2C_BUS              1
#define VL53L3CX_ADDR        0x29          /* Default I2C address (ADDR pin low) */
#define POLL_DELAY_US        100000        /* 100 ms between readings */
#define MAX_TARGETS          4
#define MAX_RANGE_MM         10000         /* 10 m max range */

/*
 * VL53L3CX register addresses (16-bit, big-endian on the bus).
 * The STMicroelectronics VL53L3CX API is a complex proprietary
 * protocol that requires a proprietary firmware download.  This
 * program stubs the proprietary initialization sequence and
 * demonstrates the I2C read/write primitives.  A full implementation
 * would require a deep understanding of the VL53L3CX datasheet
 * and the STMicroelectronics VL53L3CX API.
 */
#define REG_MODEL_ID         0x010F
#define REG_SOFT_RESET       0x0000
#define REG_SYSTEM_START     0x0001
#define REG_RESULT_RANGE_0   0x0014
#define REG_RESULT_RANGE_1   0x0016
#define REG_RESULT_RANGE_2   0x0018
#define REG_RESULT_RANGE_3   0x001A

#define EXPECTED_MODEL_ID    0xEA

/* --------------------------- Global State ---------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------- Signal Handling --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------- Timestamp Helper -------------------------- */

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

/* ------------------------- I2C Helpers ------------------------------- */

/*
 * Write a 16-bit register address, then a 16-bit big-endian value.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Write a 16-bit register address, then read back 2 bytes.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr_buf[2];
    char data_buf[2];

    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write (addr) for reg 0x%04X failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C read for reg 0x%04X failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------- Sensor Initialization ---------------------- */

/*
 * Stub:  The VL53L3CX requires a proprietary firmware download and
 * complex initialization sequence.  This program stubs the required
 * I2C communication and demonstrates the I2C primitives.  A full
 * implementation would require a deep understanding of the VL53L3CX
 * datasheet and the STMicroelectronics VL53L3CX API.
 */
static int vl53l3cx_init(int handle)
{
    uint16_t model_id = 0;

    /* 1. Verify sensor model ID */
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read model ID - sensor may be absent\n");
        return -1;
    }

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr,
                "[ERROR] Unexpected model ID 0x%04X (expected 0x%04X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    printf("[INFO] VL53L3CX detected (model ID 0x%04X)\n", model_id);

    /* 2. Software reset */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x0001) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* 3. Start ranging (stubbed: real firmware would perform this sequence) */
    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x0001) != 0)
        return -1;

    gpioDelay(100000); /* 100 ms for first measurement */
    return 0;
}

/* ------------------------- Read Distance ----------------------------- */

/*
 * Read distance for a single target.
 * Returns distance in mm on success, -1 on error.
 */
static int read_distance(int handle, int target_index)
{
    uint16_t reg;
    uint16_t range_mm;

    switch (target_index) {
    case 0: reg = REG_RESULT_RANGE_0; break;
    case 1: reg = REG_RESULT_RANGE_1; break;
    case 2: reg = REG_RESULT_RANGE_2; break;
    case 3: reg = REG_RESULT_RANGE_3; break;
    default:
        fprintf(stderr, "[ERROR] Invalid target index %d\n", target_index);
        return -1;
    }

    if (i2c_read_reg16(handle, reg, &range_mm) != 0)
        return -1;

    /* Sanity check: 0xFFFF indicates no valid data */
    if (range_mm == 0xFFFF) {
        fprintf(stderr, "[WARN] Target %d: no valid data (0xFFFF)\n", target_index);
        return -1;
    }

    return (int)range_mm;
}

/* ------------------------------- Main -------------------------------- */

int main(void)
{
    char ts[32];

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d) - sensor may be absent\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l3cx_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] VL53L3CX initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Reading VL53L3CX targets every %d ms. Press Ctrl+C to stop.\n",
           POLL_DELAY_US / 1000);

    /* Main polling loop */
    while (g_running) {
        get_timestamp(ts, sizeof(ts));

        for (int i = 0; i < MAX_TARGETS; i++) {
            int dist = read_distance(g_i2c_handle, i);
            if (dist >= 0) {
                printf("%s Target %d: %d mm\n", ts, i, dist);
            } else {
                printf("%s Target %d: ERROR\n", ts, i);
            }
        }

        fflush(stdout);
        gpioDelay(POLL_DELAY_US);
    }

    /* ----------------------- Cleanup ----------------------- */
    printf("\n[INFO] Shutting down...\n");

    /* Stop ranging (stubbed: real firmware would perform this) */
    if (i2c_write_reg16(g_i2c_handle, REG_SYSTEM_START, 0x0000) != 0)
        fprintf(stderr, "[WARN] Failed to stop ranging\n");

    /* Software reset */
    if (i2c_write_reg16(g_i2c_handle, REG_SOFT_RESET, 0x0000) != 0)
        fprintf(stderr, "[WARN] Failed to reset sensor\n");

    i2cClose(g_i2c_handle);
    g_i2c_handle = -1;

    gpioTerminate();
    return EXIT_SUCCESS;
}

