#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x40
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int i2c_write_byte(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("i2c_write_byte");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("i2c_read_bytes write reg");
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        perror("i2c_read_bytes read data");
        return -1;
    }
    return 0;
}

static int read_distance(int *distance) {
    uint8_t buf[2];
    if (i2c_read_bytes(0x00, buf, 2) < 0) {
        return -1;
    }
    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

static int log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_fp, "%s,%d\n", timestamp, distance) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (i2c_init() < 0) {
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen log");
        cleanup();
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        if (fprintf(log_fp, "Timestamp,Distance\n") < 0) {
            perror("fprintf header");
            cleanup();
            return 1;
        }
        fflush(log_fp);
    }

    while (running) {
        int distance;
        if (read_distance(&distance) < 0) {
            fprintf(stderr, "I2C read error, attempting re-init...\n");
            close(i2c_fd);
            i2c_fd = -1;
            usleep(100000);
            if (i2c_init() < 0) {
                fprintf(stderr, "Re-init failed, exiting.\n");
                break;
            }
            continue;
        }

        if (log_data(distance) < 0) {
            fprintf(stderr, "Log write error, exiting.\n");
            break;
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

