#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_MS      500

/* Si1145 register addresses */
#define REG_PART_ID    0x00
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0    0x24
#define REG_PS1_DATA1    0x25
#define REG_COMMAND      0x30

#define CMD_RESET       0x01
#define CMD_PS_FORCE    0x05
#define CMD_ALS_FORCE   0x06
#define CMD_PSALS_FORCE 0x07

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg8: read");
        return -1;
    }
    return 0;
}

static int si1145_init(int fd)
{
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor may be absent.\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x45).\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, REG_COMMAND, CMD_RESET) < 0)
        return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, REG_MEAS_RATE0, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, REG_MEAS_RATE1, 0x00) < 0)
        return -1;

    if (i2c_write_reg8(fd, REG_HW_KEY, 0x17) < 0)
        return -1;

    return 0;
}

static int read_proximity(int fd, uint16_t *prox)
{
    uint8_t lo, hi;
    if (i2c_write_reg8(fd, REG_COMMAND, CMD_PS_FORCE) < 0)
        return -1;
    usleep(10000);
    if (i2c_read_reg8(fd, REG_PS1_DATA0, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_PS1_DATA1, &hi) < 0)
        return -1;
    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int read_ambient_light(int fd, uint16_t *als)
{
    uint8_t lo, hi;
    if (i2c_write_reg8(fd, REG_COMMAND, CMD_ALS_FORCE) < 0)
        return -1;
    usleep(10000);
    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA0, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA1, &hi) < 0)
        return -1;
    *als = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_data(FILE *f, uint16_t prox, uint16_t als)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(f, "%s, Proximity: %u, Ambient Light: %u\n", ts, prox, als);
    fflush(f);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }

    if (si1145_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        return 1;
    }

    while (g_running) {
        uint16_t prox = 0, als = 0;
        int ok = 1;

        if (read_proximity(g_i2c_fd, &prox) < 0) {
            fprintf(stderr, "Proximity read failed.\n");
            ok = 0;
        }
        if (ok && read_ambient_light(g_i2c_fd, &als) < 0) {
            fprintf(stderr, "Ambient light read failed.\n");
            ok = 0;
        }

        if (ok)
            log_data(g_log, prox, als);

        usleep(SAMPLE_MS * 1000);
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    if (g_log)
        fclose(g_log);

    return 0;
}

