#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE 0x08
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x26
#define SI1145_REG_PS1_DATA1 0x27

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int si1145_init(void) {
    uint8_t part_id;
    if (i2c_read_reg(SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    if (i2c_write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) != 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        return -1;
    }
    if (i2c_write_reg(SI1145_REG_MEAS_RATE, 0x00) != 0) {
        fprintf(stderr, "Failed to set measurement rate\n");
        return -1;
    }
    return 0;
}

static int read_proximity(uint16_t *proximity) {
    uint8_t low, high;
    if (i2c_read_reg(SI1145_REG_PS1_DATA0, &low) != 0) return -1;
    if (i2c_read_reg(SI1145_REG_PS1_DATA1, &high) != 0) return -1;
    *proximity = ((uint16_t)high << 8) | low;
    return 0;
}

static int read_ambient_light(uint16_t *ambient_light) {
    uint8_t low, high;
    if (i2c_read_reg(SI1145_REG_ALS_VIS_DATA0, &low) != 0) return -1;
    if (i2c_read_reg(SI1145_REG_ALS_VIS_DATA1, &high) != 0) return -1;
    *ambient_light = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    if (si1145_init() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Si1145 initialized. Logging to biometric_data.log\n");

    while (!terminate) {
        uint16_t proximity, ambient_light;

        if (read_proximity(&proximity) != 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            sleep(1);
            continue;
        }

        if (read_ambient_light(&ambient_light) != 0) {
            fprintf(stderr, "Failed to read ambient light data\n");
            sleep(1);
            continue;
        }

        log_data(proximity, ambient_light);
        sleep(1);
    }

    printf("\nCaught SIGINT, exiting gracefully...\n");
    cleanup();
    return 0;
}

