    double pulse_duration = (double)(end_tick - start_tick);
    double distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0;
    }
    return distance;
}

static void log_data(double distance, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (distance >= 0.0) {
            fprintf(log_file, "%s, Distance: %.2f cm, %s\n", timestamp, distance, message);
        } else {
            fprintf(log_file, "%s, Error: Invalid distance reading\n", timestamp);
        }
        fflush(log_file);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Plant watering system started. Logging to %s\n", LOG_FILE);

    while (running) {
        double distance = measure_distance();

        if (distance >= 0.0) {
            log_data(distance, "");
            if (distance < WATER_THRESHOLD) {
                log_data(distance, "Time to water the plant!");
            }
        } else {
            log_data(-1.0, "Error: Invalid distance reading");
        }

        for (int i = 0; i < LOOP_INTERVAL_S && running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return 0;
}

