    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int apds9960_init(int fd) {
    uint8_t id;
    if (i2c_read_byte(fd, APDS9960_ID, &id) < 0) {
        fprintf(stderr, "Error: Failed to read ID register.\n");
        return -1;
    }
    if (id != APDS9960_ID_VALUE) {
        fprintf(stderr, "Error: Invalid sensor ID (0x%02X, expected 0x%02X).\n", id, APDS9960_ID_VALUE);
        return -1;
    }

