        fprintf(stderr, "Error: Failed to power on sensor.\n");
        return -1;
    }
    usleep(10000);

    if (i2c_write_byte(fd, APDS9960_ATIME, 0xFF) < 0) {
        fprintf(stderr, "Error: Failed to set ATIME.\n");
        return -1;
    }
    if (i2c_write_byte(fd, APDS9960_WTIME, 0xFF) < 0) {
        fprintf(stderr, "Error: Failed to set WTIME.\n");
        return -1;
    }
    if (i2c_write_byte(fd, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error: Failed to set PPULSE.\n");
        return -1;
    }
    if (i2c_write_byte(fd, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to set CONTROL.\n");
        return -1;
    }
    if (i2c_write_byte(fd, APDS9960_CONFIG1, 0x60) < 0) {
        fprintf(stderr, "Error: Failed to set CONFIG1.\n");
        return -1;
    }
    if (i2c_write_byte(fd, APDS9960_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set CONFIG2.\n");
        return -1;
    }

    if (i2c_write_byte(fd, APDS9960_ENABLE, APDS9960_ENABLE_PON | APDS9960_ENABLE_AEN | APDS9960_ENABLE_AIEN) < 0) {
        fprintf(stderr, "Error: Failed to enable ALS and proximity.\n");
        return -1;
    }
    usleep(10000);

