        perror("Error: Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
        fflush(log_file);
    }

    printf("APDS9960 initialized. Logging data to color_proximity_log.csv\n");

    while (running) {
        uint16_t r, g, b, p;

        if (apds9960_read_color(i2c_fd, &r, &g, &b) < 0) {
            fprintf(stderr, "Error: Failed to read color data. Re-initializing I2C...\n");
            close(i2c_fd);
            i2c_fd = -1;
            usleep(100000);
            i2c_fd = open(APDS9960_I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Error: Failed to re-open I2C bus");
                break;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, APDS9960_I2C_ADDR) < 0) {
                perror("Error: Failed to acquire I2C bus access");
                close(i2c_fd);
                break;
            }
            if (apds9960_init(i2c_fd) < 0) {
                fprintf(stderr, "Error: APDS9960 re-initialization failed.\n");
                close(i2c_fd);
                break;
            }
            continue;
        }

        if (apds9960_read_proximity(i2c_fd, &p) < 0) {
            fprintf(stderr, "Error: Failed to read proximity data.\n");
            continue;
        }

        if (p > PROXIMITY_THRESHOLD) {
            log_data(r, g, b, p);
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

