#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x55
#define CSV_FILENAME   "heartrate.csv"
#define SAMPLE_MS      100

/* Si1182 proximity register (0x08) — 16-bit little-endian */
#define SI1182_REG_PROX 0x08

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write one byte to a Si1182 register; returns 0 on success, -1 on error. */
static int si1182_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        perror("i2c write failed");
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian register; returns 0 on success, -1 on error. */
static int si1182_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    struct i2c_msg msgs[2] = {
        { .addr = SI1182_ADDR, .flags = 0,            .len = 1, .buf = &reg },
        { .addr = SI1182_ADDR, .flags = I2C_M_RD,     .len = 2, .buf = buf  }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        perror("i2c read16 failed");
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* Convert proximity (0–65535) to BPM (0–220). */
static float proximity_to_bpm(uint16_t prox) {
    return (float)prox / 655.35f;
}

/* Append one CSV line: "timestamp,bpm\n". */
static int log_data(FILE *fp, float bpm) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%.2f\n", ts, bpm) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

