#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L0X_ADDR 0x29
#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"

#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L0X_REG_SYSTEM_MODE_START 0x0000
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0014
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0013
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L0X_REG_RESULT_DISTANCE 0x0096
#define VL53L0X_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x000B
#define VL53L0X_REG_SYSTEM_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x000C
#define VL53L0X_REG_SYSTEM_RANGE_CONFIG_TIMEOUT_MACROP_LO 0x000D
#define VL53L0X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x000A
#define VL53L0X_REG_GPIO_HV_MUX_ACTIVE_HIGH 0x0084
#define VL53L0X_REG_GPIO_TIO_HV_STATUS 0x0080
#define VL53L0X_REG_GPIO_HV_MUX_ACTIVE_HIGH 0x0084
#define VL53L0X_REG_GPIO_TIO_HV_STATUS 0x0080

#define VL53L0X_MODEL_ID 0xEA
#define VL53L0X_SYSTEM_START_STOP 0x01
#define VL53L0X_SYSTEM_INTERRUPT_CLEAR_MASK 0x01
#define VL53L0X_SYSTEM_INTERRUPT_GPIO_MASK 0x04
#define VL53L0X_SYSTEM_INTERRUPT_POLARITY_FALLING 0x00
#define VL53L0X_SYSTEM_INTERRUPT_POLARITY_RISING 0x01
#define VL53L0X_SYSTEM_INTERRUPT_POLARITY_BOTH 0x02
#define VL53L0X_SYSTEM_INTERRUPT_POLARITY_NONE 0x03
#define VL53L0X_SYSTEM_INTERRUPT_MODE_NEW_SAMPLE 0x00
#define VL53L0X_SYSTEM_INTERRUPT_MODE_NEW_READY 0x01

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *value) {
    uint8_t buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l0x_init(int fd) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(fd, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n", model_id, VL53L0X_MODEL_ID);
        return -1;
    }

    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L0X_REG_GPIO_HV_MUX_ACTIVE_HIGH, 0x00) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L0X_REG_GPIO_TIO_HV_STATUS, 0x00) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_INTERMEASUREMENT_PERIOD, 0x00) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_RANGE_CONFIG_TIMEOUT_MACROP_LO, 0xE8) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_MODE_START, VL53L0X_SYSTEM_START_STOP) < 0) return -1;

    return 0;
}

static int vl53l0x_read_distance(int fd, uint16_t *distance) {
    uint8_t status = 0;
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, VL53L0X_SYSTEM_INTERRUPT_CLEAR_MASK) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_MODE_START, VL53L0X_SYSTEM_START_STOP) < 0) return -1;

    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg16(fd, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) < 0) return -1;
        if (status & 0x01) break;
        usleep(1000);
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    uint8_t dist_hi = 0, dist_lo = 0;
    if (i2c_read_reg16(fd, VL53L0X_REG_RESULT_DISTANCE, &dist_hi) < 0) return -1;
    if (i2c_read_reg16(fd, VL53L0X_REG_RESULT_DISTANCE + 1, &dist_lo) < 0) return -1;

    *distance = ((uint16_t)dist_hi << 8) | dist_lo;
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L0X_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (vl53l0x_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("VL53L0X initialized. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        uint16_t distance = 0;
        if (vl53l0x_read_distance(i2c_fd, &distance) == 0) {
            log_distance(log_file, distance);
            printf("Distance: %u mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        usleep(100000);
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    return 0;
}

