#define I2C_BUS         "/dev/i2c-1"
#define CH101_ADDR      0x30
#define CMD_TRIGGER     0x00
#define CMD_READ_DIST   0x80
#define TRIGGER_DELAY_US 50000   /* 50 ms */
#define SAMPLE_PERIOD_US 200000  /* 200 ms */
#define LOG_FILE        "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single command byte to the CH101 (no data payload). */
static int ch101_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        perror("I2C write command failed");
        return -1;
    }
    return 0;
