#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x30
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VAL 0x00
#define DISTANCE_REG 0x04
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100
#define LOG_FILE "tof_log.txt"
#define POLL_INTERVAL_US 50000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_distance(int *distance) {
    int raw = i2cReadWordData(i2c_handle, DISTANCE_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading distance register: %d\n", raw);
        return -1;
    }
    *distance = (int)((uint16_t)raw);
    return 0;
}

static void log_data(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    } else {
        fprintf(fp, "Timestamp error, Distance: %d mm\n", distance);
    }

    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold '%s'. Using default %d mm.\n", argv[1], DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting distance monitoring. Threshold: %d mm. Press Ctrl+C to exit.\n", threshold);

    while (!terminate) {
        int distance;
        if (read_distance(&distance) == 0) {
            log_data(distance);
            if (distance < threshold) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read distance. Retrying in 100ms...\n");
            gpioDelay(100000);
            continue;
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

