#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_ADDR       0x20
#define CMD_FRAME_LEN  4
#define RESP_FRAME_LEN 15
#define SAMPLES        10
#define SAMPLE_DELAY_MS 100
#define THRESHOLD_MM   1000
#define LOG_FILE       "intrusion_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_buf(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_buf(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int b5l_request_measurement(int fd) {
    uint8_t cmd[CMD_FRAME_LEN] = {0x01, 0x02, 0x03, 0x04};
    return i2c_write_buf(fd, cmd, CMD_FRAME_LEN);
}

static int b5l_read_distance(int fd, uint16_t *distance_mm) {
    uint8_t resp[RESP_FRAME_LEN];

    if (b5l_request_measurement(fd) != 0)
        return -1;

