#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29

#define REG_MODEL_ID                  0x010F
#define REG_SYSTEM_START              0x0000
#define REG_RESULT_INTERRUPT_STATUS   0x0046
#define REG_RESULT_RANGE_STATUS       0x0044
#define REG_RESULT_DISTANCE           0x0096
#define REG_SYSTEM_INTERRUPT_CLEAR    0x0086

#define EXPECTED_MODEL_ID 0xEA
#define POLL_TIMEOUT_MS   100
#define LOOP_DELAY_US     500000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg16(0x%04X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 write(0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 read(0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l0x_init(int handle)
{
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID register.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X).\n", model_id);

    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x00) != 0)
        return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x01) != 0)
        return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int elapsed = 0;

    while (elapsed < POLL_TIMEOUT_MS) {
        if (i2c_read_reg16(handle, REG_RESULT_INTERRUPT_STATUS, &status) != 0)
            return -1;
        if (status & 0x07)
            break;
        gpioDelay(2000);
        elapsed += 2;
    }
    if (!(status & 0x07)) {
        fprintf(stderr, "Timeout waiting for VL53L0X data ready.\n");
        return -1;
    }

    uint8_t range_status = 0;
    if (i2c_read_reg16(handle, REG_RESULT_RANGE_STATUS, &range_status) != 0)
        return -1;

    if (range_status & 0x01) {
        fprintf(stderr, "VL53L0X out of range (status 0x%02X).\n", range_status);
        return -1;
    }

    uint8_t dist_hi = 0, dist_lo = 0;
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, &dist_hi) != 0)
        return -1;
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE + 1, &dist_lo) != 0)
        return -1;

    *distance_mm = ((uint16_t)dist_hi << 8) | dist_lo;

    if (i2c_write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    printf("%s ", timestamp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d): %s\n",
                g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting distance readings (Ctrl+C to exit)...\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l0x_read_distance(g_i2c_handle, &distance) == 0) {
            print_timestamp();
            printf("Distance: %u mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

