/*
 * Si1182 Proximity Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   Si1182 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1182_reader si1182_reader.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./si1182_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1182 I2C address (7-bit) ---- */
#define SI1182_ADDR 0x18

/* ---- Si1182 register addresses ---- */
#define SI1182_REG_PART_ID       0x00
#define SI1182_REG_HW_REV        0x01
#define SI1182_REG_SEQ_ID        0x02
#define SI1182_REG_INT_CFG       0x03
#define SI1182_REG_IRQ_ENABLE    0x04
#define SI1182_REG_IRQ_STATUS    0x05
#define SI1182_REG_HW_KEY        0x07
#define SI1182_REG_MEAS_RATE     0x08
#define SI1182_REG_PS_LED21_SELECT 0x09
#define SI1182_REG_PS1_ADC_MISC  0x0A
#define SI1182_REG_PS_ADC_GAIN   0x0B
#define SI1182_REG_PS_ADC_MISC2  0x0C
#define SI1182_REG_PS_ADC_LSB    0x0D
#define SI1182_REG_PS_ADC_MSB    0x0E
#define SI1182_REG_COMMAND       0x0F

/* ---- Si1182 command codes ---- */
#define SI1182_CMD_RESET         0x01
#define SI1182_CMD_PS_FORCE      0x05

/* ---- Expected part ID ---- */
#define SI1182_PART_ID_EXPECTED  0x82

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1182 register. Returns 0 on success, -1 on error. */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1182 register. Returns 0 on success, -1 on error. */
static int si1182_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair. Returns 0 on success, -1 on error. */
static int si1182_read_reg16(int handle, uint8_t reg_lsb, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg_lsb);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n", reg_lsb, rc);
        return -1;
    }
    /* pigpio returns the word as (msb << 8) | lsb, which matches Si1182 little-endian. */
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1182 sensor. Returns 0 on success, -1 on error. */
static int si1182_init(int handle)
{
    uint8_t part_id = 0;

    /* --- Verify sensor presence via NACK on the first write --- */
    if (i2cWriteByte(handle, 0x00) < 0) {
        fprintf(stderr, "[ERROR] No ACK from Si1182 at address 0x%02X (sensor absent or bus error).\n",
                SI1182_ADDR);
        return -1;
    }

    /* --- Read Part ID --- */
    if (si1182_read_reg(handle, SI1182_REG_PART_ID, &part_id) != 0)
        return -1;

    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] Unexpected Part ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    printf("[INFO] Si1182 detected (Part ID = 0x%02X).\n", part_id);

    /* --- Software reset --- */
    if (si1182_write_reg(handle, SI1182_REG_COMMAND, SI1182_CMD_RESET) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    /* --- Read back Part ID to confirm reset --- */
    if (si1182_read_reg(handle, SI1182_REG_PART_ID, &part_id) != 0)
        return -1;
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] Reset failed or Part ID mismatch (got 0x%02X).\n", part_id);
        return -1;
    }

    /* --- Configure LED current and ADC range for PS1 --- */
    if (si1182_write_reg(handle, SI1182_REG_PS_LED21_SELECT, 0x01) != 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_ADC_MISC, 0x00) != 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_ADC_GAIN, 0x00) != 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_ADC_MISC2, 0x00) != 0)
        return -1;

