    if (si1182_write_reg(handle, SI1182_REG_IRQ_ENABLE, 0x01) != 0)
        return -1;

    /* --- Start periodic PS measurements at 100 ms interval --- */
    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE, 0x64) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at the Si1182 address --- */
    g_i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                SI1182_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize the sensor --- */
    if (si1182_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] Si1182 initialization failed.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] Si1182 initialized. Logging proximity every 500 ms (Ctrl+C to stop).\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t proximity = 0;

        if (si1182_read_reg16(g_i2c_handle, SI1182_REG_PS_ADC_LSB, &proximity) != 0) {
            fprintf(stderr, "[WARN] Failed to read proximity data; retrying next cycle.\n");
        } else {
