#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* OPT3101 I2C address (7-bit) */
#define OPT3101_ADDR 0x50

/* OPT3101 register addresses */
#define REG_PRODUCT_ID       0x00
#define REG_CONFIG           0x01
#define REG_RESULT_RANGE     0x02
#define REG_RESULT_AMBIENT   0x03
#define REG_RESULT_ERROR     0x04
#define REG_INT_STATUS       0x05
#define REG_INT_MASK         0x06
#define REG_FIFO_WR_PTR      0x07
#define REG_FIFO_RD_PTR      0x08
#define REG_FIFO_COUNT       0x09
#define REG_FIFO_DATA        0x0A

/* Expected product ID for OPT3101 */
#define OPT3101_PRODUCT_ID   0x3101

/* Configuration register bits */
#define CFG_RN_MASK          0x0007
#define CFG_RN_100MS         0x0000
#define CFG_RN_200MS         0x0001
#define CFG_RN_400MS         0x0002
#define CFG_RN_800MS         0x0003
#define CFG_RN_1600MS        0x0004
#define CFG_RN_3200MS        0x0005
#define CFG_RN_6400MS        0x0006
#define CFG_RN_12800MS       0x0007
#define CFG_POL_MASK         0x0008
#define CFG_POL_LOW          0x0000
#define CFG_POL_HIGH         0x0008
#define CFG_MEAS_MASK        0x0070
#define CFG_MEAS_SINGLE      0x0000
#define CFG_MEAS_CONT        0x0010
#define CFG_FLSH_MASK        0x0080
#define CFG_FLSH_NOW         0x0000
#define CFG_FLSH_NEXT        0x0080
#define CFG_RST_MASK         0x0100
#define CFG_RST_RESET        0x0000
#define CFG_RST_NORESET      0x0100
#define CFG_EN_MASK          0x0200
#define CFG_EN_DISABLE       0x0000
#define CFG_EN_ENABLE        0x0200

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit value to a 16-bit register address */
static int write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit value from a 16-bit register address */
static int read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Initialize the OPT3101 sensor */
static int init_opt3101(int handle) {
    uint16_t product_id;

