/*
 * HC-SR04 Ultrasonic Distance Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Trigger: GPIO 17 (BCM)  - output
 * Echo:    GPIO 18 (BCM)  - input
 *
 * NOTE: The HC-SR04 operates at 5 V and the Pi GPIO is 3.3 V tolerant.
 *       A 1 kΩ pull-up resistor must be placed on the echo line.
 *
 * Build:  gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms echo timeout            */
#define LOOP_DELAY_US    1000000     /* 1 s between readings           */
#define MIN_DISTANCE_CM  2.0         /* HC-SR04 minimum range (cm)     */
#define MAX_DISTANCE_CM  400.0       /* HC-SR04 maximum range (cm)     */
#define SPEED_OF_SOUND_CM_PER_US 0.0343   /* 343 m/s → cm/µs            */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns elapsed microseconds between two timespecs.                */
static uint32_t elapsed_us(const struct timespec *start,
                           const struct timespec *end)
{
    return (uint32_t)((end->tv_sec  - start->tv_sec)  * 1000000ULL +
                      (end->tv_nsec - start->tv_nsec) / 1000ULL);
}

/* ------------------------------------------------------------------ */
/* Returns distance in cm, or -1.0 on timeout / invalid pulse.        */
static float read_distance(void)
{
    struct timespec t_start, t_rise, t_fall;
    uint32_t elapsed;

    /* --- Trigger: 10 µs falling pulse --- */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);                       /* ensure clean low            */

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0f;
    }

    /* --- Wait for echo rising edge --- */
    if (gpioSetAlertFunc(ECHO_PIN, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc(ECHO_PIN, NULL) failed\n");
        return -1.0f;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &t_start) != 0) {
        fprintf(stderr, "Error: clock_gettime failed\n");
        return -1.0f;
    }

    while (gpioRead(ECHO_PIN) == 0) {
        if (!g_running)
            return -1.0f;
        if (clock_gettime(CLOCK_MONOTONIC, &t_rise) != 0) {
            fprintf(stderr, "Error: clock_gettime failed\n");
            return -1.0f;
        }
        elapsed = elapsed_us(&t_start, &t_rise);
        if (elapsed > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo rising-edge timeout (%u us)\n",
                    elapsed);
            return -1.0f;
        }
    }

    /* --- Wait for echo falling edge --- */
    if (clock_gettime(CLOCK_MONOTONIC, &t_rise) != 0) {
        fprintf(stderr, "Error: clock_gettime failed\n");
        return -1.0f;
    }

    while (gpioRead(ECHO_PIN) == 1) {
        if (!g_running)
            return -1.0f;
        if (clock_gettime(CLOCK_MONOTONIC, &t_fall) != 0) {
            fprintf(stderr, "Error: clock_gettime failed\n");
            return -1.0f;
        }
        elapsed = elapsed_us(&t_rise, &t_fall);
        if (elapsed > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo falling-edge timeout (%u us)\n",
                    elapsed);
            return -1.0f;
        }
    }

    /* --- Compute pulse duration --- */
    uint32_t pulse_us = elapsed_us(&t_rise, &t_fall);

    if (pulse_us == 0) {
        fprintf(stderr, "Error: Invalid pulse duration (0 µs)\n");
        return -1.0f;
    }
    if (pulse_us > ECHO_TIMEOUT_US) {
        fprintf(stderr, "Error: Pulse too long (%u µs) – out of range\n",
                pulse_us);
        return -1.0f;
    }

    /* --- Distance = (pulse_us * 343 m/s) / 2 / 1e6 --- */
    float distance = (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: Distance %.2f cm out of range [%.1f–%.1f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    gpioDelay(500000);  /* 500 ms */

    printf("HC-SR04 distance sensor started.\n");
    printf("  Trigger: GPIO %d (output)\n", TRIGGER_PIN);
    printf("  Echo:    GPIO %d (input)\n", ECHO_PIN);
    printf("  Trigger pulse: %d µs\n", TRIGGER_PULSE_US);
    printf("  Echo timeout:  %d µs\n", ECHO_TIMEOUT_US);
    printf("  Loop delay:    %d µs\n", LOOP_DELAY_US);
    printf("  Range:         %.1f–%.1f cm\n",
           MIN_DISTANCE_CM, MAX_DISTANCE_CM);
    printf("  Speed of sound: %.3f cm/µs\n", SPEED_OF_SOUND_CM_PER_US);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main loop --- */
    while (g_running) {
        float distance = read_distance();

        if (distance >= 0.0f) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp),
                     "%Y-%m-%d %H:%M:%S", &timeinfo);

            printf("[%s] Distance: %.2f cm\n", timestamp, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        uint32_t remaining = LOOP_DELAY_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = (remaining > 100000) ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    /* --- Cleanup --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

