    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    gpioDelay(500000);  /* 500 ms */

    printf("HC-SR04 distance sensor started.\n");
    printf("  Trigger: GPIO %d (output)\n", TRIGGER_PIN);
    printf("  Echo:    GPIO %d (input)\n", ECHO_PIN);
    printf("  Trigger pulse: %d µs\n", TRIGGER_PULSE_US);
    printf("  Echo timeout:  %d µs\n", ECHO_TIMEOUT_US);
    printf("  Loop delay:    %d µs\n", LOOP_DELAY_US);
    printf("  Range:         %.1f–%.1f cm\n",
           MIN_DISTANCE_CM, MAX_DISTANCE_CM);
    printf("  Speed of sound: %.3f cm/µs\n", SPEED_OF_SOUND_CM_PER_US);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main loop --- */
    while (g_running) {
        float distance = read_distance();

        if (distance >= 0.0f) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp),
                     "%Y-%m-%d %H:%M:%S", &timeinfo);

            printf("[%s] Distance: %.2f cm\n", timestamp, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        uint32_t remaining = LOOP_DELAY_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = (remaining > 100000) ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    /* --- Cleanup --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

