#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0f
#define LOG_FILE "intrusion_log.csv"
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define NUM_BINS 64
#define HEADER_SIZE 8
#define FRAME_SIZE (HEADER_SIZE + RANGE_PROFILE_SIZE)

static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};

static volatile sig_atomic_t terminate = 0;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Error opening UART port");
        return -1;
    }

    if (fcntl(fd, F_SETFL, 0) < 0) {
        perror("Error clearing O_NDELAY");
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("Error reading from UART");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read timeout\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int decode_range_profile(const uint8_t *data, float *distances) {
    for (int i = 0; i < NUM_BINS; i++) {
        uint16_t raw = (uint16_t)data[i * 2] | ((uint16_t)data[i * 2 + 1] << 8);
        distances[i] = (float)raw / 100.0f;
    }
    return 0;
}

static int check_threshold(const float *distances) {
    for (int i = 0; i < NUM_BINS; i++) {
        if (distances[i] < DISTANCE_THRESHOLD) return 1;
    }
    return 0;
}

static int log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("Error getting local time");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, distance) < 0) {
        perror("Error writing to log file");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("Error flushing log file");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    return 0;
}

static void trigger_alert(void) {
    if (gpioWrite(GPIO_LED, 1) != 0) {
        fprintf(stderr, "Error setting LED high\n");
        return;
    }
    gpioDelay(2000000);
    if (gpioWrite(GPIO_LED, 0) != 0) {
        fprintf(stderr, "Error setting LED low\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_PORT);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    uint8_t frame_buf[FRAME_SIZE];
    float distances[NUM_BINS];

    while (!terminate) {
        if (read_exact(uart_fd, frame_buf, MAGIC_WORD_SIZE) != 0) {
            fprintf(stderr, "Failed to read magic word header\n");
            continue;
        }

        if (memcmp(frame_buf, MAGIC_WORD, MAGIC_WORD_SIZE) != 0) {
            continue;
        }

        if (read_exact(uart_fd, frame_buf + MAGIC_WORD_SIZE, RANGE_PROFILE_SIZE) != 0) {
            fprintf(stderr, "Failed to read range profile data\n");
            continue;
        }

        if (decode_range_profile(frame_buf + MAGIC_WORD_SIZE, distances) != 0) {
            fprintf(stderr, "Failed to decode range profile\n");
            continue;
        }

        if (check_threshold(distances)) {
            float max_distance = 0.0f;
            for (int i = 0; i < NUM_BINS; i++) {
                if (distances[i] > max_distance) max_distance = distances[i];
            }

            if (log_intrusion(max_distance) != 0) {
                fprintf(stderr, "Failed to log intrusion\n");
            }

            trigger_alert();
        }
    }

    printf("\nCleaning up...\n");
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();

    return 0;
}

