#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_event(FILE *fp, int obstacle_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s - Obstacle %s\n", timestamp,
                obstacle_detected ? "Detected" : "Cleared") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    FILE *fp = NULL;
    int last_state = -1;
    int ret = EXIT_FAILURE;

    /* --- Install signal handlers early --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pin as input --- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sensor pin %d as input\n", SENSOR_PIN);
        goto cleanup_gpio;
    }

    /* --- Configure buzzer pin as output --- */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer pin %d as output\n", BUZZER_PIN);
        goto cleanup_gpio;
    }

    /* --- Ensure buzzer is off at start --- */
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise buzzer state on pin %d\n",
                BUZZER_PIN);
        goto cleanup_gpio;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    printf("Obstacle detection system started. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor pin %d\n", SENSOR_PIN);
            break;
        }

        /* E18-D80NK is active-low: 0 = obstacle detected */
        int obstacle_detected = (sensor_value == 0);

        if (gpioWrite(BUZZER_PIN, obstacle_detected ? 1 : 0) != 0) {
            fprintf(stderr, "Error writing to buzzer pin %d\n", BUZZER_PIN);
            break;
        }

        if (obstacle_detected != last_state) {
            if (log_event(fp, obstacle_detected) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
            last_state = obstacle_detected;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");

    /* Ensure buzzer is off */
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off buzzer during shutdown\n");
    }

    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
    }

    gpioTerminate();
    ret = EXIT_SUCCESS;

cleanup_gpio:
    gpioTerminate();
    return ret;
}

