#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS         "/dev/i2c-1"
#define VL53L1X_ADDR    0x29
#define LOG_FILE        "distance_log.csv"
#define POLL_MS         100
#define STOP_THRESHOLD  300
#define APPROACH_THRESHOLD 600
#define SLOW_THRESHOLD  1200

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- VL53L1X register map (16-bit addresses, 16-bit data) ---- */
#define VL53L1X_REG_SOFT_RESET       0x000B
#define VL53L1X_REG_SYSTEM_MODE      0x0001
#define VL53L1X_REG_RANGE_START      0x0000
#define VL53L1X_REG_RESULT_RANGE_MM  0x0096

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint16_t reg, uint16_t val)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (val >> 8) & 0xFF;
    buf[3] = val & 0xFF;
    if (write(fd, buf, 4) != 4) {
        perror("i2c_write16: write");
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, addr, 2) != 2) {
        perror("i2c_read16: write addr");
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("i2c_read16: read data");
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int vl53l1x_init(int fd)
{
    if (i2c_write16(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write16(fd, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write16(fd, VL53L1X_REG_SYSTEM_MODE, 0x00) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance_mm)
{
    if (i2c_write16(fd, VL53L1X_REG_RANGE_START, 0x01) < 0) return -1;
    usleep(10000);
    uint16_t raw;
    if (i2c_read16(fd, VL53L1X_REG_RESULT_RANGE_MM, &raw) < 0) return -1;
    *distance_mm = raw;
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", ts, distance);
    fflush(fp);
}

static void print_guidance(uint16_t distance)
{
    if (distance < STOP_THRESHOLD)
        printf("Guidance: STOP\n");
    else if (distance < APPROACH_THRESHOLD)
        printf("Guidance: APPROACH\n");
    else if (distance < SLOW_THRESHOLD)
        printf("Guidance: SLOW\n");
    else
        printf("Guidance: CLEAR\n");
    fflush(stdout);
}

static int ensure_log_header(void)
{
    FILE *check = fopen(LOG_FILE, "r");
    if (check) { fclose(check); return 0; }
    FILE *fp = fopen(LOG_FILE, "w");
    if (!fp) { perror("fopen log"); return -1; }
    fprintf(fp, "timestamp,distance_mm\n");
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open i2c bus");
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (ensure_log_header() < 0) {
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Parking Assistance System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance;
        if (vl53l1x_read_distance(g_i2c_fd, &distance) == 0) {
            log_distance(g_log_fp, distance);
            print_guidance(distance);
        } else {
            fprintf(stderr, "Sensor read error\n");
        }
        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

