/*
 * CH201 Ultrasonic ToF Sensor -> LED Blink Frequency Logger
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensor: TDK InvenSense CH201 (I2C bus 1, address 0x30)
 * LED:    330 ohm current-limiting resistor to GPIO 18 (BCM)
 *
 * Build:  gcc -O2 -Wall -o ch201_blink ch201_blink.c -lpigpio -lrt
 * Run:    sudo ./ch201_blink
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define CH201_ADDR           0x30
#define LED_GPIO             18
#define SAMPLE_PERIOD_US     100000          /* 100 ms  */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       10000           /* 10 ms   */
#define MAX_DISTANCE_CM      400.0f          /* CH201 max range */
#define MIN_DISTANCE_CM      2.0f            /* CH201 min range */
#define LED_ON_TIME_US       10000           /* 10 ms half-cycle */
#define LED_OFF_TIME_US      9000            /* 9 ms  half-cycle */

/*
 * CH201 register map (16-bit registers, big-endian on the bus).
 * Distance register 0x00: 16-bit unsigned, units of 0.1 mm.
 */
#define CH201_REG_DISTANCE   0x00

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_terminate = 0;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* --------------------------- I2C helpers --------------------------------- */
/*
 * Read a 16-bit big-endian register with retries.
 * Returns 0 on success, -1 on failure.
 */
static int ch201_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
        if (rc == 2) {
            *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read distance in centimetres.
 * Returns 0 on success, -1 on failure.
 */
static int ch201_read_distance(int handle, float *distance_cm)
{
    uint16_t raw;
    if (ch201_read_reg16(handle, CH201_REG_DISTANCE, &raw) != 0)
        return -1;

    /* CH201 distance register: 16-bit unsigned, units of 0.1 mm */
    *distance_cm = (float)raw * 0.1f;
    return 0;
}

/* --------------------------- LED helpers --------------------------------- */
static void led_on(void)
{
    gpioWrite(LED_GPIO, 1);
}

static void led_off(void)
{
    gpioWrite(LED_GPIO, 0);
}

/*
 * Map distance to LED blink frequency.
 * Faster distance -> faster blink.
 * Clamp to a minimum frequency of 1 Hz (LED off) for very close objects.
 */
static int distance_to_frequency(float distance_cm)
{
    if (distance_cm < MIN_DISTANCE_CM)
        return 0;

    /*
     * Linear mapping: 400 cm -> 1 Hz, 2 cm -> 10 Hz.
     * Frequency = 10 Hz + (distance_cm - 2 cm) * 9 Hz / 398 cm.
     */
    float freq = 10.0f + (distance_cm - MIN_DISTANCE_CM) * 9.0f / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    if (freq < 1.0f) freq = 1.0f;
    if (freq > 10.0f) freq = 10.0f;
    return (int)freq;
}

/* --------------------------- Main loop ----------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    led_off();

    /* --- Open I2C bus to CH201 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, CH201_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance logger started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (!g_terminate) {
        float distance_cm;

        if (ch201_read_distance(g_i2c_handle, &distance_cm) != 0) {
            fprintf(stderr, "Sensor read failed; continuing after delay.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int freq = distance_to_frequency(distance_cm);

        /*
         * Drive the LED through one half-cycle (on + off) per iteration.
         * This keeps the blink smooth across samples and avoids a
         * hard-to-see flicker when the LED is driven directly.
         */
        if (freq > 0) {
            led_on();
            gpioDelay(LED_ON_TIME_US);
            led_off();
            gpioDelay(LED_OFF_TIME_US);
        } else {
            led_off();
            gpioDelay(SAMPLE_PERIOD_US);
        }

        /* Timestamped logging */
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        printf("%s  Distance: %.2f cm  Blink: %d Hz\n", ts, distance_cm, freq);
        fflush(stdout);
    }

    /* --- Cleanup --- */
    led_off();
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

