#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 10000
#define LOG_FILE "proximity_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

static int debounce_and_log(int sensor_id, int level) {
    static int sensor1_state = 0;
    static int sensor2_state = 0;
    static uint32_t last_tick1 = 0;
    static uint32_t last_tick2 = 0;

    uint32_t now = gpioTick();
    uint32_t elapsed;

    if (sensor_id == 1) {
        elapsed = now - last_tick1;
        if (elapsed < (uint32_t)(DEBOUNCE_MS * 1000)) {
            return 0;
        }
        last_tick1 = now;
    } else if (sensor_id == 2) {
        elapsed = now - last_tick2;
        if (elapsed < (uint32_t)(DEBOUNCE_MS * 1000)) {
            return 0;
        }
        last_tick2 = now;
    } else {
        return 0;
    }

    int current_state = (sensor_id == 1) ? sensor1_state : sensor2_state;

    if (level == 1 && current_state == 0) {
        if (log_event(sensor_id, "DETECTED") != 0) {
            return -1;
        }
    } else if (level == 0 && current_state == 1) {
        if (log_event(sensor_id, "CLEARED") != 0) {
            return -1;
        }
    }

    if (sensor_id == 1) {
        sensor1_state = level;
    } else if (sensor_id == 2) {
        sensor2_state = level;
    }

    return 0;
}

