        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead failed\n");
            break;
        }

        if (debounce_and_log(1, s1) != 0) {
            fprintf(stderr, "Logging failed for sensor 1\n");
            break;
        }
        if (debounce_and_log(2, s2) != 0) {
