#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x30
#define REG_MEAS_STATUS 0x00
#define REG_DISTANCE   0x04
#define LOG_FILE       "distance_log.csv"
#define POLL_TIMEOUT_MS 50
#define SAMPLE_DELAY_MS 500

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t b;
    if (read(fd, &b, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = b;
    return 0;
}

static int ch101_poll_status(int fd) {
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        uint8_t status;
        if (i2c_read_reg8(fd, REG_MEAS_STATUS, &status) < 0)
            return -1;
        if ((status & 0x01) != 0)
            return 0;
        usleep(1000);
    }
    fprintf(stderr, "CH-101 measurement timeout\n");
    return -1;
}

static int ch101_read_distance(int fd, uint16_t *distance_mm) {
    if (i2c_write_reg8(fd, REG_MEAS_STATUS, 0x01) < 0)
        return -1;
    if (ch101_poll_status(fd) < 0)
        return -1;
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, REG_DISTANCE, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_DISTANCE + 1, &hi) < 0)
        return -1;
    *distance_mm = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void log_data(FILE *fp, uint16_t distance_mm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", ts, distance_mm);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    fprintf(g_log_fp, "# CH-101 distance log started\n");
    fflush(g_log_fp);

    while (g_running) {
        uint16_t distance;
        if (ch101_read_distance(g_i2c_fd, &distance) == 0) {
            log_data(g_log_fp, distance);
        } else {
            fprintf(stderr, "Failed to read distance, skipping sample\n");
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

