#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX75030_ADDR  0x60
#define SAMPLE_PERIOD_US 100000  /* 100 ms */
#define MAX_RETRIES     3
#define RETRY_DELAY_US  10000    /* 10 ms */

/*
 * MLX75030 register map (simplified for distance read).
 * The full datasheet provides a full 16-bit register map; this
 * mapping is a reduced subset that exercises the I2C primitives.
 */
#define REG_DISTANCE_HIGH 0x00
#define REG_DISTANCE_LOW  0x01
#define REG_STATUS        0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single byte to an 8-bit register.
 * Returns 0 on success, -1 on failure.
 */
static int mlx75030_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: I2C write to reg 0x%02X failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read a single byte from an 8-bit register.
 * Returns 0 on success and stores the byte in *value; -1 on failure.
 */
static int mlx75030_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "Warning: I2C read from reg 0x%02X failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read the 16-bit distance value from the sensor.
 * Returns 0 on success and stores the distance in *distance_mm; -1 on failure.
 */
static int mlx75030_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t hi, lo;

    if (mlx75030_read_reg(handle, REG_DISTANCE_HIGH, &hi) != 0)
        return -1;
    if (mlx75030_read_reg(handle, REG_DISTANCE_LOW, &lo) != 0)
        return -1;

    *distance_mm = ((uint16_t)hi << 8) | lo;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Sensor may be absent or bus unavailable.\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance reader started. Press Ctrl-C to exit.\n");

    while (g_running) {
        uint16_t distance;
        struct timespec ts;

        if (mlx75030_read_distance(g_i2c_handle, &distance) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("%ld.%03ld  Distance: %u mm\n",
                   (long)ts.tv_sec, ts.tv_nsec / 1000000L, (unsigned)distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: Failed to read distance after %d retries.\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful cleanup */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

