/* VL53L4CX register addresses */
#define VL53L4CX_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR 0x000B
#define VL53L4CX_REG_SYSTEM_INTERRUPT_STATUS 0x000A
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L4CX_REG_RESULT_DISTANCE 0x0096

/* Expected model ID for VL53L4CX */
#define VL53L4CX_MODEL_ID 0xEA

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address, then a 16-bit value               */
/* ------------------------------------------------------------------ */
static int vl53l4cx_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "Error writing register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register address (2 bytes)                            */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char addr_buf[2];
    char data_buf[2];

    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "Error setting register address 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L4CX sensor                                      */
/* ------------------------------------------------------------------ */
static int vl53l4cx_init(int handle)
{
    uint16_t model_id = 0;

    /* Read model ID to confirm sensor is present and responding */
    if (vl53l4cx_read_reg16(handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID — sensor not responding or bus error\n");
        return -1;
    }

    if (model_id != VL53L4CX_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%04X (expected 0x%04X)\n",
                model_id, VL53L4CX_MODEL_ID);
        return -1;
    }

    printf("VL53L4CX detected (model ID 0x%04X)\n", model_id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a distance measurement from the sensor                         */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_distance(int handle, uint16_t *distance)
{
    uint16_t status = 0;

    /* Poll interrupt status register for data-ready */
    if (vl53l4cx_read_reg16(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_STATUS, &status) != 0) {
        return -1;
    }

    if ((status & 0x01) == 0) {
        /* Data not ready — skip this cycle */
        return 1;
    }

    /* Read distance */
    if (vl53l4cx_read_reg16(handle, VL53L4CX_REG_RESULT_DISTANCE, distance) != 0) {
        return -1;
    }

    /* Clear interrupt to allow next measurement */
    if (vl53l4cx_write_reg16(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Format a timestamp with microsecond precision                       */
/* ------------------------------------------------------------------ */
static void format_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "Timestamp: Error");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(buf + strlen(buf), len - strlen(buf), ".%06ld", ts.tv_nsec / 1000);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    char timestamp[64];
    uint16_t distance = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the VL53L4CX address */
    g_i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %s\n",
                VL53L4CX_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (vl53l4cx_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Starting distance measurements (Ctrl+C to exit)...\n");

    /* Main measurement loop */
    while (g_running) {
        int ret = vl53l4cx_read_distance(g_i2c_handle, &distance);

        if (ret == 0) {
            format_timestamp(timestamp, sizeof(timestamp));
            printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance);
            fflush(stdout);
        } else if (ret < 0) {
            fprintf(stderr, "I2C communication error — skipping cycle\n");
        }
        /* ret == 1 means data not ready, no error — just skip */

