#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int fd) {
    if (i2c_write_reg8(fd, 0x88, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x80, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x00, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x91, 0x3C) < 0) return -1;
    if (i2c_write_reg8(fd, 0x00, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFF, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x80, 0x00) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance) {
    uint8_t status = 0;
    if (i2c_read_reg8(fd, 0x14, &status) < 0) return -1;
    if (status & 0x01) {
        uint8_t dist_low = 0, dist_high = 0;
        if (i2c_read_reg8(fd, 0x16, &dist_low) < 0) return -1;
        if (i2c_read_reg8(fd, 0x17, &dist_high) < 0) return -1;
        *distance = (dist_high << 8) | dist_low;
        return 0;
    }
    return 1;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    while (running) {
        uint16_t distance = 0;
        int ret = vl53l1x_read_distance(i2c_fd, &distance);

        if (ret == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else if (ret < 0) {
            fprintf(stderr, "I2C read error, skipping iteration\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(BUZZER_GPIO, 0);
    close(i2c_fd);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return 0;
}

