#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define MIN_DISTANCE_CM 2.0f
#define MAX_DISTANCE_CM 400.0f
#define MIN_ANGLE_DEG   -90.0f
#define MAX_ANGLE_DEG   90.0f

#define ECHO_TIMEOUT_US 50000
#define LOOP_DELAY_US   200000
#define TRIGGER_PULSE_US 10

#define ERROR_DISTANCE -1.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static float read_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return ERROR_DISTANCE;
    gpioDelay(5);
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return ERROR_DISTANCE;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return ERROR_DISTANCE;

    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) return ERROR_DISTANCE;
    }
