#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <mqueue.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define TIMING_BUDGET_MS 50
#define POLL_INTERVAL_MS 50
#define MQ_NAME "/distance_queue"
#define MQ_MAX_MSG 10
#define MQ_MSG_SIZE 256

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static mqd_t mq = (mqd_t)-1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int fd) {
    if (i2c_write_byte(fd, 0x88, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x80, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, 0xFF, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, 0x00, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x91, 0x3C) < 0) return -1;
    if (i2c_write_byte(fd, 0x00, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, 0xFF, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x80, 0x00) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int fd, int *distance) {
    uint8_t status = 0;
    if (i2c_read_byte(fd, 0x14, &status) < 0) return -1;
    if (status & 0x01) {
        uint8_t dist_low = 0, dist_high = 0;
        if (i2c_read_byte(fd, 0x18, &dist_low) < 0) return -1;
        if (i2c_read_byte(fd, 0x19, &dist_high) < 0) return -1;
        *distance = (dist_high << 8) | dist_low;
        return 0;
    }
    return 1;
}

static int mq_send_message(mqd_t mq, const char *message) {
    if (mq_send(mq, message, strlen(message) + 1, 0) == -1) {
        perror("mq_send failed");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer GPIO mode\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = MQ_MAX_MSG;
    attr.mq_msgsize = MQ_MSG_SIZE;
    attr.mq_curmsgs = 0;

    mq = mq_open(MQ_NAME, O_CREAT | O_RDWR, 0666, &attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open failed");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int distance;
        int ret = vl53l1x_read_distance(i2c_fd, &distance);

        if (ret == 0) {
            char message[64];
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            strftime(message, sizeof(message), "%Y-%m-%d %H:%M:%S", t);
            snprintf(message + strlen(message), sizeof(message) - strlen(message), " Distance: %d mm", distance);

            if (mq_send_message(mq, message) == 0) {
                printf("%s\n", message);
            }

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else if (ret < 0) {
            fprintf(stderr, "I2C communication error\n");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    gpioWrite(BUZZER_GPIO, 0);
    mq_close(mq);
    mq_unlink(MQ_NAME);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

