#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define THRESHOLD_DISTANCE_CM 30.0
#define TIMEOUT_US 30000
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile bool     echo_seen  = false;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
        echo_seen  = false;
    } else if (level == 0 && start_tick != 0) {
        end_tick = tick;
        echo_seen = true;
    }
}

static void trigger_pulse(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance(uint32_t start, uint32_t end)
{
    uint32_t diff = end - start;
    if (diff > (UINT32_MAX / 2))
        diff = start;
    double time_us = (double)diff;
    return (time_us * SPEED_OF_SOUND_CM_PER_S) / 2000000.0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();

        uint32_t waited = 0;
        while (!echo_seen && running && waited < TIMEOUT_US) {
            gpioDelay(100);
            waited += 100;
        }

        if (!running)
            break;

        if (!echo_seen) {
            printf("Error: sensor absent or echo timeout.\n");
            gpioWrite(BUZZER_PIN, 0);
        } else {
            double distance = calculate_distance(start_tick, end_tick);

            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                printf("Error: distance %.2f cm out of valid range [%.0f-%.0f].\n",
                       distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
                gpioWrite(BUZZER_PIN, 0);
            } else {
                printf("Distance: %.2f cm\n", distance);
                if (distance < THRESHOLD_DISTANCE_CM) {
                    gpioWrite(BUZZER_PIN, 1);
                } else {
                    gpioWrite(BUZZER_PIN, 0);
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
    printf("\nParking sensor stopped.\n");
    return EXIT_SUCCESS;
}

