/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM 23)
 *   ECHO -> GPIO 24 (physical pin 18, BCM 24)
 *
 * NOTE: The HC-SR04 echo line is 5 V.  The Pi GPIO is 3.3 V tolerant.
 *       A level-shifter (e.g., MAX3232 or similar) must be used to
 *       convert the 5 V echo signal to a 3.3 V input.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN        23
#define ECHO_PIN        24

#define TRIG_PULSE_US   10          /* 10 µs trigger pulse            */
#define SAMPLE_PERIOD_S 0.2         /* 200 ms between trigger pulses  */
#define ECHO_TIMEOUT_US 60000       /* 60 ms max echo wait            */
#define MIN_PULSE_US    100         /* reject noise below 100 µs      */
#define MAX_PULSE_US    30000       /* reject stalls above 30 ms       */
#define LOG_FILE        "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                      */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/*
 * pigpio tick is a 32-bit microsecond counter that wraps every ~72 min.
 * We compute the 32-bit delta with wraparound semantics so that
 *   tick_diff = (tick_end - tick_start) is always a valid duration.
 */
static inline uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;          /* unsigned subtraction wraps correctly */
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_distance(float distance_cm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    printf("[%s] Distance: %.2f cm\n", ts, distance_cm);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s, %.2f\n", ts, distance_cm);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Echo alert callback (runs in pigpio callback thread)                */
/* ------------------------------------------------------------------ */

/*
 * pigpio alert callbacks run in a dedicated thread, so we keep the
 * shared state here and perform minimal work.  We use a static flag
 * to track whether we have already seen a rising edge so we can
 * compute distance only on the falling edge.
 */
static volatile uint32_t g_rising_tick  = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_rising_seen  = false;

static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        g_rising_tick  = tick;
        g_rising_seen  = true;
    } else if (level == 0 && g_rising_seen) {
        /* Falling edge: end of echo pulse */
        g_falling_tick = tick;

        uint32_t pulse_us = tick_diff(g_rising_tick, g_falling_tick);

        if (pulse_us >= MIN_PULSE_US && pulse_us <= MAX_PULSE_US) {
            float distance_cm = (float)pulse_us / 58.0f;
            log_distance(distance_cm);
        } else {
            /* Rejection: warn and reset so we don't log spurious pulses */
            fprintf(stderr,
                    "Warning: Echo pulse %u µs out of range [%u, %u] - "
                    "possible noise or out-of-range object\n",
                    pulse_us, MIN_PULSE_US, MAX_PULSE_US);
        }

        g_rising_seen = false;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d.\n",
                ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) != 0) {
        fprintf(stderr, "Error: cannot initialise TRIG pin LOW.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append mode) --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error: cannot open log file '" LOG_FILE "'");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGTERM) failed");
    }

    /* --- Register echo alert callback --- */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Error: cannot register alert callback on GPIO %d.\n",
                ECHO_PIN);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG: GPIO %d (output, 10 µs pulse every %.0f s)\n",
           TRIG_PIN, SAMPLE_PERIOD_S);
    printf("  ECHO: GPIO %d (input, 5 V level-shifted to 3.3 V)\n", ECHO_PIN);
    printf("  Logging to '%s'.  Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        /* Generate 10 µs trigger pulse */
        if (gpioWrite(TRIG_PIN, 1) != 0) {
            fprintf(stderr, "Warning: failed to set TRIG HIGH.\n");
        }
        gpioDelay(TRIG_PULSE_US);
        if (gpioWrite(TRIG_PIN, 0) != 0) {
            fprintf(stderr, "Warning: failed to set TRIG LOW.\n");
        }

        /* Wait for the next trigger window (pigpio tick is microseconds) */
        gpioDelay((uint32_t)(SAMPLE_PERIOD_S * 1e6f));
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");

    /* Disable callback before tearing down */
    gpioSetAlertFunc(ECHO_PIN, NULL);

    /* Ensure trigger is LOW */
    gpioWrite(TRIG_PIN, 0);

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

