#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_OPEN 50
#define DISTANCE_THRESHOLD_CLOSE 60
#define LOG_FILE "parking_log.txt"
#define POLL_DELAY_US 100000
#define SERVO_OPEN_PULSE_US 1500
#define SERVO_CLOSE_PULSE_US 1000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static int gate_open = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int vl53l1x_init(int fd) {
    uint8_t model_id = 0;
    if (i2c_read_byte(fd, 0x010F, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }
    if (i2c_write_byte(fd, 0x0000, 0x01) != 0) return -1;
    if (i2c_write_byte(fd, 0x0001, 0x00) != 0) return -1;
    if (i2c_write_byte(fd, 0x0000, 0x00) != 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int fd, int *distance_mm) {
    uint8_t status = 0;
    if (i2c_read_byte(fd, 0x0013, &status) != 0) return -1;
    if ((status & 0x01) == 0) return 1;
    uint8_t dist_hi = 0, dist_lo = 0;
    if (i2c_read_byte(fd, 0x0096, &dist_hi) != 0) return -1;
    if (i2c_read_byte(fd, 0x0098, &dist_lo) != 0) return -1;
    *distance_mm = (dist_hi << 8) | dist_lo;
    return 0;
}

static void log_event(int distance_mm, int gate_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - Distance: %d mm, Gate: %s\n", timestamp, distance_mm, gate_state ? "OPEN" : "CLOSE");
    fflush(log_file);
}

static void control_servo(int gate_state) {
    if (gate_state) {
        gpioServo(SERVO_PIN, SERVO_OPEN_PULSE_US);
    } else {
        gpioServo(SERVO_PIN, SERVO_CLOSE_PULSE_US);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(SHUTDOWN_PIN, 1);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Smart Parking Gate System started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance_mm = 0;
        int ret = vl53l1x_read_distance(i2c_fd, &distance_mm);

        if (ret == 0) {
            if (distance_mm < DISTANCE_THRESHOLD_OPEN && !gate_open) {
                gate_open = 1;
                control_servo(gate_open);
                log_event(distance_mm, gate_open);
                printf("Gate OPENED (Distance: %d mm)\n", distance_mm);
            } else if (distance_mm > DISTANCE_THRESHOLD_CLOSE && gate_open) {
                gate_open = 0;
                control_servo(gate_open);
                log_event(distance_mm, gate_open);
                printf("Gate CLOSED (Distance: %d mm)\n", distance_mm);
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error: I2C read failed, retrying...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    control_servo(0);
    gpioServo(SERVO_PIN, 0);
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

