#define DISTANCE_THRESHOLD_HIGH 300
#define DISTANCE_READ_PIN 24
#define POLL_TIMEOUT_MS 100
#define MAX_RETRIES 3

/* VL53L1X register addresses */
#define VL53L1X_SOFT_RESET 0x000B
#define VL53L1X_SYSTEM_START 0x0000
#define VL53L1X_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data[1];
    if (i2cReadDevice(i2c_handle, data, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)data[0];
    return 0;
}

static int vl53l1x_read_reg16(uint8_t reg, uint16_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: I2C read16 from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(void) {
    if (vl53l1x_write_reg(VL53L1X_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000); /* 1 ms */
    if (vl53l1x_write_reg(VL53L1X_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000); /* 1 ms */
    return 0;
}

static int vl53l1x_start_measurement(void) {
    return vl53l1x_write_reg(VL53L1X_SYSTEM_START, 0x01);
