#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR     0x5A

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80

#define LED_PIN_0 17
#define LED_PIN_1 18
#define LED_PIN_2 27
#define LED_PIN_3 22

#define POLL_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg8(fd, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: MPR121 config write failed\n");
        return -1;
    }
    gpioDelay(10000);

    uint8_t cfg;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_CONFIG, &cfg) < 0) {
        fprintf(stderr, "Error: MPR121 config read failed\n");
        return -1;
    }
    if (cfg != 0x0C) {
        fprintf(stderr, "Error: MPR121 config verification failed (got 0x%02X)\n", cfg);
        return -1;
    }
    return 0;
}

static int mpr121_read_touch(int fd, uint16_t *touch_status) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void set_led_pattern(uint16_t touch_status) {
    gpioWrite(LED_PIN_0, (touch_status & 0x0001) ? 1 : 0);
    gpioWrite(LED_PIN_1, (touch_status & 0x0002) ? 1 : 0);
    gpioWrite(LED_PIN_2, (touch_status & 0x0004) ? 1 : 0);
    gpioWrite(LED_PIN_3, (touch_status & 0x0008) ? 1 : 0);
}

static void log_proximity_event(uint16_t touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Proximity Event: 0x%04X\n", timestamp, touch_status);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, MPR121_ELECTRODE_CONFIG, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN_0, 0);
    gpioWrite(LED_PIN_1, 0);
    gpioWrite(LED_PIN_2, 0);
    gpioWrite(LED_PIN_3, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: opening I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error: acquiring I2C bus access");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN_0, PI_OUTPUT);
    gpioSetMode(LED_PIN_1, PI_OUTPUT);
    gpioSetMode(LED_PIN_2, PI_OUTPUT);
    gpioSetMode(LED_PIN_3, PI_OUTPUT);

    log_file = fopen("proximity_log.txt", "a");
    if (!log_file) {
        perror("Error: opening log file");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity art installation started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch(i2c_fd, &touch_status) == 0) {
            set_led_pattern(touch_status);
            if (touch_status != 0) {
                log_proximity_event(touch_status);
            }
        } else {
            fprintf(stderr, "Error: I2C read failed, continuing...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

