#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"

#define SPEED_OF_SOUND_CM_S 343.0
#define MIN_DISTANCE_CM     2.0
#define MAX_DISTANCE_CM     400.0
#define TRIGGER_PULSE_US    10
#define ECHO_TIMEOUT_US     30000
#define LOOP_DELAY_US       1000000

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1;
    }
    gpioDelay(5);
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1;
    }
    return 0;
}

static int wait_for_echo_rising(uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start) > timeout_us) {
            return -1;
        }
    }
    return 0;
}

static int wait_for_echo_falling(uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start) > timeout_us) {
            return -1;
        }
    }
    return 0;
}

static double calculate_distance(uint32_t pulse_width_us)
{
    double time_s = (double)pulse_width_us / 1000000.0;
    return (time_s * SPEED_OF_SOUND_CM_S) / 2.0;
}

static int log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log, "%s,%.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Trigger pulse failed\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (wait_for_echo_rising(ECHO_TIMEOUT_US) != 0) {
            fprintf(stderr, "Timeout waiting for echo rising edge (sensor absent or no object)\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        uint32_t start = gpioTick();

        if (wait_for_echo_falling(ECHO_TIMEOUT_US) != 0) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        uint32_t end = gpioTick();
        uint32_t pulse_width = end - start;

        double distance = calculate_distance(pulse_width);

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Distance out of range: %.2f cm (pw=%u us)\n", distance, pulse_width);
            if (log_distance(-1.0) != 0) {
                fprintf(stderr, "Failed to log error entry\n");
            }
        } else {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Failed to log distance\n");
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

