#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* 30 ms (~4 m max range) */
#define LOG_FILE         "distance_log.txt"

/* Speed of sound at ~20 °C: 343 m/s = 0.0343 cm/µs */
#define SPEED_OF_SOUND_CM_PER_US 0.0343

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* ISR state — only accessed from pigpio callback context */
static volatile uint32_t echo_start_tick = 0;
static volatile uint32_t echo_end_tick   = 0;
static volatile int      echo_ready      = 0;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * ISR callback — runs in a pigpio worker thread.
 * pigpio tick is a 32-bit microsecond counter that wraps every ~71.6 min.
 */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        echo_start_tick = tick;
        echo_ready      = 0;
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_ready    = 1;
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance(uint32_t pulse_width_us)
{
    return (double)pulse_width_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);  /* let sensor settle */

    /* --- Register ISR on ECHO_PIN (both edges) --- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIGGER: GPIO%d | ECHO: GPIO%d\n", TRIGGER_PIN, ECHO_PIN);
    printf("  Logging to: %s\n", LOG_FILE);
    printf("  Press Ctrl+C to exit.\n");

    /* --- Main measurement loop --- */
    while (running) {
        trigger_sensor();

        /* Wait for echo_ready with timeout */
        uint32_t waited = 0;
        while (!echo_ready && running && waited < ECHO_TIMEOUT_US) {
            gpioDelay(100);  /* 100 µs */
            waited += 100;
        }

        if (!running) {
            break;
        }

        if (!echo_ready) {
            fprintf(stderr, "Warning: echo timeout (no object within range or sensor fault).\n");
            continue;
        }

        /*
         * pigpio tick is a 32-bit microsecond counter that wraps every ~71.6 min.
         * Handle the wrap-around case by subtracting the start from the end.
         */
        uint32_t pulse_width;
        if (echo_end_tick >= echo_start_tick) {
            pulse_width = echo_end_tick - echo_start_tick;
        } else {
            pulse_width = (0xFFFFFFFFu - echo_start_tick) + echo_end_tick + 1u;
        }

        /* Validate pulse width: 58 µs (~1 cm) to 25 ms (~4 m) */
        if (pulse_width < 58 || pulse_width > 25000) {
            fprintf(stderr, "Warning: invalid pulse width %u µs (out of range).\n",
                    pulse_width);
            continue;
        }

        double distance = calculate_distance(pulse_width);
        log_distance(distance);

        /*
         * Sleep 1 s between measurements.
         * gpioDelay is a busy-wait; use gpioDelay(1000000) for a 1 s sleep.
         * We use a busy-wait loop so the main loop can exit on signal.
         */
        uint32_t slept = 0;
        while (slept < 1000000 && running) {
            gpioDelay(100000);  /* 100 ms chunks */
            slept += 100000;
        }
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");

    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);  /* disable ISR */

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();

    printf("Done.\n");
    return EXIT_SUCCESS;
}

