#include <pigpio.h>
#include <vl53l1x_api.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define XSHUT_PIN      27
#define POLL_DELAY_US  100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(XSHUT_PIN, 0);
    gpioTerminate();
    VL53L1X_DeInit();
    closelog();
}

static int init_sensor(void) {
    if (gpioSetMode(XSHUT_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set XSHUT_PIN %d as output", XSHUT_PIN);
        return -1;
    }
    if (gpioWrite(XSHUT_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to set XSHUT_PIN high");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    if (VL53L1X_Init() != VL53L1X_ERROR_NONE) {
        syslog(LOG_ERR, "VL53L1X_Init failed");
        return -1;
    }

    if (VL53L1X_DataInit() != VL53L1X_ERROR_NONE) {
        syslog(LOG_ERR, "VL53L1X_DataInit failed");
        return -1;
    }

    return 0;
}

static int read_distance(uint16_t *distance_mm) {
    int status = VL53L1X_GetDistance(distance_mm);
    if (status != VL53L1X_ERROR_NONE) {
        syslog(LOG_ERR, "VL53L1X_GetDistance failed: %d", status);
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        syslog(LOG_ERR, "Sensor initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at bus %d addr 0x%02X: %d",
               I2C_BUS, I2C_ADDR, g_i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X sensor initialized on I2C bus %d addr 0x%02X",
           I2C_BUS, I2C_ADDR);

    while (g_running) {
        uint16_t distance = 0;
        int rc = read_distance(&distance);

        if (rc == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            syslog(LOG_INFO, "%s Distance: %u mm", ts, distance);
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }

        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

