#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20
#define POLL_INTERVAL_US 100000
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        log_message("I2C write failed");
        return -1;
    }
    return 0;
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *out) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        log_message("I2C write (reg select) failed");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        log_message("I2C read failed");
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint16_t model_id = 0;
    if (vl53l1x_read16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        log_message("Failed to read model ID");
        return -1;
    }
    if (model_id != 0xEA) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Unexpected model ID: 0x%04X", model_id);
        log_message(msg);
        return -1;
    }
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_distance_cm(int handle, int *distance_cm) {
    uint16_t status = 0;
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0) return -1;
    if (status != 0) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Range status error: 0x%04X", status);
        log_message(msg);
        return -1;
    }
    uint16_t raw = 0;
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_DISTANCE, &raw) != 0) return -1;
    *distance_cm = (int)(raw / 10);
    return 0;
}

static void control_gate(int distance_cm) {
    static int gate_open = 0;
    if (distance_cm < DISTANCE_THRESHOLD_CM && !gate_open) {
        if (gpioWrite(GATE_GPIO, 1) == 0) {
            gate_open = 1;
            log_message("Gate opened");
        } else {
            log_message("Failed to set gate GPIO high");
        }
    } else if (distance_cm >= DISTANCE_THRESHOLD_CM && gate_open) {
        if (gpioWrite(GATE_GPIO, 0) == 0) {
            gate_open = 0;
            log_message("Gate closed");
        } else {
            log_message("Failed to set gate GPIO low");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[64];
        snprintf(msg, sizeof(msg), "i2cOpen failed: %d", i2c_handle);
        log_message(msg);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        log_message("VL53L1X init failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        log_message("Failed to set gate GPIO mode");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GATE_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Gate control system started");

    while (!terminate) {
        int distance_cm = 0;
        if (read_distance_cm(i2c_handle, &distance_cm) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %d cm", distance_cm);
            log_message(msg);
            control_gate(distance_cm);
        } else {
            log_message("Failed to read distance");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(GATE_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    log_message("Gate control system stopped");
    return 0;
}

