#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define SAMPLE_INTERVAL_US 100000
#define MOVING_AVG_SIZE 5
#define SERVO_CENTER_US 1500
#define SERVO_RANGE_US 500
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define DISTANCE_MIN_CM 2.0
#define DISTANCE_MAX_CM 400.0
#define LOG_FILE "distance_log.csv"

static volatile uint32_t pulse_width = 0;
static volatile bool new_pulse = false;
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static double distance_buffer[MOVING_AVG_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static bool rising = true;

    if (level == 1) {
        start_tick = tick;
        rising = true;
    } else if (level == 0 && rising) {
        uint32_t diff = tick - start_tick;
        pulse_width = diff;
        new_pulse = true;
        rising = false;
    }
}

static double calculate_distance(uint32_t pulse_width_us) {
    if (pulse_width_us == 0) return -1.0;
    double time_s = (double)pulse_width_us / 1000000.0;
    double distance = (time_s * 34300.0) / 2.0;
    if (distance < DISTANCE_MIN_CM || distance > DISTANCE_MAX_CM) return -1.0;
    return distance;
}

static double moving_average(double new_value) {
    distance_buffer[buffer_index] = new_value;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;
    if (buffer_count < MOVING_AVG_SIZE) buffer_count++;
    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) sum += distance_buffer[i];
    return sum / buffer_count;
}

static int angle_to_pulse_width(int angle) {
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    return SERVO_CENTER_US + (angle * SERVO_RANGE_US / SERVO_MAX_ANGLE);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (gpioInitialise() >= 0) {
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance_cm,Servo_Angle_Deg\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to set SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_wait = gpioTick();
        while (running && !new_pulse) {
            if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) break;
            gpioDelay(100);
        }

        uint32_t pulse_us = 0;
        if (new_pulse) {
            pulse_us = pulse_width;
            new_pulse = false;
        }

        double distance = calculate_distance(pulse_us);
        if (distance < 0.0) distance = -1.0;
        double filtered_distance = moving_average(distance);

        int angle = (filtered_distance < 0.0) ? 90 : (int)((filtered_distance - DISTANCE_MIN_CM) / (DISTANCE_MAX_CM - DISTANCE_MIN_CM) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE));
        if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
        if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;

        int pulse_width_us = angle_to_pulse_width(angle);
        if (gpioServo(SERVO_PIN, pulse_width_us) != 0) {
            fprintf(stderr, "Servo API call failed\n");
        }

        time_t rawtime;
        time(&rawtime);
        struct tm *timeinfo = localtime(&rawtime);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f,%d\n", timestamp, filtered_distance, angle);
        fflush(log_file);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

