#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <stdint.h>
#include <getopt.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x53
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_LOG_FILE "proximity.log"
#define DEFAULT_GPIO_PIN 27
#define I2C_BUS 1

#define SI1102_REG_PART_ID 0x00
#define SI1102_REG_HW_ID 0x01
#define SI1102_REG_SEQ_ID 0x02
#define SI1102_REG_INT_CFG 0x03
#define SI1102_REG_INT_EN 0x04
#define SI1102_REG_INT_STATUS 0x05
#define SI1102_REG_PROX_DATA 0x06
#define SI1102_REG_PROX_DATA_LSB 0x07
#define SI1102_REG_COMMAND 0x08
#define SI1102_REG_RESPONSE 0x09
#define SI1102_REG_HOST_COMMAND 0x0A
#define SI1102_REG_HOST_RESPONSE 0x0B

#define SI1102_CMD_RESET 0x01
#define SI1102_CMD_PS_FORCE 0x05
#define SI1102_CMD_PS_AUTO 0x0D

static int i2c_handle = -1;
static FILE *log_file = NULL;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int gpio_pin = DEFAULT_GPIO_PIN;
static volatile sig_atomic_t program_running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, value=0x%02X, pigpio error=%d\n", reg, value, result);
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "I2C read error: reg=0x%02X, pigpio error=%d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg_lsb, uint16_t *value) {
    uint8_t lsb, msb;
    if (i2c_read_byte(handle, reg_lsb, &lsb) < 0) return -1;
    if (i2c_read_byte(handle, reg_lsb + 1, &msb) < 0) return -1;
    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int initialize_sensor(void) {
    uint8_t part_id, hw_id, seq_id;
    if (i2c_read_byte(i2c_handle, SI1102_REG_PART_ID, &part_id) < 0) return -1;
    if (i2c_read_byte(i2c_handle, SI1102_REG_HW_ID, &hw_id) < 0) return -1;
    if (i2c_read_byte(i2c_handle, SI1102_REG_SEQ_ID, &seq_id) < 0) return -1;
    printf("Si1102 Part ID: 0x%02X, HW ID: 0x%02X, Seq ID: 0x%02X\n", part_id, hw_id, seq_id);

    if (i2c_write_byte(i2c_handle, SI1102_REG_COMMAND, SI1102_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_byte(i2c_handle, SI1102_REG_INT_CFG, 0x01) < 0) return -1;
    if (i2c_write_byte(i2c_handle, SI1102_REG_INT_EN, 0x01) < 0) return -1;
    if (i2c_write_byte(i2c_handle, SI1102_REG_COMMAND, SI1102_CMD_PS_AUTO) < 0) return -1;

    return 0;
}

static void log_proximity_data(int proximity_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    const char *status;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (proximity_value <= threshold) {
        status = "SAFE";
    } else {
        status = "ALERT";
    }

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %s\n", timestamp, proximity_value, status);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

static void proximity_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    uint16_t proximity_value;
    if (i2c_read_word(i2c_handle, SI1102_REG_PROX_DATA, &proximity_value) == 0) {
        log_proximity_data((int)proximity_value);
    } else {
        fprintf(stderr, "Failed to read proximity data from sensor\n");
    }
    i2c_write_byte(i2c_handle, SI1102_REG_INT_STATUS, 0x01);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:a:h")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                if (threshold < 0) {
                    fprintf(stderr, "Invalid threshold value. Using default: %d\n", DEFAULT_THRESHOLD);
                    threshold = DEFAULT_THRESHOLD;
                }
                break;
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                if (i2c_address < 0 || i2c_address > 0x7F) {
                    fprintf(stderr, "Invalid I2C address. Using default: 0x%02X\n", DEFAULT_I2C_ADDRESS);
                    i2c_address = DEFAULT_I2C_ADDRESS;
                }
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-a i2c_address]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(gpio_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(gpio_pin, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-down\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(gpio_pin, RISING_EDGE, 0, proximity_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(DEFAULT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity monitoring started. Threshold: %d, I2C Address: 0x%02X, GPIO Pin: %d\n", threshold, i2c_address, gpio_pin);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

