    if (gpioSetISRFuncEx(gpio_pin, RISING_EDGE, 0, proximity_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(DEFAULT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity monitoring started. Threshold: %d, I2C Address: 0x%02X, GPIO Pin: %d\n", threshold, i2c_address, gpio_pin);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

