#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM         2.0
#define MAX_DISTANCE_CM         200.0
#define MIN_FREQUENCY_HZ        200.0
#define MAX_FREQUENCY_HZ        2000.0
#define PWM_RANGE               1000
#define PWM_DUTY_50_PERCENT     500
#define ECHO_TIMEOUT_US         200000
#define TRIGGER_PULSE_US        10
#define LOOP_DELAY_US           50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint64_t now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static int set_pwm_frequency(int freq_hz) {
    if (freq_hz <= 0) {
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_PIN, freq_hz) < 0) {
        return -1;
    }
    if (gpioPWM(PWM_PIN, PWM_DUTY_50_PERCENT) < 0) {
        return -1;
    }
    return 0;
}

static int read_distance(float *distance_cm) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        return -1;
    }
    gpioDelay(2);

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        return -1;
    }

    uint64_t start_wait = now_us();
    while (gpioRead(ECHO_PIN) == 0) {
        if (now_us() - start_wait > ECHO_TIMEOUT_US) {
            return -1;
        }
    }
    uint64_t echo_start = now_us();

    while (gpioRead(ECHO_PIN) == 1) {
        if (now_us() - echo_start > ECHO_TIMEOUT_US) {
            return -1;
        }
    }
    uint64_t echo_end = now_us();

    uint64_t pulse_us = echo_end - echo_start;
    *distance_cm = (float)pulse_us * SPEED_OF_SOUND_CM_PER_S / 2000000.0;
    return 0;
}

static float distance_to_frequency(float distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) {
        return MIN_FREQUENCY_HZ;
    }
    if (distance_cm > MAX_DISTANCE_CM) {
        return MAX_FREQUENCY_HZ;
    }
    float log_distance = log10f(distance_cm);
    float log_min = log10f(MIN_DISTANCE_CM);
    float log_max = log10f(MAX_DISTANCE_CM);
    float freq_ratio = (log_distance - log_min) / (log_max - log_min);
    return MIN_FREQUENCY_HZ + freq_ratio * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty cycle.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler.\n");
    }

    float last_frequency = MIN_FREQUENCY_HZ;

    while (g_running) {
        float distance;
        if (read_distance(&distance) == 0) {
            float freq = distance_to_frequency(distance);
            if (set_pwm_frequency((int)freq) == 0) {
                last_frequency = freq;
            } else {
                fprintf(stderr, "Warning: failed to set PWM frequency (%.1f Hz).\n", freq);
            }
        } else {
            fprintf(stderr, "Warning: distance read failed or timeout.\n");
            if (set_pwm_frequency((int)last_frequency) != 0) {
                fprintf(stderr, "Warning: failed to restore PWM frequency.\n");
            }
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

