#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"
#define READ_DELAY_US 100000
#define MIN_DISTANCE_MM 200
#define MAX_DISTANCE_MM 5000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_spi(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d).\n", spi_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_distance(int *distance_mm) {
    char tx_buf[4] = {0x01, 0x02, 0x03, 0x04};
    char rx_buf[4] = {0};
    gpioWrite(CS_PIN, 0);
    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    gpioWrite(CS_PIN, 1);
    if (ret != 4) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d).\n", ret);
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx_buf[0] << 24) |
                   ((uint32_t)(uint8_t)rx_buf[1] << 16) |
                   ((uint32_t)(uint8_t)rx_buf[2] << 8)  |
                   ((uint32_t)(uint8_t)rx_buf[3]);
    *distance_mm = (int)raw;
    if (*distance_mm < MIN_DISTANCE_MM || *distance_mm > MAX_DISTANCE_MM) {
        fprintf(stderr, "Warning: Distance out of range (%d mm).\n", *distance_mm);
        return -1;
    }
    return 0;
}

static void log_data(int distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%d\n", timestamp, distance_mm);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }
    if (initialize_spi() != 0) {
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return 1;
    }
    fprintf(log_file, "# timestamp,distance_mm\n");
    fflush(log_file);
    while (running) {
        int distance_mm;
        if (read_distance(&distance_mm) == 0) {
            log_data(distance_mm);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }
        gpioDelay(READ_DELAY_US);
    }
    cleanup();
    return 0;
}

