#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_I2C_ADDR 0x55
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define SI1175_REG_COMMAND 0x46
#define SI1175_CMD_ALS_FORCE 0x0A
#define SI1175_CMD_RESET 0x01
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_byte: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_byte: write reg failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("i2c_read_byte: read failed");
        return -1;
    }
    return 0;
}

static int si1175_reset(int fd) {
    if (i2c_write_byte(fd, SI1175_REG_COMMAND, SI1175_CMD_RESET) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int si1175_force_als(int fd) {
    return i2c_write_byte(fd, SI1175_REG_COMMAND, SI1175_CMD_ALS_FORCE);
}

static int si1175_read_als(int fd, uint16_t *als_value) {
    uint8_t lo, hi;
    if (i2c_read_byte(fd, SI1175_REG_ALS_VIS_DATA0, &lo) < 0) return -1;
    if (i2c_read_byte(fd, SI1175_REG_ALS_VIS_DATA1, &hi) < 0) return -1;
    *als_value = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int log_data(FILE *fp, uint16_t als_value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r failed");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, als_value) < 0) {
        perror("fprintf failed");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush failed");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("Failed to open I2C bus " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / talk to slave");
        cleanup();
        return EXIT_FAILURE;
    }

    if (si1175_reset(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor reset failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Failed to open log file " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        if (fprintf(g_log_fp, "timestamp,als_visible\n") < 0) {
            perror("Failed to write CSV header");
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_fp);
    }

    printf("Si1175 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (si1175_force_als(g_i2c_fd) < 0) {
            fprintf(stderr, "Failed to force ALS measurement\n");
        } else {
            usleep(10000);
            uint16_t als_value = 0;
            if (si1175_read_als(g_i2c_fd, &als_value) < 0) {
                fprintf(stderr, "Failed to read ALS value\n");
            } else {
                if (log_data(g_log_fp, als_value) < 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

