#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdint.h>
#include <stdbool.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define DISTANCE_THRESHOLD 20.0
#define SPEED_OF_SOUND 34300.0
#define TIMEOUT_US 30000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile bool echo_received = false;
static volatile bool trigger_sent = false;
static volatile bool running = true;

static void signal_handler(int sig) {
    (void)sig;
    running = false;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        start_tick = tick;
        echo_received = false;
        trigger_sent = false;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = true;
    }
}

static double calculate_distance(uint32_t pulse_width_us) {
    return (pulse_width_us * SPEED_OF_SOUND) / 2000000.0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: could not register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on ECHO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Error: failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    while (running) {
        trigger_sensor();
        trigger_sent = true;

        uint32_t wait_start = gpioTick();
        while (running && !echo_received && (gpioTick() - wait_start) < TIMEOUT_US) {
            gpioDelay(100);
        }

        if (!running) {
            break;
        }

        if (!echo_received) {
            fprintf(stderr, "Warning: echo timeout\n");
            gpioWrite(BUZZER_PIN, 0);
            continue;
        }

        uint32_t pulse_width = end_tick - start_tick;
        double distance = calculate_distance(pulse_width);

        printf("Distance: %.2f cm\n", distance);

        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }

        gpioDelay(1000000);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

