    while (gpioRead(ECHO_PIN) == 0) {
        start_tick = gpioTick();
        if (start_tick == 0) return -1.0;
        if (++timeout > ECHO_TIMEOUT_US) return -1.0;
    }

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if (end_tick == 0) return -1.0;
        if (++timeout > ECHO_TIMEOUT_US) return -1.0;
    }

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0;
    return distance;
}

static int calculate_servo_angle(double distance) {
    if (distance < 0) return -1;
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    double angle = MIN_ANGLE + (MAX_ANGLE - MIN_ANGLE) *
                   (1.0 - (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));

    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;

    return (int)round(angle);
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) return -1;
    int pulse_width = MIN_PULSE_WIDTH + (int)((double)angle / 180.0 * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize trigger pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle = calculate_servo_angle(distance);
        if (angle < 0) {
            fprintf(stderr, "Error: Servo angle calculation failed\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Error: Failed to set servo angle\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        printf("Distance: %.2f cm, Servo Angle: %d degrees\n", distance, angle);
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

