#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_CLOSE 200
#define DISTANCE_THRESHOLD_FAR 250
#define SERVO_OPEN_US 1000
#define SERVO_CLOSE_US 2000
#define POLL_DELAY_US 50000
#define LOG_FILE "gate_log.txt"

#define REG_MODEL_ID 0x010F
#define REG_SYSTEM_START 0x0000
#define REG_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(uint16_t reg, uint8_t val) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    if (i2cWriteDevice(i2c_handle, buf, 3) != 3) return -1;
    return 0;
}

static int read_reg16(uint16_t reg, uint8_t *val) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) return -1;
    if (i2cReadDevice(i2c_handle, (char *)val, 1) != 1) return -1;
    return 0;
}

static int init_sensor(void) {
    uint8_t model_id;
    if (read_reg16(REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }
    if (write_reg16(0x0000, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to stop ranging\n");
        return -1;
    }
    if (write_reg16(0x0001, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to clear interrupts\n");
        return -1;
    }
    if (write_reg16(0x0001, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance) {
    uint8_t status;
    if (read_reg16(REG_RANGE_STATUS, &status) != 0) return -1;
    if ((status & 0x01) == 0) return 1;
    uint8_t dist_hi, dist_lo;
    if (read_reg16(REG_RESULT_DISTANCE, &dist_hi) != 0) return -1;
    if (read_reg16(REG_RESULT_DISTANCE + 1, &dist_lo) != 0) return -1;
    *distance = ((uint16_t)dist_hi << 8) | dist_lo;
    return 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static void set_servo(int pulse_us) {
    if (pulse_us < 500) pulse_us = 500;
    if (pulse_us > 2500) pulse_us = 2500;
    gpioServo(SERVO_PIN, pulse_us);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (init_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    set_servo(SERVO_CLOSE_US);
    log_event("System started");
    int gate_open = 0;
    while (running) {
        uint16_t distance;
        int rc = read_distance(&distance);
        if (rc == 0) {
            int new_state = (distance > DISTANCE_THRESHOLD_FAR) ? 1 : 0;
            if (new_state != gate_open) {
                set_servo(new_state ? SERVO_OPEN_US : SERVO_CLOSE_US);
                gate_open = new_state;
                log_event(gate_open ? "Gate opened" : "Gate closed");
            }
        } else if (rc < 0) {
            fprintf(stderr, "Warning: I2C read error\n");
        }
        gpioDelay(POLL_DELAY_US);
    }
    set_servo(SERVO_CLOSE_US);
    gpioServo(SERVO_PIN, 0);
    log_event("System stopped");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

