#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE_DEG   0
#define MAX_ANGLE_DEG   180
#define MIN_DISTANCE_ANGLE 20.0
#define MAX_DISTANCE_ANGLE 200.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000
#define LOOP_DELAY_US    100000
#define SERVO_MIN_US     500
#define SERVO_MAX_US     2500

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_us(uint32_t us)
{
    struct timespec ts = {
        .tv_sec  = (time_t)(us / 1000000U),
        .tv_nsec = (long)((us % 1000000U) * 1000L)
    };
    nanosleep(&ts, NULL);
}

static void sleep_ms(uint32_t ms)
{
    sleep_us(ms * 1000U);
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    sleep_us(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void)
{
    trigger_sensor();

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US)
            return -1.0;
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US)
            return -1.0;
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    return (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static int angle_from_distance(double distance)
{
    if (distance < 0.0)
        return -1;
    if (distance < MIN_DISTANCE_CM)
        distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM)
        distance = MAX_DISTANCE_CM;

    double angle = MIN_ANGLE_DEG +
        (distance - MIN_DISTANCE_CM) *
        (MAX_ANGLE_DEG - MIN_ANGLE_DEG) /
        (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    if (angle < MIN_ANGLE_DEG) angle = MIN_ANGLE_DEG;
    if (angle > MAX_ANGLE_DEG) angle = MAX_ANGLE_DEG;
    return (int)(angle + 0.5);
}

static int set_servo_angle(int angle)
{
    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        return -1;
    }
    int pulse_us = SERVO_MIN_US +
        (int)((double)angle / MAX_ANGLE_DEG *
              (SERVO_MAX_US - SERVO_MIN_US));
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for TRIGGER_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for ECHO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for SERVO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    sleep_ms(50);

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Servo: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, SERVO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: sensor timeout (no echo within %d us)\n",
                    ECHO_TIMEOUT_US);
        } else {
            int angle = angle_from_distance(distance);
            if (angle < 0) {
                fprintf(stderr, "Warning: invalid angle from distance %.2f cm\n",
                        distance);
            } else {
                printf("Distance: %.2f cm -> Servo Angle: %d degrees\n",
                       distance, angle);
                if (set_servo_angle(angle) != 0) {
                    fprintf(stderr, "Error: failed to set servo angle\n");
                }
            }
        }

        sleep_ms(LOOP_DELAY_US / 1000U);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

