    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for TRIGGER_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for ECHO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for SERVO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    sleep_ms(50);

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Servo: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, SERVO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: sensor timeout (no echo within %d us)\n",
                    ECHO_TIMEOUT_US);
        } else {
            int angle = angle_from_distance(distance);
            if (angle < 0) {
                fprintf(stderr, "Warning: invalid angle from distance %.2f cm\n",
                        distance);
            } else {
                printf("Distance: %.2f cm -> Servo Angle: %d degrees\n",
                       distance, angle);
                if (set_servo_angle(angle) != 0) {
                    fprintf(stderr, "Error: failed to set servo angle\n");
                }
            }
        }

        sleep_ms(LOOP_DELAY_US / 1000U);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

