#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define SI7005_CONFIG_REG 0x1F
#define SI7005_MEAS_TEMP_HOLD 0xE5
#define SI7005_MEAS_HUM_HOLD 0xE5
#define SI7005_READ_TEMP_PREV 0xE0
#define SI7005_READ_HUM_PREV 0xE0
#define SI7005_READ_ID1 0xFA
#define SI7005_READ_ID2 0x0F
#define SI7005_READ_ID3 0xC9
#define SI7005_READ_ID4 0x22
#define CONVERSION_DELAY_US 10000
#define LOOP_DELAY_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI7005_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint8_t reg, uint16_t *value) {
    char buf[2];
    int rc;

    rc = i2cWriteByte(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    rc = i2cReadDevice(i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading register 0x%02X (got %d bytes): %d\n", reg, rc, rc);
        return -1;
    }

    *value = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_temperature(float *temperature) {
    uint16_t raw;
    if (read_sensor_data(SI7005_MEAS_TEMP_HOLD, &raw) != 0) {
        return -1;
    }
    *temperature = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(float *humidity) {
    uint16_t raw;
    if (read_sensor_data(SI7005_MEAS_HUM_HOLD, &raw) != 0) {
        return -1;
    }
    *humidity = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    return 0;
}

static int verify_sensor(void) {
    char id[4];
    int rc;

    rc = i2cWriteByte(i2c_handle, SI7005_READ_ID1);
    if (rc < 0) {
        fprintf(stderr, "Error writing ID1 read: %d\n", rc);
        return -1;
    }
    gpioDelay(10000);

    rc = i2cReadDevice(i2c_handle, id, 4);
    if (rc != 4) {
        fprintf(stderr, "Error reading ID block: got %d bytes\n", rc);
        return -1;
    }

    if ((uint8_t)id[0] != SI7005_READ_ID1 ||
        (uint8_t)id[1] != SI7005_READ_ID2 ||
        (uint8_t)id[2] != SI7005_READ_ID3 ||
        (uint8_t)id[3] != SI7005_READ_ID4) {
        fprintf(stderr, "Sensor ID mismatch: got 0x%02X 0x%02X 0x%02X 0x%02X, expected 0x%02X 0x%02X 0x%02X 0x%02X\n",
                (uint8_t)id[0], (uint8_t)id[1], (uint8_t)id[2], (uint8_t)id[3],
                SI7005_READ_ID1, SI7005_READ_ID2, SI7005_READ_ID3, SI7005_READ_ID4);
        return -1;
    }

    rc = i2cWriteByte(i2c_handle, SI7005_CONFIG_REG);
    if (rc < 0) {
        fprintf(stderr, "Error writing config register: %d\n", rc);
        return -1;
    }
    gpioDelay(10000);

    rc = i2cWriteByte(i2c_handle, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error writing config value: %d\n", rc);
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_sensor() != 0) {
        fprintf(stderr, "Sensor verification failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7005 sensor initialized successfully.\n");

    while (running) {
        float temperature, humidity;

        if (read_temperature(&temperature) == 0 &&
            read_humidity(&humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-initializing I2C...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
            }
            if (verify_sensor() != 0) {
                fprintf(stderr, "Sensor verification failed after re-init. Exiting.\n");
                break;
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

