#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_TEMP_OUT_H   0x41
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_WHO_AM_I     0x75

#define MPU6050_WHO_AM_I_VAL     0x68

#define I2C_BUS 1
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int16_t combine_le(const uint8_t *buf, int idx)
{
    return (int16_t)((uint16_t)buf[idx] | ((uint16_t)buf[idx + 1] << 8));
}

static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz,
                            int16_t *temp)
{
    uint8_t buf[14];

    if (i2cReadI2CBlockData(handle, MPU6050_REG_ACCEL_XOUT_H,
                            (char *)buf, sizeof(buf)) != (int)sizeof(buf)) {
        fprintf(stderr, "Error: failed to read 14-byte data block: %s\n",
                strerror(errno));
        return -1;
    }

    *ax  = combine_le(buf, 0);
    *ay  = combine_le(buf, 2);
    *az  = combine_le(buf, 4);
    *temp = combine_le(buf, 6);
    *gx  = combine_le(buf, 8);
    *gy  = combine_le(buf, 10);
    *gz  = combine_le(buf, 12);
    return 0;
}

static int initialize_mpu6050(int handle)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2cWriteByteData(handle, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1: %s\n",
                strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Sample rate divider = 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (i2cWriteByteData(handle, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV: %s\n",
                strerror(errno));
        return -1;
    }

    /* DLPF_CFG = 3 → internal 20 Hz bandwidth, delay 4 ms */
    if (i2cWriteByteData(handle, MPU6050_REG_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Error: failed to write CONFIG: %s\n",
                strerror(errno));
        return -1;
    }

    /* Gyro full-scale range = 250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG: %s\n",
                strerror(errno));
        return -1;
    }

    /* Accel full-scale range = 2 g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write ACCEL_CONFIG: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int16_t ax, ay, az, gx, gy, gz, temp;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at MPU-6050 address --- */
    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d): %s\n",
                g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor identity --- */
    int who = i2cReadByteData(g_i2c_handle, MPU6050_REG_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I: %s\n",
                strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, MPU6050_WHO_AM_I_VAL);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor --- */
    if (initialize_mpu6050(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction failed: %s\n", strerror(errno));
    }

    printf("MPU-6050 initialized on I2C bus %d, address 0x%02X.\n",
           I2C_BUS, MPU6050_ADDR);
    printf("Logging accelerometer (g) and gyroscope (deg/s) every 100 ms.\n");
    printf("Press Ctrl+C to stop.\n\n");
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz, &temp) == 0) {
            printf("Accel X: %6d  Y: %6d  Z: %6d  g\n", ax, ay, az);
            printf("Gyro  X: %6d  Y: %6d  Z: %6d  deg/s\n", gx, gy, gz);
            printf("Temp  : %6d  C\n\n", temp);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

