    gpioDelay(100000); /* 100 ms settle time */

    /* Sample rate divider = 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (i2cWriteByteData(handle, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV: %s\n",
                strerror(errno));
        return -1;
    }

    /* DLPF_CFG = 3 → internal 20 Hz bandwidth, delay 4 ms */
    if (i2cWriteByteData(handle, MPU6050_REG_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Error: failed to write CONFIG: %s\n",
                strerror(errno));
        return -1;
    }

    /* Gyro full-scale range = 250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG: %s\n",
                strerror(errno));
        return -1;
    }

    /* Accel full-scale range = 2 g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write ACCEL_CONFIG: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int16_t ax, ay, az, gx, gy, gz, temp;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at MPU-6050 address --- */
    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d): %s\n",
                g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor identity --- */
    int who = i2cReadByteData(g_i2c_handle, MPU6050_REG_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I: %s\n",
                strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, MPU6050_WHO_AM_I_VAL);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor --- */
    if (initialize_mpu6050(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction failed: %s\n", strerror(errno));
    }

    printf("MPU-6050 initialized on I2C bus %d, address 0x%02X.\n",
           I2C_BUS, MPU6050_ADDR);
    printf("Logging accelerometer (g) and gyroscope (deg/s) every 100 ms.\n");
    printf("Press Ctrl+C to stop.\n\n");
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz, &temp) == 0) {
            printf("Accel X: %6d  Y: %6d  Z: %6d  g\n", ax, ay, az);
            printf("Gyro  X: %6d  Y: %6d  Z: %6d  deg/s\n", gx, gy, gz);
            printf("Temp  : %6d  C\n\n", temp);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

