#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT40_ADDR     0x44
#define MEASURE_CMD    0x2408  /* high repeatability, clock stretching disabled */
#define MEASURE_DELAY_US 10000 /* 10 ms */
#define SAMPLE_PERIOD_S 5
#define READ_RETRIES   3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* CRC-8, polynomial 0x31, init 0xFF, as per Sensirion SHT40 datasheet */
static uint8_t sht40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int open_i2c(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, SHT40_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sht40(float *temperature, float *humidity) {
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t buf[6];

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing measurement command to SHT40\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error reading 6 bytes from SHT40\n");
        return -1;
    }

    if (sht40_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                sht40_crc8(buf, 2), buf[2]);
        return -1;
    }
    if (sht40_crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                sht40_crc8(buf + 3, 2), buf[5]);
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity   = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (open_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temperature, humidity;
        int ok = 0;

        for (int attempt = 0; attempt < READ_RETRIES && g_running; attempt++) {
            if (read_sht40(&temperature, &humidity) == 0) {
                ok = 1;
                break;
            }
            if (open_i2c() != 0) {
                fprintf(stderr, "Failed to re-open I2C after error\n");
                break;
            }
            gpioDelay(100000); /* 100 ms backoff before retry */
        }

        if (ok) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "All %d read attempts failed; continuing to retry.\n",
                    READ_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_PERIOD_S * 10 && g_running; s++) {
            gpioDelay(100000);
        }
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

