#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[3];
    if (read(fd, buf, 3) != 3) {
        return -1;
    }
    *value = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static float convert_temp(uint16_t raw) {
    return (float)raw * 0.02 - 273.15;
}

static int log_temperature(FILE *fp, float ambient, float object) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        return -1;
    }
    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, ambient, object) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen log file");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw_ambient = 0, raw_object = 0;
        int err = 0;

        if (i2c_read_reg16(fd, AMBIENT_TEMP_REG, &raw_ambient) != 0) {
            fprintf(stderr, "Error reading ambient temperature\n");
            err = 1;
        }

        if (i2c_read_reg16(fd, OBJECT_TEMP_REG, &raw_object) != 0) {
            fprintf(stderr, "Error reading object temperature\n");
            err = 1;
        }

        if (err) {
            fprintf(stderr, "Sensor read error, skipping log entry\n");
        } else {
            float ambient = convert_temp(raw_ambient);
            float object = convert_temp(raw_object);
            if (log_temperature(fp, ambient, object) != 0) {
                fprintf(stderr, "Error writing to log file\n");
            }
        }

        sleep(READ_INTERVAL_SEC);
    }

    fclose(fp);
    close(fd);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

