#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define STS30_ADDR 0x44
#define I2C_BUS 1
#define SAMPLE_INTERVAL_SEC 5
#define MEAS_DELAY_MS 10
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (error_log_file) {
        fprintf(error_log_file, "%s: %s\n", timestamp, message);
        fflush(error_log_file);
    }
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", STS30_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char cmd[2] = {0x36, 0x1B};
    char buf[3];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        log_error("Failed to write measurement command to STS30");
        return -1;
    }

    gpioDelay(MEAS_DELAY_MS * 1000);

    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        log_error("Failed to read temperature data from STS30");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)(buf[0] & 0x7F) << 8) | (uint8_t)buf[1];
    *temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);
    return 0;
}

static int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file);
        return 0;
    }
    log_error("Log file is not open.");
    return -1;
}

static void cleanup(void) {
