#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_I2C_ADDR 0x22
#define LOG_FILE "pressure_log.csv"
#define MEASUREMENT_INTERVAL_SEC 1
#define MEASUREMENT_DELAY_MS 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, int len) {
    if (write(fd, cmd, len) != len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sdp810(int fd) {
    uint8_t cmd[2] = {0x36, 0x2F};
    if (i2c_write_cmd(fd, cmd, 2) < 0) return -1;
    usleep(10000);
    cmd[0] = 0x36; cmd[1] = 0x2E;
    if (i2c_write_cmd(fd, cmd, 2) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_sdp810(int fd, float *pressure, float *temperature) {
    uint8_t cmd[2] = {0x36, 0x08};
    if (i2c_write_cmd(fd, cmd, 2) < 0) return -1;
    usleep(MEASUREMENT_DELAY_MS * 1000);

    uint8_t data[9];
    if (i2c_read_data(fd, data, 9) < 0) return -1;

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Scale factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale_factor = (int16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / (float)scale_factor;
    return 0;
}

static int log_data(const char *filename, float pressure, float temperature) {
    int need_header = 0;
    FILE *check = fopen(filename, "r");
    if (check == NULL) {
        need_header = 1;
    } else {
        fclose(check);
    }

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    if (need_header) {
        fprintf(fp, "timestamp,pressure_pa,temperature_c\n");
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_sdp810(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize SDP810\n");
        close(i2c_fd);
        return 1;
    }

    printf("SDP810 initialized. Logging to %s\n", LOG_FILE);

    while (running) {
        float pressure, temperature;
        if (read_sdp810(i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(LOG_FILE, pressure, temperature) == 0) {
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            } else {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(MEASUREMENT_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

