#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x36
#define LOG_FILE       "airflow.log"
#define SAMPLE_US      100000   /* 100 ms */
#define MEAS_DELAY_US  1000     /* 1 ms  */
#define MAX_RETRIES    3
#define RETRY_BASE_US  1000     /* 1 s  */

/* SDP31 continuous measurement command (mass flow / differential pressure) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x15 };

static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/*
 * Write a 2-byte command to the SDP31.
 * Returns 0 on success, -1 on failure.
 */
static int sdp31_write_cmd(int handle, const uint8_t *cmd, int len)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteDevice(handle, (char *)cmd, len);
        if (rc == 0)
            return 0;
        fprintf(stderr, "i2cWriteDevice failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_BASE_US * (1 << attempt) * 1000);
    }
    return -1;
}

/*
 * Read 6 bytes from the SDP31.
 * Returns 0 on success, -1 on failure.
 */
static int sdp31_read_data(int handle, uint8_t *buf, int len)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len)
            return 0;
        fprintf(stderr, "i2cReadDevice failed (attempt %d/%d): got %d, expected %d: %s\n",
                attempt + 1, MAX_RETRIES, rc, len, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_BASE_US * (1 << attempt) * 1000);
    }
    return -1;
}

/*
 * Convert raw differential pressure (signed 16-bit, 1 LSB = 0.0045 Pa)
 * to pascals.
 */
static float raw_to_pressure(int16_t raw)
{
    return (float)raw * 0.0045f;
}

/*
 * Convert raw temperature (signed 16-bit, 1 LSB = 0.001 °C)
 * to degrees Celsius.
 */
static float raw_to_temperature(int16_t raw)
{
    return (float)raw * 0.001f;
}

/*
 * Append a timestamped CSV line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* --- Start continuous measurement --- */
    if (sdp31_write_cmd(i2c_handle, CMD_CONT_MEAS, 2) != 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop --- */
    while (!terminate) {
        uint8_t buf[6];

        /* Wait for the first measurement to be ready */
        gpioDelay(MEAS_DELAY_US * 1000);

        if (sdp31_read_data(i2c_handle, buf, 6) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        /*
         * SDP31 data format (MSB first):
         *   buf[0..1]  pressure, 1 LSB = 0.0045 Pa
         *   buf[2]     CRC for pressure
         *   buf[3..4]  temperature, 1 LSB = 0.001 °C
         *   buf[5]     CRC for temperature
         *
         * CRC-8 polynomial 0x31, init 0xFF, no reflection.
         */
        uint8_t crc_p = buf[2];
        uint8_t crc_t = buf[5];
        uint8_t calc_p = 0xFF;
        uint8_t calc_t = 0xFF;
        for (int i = 0; i < 2; i++) {
            calc_p ^= buf[i];
            for (int b = 0; b < 8; b++)
                calc_p = (calc_p & 0x80) ? (calc_p << 1) ^ 0x31 : (calc_p << 1);
        }
        for (int i = 3; i < 5; i++) {
            calc_t ^= buf[i];
            for (int b = 0; b < 8; b++)
                calc_t = (calc_t & 0x80) ? (calc_t << 1) ^ 0x31 : (calc_t << 1);
        }

        if (crc_p != calc_p || crc_t != calc_t) {
            fprintf(stderr, "CRC mismatch: pressure=0x%02X/0x%02X, temperature=0x%02X/0x%02X\n",
                    crc_p, calc_p, crc_t, calc_t);
            gpioDelay(SAMPLE_US);
            continue;
        }

        int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);

        float pressure = raw_to_pressure(raw_p);
        float temperature = raw_to_temperature(raw_t);

        if (log_data(log_file, pressure, temperature) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- Cleanup --- */
    fprintf(stderr, "Shutting down...\n");
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    if (log_file != NULL)
        fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

