#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define LOG_FILE "sensor_data.txt"
#define SAMPLE_INTERVAL_US 5000000
#define MEASUREMENT_TIMEOUT_US 20000

/* Si7015 No Hold Master commands */
#define CMD_MEASURE_TEMP_HOLD  0xE3
#define CMD_MEASURE_HUM_HOLD   0xE5
#define CMD_RESET              0xFE

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (pigpio error %d)\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int reset_sensor(void) {
    char cmd = CMD_RESET;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: reset write failed\n");
        return -1;
    }
    gpioDelay(15000); /* 15 ms reset wait */
    return 0;
}

static int read_measurement(uint8_t cmd, uint16_t *raw) {
    char wbuf[1] = { (char)cmd };
    char rbuf[2];
    int rc;

    rc = i2cWriteDevice(i2c_handle, wbuf, 1);
    if (rc != 0) {
        fprintf(stderr, "Error: write cmd 0x%02X failed (rc=%d)\n", cmd, rc);
        return -1;
    }

    /* Poll for measurement ready (max ~20 ms) */
    for (int i = 0; i < 20; i++) {
        gpioDelay(1000);
        rc = i2cReadDevice(i2c_handle, rbuf, 2);
        if (rc == 2) {
            *raw = ((uint16_t)(uint8_t)rbuf[0] << 8) | (uint8_t)rbuf[1];
            return 0;
        }
        if (rc < 0) {
            fprintf(stderr, "Error: read poll failed (rc=%d)\n", rc);
            return -1;
        }
    }
    fprintf(stderr, "Error: measurement timeout for cmd 0x%02X\n", cmd);
    return -1;
}

static int read_temperature(float *temp) {
    uint16_t raw;
    if (read_measurement(CMD_MEASURE_TEMP_HOLD, &raw) != 0)
        return -1;
    *temp = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(float *hum) {
    uint16_t raw;
    if (read_measurement(CMD_MEASURE_HUM_HOLD, &raw) != 0)
        return -1;
    *hum = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*hum < 0.0f)   *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;
    return 0;
}

static int log_data(float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);

    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_i2c() != 0)
        return 1;

    if (reset_sensor() != 0) {
