            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);

    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_i2c() != 0)
        return 1;

    if (reset_sensor() != 0) {
        fprintf(stderr, "Warning: sensor may not be present at 0x%02X\n", I2C_ADDR);
    }

    while (running) {
        float temp, hum;

        if (read_temperature(&temp) != 0) {
            fprintf(stderr, "Warning: temperature read failed, retrying...\n");
        } else if (read_humidity(&hum) != 0) {
            fprintf(stderr, "Warning: humidity read failed, retrying...\n");
        } else {
            if (log_data(temp, hum) != 0)
                fprintf(stderr, "Warning: log write failed\n");
            printf("%s Temperature: %.2f C, Humidity: %.2f %%\n",
                   "Current", temp, hum);
        }

        /* Sleep in 100 ms slices so SIGINT is caught promptly */
        for (int i = 0; i < 50 && running; i++)
            gpioDelay(100000);
    }

    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

