    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SHT40_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("SHT40 greenhouse monitor started. Logging to %s every %d seconds. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        float temperature, humidity;
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
            log_data(log_file, temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    printf("Cleanup complete.\n");
    return 0;
}

