#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SI7021_ADDR          0x40
#define SI7021_TEMP_HOLD     0xE3
#define SI7021_FAN_GPIO      18
#define BUFFER_SIZE          60
#define POLL_INTERVAL_US     2000000   /* 2 s  */
#define FAN_ON_THRESHOLD     28.0f
#define FAN_OFF_THRESHOLD    27.0f
#define I2C_RETRIES          3
#define I2C_RETRY_DELAY_US   100000    /* 100 ms */
#define FAN_SETTLE_US        10000     /* 10 ms  */

typedef struct {
    time_t timestamp;
    float  temperature;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int       buffer_index = 0;
static int       buffer_count = 0;

static int  i2c_handle = -1;
static bool fan_on     = false;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int si7021_read_temperature(float *temperature)
{
    char cmd[1] = { SI7021_TEMP_HOLD };
    char data[2];
    int  rc;

    for (int attempt = 0; attempt < I2C_RETRIES; ++attempt) {
        rc = i2cWriteDevice(i2c_handle, cmd, 1);
        if (rc != 0) {
            fprintf(stderr, "[WARN] I2C write failed (attempt %d/%d): %d\n",
                    attempt + 1, I2C_RETRIES, rc);
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }

        gpioDelay(10000);                 /* 10 ms conversion time */

        rc = i2cReadDevice(i2c_handle, data, 2);
        if (rc != 2) {
            fprintf(stderr, "[WARN] I2C read failed (attempt %d/%d): %d\n",
                    attempt + 1, I2C_RETRIES, rc);
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }

        uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
        *temperature = (175.72f * (float)raw / 65536.0f) - 46.85f;
        return 0;
    }

    fprintf(stderr, "[ERROR] SI7021 read failed after %d retries.\n", I2C_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
static void buffer_add(float temperature)
{
    time(&circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        ++buffer_count;
}

/* ------------------------------------------------------------------ */
/* Fan control with hysteresis                                        */
/* ------------------------------------------------------------------ */
static void control_fan(float temperature)
{
    if (temperature > FAN_ON_THRESHOLD && !fan_on) {
        if (gpioWrite(SI7021_FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("[FAN] ON  (T=%.2f C)\n", temperature);
        } else {
            fprintf(stderr, "[WARN] Failed to set fan GPIO high.\n");
        }
    } else if (temperature < FAN_OFF_THRESHOLD && fan_on) {
        if (gpioWrite(SI7021_FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("[FAN] OFF (T=%.2f C)\n", temperature);
        } else {
            fprintf(stderr, "[WARN] Failed to set fan GPIO low.\n");
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (fan_on) {
        gpioWrite(SI7021_FAN_GPIO, 0);
        fan_on = false;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SI7021_FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO%d as output.\n", SI7021_FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SI7021_FAN_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SI7021_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7021 monitoring started (I2C bus %d, addr 0x%02X, fan GPIO%d).\n",
           I2C_BUS, SI7021_ADDR, SI7021_FAN_GPIO);
    printf("Thresholds: ON > %.1f C, OFF < %.1f C. Press Ctrl+C to exit.\n",
           FAN_ON_THRESHOLD, FAN_OFF_THRESHOLD);

    while (running) {
        float temperature;

        if (si7021_read_temperature(&temperature) == 0) {
            buffer_add(temperature);
            control_fan(temperature);
            printf("[%ld] T=%.2f C  Fan=%s\n",
                   (long)circular_buffer[buffer_index].timestamp,
                   temperature, fan_on ? "ON" : "OFF");
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; fan may be stuck.\n");
            if (fan_on) {
                gpioWrite(SI7021_FAN_GPIO, 0);
                fan_on = false;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

