#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define LOG_FILE "air_quality.log"
#define MEASUREMENT_INTERVAL_S 5
#define STRETCH_DELAY_US 100000
#define STOP_CMD_LEN 2
#define STOP_CMD_VAL 0x3F86
#define READ_MEASUREMENT_LEN 9
#define READY_FLAG_LEN 2
#define READY_FLAG_VAL 0x0001
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ CRC8_POLY;
            else crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x%02X%02X)\n", msb, lsb);
        return -1;
    }
    return 0;
}

static int read_data(uint8_t *buf, int len) {
    int n = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "Error: I2C read returned %d of %d bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int start_periodic_measurement(void) {
    if (send_command(0x21, 0xB1) != 0) return -1;
    gpioDelay(STRETCH_DELAY_US);
    return 0;
}

static int stop_periodic_measurement(void) {
    uint8_t cmd[2] = {(STOP_CMD_VAL >> 8) & 0xFF, STOP_CMD_VAL & 0xFF};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Stop command write failed\n");
        return -1;
    }
    gpioDelay(STRETCH_DELAY_US);
    return 0;
}

static int is_data_ready(void) {
    uint8_t buf[2];
    if (read_data(buf, 2) != 0) return -1;
    if (crc8(buf, 2) != 0) {
        fprintf(stderr, "Warning: CRC mismatch on ready flag\n");
        return -1;
    }
    uint16_t val = (buf[0] << 8) | buf[1];
    return (val & READY_FLAG_VAL) ? 1 : 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *rh) {
    uint8_t buf[READ_MEASUREMENT_LEN];
    if (read_data(buf, READ_MEASUREMENT_LEN) != 0) return -1;
    if (crc8(&buf[0], 2) != 0 || crc8(&buf[3], 2) != 0 || crc8(&buf[6], 2) != 0) {
        fprintf(stderr, "Error: CRC mismatch in measurement data\n");
        return -1;
    }
    *co2 = (buf[0] << 8) | buf[1];
    *temp = (buf[3] << 8) | buf[4];
    *temp = *temp * 0.01f;
    *rh = (buf[6] << 8) | buf[7];
    *rh = *rh * 0.01f;
    return 0;
}

static int log_data(uint16_t co2, float temp, float rh) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    if (start_periodic_measurement() != 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        cleanup();
        return 1;
    }

    printf("SCD40 periodic measurement started. Logging to %s every %d s.\n",
           LOG_FILE, MEASUREMENT_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (!terminate) {
        int ready = is_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Error: failed to read data-ready flag\n");
        } else if (ready == 1) {
            uint16_t co2;
            float temp, rh;
            if (read_measurement(&co2, &temp, &rh) == 0) {
                printf("CO2: %u ppm, Temp: %.2f C, RH: %.2f %%\n", co2, temp, rh);
                if (log_data(co2, temp, rh) != 0) {
                    fprintf(stderr, "Warning: failed to log data\n");
                }
            } else {
                fprintf(stderr, "Error: failed to read measurement data\n");
            }
        }
        sleep(MEASUREMENT_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

