    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    if (start_periodic_measurement() != 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        cleanup();
        return 1;
    }

    printf("SCD40 periodic measurement started. Logging to %s every %d s.\n",
           LOG_FILE, MEASUREMENT_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (!terminate) {
        int ready = is_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Error: failed to read data-ready flag\n");
        } else if (ready == 1) {
            uint16_t co2;
            float temp, rh;
            if (read_measurement(&co2, &temp, &rh) == 0) {
                printf("CO2: %u ppm, Temp: %.2f C, RH: %.2f %%\n", co2, temp, rh);
                if (log_data(co2, temp, rh) != 0) {
                    fprintf(stderr, "Warning: failed to log data\n");
                }
            } else {
                fprintf(stderr, "Error: failed to read measurement data\n");
            }
        }
        sleep(MEASUREMENT_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

