#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_S 5

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, int len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "I2C read failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

static int init_scd40(void) {
    if (i2c_write_cmd(CMD_START_PERIODIC_MEASUREMENT) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_scd40(float *co2, float *temp, float *hum) {
    if (i2c_write_cmd(CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(10000);

    uint8_t data[18];
    if (i2c_read_bytes(data, 18) != 0) return -1;

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CO2 CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t co2_raw = (data[0] << 8) | data[1];
    uint16_t temp_raw = (data[3] << 8) | data[4];
    uint16_t hum_raw = (data[6] << 8) | data[7];

    *co2 = (float)co2_raw;
    *temp = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
    *hum = (float)hum_raw / 65535.0f * 100.0f;
    return 0;
}

static void add_to_buffer(float co2, float temp, float hum) {
    buffer.data[buffer.head].timestamp = time(NULL);
    buffer.data[buffer.head].co2 = co2;
    buffer.data[buffer.head].temperature = temp;
    buffer.data[buffer.head].humidity = hum;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) buffer.count++;
}

static void print_buffer(void) {
    printf("\n--- Circular Buffer Contents ---\n");
    int start = (buffer.count == BUFFER_SIZE) ? buffer.head : 0;
    for (int i = 0; i < buffer.count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&buffer.data[idx].timestamp));
        printf("[%d] %s - CO2: %.0f ppm, Temp: %.2f C, Hum: %.2f %%\n",
               i, ts, buffer.data[idx].co2, buffer.data[idx].temperature, buffer.data[idx].humidity);
    }
    printf("--- End of Buffer ---\n\n");
}

static void control_led(float co2) {
    gpioWrite(LED_GPIO, (co2 > CO2_THRESHOLD) ? 1 : 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2c_write_cmd(CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d\n", SCD40_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_scd40() != 0) {
        fprintf(stderr, "SCD40 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    buffer.head = 0;
    buffer.count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float co2, temp, hum;
        if (read_scd40(&co2, &temp, &hum) == 0) {
            add_to_buffer(co2, temp, hum);
            print_buffer();
            control_led(co2);
            printf("CO2: %.0f ppm, Temp: %.2f C, Hum: %.2f %%\n", co2, temp, hum);
        } else {
            fprintf(stderr, "Read failed; continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

