        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_error(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, ERROR: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consecutive_failures = 0;

    while (running) {
        double temperature;

        if (read_sensor(&temperature) != 0) {
            consecutive_failures++;
            fprintf(stderr, "Sensor read failed (attempt %d)\n", consecutive_failures);
            if (consecutive_failures >= MAX_CONSECUTIVE_FAILURES) {
                log_error("SENSOR MALFUNCTION");
                consecutive_failures = 0;
            }
        } else {
            consecutive_failures = 0;

            if (temperature < MIN_VALID_TEMP || temperature > MAX_VALID_TEMP) {
                fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
                log_error("TEMPERATURE OUT OF RANGE");
            } else {
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Failed to log temperature\n");
                }
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

