#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH_REP 0x2400
#define MEASURE_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define LOG_INTERVAL_S 5
#define LOG_FILE_NAME "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, SensorData *data) {
    uint8_t cmd[2] = { (MEASURE_CMD_HIGH_REP >> 8) & 0xFF, MEASURE_CMD_HIGH_REP & 0xFF };
    uint8_t buf[6];

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
            fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n", attempt + 1, RETRY_COUNT, strerror(errno));
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n", attempt + 1, RETRY_COUNT, strerror(errno));
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "CRC mismatch (attempt %d/%d)\n", attempt + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t hum_raw = (buf[3] << 8) | buf[4];

        data->temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        data->humidity = 100.0f * (float)hum_raw / 65535.0f;
        return 0;
    }

    fprintf(stderr, "SHT35 read failed after %d retries\n", RETRY_COUNT);
    data->temperature = NAN;
    data->humidity = NAN;
    return -1;
}

static SensorData apply_greenhouse_offsets(SensorData data) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    int hour = utc->tm_hour;

    float temp_offset = 2.0f * sinf((2.0f * M_PI * hour) / 24.0f);
    float hum_offset = 5.0f * sinf((2.0f * M_PI * hour) / 24.0f);

    data.temperature += temp_offset;
    data.humidity += hum_offset;

    if (data.temperature < 0.0f) data.temperature = 0.0f;
    if (data.temperature > 40.0f) data.temperature = 40.0f;
    if (data.humidity < 0.0f) data.humidity = 0.0f;
    if (data.humidity > 100.0f) data.humidity = 100.0f;

    return data;
}

static int log_data(FILE *fp, SensorData data) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device on bus %d addr 0x%02X: %s\n", I2C_BUS, SHT35_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Greenhouse environmental monitoring started. Logging to %s every %d seconds.\n", LOG_FILE_NAME, LOG_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (!terminate) {
        SensorData data;
        if (read_sht35(i2c_handle, &data) == 0) {
            data = apply_greenhouse_offsets(data);
            if (log_data(log_file, data) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; logging NaN values.\n");
            if (log_data(log_file, (SensorData){NAN, NAN}) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }
        sleep(LOG_INTERVAL_S);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

