#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x44
#define CSV_FILENAME   "environment.csv"
#define SAMPLE_PERIOD  5.0
#define MEAS_DELAY_US  15000

/* SHT35 single-shot, high repeatability, clock stretching disabled */
#define CMD_MEASURE    0x2400

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Issue a 16-bit command to the SHT35.
 * Returns 0 on success, -1 on I2C write failure.
 */
static int sht35_send_command(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read 6 bytes from the SHT35.
 * Returns 0 on success, -1 on I2C read failure, -2 on CRC mismatch.
 */
static int sht35_read_data(int handle, float *temperature, float *humidity)
{
    uint8_t data[6];

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    if (sht35_crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -2;
    }
    if (sht35_crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -2;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity)
{
    FILE *fp = fopen(filename, "r");
    int needs_header = (fp == NULL);
    if (fp) fclose(fp);

    fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (needs_header)
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Cannot close %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int rc = EXIT_SUCCESS;

    while (g_running) {
        if (sht35_send_command(g_i2c_handle, CMD_MEASURE) != 0) {
            rc = EXIT_FAILURE;
            break;
        }

        gpioDelay(MEAS_DELAY_US);

        float temperature, humidity;
        int ret = sht35_read_data(g_i2c_handle, &temperature, &humidity);
        if (ret != 0) {
            fprintf(stderr, "Warning: Sensor read failed (code %d), retrying next cycle\n", ret);
            rc = EXIT_FAILURE;
            break;
        }

        if (log_data(CSV_FILENAME, temperature, humidity) != 0) {
            rc = EXIT_FAILURE;
            break;
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000);
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    if (rc == EXIT_SUCCESS)
        printf("Program terminated gracefully.\n");
    return rc;
}

