#define MEASURE_CMD 0x361F
#define CONVERSION_TIME_US 45000
#define SAMPLE_INTERVAL_US 1000000
#define FILENAME "airflow.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SDP810_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X on bus %d (handle=%d).\n",
                SDP810_I2C_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int send_measurement_command(void) {
    uint8_t cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: Failed to write measurement command (rc=%d).\n", rc);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint8_t *buf, int len) {
    int rc = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "Error: I2C read returned %d bytes, expected %d.\n", rc, len);
        return -1;
    }
    return 0;
}

static int validate_crc(const uint8_t *data, int len) {
    if (crc8(data, len) != 0) {
        fprintf(stderr, "Error: CRC validation failed for data block.\n");
        return -1;
    }
    return 0;
}

static int convert_data(const uint8_t *buf, float *pressure, float *temperature) {
    if (validate_crc(buf, 6) < 0) return -1;
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    *pressure = (float)raw_pressure / 200.0f;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

