    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_i2c() < 0) return 1;

    fp = fopen(FILENAME, "wb");
    if (!fp) {
        perror("fopen");
        cleanup();
        return 1;
    }

    uint8_t buf[9];
    float pressure, temperature;

    while (running) {
        if (send_measurement_command() < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        gpioDelay(CONVERSION_TIME_US);
        if (read_sensor_data(buf, 9) < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (convert_data(buf, &pressure, &temperature) < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (log_data(pressure, temperature) < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

