#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LPS33HW_ADDR 0x5D
#define CTRL_REG1 0x20
#define CTRL_REG2 0x21
#define PRESS_OUT_XL 0x28
#define TEMP_OUT_L 0x2B
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_lps33hw(void) {
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1 (0x20).\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x04) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG2 (0x21).\n");
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure) {
    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read pressure data.\n");
        return -1;
    }
    int32_t raw = (int32_t)((uint8_t)buf[2] << 16) |
                  (int32_t)((uint8_t)buf[1] << 8) |
                  (int32_t)((uint8_t)buf[0]);
    if (raw & 0x00800000) raw |= 0xFF000000;
    *pressure = (float)raw / 4096.0f;
    return 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read temperature data.\n");
        return -1;
    }
    int16_t raw = (int16_t)(((uint8_t)buf[1] << 8) | (uint8_t)buf[0]);
    *temperature = (float)raw / 100.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f C\n",
            timestamp, pressure, temperature);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
    if (log_file) {
        fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(log_file);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X.\n", LPS33HW_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lps33hw() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float pressure, temperature;
    while (!terminate) {
        if (read_pressure(&pressure) == 0 && read_temperature(&temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            log_error("Failed to read sensor data.");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Terminating gracefully...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

