        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X.\n", LPS33HW_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lps33hw() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float pressure, temperature;
    while (!terminate) {
        if (read_pressure(&pressure) == 0 && read_temperature(&temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            log_error("Failed to read sensor data.");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Terminating gracefully...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

