#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define GPIO_LED       17
#define TEMP_THRESHOLD 28.0f
#define BUFFER_SIZE    10
#define POLL_DELAY_US  1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read the STLM75 temperature register (0x00) and convert to Celsius.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_temperature(int handle, float *out)
{
    char buf[2];

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    /*
     * STLM75: 12-bit two's-complement, left-justified in 16 bits.
     * Byte 0 = MSB, Byte 1 = LSB (bits 7..0 = data, bit 15 = alert/alert).
     */
    int16_t raw = (int16_t)((uint16_t)((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    raw >>= 4;                       /* right-justify 12-bit value */
    *out = (float)raw * 0.0625f;     /* 0.0625 °C per LSB */
    return 0;
}

int main(void)
{
    int  i2c_handle = -1;
    float temperature_buffer[BUFFER_SIZE];
    int  buffer_index = 0;
    float running_average = 0.0f;
    int  samples_collected = 0;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* --- Open I2C bus to STLM75 --- */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioWrite(GPIO_LED, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float temperature;

        if (read_temperature(i2c_handle, &temperature) == 0) {
            /* Update circular buffer */
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            /* Update running average */
            if (samples_collected < BUFFER_SIZE) {
                running_average = (running_average * (float)samples_collected + temperature)
                                  / (float)(samples_collected + 1);
                samples_collected++;
            } else {
                running_average = (running_average * (float)(BUFFER_SIZE - 1) + temperature)
                                  / (float)BUFFER_SIZE;
            }

            /* Control LED */
            if (running_average > TEMP_THRESHOLD) {
                gpioWrite(GPIO_LED, 1);
            } else {
                gpioWrite(GPIO_LED, 0);
            }

            printf("Temperature: %.2f C, Average: %.2f C\n",
                   temperature, running_average);
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping cycle\n");
        }

        /* Sleep 1 second (interruptible by signals) */
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

