#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SCD30_I2C_BUS 1
#define SCD30_I2C_ADDR 0x61

#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_SET_MEASUREMENT_INTERVAL 0x4600
#define SCD30_CMD_GET_MEASUREMENT_INTERVAL 0x4603
#define SCD30_CMD_SET_AUTOMATIC_SELF_CALIBRATION 0x4636
#define SCD30_CMD_GET_AUTOMATIC_SELF_CALIBRATION 0x4637
#define SCD30_CMD_SET_TEMPERATURE_OFFSET 0x4630
#define SCD30_CMD_GET_TEMPERATURE_OFFSET 0x4631
#define SCD30_CMD_SET_ALTITUDE_COMPENSATION 0x4632
#define SCD30_CMD_GET_ALTITUDE_COMPENSATION 0x4633
#define SCD30_CMD_SOFT_RESET 0x3041

#define SCD30_INTERVAL_SEC 5
#define SCD30_MEASUREMENT_READY_TIMEOUT_MS 1000
#define SCD30_MAX_RETRIES 3

#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_HIGH 1200

#define VENTILATION_PIN 4
#define VENTILATION_OFF 0
#define VENTILATION_LOW 1
#define VENTILATION_HIGH 2

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int scd30_write_command(int handle, uint16_t cmd) {
    char buf[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing command 0x%04X: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int scd30_read_response(int handle, uint8_t *data, int len) {
    if (i2cReadDevice(handle, (char *)data, len) != len) {
        fprintf(stderr, "Error reading response: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int scd30_start_periodic_measurement(int handle) {
    if (scd30_write_command(handle, SCD30_CMD_START_PERIODIC_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000);
    return 0;
}

static int scd30_stop_periodic_measurement(int handle) {
    if (scd30_write_command(handle, SCD30_CMD_STOP_PERIODIC_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000);
    return 0;
}

static int scd30_get_data_ready(int handle, int *ready) {
    if (scd30_write_command(handle, SCD30_CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t data[3];
    if (scd30_read_response(handle, data, 3) != 0)
        return -1;
    *ready = (data[0] == 1) ? 1 : 0;
    return 0;
}

static int scd30_read_measurement(int handle, float *co2, float *temp, float *hum) {
    if (scd30_write_command(handle, SCD30_CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t data[18];
    if (scd30_read_response(handle, data, 18) != 0)
        return -1;
    uint32_t co2_raw = ((uint32_t)data[0] << 24) | ((uint32_t)data[1] << 16) |
                       ((uint32_t)data[3] << 8) | (uint32_t)data[4];
    uint32_t temp_raw = ((uint32_t)data[6] << 24) | ((uint32_t)data[7] << 16) |
                        ((uint32_t)data[9] << 8) | (uint32_t)data[10];
    uint32_t hum_raw = ((uint32_t)data[12] << 24) | ((uint32_t)data[13] << 16) |
                       ((uint32_t)data[15] << 8) | (uint32_t)data[16];
    *co2 = (float)co2_raw;
    *temp = (float)temp_raw / 65536.0f;
    *hum = (float)hum_raw / 65536.0f;
    return 0;
}

static int scd30_set_measurement_interval(int handle, uint16_t interval) {
    if (scd30_write_command(handle, SCD30_CMD_SET_MEASUREMENT_INTERVAL) != 0)
        return -1;
    gpioDelay(2000);
    char buf[3] = { (char)(interval >> 8), (char)(interval & 0xFF), 0x00 };
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error setting measurement interval: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000);
    return 0;
}

static int scd30_get_measurement_interval(int handle, uint16_t *interval) {
    if (scd30_write_command(handle, SCD30_CMD_GET_MEASUREMENT_INTERVAL) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t data[3];
    if (scd30_read_response(handle, data, 3) != 0)
        return -1;
    *interval = ((uint16_t)data[0] << 8) | (uint16_t)data[1];
    return 0;
}

static int scd30_set_automatic_self_calibration(int handle, uint16_t enable) {
    if (scd30_write_command(handle, SCD30_CMD_SET_AUTOMATIC_SELF_CALIBRATION) != 0)
        return -1;
    gpioDelay(2000);
    char buf[3] = { (char)(enable >> 8), (char)(enable & 0xFF), 0x00 };
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error setting automatic self-calibration: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000);
    return 0;
}

static int scd30_get_automatic_self_calibration(int handle, uint16_t *enabled) {
    if (scd30_write_command(handle, SCD30_CMD_GET_AUTOMATIC_SELF_CALIBRATION) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t data[3];
    if (scd30_read_response(handle, data, 3) != 0)
        return -1;
    *enabled = ((uint16_t)data[0] << 8) | (uint16_t)data[1];
    return 0;
}

static int scd30_set_temperature_offset(int handle, float offset) {
    if (scd30_write_command(handle, SCD30_CMD_SET_TEMPERATURE_OFFSET) != 0)
        return -1;
    gpioDelay(2000);
    char buf[3] = { (char)(offset * 65536.0f), 0x00, 0x00 };
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error setting temperature offset: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000);
    return 0;
}

static int scd30_get_temperature_offset(int handle, float *offset) {
    if (scd30_write_command(handle, SCD30_CMD_GET_TEMPERATURE_OFFSET) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t data[3];
    if (scd30_read_response(handle, data, 3) != 0)
        return -1;
    *offset = (float)data[0] / 65536.0f;
    return 0;
}

static int scd30_set_altitude_compensation(int handle, float altitude) {
    if (scd30_write_command(handle, SCD30_CMD_SET_ALTITUDE_COMPENSATION) != 0)
        return -1;
    gpioDelay(2000);
    char buf[3] = { (char)(altitude * 65536.0f), 0x00, 0x00 };
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error setting altitude compensation: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000);
    return 0;
}

static int scd30_get_altitude_compensation(int handle, float *altitude) {
    if (scd30_write_command(handle, SCD30_CMD_GET_ALTITUDE_COMPENSATION) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t data[3];
    if (scd30_read_response(handle, data, 3) != 0)
        return -1;
    *altitude = (float)data[0] / 65536.0f;
    return 0;
}

static int scd30_soft_reset(int handle) {
    if (scd30_write_command(handle, SCD30_CMD_SOFT_RESET) != 0)
        return -1;
    gpioDelay(2000);
    return 0;
}

static int control_ventilation(float co2) {
    int state = VENTILATION_OFF;
    if (co2 < CO2_THRESHOLD_LOW) {
        state = VENTILATION_LOW;
    } else if (co2 >= CO2_THRESHOLD_HIGH) {
        state = VENTILATION_HIGH;
    }
    gpioWrite(VENTILATION_PIN, state);
    return state;
}

static void log_data(FILE *fp, float co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temp, hum);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    fprintf(fp, "%s,ERROR,%s\n", timestamp, msg);
    fflush(fp);
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        scd30_stop_periodic_measurement(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(SCD30_I2C_BUS, SCD30_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen("air_quality.log", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (scd30_soft_reset(g_i2c_handle) != 0) {
        fprintf(stderr, "SCD30 soft reset failed\n");
        cleanup();
        return 1;
    }
    gpioDelay(2000);

    if (scd30_set_measurement_interval(g_i2c_handle, SCD30_INTERVAL_SEC) != 0) {
        fprintf(stderr, "Failed to set measurement interval\n");
        cleanup();
        return 1;
    }

    if (scd30_start_periodic_measurement(g_i2c_handle) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }

    while (g_running) {
        int ready = 0;
        int retries = 0;
        while (retries < SCD30_MAX_RETRIES && !ready) {
            if (scd30_get_data_ready(g_i2c_handle, &ready) != 0) {
                retries++;
                gpioDelay(100000);
                continue;
            }
            if (ready) break;
            gpioDelay(200000);
            retries++;
        }

        if (!ready) {
            log_error(g_log_file, "Sensor data not ready or sensor not responding");
            gpioDelay(SCD30_INTERVAL_SEC * 1000000);
            continue;
        }

        float co2, temp, hum;
        if (scd30_read_measurement(g_i2c_handle, &co2, &temp, &hum) != 0) {
            log_error(g_log_file, "Failed to read measurement data");
            gpioDelay(SCD30_INTERVAL_SEC * 1000000);
            continue;
        }

        log_data(g_log_file, co2, temp, hum);
        control_ventilation(co2);

        gpioDelay(SCD30_INTERVAL_SEC * 1000000);
    }

    cleanup();
    return 0;
}

