#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x21
#define DEFAULT_INTERVAL_MS 1000
#define READ_LEN       9
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sdp32(int handle, float *pressure, float *temperature) {
    uint8_t buf[READ_LEN];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(handle, (char *)buf, READ_LEN);
        if (bytes_read == READ_LEN) {
            if (crc8(&buf[0], 2) != buf[2]) {
                fprintf(stderr, "CRC error on pressure word (attempt %d)\n", retries + 1);
                retries++;
                continue;
            }
            if (crc8(&buf[3], 2) != buf[5]) {
                fprintf(stderr, "CRC error on temperature word (attempt %d)\n", retries + 1);
                retries++;
                continue;
            }
            if (crc8(&buf[6], 2) != buf[8]) {
                fprintf(stderr, "CRC error on scale-factor word (attempt %d)\n", retries + 1);
                retries++;
                continue;
            }

            int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
            int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
            int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

            if (scale_factor == 0) {
                fprintf(stderr, "Invalid scale factor (0) from sensor\n");
                return -1;
            }

            *pressure = (float)raw_pressure / (float)scale_factor;
            *temperature = (float)raw_temperature / (float)scale_factor;
            return 0;
        }

        fprintf(stderr, "I2C read error: %d (attempt %d)\n", bytes_read, retries + 1);
        retries++;
        gpioDelay(10000);
    }

    fprintf(stderr, "Failed to read SDP32 after %d retries\n", MAX_RETRIES);
    return -1;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(int argc, char *argv[]) {
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Invalid interval '%s'. Using default %d ms.\n", argv[1], DEFAULT_INTERVAL_MS);
            interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SDP32 differential pressure logger started. Interval: %d ms. Press Ctrl+C to exit.\n", interval_ms);

    while (g_running) {
        float pressure = 0.0f;
        float temperature = 0.0f;

        if (read_sdp32(g_i2c_handle, &pressure, &temperature) == 0) {
            print_timestamp();
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            print_timestamp();
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        for (int i = 0; i < interval_ms / 100 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return 0;
}

