#define I2C_BUS         "/dev/i2c-1"
#define SI7051_ADDR     0x40
#define CMD_TEMP_HOLD   0xE3
#define CMD_RESET       0xFE
#define POLL_INTERVAL_S 5
#define MAX_RETRIES     3
#define MEAS_DELAY_MS   15

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int si7051_reset(int fd) {
    if (i2c_write_cmd(fd, CMD_RESET) < 0)
        return -1;
    usleep(15000);
    return 0;
}

static int si7051_read_temperature(int fd, float *temp_c) {
    uint8_t cmd = CMD_TEMP_HOLD;
    uint8_t buf[2];

    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, buf, 2) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
