    while (g_running) {
        float temp;
        bool success = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (si7051_read_temperature(fd, &temp) == 0) {
                success = true;
                break;
            }
            if (attempt < MAX_RETRIES - 1)
                usleep(100000);
        }

        if (success) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
            printf("[%s] Temperature: %.2f C\n", ts, temp);
            fflush(stdout);
        } else {
            fprintf(stderr, "Temperature read failed after %d attempts.\n", MAX_RETRIES);
        }

        for (int s = 0; s < POLL_INTERVAL_S && g_running; s++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    printf("\nExiting cleanly.\n");
    return rc;
}

