#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x55
#define MEASURE_CMD    0x00
#define READ_CMD       0x01
#define DEFAULT_TEMP   25.0f
#define DEFAULT_PRESS  101325.0f
#define MEASURE_DELAY_US 7000
#define LOOP_DELAY_US   5000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_sensor(float *temperature, float *pressure)
{
    char cmd[1] = { MEASURE_CMD };
    char buf[6];
    int rc;

    rc = i2cWriteDevice(g_i2c_handle, cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (trigger): %d\n", rc);
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    rc = i2cReadDevice(g_i2c_handle, buf, 6);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: %d\n", rc);
        return -1;
    }
    if (rc != 6) {
        fprintf(stderr, "I2C short read: got %d bytes, expected 6\n", rc);
        return -1;
    }

    if (buf[0] == 0xFF && buf[1] == 0xFF && buf[2] == 0xFF &&
        buf[3] == 0xFF && buf[4] == 0xFF && buf[5] == 0xFF) {
        fprintf(stderr, "Sensor absent or not responding (all bytes 0xFF)\n");
        return -1;
    }

    uint32_t raw_press = ((uint32_t)(uint8_t)buf[0] << 16) |
                         ((uint32_t)(uint8_t)buf[1] << 8)  |
                         ((uint32_t)(uint8_t)buf[2]);
    uint16_t raw_temp  = ((uint16_t)(uint8_t)buf[3] << 8)  |
                         ((uint16_t)(uint8_t)buf[4]);

    *temperature = (float)raw_temp / 100.0f;
    *pressure    = (float)raw_press / 100.0f;
    return 0;
}

static void log_data(float temperature, float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    }

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
           ts, temperature, pressure);
    fflush(stdout);
}

int main(void)
{
    float temperature, pressure;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        if (read_sensor(&temperature, &pressure) == 0) {
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Sensor read failed; continuing to next cycle.\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

