#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x22
#define LOG_FILE "airflow_log.csv"
#define READ_INTERVAL_MS 100
#define MEASUREMENT_DELAY_MS 8

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write error (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure) {
    uint8_t data[3];

    if (i2c_write_cmd(fd, 0x36) < 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, 3) < 0) {
        return -1;
    }

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on pressure data\n");
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *pressure = (float)raw / 65536.0f * 500.0f;
    return 0;
}

static int log_data(FILE *fp, float pressure) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (access(LOG_FILE, F_OK) != 0) {
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to create %s: %s\n", LOG_FILE, strerror(errno));
            cleanup();
            return 1;
        }
        if (fprintf(log_file, "Timestamp,Pressure (Pa)\n") < 0) {
            fprintf(stderr, "Failed to write header: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        fflush(log_file);
    } else {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
            cleanup();
            return 1;
        }
    }

    printf("Starting airflow monitoring. Press Ctrl+C to stop.\n");

    while (running) {
        float pressure;
        if (read_sdp800(i2c_fd, &pressure) == 0) {
            if (log_data(log_file, pressure) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        usleep(READ_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

