#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR        0x48
#define LOG_FILE        "pressure_log.csv"
#define SAMPLE_PERIOD_S 1
#define SAFE_TIRE_MIN   200.0f
#define SAFE_TIRE_MAX   250.0f
#define MAX_RETRIES     2

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_open(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_pressure(int fd, float *pressure_kPa)
{
    uint8_t reg = 0x00;
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        perror("write(reg select)");
        return -1;
    }
    usleep(10000);
    if (read(fd, buf, 2) != 2) {
        perror("read(pressure data)");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure_kPa = (float)raw / 100.0f;
    return 0;
}

static int log_open(void)
{
    long sz = -1;
    FILE *fp = fopen(LOG_FILE, "a+");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    if (fseek(fp, 0, SEEK_END) == 0)
        sz = ftell(fp);
    if (sz == 0) {
        fprintf(fp, "timestamp,pressure_kPa\n");
        fflush(fp);
    }
    return (int)(intptr_t)fp;
}

static void log_data(FILE *fp, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, pressure);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
