#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HIH6130_ADDR   0x27
#define LOG_FILE       "environmental_data.log"
#define LOG_MAX_SIZE   1048576  /* 1 MB */
#define SAMPLE_PERIOD  5         /* seconds */
#define MEASURE_DELAY  40000     /* microseconds (40 ms) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read 4 bytes from the HIH6130.
 * Returns 0 on success, -1 on error.
 */
static int hih6130_read(int fd, float *temperature, float *humidity)
{
    uint8_t buf[4];

    /*
     * Trigger a measurement by writing a zero byte to the device.
     * The HIH6130 is a push-pull sensor; the master drives SDA low
     * to trigger a measurement.  We do not drive SDA; the pull-up
     * on the bus drives SDA high and the sensor pulls it low.
     */
    if (write(fd, buf, 0) < 0) {
        fprintf(stderr, "write(trigger): %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASURE_DELAY);

    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read: expected 4 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /*
     * Status bits are the two MSBs of the first byte.
     * Bit 0 = bit 7 of the first byte, bit 1 = bit 6 of the first byte.
     */
    uint8_t status = (buf[0] >> 6) & 0x03;
    if (status != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", status);
        return -1;
    }

    uint16_t raw_humidity    = ((uint16_t)(buf[0] & 0x3F) << 8) | buf[1];
    uint16_t raw_temperature = ((uint16_t)buf[2] << 6) | (buf[3] >> 2);

    *humidity    = (float)raw_humidity    / 16383.0f * 100.0f;
    *temperature = (float)raw_temperature / 16383.0f * 165.0f - 40.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    return fd;
}

static int log_roll(int fd, const char *path)
{
    if (fd < 0) return -1;

    if (close(fd) < 0) {
        fprintf(stderr, "close(%s): %s\n", path, strerror(errno));
        return -1;
    }

    if (rename(path, "environmental_data.log.old") < 0 &&
        errno != ENOENT) {
        fprintf(stderr, "rename: %s\n", strerror(errno));
        return -1;
    }

    fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    return fd;
}

static int log_write(int fd, float temperature, float humidity)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_local) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    char line[256];
    int len = snprintf(line, sizeof(line),
                       "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                       ts, temperature, humidity);
    if (len < 0 || (size_t)len >= sizeof(line)) {
        fprintf(stderr, "snprintf truncated\n");
        return -1;
    }

    ssize_t written = write(fd, line, (size_t)len);
    if (written < 0) {
        fprintf(stderr, "write: %s\n", strerror(errno));
        return -1;
    }
    if (written != len) {
        fprintf(stderr, "write: partial write (%zd of %d)\n", written, len);
        return -1;
    }

    if (fsync(fd) < 0) {
        fprintf(stderr, "fsync: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, HIH6130_ADDR);
    if (g_i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    int log_fd = log_open(LOG_FILE);
    if (log_fd < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("HIH6130 logger started.  Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        if (hih6130_read(g_i2c_fd, &temperature, &humidity) < 0) {
            fprintf(stderr, "Sensor read failed; retrying next cycle.\n");
        } else {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);

            if (log_write(log_fd, temperature, humidity) < 0) {
                fprintf(stderr, "Log write failed.\n");
            }

            /* Check file size and roll if necessary */
            struct stat st;
            if (fstat(log_fd, &st) == 0 && st.st_size > (off_t)LOG_MAX_SIZE) {
                printf("Log file exceeded %d bytes; rolling.\n", LOG_MAX_SIZE);
                log_fd = log_roll(log_fd, LOG_FILE);
                if (log_fd < 0) {
                    fprintf(stderr, "Log roll failed; continuing.\n");
                }
            }
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    /* Clean shutdown */
    if (log_fd >= 0) {
        close(log_fd);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

