#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "pressure_log.txt"
#define TIMEOUT_US 1000000
#define SYNC_TICKS 56
#define MIN_NIBBLE_TICKS 12
#define MAX_NIBBLE_TICKS 271
#define NIBBLE_COUNT 4
#define NIBBLE_WIDTH_TOL 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int in_range(int ticks, int min_ticks, int max_ticks) {
    return (ticks >= min_ticks && ticks <= max_ticks);
}

static int read_nibble(int gpio, int *nibble_out) {
    uint32_t start_tick, end_tick;
    int level;

    start_tick = gpioTick();
    while (gpioRead(gpio) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) return -1;
    }
    level = 1;
    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) return -1;
    }
    end_tick = gpioTick();

    int ticks = (int)(end_tick - start_tick);
    if (!in_range(ticks, MIN_NIBBLE_TICKS, MAX_NIBBLE_TICKS)) return -2;

    *nibble_out = (ticks - MIN_NIBBLE_TICKS) / 10;
    return 0;
