#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_DEVICE_ID_REG 0x00
#define TMP117_DEVICE_ID_VAL 0x0117
#define TMP117_TEMP_REG 0x00
#define TMP117_CONFIG_REG 0x01
#define TMP117_CONFIG_VAL 0x0000
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int16_t raw;

    if (i2cWriteByte(i2c_handle, TMP117_TEMP_REG) < 0) {
        fprintf(stderr, "Error: Failed to set temperature register pointer.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read temperature data.\n");
        return -1;
    }

    raw = (int16_t)((buf[1] << 8) | buf[0]);
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static int log_temperature(float temperature) {
    if (fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write temperature to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", TMP117_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char dev_id_buf[2];
    if (i2cWriteByte(i2c_handle, TMP117_DEVICE_ID_REG) < 0) {
        fprintf(stderr, "Error: Failed to set device ID register pointer.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2cReadDevice(i2c_handle, dev_id_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read device ID.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    uint16_t dev_id = (uint16_t)((dev_id_buf[1] << 8) | dev_id_buf[0]);
    if (dev_id != TMP117_DEVICE_ID_VAL) {
        fprintf(stderr, "Error: Unexpected device ID 0x%04X (expected 0x%04X).\n", dev_id, TMP117_DEVICE_ID_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(i2c_handle, TMP117_CONFIG_REG, TMP117_CONFIG_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write configuration register.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Greenhouse temperature monitoring started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Warning: Temperature logged but file write failed.\n");
            }
        } else {
            fprintf(stderr, "Warning: Temperature read failed, skipping log entry.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

