#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define CONFIG_REG 0x01
#define CONFIG_VAL 0x0000
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "temperature_log.dat"

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

static TemperatureReading rolling_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_fd = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (uint8_t)(value >> 8), (uint8_t)(value & 0xFF)};
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int init_tmp117(int fd) {
    if (i2c_write_reg16(fd, CONFIG_REG, CONFIG_VAL) != 0) {
        fprintf(stderr, "Failed to configure TMP117\n");
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    uint16_t raw;
    if (i2c_read_reg16(fd, TEMP_REG, &raw) != 0) {
        return -1;
    }
    int16_t signed_raw = (int16_t)raw;
    *temperature = (float)signed_raw * 0.0078125f;
    return 0;
}

static void add_to_buffer(float temperature) {
    rolling_buffer[buffer_index].timestamp = time(NULL);
    rolling_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static int write_buffer_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }
    int start_index = (buffer_count == BUFFER_SIZE) ? buffer_index : 0;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start_index + i) % BUFFER_SIZE;
        if (fwrite(&rolling_buffer[idx], sizeof(TemperatureReading), 1, fp) != 1) {
            fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
            fclose(fp);
            return -1;
        }
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_tmp117(i2c_fd) != 0) {
        fprintf(stderr, "TMP117 initialization failed\n");
        cleanup();
        return 1;
    }

    printf("TMP117 initialized. Logging temperature every %d seconds. Press Ctrl+C to stop.\n", SAMPLE_INTERVAL_SEC);

    while (program_running) {
        float temperature;
        if (read_temperature(i2c_fd, &temperature) == 0) {
            add_to_buffer(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (write_buffer_to_file(LOG_FILE) != 0) {
        fprintf(stderr, "Failed to write buffer to file\n");
    }
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

