#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SHTC3_ADDR 0x70
#define MEASURE_CMD_HIGH 0x78
#define MEASURE_CMD_LOW 0x64
#define LOG_FILE "shtc3_environment.log"
#define SAMPLE_INTERVAL_SEC 5
#define CONVERSION_DELAY_US 12400

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_shtc3(int handle, SensorData *data) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    uint16_t hum_raw = (buf[3] << 8) | buf[4];

    data->temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    data->humidity = 100.0f * (float)hum_raw / 65535.0f;

    if (data->temperature < -40.0f || data->temperature > 125.0f) {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", data->temperature);
        return -1;
    }
    if (data->humidity < 0.0f || data->humidity > 100.0f) {
        fprintf(stderr, "Error: Humidity out of range: %.2f\n", data->humidity);
        return -1;
    }

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", s, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SHTC3 sensor logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        SensorData data;
        if (read_shtc3(i2c_handle, &data) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
            if (log_data(LOG_FILE, data.temperature, data.humidity) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    printf("SHTC3 sensor logging stopped.\n");
    return 0;
}

