#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define SI7202_REG_TEMP 0x00
#define SI7202_REG_SPEED 0x01
#define SI7202_REG_CONFIG 0x02
#define SI7202_REG_STATUS 0x03
#define SI7202_REG_ID 0x0F
#define SI7202_ID_VALUE 0x20
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, addr 0x%02X (code %d).\n",
                I2C_BUS, SI7202_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    int id = i2cReadByteData(i2c_handle, SI7202_REG_ID);
    if (id < 0) {
        fprintf(stderr, "Error: Failed to read sensor ID register (code %d).\n", id);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }
    if (id != SI7202_ID_VALUE) {
        fprintf(stderr, "Error: Unexpected sensor ID 0x%02X (expected 0x%02X).\n", id, SI7202_ID_VALUE);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Configure: 12-bit speed, 12-bit temp, continuous mode */
    if (i2cWriteByteData(i2c_handle, SI7202_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register.\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

