#define TEMP_REG 0x00
#define CONFIG_REG 0x01
#define CONFIG_VAL 0x0000
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, CONFIG_VAL) < 0) {
        fprintf(stderr, "Error writing config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

