    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", raw);
        return -1;
    }
    int16_t signed_raw = (int16_t)raw;
    *temp = (float)signed_raw * 0.0078125f;
    return 0;
}

static int log_temperature(float temp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp);
    fclose(fp);
    return 0;
}

