        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    int retry_count = 0;
    while (running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            if (log_temperature(temp) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
            retry_count = 0;
        } else {
            retry_count++;
            fprintf(stderr, "Failed to read temperature (attempt %d/%d)\n", retry_count, MAX_RETRIES);
            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }
        sleep(1);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

