                fprintf(stderr, "Max retries reached, attempting I2C re-initialization...\n");
                if (initialize_i2c() != 0) {
                    fprintf(stderr, "I2C re-initialization failed, exiting.\n");
                    break;
                }
                consecutive_failures = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
