#define DHT11_GPIO 4
#define DHT11_FILE "dht11_readings.txt"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 2000000  /* 2 s between samples */
#define START_LOW_US 20000          /* 20 ms low start pulse */
#define START_HIGH_US 30            /* 30 us high start pulse */
#define RESP_LOW_US 80              /* 80 us response low */
#define RESP_HIGH_US 80             /* 80 us response high */
#define BIT_LOW_US 50               /* 50 us low per bit */
#define BIT_THRESHOLD_US 40         /* high >40 us => '1', else '0' */
#define TIMEOUT_US 1000             /* per-bit timeout */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Microsecond delay (microseconds)                                    */
/* ------------------------------------------------------------------ */
static void delay_us(unsigned int us)
{
    struct timespec ts;
    ts.tv_sec  = us / 1000000U;
    ts.tv_nsec = (long)(us % 1000000U) * 1000L;
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* GPIO API (pseudo-GPIO)                                              */
/* ------------------------------------------------------------------ */
static int gpio_set_direction(int pin, int direction)
{
    (void)pin;
    (void)direction;
    return 0;
}

static int gpio_write(int pin, int level)
{
    (void)pin;
    (void)level;
    return 0;
}

static int gpio_read(int pin)
{
    (void)pin;
    return 0;
}

static void gpio_cleanup(void)
{
    /* Nothing to do on a real GPIO API */
}

/* ------------------------------------------------------------------ */
/* Timing helpers                                                      */
/* ------------------------------------------------------------------ */
static unsigned int measure_high_us(int pin, unsigned int timeout_us)
{
    unsigned int elapsed = 0;
    while (gpio_read(pin) == 1) {
        delay_us(1);
        elapsed++;
        if (elapsed >= timeout_us)
            return 0;
    }
    return elapsed;
}

static unsigned int measure_low_us(int pin, unsigned int timeout_us)
{
    unsigned int elapsed = 0;
    while (gpio_read(pin) == 0) {
        delay_us(1);
        elapsed++;
        if (elapsed >= timeout_us)
            return 0;
    }
    return elapsed;
}

/* ------------------------------------------------------------------ */
/* DHT11 read                                                          */
/* ------------------------------------------------------------------ */
static int dht11_read(float *temperature, float *humidity)
{
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int i;

    /* --- Start signal: pull low for >= 18 ms, then high --- */
    if (gpio_set_direction(DHT11_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d low\n", DHT11_GPIO);
        return -1;
    }
    delay_us(START_LOW_US);
    if (gpio_write(DHT11_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d high\n", DHT11_GPIO);
        return -1;
    }
    delay_us(START_HIGH_US);

    /* --- Release line: switch to input --- */
    if (gpio_set_direction(DHT11_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d input\n", DHT11_GPIO);
        return -1;
    }

    /* --- Wait for sensor response: low ~80 us, high ~80 us --- */
    unsigned int resp_low = measure_low_us(DHT11_GPIO, TIMEOUT_US);
    if (resp_low == 0 || resp_low > RESP_LOW_US) {
        fprintf(stderr, "Error: DHT11 response low timeout (%u us)\n", resp_low);
        return -2;
    }

    unsigned int resp_high = measure_high_us(DHT11_GPIO, TIMEOUT_US);
    if (resp_high == 0 || resp_high > RESP_HIGH_US) {
        fprintf(stderr, "Error: DHT11 response high timeout (%u us)\n", resp_high);
        return -2;
    }

    /* --- Read 40 data bits --- */
    for (i = 0; i < 40; i++) {
        /* Low period (~50 us) */
        unsigned int low = measure_low_us(DHT11_GPIO, TIMEOUT_US);
        if (low == 0 || low > BIT_LOW_US) {
            fprintf(stderr, "Error: DHT11 bit %d low timeout (%u us)\n", i, low);
            return -3;
        }

        /* High period: ~26-28 us => '0', ~70 us => '1' */
        unsigned int high = measure_high_us(DHT11_GPIO, TIMEOUT_US);
        if (high == 0 || high > BIT_THRESHOLD_US) {
            fprintf(stderr, "Error: DHT11 bit %d high timeout (%u us)\n", i, high);
            return -3;
        }

        if (high > BIT_THRESHOLD_US)
            data[i / 8] |= (1 << (7 - (i % 8)));
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "Error: DHT11 checksum mismatch (calc=%u, recv=%u)\n",
                checksum, data[4]);
        return -4;
    }

    /* --- Decode --- */
    *humidity    = (float)data[0];
    *temperature = (float)data[2];

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_reading(float temperature, float humidity)
{
    FILE *fp = fopen(DHT11_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", DHT11_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, Temperature: %.1f C, Humidity: %.1f %%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                temperature, humidity);
    } else {
        fprintf(fp, "(unknown time), Temperature: %.1f C, Humidity: %.1f %%\n",
                temperature, humidity);
    }

    fclose(fp);
}

static void log_error(const char *message, int status)
{
    FILE *fp = fopen(DHT11_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", DHT11_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, ERROR: %s (status=%d)\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message, status);
    } else {
        fprintf(fp, "(unknown time), ERROR: %s (status=%d)\n", message, status);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize GPIO --- */
    if (gpio_set_direction(DHT11_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO %d\n", DHT11_GPIO);
        return EXIT_FAILURE;
    }

    printf("DHT11 sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           DHT11_GPIO);

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int status;
        int attempt;

        for (attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            status = dht11_read(&temperature, &humidity);
            if (status == 0)
                break;
            delay_us(2000000);  /* 2 s between retries */
        }

        if (g_running) {
            if (status == 0) {
                log_reading(temperature, humidity);
                printf("Temperature: %.1f C, Humidity: %.1f %%\n",
                       temperature, humidity);
            } else {
                log_error("DHT11 read failed", status);
                fprintf(stderr, "DHT11 read failed (status=%d)\n", status);
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 20 && g_running; i++)
            delay_us(100000);
    }

    /* --- Cleanup --- */
    gpio_cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

