static int read_sht31d(float *temperature, float *humidity) {
    uint8_t cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
            fprintf(stderr, "I2C write failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t hum_raw  = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
        *humidity    = 100.0f * (float)hum_raw / 65535.0f;

        return 0;
    }

    return -1;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (!terminate) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            fprintf(stderr, "%s: Failed to read sensor data after %d retries\n", ts, MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

