static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * ADPD105 register map (simplified for CCT calculation).
 * Real implementation requires a full driver library or block reads.
 */
typedef struct {
    int i2c_fd;
    uint8_t address;
} sensor_t;

static int sensor_init(sensor_t *sensor, uint8_t address) {
    sensor->i2c_fd = open(I2C_BUS, O_RDWR);
    if (sensor->i2c_fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(sensor->i2c_fd, I2C_SLAVE, address) < 0) {
        perror("ioctl I2C_SLAVE");
        close(sensor->i2c_fd);
        sensor->i2c_fd = -1;
        return -1;
    }
    sensor->address = address;
    return 0;
}

static int sensor_read_register(sensor_t *sensor, uint8_t reg, uint8_t *value) {
    if (sensor->i2c_fd < 0) return -1;
    if (ioctl(sensor->i2c_fd, I2C_SLAVE, sensor->address) < 0) {
        perror("ioctl I2C_SLAVE");
        return -1;
    }
    if (write(sensor->i2c_fd, &reg, 1) != 1) {
        perror("write register address");
        return -1;
    }
    if (read(sensor->i2c_fd, value, 1) != 1) {
        perror("read register value");
        return -1;
    }
    return 0;
}

static int sensor_write_register(sensor_t *sensor, uint8_t reg, uint8_t value) {
    if (sensor->i2c_fd < 0) return -1;
    if (ioctl(sensor->i2c_fd, I2C_SLAVE, sensor->address) < 0) {
        perror("ioctl I2C_SLAVE");
        return -1;
    }
