    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    sensor_t sensor1, sensor2;
    sensor1.i2c_fd = -1;
    sensor2.i2c_fd = -1;

    if (sensor_init(&sensor1, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Error initializing sensor 1 at 0x%02X\n", SENSOR1_ADDR);
        return 1;
    }
    if (sensor_init(&sensor2, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Error initializing sensor 2 at 0x%02X\n", SENSOR2_ADDR);
        close(sensor1.i2c_fd);
        return 1;
    }

    printf("Starting CCT logging. Press Ctrl+C to stop.\n");

    while (running) {
        float cct1 = 0.0f, cct2 = 0.0f;
        int err1 = 0, err2 = 0;

        if (sensor_read_cct(&sensor1, &cct1) < 0) {
            fprintf(stderr, "Error reading CCT from sensor 1\n");
            err1 = 1;
        }
        if (sensor_read_cct(&sensor2, &cct2) < 0) {
            fprintf(stderr, "Error reading CCT from sensor 2\n");
            err2 = 1;
        }

        if (!err1 && !err2) {
            float avg_cct = (cct1 + cct2) / 2.0f;
            if (log_cct(avg_cct) < 0) {
                fprintf(stderr, "Error logging CCT\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (sensor1.i2c_fd >= 0) close(sensor1.i2c_fd);
    if (sensor2.i2c_fd >= 0) close(sensor2.i2c_fd);
    printf("\nExiting gracefully.\n");
    return 0;
}

