#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

/*
 * MLX90824 absolute pressure sensor register map.
 * The MLX90824 is a digital pressure sensor that outputs
 * a 16-bit pressure and temperature value via I2C.
 *
 * Register 0x00: Pressure (16-bit, big-endian)
 * Register 0x02: Temperature (16-bit, big-endian)
 */
#define REG_PRESSURE 0x00
#define REG_TEMPERATURE 0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int read_sensor_data(int handle, float *pressure, float *temperature) {
    char buf[4];
    int16_t raw_pressure, raw_temperature;

    /* Read 4 bytes starting at register 0x00 (pressure + temperature) */
    if (i2cReadI2CBlockData(handle, REG_PRESSURE, buf, 4) != 4) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    /* Pressure is big-endian, temperature is big-endian too */
    raw_pressure = (int16_t)((buf[0] << 8) | (buf[1] & 0xFF));
    raw_temperature = (int16_t)((buf[2] << 8) | (buf[3] & 0xFF));

    /*
     * Conversion formulas from the MLX90824 datasheet.
     * Adjust these to match your specific sensor calibration.
     */
    *pressure = (float)raw_pressure / 100.0f;   /* Example: divide by 100 for Pa */
    *temperature = (float)raw_temperature / 10.0f; /* Example: divide by 10 for C */

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
            timestamp, pressure, temperature);
    fflush(fp);
}

int main(void) {
    float pressure, temperature;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to set SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to set SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Starting pressure monitoring. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &pressure, &temperature) == 0) {
            log_data(g_log_file, pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed, logging error.\n");
            log_data(g_log_file, -999.0f, -999.0f);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

