#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  26.0f
#define POLL_INTERVAL_US   1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read the LM75B temperature register (0x00) and convert to Celsius.
 * The LM75B returns 16-bit two's-complement data in JEDEC-style big-endian
 * format: bits [15:12] = unused, [11:4] = integer part, [3:0] = fractional.
 * Resolution: 0.1 °C per LSB.
 */
static int read_temperature(int handle, float *temperature)
{
    char buf[2];
    int rc;

    rc = i2cReadI2CBlockData(handle, 0x00, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d (expected 2)\n", rc);
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    raw >>= 4;                       /* right-justify 12-bit value */
    *temperature = (float)raw * 0.1f;
    return 0;
}

static void control_fan(int gpio, float avg_temp)
{
    int level = (avg_temp > TEMP_THRESHOLD_HIGH) ? 1 : 0;
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", gpio, level);
        return;
    }
    printf("Fan %s (avg %.2f °C)\n", level ? "ON" : "OFF", avg_temp);
}

int main(void)
{
    int i2c_handle = -1;
    float temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    float sum = 0.0f;
    int samples_stored = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    printf("LM75B temperature monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_temperature(i2c_handle, &temperature_buffer[buffer_index]) != 0) {
            fprintf(stderr, "Warning: temperature read failed, retrying next cycle\n");
        } else {
            sum -= (samples_stored < BUFFER_SIZE) ? 0.0f : temperature_buffer[buffer_index];
            sum += temperature_buffer[buffer_index];
            if (samples_stored < BUFFER_SIZE) {
                samples_stored++;
            }
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            float avg = (samples_stored > 0) ? (sum / (float)samples_stored) : 0.0f;
            control_fan(FAN_GPIO, avg);
            printf("Temperature: %.2f °C, Average: %.2f °C\n",
                   temperature_buffer[buffer_index], avg);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            usleep(100000);
        }
    }

    /* Clean shutdown */
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

