#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x21
#define LOG_FILE       "airflow.log"
#define PRESSURE_THRESHOLD 5.0f
#define SAMPLE_PERIOD_US 1000000
#define MEASURE_DELAY_US 45000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no reflect, no final XOR */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Read one 9-byte measurement frame from the SDP810.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_sdp810(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -2;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -2;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on scale factor word\n");
        return -2;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure    / 60.0f;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);
    fflush(fp);
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (addr 0x%02X): %s\n", I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(g_log_file, "# SDP810 logging started\n");
    fflush(g_log_file);

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int rc = read_sdp810(g_i2c_handle, &pressure, &temperature);

        if (rc == 0) {
            log_data(g_log_file, pressure, temperature);
            if (pressure > PRESSURE_THRESHOLD) {
                fprintf(stderr, "WARNING: Pressure %.2f Pa exceeds threshold %.1f Pa\n",
                        pressure, PRESSURE_THRESHOLD);
            }
        } else if (rc == -1) {
            fprintf(stderr, "I2C read error — sensor may be absent\n");
        } else {
            fprintf(stderr, "CRC error — skipping sample\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return 0;
}

