#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define I2C_ADDR        0x48
#define TEMP_REG        0x00
#define LED_GPIO        17
#define HIGH_TEMP       28.0f
#define LOW_TEMP        27.0f
#define POLL_INTERVAL_S 1
#define MAX_I2C_RETRIES 3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_temp(int fd, float *temp_out)
{
    uint8_t reg = TEMP_REG;
    uint8_t buf[2];

    for (int attempt = 0; attempt < MAX_I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }
        usleep(10000);
        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }
        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        *temp_out = (float)raw / 100.0f;
        return 0;
    }
    return -1;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup_gpio;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        goto cleanup_i2c;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        goto cleanup_i2c;
    }
    gpioWrite(LED_GPIO, 0);

    bool led_on = false;

    while (g_running) {
        float temp;
        if (i2c_read_temp(fd, &temp) != 0) {
            fprintf(stderr, "Temperature read failed after %d retries; exiting.\n",
                    MAX_I2C_RETRIES);
            goto cleanup_i2c;
        }

        printf("Temperature: %.2f C\n", temp);
        fflush(stdout);

        if (temp > HIGH_TEMP && !led_on) {
            if (gpioWrite(LED_GPIO, 1) == 0) {
                led_on = true;
                printf("LED ON\n");
            } else {
                fprintf(stderr, "Failed to turn LED on: %s\n", strerror(errno));
            }
        } else if (temp < LOW_TEMP && led_on) {
            if (gpioWrite(LED_GPIO, 0) == 0) {
                led_on = false;
                printf("LED OFF\n");
            } else {
                fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
            }
        }

        sleep(POLL_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup_i2c:
    if (fd >= 0) {
        close(fd);
    }
cleanup_gpio:
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return ret;
}

