/*
 * Si7021 environmental logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si7021 SDA  -> GPIO2 (BCM 2, I2C bus 1)
 *   Si7021 SCL  -> GPIO3 (BCM 3, I2C bus 1)
 *   Si7021 VDD  -> 3.3 V
 *   Si7021 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_logger si7021_logger.c -lpigpio -lrt
 * Run:    sudo ./si7021_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40          /* Si7021 default 7-bit address */
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60            /* seconds between readings */
#define RETRY_COUNT    3
#define MEASURE_DELAY  20000         /* microseconds (20 ms) */

/* Si7021 commands (no-hold, clock-stretching / retry-free) */
#define CMD_MEASURE_RH_NO_HOLD      0xE5
#define CMD_MEASURE_TEMP_NO_HOLD    0xE3
#define CMD_READ_PREV_RH_TEMP       0xE0

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    if (g_log_file) {
        fprintf(g_log_file, "%s, ERROR, %s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s, ERROR, %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    return i2cWriteDevice(g_i2c_handle, buf, 1);
}

/*
 * Read a 16-bit big-endian value from the Si7021 after issuing a
 * no-hold measurement command.
 */
static int i2c_read_16(uint8_t cmd, uint16_t *out)
{
    char buf[2];
    int  rc;

    if (i2c_write_cmd(cmd) != 0)
        return -1;

    gpioDelay(MEASURE_DELAY);   /* ~20 ms conversion time */

    rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Read the previous-measurement temperature and humidity (0xE0) and
 * return the raw 16-bit values.
 */
static int i2c_read_prev(uint16_t *temp_raw, uint16_t *rh_raw)
{
    char buf[4];
    int  rc;

    if (i2c_write_cmd(CMD_READ_PREV_RH_TEMP) != 0)
        return -1;

    gpioDelay(MEASURE_DELAY);

    rc = i2cReadDevice(g_i2c_handle, buf, 4);
    if (rc != 4)
        return -1;

    *temp_raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *rh_raw   = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Conversion                                                          */
/* ------------------------------------------------------------------ */
static float convert_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    float h = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (h < 0.0f)   h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temp, float rh)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log_file, "%s, %.2f, %.2f\n", ts, temp, rh);
    fflush(g_log_file);
    printf("%s, %.2f, %.2f\n", ts, temp, rh);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- sensor presence check --- */
    uint16_t id_cmd = 0xFA;
    char id_buf[8];
    int rc = i2cWriteDevice(g_i2c_handle, (char *)&id_cmd, 1);
    if (rc != 0) {
        log_error("Sensor not responding on I2C bus");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);   /* 10 ms */
    rc = i2cReadDevice(g_i2c_handle, id_buf, 8);
    if (rc != 8) {
        log_error("Failed to read Si7021 electronic ID");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7021 detected (ID=0x%02X%02X%02X%02X)\n",
           (uint8_t)id_buf[0], (uint8_t)id_buf[1],
           (uint8_t)id_buf[2], (uint8_t)id_buf[3]);

    /* --- main loop --- */
    while (g_running) {
        uint16_t temp_raw = 0, rh_raw = 0;
        int ok = 0;

        for (int attempt = 0; attempt < RETRY_COUNT && g_running; ++attempt) {
            if (i2c_read_prev(&temp_raw, &rh_raw) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000);   /* 10 ms backoff */
        }

        if (!ok) {
            log_error("Failed to read temperature/humidity after retries");
        } else {
            float temp = convert_temperature(temp_raw);
            float rh   = convert_humidity(rh_raw);
            log_data(temp, rh);
        }

        /* sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; ++s)
            sleep(1);
    }

    /* --- cleanup --- */
    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

