    float h = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (h < 0.0f)   h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temp, float rh)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log_file, "%s, %.2f, %.2f\n", ts, temp, rh);
    fflush(g_log_file);
    printf("%s, %.2f, %.2f\n", ts, temp, rh);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- sensor presence check --- */
    uint16_t id_cmd = 0xFA;
    char id_buf[8];
    int rc = i2cWriteDevice(g_i2c_handle, (char *)&id_cmd, 1);
    if (rc != 0) {
        log_error("Sensor not responding on I2C bus");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);   /* 10 ms */
    rc = i2cReadDevice(g_i2c_handle, id_buf, 8);
    if (rc != 8) {
        log_error("Failed to read Si7021 electronic ID");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7021 detected (ID=0x%02X%02X%02X%02X)\n",
           (uint8_t)id_buf[0], (uint8_t)id_buf[1],
           (uint8_t)id_buf[2], (uint8_t)id_buf[3]);

    /* --- main loop --- */
    while (g_running) {
        uint16_t temp_raw = 0, rh_raw = 0;
        int ok = 0;

        for (int attempt = 0; attempt < RETRY_COUNT && g_running; ++attempt) {
            if (i2c_read_prev(&temp_raw, &rh_raw) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000);   /* 10 ms backoff */
        }

        if (!ok) {
            log_error("Failed to read temperature/humidity after retries");
        } else {
            float temp = convert_temperature(temp_raw);
            float rh   = convert_humidity(rh_raw);
            log_data(temp, rh);
        }

        /* sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; ++s)
            sleep(1);
    }

    /* --- cleanup --- */
    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

