#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define TEMP_REG 0x00
#define HUM_REG 0x01
#define CONFIG_REG 0x02
#define CONFIG_VAL 0x1000  /* Heater off, 14-bit temp, 14-bit humidity */
#define LOG_FILE "enviro_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define CONVERSION_DELAY_US 20000   /* 20 ms */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hdc1080_init(int handle) {
    if (i2cWriteWordData(handle, CONFIG_REG, CONFIG_VAL) < 0) {
        fprintf(stderr, "Error writing config register\n");
        return -1;
    }
    return 0;
}

static int hdc1080_read_temp_hum(int handle, float *temp, float *hum) {
    char buf[4];

    /* Trigger measurement by writing 0x00 to TEMP_REG */
    if (i2cWriteByteData(handle, TEMP_REG, 0x00) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    /* Read 4 bytes: temp_msb, temp_lsb, hum_msb, hum_lsb */
    if (i2cReadDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t raw_hum  = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

    *temp = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *hum  = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(const char *filename, float temp, float hum) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temp, hum);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (hdc1080_init(i2c_handle) < 0) {
        fprintf(stderr, "HDC1080 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("EnviroLogger started. Logging to %s every 5 seconds.\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float temp, hum;

        if (hdc1080_read_temp_hum(i2c_handle, &temp, &hum) == 0) {
            if (log_data(LOG_FILE, temp, hum) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log entry\n");
        }

        /* Sleep in 100 ms increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("EnviroLogger stopped.\n");
    return 0;
}

