#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define STS40_ADDR      0x40
#define LOG_FILE        "temperature_log.txt"
#define SAMPLE_INTERVAL 5
#define CONVERSION_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no reflect, no final XOR */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read temperature from STS40.
 * Returns 0 on success and stores the temperature in millidegrees Celsius.
 * Returns -1 on any I2C or CRC error.
 */
static int read_sts40(int fd, float *temperature) {
    uint8_t cmd[2] = { 0x36, 0x08 };
    ssize_t w = write(fd, cmd, sizeof(cmd));
    if (w != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "Error: write to STS40 failed (wrote %zd bytes)\n", w);
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    uint8_t buf[3];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "Error: read from STS40 failed (read %zd bytes)\n", r);
        return -1;
    }

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on STS40 data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temperature = (float)raw / 100.0f;
    return 0;
}

static void log_temperature(FILE *fp, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, temperature);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error: cannot open " I2C_DEVICE);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, STS40_ADDR) < 0) {
        perror("Error: cannot set I2C slave address 0x40");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error: cannot open " LOG_FILE);
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temperature;
        if (read_sts40(fd, &temperature) == 0) {
            log_temperature(fp, temperature);
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

