#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define SCD40_CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define SCD40_CMD_READ_MEASUREMENT 0xEC05
#define SCD40_CMD_GET_DATA_READY 0xE4BB
#define SCD40_CMD_SET_MEASUREMENT_INTERVAL 0x4615
#define SCD40_CMD_GET_TEMPERATURE_OFFSET 0xE318
#define SCD40_CMD_SET_TEMPERATURE_OFFSET 0x5445
#define SCD40_CMD_GET_ALTITUDE_COMPENSATION 0xE31A
#define SCD40_CMD_SET_ALTITUDE_COMPENSATION 0x5446
#define SCD40_CMD_GET_FIRMWARE_VERSION 0xE484
#define SCD40_CMD_SOFT_RESET 0x3041

#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define BUFFER_SIZE 100
#define LOGGING_INTERVAL_SEC 60
#define READ_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_SEC 1

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen error_log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int scd40_write_command(uint16_t command) {
    uint8_t buf[2] = { (command >> 8) & 0xFF, command & 0xFF };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        log_error("I2C write command failed");
        return -1;
    }
    return 0;
}

static int scd40_read_data(uint8_t *data, int len) {
    if (i2cReadDevice(i2c_handle, (char *)data, len) != len) {
        log_error("I2C read data failed");
        return -1;
    }
    return 0;
}

static int scd40_start_periodic_measurement(void) {
    if (scd40_write_command(SCD40_CMD_START_PERIODIC_MEASUREMENT) != 0)
        return -1;
    gpioDelay(MEASUREMENT_DELAY_SEC * 1000000);
    return 0;
}

static int scd40_stop_periodic_measurement(void) {
    return scd40_write_command(SCD40_CMD_STOP_PERIODIC_MEASUREMENT);
}

static int scd40_read_measurement(sensor_data_t *data) {
    if (scd40_write_command(SCD40_CMD_READ_MEASUREMENT) != 0)
        return -1;

    uint8_t raw[12];
    if (scd40_read_data(raw, 12) != 0)
        return -1;

    if (crc8(raw, 2) != raw[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(raw + 3, 2) != raw[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(raw + 6, 2) != raw[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }

    uint16_t co2_raw = (raw[0] << 8) | raw[1];
    uint16_t temp_raw = (raw[3] << 8) | raw[4];
    uint16_t hum_raw = (raw[6] << 8) | raw[7];

    data->co2 = (float)co2_raw;
    data->temperature = -45.0f + (float)temp_raw * 175.0f / 65535.0f;
    data->humidity = (float)hum_raw * 100.0f / 65535.0f;
    return 0;
}

static int scd40_get_data_ready(void) {
    if (scd40_write_command(SCD40_CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t buf[3];
    if (scd40_read_data(buf, 3) != 0)
        return -1;
    if (crc8(buf, 2) != buf[2]) {
        log_error("Data ready CRC mismatch");
        return -1;
    }
    uint16_t word = (buf[0] << 8) | buf[1];
    return (word & 0x07FF) ? 1 : 0;
}

static void circular_buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void circular_buffer_add(circular_buffer_t *cb, sensor_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

static int circular_buffer_get_all(circular_buffer_t *cb, sensor_data_t *out, int *out_count) {
    pthread_mutex_lock(&cb->mutex);
    int count = cb->count;
    if (count == 0) {
        pthread_mutex_unlock(&cb->mutex);
        return 0;
    }
    int start = cb->tail;
    for (int i = 0; i < count; i++) {
        out[i] = cb->data[(start + i) % BUFFER_SIZE];
    }
    cb->tail = (cb->tail + count) % BUFFER_SIZE;
    cb->count = 0;
    pthread_mutex_unlock(&cb->mutex);
    *out_count = count;
    return 1;
}

static void *logging_thread_func(void *arg) {
    circular_buffer_t *cb = (circular_buffer_t *)arg;
    char filename[256];
    time_t t;
    struct tm tm;

    while (running) {
        sensor_data_t *data = NULL;
        int count = 0;
        if (circular_buffer_get_all(cb, data, &count) && count > 0) {
            t = time(NULL);
            tm = *localtime(&t);
            snprintf(filename, sizeof(filename), "%s/scd40_data_%d-%02d-%02d_%02d-%02d-%02d.csv",
                     LOG_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                     tm.tm_hour, tm.tm_min, tm.tm_sec);

            FILE *fp = fopen(filename, "w");
            if (!fp) {
                log_error("Failed to open CSV file for writing");
                continue;
            }
            fprintf(fp, "CO2,Temperature,Humidity\n");
            for (int i = 0; i < count; i++) {
                fprintf(fp, "%.2f,%.2f,%.2f\n", data[i].co2, data[i].temperature, data[i].humidity);
            }
            fclose(fp);
        }
        sleep(LOGGING_INTERVAL_SEC);
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    circular_buffer_init(&buffer);

    if (scd40_start_periodic_measurement() != 0) {
        log_error("Failed to start periodic measurement");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    pthread_t logging_thread;
    if (pthread_create(&logging_thread, NULL, logging_thread_func, &buffer) != 0) {
        log_error("Failed to create logging thread");
        scd40_stop_periodic_measurement();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (scd40_get_data_ready() == 1) {
            sensor_data_t data;
            if (scd40_read_measurement(&data) == 0) {
                circular_buffer_add(&buffer, data);
            }
        }
        sleep(READ_INTERVAL_SEC);
    }

    pthread_join(logging_thread, NULL);

    scd40_stop_periodic_measurement();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

