    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    circular_buffer_init(&buffer);

    if (scd40_start_periodic_measurement() != 0) {
        log_error("Failed to start periodic measurement");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    pthread_t logging_thread;
    if (pthread_create(&logging_thread, NULL, logging_thread_func, &buffer) != 0) {
        log_error("Failed to create logging thread");
        scd40_stop_periodic_measurement();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (scd40_get_data_ready() == 1) {
            sensor_data_t data;
            if (scd40_read_measurement(&data) == 0) {
                circular_buffer_add(&buffer, data);
            }
        }
        sleep(READ_INTERVAL_SEC);
    }

    pthread_join(logging_thread, NULL);

    scd40_stop_periodic_measurement();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

