#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define SAMPLE_INTERVAL_SEC 5
#define SAMPLE_DELAY_US 10000
#define LOG_FILE "environmental_data.txt"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int handle, float *pressure, float *temperature) {
    char buf[6];
    if (i2cReadDevice(handle, buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }
    uint32_t raw_pressure = ((uint32_t)(uint8_t)buf[0] << 16) |
                            ((uint32_t)(uint8_t)buf[1] << 8)  |
                            ((uint32_t)(uint8_t)buf[2]);
    uint32_t raw_temp = ((uint32_t)(uint8_t)buf[3] << 16) |
                        ((uint32_t)(uint8_t)buf[4] << 8)  |
                        ((uint32_t)(uint8_t)buf[5]);
    *pressure = (float)raw_pressure / 1000.0f;
    *temperature = (float)raw_temp / 100.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n",
            timestamp, pressure, temperature);
    fflush(fp);
    printf("%s, Pressure: %.2f kPa, Temperature: %.2f C\n",
           timestamp, pressure, temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    while (running) {
        float pressure, temperature;
        if (read_sensor(handle, &pressure, &temperature) == 0) {
            log_data(fp, pressure, temperature);
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    fclose(fp);
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

