#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define ICP10125_ADDR   0x55
#define GPIO_LED        17
#define PRESSURE_THRESHOLD 95000.0f
#define POLL_DELAY_US   1000000
#define LOOP_DELAY_US   20000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc4(const uint8_t *data, int len) {
    uint8_t crc = 0x05;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x08) crc = (crc << 1) ^ 0x07;
            else           crc <<= 1;
        }
    }
    return crc & 0x0F;
}

static int i2c_read_sensor(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_icp10125(int fd, float *pressure, float *temperature) {
    uint8_t buf[6];
    if (i2c_read_sensor(fd, buf, 6) != 0) return -1;
    if (crc4(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc4(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);
    *pressure    = (float)raw_p / 100.0f;
    *temperature = (float)raw_t / 100.0f;
    return 0;
}

static void control_led(float pressure) {
    if (pressure < PRESSURE_THRESHOLD) {
        for (int i = 0; i < 5 && g_running; i++) {
            gpioWrite(GPIO_LED, 1);
            gpioDelay(100000);
            gpioWrite(GPIO_LED, 0);
            gpioDelay(100000);
        }
    } else {
        for (int i = 0; i < 5 && g_running; i++) {
            gpioWrite(GPIO_LED, 1);
            gpioDelay(500000);
            gpioWrite(GPIO_LED, 0);
            gpioDelay(500000);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    while (g_running) {
        float pressure, temperature;
        if (read_icp10125(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            control_led(pressure);
        } else {
            fprintf(stderr, "Sensor read failed; retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(GPIO_LED, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    gpioTerminate();
    return 0;
}

