#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define FAN_GPIO 18
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define HIGH_TEMP 30.0
#define LOW_TEMP 28.0
#define LOG_FILE "temperature_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_temperature(uint8_t reg, float *temp) {
    int raw;
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        raw = i2cReadWordData(i2c_handle, reg);
        if (raw >= 0) {
            *temp = (float)(raw * 0.02 - 40.0);
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X, attempt %d/%d): %s\n",
                reg, attempt + 1, RETRY_COUNT, strerror(errno));
        if (attempt < RETRY_COUNT - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static int log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", ts, ambient, object);
    } else {
        fprintf(fp, "(unknown time), Ambient: %.2f C, Object: %.2f C\n", ambient, object);
    }
    fclose(fp);
    return 0;
}

static void control_fan(float object) {
    static int fan_on = 0;
    if (object > HIGH_TEMP && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON (object %.2f C > %.1f C)\n", object, HIGH_TEMP);
    } else if (object < LOW_TEMP && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (object %.2f C < %.1f C)\n", object, LOW_TEMP);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(FAN_GPIO, 0);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float ambient, object;
        if (read_temperature(AMBIENT_TEMP_REG, &ambient) != 0 ||
            read_temperature(OBJECT_TEMP_REG, &object) != 0) {
            fprintf(stderr, "Sensor read failed; skipping cycle.\n");
        } else {
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Logging failed.\n");
            }
            control_fan(object);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

