#include <errno.h>
#include <stdint.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define HTTP_PORT 8080
#define MEASUREMENT_CMD 0x2408
#define MEASUREMENT_DELAY_US 10000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 100000

static int i2c_handle = -1;
static int server_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int sht40_read(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF};
    uint8_t data[6];
    int result;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cWriteDevice(handle, (char *)cmd, 2);
        if (result == 0) {
            gpioDelay(MEASUREMENT_DELAY_US);
            result = i2cReadDevice(handle, (char *)data, 6);
            if (result == 6) {
                uint16_t t_raw = (data[0] << 8) | data[1];
                uint16_t h_raw = (data[3] << 8) | data[4];
                *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
                *humidity = 100.0f * (float)h_raw / 65535.0f;
                return 0;
            }
        }
        fprintf(stderr, "SHT40 read attempt %d failed (result=%d, errno=%d: %s)\n",
                attempt + 1, result, errno, strerror(errno));
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int send_http_response(int handle, const char *body) {
    char header[256];
    int body_len = (int)strlen(body);
    int header_len = snprintf(header, sizeof(header),
                              "HTTP/1.1 200 OK\r\n"
                              "Content-Type: text/html\r\n"
                              "Content-Length: %d\r\n"
                              "Connection: close\r\n"
                              "\r\n", body_len);
    if (header_len < 0 || header_len >= (int)sizeof(header)) {
        fprintf(stderr, "HTTP header formatting failed\n");
        return -1;
    }
    if (handleWrite(handle, header, header_len) != header_len) {
        fprintf(stderr, "Failed to send HTTP header\n");
        return -1;
    }
    if (handleWrite(handle, body, body_len) != body_len) {
        fprintf(stderr, "Failed to send HTTP body\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (server_handle >= 0) {
        handleClose(server_handle);
        server_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device on bus %d addr 0x%02X: %d\n",
                I2C_BUS, SHT40_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    server_handle = handleHttp(HTTP_PORT);
    if (server_handle < 0) {
        fprintf(stderr, "Failed to start HTTP server on port %d\n", HTTP_PORT);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SHT40 web server running on port %d. Press Ctrl+C to stop.\n", HTTP_PORT);

    while (!terminate) {
        float temperature, humidity;
        if (sht40_read(i2c_handle, &temperature, &humidity) == 0) {
            if (humidity < 0.0f) humidity = 0.0f;
            if (humidity > 100.0f) humidity = 100.0f;

            char body[256];
            int body_len = snprintf(body, sizeof(body),
                                    "<html><body><h1>SHT40 Sensor Data</h1>"
                                    "<p>Temperature: %.2f &deg;C</p>"
                                    "<p>Humidity: %.2f %%</p></body></html>",
                                    temperature, humidity);
            if (body_len > 0 && body_len < (int)sizeof(body)) {
                if (send_http_response(server_handle, body) != 0) {
                    fprintf(stderr, "Failed to send HTTP response\n");
                }
            } else {
                fprintf(stderr, "HTTP body formatting failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read SHT40 after %d retries\n", RETRY_COUNT);
        }
        gpioDelay(1000000);
    }

    cleanup();
    printf("Server terminated gracefully.\n");
    return EXIT_SUCCESS;
}

