#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* HDC2010 I2C address (7-bit) */
#define HDC2010_ADDR 0x40

/* HDC2010 register addresses */
#define REG_TEMP_LOW    0x00
#define REG_TEMP_HIGH   0x01
#define REG_HUM_LOW     0x02
#define REG_HUM_HIGH    0x03
#define REG_MEAS_CONFIG 0x0E
#define REG_INT_CONFIG  0x0F
#define REG_DEV_ID      0xFE
#define REG_DEV_CONFIG  0xFF

/* Expected device ID for HDC2010 */
#define HDC2010_DEV_ID 0x00

/* Measurement configuration register bits */
#define MEAS_TRIGGER   0x01  /* bit 0: start a new measurement */
#define MEAS_MODE_BITS 0x02  /* bits 1:0 = measurement mode */
#define MEAS_MODE_T_H  0x00  /* temperature + humidity */
#define MEAS_MODE_T    0x01  /* temperature only */
#define MEAS_MODE_H    0x02  /* humidity only */

/* Polling timeout for measurement-ready (microseconds) */
#define MEAS_TIMEOUT_US 500000

/* Polling interval (microseconds) */
#define POLL_INTERVAL_US 10000

/* Max retries for transient I2C errors */
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a register                                   */
/* ------------------------------------------------------------------ */
static int hdc2010_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a register                                   */
/* ------------------------------------------------------------------ */
static int hdc2010_read_reg(uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair                            */
/* ------------------------------------------------------------------ */
static int hdc2010_read_reg16(uint8_t reg_low, uint16_t *out)
{
    int rc = i2cReadWordData(g_i2c_handle, reg_low);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n", reg_low, rc);
        return -1;
    }
    /* pigpio returns the word as (high << 8) | low, which matches the
       HDC2010 little-endian layout. */
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and wait for it to complete                   */
/* ------------------------------------------------------------------ */
static int hdc2010_trigger_and_wait(void)
{
    /* Trigger a temperature + humidity measurement */
    if (hdc2010_write_reg(REG_MEAS_CONFIG, MEAS_TRIGGER | MEAS_MODE_T_H) < 0)
        return -1;

    /* Poll the MEAS_CONFIG register until bit 0 clears (measurement done)
       or the timeout expires. */
    uint32_t elapsed = 0;
    uint8_t  cfg;
    while (elapsed < MEAS_TIMEOUT_US) {
        if (hdc2010_read_reg(REG_MEAS_CONFIG, &cfg) < 0)
            return -1;
        if ((cfg & MEAS_TRIGGER) == 0)
            return 0;
        gpioDelay(POLL_INTERVAL_US);
        elapsed += POLL_INTERVAL_US;
    }

    fprintf(stderr, "[ERROR] Measurement timeout (%u us)\n", MEAS_TIMEOUT_US);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity; returns 0 on success, -1 on error    */
/* ------------------------------------------------------------------ */
static int hdc2010_read_data(float *temperature, float *humidity)
{
    uint16_t raw_temp, raw_hum;

    if (hdc2010_trigger_and_wait() < 0)
        return -1;

    if (hdc2010_read_reg16(REG_TEMP_LOW, &raw_temp) < 0)
        return -1;

    if (hdc2010_read_reg16(REG_HUM_LOW, &raw_hum) < 0)
        return -1;

    /* HDC2010 conversion formulas (datasheet) */
    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the device ID                                                */
/* ------------------------------------------------------------------ */
static bool hdc2010_verify_device(void)
{
    uint8_t dev_id;
    if (hdc2010_read_reg(REG_DEV_ID, &dev_id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read device ID — sensor may be absent.\n");
        return false;
    }
    if (dev_id != HDC2010_DEV_ID) {
        fprintf(stderr, "[ERROR] Unexpected device ID 0x%02X (expected 0x%02X).\n",
                dev_id, HDC2010_DEV_ID);
        return false;
    }
    printf("[INFO] HDC2010 detected (device ID 0x%02X).\n", dev_id);
    return true;
}

/* ------------------------------------------------------------------ */
/* Initialize the HDC2010: verify device, configure measurement mode   */
/* ------------------------------------------------------------------ */
static bool hdc2010_init(void)
{
    if (!hdc2010_verify_device())
        return false;

    /* Set measurement mode to T + H (temperature + humidity) */
    if (hdc2010_write_reg(REG_MEAS_CONFIG, MEAS_MODE_T_H) < 0) {
        fprintf(stderr, "[ERROR] Failed to set measurement mode.\n");
        return false;
    }

    /* Clear any pending interrupt by writing 0x00 to the interrupt config */
    if (hdc2010_write_reg(REG_INT_CONFIG, 0x00) < 0) {
        fprintf(stderr, "[WARN] Failed to clear interrupt config.\n");
        /* Non-fatal: continue anyway */
    }

    return true;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the HDC2010 address */
    g_i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (!hdc2010_init()) {
        fprintf(stderr, "[FATAL] HDC2010 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] HDC2010 monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float temperature, humidity;
        int   retries = 0;
        bool  read_ok = false;

        while (retries < MAX_RETRIES && g_running) {
            if (hdc2010_read_data(&temperature, &humidity) == 0) {
                read_ok = true;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(100000); /* 100 ms backoff */
        }

        if (read_ok) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "[ERROR] Failed to read sensor data after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep 5 seconds, but wake early if a signal arrives */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

