#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SSR_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_PROFILE_POINTS 100
#define MAX_SPI_RETRIES 3
#define SAMPLE_PERIOD_US 1000000
#define SSR_UPDATE_PERIOD_US 1000000

typedef struct {
    double time;
    double temperature;
} TemperatureProfilePoint;

static TemperatureProfilePoint profile[MAX_PROFILE_POINTS];
static int profile_size = 0;
static volatile sig_atomic_t terminate = 0;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_max6675(int handle, float *temp) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};
    int retries = 0;

    while (retries < MAX_SPI_RETRIES) {
        if (spiXfer(handle, tx, rx, 4) == 4) {
            uint16_t raw = ((uint16_t)(rx[0] & 0xFF) << 8) | (uint16_t)(rx[1] & 0xFF);
            if (raw & 0x0001) {
                fprintf(stderr, "MAX6675: thermocouple fault (0x%04X)\n", raw);
                return -1;
            }
            *temp = (float)(raw >> 1) * 0.25f;
            return 0;
        }
        retries++;
        gpioDelay(1000);
    }
    fprintf(stderr, "MAX6675: SPI transfer failed after %d retries\n", MAX_SPI_RETRIES);
    return -1;
}

static int set_ssr_duty(int gpio, float duty) {
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 1.0f) duty = 1.0f;
    int level = (duty > 0.5f) ? 1 : 0;
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Failed to set SSR GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int load_profile(const char *filename, TemperatureProfilePoint *p, int max_size) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open profile file: %s\n", filename);
        return -1;
    }
    profile_size = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && profile_size < max_size) {
        if (sscanf(line, "%lf,%lf", &p[profile_size].time, &p[profile_size].temperature) == 2) {
            profile_size++;
        }
    }
    fclose(fp);
    if (profile_size == 0) {
        fprintf(stderr, "No valid profile points found in %s\n", filename);
        return -1;
    }
    printf("Loaded %d profile points from %s\n", profile_size, filename);
    return 0;
}

static double calculate_pid(double setpoint, double actual, double *integral, double *prev_error, double Kp, double Ki, double Kd) {
    double error = setpoint - actual;
    *integral += error;
    double derivative = error - *prev_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *prev_error = error;
    return output;
}

static int log_data(FILE *fp, double time, double temp, double pid_output) {
    if (fprintf(fp, "%.3f,%.2f,%.2f\n", time, temp, pid_output) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SSR_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set SSR GPIO %d as output\n", SSR_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(SSR_GPIO, 0);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "timestamp,temperature_c,pid_output\n");

    if (load_profile(PROFILE_FILE, profile, MAX_PROFILE_POINTS) != 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double integral = 0.0, prev_error = 0.0;
    double Kp = 10.0, Ki = 0.1, Kd = 0.01;
    uint64_t last_ssr_update = 0;

    while (!terminate) {
        double time = (double)time_time();
        float temp;
        if (read_max6675(spi_handle, &temp) != 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double pid_output = calculate_pid(profile[0].temperature, temp, &integral, &prev_error, Kp, Ki, Kd);

        if (log_data(log_file, time, temp, pid_output) != 0) {
            fprintf(stderr, "Logging error, continuing\n");
        }

        uint64_t now = time_time();
        if (now - last_ssr_update >= SSR_UPDATE_PERIOD_US) {
            double sum = 0.0;
            int count = 0;
            for (int i = 0; i < profile_size; i++) {
                if (profile[i].time <= time) {
                    sum += profile[i].temperature;
                    count++;
                } else {
                    break;
                }
            }
            if (count > 0) {
                double avg_temp = sum / count;
                double avg_pid = pid_output;
                double setpoint = avg_temp;
                double new_pid = calculate_pid(setpoint, temp, &integral, &prev_error, Kp, Ki, Kd);
                if (new_pid < 0.0) new_pid = 0.0;
                if (new_pid > 1.0) new_pid = 1.0;
                set_ssr_duty(SSR_GPIO, (float)new_pid);
            }
            last_ssr_update = now;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(SSR_GPIO, 0);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

