#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define DS18B20_DIR "/sys/bus/w1/devices/"
#define LOG_FILE "greenhouse.log"
#define PWM_CHANNEL 0
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 1000
#define PWM_DUTY_OFF 0
#define PWM_DUTY_ON 1000
#define SAMPLE_INTERVAL_US 5000000
#define MAX_SENSORS 10
#define MAX_SENSOR_NAME 20
#define MAX_SENSOR_DATA 16

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int pwm_initialized = 0;
static int relay_gpio = 17;
static double setpoint = 25.0;
static double kp = 1.0, ki = 0.1, kd = 0.01;
static double integral = 0.0, previous_error = 0.0;
static char sensor_ids[MAX_SENSORS][MAX_SENSOR_NAME];
static int num_sensors = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int find_ds18b20_sensors(void) {
    DIR *dir = opendir(DS18B20_DIR);
    if (!dir) {
        fprintf(stderr, "Error opening %s: %s\n", DS18B20_DIR, strerror(errno));
        return -1;
    }
    num_sensors = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL && num_sensors < MAX_SENSORS) {
        if (strncmp(entry->d_name, "28-", 3) == 0) {
            strncpy(sensor_ids[num_sensors], entry->d_name, MAX_SENSOR_NAME - 1);
            sensor_ids[num_sensors][MAX_SENSOR_NAME - 1] = '\0';
            num_sensors++;
        }
    }
    closedir(dir);
    if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found in %s\n", DS18B20_DIR);
        return -1;
    }
    return 0;
}

static int read_ds18b20(const char *sensor_id, double *temperature) {
    char path[256];
    snprintf(path, sizeof(path), "%s%s/w1_slave", DS18B20_DIR, sensor_id);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    char buffer[256];
    ssize_t bytes = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);
    if (bytes < 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        return -1;
    }
    buffer[bytes] = '\0';
    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }
    char *temp_str = strstr(buffer, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found in %s\n", sensor_id);
        return -1;
    }
    long raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (double)raw / 1000.0;
    return 0;
}

static double calculate_pid(double setpoint, double actual) {
    double error = setpoint - actual;
    integral += error;
    double derivative = error - previous_error;
    double output = kp * error + ki * integral + kd * derivative;
    previous_error = error;
    return output;
}

static int set_pwm_duty(int duty) {
    if (duty < PWM_DUTY_MIN) duty = PWM_DUTY_MIN;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    if (!pwm_initialized) {
        if (gpioSetPWMfrequency(PWM_CHANNEL, PWM_FREQ) < 0) {
            fprintf(stderr, "Failed to set PWM frequency\n");
            return -1;
        }
        if (gpioSetPWMrange(PWM_CHANNEL, PWM_RANGE) < 0) {
