#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_DEHUMID   17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define POLL_INTERVAL  5
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000
#define MEASURE_DELAY_US 80000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int gpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(uint8_t cmd) {
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("I2C write command failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, int len) {
    if (read(i2c_fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int aht20_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int aht20_read_humidity(float *humidity) {
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(0xAC) < 0) {
            retries++;
            if (retries < MAX_RETRIES) usleep(RETRY_DELAY_US);
            continue;
        }
        usleep(MEASURE_DELAY_US);

        if (i2c_read_bytes(buf, 6) < 0) {
            retries++;
            if (retries < MAX_RETRIES) usleep(RETRY_DELAY_US);
            continue;
        }

        if ((buf[0] & 0x80) != 0) {
            fprintf(stderr, "AHT20 busy or not calibrated\n");
            retries++;
            if (retries < MAX_RETRIES) usleep(RETRY_DELAY_US);
            continue;
        }

        uint32_t hum_raw = ((uint32_t)buf[1] << 12) |
                           ((uint32_t)buf[2] << 4)  |
                           ((uint32_t)buf[3] >> 4);
        *humidity = ((float)hum_raw / 1048576.0f) * 100.0f;
        return 0;
    }
    return -1;
}

static void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_HIGH) {
        if (!gpio_initialized) {
            if (gpioInitialise() < 0) {
                fprintf(stderr, "pigpio init failed\n");
                return;
            }
            gpio_initialized = 1;
        }
        gpioWrite(GPIO_DEHUMID, 1);
        printf("Dehumidifier ON (humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_LOW) {
        gpioWrite(GPIO_DEHUMID, 0);
        printf("Dehumidifier OFF (humidity: %.2f%%)\n", humidity);
    }
}

static void log_humidity(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (aht20_init() < 0) {
        fprintf(stderr, "AHT20 init failed\n");
        return 1;
    }

    while (running) {
        float humidity;
        if (aht20_read_humidity(&humidity) == 0) {
            log_humidity(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Failed to read humidity after %d retries\n", MAX_RETRIES);
        }
        sleep(POLL_INTERVAL);
    }

    if (gpio_initialized) {
        gpioWrite(GPIO_DEHUMID, 0);
        gpioTerminate();
    }
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

