#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTU21D_CMD_TEMP 0xE3
#define HTU21D_CMD_HUMID 0xE5
#define API_URL "http://api.example.com/humidity"
#define POLL_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (write(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    usleep(10000);
    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

float read_humidity(int fd) {
    uint8_t cmd = HTU21D_CMD_HUMID;
    uint8_t buf[3];
    if (i2c_read_bytes(fd, &cmd, 1) != 0) return -1.0f;
    if (i2c_read_bytes(fd, buf, 3) != 0) return -1.0f;

    uint32_t raw = ((uint32_t)buf[0] << 12) | ((uint32_t)buf[1] << 4) | ((uint32_t)buf[2] >> 4);
    float humidity = -6.0f + 125.0f * (float)raw / 65536.0f;
    if (humidity < 0.0f) humidity = 0.0f;
    if (humidity > 100.0f) humidity = 100.0f;
    return humidity;
}

float read_temperature(int fd) {
    uint8_t cmd = HTU21D_CMD_TEMP;
