#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define BMP280_I2C_BUS 1
#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_CMD 0xB6
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_CALIB_START_REG 0x88
#define BMP280_CALIB_LEN 24

#define PRESSURE_THRESHOLD_HIGH 1020.0
#define PRESSURE_THRESHOLD_LOW 980.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_WAIT_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X, rc=%d): %s\n", reg, rc, strerror(errno));
    }
    return rc;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write byte failed (reg 0x%02X, val 0x%02X, rc=%d): %s\n", reg, val, rc, strerror(errno));
    }
    return rc;
}

static int read_calibration_data(int handle) {
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2c_read_block(handle, BMP280_CALIB_START_REG, buf, BMP280_CALIB_LEN) < 0) {
        return -1;
    }
    calib.dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    calib.dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    calib.dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    calib.dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    calib.dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int init_bmp280(int handle) {
    uint8_t chip_id;
    if (i2c_read_block(handle, BMP280_CHIP_ID_REG, &chip_id, 1) < 0) {
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_RESET_REG, BMP280_RESET_CMD) < 0) {
        return -1;
    }
    gpioDelay(2000);
    if (read_calibration_data(handle) < 0) {
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_CTRL_MEAS_REG, 0x27) < 0) {
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_CONFIG_REG, 0x04) < 0) {
        return -1;
    }
    return 0;
}

static int read_raw_data(int handle, int32_t *raw_pressure, int32_t *raw_temp) {
    uint8_t buf[6];
    if (i2c_read_block(handle, BMP280_PRESS_MSB_REG, buf, 6) < 0) {
        return -1;
    }
    *raw_pressure = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    *raw_temp = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | ((int32_t)buf[5] >> 4);
    return 0;
}

static double compensate_temperature(int32_t raw_temp) {
    double var1 = ((double)raw_temp / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) *
                 ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * (double)calib.dig_T3;
    t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double compensate_pressure(int32_t raw_pressure) {
    double var1 = ((double)t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * (double)calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    var1 = ((double)calib.dig_P3 * var1 * var1 / 524288.0 + (double)calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)calib.dig_P1;
    if (var1 == 0.0) {
        return 0.0;
    }
    double p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)calib.dig_P7) / 16.0;
    return p;
}

static void log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f hPa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    }
    fclose(fp);
}

static int open_i2c(void) {
    int handle = i2cOpen(BMP280_I2C_BUS, BMP280_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %s\n",
                BMP280_I2C_BUS, BMP280_I2C_ADDR, strerror(errno));
        return -1;
    }
    return handle;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = open_i2c();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }
    if (init_bmp280(i2c_handle) < 0) {
        fprintf(stderr, "BMP280 initialisation failed\n");
        cleanup();
        return 1;
    }
    printf("BMP280 initialised. Monitoring pressure...\n");
    while (running) {
        int32_t raw_pressure, raw_temp;
        if (read_raw_data(i2c_handle, &raw_pressure, &raw_temp) < 0) {
            fprintf(stderr, "Failed to read raw data, retrying...\n");
            gpioDelay(100000);
            continue;
        }
        double temperature = compensate_temperature(raw_temp);
        double pressure = compensate_pressure(raw_pressure);
        printf("Pressure: %.2f hPa, Temperature: %.2f C\n", pressure, temperature);
        if (pressure > PRESSURE_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
            log_pressure(pressure);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

