/*
 * logger.c — TMP117 temperature + AHT20 humidity + PIR motion logger
 *
 * Build:  gcc -O2 -Wall -Wextra -o logger logger.c -lgpiod -lrt
 * Run:    ./logger   (needs read/write access to /dev/i2c-1 and /var/log)
 *
 * Hardware (Raspberry Pi 4B):
 *   TMP117  -> /dev/i2c-1, address 0x48
 *   AHT20   -> /dev/i2c-1, address 0x38
 *   PIR     -> gpiochip4 line 17 (GPIO17, physical pin 11)
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ----------------------------- Constants ------------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define TMP117_ADDR      0x48
#define AHT20_ADDR       0x38
#define PIR_CHIP         "gpiochip4"
#define PIR_LINE         17
#define LOG_DIR          "/var/log"
#define SAMPLE_PERIOD_S  1
#define I2C_RETRIES      3
#define I2C_BACKOFF_MS   10
#define TMP117_REG_TEMP  0x00
#define TMP117_REG_CTRL  0x08
#define AHT20_CMD_INIT   0xE1
#define AHT20_CMD_MEAS   0xAC
#define AHT20_CMD_RESET  0xBA
#define AHT20_CMD_CALIB  0xBE
#define AHT20_CAL_ACC    0x08
#define AHT20_CAL_REJ    0x18
#define AHT20_CAL_WAIT   20
#define AHT20_MEAS_WAIT  80

/* ----------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_pir  = NULL;

/* --------------------------- Prototypes -------------------------------- */
static void  sig_handler(int sig);
static int   i2c_open(const char *bus, uint8_t addr);
static int   i2c_write_reg8(int fd, uint8_t reg, uint8_t val);
static int   i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
static int   i2c_read_reg16(int fd, uint8_t reg, int16_t *val);
static int   tmp117_init(int fd);
static int   tmp117_read_temp(int fd, float *temp);
static int   aht20_init(int fd);
static int   aht20_read_humidity(int fd, float *hum);
static int   pir_init(void);
static int   pir_read(int *motion);
static int   log_open(void);
static void  log_close(void);
static void  log_line(float temp, float hum, int motion);
static void  cleanup(void);

/* --------------------------- Signal handler ---------------------------- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers -------------------------------- */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* --------------------------- TMP117 ------------------------------------- */
static int tmp117_init(int fd)
{
    /* Power on, default mode, 12-bit resolution */
    if (i2c_write_reg8(fd, TMP117_REG_CTRL, 0x00) < 0)
        return -1;
    usleep(10000);
    return 0;
}

static int tmp117_read_temp(int fd, float *temp)
{
    int16_t raw;
    if (i2c_read_reg16(fd, TMP117_REG_TEMP, &raw) < 0)
        return -1;
    *temp = (float)raw / 256.0f;
    return 0;
}

/* --------------------------- AHT20 -------------------------------------- */
static int aht20_init(int fd)
{
    if (i2c_write_reg8(fd, AHT20_CMD_RESET, 0x00) < 0)
        return -1;
    usleep(20000);
    if (i2c_write_reg8(fd, AHT20_CMD_CALIB, 0x00) < 0)
        return -1;
    usleep(AHT20_CAL_WAIT * 1000);
    return 0;
}

static int aht20_read_humidity(int fd, float *hum)
{
    uint8_t status;
    int16_t raw;

    if (i2c_write_reg8(fd, AHT20_CMD_MEAS, 0x00) < 0)
        return -1;
    usleep(AHT20_MEAS_WAIT * 1000);

    if (i2c_read_reg8(fd, AHT20_CMD_MEAS, &status) < 0)
        return -1;
    if (status & 0x08) {
        fprintf(stderr, "AHT20 busy\n");
        return -1;
    }
    if (status & 0x04) {
        fprintf(stderr, "AHT20 calibration error\n");
        return -1;
    }
    if (i2c_read_reg16(fd, AHT20_CMD_MEAS, &raw) < 0)
        return -1;

    uint32_t h = (uint32_t)raw;
    *hum = (float)h / 1048576.0f * 100.0f;
    return 0;
}

/* --------------------------- PIR ---------------------------------------- */
static int pir_init(void)
{
    g_chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", PIR_CHIP, strerror(errno));
        return -1;
    }
    g_pir = gpiod_chip_get_line(g_chip, PIR_LINE);
    if (!g_pir) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", PIR_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }
    if (gpiod_line_request_input(g_pir, "pir-logger") < 0) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", strerror(errno));
        g_pir = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }
    return 0;
}

static int pir_read(int *motion)
{
    int val = gpiod_line_get_value(g_pir);
    if (val < 0) {
        fprintf(stderr, "gpiod_line_get_value: %s\n", strerror(errno));
        return -1;
    }
    *motion = (val == 1) ? 1 : 0;
    return 0;
}

/* --------------------------- Logging ------------------------------------ */
static int log_open(void)
{
    time_t now = time(NULL);
    struct tm tm;
    char date[16];
    char path[256];

    localtime_r(&now, &tm);
    strftime(date, sizeof(date), "%Y%m%d", &tm);
    snprintf(path, sizeof(path), "%s/sensor_data_%s.csv", LOG_DIR, date);

    g_log_fp = fopen(path, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
        fflush(g_log_fp);
    }
    return 0;
}

static void log_close(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

static void log_line(float temp, float hum, int motion)
{
    time_t now = time(NULL);
    struct tm tm;
    char ts[32];

    localtime_r(&now, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_log_fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fflush(g_log_fp);
}

/* --------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    log_close();
    if (g_pir) {
        gpiod_line_release(g_pir);
        g_pir = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* --------------------------- Main --------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    if (pir_init() < 0) {
        fprintf(stderr, "PIR init failed; continuing without PIR logging.\n");
    }

    g_i2c_fd = i2c_open(I2C_BUS, TMP117_ADDR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "TMP117 not found at 0x%02X; continuing without TMP117.\n",
                TMP117_ADDR);
    } else {
        if (tmp117_init(g_i2c_fd) < 0) {
            fprintf(stderr, "TMP117 init failed; continuing without TMP117.\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
        }
    }

    int aht_ok = 0;
    g_i2c_fd = i2c_open(I2C_BUS, AHT20_ADDR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "AHT20 not found at 0x%02X; continuing without AHT20.\n",
                AHT20_ADDR);
    } else {
        if (aht20_init(g_i2c_fd) < 0) {
            fprintf(stderr, "AHT20 init failed; continuing without AHT20.\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
        } else {
            aht_ok = 1;
        }
    }

    if (log_open() < 0) {
        fprintf(stderr, "Log open failed; exiting.\n");
        cleanup();
        return 1;
    }

    printf("Logger started.  TMP117=%s  AHT20=%s  PIR=%s\n",
           g_i2c_fd >= 0 ? "yes" : "no",
           aht_ok ? "yes" : "no",
           g_pir ? "yes" : "no");

    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int   motion = 0;
        int   rc = 0;

        if (g_i2c_fd >= 0) {
            for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
                if (tmp117_read_temp(g_i2c_fd, &temp) == 0)
                    break;
                usleep(I2C_BACKOFF_MS * 1000);
            }
            if (aht_ok) {
                for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
                    if (aht20_read_humidity(g_i2c_fd, &hum) == 0)
                        break;
                    usleep(I2C_BACKOFF_MS * 1000);
                }
            }
        }

        if (g_pir) {
            for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
                if (pir_read(&motion) == 0)
                    break;
                usleep(I2C_BACKOFF_MS * 1000);
            }
        }

        log_line(temp, hum, motion);
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

