    uint32_t h = (uint32_t)raw;
    *hum = (float)h / 1048576.0f * 100.0f;
    return 0;
}

/* --------------------------- PIR ---------------------------------------- */
static int pir_init(void)
{
    g_chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", PIR_CHIP, strerror(errno));
        return -1;
    }
    g_pir = gpiod_chip_get_line(g_chip, PIR_LINE);
    if (!g_pir) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", PIR_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }
    if (gpiod_line_request_input(g_pir, "pir-logger") < 0) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", strerror(errno));
        g_pir = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }
    return 0;
}

static int pir_read(int *motion)
{
    int val = gpiod_line_get_value(g_pir);
    if (val < 0) {
        fprintf(stderr, "gpiod_line_get_value: %s\n", strerror(errno));
        return -1;
    }
    *motion = (val == 1) ? 1 : 0;
    return 0;
}

/* --------------------------- Logging ------------------------------------ */
static int log_open(void)
{
    time_t now = time(NULL);
    struct tm tm;
    char date[16];
    char path[256];

    localtime_r(&now, &tm);
    strftime(date, sizeof(date), "%Y%m%d", &tm);
    snprintf(path, sizeof(path), "%s/sensor_data_%s.csv", LOG_DIR, date);

    g_log_fp = fopen(path, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
        fflush(g_log_fp);
    }
    return 0;
}

static void log_close(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

static void log_line(float temp, float hum, int motion)
{
    time_t now = time(NULL);
    struct tm tm;
    char ts[32];

    localtime_r(&now, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_log_fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fflush(g_log_fp);
}

/* --------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    log_close();
    if (g_pir) {
        gpiod_line_release(g_pir);
        g_pir = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* --------------------------- Main --------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    if (pir_init() < 0) {
        fprintf(stderr, "PIR init failed; continuing without PIR logging.\n");
    }

    g_i2c_fd = i2c_open(I2C_BUS, TMP117_ADDR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "TMP117 not found at 0x%02X; continuing without TMP117.\n",
                TMP117_ADDR);
    } else {
        if (tmp117_init(g_i2c_fd) < 0) {
            fprintf(stderr, "TMP117 init failed; continuing without TMP117.\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
        }
    }

    int aht_ok = 0;
    g_i2c_fd = i2c_open(I2C_BUS, AHT20_ADDR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "AHT20 not found at 0x%02X; continuing without AHT20.\n",
                AHT20_ADDR);
    } else {
        if (aht20_init(g_i2c_fd) < 0) {
            fprintf(stderr, "AHT20 init failed; continuing without AHT20.\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
        } else {
            aht_ok = 1;
        }
    }

    if (log_open() < 0) {
        fprintf(stderr, "Log open failed; exiting.\n");
        cleanup();
        return 1;
    }

    printf("Logger started.  TMP117=%s  AHT20=%s  PIR=%s\n",
           g_i2c_fd >= 0 ? "yes" : "no",
           aht_ok ? "yes" : "no",
           g_pir ? "yes" : "no");

    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int   motion = 0;
        int   rc = 0;

        if (g_i2c_fd >= 0) {
            for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
                if (tmp117_read_temp(g_i2c_fd, &temp) == 0)
                    break;
                usleep(I2C_BACKOFF_MS * 1000);
            }
            if (aht_ok) {
                for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
                    if (aht20_read_humidity(g_i2c_fd, &hum) == 0)
                        break;
                    usleep(I2C_BACKOFF_MS * 1000);
                }
            }
        }

        if (g_pir) {
            for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
                if (pir_read(&motion) == 0)
                    break;
                usleep(I2C_BACKOFF_MS * 1000);
            }
        }

        log_line(temp, hum, motion);
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

