#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 17
#define MOTOR_ENA_GPIO   22
#define MOTOR_IN1_GPIO   23
#define MOTOR_IN2_GPIO   24

#define POLL_INTERVAL_US 2000000  /* 2 seconds */
#define MOTOR_RUN_US     5000000  /* 5 seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int safe_set_mode(unsigned gpio, unsigned mode)
{
    if (gpioSetMode(gpio, mode) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "ERROR: gpioSetMode(%u, %u) failed", gpio, mode);
        log_event(buf);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level)
{
    if (gpioWrite(gpio, level) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "ERROR: gpioWrite(%u, %u) failed", gpio, level);
        log_event(buf);
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        log_event("ERROR: pigpio initialisation failed");
        return -1;
    }

    if (safe_set_mode(RAIN_SENSOR_GPIO, PI_INPUT) < 0)
        return -1;
    if (safe_set_mode(MOTOR_ENA_GPIO, PI_OUTPUT) < 0)
        return -1;
    if (safe_set_mode(MOTOR_IN1_GPIO, PI_OUTPUT) < 0)
        return -1;
    if (safe_set_mode(MOTOR_IN2_GPIO, PI_OUTPUT) < 0)
        return -1;

    /* Ensure motor is stopped at startup */
    if (safe_write(MOTOR_ENA_GPIO, 0) < 0)
        return -1;
    if (safe_write(MOTOR_IN1_GPIO, 0) < 0)
        return -1;
    if (safe_write(MOTOR_IN2_GPIO, 0) < 0)
        return -1;

    return 0;
}

static void stop_motor(void)
{
    safe_write(MOTOR_ENA_GPIO, 0);
    safe_write(MOTOR_IN1_GPIO, 0);
    safe_write(MOTOR_IN2_GPIO, 0);
}

static int close_window(void)
{
    log_event("INFO: Closing window (motor forward)");

    if (safe_write(MOTOR_ENA_GPIO, 1) < 0)
        return -1;
    if (safe_write(MOTOR_IN1_GPIO, 1) < 0)
        return -1;
    if (safe_write(MOTOR_IN2_GPIO, 0) < 0)
        return -1;

    gpioDelay(MOTOR_RUN_US);

    log_event("INFO: Stopping motor");
    stop_motor();
    return 0;
}

static void cleanup(void)
{
    stop_motor();
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0)
        return EXIT_FAILURE;

    log_event("INFO: Rain sensor monitoring started (GPIO17, 2 s poll)");

    while (g_running) {
        int rain = gpioRead(RAIN_SENSOR_GPIO);
        if (rain < 0) {
            char buf[128];
            snprintf(buf, sizeof(buf), "ERROR: gpioRead(%d) failed", RAIN_SENSOR_GPIO);
            log_event(buf);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* YL-83 is active-low: 0 means rain detected */
        if (rain == 0) {
            log_event("INFO: Rain detected");
            if (close_window() < 0)
                log_event("ERROR: Motor command failed during close");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("INFO: Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

