#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define SAMPLE_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read CPU load from /proc/stat. Returns 0 on success, -1 on error. */
static int read_cpu_load(double *load)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen /proc/stat");
        return -1;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    unsigned long long prev_idle = idle + iowait;
    unsigned long long prev_non_idle = user + nice + system + irq + softirq + steal + guest + guest_nice;
    unsigned long long prev_total = prev_idle + prev_non_idle;

    /* Re-read after a short delay to avoid a brief spike in load. */
    usleep(100000);

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen /proc/stat (retry)");
        return -1;
    }
    unsigned long long user2, nice2, system2, idle2, iowait2, irq2, softirq2, steal2, guest2, guest_nice2;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user2, &nice2, &system2, &idle2, &iowait2, &irq2, &softirq2, &steal2, &guest2, &guest_nice2) != 10) {
        fprintf(stderr, "Error parsing /proc/stat (retry)\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    unsigned long long curr_idle = idle2 + iowait2;
    unsigned long long curr_non_idle = user2 + nice2 + system2 + irq2 + softirq2 + steal2 + guest2 + guest_nice2;
    unsigned long long curr_total = curr_idle + curr_non_idle;

    unsigned long long totald = curr_total - prev_total;
    unsigned long long idled = curr_idle - prev_idle;

    if (totald == 0) {
        *load = 0.0;
    } else {
        *load = (double)(totald - idled) / (double)totald * 100.0;
    }

    return 0;
}

/* Map load (0-100) to a color gradient: 0% = green, 50% = yellow, 100% = red. */
static void map_load_to_color(double load, int *r, int *g, int *b)
{
    if (load < 0.0) load = 0.0;
    if (load > 100.0) load = 100.0;

    if (load < 50.0) {
        *r = (int)((load / 50.0) * 255.0);
        *g = (int)((load / 50.0) * 255.0);
        *b = 0;
    } else {
        *r = (int)(((100.0 - load) / 50.0) * 255.0);
        *g = (int)(((100.0 - load) / 50.0) * 255.0);
        *b = 0;
    }
}

/* Set PWM duty cycle for a single channel. Common-anode LED: 0 = full on, 255 = full off. */
static int set_pwm(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;
    return gpioPWM(pin, 255 - duty);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    /* Configure pins as outputs. */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    /* Set PWM range to 255 (common-anode LED: 0 = full on, 255 = full off). */
    if (gpioSetPWMrange(RED_PIN, 255) != 0 ||
        gpioSetPWMrange(GREEN_PIN, 255) != 0 ||
        gpioSetPWMrange(BLUE_PIN, 255) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    /* Ensure LED is off initially. */
    set_pwm(RED_PIN, 255);
    set_pwm(GREEN_PIN, 255);
    set_pwm(BLUE_PIN, 255);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    double load;
    int r, g, b;

    while (g_running) {
        if (read_cpu_load(&load) != 0) {
            fprintf(stderr, "CPU load read failed, exiting\n");
            break;
        }

        map_load_to_color(load, &r, &g, &b);

        if (set_pwm(RED_PIN, r) != 0 ||
            set_pwm(GREEN_PIN, g) != 0 ||
            set_pwm(BLUE_PIN, b) != 0) {
            fprintf(stderr, "PWM write failed\n");
            break;
        }

        usleep(SAMPLE_US);
    }

    /* Clean shutdown: turn LED off. */
    set_pwm(RED_PIN, 255);
    set_pwm(GREEN_PIN, 255);
    set_pwm(BLUE_PIN, 255);
    gpioTerminate();
    return 0;
}

