    if (totald == 0) {
        *load = 0.0;
    } else {
        *load = (double)(totald - idled) / (double)totald * 100.0;
    }

    return 0;
}

/* Map load (0-100) to a color gradient: 0% = green, 50% = yellow, 100% = red. */
static void map_load_to_color(double load, int *r, int *g, int *b)
{
    if (load < 0.0) load = 0.0;
    if (load > 100.0) load = 100.0;

    if (load < 50.0) {
        *r = (int)((load / 50.0) * 255.0);
        *g = (int)((load / 50.0) * 255.0);
        *b = 0;
    } else {
        *r = (int)(((100.0 - load) / 50.0) * 255.0);
        *g = (int)(((100.0 - load) / 50.0) * 255.0);
        *b = 0;
    }
}

/* Set PWM duty cycle for a single channel. Common-anode LED: 0 = full on, 255 = full off. */
static int set_pwm(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;
    return gpioPWM(pin, 255 - duty);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    /* Configure pins as outputs. */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    /* Set PWM range to 255 (common-anode LED: 0 = full on, 255 = full off). */
    if (gpioSetPWMrange(RED_PIN, 255) != 0 ||
        gpioSetPWMrange(GREEN_PIN, 255) != 0 ||
        gpioSetPWMrange(BLUE_PIN, 255) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    /* Ensure LED is off initially. */
    set_pwm(RED_PIN, 255);
    set_pwm(GREEN_PIN, 255);
    set_pwm(BLUE_PIN, 255);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    double load;
    int r, g, b;

    while (g_running) {
        if (read_cpu_load(&load) != 0) {
            fprintf(stderr, "CPU load read failed, exiting\n");
            break;
        }

        map_load_to_color(load, &r, &g, &b);

        if (set_pwm(RED_PIN, r) != 0 ||
            set_pwm(GREEN_PIN, g) != 0 ||
            set_pwm(BLUE_PIN, b) != 0) {
            fprintf(stderr, "PWM write failed\n");
            break;
        }

        usleep(SAMPLE_US);
    }

    /* Clean shutdown: turn LED off. */
    set_pwm(RED_PIN, 255);
    set_pwm(GREEN_PIN, 255);
    set_pwm(BLUE_PIN, 255);
    gpioTerminate();
    return 0;
}

