#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int udp_socket = -1;

static int32_t t_fine;
static uint16_t dig_T1;
static int16_t dig_T2, dig_T3;
static uint16_t dig_P1;
static int16_t dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) return -1;
    return 0;
}

static int read_calibration_data(int handle) {
    uint8_t buf[24];
    if (i2c_read_reg(handle, BMP280_REG_CALIB, buf, 24) != 0) return -1;
    dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int init_bmp280(int handle) {
    uint8_t id;
    if (i2c_read_reg(handle, BMP280_REG_ID, &id, 1) != 0) {
        fprintf(stderr, "Error: Failed to read chip ID.\n");
        return -1;
    }
    if (id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x58).\n", id);
        return -1;
    }
    if (i2c_write_reg(handle, BMP280_REG_RESET, 0xB6) != 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(2000);
    if (read_calibration_data(handle) != 0) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }
    if (i2c_write_reg(handle, BMP280_REG_CONFIG, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) return -1;
    return 0;
}

static int read_raw_data(int handle, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t buf[6];
    if (i2c_read_reg(handle, BMP280_REG_PRESS_MSB, buf, 6) != 0) return -1;
    *raw_press = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    *raw_temp = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

static double compensate_temperature(int32_t raw_temp) {
    double var1 = ((double)raw_temp / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0) *
                 ((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0) * (double)dig_T3;
    t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double compensate_pressure(int32_t raw_press) {
    double var1 = ((double)t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * (double)dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)dig_P4 * 65536.0);
    var1 = ((double)dig_P3 * var1 * var1 / 524288.0 + (double)dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)dig_P1;
    if (var1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)dig_P7) / 16.0;
    return p;
}

static int send_udp_data(const char *json_data) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Error: Invalid address %s\n", UDP_SERVER_IP);
        return -1;
    }
    if (sendto(udp_socket, json_data, strlen(json_data), 0,
               (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (udp_socket >= 0) {
        close(udp_socket);
        udp_socket = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_bmp280(i2c_handle) != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed.\n");
        cleanup();
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error: socket creation failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        int32_t raw_temp, raw_press;
        if (read_raw_data(i2c_handle, &raw_temp, &raw_press) != 0) {
            fprintf(stderr, "Error: Failed to read raw data.\n");
        } else {
            double temperature = compensate_temperature(raw_temp);
            double pressure = compensate_pressure(raw_press);
            char json_data[128];
            snprintf(json_data, sizeof(json_data),
                     "{\"temperature\": %.2f, \"pressure\": %.2f}",
                     temperature, pressure);
            if (send_udp_data(json_data) != 0) {
                fprintf(stderr, "Error: Failed to send UDP data.\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

