#define SPI_CHANNEL 0
#define SPI_SPEED   500000
#define SPI_FLAGS   0
#define PWM_PIN     18
#define PWM_FREQ    1000
#define PWM_RANGE   255
#define BUFFER_SIZE 20
#define READ_INTERVAL_S 1

#define TEMP_MIN 25.0f
#define TEMP_MID 40.0f
#define TEMP_MAX 60.0f

#define FAN_OFF   0
#define FAN_LOW   50
#define FAN_MED   150
#define FAN_HIGH  200
#define FAN_FULL  255

typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} DataPoint;

static DataPoint buffer[BUFFER_SIZE];
static int       buffer_index = 0;
static int       buffer_count = 0;
static volatile sig_atomic_t running = 1;
static int       spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_to_buffer(time_t ts, float temp, int duty) {
    buffer[buffer_index].timestamp  = ts;
    buffer[buffer_index].temperature = temp;
    buffer[buffer_index].pwm_duty   = duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Circular Buffer Contents ---\n");
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char tbuf[32];
        struct tm *tm = localtime(&buffer[idx].timestamp);
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%d] %s  Temp: %.2f C  PWM: %d\n",
               i, tbuf, buffer[idx].temperature, buffer[idx].pwm_duty);
    }
    printf("--- End of Buffer ---\n");
}

static int read_max31855(float *temp_c) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected (0x%08X)\n", raw);
        return -1;
    }

    int16_t therm = (int16_t)(raw >> 18);
