#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_OSS 3

#define GPIO_PIN 2

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_active = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    int16_t vals[11];
    uint8_t regs[22] = {
        BMP180_REG_CAL_AC1, BMP180_REG_CAL_AC1 + 1,
        BMP180_REG_CAL_AC1 + 2, BMP180_REG_CAL_AC1 + 3,
        BMP180_REG_CAL_AC1 + 4, BMP180_REG_CAL_AC1 + 5,
        BMP180_REG_CAL_AC1 + 6, BMP180_REG_CAL_AC1 + 7,
        BMP180_REG_CAL_AC1 + 8, BMP180_REG_CAL_AC1 + 9,
        BMP180_REG_CAL_AC1 + 10
    };
    for (int i = 0; i < 11; i++) {
        if (i2cReadI2CBlockData(i2c_handle, regs[i], (char *)&vals[i], 2) != 2) {
            fprintf(stderr, "Error reading calibration data (AC1+%d).\n", i);
            return -1;
        }
    }
    ac1 = vals[0]; ac2 = vals[1]; ac3 = vals[2];
    ac4 = (uint16_t)vals[3]; ac5 = (uint16_t)vals[4]; ac6 = (uint16_t)vals[5];
    b1 = vals[6]; b2 = vals[7]; mb = vals[8]; mc = vals[9]; md = vals[10];
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error writing temperature command.\n");
        return -1;
    }
    gpioDelay(5000);
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature.\n");
        return -1;
    }
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error writing pressure command.\n");
        return -1;
    }
    gpioDelay(2000 + (3000 << BMP180_OSS));
    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure.\n");
        return -1;
    }
    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static double calculate_temperature(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;
}

static void log_data(double temp, double pres) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, pres);
    fflush(log_file);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    logging_active = !logging_active;
    printf("Logging %s\n", logging_active ? "ACTIVE" : "INACTIVE");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("BMP180 logger started. Press Ctrl+C to exit.\n");

    while (running) {
        if (logging_active) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) == 0 && read_raw_pressure(&up) == 0) {
                double temp = calculate_temperature(ut);
                double pres = calculate_pressure(up, ut);
                log_data(temp, pres);
            } else {
                fprintf(stderr, "Error reading sensor data.\n");
            }
        }
        gpioDelay(1000000);
    }

    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

