    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = {0};
    return spi_transfer(fd, tx, rx, 2);
}

static int max31865_read_reg(int fd, uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) return -1;
    *value = rx[1];
    return 0;
}

static int max31865_init(int fd) {
    uint8_t config = MAX31865_CONFIG_VBIAS | MAX31865_CONFIG_3WIRE |
                     MAX31865_CONFIG_FAULT_AUTO;
    if (max31865_write_reg(fd, MAX31865_CONFIG_REG, config) < 0) return -1;
    return 0;
}

static int max31865_read_rtd(int fd, float *rtd_temp) {
    uint8_t fault = 0;
    if (max31865_read_reg(fd, MAX31865_FAULT_REG, &fault) < 0) return -1;

    if (fault & (MAX31865_CONFIG_FAULT_OPEN |
                 MAX31865_CONFIG_FAULT_SHORT_GND |
                 MAX31865_CONFIG_FAULT_SHORT_VCC)) {
        fprintf(stderr, "MAX31865 fault detected: ");
        if (fault & MAX31865_CONFIG_FAULT_OPEN)
            fprintf(stderr, "open ");
        if (fault & MAX31865_CONFIG_FAULT_SHORT_GND)
            fprintf(stderr, "short_gnd ");
        if (fault & MAX31865_CONFIG_FAULT_SHORT_VCC)
            fprintf(stderr, "short_vcc ");
        fprintf(stderr, "\n");
        return -2;
    }

    uint8_t msb = 0, lsb = 0;
    if (max31865_read_reg(fd, MAX31865_RTD_MSB_REG, &msb) < 0) return -1;
    if (max31865_read_reg(fd, MAX31865_RTD_LSB_REG, &lsb) < 0) return -1;

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    raw >>= 1;

    if (raw == 0x0000 || raw == 0x8000) {
        fprintf(stderr, "RTD reading invalid (raw=0x%04X)\n", raw);
