        fprintf(stderr, "MAX31865 initialization failed\n");
        close(spi_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Temperature\n");
        fflush(log_fp);
    }

    printf("RTD temperature logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float temp = 0.0f;
        int ret = max31865_read_rtd(spi_fd, &temp);

        if (ret == 0) {
            log_temperature(log_fp, temp);
            printf("Temperature: %.2f C\n", temp);
        } else if (ret == -2) {
            fprintf(stderr, "Sensor fault, skipping log\n");
        } else {
            fprintf(stderr, "SPI read error, skipping log\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
