    cal.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    cal.dig_H1 = buf[25];

    uint8_t h_buf[7];
    if (i2c_read_reg(BME280_REG_CALIB_26, h_buf, 7) < 0) return -1;
    cal.dig_H2 = (int16_t)(h_buf[0] | (h_buf[1] << 8));
    cal.dig_H3 = h_buf[2];
    cal.dig_H4 = (int16_t)((h_buf[3] << 4) | (h_buf[4] & 0x0F));
    cal.dig_H5 = (int16_t)((h_buf[5] << 4) | (h_buf[4] >> 4));
    cal.dig_H6 = (int8_t)h_buf[6];
    return 0;
