    uint8_t data[8];
    if (i2c_read_reg(BME280_REG_DATA, data, 8) < 0) return -1;
    int32_t adc_P = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t adc_T = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t adc_H = (data[6] << 8) | data[7];
    *temp = compensate_temp(adc_T) / 100.0f;
    *press = compensate_press(adc_P) / 100.0f;
    *hum = compensate_hum(adc_H) / 1024.0f;
    return 0;
}

