    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[20];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(log_fp, "%s,%.2f,%.2f,%.2f\n", ts, temp, hum, press) < 0) return -1;
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) { perror("ioctl"); close(i2c_fd); return 1; }

    uint8_t id;
    if (i2c_read_reg(BME280_REG_ID, &id, 1) < 0) { fprintf(stderr, "I2C read error\n"); close(i2c_fd); return 1; }
    if (id != BME280_CHIP_ID) { fprintf(stderr, "Wrong chip ID: 0x%02X\n", id); close(i2c_fd); return 1; }

    if (i2c_write_reg(BME280_REG_RESET, BME280_RESET_CMD) < 0) { fprintf(stderr, "Reset failed\n"); close(i2c_fd); return 1; }
    usleep(2000);

    if (read_calibration() < 0) { fprintf(stderr, "Calibration read failed\n"); close(i2c_fd); return 1; }

    if (i2c_write_reg(BME280_REG_CTRL_HUM, 0x01) < 0) { fprintf(stderr, "Humidity config failed\n"); close(i2c_fd); return 1; }
    if (i2c_write_reg(BME280_REG_CONFIG, 0xA0) < 0) { fprintf(stderr, "Config failed\n"); close(i2c_fd); return 1; }
    if (i2c_write_reg(BME280_REG_CTRL_MEAS, 0x27) < 0) { fprintf(stderr, "Measurement failed\n"); close(i2c_fd); return 1; }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) { perror("fopen"); close(i2c_fd); return 1; }

    while (running) {
        float t, h, p;
        if (read_sensor(&t, &h, &p) == 0) {
            if (log_data(t, h, p) < 0) fprintf(stderr, "Log write failed\n");
        } else {
            fprintf(stderr, "Sensor read failed\n");
        }
        sleep(5);
    }

    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

