    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    mc = (int16_t)val;
    val = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);
    md = (int16_t)val;
