static void buffer_add(double pressure) {
    time(&pressure_buffer.buffer[pressure_buffer.head].timestamp);
    pressure_buffer.buffer[pressure_buffer.head].pressure = pressure;
    pressure_buffer.head = (pressure_buffer.head + 1) % BUFFER_SIZE;
    if (pressure_buffer.count < BUFFER_SIZE) pressure_buffer.count++;
