    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

