#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_BUS        "/dev/i2c-1"
#define BMP280_DEFAULT_ADDR   0x76
#define BMP280_ALT_ADDR       0x77

#define BMP280_REG_ID         0xD0
#define BMP280_REG_RESET      0xE0
#define BMP280_REG_CTRL_MEAS  0xF4
#define BMP280_REG_CONFIG     0xF5
#define BMP280_REG_PRESS_MSB  0xF7
#define BMP280_REG_TEMP_MSB   0xFA
#define BMP280_REG_CALIB      0x88

#define BMP280_CHIP_ID        0x58

#define OVERSAMPLING_TEMP     0x02
#define OVERSAMPLING_PRESS    0x05
#define MODE_FORCED           0x01
#define T_SB_500MS            0x00

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bmp280_read_calib(int fd, bmp280_calib_t *cal) {
    uint8_t buf[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB, buf, sizeof(buf)) != 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int bmp280_init(int fd, bmp280_calib_t *cal) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) != 0) {
        fprintf(stderr, "Error: failed to read chip ID\n");
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: chip ID 0x%02X != expected 0x%02X (BMP280)\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (bmp280_read_calib(fd, cal) != 0) {
        fprintf(stderr, "Error: failed to read calibration data\n");
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, (OVERSAMPLING_TEMP << 5) | (OVERSAMPLING_PRESS << 2) | T_SB_500MS) != 0) {
        fprintf(stderr, "Error: failed to write config register\n");
        return -1;
    }
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    uint8_t buf[6];
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, (OVERSAMPLING_TEMP << 5) | (OVERSAMPLING_PRESS << 2) | MODE_FORCED) != 0) {
        fprintf(stderr, "Error: failed to trigger forced measurement\n");
        return -1;
    }
    usleep(5000);
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, buf, 6) != 0) {
        fprintf(stderr, "Error: failed to read pressure/temperature data\n");
        return -1;
    }
    *raw_p = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    *raw_t = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | ((int32_t)buf[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_t, const bmp280_calib_t *cal, int32_t *t_fine) {
    double v1 = ((double)raw_t / 16384.0 - (double)cal->dig_T1 / 1024.0) * (double)cal->dig_T2;
    double v2 = (((double)raw_t / 131072.0 - (double)cal->dig_T1 / 8192.0) *
                 ((double)raw_t / 131072.0 - (double)cal->dig_T1 / 8192.0)) * (double)cal->dig_T3;
    *t_fine = (int32_t)(v1 + v2);
    return (v1 + v2) / 5120.0;
}

static double bmp280_compensate_press(int32_t raw_p, int32_t t_fine, const bmp280_calib_t *cal) {
    double v1 = (double)t_fine / 2.0 - 64000.0;
    double v2 = v1 * v1 * (double)cal->dig_P6 / 32768.0;
    v2 = v2 + v1 * (double)cal->dig_P5 * 2.0;
    v2 = v2 / 4.0 + (double)cal->dig_P4 * 65536.0;
    v1 = ((double)cal->dig_P3 * v1 * v1 / 524288.0 + (double)cal->dig_P2 * v1) / 524288.0;
    v1 = (1.0 + v1 / 32768.0) * (double)cal->dig_P1;
    if (v1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_p;
    p = (p - v2 / 4096.0) * 6250.0 / v1;
    v1 = (double)cal->dig_P9 * p * p / 2147483648.0;
    v2 = p * (double)cal->dig_P8 / 32768.0;
    p = p + (v1 + v2 + (double)cal->dig_P7) / 16.0;
    return p / 100.0;
}

static void format_data(const char *ts, double temp, double press, char *out, size_t outsz) {
    snprintf(out, outsz, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(BMP280_I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " BMP280_I2C_BUS);
        return 1;
    }

    int addr = BMP280_DEFAULT_ADDR;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl I2C_SLAVE 0x76");
        close(fd);
        return 1;
    }

    bmp280_calib_t cal;
    if (bmp280_init(fd, &cal) != 0) {
        fprintf(stderr, "BMP280 init failed at 0x%02X\n", addr);
        close(fd);
        return 1;
    }

    while (g_running) {
        int32_t raw_t, raw_p, t_fine;
        if (bmp280_read_raw(fd, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "Sensor read failed; continuing\n");
            sleep(1);
            continue;
        }
        double temp = bmp280_compensate_temp(raw_t, &cal, &t_fine);
        double press = bmp280_compensate_press(raw_p, t_fine, &cal);

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[20];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

        char line[128];
        format_data(ts, temp, press, line, sizeof(line));

        FILE *fp = fopen("weather_data.txt", "a");
        if (!fp) {
            perror("fopen weather_data.txt");
        } else {
            if (fputs(line, fp) == EOF) {
                perror("fputs");
            }
            fclose(fp);
        }
        sleep(5);
    }

    close(fd);
    return 0;
}

