    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(BMP280_I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " BMP280_I2C_BUS);
        return 1;
    }

    int addr = BMP280_DEFAULT_ADDR;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl I2C_SLAVE 0x76");
        close(fd);
        return 1;
    }

    bmp280_calib_t cal;
    if (bmp280_init(fd, &cal) != 0) {
        fprintf(stderr, "BMP280 init failed at 0x%02X\n", addr);
        close(fd);
        return 1;
    }

    while (g_running) {
        int32_t raw_t, raw_p, t_fine;
        if (bmp280_read_raw(fd, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "Sensor read failed; continuing\n");
            sleep(1);
            continue;
        }
        double temp = bmp280_compensate_temp(raw_t, &cal, &t_fine);
        double press = bmp280_compensate_press(raw_p, t_fine, &cal);

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[20];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

        char line[128];
        format_data(ts, temp, press, line, sizeof(line));

        FILE *fp = fopen("weather_data.txt", "a");
        if (!fp) {
            perror("fopen weather_data.txt");
        } else {
            if (fputs(line, fp) == EOF) {
                perror("fputs");
            }
            fclose(fp);
        }
        sleep(5);
    }

    close(fd);
    return 0;
}

