#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75_ADDR      0x48
#define TEMP_REG       0x00
#define ALERT_GPIO     18
#define TEMP_THRESHOLD 28.0f
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD_US 1000000

static int i2c_fd = -1;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t running = 1;

static float temperature_buffer[BUFFER_SIZE];
static int   buffer_index = 0;
static int   buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    char dev_path[32];
    snprintf(dev_path, sizeof(dev_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(dev_path, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int read_temperature(float *temp) {
    uint8_t reg = TEMP_REG;
    uint8_t data[2];

    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    if (read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temp = (float)raw / 256.0f;
    return 0;
}

static void add_to_buffer(float temp) {
    temperature_buffer[buffer_index] = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static float calculate_average(void) {
    if (buffer_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += temperature_buffer[i];
    return sum / (float)buffer_count;
}

static void *alert_thread(void *arg) {
    (void)arg;
    while (running) {
        float avg = calculate_average();
        if (avg > TEMP_THRESHOLD) {
            gpioWrite(ALERT_GPIO, 1);
        } else {
            gpioWrite(ALERT_GPIO, 0);
        }
        usleep(100000);
    }
    return NULL;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    if (i2c_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pthread_t alert_tid;
    if (pthread_create(&alert_tid, NULL, alert_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create alert thread: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            pthread_mutex_lock(&buffer_mutex);
            add_to_buffer(temp);
            pthread_mutex_unlock(&buffer_mutex);
            printf("Temperature: %.2f C, Average: %.2f C\n", temp, calculate_average());
        } else {
            fprintf(stderr, "Sensor read failed, attempting re-initialization...\n");
            close(i2c_fd);
            i2c_fd = -1;
            usleep(1000000);
            if (i2c_init() != 0) {
                fprintf(stderr, "Re-initialization failed, exiting.\n");
                break;
            }
        }
        usleep(SAMPLE_PERIOD_US);
    }

    running = 0;
    gpioWrite(ALERT_GPIO, 0);
    pthread_join(alert_tid, NULL);

    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    pthread_mutex_destroy(&buffer_mutex);

    return EXIT_SUCCESS;
}

