#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <cjson/cJSON.h>

#define CONFIG_FILE "config.json"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define SPI_MODE 1
#define SPI_BITS 8
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define PWM_DUTY_MAX 1000
#define TEMP_MAX 80.0
#define LOOP_DELAY_US 100000
#define RTD_REF_RESISTANCE 430.0
#define RTD_NOMINAL_RESISTANCE 100.0
#define RTD_ALPHA 0.0039083
#define RTD_ZERO_POINT_TEMP -273.15
#define RTD_ZERO_POINT_RESISTANCE 100.0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static double target_temperature = 25.0;
static double kp = 1.0;
static double ki = 0.1;
static double kd = 0.01;
static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    return 0;
}

static int read_max31865(double *temperature) {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    uint32_t raw = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) | ((uint32_t)rx[2] << 8) | rx[3];
    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31865 fault detected: 0x%08X\n", raw);
        return -1;
    }
    int16_t rtd_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (rtd_raw & 0x2000) rtd_raw |= 0xC000;
    double rtd_resistance = RTD_REF_RESISTANCE * (1.0 + (double)rtd_raw * RTD_ALPHA);
    double temp = (rtd_resistance / RTD_NOMINAL_RESISTANCE - 1.0) / RTD_ALPHA;
    *temperature = temp;
    return 0;
}

static int pwm_init(void) {
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return -1;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return -1;
    }
    if (gpioPWM(PWM_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialize PWM duty\n");
        return -1;
    }
    return 0;
}

static int set_pwm_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    if (gpioPWM(PWM_GPIO, duty) < 0) {
        fprintf(stderr, "Failed to set PWM duty\n");
        return -1;
    }
    return 0;
}

static int load_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Config file not found, using defaults\n");
        return 0;
    }
    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    char *buf = malloc(size + 1);
    if (!buf) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(fp);
        return -1;
    }
    size_t read_size = fread(buf, 1, size, fp);
    buf[read_size] = '\0';
    fclose(fp);
    cJSON *root = cJSON_Parse(buf);
    free(buf);
    if (!root) {
        const char *err = cJSON_GetErrorPtr();
        fprintf(stderr, "JSON parse error: %s\n", err ? err : "unknown");
        return -1;
    }
    cJSON *t = cJSON_GetObjectItemCaseSensitive(root, "target_temperature");
    if (t && t->type == cJSON_Number) target_temperature = t->valuedouble;
    cJSON *kp_val = cJSON_GetObjectItemCaseSensitive(root, "kp");
    if (kp_val && kp_val->type == cJSON_Number) kp = kp_val->valuedouble;
    cJSON *ki_val = cJSON_GetObjectItemCaseSensitive(root, "ki");
    if (ki_val && ki_val->type == cJSON_Number) ki = ki_val->valuedouble;
    cJSON *kd_val = cJSON_GetObjectItemCaseSensitive(root, "kd");
    if (kd_val && kd_val->type == cJSON_Number) kd = kd_val->valuedouble;
    cJSON_Delete(root);
    return 0;
}

static void log_data(double temperature, int pwm_duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("%s, Temperature: %.2f C, PWM Duty: %d\n", ts, temperature, pwm_duty);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }
    if (pwm_init() < 0) {
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (load_config() < 0) {
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    printf("Starting temperature regulation. Target: %.2f C, Kp: %.2f, Ki: %.2f, Kd: %.2f\n", target_temperature, kp, ki, kd);
    while (running) {
        double temperature = 0.0;
        if (read_max31865(&temperature) < 0) {
            fprintf(stderr, "SPI read failed, setting failsafe\n");
            set_pwm_duty(0);
            break;
        }
        double error = target_temperature - temperature;
        integral += error;
        double derivative = error - previous_error;
        double output = kp * error + ki * integral + kd * derivative;
        int pwm_duty = (int)(output * (PWM_DUTY_MAX / 100.0));
        if (pwm_duty < 0) pwm_duty = 0;
        if (pwm_duty > PWM_DUTY_MAX) pwm_duty = PWM_DUTY_MAX;
        if (temperature > TEMP_MAX) {
            fprintf(stderr, "Temperature exceeds %.1f C, setting failsafe\n", TEMP_MAX);
            set_pwm_duty(0);
            break;
        }
        if (set_pwm_duty(pwm_duty) < 0) {
            fprintf(stderr, "PWM set failed, setting failsafe\n");
            set_pwm_duty(0);
            break;
        }
        log_data(temperature, pwm_duty);
        previous_error = error;
        gpioDelay(LOOP_DELAY_US);
    }
    set_pwm_duty(0);
    if (spi_fd >= 0) close(spi_fd);
    gpioTerminate();
    printf("Shutdown complete\n");
    return 0;
}

