static int read_raw_pressure(int fd, int oss, int32_t *up) {
    uint8_t cmd;
    switch (oss) {
        case 0: cmd = BMP180_CMD_PRESSURE_OSS0; break;
        case 1: cmd = BMP180_CMD_PRESSURE_OSS1; break;
        case 2: cmd = BMP180_CMD_PRESSURE_OSS2; break;
        case 3: cmd = BMP180_CMD_PRESSURE_OSS3; break;
        default: return -1;
    }
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, cmd) < 0) return -1;
    usleep(20000);
    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *up = (int32_t)(((msb << 16) | (lsb << 8) | xlsb) >> (8 - oss));
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static float calculate_temperature(int32_t ut) {
    int32_t b5 = compute_b5(ut);
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int oss) {
    int32_t b5 = compute_b5(0);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
