    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p / 100.0f;
}

static int log_breach(float temp, float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return -1;
    time_t t = time(NULL);
