}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    if (read_calibration_data(i2c_fd) < 0) {
        fprintf(stderr, "Failed to read calibration data. Sensor may be absent.\n");
        close(i2c_fd);
        return 1;
    }

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t ut, up;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (read_raw_temperature(i2c_fd, &ut) == 0 && read_raw_pressure(i2c_fd, 0, &up) == 0) {
