            if (log_breach(temp, pressure) == 0) {
                printf("Breach detected! Temp: %.2f C, Pressure: %.2f hPa\n", temp, pressure);
            } else {
                fprintf(stderr, "Failed to log breach.\n");
            }
        }

        sleep(1);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("Exiting.\n");
    return 0;
}

