        }

        float temp = calculate_temperature(ut);
        float pressure = calculate_pressure(up, 0);

        if (temp > TEMP_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
            if (log_breach(temp, pressure) == 0) {
