#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS0 0x34
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 30.0
#define TIMER_INTERVAL_MS 500

typedef struct {
    time_t timestamp;
    double temperature;
    double pressure;
} Reading;

typedef struct {
    Reading readings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static CircularBuffer buffer;
static int32_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    int32_t vals[11];
    for (int i = 0; i < 11; i++) {
        int rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + i * 2);
        if (rc < 0) {
            fprintf(stderr, "Error reading calibration data (reg 0x%02X): %d\n",
                    BMP180_REG_CAL_AC1 + i * 2, rc);
            return -1;
        }
        vals[i] = (int32_t)rc;
    }
    ac1 = vals[0]; ac2 = vals[1]; ac3 = vals[2];
    ac4 = (uint16_t)vals[3]; ac5 = (uint16_t)vals[4]; ac6 = (uint16_t)vals[5];
    b1 = vals[6]; b2 = vals[7]; mb = vals[8]; mc = vals[9]; md = vals[10];
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0)
        return -1;
    gpioDelay(5000);
    int rc = i2cReadWordData(i2c_handle, BMP180_REG_MSB);
    if (rc < 0) return -1;
    *ut = (int32_t)rc;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS0) < 0)
        return -1;
    gpioDelay(5000);
    int rc = i2cReadWordData(i2c_handle, BMP180_REG_MSB);
    if (rc < 0) return -1;
    *up = (int32_t)rc;
    return 0;
}

static double calculate_temperature(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p / 100.0;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temperature(&ut) < 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return;
    }
    if (read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        return;
    }
    double temperature = calculate_temperature(ut);
    double pressure = calculate_pressure(up, ut);
    time_t now = time(NULL);
    buffer.readings[buffer.head].timestamp = now;
    buffer.readings[buffer.head].temperature = temperature;
    buffer.readings[buffer.head].pressure = pressure;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) buffer.count++;
    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n",
           (long)now, temperature, pressure);
    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
        printf("Fan ON\n");
    } else {
        gpioWrite(FAN_GPIO, 0);
        printf("Fan OFF\n");
    }
}

static void cleanup(void) {
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        cleanup();
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);
    buffer.head = 0;
    buffer.count = 0;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting timer\n");
        cleanup();
        return 1;
    }
    while (running) {
        gpioDelay(100000);
    }
    cleanup();
    return 0;
}

