#define BMP180_CMD_PRESSURE_OSS0 0x34
#define LOG_GPIO 27
#define LOG_INTERVAL_SEC 2
#define DEBOUNCE_MS 200

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_t log_thread;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    int n = i2cReadDevice(handle, (char *)buf, len);
    return (n == (int)len) ? 0 : -1;
}

static int read_calibration(int handle) {
    uint8_t buf[22];
    if (i2c_read_block(handle, BMP180_REG_CAL_AC1, buf, sizeof(buf)) < 0) return -1;
    ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1 = (int16_t)((buf[12] << 8) | buf[13]);
    b2 = (int16_t)((buf[14] << 8) | buf[15]);
    mb = (int16_t)((buf[16] << 8) | buf[17]);
    mc = (int16_t)((buf[18] << 8) | buf[19]);
    md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temp(int handle, int32_t *ut) {
    uint8_t buf[2];
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    if (i2c_read_block(handle, BMP180_REG_MSB, buf, 2) < 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    uint8_t buf[3];
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS0) < 0) return -1;
    gpioDelay(5000);
    if (i2c_read_block(handle, BMP180_REG_MSB, buf, 3) < 0) return -1;
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | buf[2]) >> 8;
    return 0;
}

static double compute_pressure(int32_t ut, int32_t up) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p;
}

static void log_data(double pressure) {
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        time_t t = time(NULL);
        struct tm tm;
        localtime_r(&t, &tm);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %.2f Pa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void *log_thread_func(void *arg) {
    (void)arg;
    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temp(0, &ut) == 0 && read_raw_pressure(0, &up) == 0) {
                double p = compute_pressure(ut, up);
                log_data(p);
            } else {
                fprintf(stderr, "I2C read error in log thread\n");
            }
        }
        sleep(LOG_INTERVAL_SEC);
    }
    return NULL;
}

static void gpio_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    static uint32_t last_tick = 0;
    uint32_t now = gpioTick();
    if ((now - last_tick) > (DEBOUNCE_MS * 1000)) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_tick = now;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    int handle = i2cOpen(1, BMP180_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    if (read_calibration(handle) < 0) {
        fprintf(stderr, "Calibration read failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LOG_GPIO, PI_INPUT);
    gpioSetPullUpDown(LOG_GPIO, PI_PUD_UP);
    if (gpioSetAlertFuncEx(LOG_GPIO, gpio_callback, NULL) < 0) {
        fprintf(stderr, "GPIO alert setup failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (pthread_create(&log_thread, NULL, log_thread_func, NULL) != 0) {
        perror("pthread_create");
        fclose(log_file);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    printf("Pressure logger running. Press GPIO27 to toggle logging.\n");
    while (running) sleep(1);

    pthread_join(log_thread, NULL);
    pthread_mutex_lock(&log_mutex);
    if (log_file) fclose(log_file);
    pthread_mutex_unlock(&log_mutex);
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

