#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        2000000
#define SPI_FLAGS        0
#define CS_PIN           8
#define HEATER_PIN       17
#define PWM_FREQUENCY    1000
#define PWM_RANGE        100
#define TARGET_TEMP      25.0
#define SAFE_MAX_DUTY    80.0
#define LOG_FILE         "heater_log.csv"
#define SAMPLE_PERIOD_US 1000000

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_read_max31855(int handle, float *temp_c, int *fault)
{
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (gpioWrite(CS_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(CS low) failed: %s\n", strerror(errno));
        return -1;
    }

    int ret = spiXfer(handle, tx, rx, 4);

    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(CS high) failed: %s\n", strerror(errno));
        return -1;
    }

    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        *fault = 1;
        return -1;
    }

    if (raw & 0x00000004) {
        *fault = 2;
        return -1;
    }

    if (raw & 0x00000002) {
        *fault = 3;
        return -1;
    }

    int16_t therm = (int16_t)(raw >> 18);
    *temp_c = therm * 0.25f;
    return 0;
}

static int set_heater_duty(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "gpioPWM(%d, %d) failed: %s\n", pin, duty, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, float temp, int duty, int fault)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%d,%d\n", ts, temp, duty, fault) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        gpioPWM(HEATER_PIN, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(CS) failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(CS init high) failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetMode(HEATER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(HEATER) failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpioSetPWMrange(HEATER_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (set_heater_duty(HEATER_PIN, 0) < 0) {
        fprintf(stderr, "Initial heater PWM set failed\n");
        cleanup();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(g_log_file, "# timestamp,temperature_c,duty_pct,fault_code\n");
    fflush(g_log_file);

    float integral = 0.0f;
    float last_temp = 0.0f;
    int   last_duty = 0;

    while (g_running) {
        float temp = 0.0f;
        int   fault = 0;

        if (spi_read_max31855(g_spi_handle, &temp, &fault) != 0) {
            fprintf(stderr, "SPI read error — setting duty to 0%%\n");
            if (set_heater_duty(HEATER_PIN, 0) < 0) {
                fprintf(stderr, "Failed to set heater to 0%%\n");
            }
            if (log_data(g_log_file, temp, 0, fault) < 0) {
                fprintf(stderr, "Logging failed\n");
            }
            last_duty = 0;
            last_temp = 0.0f;
            integral = 0.0f;
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float error = TARGET_TEMP - temp;
        integral += error;
        if (integral > 1000.0f) integral = 1000.0f;
        if (integral < -1000.0f) integral = -1000.0f;

        float p = 1.0f;
        float i = 0.1f;
        float d = 0.01f;
        float output = p * error + i * integral + d * (temp - last_temp);

        int duty = (int)(output + 0.5f);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;

        if (duty != last_duty) {
            if (set_heater_duty(HEATER_PIN, duty) == 0) {
                last_duty = duty;
            }
        }

        if (log_data(g_log_file, temp, duty, fault) < 0) {
            fprintf(stderr, "Logging failed\n");
        }

        last_temp = temp;
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

