#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <gpiod.h>

#define DHT22_GPIO_LINE 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 5
#define POLL_INTERVAL_SEC 5

volatile sig_atomic_t program_running = 1;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

void sleep_ms(int milliseconds) {
    struct timespec ts;
    ts.tv_sec = milliseconds / 1000;
    ts.tv_nsec = (milliseconds % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}

int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int counter = 0;
    int j = 0, i;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) {
        fprintf(stderr, "Failed to request line as output: %s\n", strerror(errno));
        return -1;
    }

    gpiod_line_set_value(line, 0);
    sleep_ms(1000);
    gpiod_line_set_value(line, 1);
    sleep_ms(30);

    if (gpiod_line_request_input(line, "dht22") < 0) {
        fprintf(stderr, "Failed to request line as input: %s\n", strerror(errno));
        return -1;
    }

    for (i = 0; i < 85; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == laststate) {
            counter++;
            sleep_ms(1);
            if (counter == 255) break;
        }
        laststate = gpiod_line_get_value(line);

        if (counter == 255) break;

        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    if (j < 40) {
        fprintf(stderr, "DHT22: Not enough data received (%d bits)\n", j);
        return -1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22: Checksum error\n");
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

int send_data(const char *url, const char *json_payload) {
    struct hostent *server;
    struct sockaddr_in serv_addr;
    int sockfd;
    char buffer[256];
    int bytes_sent, bytes_received;

    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation failed");
        return -1;
    }

    server = gethostbyname(url);
    if (server == NULL) {
        fprintf(stderr, "DNS resolution failed for %s\n", url);
        close(sockfd);
        return -1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);
    memcpy(&serv_addr.sin_addr.s_addr, server->h_addr, server->h_length);

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection failed");
        close(sockfd);
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s",
             url, url, strlen(json_payload), json_payload);

    bytes_sent = send(sockfd, buffer, strlen(buffer), 0);
    if (bytes_sent < 0) {
        perror("Send failed");
        close(sockfd);
        return -1;
    }

    bytes_received = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Receive failed");
        close(sockfd);
        return -1;
    }
    buffer[bytes_received] = '\0';

    close(sockfd);
    return 0;
}

void *sensor_thread(void *arg) {
    struct gpiod_chip *chip = (struct gpiod_chip *)arg;
    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT22_GPIO_LINE);
    float temperature, humidity;
    char json_payload[256];
    int retries;

    while (program_running) {
        retries = 0;
        while (retries < MAX_RETRIES && program_running) {
            if (read_dht22(line, &temperature, &humidity) == 0) {
                pthread_mutex_lock(&mutex);
                snprintf(json_payload, sizeof(json_payload), "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
                pthread_mutex_unlock(&mutex);

                if (send_data(SERVER_URL, json_payload) == 0) {
                    printf("Data sent successfully: %s\n", json_payload);
                    break;
                } else {
                    fprintf(stderr, "Failed to send data, retrying...\n");
                }
            } else {
                fprintf(stderr, "Failed to read DHT22 sensor, retrying...\n");
            }
            retries++;
            sleep(RETRY_DELAY_SEC);
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read DHT22 sensor after %d retries.\n", MAX_RETRIES);
        }
        sleep(POLL_INTERVAL_SEC);
    }
    pthread_exit(NULL);
}

int main() {
    struct gpiod_chip *chip;
    pthread_t sensor_thread_id;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    ret = pthread_create(&sensor_thread_id, NULL, sensor_thread, (void *)chip);
    if (ret != 0) {
        fprintf(stderr, "Failed to create sensor thread: %s\n", strerror(ret));
        gpiod_chip_close(chip);
        return 1;
    }

    pthread_join(sensor_thread_id, NULL);

    gpiod_chip_close(chip);
    printf("Program terminated.\n");
    return 0;
}

