#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <getopt.h>
#include <stdint.h>
#include <pthread.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 2
#define READ_INTERVAL_SEC 10
#define DHT_TIMEOUT_US 1000
#define MAX_JSON_LEN 256
#define API_URL_LEN 256

static volatile sig_atomic_t running = 1;
static char api_url[API_URL_LEN] = "http://your-the-library’s-API-call.com/api/humidity";
static pthread_mutex_t api_url_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_api_url(const char *url) {
    pthread_mutex_lock(&api_url_mutex);
    strncpy(api_url, url, API_URL_LEN - 1);
    api_url[API_URL_LEN - 1] = '\0';
    pthread_mutex_unlock(&api_url_mutex);
}

static int read_dht22(float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int i;
        uint32_t tick;
        int bit_idx = 0;
        int last_state = 1;

        memset(data, 0, sizeof(data));

        if (gpioSetMode(DHT22_GPIO, PI_OUTPUT) < 0) {
            syslog(LOG_ERR, "gpioSetMode failed: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(2000);
        gpioWrite(DHT22_GPIO, 1);
        gpioDelay(30);

        if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) {
            syslog(LOG_ERR, "gpioSetMode failed: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
            if (gpioTick() - tick > DHT_TIMEOUT_US) {
                syslog(LOG_ERR, "DHT22 response timeout (high)");
                retries++;
                sleep(RETRY_DELAY_SEC);
                goto retry;
            }
        }

        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 0) {
            if (gpioTick() - tick > DHT_TIMEOUT_US) {
                syslog(LOG_ERR, "DHT22 response timeout (low)");
                retries++;
                sleep(RETRY_DELAY_SEC);
                goto retry;
            }
        }

        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
            if (gpioTick() - tick > DHT_TIMEOUT_US) {
                syslog(LOG_ERR, "DHT22 data timeout");
                retries++;
                sleep(RETRY_DELAY_SEC);
                goto retry;
            }
        }

        for (i = 0; i < 40; i++) {
            tick = gpioTick();
            while (gpioRead(DHT22_GPIO) == last_state) {
                if (gpioTick() - tick > DHT_TIMEOUT_US) {
                    syslog(LOG_ERR, "DHT22 bit timeout");
                    retries++;
                    sleep(RETRY_DELAY_SEC);
                    goto retry;
                }
            }
            last_state = gpioRead(DHT22_GPIO);
            uint32_t high_tick = gpioTick();
            while (gpioRead(DHT22_GPIO) == last_state) {
                if (gpioTick() - high_tick > DHT_TIMEOUT_US) {
                    syslog(LOG_ERR, "DHT22 bit timeout");
                    retries++;
                    sleep(RETRY_DELAY_SEC);
                    goto retry;
                }
            }
            uint32_t low_tick = gpioTick();
            uint32_t duration = low_tick - high_tick;
            if (duration > 50) {
                data[bit_idx / 8] |= (1 << (7 - (bit_idx % 8)));
            }
            bit_idx++;
        }

        if (bit_idx != 40) {
            syslog(LOG_ERR, "DHT22 bit count mismatch: %d", bit_idx);
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        uint8_t checksum = (uint8_t)((data[0] + data[1] + data[2] + data[3]) & 0xFF);
        if (checksum != data[4]) {
            syslog(LOG_ERR, "DHT22 checksum failed: calc=0x%02X recv=0x%02X", checksum, data[4]);
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
        return 0;

    retry:
        retries++;
        sleep(RETRY_DELAY_SEC);
    }

    syslog(LOG_ERR, "DHT22 read failed after %d retries", MAX_RETRIES);
    return -1;
}

static int format_json(float humidity, char *json_string, size_t json_string_size) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        syslog(LOG_ERR, "localtime failed: %s", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    int ret = snprintf(json_string, json_string_size,
                       "{\"timestamp\": \"%s\", \"humidity\": %.1f}",
                       timestamp, humidity);
    if (ret < 0 || (size_t)ret >= json_string_size) {
        syslog(LOG_ERR, "JSON formatting failed");
        return -1;
    }
    return 0;
}

static int post_data(const char *json_string) {
    int retries = 0;
    char curl_command[MAX_JSON_LEN + 128];

    while (retries < MAX_RETRIES) {
        int ret = snprintf(curl_command, sizeof(curl_command),
                           "curl -s -X POST -H \"Content-Type: application/json\" "
                           "--data-binary '%s' %s",
                           json_string, api_url);
        if (ret < 0 || (size_t)ret >= sizeof(curl_command)) {
            syslog(LOG_ERR, "curl command buffer too small");
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        FILE *fp = popen(curl_command, "r");
        if (fp == NULL) {
            syslog(LOG_ERR, "popen failed: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        char buffer[128];
        int exit_code = pclose(fp);
        if (exit_code != 0) {
            syslog(LOG_ERR, "curl exited with code %d", exit_code);
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        return 0;
    }

    syslog(LOG_ERR, "POST failed after %d retries", MAX_RETRIES);
    return -1;
}

static void *read_and_post(void *arg) {
    (void)arg;
    float humidity;
    char json_string[MAX_JSON_LEN];

    while (running) {
        if (read_dht22(&humidity) == 0) {
            if (format_json(humidity, json_string, sizeof(json_string)) == 0) {
                if (post_data(json_string) != 0) {
                    syslog(LOG_ERR, "Failed to post data");
                } else {
                    syslog(LOG_INFO, "Data posted successfully: %s", json_string);
                }
            } else {
                syslog(LOG_ERR, "Failed to format JSON");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 sensor");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    int opt;
    pthread_t thread;

    openlog("dht22_logger", LOG_PID | LOG_CONS, LOG_USER);

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                set_api_url(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s api_url]\n", argv[0]);
                closelog();
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (pthread_create(&thread, NULL, read_and_post, NULL) != 0) {
        syslog(LOG_ERR, "pthread_create failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

