#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temp(float *temp_c) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    int raw;
    if (fscanf(fp, "%d", &raw) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp_c = (float)raw / 1000.0f;
    return 0;
}

static int read_fan_state(int *state) {
    FILE *fp = fopen(FAN_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }
    if (fscanf(fp, "%d", state) != 1) {
        fprintf(stderr, "Error reading fan state from %s\n", FAN_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state to %s\n", FAN_FILE);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_event(int fan_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s - Fan state changed to: %d\n", timestamp, fan_state) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int determine_fan_speed(float temp_c) {
    if (temp_c < 45.0f) return 0;
    if (temp_c < 55.0f) return 1;
    if (temp_c < 65.0f) return 2;
    return 3;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int fan_state = 0;
    if (read_fan_state(&fan_state) != 0) {
        fprintf(stderr, "Failed to read initial fan state. Exiting.\n");
        return 1;
    }

    printf("Fan control started. Initial state: %d\n", fan_state);

    while (running) {
        float temp_c;
        if (read_temp(&temp_c) != 0) {
            fprintf(stderr, "Temperature read failed. Retrying in %d seconds.\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        int new_fan_state = determine_fan_speed(temp_c);
        if (new_fan_state != fan_state) {
            if (write_fan_state(new_fan_state) == 0) {
                fan_state = new_fan_state;
                if (log_event(fan_state) != 0) {
                    fprintf(stderr, "Warning: failed to log event.\n");
                }
                printf("Temperature: %.2f C, Fan state: %d\n", temp_c, fan_state);
            } else {
                fprintf(stderr, "Failed to set fan state. Retrying in %d seconds.\n", POLL_INTERVAL);
            }
        }

        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    if (write_fan_state(0) != 0) {
        fprintf(stderr, "Warning: failed to turn off fan during shutdown.\n");
    }
    if (log_event(0) != 0) {
        fprintf(stderr, "Warning: failed to log shutdown event.\n");
    }
    printf("Fan control stopped.\n");
    return 0;
}

