    if (result != 4) {
        fprintf(stderr, "SPI read error: expected 4 bytes, got %d\n", result);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buffer[0] << 24) |
                   ((uint32_t)(uint8_t)buffer[1] << 16) |
                   ((uint32_t)(uint8_t)buffer[2] << 8)  |
                   ((uint32_t)(uint8_t)buffer[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected: ");
        if (raw & 0x00000001) fprintf(stderr, "Open circuit ");
        if (raw & 0x00000002) fprintf(stderr, "Short to GND ");
        if (raw & 0x00000004) fprintf(stderr, "Short to VCC ");
        fprintf(stderr, "\n");
        return -2;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temperature = temp_raw * 0.25;
    return 0;
}

static void set_heater_pwm(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(HEATER_GPIO, duty_cycle);
}

static void log_data(float temperature, int duty_cycle, float pid_output) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle, pid_output);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float integral = 0.0;
    float previous_error = 0.0;
    bool heater_enabled = false;

    while (running) {
        float temperature;
        int ret = read_max31855(&temperature);

        if (ret == 0) {
            if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
                fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
                if (heater_enabled) {
                    gpioPWM(HEATER_GPIO, 0);
                    heater_enabled = false;
                }
            } else {
                float error = TARGET_TEMPERATURE - temperature;
                integral += error;
                float derivative = error - previous_error;
                float output = KP * error + KI * integral + KD * derivative;

                int duty_cycle = (int)(output + 0.5);
                if (duty_cycle < 0) duty_cycle = 0;
                if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

                if (!heater_enabled) {
                    gpioPWM(HEATER_GPIO, duty_cycle);
                    heater_enabled = true;
                }

                log_data(temperature, duty_cycle, output);
                previous_error = error;
            }
        } else if (ret == -2) {
            fprintf(stderr, "MAX31855 fault detected, disabling heater\n");
            if (heater_enabled) {
                gpioPWM(HEATER_GPIO, 0);
                heater_enabled = false;
            }
            integral = 0.0;
            previous_error = 0.0;
        } else {
            fprintf(stderr, "Sensor read failed, disabling heater\n");
            if (heater_enabled) {
                gpioPWM(HEATER_GPIO, 0);
                heater_enabled = false;
            }
            integral = 0.0;
            previous_error = 0.0;
        }

        sleep(1);
    }

    gpioPWM(HEATER_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

