#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(handle, (char *)buf, 3);
        if (bytes_read == 3) {
            if (crc8(buf, 2) == buf[2]) {
                int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
                *flow_rate = (float)raw / 100.0f;
                return 0;
            }
            fprintf(stderr, "CRC mismatch on handle %d (attempt %d)\n", handle, retries + 1);
        } else {
            fprintf(stderr, "I2C read error on handle %d (attempt %d): %d\n", handle, retries + 1, bytes_read);
        }
        retries++;
        if (retries < MAX_RETRIES)
            gpioDelay(10000);
    }
    return -1;
}

static int log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, flow1, flow2);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%.2f,%.2f\n", flow1, flow2);
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device 0x%02X: %d\n", SENSOR1_ADDR, handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device 0x%02X: %d\n", SENSOR2_ADDR, handle2);
        i2cClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = read_flow_rate(handle1, &flow1);
        int ok2 = read_flow_rate(handle2, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            if (log_flow_data(flow1, flow2) != 0)
                fprintf(stderr, "Logging failed\n");
        } else {
            fprintf(stderr, "Sensor read failed (s1=%d, s2=%d)\n", ok1, ok2);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

