#define PULSES_PER_REVOLUTION 360

static volatile int running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int log_position(float position) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    if (fprintf(fp, "%s, %.2f\n", timestamp, position) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_A, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_A);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_B, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_B);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_A);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_B);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    int last_a = gpioRead(GPIO_A);
    int last_b = gpioRead(GPIO_B);
    if (last_a < 0 || last_b < 0) {
        fprintf(stderr, "Failed to read initial GPIO states\n");
        gpioTerminate();
        return 1;
    }

    int state = 0;
    float position = 0.0f;

    while (running) {
        int a = gpioRead(GPIO_A);
        int b = gpioRead(GPIO_B);

        if (a < 0 || b < 0) {
            fprintf(stderr, "Error reading GPIO pins\n");
            break;
        }

        if (a != last_a || b != last_b) {
            state = (state << 2) | (a << 1) | b;
            state &= 0x0F;

            switch (state) {
                case 0x01: case 0x02: case 0x04: case 0x08:
                    position += 360.0f / PULSES_PER_REVOLUTION;
                    break;
                case 0x03: case 0x06: case 0x09: case 0x0C:
                    position -= 360.0f / PULSES_PER_REVOLUTION;
                    break;
                case 0x05: case 0x0A: case 0x0D: case 0x0E:
                    position += 360.0f / PULSES_PER_REVOLUTION;
                    break;
                case 0x07: case 0x0B: case 0x0F: case 0x04:
                    position -= 360.0f / PULSES_PER_REVOLUTION;
                    break;
            }

            while (position < 0.0f) {
                position += 360.0f;
            }

            position = position - (int)(position / 360.0f) * 360.0f;

            if (log_position(position) != 0) {
                fprintf(stderr, "Error logging position\n");
            }

            last_a = a;
            last_b = b;
        }

        gpioDelay(1000);
    }

    gpioTerminate();
    return 0;
}

