            log_rpm(0.0);
        }
    }

    printf("\nShutting down...\n");
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

