#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_GPIO_LINE	17
#define TOUCH_CONSUMER	"ttp223_tamper"
#define POLL_INTERVAL_MS	100
#define TOUCH_DURATION_S	5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
	(void)sig;
	g_running = 0;
}

static int install_signal_handlers(void)
{
	struct sigaction sa;
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = signal_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;

	if (sigaction(SIGINT, &sa, NULL) == -1) {
		perror("sigaction(SIGINT)");
		return -1;
	}
	if (sigaction(SIGTERM, &sa, NULL) == -1) {
		perror("sigaction(SIGTERM)");
		return -1;
	}
	return 0;
}

static void sleep_ms(unsigned int ms)
{
	struct timespec ts;
	ts.tv_sec  = ms / 1000;
	ts.tv_nsec = (long)(ms % 1000) * 1000000L;
	nanosleep(&ts, NULL);
}

int main(void)
{
	struct gpiod_chip *chip = NULL;
	struct gpiod_line *line = NULL;
	struct timespec touch_start;
	int ret = EXIT_FAILURE;

	if (install_signal_handlers() != 0)
		return EXIT_FAILURE;

	chip = gpiod_chip_open_by_name("gpiochip4");
	if (chip == NULL) {
		fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
		return EXIT_FAILURE;
	}

	line = gpiod_chip_get_line(chip, TOUCH_GPIO_LINE);
	if (line == NULL) {
		fprintf(stderr, "Failed to get GPIO line %d: %s\n",
			TOUCH_GPIO_LINE, strerror(errno));
		goto cleanup;
	}

	if (gpiod_line_request_input_flags(line, TOUCH_CONSUMER,
					    GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
		fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
			TOUCH_GPIO_LINE, strerror(errno));
		goto cleanup;
	}

	printf("TTP223B touch sensor monitoring started on GPIO %d.\n",
	       TOUCH_GPIO_LINE);
	printf("Press Ctrl+C to exit.\n");

	while (g_running) {
		int val = gpiod_line_get_value(line);
		if (val < 0) {
			fprintf(stderr, "Failed to read GPIO line %d: %s\n",
				TOUCH_GPIO_LINE, strerror(errno));
			goto cleanup;
		}

		if (val == 1) {
			if (clock_gettime(CLOCK_MONOTONIC, &touch_start) == -1) {
				perror("clock_gettime");
				goto cleanup;
			}

			while (g_running) {
				val = gpiod_line_get_value(line);
				if (val < 0) {
					fprintf(stderr, "Failed to read GPIO line %d: %s\n",
						TOUCH_GPIO_LINE, strerror(errno));
					goto cleanup;
				}

				if (val == 0)
					break;

				struct timespec now;
				if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
					perror("clock_gettime");
					goto cleanup;
				}

				double elapsed = (now.tv_sec - touch_start.tv_sec) +
						 (now.tv_nsec - touch_start.tv_nsec) / 1e9;

				if (elapsed >= TOUCH_DURATION_S) {
					printf("ALERT: Tamper detected! Sensor touched for %.1f seconds.\n",
					       elapsed);
					fflush(stdout);
					break;
				}

				sleep_ms(POLL_INTERVAL_MS);
			}
		}

		if (g_running)
			sleep_ms(POLL_INTERVAL_MS);
	}

	ret = EXIT_SUCCESS;

cleanup:
	if (line != NULL)
		gpiod_line_release(line);
	if (chip != NULL)
		gpiod_chip_close(chip);

	if (ret == EXIT_SUCCESS)
		printf("Exiting cleanly.\n");
	return ret;
}

