#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <linux/i2s.h>
#include <pigpio.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define AUDIO_FILE "audio_capture.pcm"
#define GPIO_CHANNEL 17
#define SAMPLE_RATE 16000
#define BITS_PER_SAMPLE 16
#define NUM_CHANNELS 2
#define BUFFER_SIZE (SAMPLE_RATE * BITS_PER_SAMPLE / 8)

static volatile sig_atomic_t running = 1;
static int audio_fd = -1;
static FILE *audio_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_i2s(void) {
    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2S device %s: %s\n", I2S_DEVICE, strerror(errno));
        return -1;
    }

    int format = AFMT_S16_LE;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(fd, SNDCTL_DSP_SPEED, &rate) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(GPIO_CHANNEL, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_CHANNEL);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GPIO_CHANNEL, 0) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", GPIO_CHANNEL);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    audio_fd = init_i2s();
    if (audio_fd < 0) {
        gpioTerminate();
        return 1;
    }

    audio_file = fopen(AUDIO_FILE, "wb");
    if (audio_file == NULL) {
        fprintf(stderr, "Error opening audio file %s: %s\n", AUDIO_FILE, strerror(errno));
        close(audio_fd);
        gpioTerminate();
        return 1;
    }

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    uint8_t buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    while (running) {
        bytes_read = read(audio_fd, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
            break;
        }

        if (bytes_read == 0) {
            fprintf(stderr, "End of stream reached.\n");
            break;
        }

        if (fwrite(buffer, 1, bytes_read, audio_file) != (size_t)bytes_read) {
            fprintf(stderr, "Error writing to audio file: %s\n", strerror(errno));
            break;
        }
    }

    printf("Cleaning up...\n");
    if (audio_file) {
        fclose(audio_file);
    }
    if (audio_fd >= 0) {
        close(audio_fd);
    }
    gpioTerminate();

    printf("Audio capture stopped.\n");
    return 0;
}

