#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PWM_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define SENSOR_TIMEOUT_SEC 10

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set flame sensor pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(FAN_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set fan PWM pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty cycle\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(FAN_PWM_PIN, 0);
    gpioSetMode(FAN_PWM_PIN, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioTerminate();
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read flame sensor (GPIO%d)\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return value;
}

static void control_fan(int on) {
    if (gpioPWM(FAN_PWM_PIN, on ? 255 : 0) != 0) {
        fprintf(stderr, "Error: failed to set fan PWM duty cycle\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_event("Program started");

    time_t start_time = time(NULL);
    int flame_active = 0;

    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (sensor_value == 0) {
            if (!flame_active) {
                flame_active = 1;
                log_event("Flame detected");
                control_fan(1);
                start_time = time(NULL);
            }
        } else {
            if (flame_active) {
                flame_active = 0;
                log_event("Flame ended");
                control_fan(0);
            }
        }

        if (time(NULL) - start_time > SENSOR_TIMEOUT_SEC) {
            fprintf(stderr, "Warning: sensor timeout - no valid reading for %d seconds\n", SENSOR_TIMEOUT_SEC);
            log_event("Sensor timeout");
            start_time = time(NULL);
        }

        gpioDelay(DEBOUNCE_DELAY_US);
    }

    log_event("Program shutting down");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    return EXIT_SUCCESS;
}

