#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define TRIGGER_PIN 23
#define DATA_READY_PIN 24

#define MAGIC_NUMBER 4144
#define FRAME_SIZE 32768
#define FRAME_PERIOD_US 100000

#define START_FREQ 77.0f
#define END_FREQ 79.0f
#define CHIRPS 64
#define SAMPLES 256

typedef struct {
    uint32_t magic;
    uint32_t version;
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t chirps;
    uint32_t samples;
    uint32_t frame_size;
    uint32_t frame_period_us;
} ConfigHeader;

typedef struct {
    uint32_t timestamp_sec;
    uint32_t timestamp_nsec;
    uint32_t frame_number;
    uint8_t data[FRAME_SIZE];
} FrameData;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int gpio_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set data ready pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on data ready pin\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

int log_init(void) {
    log_file = fopen("radar_data.bin", "wb");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    ConfigHeader header = {
        .magic = MAGIC_NUMBER,
        .version = 1,
        .start_freq = (uint32_t)(START_FREQ * 1000.0f),
        .end_freq = (uint32_t)(END_FREQ * 1000.0f),
        .chirps = CHIRPS,
        .samples = SAMPLES,
        .frame_size = FRAME_SIZE,
        .frame_period_us = FRAME_PERIOD_US
    };

    if (fwrite(&header, sizeof(ConfigHeader), 1, log_file) != 1) {
        perror("Failed to write header");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    return 0;
}

int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

int capture_frame(uint8_t *frame_data) {
    uint8_t tx_buf[FRAME_SIZE];
    memset(tx_buf, 0, FRAME_SIZE);

    if (spi_transfer(tx_buf, frame_data, FRAME_SIZE) < 0) {
        return -1;
    }
    return 0;
}

int log_frame(uint8_t *frame_data) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        perror("clock_gettime failed");
        return -1;
    }

    FrameData frame;
    frame.timestamp_sec = (uint32_t)ts.tv_sec;
    frame.timestamp_nsec = (uint32_t)(ts.tv_nsec / 1000);
    frame.frame_number = 0;
    memcpy(frame.data, frame_data, FRAME_SIZE);

    if (fwrite(&frame, sizeof(FrameData), 1, log_file) != 1) {
        perror("Failed to write frame data");
        return -1;
    }

    fflush(log_file);
    return 0;
}

void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        return 1;
    }

    if (log_init() < 0) {
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Radar data acquisition started. Press Ctrl+C to stop.\n");

    uint8_t *frame_data = malloc(FRAME_SIZE);
    if (!frame_data) {
        perror("Failed to allocate frame data buffer");
        cleanup();
        return 1;
    }

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(100);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t timeout = 0;
        int ready = 0;
        while (running && !ready) {
            if (gpioRead(DATA_READY_PIN) == 0) {
                ready = 1;
            } else {
                gpioDelay(1000);
                timeout++;
                if (timeout > 1000) {
                    fprintf(stderr, "Timeout waiting for data ready\n");
                    break;
                }
            }
        }

        if (!ready) {
            continue;
        }

        if (capture_frame(frame_data) < 0) {
            fprintf(stderr, "Frame capture failed\n");
            continue;
        }

        if (log_frame(frame_data) < 0) {
            fprintf(stderr, "Frame logging failed\n");
        }

        gpioDelay(FRAME_PERIOD_US);
    }

    free(frame_data);
    cleanup();
    printf("Radar data acquisition stopped.\n");
    return 0;
}

