        .chirps = CHIRPS,
        .samples = SAMPLES,
        .frame_size = FRAME_SIZE,
        .frame_period_us = FRAME_PERIOD_US
    };

    if (fwrite(&header, sizeof(ConfigHeader), 1, log_file) != 1) {
        perror("Failed to write header");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    return 0;
}

int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

int capture_frame(uint8_t *frame_data) {
    uint8_t tx_buf[FRAME_SIZE];
    memset(tx_buf, 0, FRAME_SIZE);

    if (spi_transfer(tx_buf, frame_data, FRAME_SIZE) < 0) {
        return -1;
    }
    return 0;
}

int log_frame(uint8_t *frame_data) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        perror("clock_gettime failed");
        return -1;
    }

    FrameData frame;
    frame.timestamp_sec = (uint32_t)ts.tv_sec;
    frame.timestamp_nsec = (uint32_t)(ts.tv_nsec / 1000);
    frame.frame_number = 0;
    memcpy(frame.data, frame_data, FRAME_SIZE);

    if (fwrite(&frame, sizeof(FrameData), 1, log_file) != 1) {
        perror("Failed to write frame data");
        return -1;
    }

    fflush(log_file);
    return 0;
}

void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        return 1;
    }

    if (log_init() < 0) {
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Radar data acquisition started. Press Ctrl+C to stop.\n");

    uint8_t *frame_data = malloc(FRAME_SIZE);
    if (!frame_data) {
        perror("Failed to allocate frame data buffer");
        cleanup();
        return 1;
    }

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(100);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t timeout = 0;
        int ready = 0;
        while (running && !ready) {
            if (gpioRead(DATA_READY_PIN) == 0) {
                ready = 1;
            } else {
                gpioDelay(1000);
                timeout++;
                if (timeout > 1000) {
                    fprintf(stderr, "Timeout waiting for data ready\n");
                    break;
                }
            }
        }

        if (!ready) {
            continue;
        }

        if (capture_frame(frame_data) < 0) {
            fprintf(stderr, "Frame capture failed\n");
            continue;
        }

        if (log_frame(frame_data) < 0) {
            fprintf(stderr, "Frame logging failed\n");
        }

        gpioDelay(FRAME_PERIOD_US);
    }

    free(frame_data);
    cleanup();
    printf("Radar data acquisition stopped.\n");
    return 0;
}

