#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE 0.00001f
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int opt3001_write_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int opt3001_read_result(int handle, uint16_t *result) {
    char reg = RESULT_REG;
    char data[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error setting result register pointer: %s\n", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading result register: %s\n", strerror(errno));
        return -1;
    }
    *result = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int opt3001_read_lux(int handle, float *lux) {
    uint16_t raw;
    if (opt3001_read_result(handle, &raw) != 0) {
        return -1;
    }
    *lux = (float)raw * LUX_SCALE;
    return 0;
}

static int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", OPT3001_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    uint16_t config = 0xC003;
    if (opt3001_write_config(i2c_handle, config) != 0) {
        fprintf(stderr, "Error configuring OPT3001. Sensor may be absent.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (opt3001_read_lux(i2c_handle, &lux) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
        }

        if (success) {
            if (log_data("light_data.txt", lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux after %d attempts\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

