/*
 * Raspberry Pi 3 Model B+ — SainSmart IR Flame Detection Sensor Module
 *
 * Wiring:
 *   VCC  -> 3.3 V (Pin 1)
 *   GND  -> GND   (Pin 9)
 *   DOUT -> GPIO17 (Pin 11, BCM 17)
 *
 * DOUT is active-low: 0 = flame detected, 1 = no flame.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 *
 * Run:
 *   ./flame_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define FLAME_SENSOR_LINE 17          /* BCM 17 */
#define POLL_INTERVAL_SEC 1
#define CONSUMER_NAME     "flame-detect"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[timestamp-error]");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[timestamp-error]");
        return;
    }

    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[timestamp-error]");
        return;
    }

    printf("%s", buf);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the default gpiochip (gpiochip0 on Pi 3 B+) ---------- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name(\"gpiochip0\") "
                "failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get the line for BCM 17 ---------------------------------- */
    line = gpiod_chip_get_line(chip, FLAME_SENSOR_LINE);
    if (line == NULL) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d) failed: %s\n",
                FLAME_SENSOR_LINE, strerror(errno));
        goto cleanup_chip;
    }

    /* ---- Request the line as input with pull-up ------------------- */
    /*
     * Request flags:
     *   GPIOD_LINE_REQUEST_DIRECTION_INPUT:  the line is read-only.
