#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

/* BCM GPIO pins for TTP226 OUT1..OUT8 */
static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    } else {
        printf("[unknown] ");
    }
}

int main(void)
{
    int i;
    int ret;
    int pigpio_initialized = 0;
    int line_handles[NUM_CHANNELS];
    int line_requested[NUM_CHANNELS];

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }
    pigpio_initialized = 1;

    /* Open the default GPIO chip (gpiochip0 on Raspberry Pi) */
    gpioCfgClock(5, 1, 0);  /* 5 MHz, allow remapping, no external clock */

    /* Request each channel line as input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        line_handles[i] = gpioGetLine(channel_pins[i]);
        if (line_handles[i] < 0) {
            fprintf(stderr, "Error: gpioGetLine(%d) failed: %s\n",
                    channel_pins[i], pigpio_error(line_handles[i]));
            goto cleanup;
        }
        line_requested[i] = 0;

        ret = gpioSetMode(line_handles[i], PI_INPUT);
        if (ret != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed: %s\n",
                    channel_pins[i], pigpio_error(ret));
            goto cleanup;
        }
        line_requested[i] = 1;
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        print_timestamp();

        for (i = 0; i < NUM_CHANNELS; i++) {
            int value = gpioRead(line_handles[i]);
            if (value < 0) {
                fprintf(stderr, "Error: gpioRead(%d) failed: %s\n",
                        channel_pins[i], pigpio_error(value));
                goto cleanup;
            }
            printf("CH%d: %d ", i + 1, value);
        }
        printf("\n");
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    /* Release all line handles that were requested */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (line_requested[i]) {
            gpioSetMode(line_handles[i], PI_INPUT);  /* restore to safe state */
        }
    }

    if (pigpio_initialized) {
        gpioTerminate();
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

