#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure eight sensor output pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = i + 2;  /* GPIO 2..9 */
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Allow pull-down resistors to settle */
    gpioDelay(10000);  /* 10 ms */

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int values[NUM_CHANNELS];
        int rc = gpioReadAll(values, NUM_CHANNELS);

        if (rc != 0) {
            fprintf(stderr, "Error: gpioReadAll failed (code %d).\n", rc);
            break;
        }

        printf("[+%d ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               gpioTick() / 1000,
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

