/*
 * Hall-Effect Latch Sensor Reader for Raspberry Pi 3 Model B+
 * Sensors : TMAG5110 (Texas Instruments)
 * Pins    : Sensor 1 OUT -> BCM GPIO4 (physical pin 7)
 *           Sensor 2 OUT -> BCM GPIO5 (physical pin 8)
 *
 * The TMAG5110 OUT pin is open-drain; an unasserted output reads HIGH
 * and a magnet-detected assertion reads LOW.  External pull-ups are
 * required on the OUT pins to keep them HIGH when the sensor is
 * disconnected.
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lthe driver library -lrt
 *
 * Run:
 *   sudo ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#include <the_driver_library.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize the driver library --- */
    if (the_driver_library_init() != 0) {
        fprintf(stderr, "Failed to initialize the driver library.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins as inputs --- */
    if (gpio_set_mode(SENSOR_1_PIN, GPIO_MODE_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        the_driver_library_terminate();
        return EXIT_FAILURE;
    }
    if (gpio_set_mode(SENSOR_2_PIN, GPIO_MODE_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        the_driver_library_terminate();
        return EXIT_FAILURE;
    }

    /*
     * TMAG5110 OUT pin is open-drain; external pull-ups are required
     * to keep the pin HIGH when the sensor is disconnected.
     */
    if (gpio_set_pull(SENSOR_1_PIN, GPIO_PULL_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d.\n", SENSOR_1_PIN);
        the_driver_library_terminate();
        return EXIT_FAILURE;
    }
    if (gpio_set_pull(SENSOR_2_PIN, GPIO_PULL_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d.\n", SENSOR_2_PIN);
        the_driver_library_terminate();
        return EXIT_FAILURE;
    }

    printf("Hall-Effect Latch Sensor Reader\n");
    printf("Sensor 1 OUT: BCM GPIO%d | Sensor 2 OUT: BCM GPIO%d\n",
           SENSOR_1_PIN, SENSOR_2_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = gpio_read(SENSOR_1_PIN);
        int s2 = gpio_read(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading GPIO pins (s1=%d, s2=%d).\n", s1, s2);
            break;
        }

        printf("Sensor 1: %s | Sensor 2: %s\n",
               s1 ? "HIGH" : "LOW",
               s2 ? "HIGH" : "LOW");
        fflush(stdout);

        sleep_ms(POLL_INTERVAL_MS);
    }

    /* --- Clean shutdown --- */
    the_driver_library_terminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

