#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_PIN 4          /* BCM pin 7 */
#define POLL_INTERVAL_US 100000    /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int ret;
    int last_state = -1;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO4 as input with internal pull-up --- */
    ret = gpioSetMode(TILT_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d (code %d).\n",
                TILT_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(TILT_SENSOR_PIN, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d (code %d).\n",
                TILT_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO%d.\n", TILT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int level = gpioRead(TILT_SENSOR_PIN);

        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed for pin %d (code %d).\n",
                    TILT_SENSOR_PIN, level);
            break;
        }

        if (level != last_state) {
            last_state = level;
            fflush(stdout);
            printf("Tilted\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

