#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60

#define SI1145_REG_PARTID 0x00
#define SI1145_REG_REVID 0x01
#define SI1145_REG_SEQID 0x02
#define SI1145_REG_INTCFG 0x03
#define SI1145_REG_IRQEN 0x04
#define SI1145_REG_IRQMODE1 0x05
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEASRATE0 0x08
#define SI1145_REG_MEASRATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UVINDEX0 0x2C
#define SI1145_REG_UVINDEX1 0x2D

#define SI1145_HW_KEY_VAL 0x17
#define SI1145_PARTID_VAL 0x45

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int init_si1145(int fd) {
    uint8_t partid;
    if (i2c_read_reg(fd, SI1145_REG_PARTID, &partid) < 0) {
        fprintf(stderr, "Error: Failed to read PARTID register.\n");
        return -1;
    }
    if (partid != SI1145_PARTID_VAL) {
        fprintf(stderr, "Error: Unexpected PARTID 0x%02X (expected 0x%02X). Sensor not present?\n", partid, SI1145_PARTID_VAL);
        return -1;
    }

    if (i2c_write_reg(fd, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY.\n");
        return -1;
    }

    if (i2c_write_reg(fd, SI1145_REG_MEASRATE0, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set measurement rate.\n");
        return -1;
    }

    if (i2c_write_reg(fd, SI1145_REG_MEASRATE1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set measurement rate.\n");
        return -1;
    }

    return 0;
}

static int read_si1145_data(int fd, uint16_t *uv_index, uint16_t *als_visible) {
    uint8_t uv_low, uv_high, als_low, als_high;

    if (i2c_read_reg(fd, SI1145_REG_UVINDEX0, &uv_low) < 0) return -1;
    if (i2c_read_reg(fd, SI1145_REG_UVINDEX1, &uv_high) < 0) return -1;
    if (i2c_read_reg(fd, SI1145_REG_ALS_VIS_DATA0, &als_low) < 0) return -1;
