#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define ALARM_GPIO     17
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define MEAS_DELAY_US  100000   /* 100 ms after start command */
#define READ_DELAY_US  1000000  /* 1 s between readings */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ---- Sensirion 8-bit CRC (polynomial 0x31, init 0xFF) ---- */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- I2C helpers ---- */
static int i2c_write_cmd(int fd, uint8_t addr, const uint8_t *cmd, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl I2C_SLAVE");
        return -1;
    }
    if (write(fd, cmd, len) != (ssize_t)len) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t addr, uint8_t *buf, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl I2C_SLAVE");
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read: expected %zu, got %zd\n", len, n);
        return -1;
    }
    return 0;
}

/* ---- Sensor read: start + wait + read 4 bytes ---- */
static int read_flow_rate(int fd, uint8_t addr, float *out)
{
    uint8_t cmd[2] = { 0x36, 0x08 };  /* mass flow continuous mode */
    if (i2c_write_cmd(fd, addr, cmd, sizeof(cmd)) < 0)
        return -1;

    gpioDelay(MEAS_DELAY_US);

    uint8_t buf[4];
    if (i2c_read_data(fd, addr, buf, sizeof(buf)) < 0)
        return -1;

    /* CRC covers bytes 0-1 (2 data bytes) */
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on sensor 0x%02X\n", addr);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out = (float)raw / 60.0f;  /* scale factor per datasheet */
    return 0;
}

/* ---- Logging ---- */
static void log_flow_rate(FILE *f, float avg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(f, "%04d-%02d-%02d %02d:%02d:%02d, Average Flow Rate: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg);
    fflush(f);
}

/* ---- Alarm ---- */
static void set_alarm(int gpio, float avg)
{
    int level = (avg < FLOW_THRESHOLD) ? 1 : 0;
    if (gpioWrite(gpio, level) < 0)
        fprintf(stderr, "gpioWrite(%d) failed\n", gpio);
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* I2C open */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* GPIO setup */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", ALARM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* Log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signals */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = 0, ok2 = 0;

        if (read_flow_rate(g_i2c_fd, SENSOR1_ADDR, &f1) == 0)
            ok1 = 1;
        if (read_flow_rate(g_i2c_fd, SENSOR2_ADDR, &f2) == 0)
            ok2 = 1;

        if (ok1 && ok2) {
            float avg = (f1 + f2) / 2.0f;
            log_flow_rate(g_log, avg);
            set_alarm(ALARM_GPIO, avg);
        } else {
            fprintf(stderr, "Skipping cycle due to I2C error.\n");
        }

        gpioDelay(READ_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

