#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_PIN 4          /* BCM 4, physical pin 7 */
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 50000  /* 50 ms */

typedef struct {
    time_t timestamp;
    int    level;
} SensorData;

static SensorData buffer[BUFFER_SIZE];
static int        buffer_index = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void add_to_buffer(int level)
{
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].level     = level;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void)
{
    printf("\n--- Sensor Data Buffer Dump ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm tm_info;
        if (localtime_r(&buffer[idx].timestamp, &tm_info) != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(time_str, sizeof(time_str), "<unknown>");
        }
        printf("[%s] Level: %d\n", time_str, buffer[idx].level);
    }
    printf("--- End of Buffer Dump ---\n");
}

int main(void)
{
    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

