#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x50
#define MODE_REG       0x00
#define MODE_ACCEL     0x01
#define REG_X_LSB      0x02
#define REG_X_MSB      0x03
#define REG_Y_LSB      0x04
#define REG_Y_MSB      0x05
#define REG_Z_LSB      0x06
#define REG_Z_MSB      0x07
#define SAMPLE_PERIOD_US 500000
#define SENSOR_TIMEOUT_US 1000000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int d7s_init(int fd) {
    if (i2c_write_byte(fd, MODE_REG, MODE_ACCEL) < 0) {
        fprintf(stderr, "Failed to set D7S to acceleration mode\n");
        return -1;
    }
    usleep(10000);
    return 0;
}

static int d7s_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, REG_X_LSB, buf, 6) < 0)
        return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void get_timestamp(char *ts, size_t len) {
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(ts, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

static int write_header_if_new(FILE *fp) {
    long pos = ftell(fp);
    if (pos == 0) {
        fprintf(fp, "timestamp,x,y,z\n");
        fflush(fp);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", D7S_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (d7s_init(fd) < 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *csv = fopen("fan_health.csv", "a");
    if (!csv) {
        fprintf(stderr, "Cannot open fan_health.csv: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    write_header_if_new(csv);

    uint64_t start_wait = (uint64_t)clock();
    int sensor_active = 0;

    while (g_running) {
        if (!sensor_active) {
            if ((uint64_t)clock() - start_wait >= SENSOR_TIMEOUT_US) {
                fprintf(stderr, "D7S sensor did not respond within 1 s\n");
                break;
            }
            usleep(10000);
            continue;
        }

        int16_t x, y, z;
        if (d7s_read_xyz(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, retrying next cycle\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(csv, "%s,%d,%d,%d\n", ts, x, y, z);
        fflush(csv);
        usleep(SAMPLE_PERIOD_US);
    }

    fclose(csv);
    close(fd);
    return EXIT_SUCCESS;
}

