#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS         "/dev/i2c-1"
#define TMAG5170_ADDR   0x30

#define REG_DEVICE_CONFIG  0x00
#define REG_X_CH_CONFIG    0x01
#define REG_Y_CH_CONFIG    0x02
#define REG_Z_CH_CONFIG    0x03
#define REG_X_CH_DATA      0x04
#define REG_Y_CH_DATA      0x05
#define REG_Z_CH_DATA      0x06
#define REG_DEVICE_ID      0x07

#define DEVICE_ID_EXPECTED 0x51

#define DEVICE_CONFIG_CONTINUOUS 0x01
#define DEVICE_CONFIG_ACTIVE     0x02

#define X_CH_CONFIG_EN 0x01
#define Y_CH_CONFIG_EN 0x02
#define Z_CH_CONFIG_EN 0x04

#define LOG_FILE "magnetic_log.csv"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = val;
    return 0;
}

static int tmag5170_init(int fd) {
    uint8_t device_id;
    if (i2c_read_reg8(fd, REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "Failed to read device ID\n");
        return -1;
    }
    if (device_id != DEVICE_ID_EXPECTED) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n", device_id, DEVICE_ID_EXPECTED);
        return -1;
    }

    if (i2c_write_reg8(fd, REG_DEVICE_CONFIG, DEVICE_CONFIG_ACTIVE) != 0) return -1;
    if (i2c_write_reg8(fd, REG_X_CH_CONFIG, X_CH_CONFIG_EN) != 0) return -1;
    if (i2c_write_reg8(fd, REG_Y_CH_CONFIG, Y_CH_CONFIG_EN) != 0) return -1;
    if (i2c_write_reg8(fd, REG_Z_CH_CONFIG, Z_CH_CONFIG_EN) != 0) return -1;
    if (i2c_write_reg8(fd, REG_DEVICE_CONFIG, DEVICE_CONFIG_CONTINUOUS | DEVICE_CONFIG_ACTIVE) != 0) return -1;

    return 0;
}

static int tmag5170_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_lo, x_hi, y_lo, y_hi, z_lo, z_hi;

    if (i2c_read_reg8(fd, REG_X_CH_DATA, &x_lo) != 0) return -1;
    if (i2c_read_reg8(fd, REG_X_CH_DATA + 1, &x_hi) != 0) return -1;
    if (i2c_read_reg8(fd, REG_Y_CH_DATA, &y_lo) != 0) return -1;
    if (i2c_read_reg8(fd, REG_Y_CH_DATA + 1, &y_hi) != 0) return -1;
    if (i2c_read_reg8(fd, REG_Z_CH_DATA, &z_lo) != 0) return -1;
    if (i2c_read_reg8(fd, REG_Z_CH_DATA + 1, &z_hi) != 0) return -1;

    *x = (int16_t)((x_hi << 8) | x_lo);
    *y = (int16_t)((y_hi << 8) | y_lo);
    *z = (int16_t)((z_hi << 8) | z_lo);

    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5170_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TMAG5170_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (tmag5170_init(g_i2c_fd) != 0) {
        fprintf(stderr, "TMAG5170 initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "Timestamp,X,Y,Z\n");
        fflush(g_log_fp);
    }

    printf("TMAG5170 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x, y, z;
        if (tmag5170_read_xyz(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

