#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define SENSOR_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", tm_info);
}

static void log_message(const char *msg) {
    pthread_mutex_lock(&log_mutex);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(fp, "%s %s\n", ts, msg);
        fclose(fp);
    } else {
        perror("fopen log");
    }
    pthread_mutex_unlock(&log_mutex);
}

static int read_sensor(void) {
    int v = gpioRead(SENSOR_PIN);
    if (v < 0) {
        log_message("ERROR: gpioRead failed");
        return -1;
    }
    return v;
}

static void check_water_level(void) {
    int level = read_sensor();
    if (level < 0) {
        return;
    }
    if (level == 1) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        printf("%s ALERT: Water detected\n", ts);
        fflush(stdout);
        char msg[128];
        snprintf(msg, sizeof(msg), "ALERT: Water detected");
        log_message(msg);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
