#include <stdatomic.h>
#include <pigpio.h>

#define SENSOR_GPIO 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define WINDOW_SECONDS 1

static atomic_int pulse_count = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    atomic_fetch_add(&pulse_count, 1);
}

static void log_rpm(float rpm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s %.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
    }

    printf("%s %.2f\n", timestamp, rpm);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        int pulses = atomic_exchange(&pulse_count, 0);
        float rpm = (float)pulses * 60.0f / (float)WINDOW_SECONDS;

