#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"

/* Quadrature state machine states */
typedef enum {
    STATE_A_LOW = 0,
    STATE_A_HIGH = 1,
    STATE_B_LOW = 2,
    STATE_B_HIGH = 3
} QuadState;

/* Direction of rotation */
typedef enum {
    CLOCKWISE = 1,
    COUNTER_CLOCKWISE = -1
} RotationDirection;

/* Shared state between ISR and main thread */
typedef struct {
    QuadState state;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    volatile sig_atomic_t running;
} SharedState;

static SharedState shared;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    shared.running = 0;
    pthread_cond_signal(&shared.cond);
}

/* ISR callback for sensor A edges */
static void sensor_a_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level != PI_TIMEOUT) {
        QuadState prev, next;
        RotationDirection dir;

        pthread_mutex_lock(&shared.mutex);

        /* Determine previous state and next state */
        switch (shared.state) {
            case STATE_A_LOW:
                prev = STATE_A_LOW;
                next = (level == PI_HIGH) ? STATE_A_HIGH : STATE_A_LOW;
                break;
            case STATE_A_HIGH:
                prev = STATE_A_HIGH;
                next = (level == PI_HIGH) ? STATE_B_HIGH : STATE_A_LOW;
                break;
            case STATE_B_LOW:
                prev = STATE_B_LOW;
                next = (level == PI_HIGH) ? STATE_B_HIGH : STATE_B_LOW;
                break;
            case STATE_B_HIGH:
                prev = STATE_B_HIGH;
                next = (level == PI_HIGH) ? STATE_A_HIGH : STATE_B_LOW;
                break;
            default:
                pthread_mutex_unlock(&shared.mutex);
                return;
        }

        /* Determine rotation direction based on previous and next states */
        if (prev == STATE_A_LOW && next == STATE_A_HIGH) {
            dir = CLOCKWISE;
        } else if (prev == STATE_A_HIGH && next == STATE_B_HIGH) {
            dir = CLOCKWISE;
        } else if (prev == STATE_B_HIGH && next == STATE_B_LOW) {
            dir = COUNTER_CLOCKWISE;
        } else if (prev == STATE_B_LOW && next == STATE_A_LOW) {
            dir = COUNTER_CLOCKWISE;
        } else {
            pthread_mutex_unlock(&shared.mutex);
            return;
        }

        /* Update state */
        shared.state = next;

        /* Get current timestamp */
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            pthread_mutex_unlock(&shared.mutex);
            return;
        }

        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);

        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        long milliseconds = ts.tv_nsec / 1000000;

        /* Log the event */
        if (log_file != NULL) {
            fprintf(log_file, "%s.%03ld: Sensor A, Direction: %s\n",
                    timestamp, milliseconds,
                    (dir == CLOCKWISE) ? "CLOCKWISE" : "COUNTER_CLOCKWISE");
            fflush(log_file);
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
        }

        pthread_mutex_unlock(&shared.mutex);
    }
}

/* ISR callback for sensor B edges */
static void sensor_b_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level != PI_TIMEOUT) {
        QuadState prev, next;
        RotationDirection dir;

        pthread_mutex_lock(&shared.mutex);

        /* Determine previous state and next state */
        switch (shared.state) {
            case STATE_A_LOW:
                prev = STATE_A_LOW;
                next = (level == PI_HIGH) ? STATE_B_HIGH : STATE_A_LOW;
                break;
            case STATE_A_HIGH:
                prev = STATE_A_HIGH;
                next = (level == PI_HIGH) ? STATE_A_HIGH : STATE_B_LOW;
                break;
            case STATE_B_LOW:
                prev = STATE_B_LOW;
                next = (level == PI_HIGH) ? STATE_A_HIGH : STATE_B_LOW;
                break;
            case STATE_B_HIGH:
                prev = STATE_B_HIGH;
                next = (level == PI_HIGH) ? STATE_B_HIGH : STATE_A_LOW;
                break;
            default:
                pthread_mutex_unlock(&shared.mutex);
                return;
        }

        /* Determine rotation direction based on previous and next states */
        if (prev == STATE_A_LOW && next == STATE_B_HIGH) {
            dir = CLOCKWISE;
        } else if (prev == STATE_A_HIGH && next == STATE_A_HIGH) {
            dir = CLOCKWISE;
        } else if (prev == STATE_B_HIGH && next == STATE_B_LOW) {
            dir = COUNTER_CLOCKWISE;
        } else if (prev == STATE_B_LOW && next == STATE_A_LOW) {
            dir = COUNTER_CLOCKWISE;
        } else {
            pthread_mutex_unlock(&shared.mutex);
            return;
        }

        /* Update state */
        shared.state = next;

        /* Get current timestamp */
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            pthread_mutex_unlock(&shared.mutex);
            return;
        }

        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);

        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        long milliseconds = ts.tv_nsec / 1000000;

        /* Log the event */
        if (log_file != NULL) {
            fprintf(log_file, "%s.%03ld: Sensor B, Direction: %s\n",
                    timestamp, milliseconds,
                    (dir == CLOCKWISE) ? "CLOCKWISE" : "COUNTER_CLOCKWISE");
            fflush(log_file);
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
        }

        pthread_mutex_unlock(&shared.mutex);
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize shared state */
    shared.state = STATE_A_LOW;
    if (pthread_mutex_init(&shared.mutex, NULL) != 0) {
        perror("pthread_mutex_init");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (pthread_cond_init(&shared.cond, NULL) != 0) {
        perror("pthread_cond_init");
        pthread_mutex_destroy(&shared.mutex);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    shared.running = 1;

    /* Set GPIO modes */
    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A_GPIO);
        goto cleanup;
    }
    if (gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B_GPIO);
        goto cleanup;
    }

    /* Enable pull-up resistors */
    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A_GPIO);
        goto cleanup;
    }
    if (gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B_GPIO);
        goto cleanup;
    }

    /* Register ISRs with pigpio's edge-triggered alert system */
    if (gpioSetAlertFuncEx(SENSOR_A_GPIO, sensor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d\n", SENSOR_A_GPIO);
        goto cleanup;
    }
    if (gpioSetAlertFuncEx(SENSOR_B_GPIO, sensor_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d\n", SENSOR_B_GPIO);
        goto cleanup;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        goto cleanup;
    }

    printf("Monitoring rotation on GPIO %d and GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_A_GPIO, SENSOR_B_GPIO);

    /* Main loop */
    while (shared.running) {
        pthread_mutex_lock(&shared.mutex);
        pthread_cond_wait(&shared.cond, &shared.mutex);
        pthread_mutex_unlock(&shared.mutex);
    }

cleanup:
    printf("\nShutting down...\n");

    /* Disable ISRs */
    gpioSetAlertFuncEx(SENSOR_A_GPIO, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_B_GPIO, NULL, NULL);

    /* Close log file */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();

    /* Cleanup mutex and condition variable */
    pthread_mutex_destroy(&shared.mutex);
    pthread_cond_destroy(&shared.cond);

    return EXIT_SUCCESS;
}

