#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting touch-led program (GPIO23=touch, GPIO18=LED)");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", TOUCH_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        syslog(LOG_ERR, "Failed to request touch line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led_control", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "GPIO initialized: touch=BCM%d, LED=BCM%d", TOUCH_SENSOR_PIN, LED_PIN);

    int last_state = 0;
    int led_on = 0;

    while (program_running) {
        int val = gpiod_line_get_value(touch_line);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor: %s", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val != last_state) {
            if (val == 1) {
                syslog(LOG_INFO, "Touch detected (GPIO%d=1)", TOUCH_SENSOR_PIN);
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    syslog(LOG_ERR, "Failed to turn LED on: %s", strerror(errno));
                } else {
                    led_on = 1;
                    syslog(LOG_INFO, "LED turned ON");
                }
            } else {
                syslog(LOG_INFO, "Touch released (GPIO%d=0)", TOUCH_SENSOR_PIN);
                if (led_on) {
                    if (gpiod_line_set_value(led_line, 0) < 0) {
                        syslog(LOG_ERR, "Failed to turn LED off: %s", strerror(errno));
                    } else {
                        led_on = 0;
                        syslog(LOG_INFO, "LED turned OFF");
                    }
                }
            }
            last_state = val;
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    if (led_on) {
        gpiod_line_set_value(led_line, 0);
    }
    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

