#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define TOUCH_PIN  17
#define LED_PIN    18
#define DEBOUNCE_US 50000   /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    int led_state = 0;
    int ret;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure touch sensor line as input --- */
    ret = gpioSetMode(TOUCH_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %s\n", TOUCH_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED line as output and drive LOW --- */
    ret = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %s\n", LED_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioWrite(LED_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to initialise LED state on GPIO%d: %s\n", LED_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor application started. Touch the sensor to toggle the LED.\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop: wait for rising-edge events --- */
    while (running) {
        ret = gpioSetAlertFuncEx(TOUCH_PIN, NULL, NULL);   /* discard any pending callback */
        if (ret != 0) {
            fprintf(stderr, "Failed to discard alert callback: %s\n", strerror(errno));
            break;
        }

        ret = gpioSetAlertFuncEx(TOUCH_PIN, NULL, NULL);   /* re-register without callback */
        if (ret != 0) {
            fprintf(stderr, "Failed to re-register alert callback: %s\n", strerror(errno));
            break;
        }

        /*
         * gpioSetAlertFuncEx with NULL callback = wait for rising edge.
         * If no edge arrives within the 1 s timeout, the function returns 0.
         */
        ret = gpioSetAlertFuncEx(TOUCH_PIN, NULL, NULL);
        if (ret != 0) {
            fprintf(stderr, "gpioSetAlertFuncEx failed: %s\n", strerror(errno));
            break;
        }

        /* Debounce: 50 ms */
        gpioDelay(DEBOUNCE_US);

        /* Toggle LED */
        led_state = !led_state;
        ret = gpioWrite(LED_PIN, led_state);
        if (ret != 0) {
            fprintf(stderr, "Failed to write LED state on GPIO%d: %s\n", LED_PIN, strerror(errno));
            break;
        }
    }

    /* --- Clean shutdown --- */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nApplication terminated gracefully.\n");
    return EXIT_SUCCESS;
}

