#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

#define BUFFER_SIZE 100
#define DEBOUNCE_US 50000  /* 50 ms */
#define POLL_US 50000      /* 50 ms */

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int log_index = 0;
static int overflow_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

static void log_event(int sensor_pin, int state) {
    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].state = state;
    log_index = (log_index + 1) % BUFFER_SIZE;

    if (log_index == 0) {
        overflow_count++;
    }
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (log_index + i) % BUFFER_SIZE;
        printf("[%d] Sensor: %d, Timestamp: %ld, State: %d\n",
               idx, log_buffer[idx].sensor_pin,
               (long)log_buffer[idx].timestamp, log_buffer[idx].state);
    }
    printf("Overflow Count: %d\n", overflow_count);
    printf("--- End of Log Buffer ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED_1_PIN (GPIO%d).\n", LED_1_PIN);
        cleanup();
        return EXIT_FAILURE;
