#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_US 5000
#define LOG_FILE "shaft_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

int log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int calculate_rpm(int sensor1_state, int sensor2_state, double *rpm) {
    static int prev_sensor1_state = -1;
    static int prev_sensor2_state = -1;
    static uint32_t last_tick1 = 0;
    static uint32_t last_tick2 = 0;
    static double rpm1 = 0.0;
    static double rpm2 = 0.0;

    uint32_t current_tick = gpioTick();

    if (sensor1_state != prev_sensor1_state) {
        if (prev_sensor1_state != -1) {
            uint32_t diff = current_tick - last_tick1;
            if (diff > 0) {
                rpm1 = 60000000.0 / (double)diff;
            }
        }
        last_tick1 = current_tick;
        prev_sensor1_state = sensor1_state;
    }

    if (sensor2_state != prev_sensor2_state) {
        if (prev_sensor2_state != -1) {
            uint32_t diff = current_tick - last_tick2;
            if (diff > 0) {
                rpm2 = 60000000.0 / (double)diff;
            }
        }
        last_tick2 = current_tick;
        prev_sensor2_state = sensor2_state;
    }

    *rpm = (rpm1 + rpm2) / 2.0;
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Monitoring rotating shaft RPM. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error reading sensor states. Exiting.\n");
            break;
        }

        if (log_data(sensor1_state, sensor2_state) != 0) {
            fprintf(stderr, "Error logging data. Exiting.\n");
            break;
        }

        double rpm = 0.0;
        if (calculate_rpm(sensor1_state, sensor2_state, &rpm) != 0) {
            fprintf(stderr, "Error calculating RPM. Exiting.\n");
            break;
        }

        printf("RPM: %.2f\n", rpm);

        gpioDelay(DEBOUNCE_US);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

