            uint32_t diff = current_tick - last_tick1;
            if (diff > 0) {
                rpm1 = 60000000.0 / (double)diff;
            }
        }
        last_tick1 = current_tick;
        prev_sensor1_state = sensor1_state;
    }

    if (sensor2_state != prev_sensor2_state) {
        if (prev_sensor2_state != -1) {
            uint32_t diff = current_tick - last_tick2;
            if (diff > 0) {
                rpm2 = 60000000.0 / (double)diff;
            }
        }
        last_tick2 = current_tick;
        prev_sensor2_state = sensor2_state;
    }

    *rpm = (rpm1 + rpm2) / 2.0;
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Monitoring rotating shaft RPM. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error reading sensor states. Exiting.\n");
            break;
        }

        if (log_data(sensor1_state, sensor2_state) != 0) {
            fprintf(stderr, "Error logging data. Exiting.\n");
            break;
        }

        double rpm = 0.0;
        if (calculate_rpm(sensor1_state, sensor2_state, &rpm) != 0) {
            fprintf(stderr, "Error calculating RPM. Exiting.\n");
            break;
        }

        printf("RPM: %.2f\n", rpm);

        gpioDelay(DEBOUNCE_US);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

