    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        if (read_heart_rate(&hr) == 0 && read_spo2(&spo2) == 0) {
            log_data(hr, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

