#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN   27

#define TILT_THRESHOLD_SEC 2.0
#define POLL_INTERVAL_US   100000
#define LOG_FILE_NAME      "bridge_integrity.log"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_alarm(void) {
    if (gpioWrite(ALARM_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set alarm HIGH\n");
        return -1;
    }
    return 0;
}

static int deactivate_alarm(void) {
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set alarm LOW\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int sensor1_state, sensor2_state;
    double tilt_start_time = 0.0;
    int alarm_active = 0;
    int pigpio_initialized = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (deactivate_alarm() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Bridge integrity monitor started. Press Ctrl+C to exit.\n");

    while (program_running) {
        sensor1_state = gpioRead(SENSOR_1_PIN);
        sensor2_state = gpioRead(SENSOR_2_PIN);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor GPIOs\n");
            break;
        }

        if (sensor1_state == 1 && sensor2_state == 1) {
            if (!alarm_active) {
                if (activate_alarm() == 0) {
                    alarm_active = 1;
                    tilt_start_time = time_time();
                    if (log_event("Tilt-start") != 0) {
                        fprintf(stderr, "Failed to log tilt start event\n");
                    }
                } else {
                    fprintf(stderr, "Failed to activate alarm\n");
                }
            } else {
                if (time_time() - tilt_start_time > TILT_THRESHOLD_SEC) {
                    if (log_event("Threshold-exceeded") != 0) {
                        fprintf(stderr, "Failed to log threshold exceeded event\n");
                    }
                }
            }
        } else {
            if (alarm_active) {
                if (log_event("Tilt-end") != 0) {
                    fprintf(stderr, "Failed to log tilt end event\n");
                }
                if (deactivate_alarm() == 0) {
                    alarm_active = 0;
                } else {
                    fprintf(stderr, "Failed to deactivate alarm\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

