/*
 * seismic.c — Raspberry Pi 3 Model B+ seismic monitor
 *
 * Sensor : Omron D7S-A0011 (I2C address 0x50)
 * Bus    : I2C-1 (SDA=GPIO2, SCL=GPIO3)
 * Alert  : LED on GPIO17 (active-high)
 * Log    : seismic_events.log (ISO-8601 timestamps)
 *
 * Build  : gcc -O2 -Wall -o seismic seismic.c -lrt -lm
 * Run    : ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define D7S_ADDR         0x50
#define CTRL1_REG        0x01
#define CTRL2_REG        0x02
#define OUT_X_L_REG      0x08
#define OUT_X_H_REG      0x09
#define OUT_Y_L_REG      0x0A
#define OUT_Y_H_REG      0x0B
#define OUT_Z_L_REG      0x0C
#define OUT_Z_H_REG      0x0D
#define ALERT_LED_PIN    17
#define THRESHOLD        500
#define POLL_MS          100
#define MAX_RETRIES      3
#define LOG_FILE         "seismic_events.log"

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes ------------------------------- */
static int  i2c_write_reg(uint8_t reg, uint8_t val);
static int  i2c_read_reg(uint8_t reg, uint8_t *val);
static int  d7s_init(void);
static int  d7s_read_xyz(int16_t *x, int16_t *y, int16_t *z);
static int  d7s_is_present(void);
static int  magnitude(int16_t x, int16_t y, int16_t z);
static void log_event(int mag);
static void alert_led_on(void);
static void alert_led_off(void);
static void cleanup(void);
static void sigint_handler(int sig);

/* ----------------------------- I2C helpers ------------------------------ */

static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- D7S helpers ------------------------------ */

static int d7s_init(void)
{
    if (!d7s_is_present()) {
        fprintf(stderr, "D7S-A0011 not detected on 0x%02X\n", D7S_ADDR);
        return -1;
    }

    /* Clear power-down bit (CTRL1 bit 0) so sensor is operational. */
    uint8_t ctrl1 = 0;
    if (i2c_read_reg(CTRL1_REG, &ctrl1) < 0)
        return -1;
    if (i2c_write_reg(CTRL1_REG, ctrl1 & ~0x01) < 0)
        return -1;

    /* CTRL2: 0x00 = default, 0x01 = default, 0x02 = default. */
    if (i2c_write_reg(CTRL2_REG, 0x00) < 0)
        return -1;
    if (i2c_write_reg(CTRL2_REG, 0x01) < 0)
        return -1;
    if (i2c_write_reg(CTRL2_REG, 0x02) < 0)
        return -1;

    return 0;
}

static int d7s_is_present(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 0;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 0;
    }
    /* A read of CTRL1 will succeed if the sensor is present. */
    uint8_t ctrl1 = 0;
    if (i2c_read_reg(CTRL1_REG, &ctrl1) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 0;
    }
    close(g_i2c_fd);
    g_i2c_fd = -1;
    return 1;
}

static int d7s_read_xyz(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;
    int ok = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg(OUT_X_L_REG, &xl) < 0) goto retry;
        if (i2c_read_reg(OUT_X_H_REG, &xh) < 0) goto retry;
        if (i2c_read_reg(OUT_Y_L_REG, &yl) < 0) goto retry;
        if (i2c_read_reg(OUT_Y_H_REG, &yh) < 0) goto retry;
        if (i2c_read_reg(OUT_Z_L_REG, &zl) < 0) goto retry;
        if (i2c_read_reg(OUT_Z_H_REG, &zh) < 0) goto retry;

        *x = (int16_t)((xh << 8) | xl);
        *y = (int16_t)((yh << 8) | yl);
        *z = (int16_t)((zh << 8) | zl);
        ok = 1;
        break;

    retry:
        if (attempt < MAX_RETRIES - 1)
            usleep(10000); /* 10 ms back-off */
    }

    if (!ok) {
        fprintf(stderr, "D7S-A0011 read failed after %d attempts\n", MAX_RETRIES);
        return -1;
    }
    return 0;
}

static int magnitude(int16_t x, int16_t y, int16_t z)
{
    double dx = (double)x;
    double dy = (double)y;
    double dz = (double)z;
    return (int)lround(sqrt(dx * dx + dy * dy + dz * dz));
}

