#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN 18

#define POLL_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

static int set_led(int on) {
    int v = gpioWrite(LED_PIN, on ? 1 : 0);
    if (v < 0) {
        fprintf(stderr, "gpioWrite failed on LED pin %d: %s\n", LED_PIN, pigpio_error(v));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on LED pin %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups so the open-drain sensors have a defined
       idle state when the bus is disconnected. */
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(SENSOR4_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off. */
    if (set_led(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int any_detected = 0;
        int vals[4];

        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            vals[i] = read_sensor(pins[i]);
            if (vals[i] < 0) {
                /* Sensor read error: turn LED off and exit. */
                set_led(0);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (vals[i] == 0) {  /* active-low: 0 => object detected */
                any_detected = 1;
            }
        }

        if (set_led(any_detected) < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown: turn LED off and release pigpio. */
    set_led(0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

