/*
 * flame_monitor.c — Raspberry Pi 3 Model B+
 *
 * Monitors five Keyes KY-026 flame sensors on the GPIO bus using libgpiod.
 * Logs flame-detection events to /var/log/flame_events.log with syslog.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define LOG_FILE         "/var/log/flame_events.log"
#define LOG_IDENT        "flame_monitor"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const int          sensor_ids[NUM_SENSORS]   = {1, 2, 3, 4, 5};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

/*
 * Append a timestamped flame event to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_flame_event(int sensor_id, unsigned int pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        syslog(LOG_ERR, "time: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r");
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime");
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "fprintf: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        syslog(LOG_ERR, "fflush: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock unlock: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        syslog(LOG_ERR, "fclose: %s", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    openlog(LOG_IDENT, LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting flame sensor monitoring (libgpiod)");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    memset(lines, 0, sizeof(lines));

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            for (int j = 0; j < i; j++)
                gpiod_line_release(lines[j]);
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            for (int j = 0; j < NUM_SENSORS; j++) {
                if (lines[j])
                    gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    syslog(LOG_INFO, "Monitoring %d sensors (GPIO %u, %u, %u, %u, %u)",
           NUM_SENSORS, sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    int prev_state[NUM_SENSORS];
    int curr_state[NUM_SENSORS];
    int first_read[NUM_SENSORS];

    for (int i = 0; i < NUM_SENSORS; i++) {
        int v = gpiod_line_get_value(lines[i]);
        if (v < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                   sensor_pins[i], strerror(errno));
            for (int j = 0; j < NUM_SENSORS; j++)
                gpiod_line_release(lines[j]);
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
        prev_state[i] = v;
        curr_state[i] = v;
        first_read[i] = v;
    }

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            if (v != curr_state[i]) {
                prev_state[i] = curr_state[i];
                curr_state[i] = v;

                if (v == 0) {
                    /* Debounce: re-read after 50 ms. */
                    usleep(DEBOUNCE_MS * 1000);
                    int dv = gpiod_line_get_value(lines[i]);
                    if (dv < 0) {
                        syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                               sensor_pins[i], strerror(errno));
                        continue;
                    }
                    if (dv == 0) {
                        if (first_read[i] == 1) {
                            if (log_flame_event(sensor_ids[i],
                                                sensor_pins[i]) == 0) {
                                syslog(LOG_INFO,
                                       "Flame detected on sensor %d "
                                       "(GPIO %u)",
                                       sensor_ids[i], sensor_pins[i]);
                            } else {
                                syslog(LOG_ERR,
                                       "Failed to log flame event "
                                       "for sensor %d (GPIO %u)",
                                       sensor_ids[i], sensor_pins[i]);
                            }
                            first_read[i] = 0;
                        }
                    }
                }
            }
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down flame sensor monitoring");

    for (int i = 0; i < NUM_SENSORS; i++)
        gpiod_line_release(lines[i]);

    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

