/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 B+.
 *
 * Wiring:
 *   OUT0 -> BCM GPIO 5
 *   OUT1 -> BCM GPIO 6
 *   OUT2 -> BCM GPIO 13
 *   OUT3 -> BCM GPIO 19
 *   OUT4 -> BCM GPIO 26
 *   OUT5 -> BCM GPIO 12
 *   OUT6 -> BCM GPIO 16
 *   OUT7 -> BCM GPIO 20
 *   VCC  -> 3.3 V, GND -> GND
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000  /* 50 ms */

/* BCM GPIO numbers for the eight OUT pins */
static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    } else {
        printf("[timestamp-error] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line_bulk *prev_lines = NULL;
    struct gpiod_line_bulk *curr_lines = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve all eight lines into a bulk */
    gpiod_line_bulk_init(&lines);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, touch_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Failed to get line for BCM GPIO %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /* Request all eight lines as inputs */
    if (gpiod_line_request_bulk_input(&lines, "ttp226-reader") < 0) {
        fprintf(stderr, "Failed to request lines as inputs: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Allocate and read the initial state */
    prev_lines = malloc(sizeof(struct gpiod_line_bulk));
    if (prev_lines == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_bulk_init(prev_lines);
    gpiod_line_bulk_add(prev_lines, &lines);

    if (gpiod_line_get_value_bulk(prev_lines) < 0) {
        fprintf(stderr, "Failed to read initial state: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        curr_lines = malloc(sizeof(struct gpiod_line_bulk));
        if (curr_lines == NULL) {
            fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_init(curr_lines);
        gpiod_line_bulk_add(curr_lines, &lines);

        if (gpiod_line_get_value_bulk(curr_lines) < 0) {
            fprintf(stderr, "Failed to read sensor values: %s\n", strerror(errno));
            free(curr_lines);
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Compare current with previous and log only on state change */
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int prev_val = gpiod_line_bulk_get_value(prev_lines, i);
            int curr_val = gpiod_line_bulk_get_value(curr_lines, i);

            if (prev_val < 0 || curr_val < 0) {
                fprintf(stderr, "Error reading sensor %d (BCM %u): %s\n",
                        i, touch_pins[i], strerror(errno));
                continue;
            }

            if (prev_val != curr_val) {
                print_timestamp();
                printf("Sensor %d (BCM %u): %s\n",
                       i, touch_pins[i],
                       curr_val ? "TOUCH" : "RELEASE");
                fflush(stdout);
            }
        }

        /* Swap current state for next iteration */
        struct gpiod_line_bulk *tmp = prev_lines;
        prev_lines = curr_lines;
        curr_lines = tmp;

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (prev_lines != NULL) {
        gpiod_line_bulk_free(prev_lines);
        free(prev_lines);
    }
    if (curr_lines != NULL) {
        gpiod_line_bulk_free(curr_lines);
        free(curr_lines);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully.\n");
    return ret;
}

