#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define VEML7700_ALS_CONF_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define VEML7700_ALS_POWER_ON 0x0001
#define VEML7700_ALS_IT_50MS 0x0200
#define VEML7700_ALS_PERS_1 0x0000
#define VEML7700_ALS_INT_EN 0x0000
#define VEML7700_ALS_SD_1 0x0000
#define VEML7700_ALS_AF_1 0x0000

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define SAMPLE_INTERVAL_US 1000000

#define LUX_LOW 100
#define LUX_MED 500
#define LUX_HIGH 1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_init(int handle) {
    uint16_t conf = VEML7700_ALS_POWER_ON | VEML7700_ALS_IT_50MS |
                    VEML7700_ALS_PERS_1 | VEML7700_ALS_INT_EN |
                    VEML7700_ALS_SD_1 | VEML7700_ALS_AF_1;
    if (i2cWriteWordData(handle, VEML7700_ALS_CONF_REG, conf) < 0) {
        fprintf(stderr, "Error: Failed to write VEML7700 configuration.\n");
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux_out) {
    int raw = i2cReadWordData(handle, VEML7700_ALS_DATA_REG);
    if (raw < 0) {
        fprintf(stderr, "Error: Failed to read VEML7700 data register.\n");
        return -1;
    }
    uint16_t als = (uint16_t)raw;
    *lux_out = (float)als;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < LUX_LOW) return 100;
    if (lux < LUX_MED) return 75;
    if (lux < LUX_HIGH) return 50;
    return 25;
}

static int set_pwm_brightness(int brightness) {
    if (gpioPWM(PWM_GPIO, brightness) < 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle.\n");
        return -1;
    }
    return 0;
}

static void log_data(float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(PWM_GPIO, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VEML7700_ADDR);
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VEML7700 initialization failed (sensor absent or bus error).\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", PWM_GPIO);
        cleanup();
        return 1;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency to %d Hz.\n", PWM_FREQUENCY);
        cleanup();
        return 1;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range to %d.\n", PWM_RANGE);
        cleanup();
        return 1;
    }

    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Adaptive Grow Light System started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        int brightness = 0;
        int error_code = 0;

        if (veml7700_read_lux(i2c_handle, &lux) == 0) {
            brightness = map_lux_to_brightness(lux);
            if (set_pwm_brightness(brightness) == 0) {
                error_code = 0;
            } else {
                error_code = 3;
            }
        } else {
            error_code = 2;
        }

        log_data(lux, brightness, error_code);
        printf("Lux: %.2f, Brightness: %d%%, Error: %d\n", lux, brightness, error_code);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

