    for (int i = 0; i < NUM_CHANNELS; i++) {
        prev_state[i] = gpioRead(touch_pins[i]);
        if (prev_state[i] < 0) {
            fprintf(stderr, "gpioRead(touch_pins[%d]) failed\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpioRead(touch_pins[i]);
            if (val < 0) {
                fprintf(stderr, "gpioRead(touch_pins[%d]) failed\n", i);
                continue;
            }

            if (val == 1 && prev_state[i] == 0) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                }
                any_touched = 1;
            }
            prev_state[i] = val;
        }

        if (any_touched) {
            control_led(1);
        } else {
            control_led(0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    control_led(0);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

