#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_US 500000
#define ALERT_DURATION_US 1000000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    struct tm *tstruct = localtime(&now);
    if (tstruct == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return -1;
    }

    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "Error formatting time\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", buf, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_flame_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int set_alert_pin(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result < 0) {
        fprintf(stderr, "Error writing GPIO %d: %s\n", pin, pigpio_error(result));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", ALERT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing GPIO %d to LOW\n", ALERT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = read_flame_sensor(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            log_event("Error reading flame sensor");
        } else if (sensor_value == 0) {
            printf("Flame detected!\n");
            log_event("Flame detected");

            if (set_alert_pin(ALERT_PIN, 1) == 0) {
                gpioDelay(ALERT_DURATION_US);
                set_alert_pin(ALERT_PIN, 0);
            } else {
                log_event("Error activating alert pin");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

