#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS         "/dev/i2c-1"
#define SLF3S_ADDR      0x36
#define CMD_START_MEAS  0x362F
#define CMD_READ_MEAS   0x360D
#define CMD_STOP_MEAS   0x3FF9
#define CMD_RESET       0x3632
#define CMD_SOFT_RESET  0x3646
#define CMD_READ_ID     0x3600
#define CMD_READ_FIRM   0x3602
#define CMD_READ_CAL    0x3608
#define CMD_READ_STATUS 0x3644

#define FLOW_MIN_ML_MIN 0.0f
#define FLOW_MAX_ML_MIN 100.0f
#define SAMPLE_INTERVAL_S 1
#define LOG_FILE         "cooling_log.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (uint8_t)((crc << 1) ^ 0x31);
            else           crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n <= 0) return -1;
        total += (size_t)n;
    }
    return 0;
}

static int init_sensor(void) {
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd); g_i2c_fd = -1;
        return -1;
    }

    if (i2c_write_cmd(g_i2c_fd, CMD_SOFT_RESET) < 0) {
        fprintf(stderr, "Soft reset failed\n");
        close(g_i2c_fd); g_i2c_fd = -1;
        return -1;
    }
    usleep(10000);

    if (i2c_write_cmd(g_i2c_fd, CMD_START_MEAS) < 0) {
        fprintf(stderr, "Start measurement failed\n");
        close(g_i2c_fd); g_i2c_fd = -1;
        return -1;
    }
    usleep(2000);
    return 0;
}

static int read_flow_rate(float *flow_out) {
    uint8_t buf[3];

    if (i2c_write_cmd(g_i2c_fd, CMD_READ_MEAS) < 0) return -1;
    usleep(2000);

    if (i2c_read_bytes(g_i2c_fd, buf, 3) < 0) return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw;
    return 0;
}

static void log_data(float flow, const char *status) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp, "%s,%.2f,%s\n", ts, flow, status);
    fflush(g_log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_log_fp);
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor init failed\n");
        fclose(g_log_fp);
        return 1;
    }

    printf("Monitoring coolant flow... (Ctrl+C to stop)\n");

    while (g_running) {
        float flow;
        if (read_flow_rate(&flow) == 0) {
            if (flow >= FLOW_MIN_ML_MIN && flow <= FLOW_MAX_ML_MIN) {
                log_data(flow, "OK");
            } else {
                log_data(flow, "INVALID");
            }
        } else {
            fprintf(stderr, "Read error, re-initializing sensor...\n");
            log_data(0.0f, "ERROR");
            if (init_sensor() < 0) {
                fprintf(stderr, "Re-init failed, exiting\n");
                break;
            }
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_log_fp) fclose(g_log_fp);
    printf("\nExiting gracefully.\n");
    return 0;
}

