static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *middle_line = NULL;
    struct gpiod_line *right_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (left_line == NULL || middle_line == NULL || right_line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(left_line, "obstacle_avoidance") < 0) {
        perror("gpiod_line_request_input (left)");
        goto cleanup;
    }
    if (gpiod_line_request_input(middle_line, "obstacle_avoidance") < 0) {
        perror("gpiod_line_request_input (middle)");
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "obstacle_avoidance") < 0) {
        perror("gpiod_line_request_input (right)");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("fopen");
        goto cleanup;
    }

    if (fprintf(log_file, "timestamp,left,middle,right\n") < 0) {
        perror("fprintf header");
        goto cleanup;
    }
    if (fflush(log_file) == EOF) {
        perror("fflush header");
        goto cleanup;
    }

    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        char timestamp[32];
        if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Failed to generate timestamp\n");
            break;
        }

        if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_val, middle_val, right_val) < 0) {
            perror("fprintf data");
            break;
        }
        if (fflush(log_file) == EOF) {
            perror("fflush data");
            break;
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    if (left_line != NULL) {
        gpiod_line_release(left_line);
    }
    if (middle_line != NULL) {
        gpiod_line_release(middle_line);
    }
    if (right_line != NULL) {
        gpiod_line_release(right_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

