#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define EVENT_FILE "flame_events.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(EVENT_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", EVENT_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - %s\n",
                tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
                tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec, message);
    } else {
        fprintf(fp, "(unknown time) - %s\n", message);
    }

    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(FLAME_SENSOR_GPIO, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", FLAME_SENSOR_GPIO);

    while (running) {
        gpioDelay(100000);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

