#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24
#define GPIO_CHIP_NAME "/dev/gpiochip4"
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
        touch_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_event(int led_state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s LED: %d\n", timestamp, led_state) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    struct gpiod_line_event event;
    struct pollfd pfd;
    int led_state = 0;
    int ret;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting touch sensor line (GPIO%d): %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line (GPIO%d): %s\n", LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_rising_edge_events(touch_line, "touch_lamp");
    if (ret < 0) {
        fprintf(stderr, "Error requesting rising edge events on touch sensor: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "touch_lamp", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    pfd.fd = gpiod_line_event_get_fd(touch_line);
    if (pfd.fd < 0) {
        fprintf(stderr, "Error getting event fd: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    pfd.events = POLLIN;

    printf("Touch-activated lamp running. Press Ctrl+C to exit.\n");

    while (program_running) {
        ret = poll(&pfd, 1, POLL_TIMEOUT_MS);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "poll failed: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            continue;
        }

        if (pfd.revents & POLLIN) {
            ret = gpiod_line_event_read(touch_line, &event);
            if (ret < 0) {
                fprintf(stderr, "Error reading event: %s\n", strerror(errno));
                break;
            }

            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                led_state = !led_state;
                ret = gpiod_line_set_value(led_line, led_state);
                if (ret < 0) {
                    fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
                    break;
                }

                if (log_event(led_state) != 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

