/*
 * Flame detection safety system for Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 flame sensor (digital output, active-low)
 *   DO  -> GPIO17 (BCM, physical pin 11)
 *   VCC -> 3.3 V, GND -> GND
 * Buzzer: active buzzer on GPIO18 (BCM, physical pin 12)
 *
 * Behavior:
 *   - Polls the sensor every 500 ms (100 ms slices so SIGINT/SIGTERM
 *     are handled promptly).
 *   - On a HIGH-to-LOW transition (LOW = flame detected) logs a
 *     timestamped entry to alert_log.txt and drives the buzzer HIGH
 *     for 2 s.
 *   - On SIGINT/SIGTERM the buzzer is turned off, lines are released,
 *     the chip is closed, and the log file is closed.
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN       18
#define LOG_FILE         "alert_log.txt"
#define POLL_INTERVAL_US 100000   /* 100 ms */
#define BUZZER_DURATION_S 2

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(FILE *fp, const char *event)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Buzzer helpers                                                      */
/* ------------------------------------------------------------------ */
static int buzzer_on(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set buzzer HIGH: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int buzzer_off(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set buzzer LOW: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
