#define LED_PIN 17
#define DEBOUNCE_MS 200
#define POLL_INTERVAL_US 10000
#define TIMESTAMP_LEN 32

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d\n", LED_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open touch_log.txt: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: gmtime_r() failed\n");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    return 0;
}

static int log_touch_event(const char *timestamp) {
    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Warning: fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }
    if (init_log() != 0) {
        gpioTerminate();
        return 1;
    }

    int last_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error: initial gpioRead(%d) failed\n", TOUCH_SENSOR_PIN);
        cleanup();
        return 1;
    }

    uint32_t last_event_tick = 0;

    while (running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (current_state == 0 && last_state == 1) {
            uint32_t now = gpioTick();
            if (now == 0) {
                fprintf(stderr, "Error: gpioTick() returned 0\n");
                break;
            }
            if (now - last_event_tick >= (uint32_t)(DEBOUNCE_MS * 1000)) {
                char timestamp[TIMESTAMP_LEN];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    if (log_touch_event(timestamp) != 0) {
                        fprintf(stderr, "Error: failed to log touch event\n");
                    }
                }
                last_event_tick = now;
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

