/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern API, no wiringPi)
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4
 *   Sensor 2 OUT -> GPIO17
 *   Sensor 3 OUT -> GPIO27
 *
 * The TMAG5110A1 is an open-drain sensor.  Its output is driven LOW
 * when a south pole is present (magnet present) and HIGH when the
 * magnet is removed (magnet removed).  A pull-up resistor is used to
 * keep the line HIGH when the sensor output is open-circuit.
 *
 * Build:  gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define LOG_FILE     "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

/*
 * Append an ISO-8601 timestamped state change record to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_state(int sensor_id, int state)
{
    time_t now;
    struct tm tm_info;
    char ts[32];

    if (g_log_fp == NULL) {
        fprintf(stderr, "log_state: log file not open\n");
        return -1;
    }

    now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "log_state: time() failed\n");
        return -1;
    }

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "log_state: localtime_r() failed\n");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "log_state: strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s Sensor %d: %s\n", ts, sensor_id,
                state ? "Magnet Present" : "Magnet Removed") < 0) {
        fprintf(stderr, "log_state: fprintf() failed\n");
        return -1;
    }

