#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define LOG_FILE "heart_rate.csv"
#define SAMPLE_COUNT 5
#define MIN_BPM 30
#define MAX_BPM 220
#define EXPECTED_PART_ID 0x82
#define EXPECTED_HW_REV 0x01

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_HR_DATA 0x02
#define REG_CONFIG 0x03

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int read_sensor_data(uint8_t *hr_data) {
    if (i2c_read_reg(REG_HR_DATA, hr_data) != 0) {
        return -1;
    }
    return 0;
}

static int apply_moving_average(const uint8_t *samples, int count, uint8_t *filtered) {
    if (count <= 0) return -1;
    long sum = 0;
    for (int i = 0; i < count; i++) sum += samples[i];
    *filtered = (uint8_t)(sum / count);
    return 0;
}

static int validate_heart_rate(uint8_t bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM);
}

static int log_heart_rate(uint8_t bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%u\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush on log file failed\n");
        return -1;
    }
    return 0;
}

static int initialize_sensor(void) {
    uint8_t part_id, hw_rev;

    if (i2c_read_reg(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Failed to read PART_ID register\n");
        return -1;
    }
    if (i2c_read_reg(REG_HW_REV, &hw_rev) != 0) {
        fprintf(stderr, "Error: Failed to read HW_REV register\n");
        return -1;
    }

    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X (expected 0x%02X). Sensor absent or wrong device.\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Warning: HW_REV 0x%02X differs from expected 0x%02X.\n", hw_rev, EXPECTED_HW_REV);
    }

    if (i2c_write_reg(REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to write CONFIG register\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: fopen log file");
        cleanup();
        return 1;
    }

    uint8_t samples[SAMPLE_COUNT];
    int sample_index = 0;
    int consecutive_errors = 0;

    while (!terminate) {
        uint8_t raw_hr;
        if (read_sensor_data(&raw_hr) != 0) {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Error: Too many consecutive I2C read failures, aborting.\n");
                break;
            }
            sleep(1);
            continue;
        }
        consecutive_errors = 0;

        samples[sample_index] = raw_hr;
        sample_index = (sample_index + 1) % SAMPLE_COUNT;

        uint8_t filtered_hr;
        if (apply_moving_average(samples, SAMPLE_COUNT, &filtered_hr) != 0) {
            fprintf(stderr, "Error: apply_moving_average failed\n");
            sleep(1);
            continue;
        }

        if (validate_heart_rate(filtered_hr) != 0) {
            fprintf(stderr, "Warning: Heart rate %u out of range, skipping log.\n", filtered_hr);
            sleep(1);
            continue;
        }

        if (log_heart_rate(filtered_hr) != 0) {
            fprintf(stderr, "Error: log_heart_rate failed\n");
            break;
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

