/*
 * touch_counter.c — 8-channel capacitive TTP226 touch sensor counter
 *
 * Board:  Raspberry Pi Zero W
 * Library: libgpiod (modern GPIO character-device API)
 *
 * Wiring:
 *   TTP226 OUT1 -> BCM 5
 *   TTP226 OUT2 -> BCM 6
 *   TTP226 OUT3 -> BCM 7
 *   TTP226 OUT4 -> BCM 8
 *   TTP226 OUT5 -> BCM 9
 *   TTP226 OUT6 -> BCM 10
 *   TTP226 OUT7 -> BCM 11
 *   TTP226 OUT8 -> BCM 12
 *   Counter bit 0 -> BCM 17
 *   Counter bit 7 -> BCM 24
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define LOG_FILE     "touch_log.txt"
#define POLL_MS      10
#define STAB_MS      200

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int counter_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static void iso_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    gmtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm);
}

static int log_event(FILE *fp, int channel, int counter)
{
    char ts[32];
    iso_timestamp(ts, sizeof(ts));
    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter) < 0) {
        fprintf(stderr, "log_event: fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static int set_counter_bits(struct gpiod_line *lines[], int val)
{
    int vals[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++)
        vals[i] = (val >> i) & 1;
    if (gpiod_line_set_value_bulk(lines, vals, NUM_CHANNELS) < 0) {
        fprintf(stderr, "set_counter_bits: bulk write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_CHANNELS];
    struct gpiod_line *counter_lines[NUM_CHANNELS];
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "get_line(sensor BCM %u): %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], "ttp226-sensor") < 0) {
            fprintf(stderr, "request_input(sensor BCM %u): %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (!counter_lines[i]) {
            fprintf(stderr, "get_line(counter BCM %u): %s\n", counter_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(counter_lines[i], "ttp226-counter", 0) < 0) {
            fprintf(stderr, "request_output(counter BCM %u): %s\n", counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor counter running. Press Ctrl+C to exit.\n");

    usleep(STAB_MS * 1000);

    int counter = 0;
    int prev[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++)
        prev[i] = gpiod_line_get_value(sensor_lines[i]);

    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int cur = gpiod_line_get_value(sensor_lines[i]);
            if (cur < 0) {
                fprintf(stderr, "read sensor BCM %u: %s\n", sensor_pins[i], strerror(errno));
                continue;
            }
            if (cur == 1 && prev[i] == 0) {
                counter++;
                if (counter > 255)
                    counter = 0;
                if (set_counter_bits(counter_lines, counter) < 0)
                    fprintf(stderr, "set_counter_bits failed for channel %d\n", i + 1);
                if (log_event(log_fp, i + 1, counter) < 0)
                    fprintf(stderr, "log_event failed for channel %d\n", i + 1);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
            prev[i] = cur;
        }
        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (set_counter_bits(counter_lines, 0) < 0)
        fprintf(stderr, "set_counter_bits reset failed\n");
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i])
            gpiod_line_release(sensor_lines[i]);
        if (counter_lines[i])
            gpiod_line_release(counter_lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (log_fp)
        fclose(log_fp);
    return ret;
}

