    }
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

int main(void) {
    int prev_state1 = 1;
    int prev_state2 = 1;
    uint32_t last_event_time1 = 0;
    uint32_t last_event_time2 = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
