        int cur_state2 = gpioRead(SENSOR_2_GPIO);

        if (cur_state1 < 0) {
            fprintf(stderr, "Error reading GPIO%d: %s\n", SENSOR_1_GPIO, strerror(errno));
        } else if (cur_state1 == 0 && prev_state1 == 1) {
            uint32_t now = gpioTick();
            if (now - last_event_time1 > DEBOUNCE_MS * 1000) {
                log_event(1);
                last_event_time1 = now;
            }
        }
        prev_state1 = cur_state1;

        if (cur_state2 < 0) {
            fprintf(stderr, "Error reading GPIO%d: %s\n", SENSOR_2_GPIO, strerror(errno));
