    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, s1, s2, led) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    int s1, s2;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for sensor1 pin %d\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for sensor2 pin %d\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for LED pin %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* TCRT5000 modules are active-low: 0 = obstacle detected, 1 = clear */
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for sensor1 pin %d\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for sensor2 pin %d\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (running) {
        s1 = read_sensor(SENSOR1_PIN);
        s2 = read_sensor(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* TCRT5000 modules are active-low: 0 = obstacle detected */
        int led_state = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (control_led(led_state) < 0) {
            fprintf(stderr, "LED control error; continuing.\n");
        }

        if (log_data(s1, s2, led_state) < 0) {
            fprintf(stderr, "Logging error; continuing.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

