#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN      4
#define LED_PIN      17
#define SAMPLE_US    125          /* 8 kHz polling period */
#define LED_ON_US    100000       /* 100 ms LED on-time */
#define POLL_SAMPLES 100000       /* 100 ms window for peak detection */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read the microphone pin once.
 * Returns 0 or 1 on success, -1 on error.
 */
static int read_mic(void)
{
    int v = gpioRead(MIC_PIN);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                MIC_PIN, pigpio_error(v));
        return -1;
    }
    return v;
}

/*
 * Turn the LED on or off.
 * Returns 0 on success, -1 on error.
 */
static int led_set(int on)
{
    int rc = gpioWrite(LED_PIN, on ? 1 : 0);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d: %s\n",
                LED_PIN, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/*
 * Print a millisecond-precision timestamp to stdout.
 */
static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    printf("%ld.%03ld\n", (long)ts.tv_sec, ts.tv_nsec / 1000000L);
    fflush(stdout);
}

int main(void)
{
    /* --- Install SIGINT handler ------------------------------------------ */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ----------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins -------------------------------------------------- */
    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (led_set(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop ---------------------------------------------- */
    while (g_running) {
        int peak_count = 0;

        for (int i = 0; i < POLL_SAMPLES && g_running; i++) {
            int v = read_mic();
            if (v < 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (v == 1) {
                peak_count++;
            }
            gpioDelay(SAMPLE_US);
        }

        if (peak_count > 0) {
            print_timestamp();
            if (led_set(1) < 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
            gpioDelay(LED_ON_US);
            if (led_set(0) < 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
    }

    /* --- Clean shutdown --------------------------------------------------- */
    led_set(0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

