#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_IR_PIN   17
#define CENTER_IR_PIN 27
#define RIGHT_IR_PIN  22
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs with internal pull-up resistors */
    if (gpioSetMode(LEFT_IR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LEFT_IR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_IR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", CENTER_IR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_IR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_IR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LEFT_IR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", LEFT_IR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(CENTER_IR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", CENTER_IR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RIGHT_IR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", RIGHT_IR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SunFounder 3-Way Tracing Sensor Reader\n");
    printf("Left: GPIO%d | Center: GPIO%d | Right: GPIO%d\n",
           LEFT_IR_PIN, CENTER_IR_PIN, RIGHT_IR_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main polling loop */
    while (running) {
        int left   = gpioRead(LEFT_IR_PIN);
        int center = gpioRead(CENTER_IR_PIN);
        int right  = gpioRead(RIGHT_IR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: GPIO read failure (left=%d, center=%d, right=%d).\n",
                    left, center, right);
            break;
        }

        /* Active-low: 0 = reflectance detected, 1 = no reflection */
        printf("Left: %s | Center: %s | Right: %s\n",
               left   == 0 ? "DETECTED" : "CLEAR",
               center == 0 ? "DETECTED" : "CLEAR",
               right  == 0 ? "DETECTED" : "CLEAR");

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

