#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

/* Si1175 I2C address (7-bit) */
#define SI1175_ADDR 0x55

/* Si1175 register addresses */
#define SI1175_REG_PART_ID      0x00
#define SI1175_REG_REV_ID       0x01
#define SI1175_REG_SEQ_ID       0x02
#define SI1175_REG_INT_CFG      0x03
#define SI1175_REG_IRQ_ENABLE   0x04
#define SI1175_REG_IRQ_MODE1    0x05
#define SI1175_REG_IRQ_MODE2    0x06
#define SI1175_REG_HW_KEY       0x07
#define SI1175_REG_MEAS_RATE0   0x08
#define SI1175_REG_MEAS_RATE1   0x09
#define SI1175_REG_ALS_RATE     0x0A
#define SI1175_REG_ALS_IR_ADC_GAIN 0x0B
#define SI1175_REG_ALS_VIS_ADC_GAIN 0x0C
#define SI1175_REG_ALS_IR_ADC_MISC 0x0D
#define SI1175_REG_ALS_VIS_ADC_MISC 0x0E
#define SI1175_REG_ALS_IR_ADC_DATA0 0x0F
#define SI1175_REG_ALS_IR_ADC_DATA1 0x10
#define SI1175_REG_ALS_VIS_ADC_DATA0 0x11
#define SI1175_REG_ALS_VIS_ADC_DATA1 0x12
#define SI1175_REG_ALS_VIS_DATA0    0x13
#define SI1175_REG_ALS_VIS_DATA1    0x14
#define SI1175_REG_ALS_IR_DATA0     0x15
#define SI1175_REG_ALS_IR_DATA1     0x16
#define SI1175_REG_COMMAND        0x17

/* Si1175 command codes */
#define SI1175_CMD_RESET         0x01
#define SI1175_CMD_ALS_FORCE     0x06
#define SI1175_CMD_PS_FORCE      0x07
#define SI1175_CMD_ALS_PS_FORCE  0x08

/* Expected chip ID */
#define SI1175_PART_ID_EXPECTED  0x75

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a single byte to a Si1175 register */
static int si1175_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X (value 0x%02X): pigpio error %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* Read a single byte from a Si1175 register */
static int si1175_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: pigpio error %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Initialize the Si1175 sensor */
static int si1175_init(int handle) {
    uint8_t part_id;

    /* Verify sensor presence by reading PART_ID */
    if (si1175_read_reg(handle, SI1175_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Sensor not responding on I2C bus.\n");
        return -1;
    }

    if (part_id != SI1175_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X). Sensor absent or wrong device.\n",
                part_id, SI1175_PART_ID_EXPECTED);
        return -1;
    }

    printf("Si1175 detected (PART_ID = 0x%02X).\n", part_id);

    /* Reset the sensor */
    if (si1175_write_reg(handle, SI1175_REG_COMMAND, SI1175_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset Si1175.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms reset delay */

    /* Configure measurement rate (100 ms) */
    if (si1175_write_reg(handle, SI1175_REG_MEAS_RATE0, 0x00) != 0) return -1;
    if (si1175_write_reg(handle, SI1175_REG_MEAS_RATE1, 0x00) != 0) return -1;

    /* Configure ALS rate (100 ms) */
    if (si1175_write_reg(handle, SI1175_REG_ALS_RATE, 0x00) != 0) return -1;

    /* Configure ALS IR ADC gain */
    if (si1175_write_reg(handle, SI1175_REG_ALS_IR_ADC_GAIN, 0x00) != 0) return -1;

    /* Configure ALS VIS ADC gain */
    if (si1175_write_reg(handle, SI1175_REG_ALS_VIS_ADC_GAIN, 0x00) != 0) return -1;

    /* Configure ALS IR ADC misc */
    if (si1175_write_reg(handle, SI1175_REG_ALS_IR_ADC_MISC, 0x00) != 0) return -1;

    /* Configure ALS VIS ADC misc */
    if (si1175_write_reg(handle, SI1175_REG_ALS_VIS_ADC_MISC, 0x00) != 0) return -1;

    /* Clear any pending interrupts */
    if (si1175_write_reg(handle, SI1175_REG_IRQ_ENABLE, 0x00) != 0) return -1;

    return 0;
}

/* Read ambient light sensor data (visible channel) */
static int si1175_read_als_vis(int handle, uint16_t *raw_value) {
    uint8_t lsb, msb;

    /* Trigger a forced ALS measurement */
    if (si1175_write_reg(handle, SI1175_REG_COMMAND, SI1175_CMD_ALS_FORCE) != 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms measurement delay */

    /* Read LSB and MSB of visible ALS data */
    if (si1175_read_reg(handle, SI1175_REG_ALS_VIS_DATA0, &lsb) != 0) {
        return -1;
    }
    if (si1175_read_reg(handle, SI1175_REG_ALS_VIS_DATA1, &msb) != 0) {
        return -1;
    }

    *raw_value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1175 address */
    i2c_handle = i2cOpen(1, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: pigpio error %d\n",
                SI1175_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si1175 sensor */
    if (si1175_init(i2c_handle) != 0) {
        fprintf(stderr, "Si1175 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not set SIGINT handler: %s\n", strerror(errno));
    }

    printf("Reading Si1175 ALS (visible) data every 100 ms. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        uint16_t raw_value;

        if (si1175_read_als_vis(i2c_handle, &raw_value) == 0) {
            printf("Ambient Light Sensor (Visible): %u\n", raw_value);
        } else {
            fprintf(stderr, "Error reading ALS data.\n");
        }

        gpioDelay(100000); /* 100 ms delay between readings */
    }

    /* Clean up resources */
    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

