#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LEFT_PIN   2
#define MIDDLE_PIN 3
#define RIGHT_PIN  4
#define POLL_MS    100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *mid_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the three GPIO lines */
    left_line  = gpiod_chip_get_line(chip, LEFT_PIN);
    mid_line   = gpiod_chip_get_line(chip, MIDDLE_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (!left_line || !mid_line || !right_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request each line as input */
    if (gpiod_line_request_input(left_line, "tracking-sensor") < 0) {
        perror("gpiod_line_request_input (left)");
        goto cleanup;
    }
    if (gpiod_line_request_input(mid_line, "tracking-sensor") < 0) {
        perror("gpiod_line_request_input (middle)");
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "tracking-sensor") < 0) {
        perror("gpiod_line_request_input (right)");
        goto cleanup;
    }

    /* Main polling loop */
    while (running) {
        int left_val  = gpiod_line_get_value(left_line);
        int mid_val   = gpiod_line_get_value(mid_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || mid_val < 0 || right_val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        printf("L:%d M:%d R:%d\n", left_val, mid_val, right_val);
        fflush(stdout);

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    if (left_line)  gpiod_line_release(left_line);
    if (mid_line)   gpiod_line_release(mid_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip)       gpiod_chip_close(chip);

    return ret;
}

