/*
 * touch_poll.c — Polls an 8-channel TTP226 capacitive touch sensor on a
 * Raspberry Pi 3 Model B+ using the pigpio library.
 *
 * Wiring (BCM numbering):
 *   TP1 -> GPIO5  TP2 -> GPIO6  TP3 -> GPIO13
 *   TP4 -> GPIO19  TP5 -> GPIO26  TP6 -> GPIO12
 *   TP7 -> GPIO16  TP8 -> GPIO20
 *
 * Build:
 *   gcc -o touch_poll touch_poll.c -lrt -lpigpio -lrt
 * Run:
 *   sudo ./touch_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 200000  /* 200 ms */

static const int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }
}

static double monotonic_seconds(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0.0;
    }
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;
}

int main(void)
{
    int rc = EXIT_SUCCESS;
    int ret;

    install_signal_handlers();

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        ret = gpioSetMode(touch_pins[i], PI_INPUT);
        if (ret != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for GPIO%d (code %d).\n",
                    touch_pins[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (g_running) {
        double start_time = monotonic_seconds();
        int values[NUM_CHANNELS];
        bool read_error = false;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpioRead(touch_pins[i]);
            if (v < 0) {
                fprintf(stderr, "Error: gpioRead failed for GPIO%d (code %d).\n",
                        touch_pins[i], v);
                read_error = true;
                break;
            }
            values[i] = v;
        }

        if (read_error) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        double elapsed = monotonic_seconds() - start_time;

        printf("[%.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               elapsed,
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        /*
         * Sleep in 100 ms increments so SIGINT/SIGTERM is noticed promptly.
         */
        for (int i = 0; i < 20 && g_running; i++) {
            usleep(100000);
        }
    }

    gpioTerminate();
    return rc;
}

