#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define STEP_DELAY_US 10000  /* 10 ms per step */
#define TRANSITION_STEPS 50
#define TRANSITION_SECONDS 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_pwm_channel(int pin, int value)
{
    if (value < 0) value = 0;
    if (value > PWM_RANGE) value = PWM_RANGE;
    if (gpioPWM(pin, value) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on pin %d: %s", pin, pigpio_error(0));
        return -1;
    }
    return 0;
}

static int set_all_channels(int r, int g, int b)
{
    if (set_pwm_channel(RED_PIN, r) < 0)   return -1;
    if (set_pwm_channel(GREEN_PIN, g) < 0) return -1;
    if (set_pwm_channel(BLUE_PIN, b) < 0)  return -1;
    return 0;
}

static int off_all_channels(void)
{
    if (set_pwm_channel(RED_PIN, 0) < 0)   return -1;
    if (set_pwm_channel(GREEN_PIN, 0) < 0) return -1;
    if (set_pwm_channel(BLUE_PIN, 0) < 0)  return -1;
    return 0;
}

static int clamp_byte(int v)
{
    if (v < 0)   return 0;
    if (v > 255) return 255;
    return v;
}

static int lerp_byte(int a, int b, float t)
{
    return clamp_byte((int)(a + (b - a) * t));
}

static int random_hue(void)
{
    return rand() % 256;
}

static int smooth_transition(int start_r, int start_g, int start_b,
