        int r = lerp_byte(start_r, end_r, t);
        int g = lerp_byte(start_g, end_g, t);
        int b = lerp_byte(start_b, end_b, t);
        if (set_all_channels(r, g, b) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

