#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/pwm.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 1000000000ULL
#define PWM_DUTY_CYCLE_NS 0
#define NUM_LEDS 10
#define MAX_LUX 10000.0f
#define MIN_LUX 1.0f
#define LOG_SCALE_EXP 0.2f
#define PWM_PERIOD_US 1000
#define I2C_RETRY_DELAY_US 100000
#define I2C_RETRY_MAX 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *value) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *value = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES_MODE) < 0) {
        return -1;
    }
    usleep(180000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0) {
        return -1;
    }
    *lux = (float)raw / 1.2f;
    return 0;
}

static int pwm_init(void) {
    pwm_fd = open("/dev/pwmchip0", O_RDWR);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to open /dev/pwmchip0: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(pwm_fd, PWM_EXPORT, PWM_CHANNEL) < 0 && errno != EBUSY) {
        fprintf(stderr, "Failed to export PWM channel: %s\n", strerror(errno));
        close(pwm_fd);
        pwm_fd = -1;
        return -1;
    }
    return 0;
}

static void pwm_set_duty_cycle(int fd, uint32_t duty_ns) {
    struct pwm_config config;
    memset(&config, 0, sizeof(config));
    config.duty_cycle = duty_ns;
    config.period = PWM_PERIOD_NS;
    config.polarity = PWM_POLARITY_NORMAL;
    config.enable = 1;
    if (ioctl(fd, PWM_SET_CONFIG, &config) < 0) {
        fprintf(stderr, "Failed to set PWM config: %s\n", strerror(errno));
    }
}

static void pwm_disable(int fd) {
    struct pwm_config config;
    memset(&config, 0, sizeof(config));
    config.enable = 0;
    if (ioctl(fd, PWM_SET_CONFIG, &config) < 0) {
        fprintf(stderr, "Failed to disable PWM: %s\n", strerror(errno));
    }
}

static void map_lux_to_brightness(float lux, int *brightness) {
    float log_lux = log10f(lux + 1.0f);
    float scaled = (log_lux - log10f(MIN_LUX + 1.0f)) / (log10f(MAX_LUX + 1.0f) - log10f(MIN_LUX + 1.0f));
    if (scaled < 0.0f) scaled = 0.0f;
    if (scaled > 1.0f) scaled = 1.0f;
    float brightness_float = powf(scaled, LOG_SCALE_EXP) * (float)NUM_LEDS;
    *brightness = (int)brightness_float;
    if (*brightness > NUM_LEDS) *brightness = NUM_LEDS;
    if (*brightness < 0) *brightness = 0;
}

static void generate_ws2812b_data(int brightness, uint8_t *data) {
    int num_zeros = NUM_LEDS - brightness;
    int num_ones = brightness;
    int total_bits = num_zeros + num_ones;
    int total_bytes = (total_bits + 7) / 8;
    memset(data, 0, total_bytes);
    for (int i = 0; i < num_ones; i++) {
        int byte_idx = i / 8;
        int bit_idx = i % 8;
        data[byte_idx] |= (1 << (7 - bit_idx));
    }
}

static void send_ws2812b_data(int fd, const uint8_t *data, int data_len) {
    for (int i = 0; i < data_len; i++) {
        uint8_t byte = data[i];
        for (int j = 0; j < 8; j++) {
            uint32_t duty_ns = (byte & (1 << (7 - j))) ? 1000000000ULL : 500000000ULL;
            pwm_set_duty_cycle(fd, duty_ns);
            usleep(PWM_PERIOD_US);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    if (pwm_init() < 0) {
        fprintf(stderr, "Failed to initialize PWM.\n");
        close(i2c_fd);
        return 1;
    }

    uint8_t ws2812b_data[NUM_LEDS];
    float lux;
    int brightness;

    while (running) {
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Failed to read lux value, retrying...\n");
            usleep(I2C_RETRY_DELAY_US);
            continue;
        }

        map_lux_to_brightness(lux, &brightness);
        generate_ws2812b_data(brightness, ws2812b_data);
        send_ws2812b_data(pwm_fd, ws2812b_data, NUM_LEDS);

        usleep(100000);
    }

    pwm_disable(pwm_fd);
    if (pwm_fd >= 0) close(pwm_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

