#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_PWR_ON 0x01
#define BH1750_RESET 0x07
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_MS 120
#define NUM_LEDS 10
#define SPI_SPEED_HZ 1000000
#define SPI_BITS 8
#define SPI_DELAY_US 0

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_RESET) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES) < 0) return -1;
    usleep(10000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES) < 0) return -1;
    usleep(BH1750_CONV_TIME_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int spi_transfer(int fd, const uint8_t *tx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = 0,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void apa102_set_led(uint8_t *led_buf, int led_num, int brightness) {
    if (led_num < 0 || led_num >= NUM_LEDS) return;
    int idx = led_num * 4;
    led_buf[idx] = brightness;
    led_buf[idx + 1] = brightness;
    led_buf[idx + 2] = brightness;
    led_buf[idx + 3] = brightness;
}

static int apa102_send(int spi_fd, uint8_t *led_buf, int num_leds) {
    size_t total_len = 4 + (size_t)num_leds * 4 + 4;
    uint8_t *tx = malloc(total_len);
    if (!tx) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    memset(tx, 0x00, 4);
    memcpy(tx + 4, led_buf, (size_t)num_leds * 4);
    memset(tx + 4 + (size_t)num_leds * 4, 0xFF, 4);

    int ret = spi_transfer(spi_fd, tx, total_len);
    free(tx);
    return ret;
}

int main(void) {
    struct sigaction sa = { .sa_handler = sigint_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open /dev/spidev0.0: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t spi_mode = SPI_MODE_0;
