#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_LEDS 10
#define FADE_STEPS 50
#define LOOP_DELAY_US 100000
#define BH1750_CONV_TIME_US 180000

static volatile sig_atomic_t running = 1;
static int i2c_handles[2] = {-1, -1};
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(int handle) {
    if (i2cWriteByte(handle, 0x80) < 0) {
        fprintf(stderr, "BH1750 init failed (handle %d): %s\n", handle, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read(int handle, float *lux) {
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "BH1750 read failed (handle %d): %s\n", handle, strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int spi_write_leds(const uint8_t *data, int len) {
    if (spiWrite(spi_handle, (char *)data, len) < 0) {
        fprintf(stderr, "SPI write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void fade_leds(uint8_t r, uint8_t g, uint8_t b) {
    uint8_t led_data[NUM_LEDS * 4 + 4];
    uint8_t *frame = led_data + 4;
    for (int i = 0; i < NUM_LEDS; i++) {
        frame[i * 4] = r;
        frame[i * 4 + 1] = g;
        frame[i * 4 + 2] = b;
        frame[i * 4 + 3] = 0xFF;
    }
    for (int i = 0; i < FADE_STEPS; i++) {
        uint8_t step = (uint8_t)((float)i / FADE_STEPS * 31.0f);
        for (int j = 0; j < NUM_LEDS; j++) {
            frame[j * 4] = (uint8_t)((float)r * step / 31.0f);
            frame[j * 4 + 1] = (uint8_t)((float)g * step / 31.0f);
            frame[j * 4 + 2] = (uint8_t)((float)b * step / 31.0f);
        }
        if (spi_write_leds(led_data, sizeof(led_data)) < 0) return;
        gpioDelay(1000000 / FADE_STEPS);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        uint8_t off[NUM_LEDS * 4 + 4];
        memset(off, 0, sizeof(off));
        spi_write_leds(off, sizeof(off));
        spiClose(spi_handle);
        spi_handle = -1;
    }
    for (int i = 0; i < 2; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handles[0] = i2cOpen(I2C_BUS, BH1750_ADDR_1, 0);
    if (i2c_handles[0] < 0) {
        fprintf(stderr, "Failed to open BH1750 at 0x%02X: %s\n", BH1750_ADDR_1, strerror(errno));
    }
    i2c_handles[1] = i2cOpen(I2C_BUS, BH1750_ADDR_2, 0);
    if (i2c_handles[1] < 0) {
        fprintf(stderr, "Failed to open BH1750 at 0x%02X: %s\n", BH1750_ADDR_2, strerror(errno));
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    for (int i = 0; i < 2; i++) {
        if (i2c_handles[i] >= 0) {
            if (bh1750_init(i2c_handles[i]) < 0) {
                fprintf(stderr, "BH1750 init failed at handle %d\n", i);
                cleanup();
                return 1;
            }
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        float lux_sum = 0.0f;
        int valid_count = 0;

        for (int i = 0; i < 2; i++) {
            if (i2c_handles[i] < 0) continue;
            if (i2cWriteByte(i2c_handles[i], 0x80) < 0) {
                fprintf(stderr, "BH1750 write failed at handle %d: %s\n", i, strerror(errno));
                continue;
            }
            gpioDelay(BH1750_CONV_TIME_US);
            float lux;
            if (bh1750_read(i2c_handles[i], &lux) == 0) {
                lux_sum += lux;
                valid_count++;
            }
        }

        if (valid_count == 0) {
            fprintf(stderr, "No valid BH1750 sensors found. Turning off LEDs.\n");
            fade_leds(0, 0, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float avg_lux = lux_sum / valid_count;
        uint8_t r, g, b;
        if (avg_lux < 200.0f) {
            r = 255; g = 255; b = 255;
        } else if (avg_lux < 500.0f) {
            r = 255; g = 128; b = 0;
        } else {
            r = 255; g = 0; b = 0;
        }
        fade_leds(r, g, b);
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

