#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_DATA 0x04
#define LED_GPIO 18
#define NUM_LEDS 10
#define GAMMA 2.8f
#define MAX_LUX 10000.0f
#define MAX_BRIGHTNESS 255
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *chip = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int veml7700_init(int fd) {
    if (i2c_write_reg8(fd, VEML7700_ALS_CONF, 0x00) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

int veml7700_read_lux(int fd, float *lux) {
    uint16_t raw;
    if (i2c_read_reg16(fd, VEML7700_ALS_DATA, &raw) < 0) {
        return -1;
    }
    *lux = (float)raw;
    return 0;
}

float gamma_correct(float lux, float gamma) {
