#include <stdbool.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define FLAME_SENSOR_READ_INTERVAL_US 100000
#define FLAME_SENSOR_READ_COUNT 5
#define SELF_TEST_BLINK_COUNT 2
#define SELF_TEST_BLINK_DELAY_US 500000
#define ERROR_BUZZER_PATTERN_COUNT 3
#define ERROR_BUZZER_PATTERN_DELAY_US 200000
#define ERROR_BUZZER_PATTERN_ON_US 200000
#define ERROR_BUZZER_PATTERN_OFF_US 200000
#define ERROR_BUZZER_PATTERN_LONG_US 600000
#define ERROR_BUZZER_PATTERN_SHORT_US 200000
#define MAIN_LOOP_DELAY_US 50000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize buzzer state\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize LED state\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Failed to read flame sensor\n");
        return -1;
    }
    return value;
}

static int control_buzzer(int state) {
    if (gpioWrite(BUZZER_PIN, state) != 0) {
        fprintf(stderr, "Failed to write buzzer state\n");
        return -1;
    }
    return 0;
}

static int control_led(int state) {
    if (gpioWrite(LED_PIN, state) != 0) {
        fprintf(stderr, "Failed to write LED state\n");
        return -1;
    }
    return 0;
}

static void self_test(void) {
    log_event("Starting self-test...");

    for (int i = 0; i < SELF_TEST_BLINK_COUNT; i++) {
        if (control_led(1) != 0) break;
        gpioDelay(SELF_TEST_BLINK_DELAY_US);
        if (control_led(0) != 0) break;
        gpioDelay(SELF_TEST_BLINK_DELAY_US);
    }

    int flame_detected = 0;
    for (int i = 0; i < FLAME_SENSOR_READ_COUNT; i++) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            log_event("Self-test: Error reading flame sensor during self-test");
            control_led(1);
            gpioDelay(ERROR_BUZZER_PATTERN_COUNT * (ERROR_BUZZER_PATTERN_ON_US + ERROR_BUZZER_PATTERN_OFF_US));
            control_led(0);
            gpioDelay(MAIN_LOOP_DELAY_US);
            return;
        }
        if (sensor_value == 0) {
            flame_detected = 1;
        }
        gpioDelay(FLAME_SENSOR_READ_INTERVAL_US);
    }

    if (flame_detected) {
        log_event("Self-test: Flame detected on all five samples");
        control_led(1);
        gpioDelay(ERROR_BUZZER_PATTERN_COUNT * (ERROR_BUZZER_PATTERN_ON_US + ERROR_BUZZER_PATTERN_OFF_US));
        control_led(0);
        gpioDelay(MAIN_LOOP_DELAY_US);
    } else {
        log_event("Self-test: No flame detected");
    }
}

static void error_handler(void) {
    log_event("Error detected!");
    control_led(1);
    for (int i = 0; i < ERROR_BUZZER_PATTERN_COUNT; i++) {
        if (control_buzzer(1) != 0) break;
        gpioDelay(ERROR_BUZZER_PATTERN_ON_US);
        if (control_buzzer(0) != 0) break;
        gpioDelay(ERROR_BUZZER_PATTERN_OFF_US);
    }
    control_led(0);
    gpioDelay(MAIN_LOOP_DELAY_US);
}

static void cleanup_gpio(void) {
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (initialize_gpio() != 0) {
        return 1;
    }

    self_test();

    int previous_flame_state = -1;

    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            error_handler();
            continue;
        }

        if (sensor_value == 0) {
            if (previous_flame_state != 0) {
                log_event("Flame detected!");
                control_led(1);
                control_buzzer(1);
                gpioDelay(MAIN_LOOP_DELAY_US);
                control_buzzer(0);
                control_led(0);
                previous_flame_state = 0;
            }
        } else {
            if (previous_flame_state == 0) {
                log_event("Flame cleared!");
                control_led(1);
                control_buzzer(1);
                gpioDelay(MAIN_LOOP_DELAY_US);
                control_buzzer(0);
                control_led(0);
                previous_flame_state = 1;
            }
        }

        gpioDelay(MAIN_LOOP_DELAY_US);
    }

    log_event("Program terminating...");
    cleanup_gpio();
    return 0;
}

