#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_RESET) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CONT_H) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CONT_L) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t buf[2];
    if (i2c_write_byte(fd, BH1750_ONE_H) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_ONE_L) < 0) return -1;
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void led_pulse(struct gpiod_line *line, float lux) {
    float freq = 0.5f + (lux / 1000.0f) * 4.0f;
    if (freq < 0.5f) freq = 0.5f;
    if (freq > 5.0f) freq = 5.0f;
    float period_s = 1.0f / freq;
    struct timespec on_ts = {0, (long)(period_s * 500000000L)};
    struct timespec off_ts = {0, (long)(period_s * 500000000L)};
    struct timespec rem;
    while (g_running) {
        if (gpiod_line_set_value(line, 1) < 0) break;
        nanosleep(&on_ts, &rem);
        if (!g_running) break;
        if (gpiod_line_set_value(line, 0) < 0) break;
        nanosleep(&off_ts, &rem);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "bh1750-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    float lux_buf[BUFFER_SIZE];
    int buf_idx = 0;
    int buf_count = 0;

    while (g_running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed; skipping sample\n");
        } else {
            lux_buf[buf_idx] = lux;
            buf_idx = (buf_idx + 1) % BUFFER_SIZE;
            if (buf_count < BUFFER_SIZE) buf_count++;
            float sum = 0.0f;
            for (int i = 0; i < buf_count; i++) sum += lux_buf[i];
            float avg = sum / (float)buf_count;
            printf("Lux: %.2f  Avg: %.2f\n", lux, avg);
            led_pulse(led, avg);
        }
        sleep(SAMPLE_PERIOD);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

