#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

/*
 * 74HC595 Shift Register Bit-Bang for 7-Segment Display
 *
 * Wiring (Raspberry Pi 40-pin header, BCM numbering):
 *   GPIO17 -> DS (Data)
 *   GPIO18 -> SHCP (Shift Clock)
 *   GPIO27 -> STCP (Storage Clock)
 *
 * Segment mapping (common cathode, active-high):
 *   a -> Q0, b -> Q1, c -> Q2, d -> Q3, e -> Q4, f -> Q5, g -> Q6, dp -> Q7
 *
 * Pattern for digit '5':
 *   a=1, b=1, c=1, d=0, e=0, f=1, g=0, dp=0  -> 0b11100100
 */

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SHIFT_OUT_PATTERN 0b11100100  /* 5: a,b,c,e,f */

#define ON_DELAY_US  500000  /* 500 ms */
#define OFF_DELAY_US 500000  /* 500 ms */

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set DATA_PIN (GPIO%d) as output.\n", DATA_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set CLOCK_PIN (GPIO%d) as output.\n", CLOCK_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LATCH_PIN (GPIO%d) as output.\n", LATCH_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure all lines start LOW */
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    return 0;
}

static void shift_out_byte(unsigned char data) {
    /*
     * Shift out 8 bits MSB-first.
     * The 74HC595 latches on the rising edge of STCP, so we hold it LOW
     * while shifting, then raise STCP to latch the data.
     */
    gpioWrite(LATCH_PIN, 0);

    for (int i = 7; i >= 0; i--) {
        int bit = (data >> i) & 1;
        gpioWrite(DATA_PIN, bit);
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1);          /* 1 us clock high */
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1);          /* 1 us clock low */
    }

    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1);              /* 1 us latch high */
    gpioWrite(LATCH_PIN, 0);
}

static void display_digit(unsigned char pattern) {
    shift_out_byte(pattern);
}

static void cleanup_gpio(void) {
    /* Ensure all lines are LOW before terminating */
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("74HC595 Shift Register Demo (digit '5' blinking)\n");
    printf("Press Ctrl+C to exit.\n");

    while (1) {
        display_digit(SHIFT_OUT_PATTERN);
        gpioDelay(ON_DELAY_US);

        /* Turn off display (all segments off) */
        shift_out_byte(0x00);
        gpioDelay(OFF_DELAY_US);
    }

    /* Unreachable in normal operation, but kept for completeness */
    cleanup_gpio();
    return EXIT_SUCCESS;
}

