 * blink_button.c — Raspberry Pi GPIO blink with button stop on falling edge.
 *
 * Build:  gcc -O2 -Wall -Wextra -o blink_button blink_button.c -lgpiod
 * Run:    ./blink_button
 *
 * Hardware (Raspberry Pi 40-pin header, BCM numbering):
 *   LED    -> GPIO17 (physical pin 11)
 *   Button -> GPIO18 (physical pin 12) with pull-up (external 330 Ω to 3V3)
 *
 * Behavior:
 *   LED blinks 2 s on, 2 s off.  On a falling edge from the button the
 *   blink is stopped immediately, the LED is turned off, and the program
 *   exits cleanly.  SIGINT (Ctrl-C) also triggers graceful termination.
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define BLINK_PERIOD_SEC  2
#define BUTTON_CHIP_NAME  "gpiochip0"
#define LED_LINE_OFFSET   17
#define BUTTON_LINE_OFFSET 18

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static void sleep_sec(unsigned int sec)
{
    struct timespec ts = { .tv_sec = sec, .tv_nsec = 0 };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        if (g_stop)
            return;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(BUTTON_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* --- Get LED line --- */
    led_line = gpiod_chip_get_line(chip, LED_LINE_OFFSET);
    if (!led_line) {
        perror("gpiod_chip_get_line(LED)");
        goto cleanup;
    }

    /* --- Request LED line as output, initial value LOW --- */
    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    /* --- Get button line --- */
    button_line = gpiod_chip_get_line(chip, BUTTON_LINE_OFFSET);
    if (!button_line) {
        perror("gpiod_chip_get_line(BUTTON)");
        goto cleanup;
    }

    /* --- Request button line as input with pull-up and falling-edge events --- */
    if (gpiod_line_request_falling_edge_events(button_line, "blink_button") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }

    /* --- Ensure pull-up is enabled (external 330 Ω to 3V3) --- */
    if (gpiod_line_set_value(button_line, 1) < 0) {
        perror("gpiod_line_set_value(button pull-up)");
        goto cleanup;
    }

    printf("Blinking LED on GPIO%d (2 s period) with button on GPIO%d.\n",
           LED_LINE_OFFSET, BUTTON_LINE_OFFSET);
    printf("Press the button (falling edge) to stop the blink and exit.\n");
    fflush(stdout);

    /* --- Main blink loop --- */
    while (!g_stop) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("gpiod_line_set_value(LED on)");
            goto cleanup;
        }
        sleep_sec(BLINK_PERIOD_SEC);
        if (g_stop)
            break;

        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("gpiod_line_set_value(LED off)");
            goto cleanup;
        }
        sleep_sec(BLINK_PERIOD_SEC);
        if (g_stop)
            break;
    }

    /* --- Button event wait loop --- */
    while (!g_stop) {
        struct timespec ts = { .tv_sec = 1, .tv_nsec = 0 };
        int ev = gpiod_line_event_wait(button_line, &ts);
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            goto cleanup;
        }
        if (ev == 0)
            continue;  /* timeout, loop and check g_stop */

        /* Event detected — read it to clear the event queue */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(button_line, &event) < 0) {
            perror("gpiod_line_event_read");
            goto cleanup;
        }

        /* Button pressed (falling edge) — stop blink, turn LED off, exit */
        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("gpiod_line_set_value(LED off)");
            goto cleanup;
        }
        printf("Button pressed (falling edge). Blink stopped. Exiting.\n");
        fflush(stdout);
        ret = EXIT_SUCCESS;
        goto cleanup;
    }

    /* --- Graceful shutdown via SIGINT --- */
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("gpiod_line_set_value(LED off)");
        goto cleanup;
    }
    printf("Interrupted by signal. Exiting.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (led_line)
        gpiod_line_release(led_line);
    if (button_line)
        gpiod_line_release(button_line);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

