#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_FREQ_HZ 100
#define PWM_PERIOD_NS (1000000000L / PWM_FREQ_HZ)
#define STEP_DELAY_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int pwm_write(struct gpiod_line *line, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    long on_ns  = (PWM_PERIOD_NS * duty_percent) / 100;
    long off_ns = PWM_PERIOD_NS - on_ns;

    if (on_ns > 0) {
        if (gpiod_line_set_value(line, 1) < 0) return -1;
        struct timespec ts_on = {0, on_ns};
        while (nanosleep(&ts_on, &ts_on) == -1) {
            if (!program_running) return -1;
        }
    }
    if (off_ns > 0) {
        if (gpiod_line_set_value(line, 0) < 0) return -1;
        struct timespec ts_off = {0, off_ns};
        while (nanosleep(&ts_off, &ts_off) == -1) {
            if (!program_running) return -1;
        }
    }
    return 0;
}

static int set_random_color(struct gpiod_line *red, struct gpiod_line *green, struct gpiod_line *blue) {
    int r = rand() % 101;
    int g = rand() % 101;
    int b = rand() % 101;

    if (pwm_write(red, r) < 0) return -1;
    if (pwm_write(green, g) < 0) return -1;
    if (pwm_write(blue, b) < 0) return -1;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0) {
        perror("gpiod_line_request_output red");
        goto cleanup;
    }
    if (gpiod_line_request_output(green_line, "rgb_led", 0) < 0) {
        perror("gpiod_line_request_output green");
        goto cleanup;
    }
    if (gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        perror("gpiod_line_request_output blue");
        goto cleanup;
    }

    while (program_running) {
        if (set_random_color(red_line, green_line, blue_line) < 0) {
            perror("pwm_write");
            break;
        }
        usleep(STEP_DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

