/* LSM303DLHC accelerometer I2C address (SA0 tied to GND) */
#define LSM303_ACCEL_ADDR 0x19

/* LSM303DLHC accelerometer registers */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_CTRL_REG4_A 0x23
#define LSM303_ACCEL_OUT_X_L_A   0x28

/* Impact interrupt GPIO pin (BCM numbering) */
#define IMPACT_GPIO 17

/* Default impact threshold in G-force */
#define DEFAULT_THRESHOLD 2.0f

/* Impact pulse duration in microseconds */
#define IMPACT_PULSE_US 50000

/* Polling interval in microseconds (10 Hz) */
#define POLL_INTERVAL_US 100000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;
static float impact_threshold = DEFAULT_THRESHOLD;

/* Accelerometer data structure */
typedef struct {
    int16_t x, y, z;
} accel_data_t;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Accelerometer initialization                                        */
/* ------------------------------------------------------------------ */
static int init_accelerometer(void)
{
    /*
     * CTRL_REG1_A (0x20):
     *   AODR=0100 (10 Hz), LPen=0, Zen=1, Yen=1, Xen=1 -> 0x57
     * CTRL_REG4_A (0x23):
     *   FS=00 (+/-2g), HR=0, ST=0, SIM=0 -> 0x00
     */
    if (i2c_write_byte(i2c_handle, LSM303_ACCEL_CTRL_REG1_A, 0x57) < 0)
        return -1;
    if (i2c_write_byte(i2c_handle, LSM303_ACCEL_CTRL_REG4_A, 0x00) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer data                                             */
/* ------------------------------------------------------------------ */
static int read_accelerometer(accel_data_t *data)
{
    uint8_t buf[6];

    if (i2c_read_block(i2c_handle, LSM303_ACCEL_OUT_X_L_A, buf, 6) != 6)
        return -1;

    /* LSM303DLHC is little-endian: low byte first */
    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute G-force magnitude                                            */
/* ------------------------------------------------------------------ */
static float calculate_magnitude(const accel_data_t *data)
{
    float x = (float)data->x;
    float y = (float)data->y;
    float z = (float)data->z;
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Impact interrupt                                                    */
/* ------------------------------------------------------------------ */
static void trigger_impact(void)
{
    gpioWrite(IMPACT_GPIO, 1);
    gpioDelay(IMPACT_PULSE_US);
    gpioWrite(IMPACT_GPIO, 0);
}

/* ------------------------------------------------------------------ */
/* Log impact event                                                    */
/* ------------------------------------------------------------------ */
static void log_impact(const accel_data_t *data)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        perror("fopen impact_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X=%d, Y=%d, Z=%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                data->x, data->y, data->z);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(IMPACT_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
        case 't':
            impact_threshold = (float)atof(optarg);
            if (impact_threshold <= 0.0f) {
                fprintf(stderr, "Threshold must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at LSM303 address */
    i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device (rc=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize accelerometer */
    if (init_accelerometer() < 0) {
        fprintf(stderr, "Accelerometer initialization failed (sensor may be absent)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure impact GPIO as output, initially low */
    gpioSetMode(IMPACT_GPIO, PI_OUTPUT);
    gpioWrite(IMPACT_GPIO, 0);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring accelerometer (threshold %.2f G)...\n", impact_threshold);

    while (program_running) {
        accel_data_t data;

        if (read_accelerometer(&data) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float magnitude = calculate_magnitude(&data);

        if (magnitude > impact_threshold) {
            printf("Impact detected! Magnitude: %.2f G\n", magnitude);
            trigger_impact();
            log_impact(&data);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

