#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define LED_GPIO 18
#define ADPD188BI_ADDR 0x30
#define ADPD188BI_REG_ALS_LSB 0x00
#define ADPD188BI_REG_ALS_MSB 0x01
#define ADPD188BI_REG_RED_LSB 0x02
#define ADPD188BI_REG_RED_MSB 0x03
#define ADPD188BI_REG_GREEN_LSB 0x04
#define ADPD188BI_REG_GREEN_MSB 0x05
#define ADPD188BI_REG_BLUE_LSB 0x06
#define ADPD188BI_REG_BLUE_MSB 0x07
#define ADPD188BI_REG_CONFIG 0x08
#define ADPD188BI_REG_STATUS 0x09
#define ADPD188BI_REG_ID 0x0A
#define ADPD188BI_REG_RESET 0x0B
#define ADPD188BI_REG_PS_LSB 0x0C
#define ADPD188BI_REG_PS_MSB 0x0D
#define ADPD188BI_REG_PS_CONFIG 0x0E
#define ADPD188BI_REG_PS_STATUS 0x0F
#define ADPD188BI_REG_PS_DATA_LSB 0x10
#define ADPD188BI_REG_PS_DATA_MSB 0x11
#define ADPD188BI_REG_PS_DATA_LSB_2 0x12
#define ADPD188BI_REG_PS_DATA_MSB_2 0x13
#define ADPD188BI_REG_PS_DATA_LSB_3 0x14
#define ADPD188BI_REG_PS_DATA_MSB_3 0x15
#define ADPD188BI_REG_PS_DATA_LSB_4 0x16
#define ADPD188BI_REG_PS_DATA_MSB_4 0x17
#define ADPD188BI_REG_PS_DATA_LSB_5 0x18
#define ADPD188BI_REG_PS_DATA_MSB_5 0x19
#define ADPD188BI_REG_PS_DATA_LSB_6 0x1A
#define ADPD188BI_REG_PS_DATA_MSB_6 0x1B
#define ADPD188BI_REG_PS_DATA_LSB_7 0x1C
#define ADPD188BI_REG_PS_DATA_MSB_7 0x1D
#define ADPD188BI_REG_PS_DATA_LSB_8 0x1E
#define ADPD188BI_REG_PS_DATA_MSB_8 0x1F

#define ADPD188BI_ID_VALUE 0x18
#define ADPD188BI_RESET_VALUE 0x00
#define ADPD188BI_CONFIG_DEFAULT 0x00
#define ADPD188BI_STATUS_DEFAULT 0x00
#define ADPD188BI_PS_CONFIG_DEFAULT 0x00
#define ADPD188BI_PS_STATUS_DEFAULT 0x00

#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t lsb_reg, uint8_t msb_reg, uint16_t *value) {
    uint8_t lsb, msb;
    if (read_register(lsb_reg, &lsb) < 0) return -1;
    if (read_register(msb_reg, &msb) < 0) return -1;
    *value = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int initialize_adpd188bi(void) {
    uint8_t id;
    if (read_register(ADPD188BI_REG_ID, &id) < 0) return -1;
    if (id != ADPD188BI_ID_VALUE) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X (expected 0x%02X)\n", id, ADPD188BI_ID_VALUE);
        return -1;
    }
    if (write_register(ADPD188BI_REG_RESET, ADPD188BI_RESET_VALUE) < 0) return -1;
    gpioDelay(10000);
    if (write_register(ADPD188BI_REG_CONFIG, ADPD188BI_CONFIG_DEFAULT) < 0) return -1;
    if (write_register(ADPD188BI_REG_STATUS, ADPD188BI_STATUS_DEFAULT) < 0) return -1;
    if (write_register(ADPD188BI_REG_PS_CONFIG, ADPD188BI_PS_CONFIG_DEFAULT) < 0) return -1;
    if (write_register(ADPD188BI_REG_PS_STATUS, ADPD188BI_PS_STATUS_DEFAULT) < 0) return -1;
    return 0;
}

static int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_word(ADPD188BI_REG_ALS_LSB, ADPD188BI_REG_ALS_MSB, als) < 0) return -1;
    if (read_word(ADPD188BI_REG_RED_LSB, ADPD188BI_REG_RED_MSB, red) < 0) return -1;
    if (read_word(ADPD188BI_REG_GREEN_LSB, ADPD188BI_REG_GREEN_MSB, green) < 0) return -1;
    if (read_word(ADPD188BI_REG_BLUE_LSB, ADPD188BI_REG_BLUE_MSB, blue) < 0) return -1;
    return 0;
}

static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file);
}

static void control_led(uint16_t als) {
    int duty = (int)((float)als / 65535.0f * 255.0f);
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;
    gpioPWM(LED_GPIO, duty);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioPWM(LED_GPIO, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (initialize_adpd188bi() < 0) {
        fprintf(stderr, "ADPD188BI initialization failed\n");
        cleanup();
        return 1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, 1000);
    gpioPWM(LED_GPIO, 0);
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    uint16_t als, red, green, blue;
    while (!terminate) {
        if (read_sensor_data(&als, &red, &green, &blue) == 0) {
            log_data(als, red, green, blue);
            control_led(als);
        } else {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

