#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x1D

/* FXOS8700CQ register addresses */
#define FXOS8700_REG_STATUS       0x00
#define FXOS8700_REG_OUT_X_MSB    0x01
#define FXOS8700_REG_WHO_AM_I     0x0D
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E
#define FXOS8700_REG_CTRL_REG1    0x2A
#define FXOS8700_REG_M_CTRL_REG1  0x5B

/* Expected WHO_AM_I value for FXOS8700CQ */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* Impact threshold in g */
#define IMPACT_THRESHOLD 0.5f

/* Sampling interval in microseconds (50 ms) */
#define SAMPLE_INTERVAL_US 50000

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Write a single byte to a register; returns 0 on success, -1 on error */
static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X (rc=%d)\n", value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read a single byte from a register; returns 0 on success, -1 on error */
static int read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Read 6 bytes starting at OUT_X_MSB and store as little-endian int16_t pairs */
static int read_xyz(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, FXOS8700_REG_OUT_X_MSB, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading 6-byte XYZ block (rc=%d)\n", rc);
        return -1;
    }
    *x = (int16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    *y = (int16_t)((uint8_t)buf[2] | ((uint8_t)buf[3] << 8));
    *z = (int16_t)((uint8_t)buf[4] | ((uint8_t)buf[5] << 8));
    return 0;
}

/* Append a timestamped impact line to impact_log.txt */
static int log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        perror("Error opening impact_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z, magnitude);

    if (fclose(fp) != 0) {
        perror("Error closing impact_log.txt");
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at FXOS8700_ADDR */
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X (rc=%d)\n", FXOS8700_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Verify device identity */
    uint8_t who_am_i = 0;
    if (read_reg(i2c_handle, FXOS8700_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("FXOS8700CQ detected (WHO_AM_I=0x%02X)\n", who_am_i);

    /* Put device in standby before configuration */
    if (write_reg(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Failed to put device in standby\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Configure accelerometer: ±2 g range, high-resolution mode */
    if (write_reg(i2c_handle, FXOS8700_REG_XYZ_DATA_CFG, 0x00) != 0) {
        fprintf(stderr, "Failed to configure accelerometer range\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Configure magnetometer: ±4 gauss range */
    if (write_reg(i2c_handle, FXOS8700_REG_M_CTRL_REG1, 0x1F) != 0) {
        fprintf(stderr, "Failed to configure magnetometer range\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Activate sensor: 200 Hz ODR, active mode */
    if (write_reg(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x15) != 0) {
        fprintf(stderr, "Failed to activate sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Allow sensor to settle after activation */
    gpioDelay(50000); /* 50 ms */

    /* Install signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    printf("Monitoring for impacts (threshold %.1f g)... (Ctrl+C to exit)\n", IMPACT_THRESHOLD);

    while (1) {
        int16_t x, y, z;

        if (read_xyz(i2c_handle, &x, &y, &z) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float magnitude = sqrtf((float)x * x + (float)y * y + (float)z * z);

        if (magnitude > IMPACT_THRESHOLD) {
            if (log_impact(x, y, z, magnitude) != 0) {
                fprintf(stderr, "Warning: failed to log impact\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Unreachable, but kept for completeness */
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

