#define SAMPLE_PERIOD_US 100000
#define SCALE_FACTOR 0.0039f

#define REG_DEVID 0x00
#define REG_POWER_CTL 0x2D
#define REG_DATA_FORMAT 0x31
#define REG_DATAX0 0x32

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X\n", reg, val);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int r = i2cReadByteData(i2c_handle, reg);
    if (r < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X\n", reg);
        return -1;
    }
    *val = (uint8_t)r;
    return 0;
}

static int read_accel(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2cReadI2CBlockData(i2c_handle, REG_DATAX0, (char *)buf, 6) != 6) {
        fprintf(stderr, "I2C block read failed\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * SCALE_FACTOR;
    *y = (float)raw_y * SCALE_FACTOR;
    *z = (float)raw_z * SCALE_FACTOR;
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[20];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(log_file);
}

