#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_CTRL_REG4_A 0x23
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03

/* ---- Scaling factors ---- */
#define ACCEL_SCALE 0.000244f   /* g/LSB  (12-bit, +/-2 g) */
#define MAG_SCALE   0.00014f    /* gauss/LSB (12-bit, +/-1.3 gauss) */

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US 100000 /* 100 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_accel = -1;
static int g_i2c_mag   = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair from the LSM303DLHC        */
/* ------------------------------------------------------------------ */
static int read_reg16(int handle, uint8_t reg, int16_t *out)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)(uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (g) and magnetic field (gauss)                    */
/* ------------------------------------------------------------------ */
static int read_sensors(float *ax, float *ay, float *az,
                        float *mx, float *my, float *mz)
{
    int16_t raw_ax, raw_ay, raw_az;
    int16_t raw_mx, raw_my, raw_mz;

    if (read_reg16(g_i2c_accel, LSM303_ACCEL_OUT_X_L_A, &raw_ax) != 0) {
        fprintf(stderr, "Error: failed to read accel X\n");
        return -1;
    }
    if (read_reg16(g_i2c_accel, LSM303_ACCEL_OUT_X_L_A + 2, &raw_ay) != 0) {
        fprintf(stderr, "Error: failed to read accel Y\n");
        return -1;
    }
    if (read_reg16(g_i2c_accel, LSM303_ACCEL_OUT_X_L_A + 4, &raw_az) != 0) {
        fprintf(stderr, "Error: failed to read accel Z\n");
        return -1;
    }
    if (read_reg16(g_i2c_mag, LSM303_MAG_OUT_X_H_M, &raw_mx) != 0) {
        fprintf(stderr, "Error: failed to read mag X\n");
        return -1;
    }
    if (read_reg16(g_i2c_mag, LSM303_MAG_OUT_X_H_M + 2, &raw_my) != 0) {
        fprintf(stderr, "Error: failed to read mag Y\n");
        return -1;
    }
    if (read_reg16(g_i2c_mag, LSM303_MAG_OUT_X_H_M + 4, &raw_mz) != 0) {
        fprintf(stderr, "Error: failed to read mag Z\n");
        return -1;
    }

