/* ------------------------------------------------------------------ */
/* Compute tilt-compensated heading (degrees)                          */
/* ------------------------------------------------------------------ */
static float calculate_heading(float ax, float ay, float az)
{
    float heading = atan2f(ay, ax) * 180.0f / (float)M_PI;
    if (heading < 0.0f) {
        heading += 360.0f;
    }
    return heading;
}

/* ------------------------------------------------------------------ */
/* Append a CSV row to the log file                                    */
/* ------------------------------------------------------------------ */
static int log_data(float heading, float ax, float ay, float az,
                    float mx, float my, float mz)
{
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            heading, ax, ay, az, mx, my, mz);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — close I2C handles and terminate pigpio                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_accel >= 0) {
        i2cClose(g_i2c_accel);
        g_i2c_accel = -1;
    }
    if (g_i2c_mag >= 0) {
        i2cClose(g_i2c_mag);
        g_i2c_mag = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C handles ---- */
    g_i2c_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (g_i2c_accel < 0) {
        fprintf(stderr, "Error: cannot open I2C for accel (addr 0x%02X): %d\n",
                LSM303_ACCEL_ADDR, g_i2c_accel);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (g_i2c_mag < 0) {
        fprintf(stderr, "Error: cannot open I2C for mag (addr 0x%02X): %d\n",
                LSM303_MAG_ADDR, g_i2c_mag);
        i2cClose(g_i2c_accel);
        g_i2c_accel = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

