    if (i2cWriteByteData(g_i2c_accel, LSM303_ACCEL_CTRL_REG1_A, 0x57) != 0) {
        fprintf(stderr, "Error: cannot write accel CTRL_REG1_A\n");
        cleanup();
        return EXIT_FAILURE;
    }
