    if (i2cWriteByteData(g_i2c_mag, LSM303_MAG_MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Error: cannot write mag MR_REG_M\n");
        cleanup();
        return EXIT_FAILURE;
    }

