    fclose(fp);

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (read_sensors(&ax, &ay, &az, &mx, &my, &mz) != 0) {
            fprintf(stderr, "Warning: sensor read failed, retrying next cycle\n");
