#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL6180X_ADDR   0x29

#define REG_MODEL_ID   0x000
#define REG_SYSRANGE_START 0x018
#define REG_RESULT_RANGE_VAL 0x062
#define REG_RESULT_INT_STATUS 0x04D
#define REG_SYSTEM_INTERRUPT_CLEAR 0x015
#define REG_SYSRANGE_THRESH_HIGH 0x01B
#define REG_SYSRANGE_THRESH_LOW 0x01C
#define REG_SYSTEM_INTERRUPT_CONFIG 0x014
#define REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define REG_SYSTEM_MODE_GPIO1 0x020
#define REG_SYSTEM_INTERRUPT_CLEAR 0x015
#define REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x016

#define MODEL_ID_EXPECTED 0xB4
#define DOOR_THRESHOLD_MM 100
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val) {
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *val) {
    uint8_t buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, buf, 2) != 2) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int vl6180x_init(int fd) {
    uint8_t model_id = 0;
    if (i2c_read_reg8(fd, REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: failed to read model ID\n");
        return -1;
    }
    if (model_id != MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, MODEL_ID_EXPECTED);
        return -1;
    }

    uint8_t fresh = 0;
    if (i2c_read_reg8(fd, REG_SYSTEM_FRESH_OUT_OF_RESET, &fresh) < 0) {
        fprintf(stderr, "Error: failed to read fresh-out-of-reset\n");
        return -1;
    }
    if (fresh == 0x01) {
        if (i2c_write_reg8(fd, REG_SYSRANGE_THRESH_HIGH, 0x0B) < 0) return -1;
        if (i2c_write_reg8(fd, REG_SYSRANGE_THRESH_LOW, 0x0A) < 0) return -1;
        if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) < 0) return -1;
        if (i2c_write_reg8(fd, REG_SYSTEM_MODE_GPIO1, 0x03) < 0) return -1;
        if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x07) < 0) return -1;
        if (i2c_write_reg8(fd, REG_SYSTEM_FRESH_OUT_OF_RESET, 0x00) < 0) return -1;
    }
    return 0;
}

static int vl6180x_read_distance(int fd, int *distance_mm) {
    uint8_t status = 0;
    if (i2c_read_reg8(fd, REG_RESULT_INT_STATUS, &status) < 0) return -1;
    if ((status & 0x07) == 0) return 1;

    if (i2c_write_reg8(fd, REG_SYSRANGE_START, 0x01) < 0) return -1;

    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg8(fd, REG_RESULT_INT_STATUS, &status) < 0) return -1;
        if ((status & 0x07) != 0) break;
        usleep(1000);
    }

    uint8_t range = 0;
    if (i2c_read_reg8(fd, REG_RESULT_RANGE_VAL, &range) < 0) return -1;
    *distance_mm = (int)range;

    if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x07) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, int distance, const char *status) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Distance: %d mm, %s\n", ts, distance, status);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL6180X_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(g_i2c_fd);
        return 1;
    }

    if (vl6180x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Error: VL6180X initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        close(g_i2c_fd);
        return 1;
    }

    while (g_running) {
        int distance = 0;
        int rc = vl6180x_read_distance(g_i2c_fd, &distance);

        if (rc < 0) {
            fprintf(stderr, "Error: I2C communication failure, attempting re-init...\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            usleep(1000000);
            g_i2c_fd = open(I2C_BUS, O_RDWR);
            if (g_i2c_fd < 0) {
                perror("Error re-opening I2C bus");
                break;
            }
            if (ioctl(g_i2c_fd, I2C_SLAVE, VL6180X_ADDR) < 0) {
                perror("Error re-setting I2C slave address");
                break;
            }
            if (vl6180x_init(g_i2c_fd) < 0) {
                fprintf(stderr, "Error: VL6180X re-initialization failed\n");
                break;
            }
            continue;
        }

        if (rc == 0) {
            const char *status = (distance < DOOR_THRESHOLD_MM) ? "DOOR_OPEN" : "DOOR_CLOSED";
            log_data(fp, distance, status);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    if (fp) fclose(fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

