#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x40
#define SENSOR2_ADDR 0x41
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

static int read_audio_sample(int handle) {
    char buf[2];
    int result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C handle %d: %d\n", handle, result);
        return -1;
    }
    int16_t sample = (int16_t)((buf[0] << 8) | buf[1]);
    return (int)sample;
}

static double calculate_tdoa(const struct timespec *t1, const struct timespec *t2) {
    return (double)(t2->tv_sec - t1->tv_sec) + (double)(t2->tv_nsec - t1->tv_nsec) / 1e9;
}

static int log_data(FILE *fp, const struct timespec *t1, const struct timespec *t2, int s1, int s2, double tdoa) {
    if (fprintf(fp, "%ld,%ld,%d,%d,%.9f\n", t1->tv_sec, t1->tv_nsec, s1, s2, tdoa) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    struct timespec t1, t2;
    int s1, s2;

    while (running) {
        s1 = read_audio_sample(i2c_handle1);
        s2 = read_audio_sample(i2c_handle2);

        if (s1 == -1 || s2 == -1) {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &t1) != 0) {
            fprintf(stderr, "Error getting timestamp, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        gpioDelay(SAMPLE_INTERVAL_US);

        if (!running) break;

        s2 = read_audio_sample(i2c_handle2);
        if (s2 == -1) {
            fprintf(stderr, "Error reading sensor 2, skipping sample\n");
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &t2) != 0) {
            fprintf(stderr, "Error getting timestamp, skipping sample\n");
            continue;
        }

        double tdoa = calculate_tdoa(&t1, &t2);

        if (log_data(log_file, &t1, &t2, s1, s2, tdoa) != 0) {
            fprintf(stderr, "Error logging data\n");
        }
    }

    cleanup();
    return 0;
}

