#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define STALL_US        40
#define SAMPLE_MS       100
#define LOG_FILE        "imu_data.csv"

#define REG_GYRO_XOUT   0x04
#define REG_GYRO_YOUT   0x06
#define REG_GYRO_ZOUT   0x08
#define REG_ACCEL_XOUT  0x0A
#define REG_ACCEL_YOUT  0x0C
#define REG_ACCEL_ZOUT  0x0E

#define GYRO_SENS       0.005f
#define ACCEL_SENS      0.00025f

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void cleanup(void) {
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    if (spi_fd >= 0) { close(spi_fd); spi_fd = -1; }
}

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_xfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t tx[2] = { 0x80 | (reg & 0x7F), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_xfer(fd, tx, rx, 2) < 0) return -1;
    usleep(STALL_US);

    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];
    *out = (int16_t)raw;
    return 0;
}

static int read_imu(int fd, float *gx, float *gy, float *gz,
                     float *ax, float *ay, float *az) {
    int16_t rx, ry, rz, ax1, ay1, az1;

    if (read_reg16(fd, REG_GYRO_XOUT, &rx) < 0) return -1;
    if (read_reg16(fd, REG_GYRO_YOUT, &ry) < 0) return -1;
    if (read_reg16(fd, REG_GYRO_ZOUT, &rz) < 0) return -1;
    if (read_reg16(fd, REG_ACCEL_XOUT, &ax1) < 0) return -1;
    if (read_reg16(fd, REG_ACCEL_YOUT, &ay1) < 0) return -1;
    if (read_reg16(fd, REG_ACCEL_ZOUT, &az1) < 0) return -1;

    *gx = (float)rx * GYRO_SENS;
    *gy = (float)ry * GYRO_SENS;
    *gz = (float)rz * GYRO_SENS;
    *ax = (float)ax1 * ACCEL_SENS;
    *ay = (float)ay1 * ACCEL_SENS;
    *az = (float)az1 * ACCEL_SENS;
    return 0;
}

static int log_data(FILE *fp, float gx, float gy, float gz,
                     float ax, float ay, float az) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }
    long ms = ts.tv_nsec / 1000000;
    if (fprintf(fp, "%ld.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                (long)ts.tv_sec, ms, gx, gy, gz, ax, ay, az) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }
    if (fprintf(log_fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n") < 0) {
        fprintf(stderr, "Cannot write header: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fflush(log_fp);

    atexit(cleanup);

    while (running) {
        float gx, gy, gz, ax, ay, az;
        if (read_imu(spi_fd, &gx, &gy, &gz, &ax, &ay, &az) < 0) {
            fprintf(stderr, "IMU read failed; skipping sample\n");
        } else {
            if (log_data(log_fp, gx, gy, gz, ax, ay, az) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        }
        usleep(SAMPLE_MS * 1000);
    }

    return 0;
}

