#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* ADIS16448 Register Map (16-bit addresses, bit 15 = read/write) */
#define ADIS16448_REG_GLOB_CMD    0x0000
#define ADIS16448_REG_GLOB_BURST  0x0001
#define ADIS16448_REG_GLOB_CTRL   0x0002
#define ADIS16448_REG_GLOB_STAT   0x0003
#define ADIS16448_REG_GYRO_XOUT   0x0004
#define ADIS16448_REG_GYRO_YOUT   0x0006
#define ADIS16448_REG_GYRO_ZOUT   0x0008
#define ADIS16448_REG_ACCEL_XOUT  0x000A
#define ADIS16448_REG_ACCEL_YOUT  0x000C
#define ADIS16448_REG_ACCEL_ZOUT  0x000E

#define ADIS16448_CMD_READ        0x8000
#define ADIS16448_CMD_WRITE       0x0000

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

#define GYRO_SCALE  0.05f    /* deg/s per LSB */
#define ACCEL_SCALE 0.00025f /* g per LSB */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * ADIS16448 two-cycle read:
 *   1) send 16-bit command (addr | 0x8000)
 *   2) stall >= 40 us, then send 0x0000 (dummy) to clock out data
 *
 * Returns 0 on success, -1 on transfer failure.
 */
static int adis16448_read_reg(int handle, uint16_t reg, uint16_t *out)
{
    char tx[4], rx[4];
    int  i;

    /* First 16-bit transfer: write command */
    tx[0] = (char)((reg >> 8) & 0xFF);
    tx[1] = (char)(reg & 0xFF);
    tx[2] = 0x00;
    tx[3] = 0x00;

    if (spiXfer(handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI write transfer failed for reg 0x%04X\n", reg);
        return -1;
    }

    /* Stall >= 40 us */
    gpioDelay(40);

    /* Second 16-bit transfer: dummy read */
    tx[0] = 0x00;
    tx[1] = 0x00;
    tx[2] = 0x00;
    tx[3] = 0x00;

    if (spiXfer(handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI read transfer failed for reg 0x%04X\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)rx[2] << 8) | (uint8_t)rx[3];
    return 0;
}

static int read_imu_data(int handle,
                         float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z)
{
    uint16_t raw;

    if (adis16448_read_reg(handle, ADIS16448_REG_GYRO_XOUT, &raw) != 0) return -1;
    *gyro_x = (float)raw * GYRO_SCALE;

    if (adis16448_read_reg(handle, ADIS16448_REG_GYRO_YOUT, &raw) != 0) return -1;
    *gyro_y = (float)raw * GYRO_SCALE;

    if (adis16448_read_reg(handle, ADIS16448_REG_GYRO_ZOUT, &raw) != 0) return -1;
    *gyro_z = (float)raw * GYRO_SCALE;

    if (adis16448_read_reg(handle, ADIS16448_REG_ACCEL_XOUT, &raw) != 0) return -1;
    *accel_x = (float)raw * ACCEL_SCALE;

    if (adis16448_read_reg(handle, ADIS16448_REG_ACCEL_YOUT, &raw) != 0) return -1;
    *accel_y = (float)raw * ACCEL_SCALE;

    if (adis16448_read_reg(handle, ADIS16448_REG_ACCEL_ZOUT, &raw) != 0) return -1;
    *accel_z = (float)raw * ACCEL_SCALE;

    return 0;
}

int main(void)
{
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU Reader (SPI ch%d, %d Hz, Mode 0)\n",
           SPI_CHANNEL, SPI_SPEED);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        if (read_imu_data(g_spi_handle,
                          &gyro_x, &gyro_y, &gyro_z,
                          &accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro:  X=%.2f deg/s  Y=%.2f deg/s  Z=%.2f deg/s  | "
                   "Accel:  X=%.4f g  Y=%.4f g  Z=%.4f g\n",
                   gyro_x, gyro_y, gyro_z,
                   accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "IMU read error — continuing\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

