#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

/* MPU-6886 I2C address (AD0 tied to GND) */
#define MPU6886_ADDR 0x68

/* MPU-6886 register addresses */
#define MPU6886_SMPLRT_DIV   0x19
#define MPU6886_CONFIG       0x1A
#define MPU6886_GYRO_CONFIG  0x1B
#define MPU6886_ACCEL_CONFIG 0x1C
#define MPU6886_ACCEL_XOUT_H 0x3B
#define MPU6886_GYRO_XOUT_H  0x43

/* I2C bus device path */
#define I2C_DEV "/dev/i2c-1"

/* Retry configuration */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000

/* Global flag for signal handling */
static volatile sig_atomic_t running = 1;

/* Signal handler for SIGINT (Ctrl+C) */
static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a single byte to an I2C register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an I2C register */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from two consecutive registers */
static int i2c_read_reg16(int fd, uint8_t reg, int16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* Initialize the MPU-6886 sensor */
static int init_mpu6886(int fd) {
    /* Wake up the sensor (clear sleep bit) */
    if (i2c_write_reg8(fd, MPU6886_PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    usleep(100000); /* 100 ms stabilization */

    /* Sample rate divider: 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg8(fd, MPU6886_SMPLRT_DIV, 0x07) < 0) {
        return -1;
    }

    /* DLPF configuration: 256 Hz bandwidth, 1 kHz rate */
    if (i2c_write_reg8(fd, MPU6886_CONFIG, 0x01) < 0) {
        return -1;
    }

    /* Gyro full scale range: ±250 °/s */
    if (i2c_write_reg8(fd, MPU6886_GYRO_CONFIG, 0x00) < 0) {
        return -1;
    }

    /* Accelerometer full scale range: ±2 g */
    if (i2c_write_reg8(fd, MPU6886_ACCEL_CONFIG, 0x00) < 0) {
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
    int retry_count;

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Error acquiring I2C bus address 0x%02X: %s\n", MPU6886_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6886 sensor */
    if (init_mpu6886(fd) < 0) {
        fprintf(stderr, "Error initializing MPU-6886 sensor.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6886 initialized. Reading data every 50 ms...\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        retry_count = 0;
        do {
            if (i2c_read_reg16(fd, MPU6886_ACCEL_XOUT_H, &accel_x) == 0 &&
                i2c_read_reg16(fd, MPU6886_ACCEL_YOUT_H, &accel_y) == 0 &&
                i2c_read_reg16(fd, MPU6886_ACCEL_ZOUT_H, &accel_z) == 0 &&
                i2c_read_reg16(fd, MPU6886_GYRO_XOUT_H, &gyro_x) == 0 &&
                i2c_read_reg16(fd, MPU6886_GYRO_YOUT_H, &gyro_y) == 0 &&
                i2c_read_reg16(fd, MPU6886_GYRO_ZOUT_H, &gyro_z) == 0) {
                break;
            }
            retry_count++;
            if (retry_count < MAX_RETRIES) {
                usleep(RETRY_DELAY_US);
            }
        } while (retry_count < MAX_RETRIES && running);

        if (retry_count >= MAX_RETRIES) {
            fprintf(stderr, "Error: Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        } else {
            printf("Accel X: %6d, Y: %6d, Z: %6d | Gyro X: %6d, Y: %6d, Z: %6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        }

        usleep(50000); /* 50 ms delay */
    }

    /* Clean resource release on exit */
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting gracefully.\n");

    return EXIT_SUCCESS;
}

