#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_DATAX1      0x33
#define ADXL345_DATAY0      0x34
#define ADXL345_DATAY1      0x35
#define ADXL345_DATAZ0      0x36
#define ADXL345_DATAZ1      0x37

/* Expected device ID */
#define ADXL345_DEVID_VAL   0xE5

/* Sensitivity scale factor for ±2g range: 256 LSB/g */
#define SCALE_FACTOR 256.0f

/* Impact threshold in g */
#define IMPACT_THRESHOLD 2.5f

/* LED GPIO pin (BCM) */
#define LED_PIN 17

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 10000

/* LED on-time in microseconds */
#define LED_ON_TIME_US 500000

/* Global state */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X val=0x%02X rc=%d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: reg=0x%02X rc=%d\n", reg, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read error: reg=0x%02X len=%u rc=%d\n",
                reg, len, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* ADXL345 initialization                                              */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    int devid = i2c_read_byte(handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Cannot read DEVID register — sensor absent or bus error\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "DEVID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2c_write_byte(handle, ADXL345_POWER_CTL, 0x00) < 0)
        return -1;

    /* Full resolution, ±2g range (0x0B) */
    if (i2c_write_byte(handle, ADXL345_DATA_FORMAT, 0x0B) < 0)
        return -1;

    /* Measurement mode */
    if (i2c_write_byte(handle, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (X, Y, Z) in g                                    */
/* ------------------------------------------------------------------ */
static int adxl345_read_accel(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (i2c_read_block(handle, ADXL345_DATAX0, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / SCALE_FACTOR;
    *y = (float)raw_y / SCALE_FACTOR;
    *z = (float)raw_z / SCALE_FACTOR;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Impact detection                                                    */
/* ------------------------------------------------------------------ */
static bool impact_detected(float x, float y, float z)
{
    float magnitude = sqrtf(x * x + y * y + z * z);
    return magnitude > IMPACT_THRESHOLD;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
            timestamp, x, y, z);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ADXL345 address */
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open log file in append mode */
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open impact_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 impact detection started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (!terminate) {
        float x, y, z;

        if (adxl345_read_accel(i2c_handle, &x, &y, &z) == 0) {
            if (impact_detected(x, y, z)) {
                printf("Impact detected! Magnitude: %.3f g\n",
                       sqrtf(x * x + y * y + z * z));

                gpioWrite(LED_PIN, 1);
                log_impact(x, y, z);

                /* Keep LED on for the on-time, but allow signal to exit promptly */
                uint32_t elapsed = 0;
                while (!terminate && elapsed < LED_ON_TIME_US) {
                    gpioDelay(POLL_INTERVAL_US);
                    elapsed += POLL_INTERVAL_US;
                }
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

