#define I2C_BUS        "/dev/i2c-1"
#define TMAG5273_ADDR  0x30
#define CSV_FILE       "magnetic_field_log.csv"
#define SAMPLE_PERIOD  1

/* TMAG5273 register addresses (example: X-axis Hall-effect channel) */
#define TMAG5273_REG_X_HALL_CH0  0x00
#define TMAG5273_REG_Y_HALL_CH1  0x01
#define TMAG5273_REG_Z_HALL_CH2  0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write reg address failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("i2c_read_reg8: read data failed");
        return -1;
    }
    return 0;
}

static int read_magnetic_field(int fd, float *x, float *y, float *z)
{
    uint8_t x_raw, y_raw, z_raw;

    if (i2c_read_reg8(fd, TMAG5273_REG_X_HALL_CH0, &x_raw) < 0) return -1;
    if (i2c_read_reg8(fd, TMAG5273_REG_Y_HALL_CH1, &y_raw) < 0) return -1;
    if (i2c_read_reg8(fd, TMAG5273_REG_Z_HALL_CH2, &z_raw) < 0) return -1;

    /* Convert raw ADC value to magnetic field (example: 1 LSB = 0.1 mT) */
    *x = (float)x_raw * 0.1f;
    *y = (float)y_raw * 0.1f;
    *z = (float)z_raw * 0.1f;

    return 0;
}

static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        perror("fprintf failed");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush failed");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    int ret = EXIT_FAILURE;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ") failed");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE) failed");
        goto cleanup_i2c;
    }

    /* Verify sensor presence by reading a register */
    uint8_t test_reg;
    if (i2c_read_reg8(g_i2c_fd, TMAG5273_REG_X_HALL_CH0, &test_reg) < 0) {
        fprintf(stderr, "Sensor not detected at address 0x%02X\n", TMAG5273_ADDR);
        goto cleanup_i2c;
    }

    g_csv = fopen(CSV_FILE, "a+");
    if (g_csv == NULL) {
        perror("fopen(" CSV_FILE ") failed");
        goto cleanup_i2c;
    }

    /* Write header if file is empty */
    if (fseek(g_csv, 0, SEEK_END) != 0) {
        perror("fseek failed");
        goto cleanup_all;
    }
    long file_size = ftell(g_csv);
    if (file_size == 0) {
        if (fprintf(g_csv, "Timestamp,X_mT,Y_mT,Z_mT\n") < 0) {
            perror("fprintf header failed");
            goto cleanup_all;
        }
        if (fflush(g_csv) != 0) {
            perror("fflush header failed");
            goto cleanup_all;
        }
    }

    printf("TMAG5273 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;

        if (read_magnetic_field(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_data(g_csv, x, y, z) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read magnetic field data\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup_all:
    if (g_csv != NULL) {
        fclose(g_csv);
        g_csv = NULL;
    }
cleanup_i2c:
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return ret;
}

