#define TAP_WINDOW 0x05

#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define LOG_FILE "freefall_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_line *int_line = NULL;
static struct gpiod_chip *chip = NULL;
static FILE *log_fp = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg-select 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid;
    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) < 0) return -1;
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, ADXL345_DEVID_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_BW_RATE, ADXL345_RATE_100HZ) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_DATA_FORMAT, ADXL345_FULL_RES | ADXL345_RANGE_2G) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_INT_MAP, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_INT_ENABLE, ADXL345_INT_FREE_FALL) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_THRESH_FF, FREEFALL_THRESHOLD) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_TIME_FF, FREEFALL_TIME) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_TAP_AXES, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_ACT_INACT_CTL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_DEBOUNCE, 0x00) < 0) return -1;
    return 0;
}

static int adxl345_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
