        i2c_write_reg8(i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }
    int_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!int_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(int_line, "adxl345_int") < 0) {
        fprintf(stderr, "Failed to request GPIO input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(int_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        gpiod_line_release(int_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        gpiod_line_release(int_line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        gpiod_line_release(int_line);
        gpiod_chip_close(chip);
        return 1;
    }
    fprintf(log_fp, "timestamp,x,y,z\n");
    fflush(log_fp);

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    while (running) {
        struct pollfd pfd = { .fd = i2c_fd, .events = POLLIN };
        int ret = poll(&pfd, 1, 1000);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Poll error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;
        if (pfd.revents & POLLIN) {
            uint8_t int_status;
            if (i2c_read_reg8(i2c_fd, ADXL345_INT_SOURCE, &int_status) < 0) continue;
            if (int_status & ADXL345_INT_FREE_FALL) {
                int16_t x, y, z;
                if (adxl345_read_xyz(i2c_fd, &x, &y, &z) == 0) {
                    log_data(x, y, z);
                }
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

