#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM6DSR_ADDR 0x6B

#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x69

#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define CTRL3_C 0x12

#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

#define ACCEL_SENSITIVITY 0.061f
#define GYRO_SENSITIVITY 4.375f

#define ACCEL_THRESHOLD_FREEFALL 0.2f
#define ACCEL_THRESHOLD_IMPACT 2.5f
#define IMPACT_WINDOW_SEC 1.0f

#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_regs(uint8_t reg, uint8_t *buf, int len) {
    if (write(i2c_fd, &reg, 1) != 1) return -1;
    if (read(i2c_fd, buf, len) != len) return -1;
    return 0;
}

static int init_lsm6dsr(void) {
    uint8_t who_am_i = 0;
    if (i2c_read_regs(WHO_AM_I, &who_am_i, 1) < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (0x%02X, expected 0x%02X). Sensor absent or wrong device.\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg(CTRL1_XL, 0x60) < 0) return -1;
    if (i2c_write_reg(CTRL2_G, 0x60) < 0) return -1;
    if (i2c_write_reg(CTRL3_C, 0x04) < 0) return -1;

    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[6];

    if (i2c_read_regs(OUTX_L_G, buf, 6) < 0) return -1;
    int16_t gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t gz = (int16_t)((buf[5] << 8) | buf[4]);
    data->gyro_x = gx * GYRO_SENSITIVITY / 1000.0f;
    data->gyro_y = gy * GYRO_SENSITIVITY / 1000.0f;
    data->gyro_z = gz * GYRO_SENSITIVITY / 1000.0f;

    if (i2c_read_regs(OUTX_L_XL, buf, 6) < 0) return -1;
    int16_t ax = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ay = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t az = (int16_t)((buf[5] << 8) | buf[4]);
    data->accel_x = ax * ACCEL_SENSITIVITY / 1000.0f;
    data->accel_y = ay * ACCEL_SENSITIVITY / 1000.0f;
    data->accel_z = az * ACCEL_SENSITIVITY / 1000.0f;

    return 0;
}

static void log_data(sensor_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

static void detect_fall(sensor_data_t *data) {
    static enum { IDLE, FREEFALL, IMPACT } state = IDLE;
    static struct timespec impact_start;

    float mag = sqrtf(data->accel_x * data->accel_x +
                      data->accel_y * data->accel_y +
                      data->accel_z * data->accel_z);

    switch (state) {
        case IDLE:
            if (mag < ACCEL_THRESHOLD_FREEFALL) {
                state = FREEFALL;
                impact_start = *(struct timespec *)&mag;
            }
            break;
        case FREEFALL:
            if (mag > ACCEL_THRESHOLD_IMPACT) {
                struct timespec now;
                clock_gettime(CLOCK_REALTIME, &now);
                double elapsed = (now.tv_sec - impact_start.tv_sec) +
                                 (now.tv_nsec - impact_start.tv_nsec) / 1e9;
                if (elapsed <= IMPACT_WINDOW_SEC) {
                    state = IMPACT;
                    printf("Fall detected!\n");
