#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 register addresses (16-bit, big-endian on the bus) */
#define ADIS16266_REG_WHO_AM_I   0x0000
#define ADIS16266_REG_XGYRO_OUT  0x0400
#define ADIS16266_REG_YGYRO_OUT  0x0402
#define ADIS16266_REG_ZGYRO_OUT  0x0404
#define ADIS16266_REG_TEMP_OUT   0x0406

#define ADIS16266_WHO_AM_I_VAL   0xAD
#define ADIS16266_SCALE_FACTOR  0.0305f  /* deg/sec per LSB */

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0x03     /* mode 3: CPOL=1, CPHA=1 */
#define SAMPLE_US   10000    /* 10 ms */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit register from the ADIS16266.
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int adis16266_read_reg(int handle, uint16_t reg, int16_t *out)
{
    char tx[2], rx[2];
    tx[0] = (char)(reg >> 8);
    tx[1] = (char)(reg & 0xFF);

    int ret = spiXfer(handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%04X (ret=%d)\n",
                reg, ret);
        return -1;
    }

    /* ADIS16266 returns the response in the second byte of the second
     * transfer, so the first byte of the second transfer is the data. */
    *out = (int16_t)(((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[0]);
    return 0;
}

static int adis16266_verify(int handle)
{
    int16_t who;
    if (adis16266_read_reg(handle, ADIS16266_REG_WHO_AM_I, &who) != 0)
        return -1;
    if ((uint16_t)who != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                (uint16_t)who, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

static int adis16266_read_gyro(int handle, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;
    if (adis16266_read_reg(handle, ADIS16266_REG_XGYRO_OUT, &raw_x) != 0) return -1;
    if (adis16266_read_reg(handle, ADIS16266_REG_YGYRO_OUT, &raw_y) != 0) return -1;
    if (adis16266_read_reg(handle, ADIS16266_REG_ZGYRO_OUT, &raw_z) != 0) return -1;

    *x = (float)raw_x * ADIS16266_SCALE_FACTOR;
    *y = (float)raw_y * ADIS16266_SCALE_FACTOR;
    *z = (float)raw_z * ADIS16266_SCALE_FACTOR;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld,%.4f,%.4f,%.4f\n",
            tbuf, ts.tv_nsec / 1000000L, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adis16266_verify(g_spi_handle) != 0) {
        fprintf(stderr, "ADIS16266 not detected or SPI bus error\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("gyro_log.csv", "a");
    if (!g_log_file) {
        perror("fopen(gyro_log.csv)");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# timestamp,x_deg_s,y_deg_s,z_deg_s\n");
    fflush(g_log_file);

    printf("ADIS16266 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (adis16266_read_gyro(g_spi_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "Gyro read error; continuing.\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

