#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

/* ---- L3G4200D constants (datasheet) ---- */
#define L3G4200D_ADDR        0x69
#define WHO_AM_I_REG         0x0F
#define WHO_AM_I_VAL         0xD3
#define CTRL_REG1            0x20
#define CTRL_REG4            0x23
#define OUT_X_L              0x28
#define OUT_X_H              0x29
#define OUT_Y_L              0x2A
#define OUT_Y_H              0x2B
#define OUT_Z_L              0x2C
#define OUT_Z_H              0x2D
#define SENSITIVITY_MDPS     8.75f   /* mdps/LSB at ±250 dps */
#define SAMPLE_PERIOD_US     10000   /* 10 ms */
#define MAX_INIT_RETRIES     3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static int init_gyro(void)
{
    int handle = -1;
    int status;

    /* Open I2C bus 1 at the L3G4200D address */
    handle = i2cOpen(1, L3G4200D_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %s\n",
                L3G4200D_ADDR, strerror(errno));
        return -1;
    }

    /* Verify sensor identity */
    int who = i2cReadByteData(handle, WHO_AM_I_REG);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n",
                strerror(errno));
        i2cClose(handle);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        i2cClose(handle);
        return -1;
    }

    /*
     * CTRL_REG1: 0x0F = 0001 1111
     *   bit 7  = 0  -> normal mode
     *   bits 6:5 = 11 -> ODR = 100 Hz (0x0C)
     *   bit 4  = 0  -> low-noise disabled
     *   bits 3:2 = 00 -> FS = 0 (±250 dps)
     *   bit 1  = 0  -> sleep disabled
     *   bit 0  = 1  -> active mode
     */
    status = i2cWriteByteData(handle, CTRL_REG1, 0x0F);
    if (status < 0) {
