#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Read the flame sensor on BCM GPIO17.
 * Returns 0 (flame detected) or 1 (no flame) on success,
 * -1 on pigpio read error, -2 on invalid GPIO.
 */
static int read_flame_sensor(int gpio)
{
    if (gpio < 0 || gpio > 31) {
        fprintf(stderr, "Error: invalid GPIO %d\n", gpio);
        return -2;
    }

    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed: %s\n",
                gpio, pigpio_error(level));
        return -1;
    }

    /*
     * KY-026 DO is active-LOW:
     *   LOW  (0)  -> flame detected
     *   HIGH (1)  -> no flame
     */
    return (level == 0) ? 0 : 1;
}

/*
 * Append a timestamped flame event line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_flame_event(FILE *log_file, int flame_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s – Flame detected: %s\n",
                timestamp, flame_detected ? "YES" : "NO") < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    FILE *log_file = NULL;
    int ret_code = EXIT_SUCCESS;

    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO17 as input with internal pull-up --- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file in append mode --- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d.\n", FLAME_SENSOR_GPIO);
    printf("Logging to '%s'. Press Ctrl-C to exit.\n", LOG_FILE_NAME);

    /* --- Main polling loop --- */
    while (program_running) {
        int sensor_value = read_flame_sensor(FLAME_SENSOR_GPIO);

        if (sensor_value < 0) {
            /* Sensor read error — log the event so we don't lose data */
            if (log_flame_event(log_file, -1) != 0) {
                fprintf(stderr, "Error: failed to log sensor read error\n");
            }
        } else {
            int flame_detected = (sensor_value == 0);

            if (log_flame_event(log_file, flame_detected) != 0) {
                fprintf(stderr, "Error: failed to log flame event\n");
            }

            if (flame_detected) {
                printf("FLAME DETECTED!\n");
            }
        }

        /*
         * gpioDelay returns the elapsed microseconds, but we only
         * need to break the 500 ms interval; pigpio's microsecond
         * delay is accurate enough for this application.
         */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");

    if (fclose(log_file) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        ret_code = EXIT_FAILURE;
    }

    gpioTerminate();
    return ret_code;
}

