#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x50
#define CSV_FILE       "vibration_log.csv"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */
#define READ_RETRIES   3
#define READ_RETRY_DELAY_US 10000 /* 10 ms */

/* D7S-0001: 6 bytes of acceleration data starting at register 0x00 */
#define D7S_REG_X_LSB 0x00
#define D7S_REG_X_MSB 0x01
#define D7S_REG_Y_LSB 0x02
#define D7S_REG_Y_MSB 0x03
#define D7S_REG_Z_LSB 0x04
#define D7S_REG_Z_MSB 0x05

/* Sensor-absent / bus-error sentinel values (16-bit, big-endian) */
#define D7S_SENTINEL_X 0x8000
#define D7S_SENTINEL_Y 0x4000
#define D7S_SENTINEL_Z 0x2000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit big-endian value to an 8-bit register address */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from an 8-bit register address */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg 0x%02X failed: %s\n",
