#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define CTRL_REG1      0x20
#define CTRL_REG2      0x21
#define CTRL_REG3      0x22
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D

#define SCALE_FACTOR   0.146f   /* mG/LSB at +/- 4 gauss */
#define THRESHOLD      800.0f   /* mG */
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

#define OFFSET_X 0.0f
#define OFFSET_Y 0.0f
#define OFFSET_Z 0.0f
#define SCALE_X  1.0f
#define SCALE_Y  1.0f
#define SCALE_Z  1.0f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg: write reg failed");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg: read failed");
        return -1;
    }
    return 0;
}

static int lis3mdl_init(int fd)
{
    if (i2c_write_reg(fd, CTRL_REG1, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG2, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG3, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG4, 0x0C) < 0) return -1; /* +/- 4 gauss, continuous */
    return 0;
}

static int lis3mdl_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg(fd, OUT_X_L, &xl) < 0) return -1;
    if (i2c_read_reg(fd, OUT_X_H, &xh) < 0) return -1;
    if (i2c_read_reg(fd, OUT_Y_L, &yl) < 0) return -1;
    if (i2c_read_reg(fd, OUT_Y_H, &yh) < 0) return -1;
    if (i2c_read_reg(fd, OUT_Z_L, &zl) < 0) return -1;
    if (i2c_read_reg(fd, OUT_Z_H, &zh) < 0) return -1;
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                           float *cal_x, float *cal_y, float *cal_z)
{
    *cal_x = ((float)raw_x - OFFSET_X) * SCALE_X;
    *cal_y = ((float)raw_y - OFFSET_Y) * SCALE_Y;
    *cal_z = ((float)raw_z - OFFSET_Z) * SCALE_Z;
}

static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

static void log_data(FILE *fp, float x, float y, float z, float mag)
{
    fprintf(fp, "%.2f,%.2f,%.2f,%.2f\n", x, y, z, mag);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open I2C bus failed");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("ioctl I2C_SLAVE failed");
        cleanup();
        return EXIT_FAILURE;
    }

    int init_ok = false;
    for (int attempt = 0; attempt < 3; attempt++) {
        if (lis3mdl_init(g_i2c_fd) == 0) {
            init_ok = true;
            break;
        }
        fprintf(stderr, "LIS3MDL init attempt %d failed; retrying...\n", attempt + 1);
        usleep(100000);
    }
    if (!init_ok) {
        fprintf(stderr, "LIS3MDL init failed after 3 attempts; aborting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("magnetic_log.txt", "w");
    if (!g_log_fp) {
        perror("fopen magnetic_log.txt failed");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "timestamp,x_mg,y_mg,z_mg,mag_mg\n");
    fflush(g_log_fp);

    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC, &next);

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (lis3mdl_read_xyz(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "I2C read error; continuing.\n");
            next.tv_nsec += SAMPLE_PERIOD_US * 1000;
            if (next.tv_nsec >= 1000000000L) {
                next.tv_nsec -= 1000000000L;
                next.tv_sec++;
            }
            continue;
        }

        float cal_x, cal_y, cal_z;
        calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
        float mag = calculate_magnitude(cal_x, cal_y, cal_z);

        log_data(g_log_fp, cal_x, cal_y, cal_z, mag);

        if (mag > THRESHOLD) {
            fprintf(stderr, "METAL DETECTOR ALERT: magnitude %.2f mG exceeds threshold %.2f mG\n",
                    mag, THRESHOLD);
        }

        next.tv_nsec += SAMPLE_PERIOD_US * 1000;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_nsec -= 1000000000L;
            next.tv_sec++;
        }
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec < next.tv_sec ||
            (now.tv_sec == next.tv_sec && now.tv_nsec < next.tv_nsec)) {
            struct timespec sleep_ts = {
                .tv_sec  = next.tv_sec  - now.tv_sec,
                .tv_nsec = next.tv_nsec - now.tv_nsec
            };
            if (sleep_ts.tv_nsec < 0) {
                sleep_ts.tv_sec--;
                sleep_ts.tv_nsec += 1000000000L;
            }
            nanosleep(&sleep_ts, NULL);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

