#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define LOG_FILE "vibration_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define RESET_DELAY_US 1000
#define STABLE_TIMEOUT_US 1000000

#define ADXL354_REG_STATUS 0x04
#define ADXL354_REG_XDATA_H 0x08
#define ADXL354_REG_YDATA_H 0x0A
#define ADXL354_REG_ZDATA_H 0x0C
#define ADXL354_REG_POWER_CTL 0x2D
#define ADXL354_REG_RESET 0x2F
#define ADXL354_REG_PARTID 0x02

#define ADXL354_PARTID_EXPECTED 0xE4
#define ADXL354_STATUS_STABLE 0x01
#define ADXL354_POWER_CTL_RUN 0x02

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0 };
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read error on reg 0x%02X: %d\n", reg, ret);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0 };
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write error on reg 0x%02X: %d\n", reg, ret);
        return -1;
    }
    return 0;
}

static int adxl354_reset(void) {
    if (spi_write_register(ADXL354_REG_RESET, 0x52) != 0) return -1;
    gpioDelay(RESET_DELAY_US);
    if (spi_write_register(ADXL354_REG_RESET, 0x00) != 0) return -1;
    return 0;
}

static int adxl354_init(void) {
    uint8_t partid = 0;
    if (spi_read_register(ADXL354_REG_PARTID, &partid) != 0) return -1;
    if (partid != ADXL354_PARTID_EXPECTED) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354_PARTID_EXPECTED);
        return -1;
    }
    if (adxl354_reset() != 0) return -1;
    uint32_t start = gpioTick();
    uint8_t status = 0;
    while (gpioTick() - start < STABLE_TIMEOUT_US) {
        if (spi_read_register(ADXL354_REG_STATUS, &status) != 0) return -1;
        if (status & ADXL354_STATUS_STABLE) break;
        gpioDelay(1000);
    }
    if (!(status & ADXL354_STATUS_STABLE)) {
        fprintf(stderr, "Sensor did not stabilize within timeout\n");
        return -1;
    }
    if (spi_write_register(ADXL354_REG_POWER_CTL, ADXL354_POWER_CTL_RUN) != 0) return -1;
    return 0;
}

static int adxl354_read_axis(uint8_t reg_h, int32_t *out) {
    uint8_t hi = 0, lo = 0, lo2 = 0;
    if (spi_read_register(reg_h, &hi) != 0) return -1;
    if (spi_read_register(reg_h + 1, &lo) != 0) return -1;
    if (spi_read_register(reg_h + 2, &lo2) != 0) return -1;
    uint32_t raw = ((uint32_t)(hi & 0x0F) << 16) | ((uint32_t)lo << 8) | (uint32_t)lo2;
    if (raw & 0x00100000) raw |= 0xFF000000;
    *out = (int32_t)raw;
    return 0;
}

static int adxl354_read_data(int32_t *x, int32_t *y, int32_t *z) {
    if (adxl354_read_axis(ADXL354_REG_XDATA_H, x) != 0) return -1;
    if (adxl354_read_axis(ADXL354_REG_YDATA_H, y) != 0) return -1;
    if (adxl354_read_axis(ADXL354_REG_ZDATA_H, z) != 0) return -1;
    return 0;
}

static void log_data(int32_t x, int32_t y, int32_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    if (adxl354_init() != 0) {
        fprintf(stderr, "ADXL354 init failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("ADXL354 logging started. Press Ctrl+C to stop.\n");
    while (!terminate) {
        int32_t x, y, z;
        if (adxl354_read_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Read error, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

