#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8

#define GYRO_X_OUT 0x04
#define GYRO_Y_OUT 0x06
#define GYRO_Z_OUT 0x08
#define ACCEL_X_OUT 0x0A
#define ACCEL_Y_OUT 0x0C
#define ACCEL_Z_OUT 0x0E

#define GYRO_SCALE 0.05f
#define ACCEL_SCALE 0.0025f

#define LOG_FILE "imu_log.csv"
#define SAMPLE_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(int fd, uint8_t reg, int16_t *value) {
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };
    if (spi_transfer(fd, tx, rx, 3) < 0) return -1;
    *value = (int16_t)((rx[1] << 8) | rx[2]);
    return 0;
}

static int read_imu_data(int fd, float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;
    if (read_register(fd, GYRO_X_OUT, &raw_gx) < 0) return -1;
    if (read_register(fd, GYRO_Y_OUT, &raw_gy) < 0) return -1;
    if (read_register(fd, GYRO_Z_OUT, &raw_gz) < 0) return -1;
    if (read_register(fd, ACCEL_X_OUT, &raw_ax) < 0) return -1;
    if (read_register(fd, ACCEL_Y_OUT, &raw_ay) < 0) return -1;
    if (read_register(fd, ACCEL_Z_OUT, &raw_az) < 0) return -1;
    *gyro_x = (float)raw_gx * GYRO_SCALE;
    *gyro_y = (float)raw_gy * GYRO_SCALE;
    *gyro_z = (float)raw_gz * GYRO_SCALE;
    *accel_x = (float)raw_ax * ACCEL_SCALE;
    *accel_y = (float)raw_ay * ACCEL_SCALE;
    *accel_z = (float)raw_az * ACCEL_SCALE;
    return 0;
}

static int log_data(FILE *fp, float gx, float gy, float gz,
                    float ax, float ay, float az) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%.9f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                (double)ts.tv_sec + (double)ts.tv_nsec / 1e9,
                gx, gy, gz, ax, ay, az) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(spi_fd);
        return 1;
    }

    if (fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n") < 0) {
        fprintf(stderr, "Failed to write header: %s\n", strerror(errno));
        fclose(log_file);
        close(spi_fd);
        return 1;
    }
    fflush(log_file);

    float gx, gy, gz, ax, ay, az;
    while (running) {
        if (read_imu_data(spi_fd, &gx, &gy, &gz, &ax, &ay, &az) == 0) {
            if (log_data(log_file, gx, gy, gz, ax, ay, az) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "IMU read failed, skipping sample\n");
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return 0;
}

