/*
 * KY-032 IR Obstacle Avoidance Sensor Poller
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: Two Keyes KY-032 modules, active-low output
 *   - Sensor 1: GPIO17 (physical pin 11)
 *   - Sensor 2: GPIO27 (physical pin 13)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky032_poller ky032_poller.c -lpigpio -lrt
 * Run:    sudo ./ky032_poller
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        printf("[?]");
        return;
    }
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        printf("[?]");
        return;
    }
    printf("[%04d-%02d-%02d %02d:%02d:%02d]",
           t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
           t->tm_hour, t->tm_min, t->tm_sec);
}

/*
 * Read both sensors in one bulk call.
 * Returns 0 on success, -1 on error.
 */
static int read_sensors(int *s1, int *s2)
{
    int v = gpioRead(SENSOR_1_GPIO);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed: %s\n",
                SENSOR_1_GPIO, pigpio_error(v));
        return -1;
    }
    *s1 = v;

    v = gpioRead(SENSOR_2_GPIO);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed: %s\n",
                SENSOR_2_GPIO, pigpio_error(v));
        return -1;
    }
    *s2 = v;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n",
                SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n",
                SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * KY-032 modules have an on-board pull-up resistor; enable the
     * internal pull-up so that a disconnected sensor reads 1 (path clear).
     */
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown(%d, PI_PUD_UP) failed.\n",
                SENSOR_1_GPIO);
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown(%d, PI_PUD_UP) failed.\n",
                SENSOR_2_GPIO);
    }

    printf("KY-032 Obstacle Avoidance Sensor Poller\n");
    printf("Sensor 1: GPIO%d | Sensor 2: GPIO%d\n", SENSOR_1_GPIO, SENSOR_2_GPIO);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int s1, s2;

        if (read_sensors(&s1, &s2) != 0) {
            fprintf(stderr, "Error: sensor read failed; continuing.\n");
        } else {
            /*
             * KY-032 modules are active-low:
             *   0 => obstacle detected
             *   1 => path clear
             */
            print_timestamp();
            printf(" Sensor1: %s | Sensor2: %s\n",
                   s1 == 0 ? "OBSTACLE" : "CLEAR",
                   s2 == 0 ? "OBSTACLE" : "CLEAR");
        }

        /*
         * Sleep in small increments so SIGINT is noticed promptly.
         */
        for (int i = 0; i < 10 && g_running; i++) {
            usleep(POLL_INTERVAL_US / 10);
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

