#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define LSM6DSR_WHO_AM_I   0x0F
#define LSM6DSR_CTRL1_XL   0x10
#define LSM6DSR_CTRL2_G    0x11
#define LSM6DSR_OUTX_L_G   0x22
#define LSM6DSR_OUTX_L_XL  0x28

/* Expected device ID */
#define LSM6DSR_WHO_AM_I_VAL 0x6C

/* Global handle for signal-safe cleanup */
static int g_i2c_handle = -1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Write a single byte to an I2C register; returns 0 on success, -1 on error */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read a single byte from an I2C register; returns 0 on success, -1 on error */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Read multiple bytes from consecutive registers; returns 0 on success, -1 on error */
static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading %u bytes from register 0x%02X (rc=%d)\n",
                len, reg, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "Short read: got %d of %u bytes from register 0x%02X\n",
                rc, len, reg);
        return -1;
    }
    return 0;
}

/* Initialize the LSM6DSR: verify device ID, enable accelerometer + gyroscope */
static int init_lsm6dsr(int handle)
{
    uint8_t who_am_i = 0;

    if (i2c_read_reg(handle, LSM6DSR_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    /* Enable accelerometer XYZ axes, 100 Hz ODR, normal mode */
    if (i2c_write_reg(handle, LSM6DSR_CTRL1_XL, 0x40) != 0) {
        fprintf(stderr, "Failed to configure accelerometer\n");
        return -1;
    }

    /* Enable gyroscope XYZ axes, 100 Hz ODR, normal mode */
    if (i2c_write_reg(handle, LSM6DSR_CTRL2_G, 0x40) != 0) {
        fprintf(stderr, "Failed to configure gyroscope\n");
        return -1;
    }

    return 0;
}

/* Read 6 bytes of accelerometer data (X, Y, Z) and gyroscope data (X, Y, Z) */
static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[12];

    if (i2c_read_burst(handle, LSM6DSR_OUTX_L_G, buf, sizeof(buf)) != 0) {
        return -1;
    }

    *gx = (int16_t)((buf[1] << 8) | buf[0]);
    *gy = (int16_t)((buf[3] << 8) | buf[2]);
    *gz = (int16_t)((buf[5] << 8) | buf[4]);
    *ax = (int16_t)((buf[7] << 8) | buf[6]);
    *ay = (int16_t)((buf[9] << 8) | buf[8]);
    *az = (int16_t)((buf[11] << 8) | buf[10]);

    return 0;
}

int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;
    int rc;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the LSM6DSR address */
    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the LSM6DSR */
    if (init_lsm6dsr(g_i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop: read and print sensor data every 100 ms */
    while (1) {
        rc = read_sensor_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz);
        if (rc != 0) {
            fprintf(stderr, "Error reading sensor data, exiting\n");
            i2cClose(g_i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("%d,%d,%d,%d,%d,%d\n", ax, ay, az, gx, gy, gz);
        fflush(stdout);

        gpioDelay(100000); /* 100 ms in microseconds */
    }

    /* Unreachable, but kept for completeness */
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

