#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

/* FXOS8700 I2C address (SA0 tied to GND) */
#define FXOS8700_I2C_ADDR 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_REG_STATUS       0x00
#define FXOS8700_REG_OUT_X_MSB    0x01
#define FXOS8700_REG_WHO_AM_I     0x0D
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E
#define FXOS8700_REG_CTRL_REG1    0x2A
#define FXOS8700_REG_M_CTRL_REG1  0x5B

/* Expected device ID */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 12-byte block starting at reg (auto-increment) */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block read(0x%02X, %zu) failed: got %zd (%s)\n",
                reg, len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Initialize the FXOS8700:
 *   WHO_AM_I  -> verify device identity
 *   CTRL_REG1 -> enable accelerometer, 100 Hz ODR (0x0E)
 *   M_CTRL_REG1 -> enable magnetometer, 100 Hz ODR (0x1F)
 *   XYZ_DATA_CFG -> accelerometer 14-bit, no FSR (0x00)
 */
static int fxos8700_init(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, FXOS8700_REG_WHO_AM_I, &who_am_i) != 0)
        return -1;

    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode first to allow configuration changes */
    if (i2c_write_reg8(fd, FXOS8700_REG_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Magnetometer: 100 Hz ODR, high-resolution mode */
    if (i2c_write_reg8(fd, FXOS8700_REG_M_CTRL_REG1, 0x1F) != 0)
        return -1;

    /* Accelerometer: 14-bit resolution, no FSR */
    if (i2c_write_reg8(fd, FXOS8700_REG_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    /* Active mode: 100 Hz ODR, accelerometer only */
    if (i2c_write_reg8(fd, FXOS8700_REG_CTRL_REG1, 0x0E) != 0)
        return -1;

    return 0;
}

/*
 * Read a 12-byte block:
 *   [A_X_MSB, A_X_LSB, A_X_LSB_EXT, A_Y_MSB, A_Y_LSB, A_Y_LSB_EXT,
 *    A_Z_MSB, A_Z_LSB, A_Z_LSB_EXT, M_X_MSB, M_X_LSB, M_X_LSB_EXT]
 * Accelerometer data is 14-bit left-aligned, 16-bit two's complement.
 * Magnetometer data is 16-bit two's complement.
 */
static int fxos8700_read_data(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                              int16_t *mx, int16_t *my, int16_t *mz)
{
    uint8_t buf[12];
    if (i2c_read_block(fd, FXOS8700_REG_OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    /* Accelerometer: 14-bit left-aligned, 16-bit two's complement */
    *ax = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    *ay = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    *az = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    /* Magnetometer: 16-bit two's complement */
    *mx = (int16_t)((buf[6] << 8) | buf[7]);
    *my = (int16_t)((buf[8] << 8) | buf[9]);
    *mz = (int16_t)((buf[10] << 8) | buf[11]);

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, FXOS8700_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (fxos8700_init(fd) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Reading data every 100 ms (Ctrl+C to stop)...\n");

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;
        if (fxos8700_read_data(fd, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read failed; retrying next cycle\n");
        }
        usleep(100000); /* 100 ms */
    }

    /* Return to standby before releasing */
    (void)i2c_write_reg8(fd, FXOS8700_REG_CTRL_REG1, 0x00);
    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

