#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_BW_RATE 0x2C
#define ADXL345_DATARATE_100HZ 0x0B
#define ADXL345_RANGE_2G 0x00
#define ADXL345_FULL_RES 0x08
#define ADXL345_MEASURE 0x08

#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_adxl345(int handle) {
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Could not disable measurement mode.\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, ADXL345_FULL_RES | ADXL345_RANGE_2G) < 0) {
        fprintf(stderr, "Error: Could not set data format.\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_BW_RATE, ADXL345_DATARATE_100HZ) < 0) {
        fprintf(stderr, "Error: Could not set data rate.\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, ADXL345_MEASURE) < 0) {
        fprintf(stderr, "Error: Could not enable measurement mode.\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 256.0;
    double y_g = (double)y / 256.0;
    double z_g = (double)z / 256.0;
    return atan2(sqrt(x_g * x_g + y_g * y_g), z_g) * 180.0 / M_PI;
}

static void log_tilt_event(double tilt_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: Tilt angle exceeded threshold: %.2f degrees\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, tilt_angle);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device.\n");
        gpioTerminate();
        return 1;
    }

    if (initialize_adxl345(i2c_handle) < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Tilt detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            double tilt_angle = calculate_tilt_angle(x, y, z);
            if (tilt_angle > TILT_THRESHOLD) {
                log_tilt_event(tilt_angle);
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data. Retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Tilt detection stopped.\n");
    return 0;
}

