#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define WINDOW_SECONDS 5
#define SAMPLE_DELAY_US 1000
#define PAUSE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

static int count_high_readings(int pin, int window_seconds) {
    int high_count = 0;
    int samples = window_seconds * 1000 / SAMPLE_DELAY_US;
    for (int i = 0; i < samples && running; i++) {
        int v = read_sensor(pin);
        if (v < 0) return -1;
        if (v == 1) high_count++;
        gpioDelay(SAMPLE_DELAY_US);
    }
    return high_count;
}

static void print_timestamp(void) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        printf("[%04d-%02d-%02d %02d:%02d:%02d] ",
               tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
               tm.tm_hour, tm.tm_min, tm.tm_sec);
    } else {
        printf("[unknown time] ");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    errno = 0;
    long threshold = strtol(argv[1], &endptr, 10);
    if (errno != 0 || endptr == argv[1] || *endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 on GPIO%d for %d seconds. Threshold: %ld\n",
           SENSOR_PIN, WINDOW_SECONDS, threshold);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int high_count = count_high_readings(SENSOR_PIN, WINDOW_SECONDS);
        if (high_count < 0) {
            fprintf(stderr, "Sensor read error during window.\n");
            break;
        }

        print_timestamp();
        if (high_count > threshold) {
            printf("ALERT: %d high readings in %d seconds (threshold %ld)\n",
                   high_count, WINDOW_SECONDS, threshold);
        } else {
            printf("Status: %d high readings in %d seconds (threshold %ld)\n",
                   high_count, WINDOW_SECONDS, threshold);
        }
        fflush(stdout);

        if (running) {
            gpioDelay(PAUSE_DELAY_US);
        }
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

