        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 on GPIO%d for %d seconds. Threshold: %ld\n",
           SENSOR_PIN, WINDOW_SECONDS, threshold);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
