/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Controls two 12 V electromagnetic door locks via TIP120 relays on the
 * GPIO bus.  Door A is on GPIO17 (BCM), Door B is on GPIO27 (BCM).
 *
 * Relay module: 5 V active-HIGH → locks energized, HIGH → de-energized → unlocked
 *
 * Build:  gcc -Wall -O2 -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define UNLOCK_MS   5000          /* 5 s door unlock duration */
#define LOG_FILE    "access_log.txt"
#define CODE_MIN    100000
#define CODE_MAX    999999
#define CODE_LEN    6
#define POLL_MS     100           /* poll interval for unlock timer */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int set_output(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "gpiod_line_set_value(%p, %d): %s\n",
                line, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Security code                                                       */
/* ------------------------------------------------------------------ */
static int generate_code(void)
{
    return (rand() % (CODE_MAX - CODE_MIN + 1)) + CODE_MIN;
}

static int read_code(void)
{
    char buf[CODE_LEN + 1];
    int  n;

    printf("Enter security code (%d-%d): ", CODE_MIN, CODE_MAX);
    fflush(stdout);

    if (fgets(buf, sizeof(buf), stdin) == NULL) {
        if (feof(stdin))
            return -1;                 /* EOF — normal exit */
        fprintf(stderr, "fgets: %s\n", strerror(errno));
        return -2;
    }

    /* Strip trailing newline */
    n = (int)strlen(buf);
    if (n > 0 && buf[n - 1] == '\n')
        buf[--n] = '\0';

    if (n != CODE_LEN) {
        fprintf(stderr, "Invalid input (%d digits).\n", n);
        return -3;
    }

    for (int i = 0; i < CODE_LEN; i++) {
        if (buf[i] < '0' || buf[i] > '9') {
            fprintf(stderr, "Invalid input (non-digit at position %d).\n", i + 1);
            return -3;
        }
    }

    return atoi(buf);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%06d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, code);

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Unlock                                                              */
/* ------------------------------------------------------------------ */
static int unlock_doors(struct gpiod_line *a, struct gpiod_line *b)
{
    printf("Unlocking doors for %d ms...\n", UNLOCK_MS);
    fflush(stdout);

    if (set_output(a, 1) != 0)
        return -1;
    if (set_output(b, 1) != 0)
        return -1;

    /* Sleep in 100 ms chunks so signals are caught promptly */
    for (int ms = 0; ms < UNLOCK_MS && g_running; ms += POLL_MS)
        usleep(POLL_MS * 1000);

    if (set_output(a, 0) != 0)
        return -1;
    if (set_output(b, 0) != 0)
        return -1;

    printf("Doors locked.\n");
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *a = NULL, *b = NULL;
    int rc = EXIT_FAILURE;

    srand((unsigned)time(NULL));

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fall back to the first chip on the bus */
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        goto cleanup;
    }

    a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!a || !b) {
        fprintf(stderr, "gpiod_chip_get_line: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(a, "door_access", 0) < 0) {
        fprintf(stderr, "request_output(a): %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(b, "door_access", 0) < 0) {
        fprintf(stderr, "request_output(b): %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Door access control started.\n");
    fflush(stdout);

    while (g_running) {
        int code = generate_code();
        printf("Generated code: %06d\n", code);
        fflush(stdout);

        int entered = read_code();
        if (entered == -1) {
            printf("Exiting.\n");
            break;
        }
        if (entered == -2) {
            fprintf(stderr, "Read error.\n");
            continue;
        }
        if (entered == -3) {
            fprintf(stderr, "Invalid input.\n");
            continue;
        }

        if (entered == code) {
            if (log_access(code) != 0)
                fprintf(stderr, "Warning: failed to log access.\n");
            if (unlock_doors(a, b) != 0)
                fprintf(stderr, "Warning: unlock_doors failed.\n");
        } else {
            fprintf(stderr, "Access denied.\n");
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Ensure doors are locked on every exit path */
    if (a) set_output(a, 0);
    if (b) set_output(b, 0);

    if (a) gpiod_line_release(a);
    if (b) gpiod_line_release(b);
    if (chip) gpiod_chip_close(chip);

    return rc;
}

