#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define BH1750_PWR_ON 0x01
#define BH1750_RESET 0x07
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define BH1750_CONV_TIME_MS 180
#define LOG_FILE "light_log.txt"
#define SAMPLE_INTERVAL_S 5

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int bh1750_write_cmd(int handle, uint8_t cmd) {
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "Error: Failed to write command 0x%02X to BH1750.\n", cmd);
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int handle, float *lux) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from BH1750 (got %d).\n", bytes);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", filename);
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, BH1750_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bh1750_write_cmd(i2c_handle, BH1750_PWR_ON) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);

    if (bh1750_write_cmd(i2c_handle, BH1750_RESET) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);

    if (bh1750_write_cmd(i2c_handle, BH1750_CONT_HIGH_RES_MODE) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    printf("Starting BH1750 light sensor logging. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float lux;
        if (bh1750_read_lux(i2c_handle, &lux) == 0) {
            if (log_data(LOG_FILE, lux) == 0) {
                printf("Lux: %.2f\n", lux);
            } else {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read lux value.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

