#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x50
#define PWM_PIN 18
#define SOUND_DURATION 5
#define SAMPLE_INTERVAL_US 20000
#define SERVER_PORT 12345
#define SHARED_SECRET "MySecretKey"
#define LOG_FILE "frequency_log.txt"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0 0x5E
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int server_fd = -1;
static int client_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_byte(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_byte(fd, MPR121_ELECONFIG0, 0x0C) < 0) return -1;
    gpioDelay(1000);

    for (int i = 0; i < 12; i++) {
        if (i2c_write_byte(fd, 0x41 + (i * 2), 0x30) < 0) return -1;
        if (i2c_write_byte(fd, 0x42 + (i * 2), 0x20) < 0) return -1;
    }
    return 0;
}

static int read_touch_data(int fd, uint16_t *touch_data) {
    uint8_t lo, hi;
    if (i2c_read_byte(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_byte(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *touch_data = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int detect_frequency(uint16_t touch_data, int *frequency) {
    static int prev_touch_data = 0;
    int current_touch_data = (int)touch_data;
    int delta = current_touch_data - prev_touch_data;
    if (delta != 0) {
        long freq_hz = 1000000000L / (long)delta;
        *frequency = (int)freq_hz;
        prev_touch_data = current_touch_data;
        return 1;
    }
    return 0;
}

static void play_tone(int frequency, int duration_seconds) {
    if (frequency > 0) {
        gpioSetPWMfrequency(PWM_PIN, frequency);
        gpioPWM(PWM_PIN, 128);
        gpioDelay(duration_seconds * 1000000);
        gpioPWM(PWM_PIN, 0);
    }
}

static void log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %d Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fclose(fp);
}

static int authenticate_client(int client_fd) {
    char buffer[1024];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n <= 0) {
        if (n < 0) fprintf(stderr, "recv failed: %s\n", strerror(errno));
        return -1;
    }
    buffer[n] = '\0';
    if (strncmp(buffer, "MOTION_DETECTED:", 16) != 0) {
        fprintf(stderr, "Authentication failed: Invalid message format\n");
        return -1;
    }
    if (strstr(buffer, SHARED_SECRET) == NULL) {
        fprintf(stderr, "Authentication failed: Invalid shared secret\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_close(i2c_fd);
        i2c_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = i2c_open(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        cleanup();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "setsockopt failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Bind failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Listen failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", SERVER_PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            fprintf(stderr, "Accept failed: %s\n", strerror(errno));
            continue;
        }

        if (authenticate_client(client_fd) < 0) {
            close(client_fd);
            continue;
        }

        printf("Client authenticated. Playing tone...\n");

        uint16_t touch_data;
        int frequency;
        struct timespec start, now;
        clock_gettime(CLOCK_MONOTONIC, &start);

        while (running) {
            if (read_touch_data(i2c_fd, &touch_data) < 0) {
                fprintf(stderr, "Failed to read touch data\n");
                break;
            }

            if (detect_frequency(touch_data, &frequency)) {
                play_tone(frequency, SOUND_DURATION);
                log_frequency(frequency);
            }

            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed = (now.tv_sec - start.tv_sec) + (now.tv_nsec - start.tv_nsec) / 1e9;
            if (elapsed >= SOUND_DURATION) break;

            gpioDelay(SAMPLE_INTERVAL_US);
        }

        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

