#include <signal.h>
#include <time.h>
#include <math.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define LSM303_ADDR     0x1E
#define CTRL_REG1_M     0x20
#define CTRL_REG2_M     0x21
#define CTRL_REG3_M     0x22
#define CTRL_REG4_M     0x23
#define OUT_X_L_M       0x28
#define LED_PIN         17
#define SAMPLE_US       100000
#define PWM_RANGE       100
#define PWM_FREQ        1000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_msg(const char *msg) {
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(g_log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log_fp);
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed (reg 0x%02X): %s", reg, strerror(errno));
        log_msg(msg);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write (reg select 0x%02X) failed: %s", reg, strerror(errno));
        log_msg(msg);
        return -1;
    }
    if (read(fd, buf, len) != len) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read (reg 0x%02X, %d bytes) failed: %s", reg, len, strerror(errno));
        log_msg(msg);
        return -1;
    }
    return 0;
}

static int init_magnetometer(void) {
    if (i2c_write_byte(g_i2c_fd, CTRL_REG1_M, 0x70) < 0) return -1;
    if (i2c_write_byte(g_i2c_fd, CTRL_REG2_M, 0x00) < 0) return -1;
    if (i2c_write_byte(g_i2c_fd, CTRL_REG3_M, 0x00) < 0) return -1;
    if (i2c_write_byte(g_i2c_fd, CTRL_REG4_M, 0x0C) < 0) return -1;
    return 0;
}

static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(g_i2c_fd, OUT_X_L_M, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(LED_PIN, brightness);
}

static void cleanup(void) {
    gpioPWM(LED_PIN, 0);
    gpioTerminate();
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        log_msg("Program terminated.");
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_log_fp = fopen("lsm303_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }
    log_msg("Program started.");

    if (gpioInitialise() < 0) {
        log_msg("pigpio initialisation failed");
        fclose(g_log_fp);
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open %s: %s", I2C_BUS, strerror(errno));
        log_msg(msg);
        cleanup();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to set I2C slave address 0x%02X: %s", LSM303_ADDR, strerror(errno));
        log_msg(msg);
        cleanup();
        return 1;
    }

    if (init_magnetometer() < 0) {
        log_msg("Magnetometer initialisation failed");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMrange(LED_PIN, PWM_RANGE);
    gpioSetPWMfrequency(LED_PIN, PWM_FREQ);

    while (g_running) {
        int16_t x, y, z;
        if (read_magnetometer(&x, &y, &z) == 0) {
            double mag = sqrt((double)x * x + (double)y * y + (double)z * z);
            int brightness = (int)(mag / 100.0 * PWM_RANGE);
            set_led_brightness(brightness);
        } else {
            log_msg("Error reading magnetometer data");
            set_led_brightness(0);
        }
        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return 0;
}

