#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

/* HMC5883L I2C address (AD0 tied to GND) */
#define HMC5883L_ADDR 0x1E

/* HMC5883L register addresses */
#define HMC5883L_CONFIG_A   0x00
#define HMC5883L_CONFIG_B   0x01
#define HMC5883L_MODE       0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08
#define HMC5883L_STATUS     0x09
#define HMC5883L_ID_A       0x0A
#define HMC5883L_ID_B       0x0B
#define HMC5883L_ID_C       0x0C

/* Configuration: 8-average, 15 Hz, normal measurement */
#define HMC5883L_CONFIG_A_VAL 0x70
/* Configuration B: 1090 Hz, gain 1.3 Gauss */
#define HMC5883L_CONFIG_B_VAL 0x20
/* Mode: continuous measurement */
#define HMC5883L_MODE_VAL     0x00

/* Number of samples for hard-iron calibration */
#define NUM_CALIBRATION_SAMPLES 100

/* Sampling interval in microseconds (500 ms) */
#define SAMPLE_INTERVAL_US 500000

/* Global I2C handle */
static int i2c_handle = -1;

/* Flag to indicate program termination */
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to an HMC5883L register */
static bool hmc5883l_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n",
                value, reg, rc);
        return false;
    }
    return true;
}

/* Read a single byte from an HMC5883L register */
static bool hmc5883l_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
        return false;
    }
    *value = (uint8_t)rc;
    return true;
}

/* Read 6 bytes of data (X, Z, Y) from the HMC5883L */
static bool hmc5883l_read_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading data block (rc=%d)\n", rc);
        return false;
    }
    *x = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *z = (int16_t)(((uint8_t)buf[2] << 8) | (uint8_t)buf[3]);
    *y = (int16_t)(((uint8_t)buf[4] << 8) | (uint8_t)buf[5]);
    return true;
}

/* Initialize the HMC5883L magnetometer */
static bool hmc5883l_init(void) {
    uint8_t id_a, id_b, id_c;

    /* Verify device identity */
    if (!hmc5883l_read_reg(HMC5883L_ID_A, &id_a)) return false;
    if (!hmc5883l_read_reg(HMC5883L_ID_B, &id_b)) return false;
    if (!hmc5883l_read_reg(HMC5883L_ID_C, &id_c)) return false;

    if (id_a != 0x48 || id_b != 0x34 || id_c != 0x33) {
        fprintf(stderr, "HMC5883L identification failed: ID_A=0x%02X ID_B=0x%02X ID_C=0x%02X\n",
                id_a, id_b, id_c);
        return false;
    }

    /* Configure registers */
    if (!hmc5883l_write_reg(HMC5883L_CONFIG_A, HMC5883L_CONFIG_A_VAL)) return false;
    if (!hmc5883l_write_reg(HMC5883L_CONFIG_B, HMC5883L_CONFIG_B_VAL)) return false;
    if (!hmc5883l_write_reg(HMC5883L_MODE, HMC5883L_MODE_VAL)) return false;

    return true;
}

/* Compute hard-iron offsets from a running average of calibration samples */
static void hmc5883l_calibrate(int16_t *x_offset, int16_t *y_offset, int16_t *z_offset) {
    int16_t x_sum = 0, y_sum = 0, z_sum = 0;
    int16_t x, y, z;

    printf("Calibrating HMC5883L (keep sensor still)...\n");
    for (int i = 0; i < NUM_CALIBRATION_SAMPLES; i++) {
        if (!hmc5883l_read_data(&x, &y, &z)) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            *x_offset = 0;
            *y_offset = 0;
            *z_offset = 0;
            return;
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        gpioDelay(10000); /* 10 ms between samples */
    }

    *x_offset = x_sum / NUM_CALIBRATION_SAMPLES;
    *y_offset = y_sum / NUM_CALIBRATION_SAMPLES;
    *z_offset = z_sum / NUM_CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%d, Y=%d, Z=%d\n",
           *x_offset, *y_offset, *z_offset);
}

int main(void) {
    int16_t x_offset = 0, y_offset = 0, z_offset = 0;
    int16_t x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the HMC5883L address */
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X (rc=%d)\n",
                HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the magnetometer */
    if (!hmc5883l_init()) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Calibrate the magnetometer */
    hmc5883l_calibrate(&x_offset, &y_offset, &z_offset);

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting data acquisition (Ctrl+C to stop)...\n");

    /* Main loop */
    while (!terminate) {
        if (!hmc5883l_read_data(&x, &y, &z)) {
            fprintf(stderr, "Read error, continuing...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Apply hard-iron offsets */
        int16_t x_corr = x - x_offset;
        int16_t y_corr = y - y_offset;
        int16_t z_corr = z - z_offset;

        printf("X: %6d, Y: %6d, Z: %6d\n", x_corr, y_corr, z_corr);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean up */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

