/*
 * LSM303D tri‑axial accelerometer monitor for Raspberry Pi Zero W.
 *
 * Reads acceleration (X/Y/Z) over I2C every 10 ms and stores each sample
 * in a 64-entry in‑memory circular buffer.  On a rising edge of the
 * INT1 pin (BCM GPIO 23, physical pin 16) dumps the last ten buffered
 * samples to stdout.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 * Run:    ./lsm303d_mon   (user must be in the 'i2c' group or have
 *                          appropriate /dev/i2c-1 permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D constants (datasheet) ---- */
#define LSM303D_ACCEL_ADDR  0x19
#define LSM303D_MAG_ADDR    0x1E

#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_VAL 0x49

#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_CTRL_REG4_A 0x23
#define LSM303D_CTRL_REG5_A 0x24
#define LSM303D_CTRL_REG6_A 0x25
#define LSM303D_CTRL_REG7_A 0x26
#define LSM303D_OUT_X_L_A   0x28

#define LSM303D_CTRL_REG1_M 0x20
#define LSM303D_CTRL_REG2_M 0x21
#define LSM303D_CTRL_REG3_M 0x22
#define LSM303D_OUT_X_H_M   0x22
#define LSM303D_OUT_X_L_M   0x23

#define LSM303D_INT1_CFG_A  0x30
#define LSM303D_INT1_SRC_A  0x31

#define ACCEL_SENSITIVITY   0.061f   /* mg/LSB  (±2 g full-scale) */

/* ---- Application constants ---- */
#define I2C_BUS            "/dev/i2c-1"
#define BUFFER_SIZE        64
#define SAMPLE_PERIOD_US   10000    /* 10 ms */
#define INT1_GPIO_LINE     23       /* BCM 23, physical pin 16 */
#define INT1_GPIO_CHIP     "gpiochip4" /* Pi Zero W BCM GPIO bank */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1_line = NULL;

/* ---- Circular buffer ---- */
typedef struct {
