#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

#define UART_PORT_1        "/dev/serial0"
#define UART_PORT_2        "/dev/serial1"
#define BAUD_RATE          9600
#define READ_TIMEOUT_SEC   5
#define RELAY_PIN_1        17
#define RELAY_PIN_2        27
#define EXPECTED_CODE      "123456"
#define RELAY_ON_DURATION  2
#define CODE_LENGTH        6
#define MAX_CODE_LENGTH    16

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_code(int handle, char *code, size_t max_len)
{
    char buf[16];
    int  n;
    int  i;

    memset(code, 0, max_len);

    for (i = 0; i < (int)max_len; i++) {
        n = serRead(handle, buf, 1);
        if (n < 0) {
            if (errno == EAGAIN) {
                return -1; /* timeout */
            }
            return -2; /* read error */
        }
        if (n == 0) {
            return -1; /* timeout */
        }

        if (buf[0] >= '0' && buf[0] <= '9') {
            code[i] = buf[0];
        } else {
            return -3; /* non-digit */
        }
    }
    return 0;
}

static int read_code_with_timeout(int handle, char *code, size_t max_len, int timeout_sec)
{
    time_t start = time(NULL);
    int    rc;

    while (g_running) {
        rc = read_code(handle, code, max_len);
        if (rc == 0) {
            return 0;
        }
        if (rc == -1) {
            if (time(NULL) - start >= (time_t)timeout_sec) {
                return -1;
            }
            continue;
        }
        return rc;
    }
    return -1;
}

static int constant_time_compare(const char *a, const char *b, size_t len)
{
    size_t i;
    unsigned char c1, c2;
    unsigned int diff = 0;

    for (i = 0; i < len; i++) {
        c1 = (unsigned char)a[i];
        c2 = (unsigned char)b[i];
        diff |= c1 ^ c2;
    }
    return (diff == 0) ? 0 : 1;
}

static int set_relay(int pin, int state)
{
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, state);
        return -1;
    }
    return 0;
}

static void cleanup(int h1, int h2)
{
    if (h1 >= 0) {
        serClose(h1);
    }
    if (h2 >= 0) {
        serClose(h2);
    }
    gpioWrite(RELAY_PIN_1, 0);
    gpioWrite(RELAY_PIN_2, 0);
    gpioTerminate();
}

int main(void)
{
    int  h1 = -1, h2 = -1;
    char code1[MAX_CODE_LENGTH + 1];
    char code2[MAX_CODE_LENGTH + 1];
    int  rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(RELAY_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        cleanup(h1, h2);
        return EXIT_FAILURE;
    }

    h1 = serOpen(UART_PORT_1, BAUD_RATE, 0);
    if (h1 < 0) {
        fprintf(stderr, "Error: serOpen(%s) failed: %s\n", UART_PORT_1, strerror(errno));
        cleanup(h1, h2);
        return EXIT_FAILURE;
    }

    h2 = serOpen(UART_PORT_2, BAUD_RATE, 0);
    if (h2 < 0) {
        fprintf(stderr, "Error: serOpen(%s) failed: %s\n", UART_PORT_2, strerror(errno));
        cleanup(h1, h2);
        return EXIT_FAILURE;
    }

    printf("Dual-factor door lock authentication started.\n");
    printf("  Port 1: %s @ %d baud\n", UART_PORT_1, BAUD_RATE);
    printf("  Port 2: %s @ %d baud\n", UART_PORT_2, BAUD_RATE);
    printf("  Relay 1: GPIO%d, Relay 2: GPIO%d\n", RELAY_PIN_1, RELAY_PIN_2);
    printf("  Expected code: %s\n", EXPECTED_CODE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        memset(code1, 0, sizeof(code1));
        memset(code2, 0, sizeof(code2));

        rc = read_code_with_timeout(h1, code1, MAX_CODE_LENGTH, READ_TIMEOUT_SEC);
        if (rc != 0) {
            if (rc == -1) {
                fprintf(stderr, "Warning: Port 1 timeout (%d s)\n", READ_TIMEOUT_SEC);
            } else {
                fprintf(stderr, "Warning: Port 1 read error (rc=%d)\n", rc);
            }
            continue;
        }

        rc = read_code_with_timeout(h2, code2, MAX_CODE_LENGTH, READ_TIMEOUT_SEC);
        if (rc != 0) {
            if (rc == -1) {
                fprintf(stderr, "Warning: Port 2 timeout (%d s)\n", READ_TIMEOUT_SEC);
            } else {
                fprintf(stderr, "Warning: Port 2 read error (rc=%d)\n", rc);
            }
            continue;
        }

        if (constant_time_compare(code1, code2, CODE_LENGTH) == 0) {
            printf("Codes match. Authorizing access...\n");
            if (set_relay(RELAY_PIN_1, 1) == 0 && set_relay(RELAY_PIN_2, 1) == 0) {
                sleep(RELAY_ON_DURATION);
                set_relay(RELAY_PIN_1, 0);
                set_relay(RELAY_PIN_2, 0);
                printf("Access granted. Relays deactivated.\n");
            } else {
                fprintf(stderr, "Error: Failed to activate relays.\n");
            }
        } else {
            fprintf(stderr, "Warning: Codes do not match.\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup(h1, h2);
    return EXIT_SUCCESS;
}

