 * PIR-triggered door-strike relay controller for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - HC-SR501 PIR sensor  -> physical GPIO4  (line 7, BCM 4)
 *   - Relay module         -> physical GPIO17 (line 11, BCM 17)
 *
 * Behavior:
 *   Polls the PIR every 50 ms.  When a motion event (PIR HIGH) is
 *   detected a syslog entry is logged and the relay is energized
 *   for 1 s.  If the PIR signal remains HIGH for more than 10 s the
 *   program triggers a failsafe: the relay is de-energized, a
 *   LOG_WARNING is logged, and a shutdown event is logged.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pir_door_strike pir_door_strike.c \
 *       -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN          4
#define RELAY_PIN        17
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define RELAY_ON_US      1000000 /* 1 s  */
#define FAILSAFE_THRESH_S 10

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *message)
{
    syslog(priority, "%s", message);
}

/* ------------------------------------------------------------------ */
static void cleanup_resources(struct gpiod_line *pir_line,
                              struct gpiod_line *relay_line,
                              struct gpiod_chip *chip)
{
    if (relay_line) {
        /* Ensure relay is de-energized before releasing the line. */
        if (gpiod_line_set_value(relay_line, 0) < 0)
            syslog(LOG_ERR, "Failed to de-energize relay during cleanup: %s",
                   strerror(errno));
        gpiod_line_release(relay_line);
    }
    if (pir_line)
        gpiod_line_release(pir_line);
    if (chip)
        gpiod_chip_close(chip);
    closelog();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("pir_door_strike", LOG_PID | LOG_CONS, LOG_USER);

    /* --- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        goto out;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        goto out;
    }

    /* --- Open the default gpiochip (gpiochip0 on Pi 4) --------------- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto out;
    }

    /* --- Get the PIR line ------------------------------------------ */
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line (GPIO%d): %s",
               PIR_PIN, strerror(errno));
        goto out;
    }

    /* --- Get the relay line ---------------------------------------- */
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line (GPIO%d): %s",
               RELAY_PIN, strerror(errno));
        goto out;
    }

    /* --- Request PIR as input -------------------------------------- */
    if (gpiod_line_request_input(pir_line, "pir_door_strike") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s",
               strerror(errno));
        goto out;
    }

    /* --- Request relay as output, initial value LOW ----------------- */
    if (gpiod_line_request_output(relay_line, "pir_door_strike", 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s",
               strerror(errno));
        goto out;
    }

    syslog(LOG_INFO, "PIR door-strike controller started (PIR=GPIO%d, Relay=GPIO%d)",
           PIR_PIN, RELAY_PIN);

    time_t motion_start = 0;
    int    relay_active = 0;

    /* --- Main polling loop ----------------------------------------- */
    while (g_running) {
        int pir_val = gpiod_line_get_value(pir_line);
        if (pir_val < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor: %s",
                   strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (pir_val == 1) {
            if (!relay_active) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    syslog(LOG_ERR, "Failed to energize relay: %s",
                           strerror(errno));
                } else {
                    relay_active = 1;
                    motion_start = time(NULL);
                    log_event(LOG_INFO, "Motion detected - relay energized");
                }
            }
        } else {
            if (relay_active) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to de-energize relay: %s",
                           strerror(errno));
                } else {
                    relay_active = 0;
                    log_event(LOG_INFO, "Relay de-energized");
                }
            }
        }

        /* Failsafe: if PIR stays HIGH for FAILSAFE_THRESH_S seconds
         * de-energize the relay and log a warning. */
        if (relay_active && pir_val == 1) {
            time_t now = time(NULL);
            if (difftime(now, motion_start) >= FAILSAFE_THRESH_S) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failsafe: failed to de-energize relay: %s",
                           strerror(errno));
                } else {
                    relay_active = 0;
                    log_event(LOG_WARNING,
                              "Failsafe: PIR signal stuck HIGH for 10 s - relay de-energized");
                    log_event(LOG_WARNING, "Shutting down due to malfunction");
                    g_running = 0;
                }
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    ret = EXIT_SUCCESS;

out:
    cleanup_resources(pir_line, relay_line, chip);
    return ret;
}

