#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <string.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ACTIVATION_TIME 300
#define RELAY_PAUSE_TIME 60
#define TIMER_INTERVAL 60

static volatile sig_atomic_t running = 1;

static const int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            log_message(LOG_ERR, "Failed to set GPIO mode");
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            log_message(LOG_ERR, "Failed to write to GPIO");
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < 4; i++) {
        gpioWrite(relay_pins[i], 1);
    }
}

static void activate_relay(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        log_message(LOG_ERR, "Failed to activate relay");
    } else {
        char message[128];
        snprintf(message, sizeof(message), "Relay on GPIO %d activated", pin);
        log_message(LOG_INFO, message);
    }
}

static void deactivate_relay(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        log_message(LOG_ERR, "Failed to deactivate relay");
    } else {
        char message[128];
        snprintf(message, sizeof(message), "Relay on GPIO %d deactivated", pin);
        log_message(LOG_INFO, message);
    }
}

static void timer_callback(void *user_data) {
    (void)user_data;
    static int relay_index = 0;
    static int timer_active = 0;

    if (!timer_active) {
        timer_active = 1;
        activate_relay(relay_pins[relay_index]);
        gpioSetTimerFuncEx(0, RELAY_ACTIVATION_TIME, NULL, NULL);
    }
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return 1;
    }

    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set timer");
        deactivate_all_relays();
        gpioTerminate();
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Irrigation system started");

    while (running) {
        sleep(1);
    }

    log_message(LOG_INFO, "Shutting down irrigation system");
    deactivate_all_relays();
    gpioSetTimerFuncEx(0, TIMER_INTERVAL, NULL, NULL);
    gpioTerminate();
    closelog();
    return 0;
}

