#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define ACCEL_XOUT_H   0x3B
#define PWR_MGMT_1     0x6B
#define SAMPLE_RATE_HZ 100
#define BUFFER_SIZE    100

#define DRIVER_DIR     "/sys/kernel/mpu6050_accel"
#define DRIVER_LATEST  DRIVER_DIR "/latest"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_latest_fp = NULL;
static int16_t *g_buffer = NULL;
static int g_buf_idx = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU6050 (PWR_MGMT_1)\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void buffer_add(int16_t x, int16_t y, int16_t z) {
    g_buffer[g_buf_idx] = x;
    g_buffer[g_buf_idx + 1] = y;
    g_buffer[g_buf_idx + 2] = z;
    g_buf_idx = (g_buf_idx + 3) % (BUFFER_SIZE * 3);
}

static void timer_handler(union sigval sv) {
    (void)sv;
    if (!g_running) return;

    int16_t x, y, z;
    if (read_accel(g_i2c_fd, &x, &y, &z) == 0) {
        buffer_add(x, y, z);

        if (g_latest_fp) {
            fseek(g_latest_fp, 0, SEEK_SET);
            fprintf(g_latest_fp, "%d,%d,%d", x, y, z);
            fflush(g_latest_fp);
        }
    }
}

static void cleanup(void) {
    if (g_latest_fp) {
        fclose(g_latest_fp);
        g_latest_fp = NULL;
    }
    if (g_buffer) {
        free(g_buffer);
        g_buffer = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed (sensor may be absent)\n");
        cleanup();
        return 1;
    }

    g_buffer = (int16_t *)malloc(BUFFER_SIZE * 3 * sizeof(int16_t));
    if (!g_buffer) {
        fprintf(stderr, "Failed to allocate %d-byte buffer\n", BUFFER_SIZE * 3 * (int)sizeof(int16_t));
        cleanup();
        return 1;
    }
    memset(g_buffer, 0, BUFFER_SIZE * 3 * sizeof(int16_t));

    g_latest_fp = fopen(DRIVER_LATEST, "w+");
    if (!g_latest_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", DRIVER_LATEST, strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(g_latest_fp, "0,0,0");
    fflush(g_latest_fp);

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    if (timer_create(CLOCK_MONOTONIC, &sev, NULL) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 1000000000L / SAMPLE_RATE_HZ;
    its.it_value = its.it_interval;
    if (timer_settime(0, 0, &its, NULL) < 0) {
        fprintf(stderr, "timer_settime failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU6050 sampling at %d Hz. Press Ctrl+C to stop.\n", SAMPLE_RATE_HZ);

    while (g_running) {
        pause();
    }

    printf("\nShutting down...\n");
    timer_delete(0, NULL);
    cleanup();
    return 0;
}

