            fflush(g_latest_fp);
        }
    }
}

static void cleanup(void) {
    if (g_latest_fp) {
        fclose(g_latest_fp);
        g_latest_fp = NULL;
    }
    if (g_buffer) {
        free(g_buffer);
        g_buffer = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed (sensor may be absent)\n");
        cleanup();
        return 1;
    }

    g_buffer = (int16_t *)malloc(BUFFER_SIZE * 3 * sizeof(int16_t));
    if (!g_buffer) {
        fprintf(stderr, "Failed to allocate %d-byte buffer\n", BUFFER_SIZE * 3 * (int)sizeof(int16_t));
        cleanup();
        return 1;
    }
    memset(g_buffer, 0, BUFFER_SIZE * 3 * sizeof(int16_t));

    g_latest_fp = fopen(DRIVER_LATEST, "w+");
    if (!g_latest_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", DRIVER_LATEST, strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(g_latest_fp, "0,0,0");
    fflush(g_latest_fp);

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    if (timer_create(CLOCK_MONOTONIC, &sev, NULL) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 1000000000L / SAMPLE_RATE_HZ;
    its.it_value = its.it_interval;
    if (timer_settime(0, 0, &its, NULL) < 0) {
        fprintf(stderr, "timer_settime failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU6050 sampling at %d Hz. Press Ctrl+C to stop.\n", SAMPLE_RATE_HZ);

    while (g_running) {
        pause();
    }

    printf("\nShutting down...\n");
    timer_delete(0, NULL);
    cleanup();
    return 0;
}

