#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define NUM_RELAYS 4

static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(int gpio_initialized) {
    if (gpio_initialized) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpioWrite(relay_pins[i], 0);
        }
        gpioTerminate();
    }
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise GPIO %d to LOW\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void toggle_relay(int pin) {
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return;
    }
    if (gpioWrite(pin, !level) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d\n", pin);
    }
}

static void sleep_seconds(int seconds) {
    struct timespec req = { .tv_sec = (time_t)seconds, .tv_nsec = 0 };
    struct timespec rem;
    while (nanosleep(&req, &rem) == -1 && errno == EINTR) {
        req = rem;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int gpio_initialized = setup_gpio();
    if (gpio_initialized != 0) {
        return EXIT_FAILURE;
    }

    const int intervals[NUM_RELAYS] = {2, 3, 5, 7};
    int current_relay = 0;

    while (running) {
        toggle_relay(relay_pins[current_relay]);
        printf("Relay %d toggled (pin %d)\n", current_relay + 1, relay_pins[current_relay]);
        fflush(stdout);

        sleep_seconds(intervals[current_relay]);
        if (!running) break;

        current_relay = (current_relay + 1) % NUM_RELAYS;
    }

    cleanup(gpio_initialized);
    return EXIT_SUCCESS;
}

