#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define RELAY_GPIO 27
#define POLL_INTERVAL_US 100000  /* 100 ms */
#define RELAY_ACTIVE_US 3000000  /* 3 s */
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sound detected on GPIO %d\n", timestamp, SOUND_SENSOR_GPIO) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay state on GPIO %d\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started on GPIO %d. Relay on GPIO %d. Press Ctrl+C to exit.\n",
           SOUND_SENSOR_GPIO, RELAY_GPIO);

    int relay_active = 0;

    while (program_running) {
        int sound_detected = gpioRead(SOUND_SENSOR_GPIO);
        if (sound_detected < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", SOUND_SENSOR_GPIO);
            break;
        }

        if (sound_detected == 1 && !relay_active) {
            if (gpioWrite(RELAY_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to activate relay on GPIO %d\n", RELAY_GPIO);
                break;
            }
            relay_active = 1;

            if (log_event(LOG_FILE) != 0) {
                fprintf(stderr, "Failed to log event to %s\n", LOG_FILE);
            }

            /* Debounce: wait for the sensor to return to idle */
            while (program_running) {
                int val = gpioRead(SOUND_SENSOR_GPIO);
                if (val < 0) {
                    fprintf(stderr, "gpioRead failed during debounce\n");
                    program_running = 0;
                    break;
                }
                if (val == 0) {
                    break;
                }
                gpioDelay(POLL_INTERVAL_US);
            }

            /* Ensure relay stays on for the full 3 s cooldown */
            if (program_running) {
                gpioDelay(RELAY_ACTIVE_US);
            }

            if (gpioWrite(RELAY_GPIO, 0) != 0) {
                fprintf(stderr, "Failed to deactivate relay on GPIO %d\n", RELAY_GPIO);
                break;
            }
            relay_active = 0;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

