/*
 * MH-Z19B CO2 monitor for Raspberry Pi 3 Model B+
 * UART: /dev/serial0 @ 9600 baud
 * TXD (GPIO14) -> sensor RX, RXD (GPIO15) -> sensor TX
 *
 * Reads CO2 ppm from the sensor and logs JSON lines to co2_log.json
 * and errors to co2_error.log.  SIGINT/SIGTERM cleanly close the
 * UART and release resources.
 *
 * Build:
 *   gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe_driver -lrt
 *
 * The driver library (libthe_driver.so) must be compiled and
 * installed separately.  This program uses only the public API
 * declared in the header.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>

#include "the_driver.h"

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define SAMPLE_INTERVAL  5          /* seconds between readings */
#define READ_TIMEOUT_MS  1000       /* 1 s max wait for sensor response */
#define MAX_RETRIES      5          /* retries per read cycle */
#define RESPONSE_LEN     9          /* MH-Z19B 9-byte response */

/* MH-Z19B 9-byte command to read CO2 ppm */
static const uint8_t CMD_READ_CO2[9] = {
    0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79
};

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_err_fp)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", t);
    else
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00+0000");

    fprintf(g_err_fp, "%s: %s\n", ts, msg);
    fflush(g_err_fp);
}

/* ------------------------------------------------------------------ */
/* UART helpers                                                        */
/* ------------------------------------------------------------------ */
static int uart_open(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    /* Clear O_NDELAY so reads block */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "fcntl F_SETFL: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    /* 9600 baud, 8N1, enable receiver */
    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 1;   /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int uart_write_full(int fd, const uint8_t *buf, size_t len)
{
    size_t off = 0;
    while (off < len) {
        ssize_t n = write(fd, buf + off, len - off);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        if (n == 0)
            return -1;
        off += (size_t)n;
    }
    return 0;
}

static int uart_read_full(int fd, uint8_t *buf, size_t len)
{
    size_t off = 0;
    while (off < len) {
        ssize_t n = read(fd, buf + off, len - off);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        if (n == 0)
            return -1;
        off += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CO2 reading                                                         */
/* ------------------------------------------------------------------ */
/*
 * Sends the 9-byte read command, waits for the 9-byte response,
 * verifies the checksum, and returns the CO2 ppm.
 *
 * Returns 0 on success, -1 on any error.
 */
static int read_co2(int fd, int *co2_ppm)
{
    uint8_t rx[RESPONSE_LEN];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (uart_write_full(fd, CMD_READ_CO2, sizeof(CMD_READ_CO2)) != 0) {
            log_error("UART write failed");
            return -1;
        }

        /* Wait for the full 9-byte response */
        struct timespec deadline;
        clock_gettime(CLOCK_MONOTONIC, &deadline);
        deadline.tv_sec  += READ_TIMEOUT_MS / 1000;
        deadline.tv_nsec += (READ_TIMEOUT_MS % 1000) * 1000000L;
        if (deadline.tv_nsec >= 1000000000L) {
            deadline.tv_sec  += deadline.tv_nsec / 1000000000L;
            deadline.tv_nsec %= 1000000000L;
        }

        int got = 0;
        while (got < RESPONSE_LEN) {
            ssize_t n = read(fd, rx + got, RESPONSE_LEN - got);
            if (n < 0) {
                if (errno == EINTR)
                    continue;
                log_error("UART read failed");
                return -1;
            }
            if (n == 0) {
                /* Timeout: no data within 1 s */
                if (++retries >= MAX_RETRIES) {
                    log_error("Timeout waiting for sensor response");
                    return -1;
                }
                break;
            }
            got += (int)n;
        }

        if (got < RESPONSE_LEN)
            continue;

        /* Verify checksum: 0xFF - (byte0 + byte1 + ... + byte7) */
        uint8_t checksum = 0;
        for (int i = 1; i < 8; i++)
            checksum += rx[i];
        checksum = 0xFF - checksum;

        if (checksum != rx[8]) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Checksum mismatch: calc=0x%02X recv=0x%02X",
                     checksum, rx[8]);
            log_error(msg);
            return -1;
        }

        /* Valid response: byte2..7 = CO2 ppm, big-endian */
        uint16_t ppm = ((uint16_t)rx[2] << 8) | rx[3];
        *co2_ppm = (int)ppm;
        return 0;
    }

    log_error("Max retries reached");
    return -1;
}

/* ------------------------------------------------------------------ */
/* JSON logging                                                        */
/* ------------------------------------------------------------------ */
static int log_json(FILE *fp, int co2_ppm, int error_flag)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", t);
    else
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00+0000");

    if (fprintf(fp,
                "{\"timestamp\":\"%s\",\"co2_ppm\":%d,\"error\":%d}\n",
                ts, co2_ppm, error_flag) < 0) {
        log_error("fprintf to log file failed");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open log files */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        fprintf(stderr, "fopen(%s): %s\n", ERROR_LOG_FILE, strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Open UART */
    g_uart_fd = uart_open(UART_DEVICE);
    if (g_uart_fd < 0) {
        fclose(g_log_fp);
        g_log_fp = NULL;
        fclose(g_err_fp);
        g_err_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO2 monitoring started on %s. Press Ctrl+C to exit.\n",
           UART_DEVICE);

    while (g_running) {
        int co2_ppm = 0;
        int rc = read_co2(g_uart_fd, &co2_ppm);

        if (rc == 0) {
            printf("CO2: %d ppm\n", co2_ppm);
            if (log_json(g_log_fp, co2_ppm, 0) != 0)
                fprintf(stderr, "Failed to log JSON\n");
        } else {
            fprintf(stderr, "Read failed; skipping sample\n");
            if (log_json(g_log_fp, 0, 1) != 0)
                fprintf(stderr, "Failed to log error JSON\n");
        }

        /* Sleep SAMPLE_INTERVAL seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

