#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define HEADING_DEVIATION_THRESHOLD 10.0
#define GPIO_PIN 17
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hmc5883l(void) {
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L config A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to HMC5883L config B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L mode\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

static float compensate_heading(float heading, float x_offset, float y_offset) {
    float x = heading - x_offset;
    float y = y_offset;
    float r = sqrtf(x * x + y * y);
    if (r > 0.0f) {
        x /= r;
        y /= r;
    }
    float compensated_heading = atan2f(y, x) * 180.0f / M_PI;
    if (compensated_heading < 0) {
        compensated_heading += 360.0f;
    }
    return compensated_heading;
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static void control_gpio(float heading, float target_heading) {
    float deviation = fabsf(heading - target_heading);
    if (deviation > 180.0f) {
        deviation = 360.0f - deviation;
    }
    if (deviation > HEADING_DEVIATION_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1);
    } else {
        gpioWrite(GPIO_PIN, 0);
    }
}

int main(void) {
    CircularBuffer heading_buffer = {0};
    float x_offset = 100.0f;
    float y_offset = -50.0f;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        int16_t x, y, z;
        if (read_magnetometer(&x, &y, &z) == 0) {
            float heading = calculate_heading(x, y);
            float compensated_heading = compensate_heading(heading, x_offset, y_offset);
            add_to_buffer(&heading_buffer, compensated_heading);
            control_gpio(compensated_heading, TARGET_HEADING);
        } else {
            fprintf(stderr, "Error reading magnetometer, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

