#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define BH1750_ADDR     0x23
#define BH1750_PWR_ON   0x01
#define BH1750_RESET    0x07
#define BH1750_ONE_TIME_HIGH_RES 0x20
#define BH1750_CONV_TIME_MS 120

#define RED_GPIO   17
#define GREEN_GPIO 27
#define BLUE_GPIO  22

#define LOG_FILE "lighting_log.txt"
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_RESET) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    if (i2c_write_byte(fd, BH1750_ONE_TIME_HIGH_RES) < 0) return -1;
    usleep(BH1750_CONV_TIME_MS * 1000);

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relays(float lux) {
    int r = (lux < 50.0f) ? 1 : 0;
    int g = (lux >= 50.0f && lux < 150.0f) ? 1 : 0;
    int b = (lux >= 150.0f && lux < 300.0f) ? 1 : 0;
    int a = (lux >= 300.0f) ? 1 : 0;

    gpioWrite(RED_GPIO, r);
    gpioWrite(GREEN_GPIO, g);
    gpioWrite(BLUE_GPIO, b);

    if (a) {
        gpioWrite(RED_GPIO, 1);
        gpioWrite(GREEN_GPIO, 1);
        gpioWrite(BLUE_GPIO, 1);
    }
}

static void log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_fp, "%s, %.2f\n", ts, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    fflush(log_fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return 1;
    }
    gpioWrite(RED_GPIO, 0);
    gpioWrite(GREEN_GPIO, 0);
    gpioWrite(BLUE_GPIO, 0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Lighting control started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            control_relays(lux);
            log_data(lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Sensor read error; keeping previous state.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

