        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (safe_set_mode(IN1, PI_OUTPUT) < 0 ||
        safe_set_mode(IN2, PI_OUTPUT) < 0 ||
        safe_set_mode(IN3, PI_OUTPUT) < 0 ||
        safe_set_mode(IN4, PI_OUTPUT) < 0 ||
        safe_set_mode(LOCK_BUTTON, PI_INPUT) < 0 ||
        safe_set_mode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        return -1;
    }

    if (safe_set_pull(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        safe_set_pull(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        return -1;
    }

    /* Ensure coils start de-energized */
    if (safe_write(IN1, 0) < 0 ||
        safe_write(IN2, 0) < 0 ||
        safe_write(IN3, 0) < 0 ||
        safe_write(IN4, 0) < 0) {
        return -1;
    }

    return 0;
}

static void deenergize_coils(void) {
    (void)gpioWrite(IN1, 0);
    (void)gpioWrite(IN2, 0);
    (void)gpioWrite(IN3, 0);
    (void)gpioWrite(IN4, 0);
}

static void step_motor(int direction) {
    static int step_index = 0;

    const int *current_step = step_sequence[step_index];

    if (safe_write(IN1, current_step[0]) < 0 ||
        safe_write(IN2, current_step[1]) < 0 ||
        safe_write(IN3, current_step[2]) < 0 ||
        safe_write(IN4, current_step[3]) < 0) {
        return;
    }

    step_index += direction;
    if (step_index < 0) step_index = 3;
    if (step_index > 3) step_index = 0;

    gpioDelay(STEP_DELAY_US);
}

static void lock_door(void) {
    printf("Locking door...\n");
    for (int i = 0; i < STEPS_PER_TURN && running; i++) {
        step_motor(1);
    }
    printf("Door locked.\n");
}

static void unlock_door(void) {
    printf("Unlocking door...\n");
    for (int i = 0; i < STEPS_PER_TURN && running; i++) {
        step_motor(-1);
    }
    printf("Door unlocked.\n");
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        deenergize_coils();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            /* Active-low: button pressed reads 0 */
            lock_door();
            /* Wait for button release to avoid re-triggering */
            while (running && gpioRead(LOCK_BUTTON) == 0) {
                gpioDelay(10000); /* 10 ms poll */
            }
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            /* Active-low: button pressed reads 0 */
            unlock_door();
            /* Wait for button release to avoid re-triggering */
            while (running && gpioRead(UNLOCK_BUTTON) == 0) {
                gpioDelay(10000);
            }
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    deenergize_coils();
    gpioTerminate();
    printf("Door lock system stopped.\n");

    return EXIT_SUCCESS;
}

