#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

#define SERVO_PWM_CHIP 2
#define SERVO_PWM_NUM 0
#define SERVO_PWM_PERIOD_NS 20000000
#define SERVO_PWM_RANGE 1000000

#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int init_mpu6050() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return -1;
    }

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        perror("Failed to wake up MPU6050");
        close(fd);
        return -1;
    }

    return fd;
}

int read_mpu6050_data(int fd, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    if (i2c_read_bytes(fd, ACCEL_XOUT_H, buf, 14) < 0) {
        return -1;
    }

    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

void calculate_pitch_roll(int16_t ax, int16_t ay, int16_t az, float *pitch, float *roll) {
    float accel_x = (float)ax / 16384.0;
    float accel_y = (float)ay / 16384.0;
    float accel_z = (float)az / 16384.0;

    *pitch = atan2(accel_y, accel_z) * 180.0 / M_PI;
    *roll = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180.0 / M_PI;
}

int init_pwm() {
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", SERVO_PWM_CHIP, SERVO_PWM_NUM);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM period");
        return -1;
    }
    if (write(fd, "20000000", 8) != 8) {
        perror("Failed to set PWM period");
        close(fd);
        return -1;
    }
    close(fd);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", SERVO_PWM_CHIP, SERVO_PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM duty_cycle");
        return -1;
    }
    if (write(fd, "0", 1) != 1) {
        perror("Failed to set PWM duty_cycle");
        close(fd);
        return -1;
    }
    close(fd);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", SERVO_PWM_CHIP, SERVO_PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM enable");
        return -1;
    }
    if (write(fd, "1", 1) != 1) {
        perror("Failed to enable PWM");
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

void set_servo_angle(int angle) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", SERVO_PWM_CHIP, SERVO_PWM_NUM);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM duty_cycle");
        return;
    }

    int duty_cycle = (int)((angle / 180.0) * SERVO_PWM_RANGE);
    char value[16];
    int len = snprintf(value, sizeof(value), "%d", duty_cycle);
    if (write(fd, value, len) != len) {
        perror("Failed to set PWM duty_cycle");
    }
    close(fd);
}

int log_data(float pitch, float roll, int position) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, position);
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = init_mpu6050();
    if (i2c_fd < 0) {
        fprintf(stderr, "MPU6050 initialization failed. Exiting.\n");
        return 1;
    }

    if (init_pwm() < 0) {
        fprintf(stderr, "PWM initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    int16_t ax, ay, az, gx, gy, gz;
    float pitch, roll;
    int position;

    while (running) {
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && !success) {
            if (read_mpu6050_data(i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
                success = 1;
            } else {
                retries++;
                usleep(100000 * retries);
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read MPU6050 data after %d retries. Exiting.\n", MAX_RETRIES);
            break;
        }

        calculate_pitch_roll(ax, ay, az, &pitch, &roll);

        position = (int)roll;
        if (position < 0) position = 0;
        if (position > 180) position = 180;

        set_servo_angle(position);

        if (log_data(pitch, roll, position) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        usleep(100000);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (pwm_fd >= 0) {
        char path[256];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", SERVO_PWM_CHIP, SERVO_PWM_NUM);
        int fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
    }

    return 0;
}

