#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_LAMPS 4
#define FADE_DURATION 1800
#define FADE_STEPS 100
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int lamp_gpios[NUM_LAMPS] = {4, 17, 27, 22};
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (gpioSetMode(lamp_gpios[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", lamp_gpios[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(lamp_gpios[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d to LOW.\n", lamp_gpios[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int set_lamp(int lamp_index, int on) {
    if (lamp_index < 0 || lamp_index >= NUM_LAMPS) {
        fprintf(stderr, "Error: invalid lamp index %d.\n", lamp_index);
        return -1;
    }
    if (gpioWrite(lamp_gpios[lamp_index], on ? 1 : 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", lamp_gpios[lamp_index]);
        return -1;
    }
    return 0;
}

static int read_schedule(time_t *sunrise_time, time_t *sunset_time) {
    FILE *fp = fopen(SCHEDULE_FILE, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int found_sunrise = 0, found_sunset = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        char *newline = strchr(line, '\n');
        if (newline) *newline = '\0';

        char *token = strtok(line, ",");
        if (token == NULL) continue;

        char *colon = strchr(token, ':');
        if (colon == NULL) continue;
        *colon = '\0';

        char *ampm = strchr(token, ' ');
        if (ampm != NULL) *ampm = '\0';

        int hour, minute, second;
        if (sscanf(token, "%d:%d:%d", &hour, &minute, &second) != 3) {
            fprintf(stderr, "Warning: invalid time format in line: %s\n", line);
            continue;
        }

        token = strtok(NULL, ",");
        if (token == NULL) continue;

        int lamp_index = atoi(token);
        if (lamp_index < 0 || lamp_index >= NUM_LAMPS) {
            fprintf(stderr, "Warning: invalid lamp index %d in line: %s\n", lamp_index, line);
            continue;
        }

        token = strtok(NULL, ",");
        if (token == NULL) continue;

        if (strcmp(token, "on") == 0) {
            if (hour == 0 && minute == 0 && second == 0) {
                found_sunrise = 1;
                *sunrise_time = (time_t)(hour * 3600 + minute * 60 + second);
            } else if (hour == 12 && minute == 0 && second == 0) {
                found_sunset = 1;
                *sunset_time = (time_t)(hour * 3600 + minute * 60 + second);
            }
        }
    }

    fclose(fp);

    if (!found_sunrise || !found_sunset) {
        fprintf(stderr, "Error: schedule file must contain sunrise and sunset entries.\n");
        return -1;
    }
    return 0;
}

static int calculate_brightness(time_t current_time, time_t sunrise_time, time_t sunset_time) {
    if (current_time < sunrise_time || current_time > sunset_time) {
        return 0;
    }
    double fraction = (double)(current_time - sunrise_time) / (double)(sunset_time - sunrise_time);
    return (int)(fraction * 100.0);
}

