#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM          2.0
#define MAX_DISTANCE_CM          400.0
#define MIN_FREQUENCY_HZ         200
#define MAX_FREQUENCY_HZ         8000
#define MIN_GAP_MS               60
#define LOOP_DELAY_US            20000
#define TRIGGER_PULSE_US         10
#define ECHO_TIMEOUT_US          30000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    trigger_sensor();

    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo pin stuck low (sensor absent or wiring fault).\n");
            return -1.0;
        }
    }

    end_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo pin timeout (sensor not responding).\n");
            return -1.0;
        }
    }

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (double)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: Distance out of range (%.2f cm).\n", distance);
        return -1.0;
    }

    return distance;
}

static int calculate_frequency(double distance) {
    double frequency = (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
                       (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
                       (distance - MIN_DISTANCE_CM) + MIN_FREQUENCY_HZ;

    if (frequency < MIN_FREQUENCY_HZ) frequency = MIN_FREQUENCY_HZ;
    if (frequency > MAX_FREQUENCY_HZ) frequency = MAX_FREQUENCY_HZ;

    return (int)(frequency + 0.5);
}

static void set_buzzer_frequency(int frequency) {
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency to %d Hz.\n", frequency);
        return;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {
        fprintf(stderr, "Error: Failed to start PWM on buzzer pin.\n");
    }
}

static void cleanup(void) {
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set echo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set buzzer pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    uint32_t last_measurement_tick = 0;

    while (running) {
        double distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: Invalid distance reading. Skipping buzzer update.\n");
        } else {
            int frequency = calculate_frequency(distance);
            set_buzzer_frequency(frequency);
        }

        uint32_t current_tick = gpioTick();
        if (last_measurement_tick != 0) {
            uint32_t elapsed = current_tick - last_measurement_tick;
            if (elapsed < MIN_GAP_MS * 1000) {
                gpioDelay(MIN_GAP_MS * 1000 - elapsed);
            }
        }
        last_measurement_tick = current_tick;

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

