#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

#define BUTTON_GPIO 17
#define BUZZER_GPIO 18
#define DEBOUNCE_US 50000
#define PWM_RANGE 1000
#define PWM_DUTY_50 500

static const int melody[][2] = {
    {262, 200}, {294, 200}, {330, 200}, {349, 200},
    {392, 200}, {440, 200}, {494, 200}, {523, 200},
    {0, 500}
};
static const int melody_len = sizeof(melody) / sizeof(melody[0]);

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t play_requested = 0;
static volatile sig_atomic_t play_stop_requested = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)tick; (void)user;
    if (level == 0) {
        play_requested = 1;
    }
}

static int play_melody(void) {
    for (int i = 0; i < melody_len && running; i++) {
        if (play_stop_requested) {
            play_stop_requested = 0;
            break;
        }
        int freq = melody[i][0];
        int dur  = melody[i][1];
        if (freq > 0) {
            if (gpioSetPWMfrequency(BUZZER_GPIO, freq) < 0) {
                fprintf(stderr, "Error: gpioSetPWMfrequency failed for freq %d\n", freq);
                return -1;
            }
            if (gpioPWM(BUZZER_GPIO, PWM_DUTY_50) < 0) {
                fprintf(stderr, "Error: gpioPWM start failed\n");
                return -1;
            }
        }
        gpioDelay(dur * 1000);
        if (freq > 0) {
            if (gpioPWM(BUZZER_GPIO, 0) < 0) {
                fprintf(stderr, "Error: gpioPWM stop failed\n");
                return -1;
            }
        }
        gpioDelay(DEBOUNCE_US);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BUZZER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(BUZZER_GPIO, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, DEBOUNCE_US, button_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed\n");
        gpioPWM(BUZZER_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, DEBOUNCE_US, NULL, NULL);
        gpioPWM(BUZZER_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed\n");
        gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, DEBOUNCE_US, NULL, NULL);
        gpioPWM(BUZZER_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Doorbell ready. Press the button (GPIO17) to play the melody.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (play_requested) {
            play_requested = 0;
            play_stop_requested = 0;
            if (play_melody() < 0) {
                fprintf(stderr, "Melody playback error.\n");
            }
        }
        gpioDelay(10000);
    }

    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, DEBOUNCE_US, NULL, NULL);
    gpioPWM(BUZZER_GPIO, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

