#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define DEFAULT_POLL_TIMEOUT_MS 1000
#define LOG_FILE "vibration_events.log"

typedef struct {
    time_t timestamp;
    int value;
} VibrationEvent;

static VibrationEvent event_window[WINDOW_SIZE];
static int window_index = 0;
static int window_count = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_event(time_t timestamp, int value) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    struct tm tm_info;
    char time_str[32];
    if (localtime_r(&timestamp, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %d\n", time_str, value) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }
    return 0;
}

static int check_threshold(void) {
    int high_count = 0;
    for (int i = 0; i < window_count; i++) {
        if (event_window[i].value == 1) {
            high_count++;
        }
    }
    return (high_count >= 3) ? 1 : 0;
}

static void process_event(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return;
    }

    if (log_event(now, level) != 0) {
        fprintf(stderr, "Error: Failed to log event.\n");
    }

    event_window[window_index].timestamp = now;
    event_window[window_index].value = level;
    window_index = (window_index + 1) % WINDOW_SIZE;
    if (window_count < WINDOW_SIZE) {
        window_count++;
    }

    if (check_threshold()) {
        struct tm tm_info;
        char time_str[32];
        if (localtime_r(&now, &tm_info) == NULL) {
            fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
            return;
        }
        if (strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
            fprintf(stderr, "Error: strftime failed.\n");
            return;
        }
        printf("EARTHQUAKE ALERT! Timestamp: %s\n", time_str);
        fflush(stdout);
    }
}

int main(int argc, char *argv[]) {
    int poll_timeout = DEFAULT_POLL_TIMEOUT_MS;

    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val <= 0 || val > 10000) {
            fprintf(stderr, "Error: Invalid poll timeout '%s'. Using default %d ms.\n",
                    argv[1], DEFAULT_POLL_TIMEOUT_MS);
        } else {
            poll_timeout = (int)val;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", GPIO_PIN);
