#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LSM303DLHC magnetometer I2C 7-bit address (SA0 tied to GND) */
#define LSM303_MAG_ADDR 0x3C

/* LSM303DLHC magnetometer registers */
#define LSM303_MAG_CRA_REG_M  0x00
#define LSM303_MAG_CRB_REG_M  0x01
#define LSM303_MAG_MR_REG_M   0x02
#define LSM303_MAG_OUT_X_H_M  0x03
#define LSM303_MAG_OUT_X_L_M  0x04
#define LSM303_MAG_OUT_Z_H_M  0x05
#define LSM303_MAG_OUT_Z_L_M  0x06
#define LSM303_MAG_OUT_Y_H_M  0x07
#define LSM303_MAG_OUT_Y_L_M  0x08
#define LSM303_MAG_SR_REG_M   0x09
#define LSM303_MAG_IRA_REG_M  0x0A
#define LSM303_MAG_IRB_REG_M  0x0B
#define LSM303_MAG_IRC_REG_M  0x0C

/* Calibration offsets (replace with your measured values) */
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

/* I2C bus device path */
#define I2C_DEV "/dev/i2c-1"

/* Sampling interval */
#define SAMPLE_INTERVAL_SEC 1

/* Globals for cleanup */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (out == NULL) {
        return -1;
    }
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    if (out == NULL) {
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Magnetometer initialization                                         */
/* ------------------------------------------------------------------ */
static int init_magnetometer(int fd)
{
    /* CRA: temp sensor, 100 Hz output rate, ultra-high perf */
    if (i2c_write_reg8(fd, LSM303_MAG_CRA_REG_M, 0x10) < 0) {
        return -1;
    }
    /* CRB: gain = 1.3 Gauss */
    if (i2c_write_reg8(fd, LSM303_MAG_CRB_REG_M, 0x20) < 0) {
        return -1;
    }
    /* MR: continuous conversion mode */
    if (i2c_write_reg8(fd, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read calibrated magnetic field data                                 */
/* ------------------------------------------------------------------ */
static int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, LSM303_MAG_OUT_X_H_M, x) < 0) return -1;
    if (i2c_read_reg16(fd, LSM303_MAG_OUT_Y_H_M, y) < 0) return -1;
    if (i2c_read_reg16(fd, LSM303_MAG_OUT_Z_H_M, z) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibrate raw data                                                  */
/* ------------------------------------------------------------------ */
static void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                           int16_t *cal_x, int16_t *cal_y, int16_t *cal_z)
{
    *cal_x = raw_x - X_OFFSET;
    *cal_y = raw_y - Y_OFFSET;
    *cal_z = raw_z - Z_OFFSET;
}

/* ------------------------------------------------------------------ */
/* Calculate heading in degrees                                        */
/* ------------------------------------------------------------------ */
static double calculate_heading(int16_t cal_x, int16_t cal_y)
{
    double heading = atan2((double)cal_y, (double)cal_x) * 180.0 / M_PI;
    if (heading < 0.0) {
        heading += 360.0;
    }
    return heading;
}

/* ------------------------------------------------------------------ */
/* Map heading to compass direction                                    */
/* ------------------------------------------------------------------ */
static const char *map_heading_to_direction(double heading)
{
    if (heading >= 337.5 || heading < 22.5)  return "N";
    if (heading >= 22.5  && heading < 67.5)  return "NE";
    if (heading >= 67.5  && heading < 112.5) return "E";
    if (heading >= 112.5 && heading < 157.5) return "SE";
    if (heading >= 157.5 && heading < 202.5) return "S";
    if (heading >= 202.5 && heading < 247.5) return "SW";
    if (heading >= 247.5 && heading < 292.5) return "W";
    return "NW";
}

/* ------------------------------------------------------------------ */
/* Log data to CSV                                                     */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int16_t cal_x, int16_t cal_y, int16_t cal_z,
                    double heading, const char *direction)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s, %d, %d, %d, %.2f, %s\n",
                timestamp, cal_x, cal_y, cal_z, heading, direction) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    /* Initialize magnetometer */
    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        cleanup();
        return 1;
    }

    /* Open log file (append mode) */
    g_log_file = fopen("mag_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open mag_log.csv: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading, Direction\n");
        fflush(g_log_file);
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        int16_t cal_x, cal_y, cal_z;
        double heading;
        const char *direction;

        if (read_magnetometer_data(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Error reading magnetometer data, skipping sample\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
        heading = calculate_heading(cal_x, cal_y);
        direction = map_heading_to_direction(heading);

        if (log_data(g_log_file, cal_x, cal_y, cal_z, heading, direction) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        printf("Calibrated X: %d, Calibrated Y: %d, Calibrated Z: %d, Heading: %.2f°, Direction: %s\n",
               cal_x, cal_y, cal_z, heading, direction);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return 0;
}

