    if (heading >= 202.5 && heading < 247.5) return "SW";
    if (heading >= 247.5 && heading < 292.5) return "W";
    return "NW";
}

/* ------------------------------------------------------------------ */
/* Log data to CSV                                                     */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int16_t cal_x, int16_t cal_y, int16_t cal_z,
                    double heading, const char *direction)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s, %d, %d, %d, %.2f, %s\n",
                timestamp, cal_x, cal_y, cal_z, heading, direction) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    /* Initialize magnetometer */
    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        cleanup();
        return 1;
    }

    /* Open log file (append mode) */
    g_log_file = fopen("mag_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open mag_log.csv: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading, Direction\n");
        fflush(g_log_file);
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        int16_t cal_x, cal_y, cal_z;
        double heading;
        const char *direction;

        if (read_magnetometer_data(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Error reading magnetometer data, skipping sample\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
        heading = calculate_heading(cal_x, cal_y);
        direction = map_heading_to_direction(heading);

        if (log_data(g_log_file, cal_x, cal_y, cal_z, heading, direction) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        printf("Calibrated X: %d, Calibrated Y: %d, Calibrated Z: %d, Heading: %.2f°, Direction: %s\n",
               cal_x, cal_y, cal_z, heading, direction);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return 0;
}

