#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 200000  /* 200 ms in microseconds */
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static volatile uint32_t last_touch_tick = 0;
static volatile int relay_state = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a JSON state entry to the log file                           */
/* ------------------------------------------------------------------ */
static int log_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp,
            "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n",
            ts, state ? "ON" : "OFF");

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control with safe pigpio calls                               */
/* ------------------------------------------------------------------ */
static int control_relay(int state)
{
    if (gpioWrite(RELAY_PIN, state) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, %d) failed\n", state);
        return -1;
    }
    relay_state = state;
    return 0;
}

/* ------------------------------------------------------------------ */
/* ISR — runs in pigpio callback thread                                */
/* ------------------------------------------------------------------ */
static void touch_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1)            /* only rising edge */
        return;

    uint32_t elapsed;
    if (tick >= last_touch_tick)
        elapsed = tick - last_touch_tick;
    else
        elapsed = (0xFFFFFFFFu - last_touch_tick) + tick + 1u;

    if (elapsed < DEBOUNCE_DELAY_US)
        return;

    last_touch_tick = tick;

    int new_state = !relay_state;
    if (control_relay(new_state) != 0)
        return;

    if (log_state(new_state) != 0)
        fprintf(stderr, "Warning: failed to log state\n");
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- touch sensor pin ---- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- relay pin ---- */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (control_relay(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ISR ---- */
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0,
                         touch_isr, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (running)
        gpioDelay(100000);  /* 100 ms */

    /* ---- cleanup ---- */
    printf("\nShutting down...\n");
    if (control_relay(0) != 0)
        fprintf(stderr, "Warning: failed to turn off relay during cleanup\n");
    if (log_state(0) != 0)
        fprintf(stderr, "Warning: failed to log final state\n");

    gpioTerminate();
    return EXIT_SUCCESS;
}

