#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define MOISTURE_THRESHOLD 30
#define RELAY_ACTIVE_TIME_US 5000000   /* 5 seconds in microseconds */
#define RELAY_GAP_TIME_US    1000000   /* 1 second in microseconds  */
#define SAMPLE_INTERVAL_US   10000000  /* 10 seconds in microseconds */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

static const int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void deactivate_all_relays(void)
{
    for (int i = 0; i < 4; i++)
        gpioWrite(relay_pins[i], 1);
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialise GPIO %d high.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int activate_relay(int pin, int relay_number)
{
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: failed to activate relay %d (GPIO %d).\n", relay_number, pin);
        return -1;
    }
    return 0;
}

static int deactivate_relay(int pin, int relay_number)
{
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: failed to deactivate relay %d (GPIO %d).\n", relay_number, pin);
        return -1;
    }
    return 0;
}

static int log_irrigation_event(int relay_number, int moisture_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file.\n");
        return -1;
    }

    return 0;
}

static int irrigate(int relay_number, int moisture_level)
{
    if (activate_relay(relay_pins[relay_number - 1], relay_number) != 0)
        return -1;

    if (log_irrigation_event(relay_number, moisture_level) != 0) {
        deactivate_relay(relay_pins[relay_number - 1], relay_number);
        return -1;
    }

    gpioDelay(RELAY_ACTIVE_TIME_US);

    if (deactivate_relay(relay_pins[relay_number - 1], relay_number) != 0)
        return -1;

    gpioDelay(RELAY_GAP_TIME_US);
    return 0;
}

int main(void)
{
    int seeded = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0)
        return EXIT_FAILURE;

    g_log_file = fopen("irrigation_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening irrigation_log.txt");
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));
    seeded = 1;

    while (g_running) {
        int moisture = rand() % 101;

        for (int i = 0; i < 4 && g_running; i++) {
            if (moisture < MOISTURE_THRESHOLD) {
                if (irrigate(i + 1, moisture) != 0)
                    fprintf(stderr, "Warning: irrigation sequence failed for relay %d.\n", i + 1);
            }
        }

        if (g_running)
            gpioDelay(SAMPLE_INTERVAL_US);
    }

    deactivate_all_relays();
    gpioTerminate();

    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0)
            perror("Error closing log file");
        g_log_file = NULL;
    }

    if (seeded)
        printf("Smart irrigation system stopped.\n");

    return EXIT_SUCCESS;
}

