        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));
    seeded = 1;

    while (g_running) {
        int moisture = rand() % 101;

        for (int i = 0; i < 4 && g_running; i++) {
            if (moisture < MOISTURE_THRESHOLD) {
                if (irrigate(i + 1, moisture) != 0)
                    fprintf(stderr, "Warning: irrigation sequence failed for relay %d.\n", i + 1);
            }
        }

        if (g_running)
            gpioDelay(SAMPLE_INTERVAL_US);
    }

    deactivate_all_relays();
    gpioTerminate();

    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0)
            perror("Error closing log file");
        g_log_file = NULL;
    }

    if (seeded)
        printf("Smart irrigation system stopped.\n");

    return EXIT_SUCCESS;
}

