/*
 * Automated Plant Watering System — Raspberry Pi Zero W
 *
 * Hardware:
 *   - SG90 valve servo on GPIO17 (BCM)
 *   - SG90 nozzle servo on GPIO18 (BCM)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o watering watering.c -lthe driver library -lrt
 *
 * The driver library is assumed to provide the following:
 *   int gpioInitialise(void)
 *   int gpioServo(int pin, int pulsewidth)
 *   int gpioTerminate(void)
 *
 * The SG90 pulse widths are in microseconds: 500–2500 for 0–180 degrees.
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define VALVE_PIN    17
#define NOZZLE_PIN   18

#define VALVE_OPEN_PW  1500   /* 90 degrees  */
#define VALVE_CLOSE_PW 500    /* 0 degrees    */

#define NOZZLE_ANGLES_COUNT 5
static const int nozzle_angles[NOZZLE_ANGLES_COUNT] = {0, 45, 90, 135, 180};
static const int nozzle_pws[NOZZLE_ANGLES_COUNT]    = {500, 1000, 1500, 2000, 2500};

#define MOISTURE_THRESHOLD 50
#define WATERING_DURATION  5   /* seconds */
#define NOZZLE_STEP_DELAY  2   /* seconds */
#define LOOP_DELAY         1   /* seconds */
#define MAX_RETRIES        3
#define RETRY_DELAY_US     100000  /* 100 ms */

static volatile sig_atomic_t g_stop = 0;

/* ------------------------------------------------------------------ */
/* Signal handling — async-signal-safe only                            */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */
static int set_servo_pw(int pin, int pulsewidth)
{
    if (gpioServo(pin, pulsewidth) != 0) {
        fprintf(stderr, "Error: gpioServo(pin=%d, pw=%d) failed\n", pin, pulsewidth);
        return -1;
    }
    return 0;
}

static int stop_servo(int pin)
{
    if (gpioServo(pin, 0) != 0) {
        fprintf(stderr, "Warning: gpioServo(pin=%d, 0) failed\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Moisture simulation                                                 */
/* ------------------------------------------------------------------ */
static int read_moisture(void)
{
    static int idx = 0;
    static const int sequence[] = {20, 40, 60, 80, 100};
    int v = sequence[idx];
    idx = (idx + 1) % (int)(sizeof(sequence) / sizeof(sequence[0]));
    return v;
}

/* ------------------------------------------------------------------ */
/* Watering cycle                                                      */
/* ------------------------------------------------------------------ */
static int open_valve(void)
{
    printf("Opening valve...\n");
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (set_servo_pw(VALVE_PIN, VALVE_OPEN_PW) == 0)
            return 0;
        fprintf(stderr, "Warning: valve open attempt %d/%d failed\n", attempt, MAX_RETRIES);
        usleep(RETRY_DELAY_US);
    }
    return -1;
}

static int close_valve(void)
{
    printf("Closing valve...\n");
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (set_servo_pw(VALVE_PIN, VALVE_CLOSE_PW) == 0)
            return 0;
        fprintf(stderr, "Warning: valve close attempt %d/%d failed\n", attempt, MAX_RETRIES);
        usleep(RETRY_DELAY_US);
    }
    return -1;
}

static int spray_nozzle(int angle)
{
    int pw = nozzle_pws[angle];
    printf("Spraying nozzle at %d degrees (pw=%d us)...\n", angle, pw);
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (set_servo_pw(NOZZLE_PIN, pw) == 0)
            return 0;
        fprintf(stderr, "Warning: nozzle spray attempt %d/%d failed\n", attempt, MAX_RETRIES);
        usleep(RETRY_DELAY_US);
    }
    return -1;
}

static int water_plant(void)
{
    for (int i = 0; i < NOZZLE_ANGLES_COUNT && !g_stop; ++i) {
        if (spray_nozzle(i) != 0) {
            fprintf(stderr, "Error: nozzle spray failed at angle %d\n", nozzle_angles[i]);
            return -1;
        }
        sleep(NOZZLE_STEP_DELAY);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Best-effort stop of servos */
    (void)stop_servo(VALVE_PIN);
    (void)stop_servo(NOZZLE_PIN);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Ensure servos are stopped before we start */
    (void)stop_servo(VALVE_PIN);
    (void)stop_servo(NOZZLE_PIN);

    printf("Automated Plant Watering System started.\n");
    printf("Press Ctrl+C to exit.\n");

    while (!g_stop) {
        int moisture = read_moisture();
        printf("Moisture level: %d%%\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold (%d%%). Starting watering cycle...\n",
                   MOISTURE_THRESHOLD);

            if (open_valve() != 0) {
                fprintf(stderr, "Error: failed to open valve — aborting watering cycle\n");
                cleanup();
                return EXIT_FAILURE;
            }

            if (water_plant() != 0) {
                fprintf(stderr, "Error: watering cycle failed\n");
                cleanup();
                return EXIT_FAILURE;
            }

            if (close_valve() != 0) {
                fprintf(stderr, "Error: failed to close valve\n");
                cleanup();
                return EXIT_FAILURE;
            }
        } else {
            printf("Moisture above threshold (%d%%). Skipping watering cycle.\n",
                   MOISTURE_THRESHOLD);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < LOOP_DELAY && !g_stop; ++s)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

