    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (init_mpu6050(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU6050 initialization failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    FILE *fp = fopen("gyro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_log.txt: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    printf("Logging gyro data to gyro_log.txt at %d Hz. Press Ctrl+C to stop.\n", SAMPLE_HZ);

    while (g_running) {
        int16_t x, y, z;
        if (read_gyro_data(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error; continuing after delay.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }
        if (log_data(fp, x, y, z) != 0) {
            fprintf(stderr, "Logging error; continuing.\n");
        }
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

