        gpioSetMode(IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(IN4, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK_BTN, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BTN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BTN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BTN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_coils(0, 0, 0, 0) < 0) {
        fprintf(stderr, "Error: initial coils de-energize failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock system started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_lock_state = 1;
    int last_unlock_state = 1;

    while (running) {
        int lock_state = gpioRead(LOCK_BTN);
        int unlock_state = gpioRead(UNLOCK_BTN);

        if (lock_state < 0 || unlock_state < 0) {
            fprintf(stderr, "Error: gpioRead failed\n");
            break;
        }

        if (lock_state == 0 && last_lock_state == 1) {
            if (lock_door() < 0) {
                fprintf(stderr, "Error: lock_door failed\n");
                break;
            }
        }
        if (unlock_state == 0 && last_unlock_state == 1) {
            if (unlock_door() < 0) {
                fprintf(stderr, "Error: unlock_door failed\n");
                break;
            }
        }

        last_lock_state = lock_state;
        last_unlock_state = unlock_state;
        gpioDelay(10000);
    }

    set_coils(0, 0, 0, 0);
    gpioTerminate();
    printf("\nDoor lock system stopped.\n");
    return EXIT_SUCCESS;
}

