#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  50000   /* 50 ms echo wait */
#define SAMPLE_US   1000000 /* 1 s between samples */
#define SETTLE_US   60000   /* 60 ms between measurements */
#define TRIGGER_US  10

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm.
 * Returns distance in cm on success, -1.0 on timeout, -2.0 on pigpio error.
 */
static float measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -2.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -2.0f;
    }
    gpioDelay(TRIGGER_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -2.0f;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo rising-edge timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    /* Speed of sound 343 m/s => 34300 cm/s; distance = pulse_us * 34300 / 2 / 1e6 */
    return (float)pulse_us * 17150.0f / 2.0f;
}

static void log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (distance < 0.0f) {
        fprintf(log_fp, "%s, -1\n", timestamp);
        fprintf(stderr, "Error: measurement failed at %s\n", timestamp);
    } else {
        fprintf(log_fp, "%s, %.2f\n", timestamp, distance);
    }
    fflush(log_fp);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        float distance = measure_distance();
        log_distance(distance);
        gpioDelay(SETTLE_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

