#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

#define REG_SMPLRT_DIV  0x19
#define REG_CONFIG      0x1A
#define REG_GYRO_CONFIG 0x1B
#define REG_GYRO_XOUT_H 0x43
#define REG_PWR_MGMT_1  0x6B

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int16_t combine_le(const uint8_t *p) {
    return (int16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg(fd, REG_PWR_MGMT_1, 0x80) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg(fd, REG_PWR_MGMT_1, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, REG_SMPLRT_DIV, 0x07) < 0) return -1;
    if (i2c_write_reg(fd, REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, REG_GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Logging angular velocity (x, y, z) to console...\n");
    fflush(stdout);

    while (g_running) {
        uint8_t raw[6];
        if (i2c_read_regs(fd, REG_GYRO_XOUT_H, raw, sizeof(raw)) < 0) {
            fprintf(stderr, "Read error; continuing...\n");
            usleep(100000);
            continue;
        }

        int16_t gx = combine_le(&raw[0]);
        int16_t gy = combine_le(&raw[2]);
        int16_t gz = combine_le(&raw[4]);

        printf("Gyro: X=%6d, Y=%6d, Z=%6d\n", gx, gy, gz);
        fflush(stdout);
        usleep(100000);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

