/*
 * Automated plant watering system for Raspberry Pi 4 Model B.
 *
 * Four 5 V relay modules (active-low) are sequentially activated on BCM GPIO17,
 * GPIO18, GPIO27, GPIO22 every 86 400 s (24 h) of the program lifetime.
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 * Run:    ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define RELAY_DURATION  5          /* seconds each relay is energised */
#define CYCLE_PERIOD    86400      /* seconds between full watering cycles */
#define POLL_INTERVAL   60         /* seconds between relay activations */
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;
static struct gpiod_chip  *g_chip  = NULL;
static struct gpiod_line  *g_lines[NUM_RELAYS];

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_timestamp(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s\n", ts) < 0)
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose(log): %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
static int activate_relay(int idx)
{
    if (idx < 0 || idx >= NUM_RELAYS) {
        fprintf(stderr, "activate_relay: invalid index %d\n", idx);
        return -1;
    }

    /* Active-low: line is LOW (0) to energise the relay. */
    if (gpiod_line_set_value(g_lines[idx], 0) < 0) {
        fprintf(stderr, "set_value(line %u, 0) failed: %s\n",
                relay_pins[idx], strerror(errno));
        return -1;
    }

    /* Energise for RELAY_DURATION seconds, checking for shutdown. */
    for (int i = 0; i < RELAY_DURATION && g_running; i++)
        sleep(1);

    /* De-energise: return line to HIGH (inactive). */
    if (gpiod_line_set_value(g_lines[idx], 1) < 0) {
        fprintf(stderr, "set_value(line %u, 1) failed: %s\n",
                relay_pins[idx], strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (g_lines[i]) {
            /* Return line to HIGH (inactive) before releasing. */
            (void)gpiod_line_set_value(g_lines[i], 1);
            gpiod_line_release(g_lines[i]);
            g_lines[i] = NULL;
        }
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ------------------------------------------- */
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        /* Fall back to the first chip found (gpiochip0 on older kernels). */
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get and request all four lines as outputs ---------------- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        g_lines[i] = gpiod_chip_get_line(g_chip, relay_pins[i]);
        if (!g_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u): %s\n",
                    relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_output(g_lines[i], "plant-watering", 1) < 0) {
            fprintf(stderr, "request_output(%u): %s\n",
                    relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Plant watering system started.  GPIO17,18,27,22 active-low.  "
           "Cycle every %d s.  Press Ctrl-C to exit.\n", CYCLE_PERIOD);

    /* ---- Main watering loop --------------------------------------- */
    while (g_running) {
        log_timestamp();

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (activate_relay(i) < 0) {
                fprintf(stderr, "Relay %d activation failed; aborting.\n", i);
                cleanup();
                return EXIT_FAILURE;
            }
            /* Pause between relay activations (poll interval). */
            for (int s = 0; s < POLL_INTERVAL && g_running; s++)
                sleep(1);
        }

        /* Wait until the next full cycle (CYCLE_PERIOD seconds). */
        for (int s = 0; s < CYCLE_PERIOD && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

