#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 1800
#define LOG_FILE "smart_lighting.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RELAY1_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY2_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY3_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY4_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

void set_relay_intensity(int intensity) {
    if (intensity < 0) intensity = 0;
    if (intensity > PWM_RANGE) intensity = PWM_RANGE;

    gpioPWM(RELAY1_PIN, intensity);
    gpioPWM(RELAY2_PIN, intensity);
    gpioPWM(RELAY3_PIN, intensity);
    gpioPWM(RELAY4_PIN, intensity);
}

void cleanup() {
    set_relay_intensity(0);
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed. Exiting.");
        return 1;
    }

    log_event("Smart lighting sunrise started.");

    int step_delay = SUNRISE_DURATION / PWM_RANGE;
    if (step_delay < 1) step_delay = 1;

    for (int intensity = 0; intensity <= PWM_RANGE && program_running; intensity++) {
        set_relay_intensity(intensity);
        gpioDelay(step_delay * 1000);
    }

    if (program_running) {
        log_event("Sunrise complete.");
    }

    cleanup();
    log_event("Smart lighting sunrise finished.");

    return 0;
}

