#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define GYRO_CONFIG 0x1B
#define LED_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_US 50000
#define THRESHOLD 250.0
#define MAX_REINIT_ATTEMPTS 3

typedef struct {
    struct timespec timestamp;
    int16_t x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void init_circular_buffer(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void add_to_circular_buffer(circular_buffer_t *buf, struct timespec ts, int16_t x, int16_t y, int16_t z) {
    buf->data[buf->head].timestamp = ts;
    buf->data[buf->head].x = x;
    buf->data[buf->head].y = y;
    buf->data[buf->head].z = z;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static int init_mpu6050(void) {
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    int cfg = i2cReadByteData(i2c_handle, GYRO_CONFIG);
    if (cfg < 0) {
        fprintf(stderr, "Error reading gyro config: %d\n", cfg);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, cfg) < 0) {
        fprintf(stderr, "Error writing gyro config\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", rc);
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void control_led(int16_t x, int16_t y, int16_t z) {
    double ax = (double)x / 131.0;
    double ay = (double)y / 131.0;
    double az = (double)z / 131.0;
    if (fabs(ax) > THRESHOLD || fabs(ay) > THRESHOLD || fabs(az) > THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);
    init_circular_buffer(&gyro_buffer);
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    int reinit_attempts = 0;
    while (!terminate) {
        int16_t x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_to_circular_buffer(&gyro_buffer, ts, x, y, z);
            control_led(x, y, z);
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Read failed, attempt %d/%d\n", reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
            reinit_attempts++;
            if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }
            if (init_mpu6050() != 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }
    cleanup();
    return 0;
}

