#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 8
#define CS_PIN          8
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define LOG_FILE        "gyro_log.txt"
#define SAMPLE_DELAY_MS 10
#define MAX_RETRIES     3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip); chip = NULL; return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip); chip = NULL; cs_line = NULL; return -1;
    }

    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[7] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx[7] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 7,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error asserting CS line: %s\n", strerror(errno));
        return -1;
    }

