        close(spi_fd); spi_fd = -1;
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Logging gyroscope data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        int16_t x = 0, y = 0, z = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_gyro_data(&x, &y, &z) == 0) {
                success = 1;
                break;
            }
            usleep(1000);
        }

        if (success) {
            if (log_data(log_fp, x, y, z) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data after %d attempts.\n", MAX_RETRIES);
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

