#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 3900000
#define SPI_FLAGS 0
#define LED_GPIO 17
#define BUFFER_SIZE 64
#define THRESHOLD 200.0
#define SAMPLE_DELAY_US 10000

#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43

typedef struct {
    time_t timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

static gyro_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_read_register(int handle, uint8_t reg, uint8_t *data, uint32_t len) {
    char tx[len + 1];
    char rx[len + 1];
    tx[0] = reg | 0x80;
    for (uint32_t i = 1; i <= len; i++) tx[i] = 0x00;
    if (spiXfer(handle, tx, rx, len + 1) != len + 1) return -1;
    for (uint32_t i = 0; i < len; i++) data[i] = (uint8_t)rx[i + 1];
    return 0;
}

static int spi_write_register(int handle, uint8_t reg, uint8_t data) {
    char tx[2] = { (char)(reg & 0x7F), (char)data };
    char rx[2];
    return (spiXfer(handle, tx, rx, 2) == 2) ? 0 : -1;
}

static int init_mpu6050(int handle) {
    if (spi_write_register(handle, MPU6050_PWR_MGMT_1, 0x00) != 0) return -1;
    gpioDelay(100000);
    if (spi_write_register(handle, MPU6050_SMPLRT_DIV, 0x07) != 0) return -1;
    if (spi_write_register(handle, MPU6050_GYRO_CONFIG, 0x00) != 0) return -1;
    return 0;
}

static int read_gyro_data(int handle, gyro_data_t *data) {
    uint8_t buf[6];
    if (spi_read_register(handle, MPU6050_GYRO_XOUT_H, buf, 6) != 0) return -1;
    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);
    data->timestamp = time(NULL);
    return 0;
}

static void add_to_buffer(gyro_data_t data) {
    circular_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void check_threshold(gyro_data_t data) {
    if (abs((double)data.x) > THRESHOLD || abs((double)data.y) > THRESHOLD || abs((double)data.z) > THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        gpioDelay(500000);
        gpioWrite(LED_GPIO, 0);
        gpioDelay(500000);
    }
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld,%d,%d,%d\n", circular_buffer[idx].timestamp, circular_buffer[idx].x, circular_buffer[idx].y, circular_buffer[idx].z);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (init_mpu6050(spi_handle) != 0) {
        fprintf(stderr, "MPU6050 initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    while (running) {
        gyro_data_t data;
        if (read_gyro_data(spi_handle, &data) == 0) {
            add_to_buffer(data);
            check_threshold(data);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    print_buffer();
    gpioWrite(LED_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

