    if (abs((double)data.x) > THRESHOLD || abs((double)data.y) > THRESHOLD || abs((double)data.z) > THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        gpioDelay(500000);
        gpioWrite(LED_GPIO, 0);
        gpioDelay(500000);
    }
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld,%d,%d,%d\n", circular_buffer[idx].timestamp, circular_buffer[idx].x, circular_buffer[idx].y, circular_buffer[idx].z);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (init_mpu6050(spi_handle) != 0) {
        fprintf(stderr, "MPU6050 initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    while (running) {
        gyro_data_t data;
        if (read_gyro_data(spi_handle, &data) == 0) {
            add_to_buffer(data);
            check_threshold(data);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    print_buffer();
    gpioWrite(LED_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

