#define ROLL_THRESHOLD 45.0
#define PITCH_THRESHOLD 45.0
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_word(int handle, uint8_t reg) {
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return 0;
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) return 0;
    return (int16_t)((hi << 8) | lo);
}

static int init_mpu6050(int handle) {
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake MPU6050\n");
        return -1;
    }
    gpioDelay(100000);
    return 0;
}

static void read_accel(int handle, float *ax, float *ay, float *az) {
    int16_t raw_x = read_word(handle, ACCEL_XOUT_H);
    int16_t raw_y = read_word(handle, ACCEL_YOUT_H);
    int16_t raw_z = read_word(handle, ACCEL_ZOUT_H);
    *ax = (float)raw_x / 16384.0f;
    *ay = (float)raw_y / 16384.0f;
    *az = (float)raw_z / 16384.0f;
}

static void read_gyro(int handle, float *gx, float *gy, float *gz) {
    int16_t raw_x = read_word(handle, GYRO_XOUT_H);
    int16_t raw_y = read_word(handle, GYRO_YOUT_H);
    int16_t raw_z = read_word(handle, GYRO_ZOUT_H);
