#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_COMMAND 0x18
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PSALS_FORCE 0x07
#define SI1145_CMD_PS_AUTO 0x0D
#define SI1145_CMD_ALS_AUTO 0x0E
#define SI1145_CMD_PSALS_AUTO 0x0F
#define PROXIMITY_THRESHOLD 100
#define LED_GPIO 17
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define LOOP_DELAY_US 100000

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_byte: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_byte: write reg failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("i2c_read_byte: read failed");
        return -1;
    }
    return 0;
}

static int si1145_init(int fd) {
    if (i2c_write_byte(fd, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_byte(fd, SI1145_REG_COMMAND, SI1145_CMD_PS_AUTO) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_byte(fd, SI1145_REG_COMMAND, SI1145_CMD_ALS_AUTO) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_data0, als_data1, ps_data0, ps_data1;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_byte(fd, SI1145_REG_COMMAND, SI1145_CMD_PSALS_FORCE) < 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(10000);
        if (i2c_read_byte(fd, SI1145_REG_ALS_VIS_DATA0, &als_data0) < 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (i2c_read_byte(fd, SI1145_REG_ALS_VIS_DATA0 + 1, &als_data1) < 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (i2c_read_byte(fd, SI1145_REG_PS1_DATA0, &ps_data0) < 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (i2c_read_byte(fd, SI1145_REG_PS1_DATA0 + 1, &ps_data1) < 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        *ambient_light = ((uint16_t)als_data1 << 8) | als_data0;
        *proximity = ((uint16_t)ps_data1 << 8) | ps_data0;
        return 0;
    }
    return -1;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,AmbientLight:%u,Proximity:%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_light, proximity);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus failed");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE failed");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (si1145_init(i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file failed");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint16_t ambient_light = 0, proximity = 0;
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);
            if (proximity > PROXIMITY_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

