#define ADXRS290_REG_CTRL3 0x10
#define ADXRS290_REG_CTRL4 0x11
#define ADXRS290_REG_CTRL5 0x12
#define ADXRS290_REG_CTRL6 0x13
#define ADXRS290_REG_CTRL7 0x14
#define ADXRS290_REG_CTRL8 0x15
#define ADXRS290_REG_CTRL9 0x16
#define ADXRS290_REG_CTRL10 0x17
