#define ADXRS290_REG_CTRL13 0x1A
#define ADXRS290_REG_CTRL14 0x1B
#define ADXRS290_REG_CTRL15 0x1C
#define ADXRS290_REG_CTRL16 0x1D
#define ADXRS290_REG_CTRL17 0x1E
#define ADXRS290_REG_CTRL18 0x1F

static int spi_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int spi_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int spi_read_register(uint8_t reg, int16_t *value) {
    char tx[2];
    char rx[2];

    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    *value = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

