    while (program_running) {
        uint64_t timestamp_us;
        struct timespec ts;
        int16_t x_rate = 0, y_rate = 0;

        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime failed");
            break;
        }
        timestamp_us = (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;

        if (spi_read_register(ADXRS290_REG_XGYRO_OUT, &x_rate) != 0) {
            fprintf(stderr, "Failed to read X axis rate. Re-initializing SPI...\n");
            reinit_attempts++;
            if (reinit_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }
            cleanup();
            if (spi_init() != 0) {
                break;
            }
            continue;
        }

        if (spi_read_register(ADXRS290_REG_YGYRO_OUT, &y_rate) != 0) {
            fprintf(stderr, "Failed to read Y axis rate. Re-initializing SPI...\n");
            reinit_attempts++;
            if (reinit_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }
            cleanup();
            if (spi_init() != 0) {
                break;
            }
            continue;
        }

        reinit_attempts = 0;
        csv_write(timestamp_us, x_rate, y_rate);
        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

