#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define STEP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(LAMP1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LAMP1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LAMP2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LAMP3_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", LAMP1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", LAMP2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", LAMP3_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(LAMP1_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", LAMP1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP2_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", LAMP2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP3_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", LAMP3_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(LAMP1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM on GPIO%d.\n", LAMP1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(LAMP2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM on GPIO%d.\n", LAMP2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(LAMP3_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM on GPIO%d.\n", LAMP3_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void turn_off_lamps(void) {
    gpioPWM(LAMP1_PIN, 0);
    gpioPWM(LAMP2_PIN, 0);
    gpioPWM(LAMP3_PIN, 0);
}

static void cleanup(void) {
    turn_off_lamps();
    gpioTerminate();
}

static int set_lamp_brightness(int pin, int brightness) {
    if (brightness < 0 || brightness > PWM_RANGE) {
        fprintf(stderr, "Error: invalid brightness value %d for GPIO%d.\n", brightness, pin);
        return -1;
    }
    if (gpioPWM(pin, brightness) != 0) {
        fprintf(stderr, "Error: failed to set PWM on GPIO%d.\n", pin);
        return -1;
    }
    return 0;
}

static int fade_lamp(int pin, int target_brightness, int delay_us) {
    int current_brightness = PWM_RANGE;
    int step = (target_brightness > current_brightness) ? 1 : -1;

    while (current_brightness != target_brightness) {
        if (!running) {
            return -1;
        }
        current_brightness += step;
        if (set_lamp_brightness(pin, current_brightness) != 0) {
            return -1;
        }
        gpioDelay(delay_us);
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  total_duration_seconds: integer 1-3600\n");
        return EXIT_FAILURE;
    }

    char *endptr;
    errno = 0;
    long duration = strtol(argv[1], &endptr, 10);
    if (errno != 0 || *endptr != '\0' || duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: invalid duration '%s'. Must be an integer 1-3600.\n", argv[1]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Total duration: %ld seconds.\n", duration);
    printf("Lamps: GPIO%d, GPIO%d, GPIO%d\n", LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);
    printf("PWM frequency: %d Hz, range: 0-%d\n", PWM_FREQUENCY, PWM_RANGE);
    printf("Press Ctrl+C to stop early.\n");

    int lamp_pins[] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    int num_lamps = (int)(sizeof(lamp_pins) / sizeof(lamp_pins[0]));
    int total_steps = (int)(duration * 1000000L / STEP_DELAY_US);
    int step_delay_us = STEP_DELAY_US;

    for (int i = 0; i < num_lamps && running; i++) {
        int pin = lamp_pins[i];
        printf("Fading lamp on GPIO%d (step %d/%d): full brightness -> off\n", pin, i + 1, num_lamps);

        if (fade_lamp(pin, 0, step_delay_us) != 0) {
            fprintf(stderr, "Error: fade failed on GPIO%d.\n", pin);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    if (!running) {
        printf("\nInterrupt received. Shutting down gracefully...\n");
    }

    cleanup();
    printf("Smart Sunset Simulator finished.\n");
    return EXIT_SUCCESS;
}

