        fprintf(stderr, "Error: invalid duration '%s'. Must be an integer 1-3600.\n", argv[1]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Total duration: %ld seconds.\n", duration);
    printf("Lamps: GPIO%d, GPIO%d, GPIO%d\n", LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);
    printf("PWM frequency: %d Hz, range: 0-%d\n", PWM_FREQUENCY, PWM_RANGE);
    printf("Press Ctrl+C to stop early.\n");

    int lamp_pins[] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    int num_lamps = (int)(sizeof(lamp_pins) / sizeof(lamp_pins[0]));
    int total_steps = (int)(duration * 1000000L / STEP_DELAY_US);
    int step_delay_us = STEP_DELAY_US;

    for (int i = 0; i < num_lamps && running; i++) {
        int pin = lamp_pins[i];
        printf("Fading lamp on GPIO%d (step %d/%d): full brightness -> off\n", pin, i + 1, num_lamps);

        if (fade_lamp(pin, 0, step_delay_us) != 0) {
            fprintf(stderr, "Error: fade failed on GPIO%d.\n", pin);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    if (!running) {
        printf("\nInterrupt received. Shutting down gracefully...\n");
    }

    cleanup();
    printf("Smart Sunset Simulator finished.\n");
    return EXIT_SUCCESS;
}

