#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x50
#define RELAY_GPIO 17
#define DEBOUNCE_MS 100
#define POLL_DELAY_US 10000
#define LOG_FILE "touch_relay.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s - ERROR: %s\n", timestamp, message);
        fflush(log_file);
    }
    fprintf(stderr, "%s - ERROR: %s\n", timestamp, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_byte(fd, MPR121_SOFTRESET, 0x63) < 0) {
        log_error("Failed to reset MPR121");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_byte(fd, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        log_error("Failed to set electrode config");
        return -1;
    }

    return 0;
}

static int read_touch_status(int fd, uint16_t *status) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, MPR121_TOUCHSTATUS_L, buf, 2) < 0) {
        log_error("Failed to read touch status");
        return -1;
    }
    *status = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static void toggle_relay(int gpio) {
    int level = gpioRead(gpio);
    if (level < 0) {
        log_error("Failed to read relay GPIO state");
        return;
    }
    if (gpioWrite(gpio, !level) < 0) {
        log_error("Failed to write relay GPIO");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        log_error("MPR121 initialisation failed");
        close(i2c_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set relay GPIO mode");
        close(i2c_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        log_error("Failed to initialise relay GPIO state");
        close(i2c_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    uint16_t prev_status = 0;
    uint32_t last_toggle_ms = 0;

    while (running) {
        uint16_t status;
        if (read_touch_status(i2c_fd, &status) < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (status & 0x0001) {
            uint32_t now_ms = gpioTick() / 1000;
            if ((now_ms - last_toggle_ms) >= DEBOUNCE_MS) {
                toggle_relay(RELAY_GPIO);
                last_toggle_ms = now_ms;
            }
        }

        prev_status = status;
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    close(i2c_fd);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

