#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_US 50000
#define CONSECUTIVE_READS 3
#define CONSECUTIVE_THRESHOLD 0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flame_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int control_buzzer(int pin, int state) {
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n", pin, state, pigpio_error(state));
        return -1;
    }
    return 0;
}

static int control_led(int pin, int state) {
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n", pin, state, pigpio_error(state));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_detected = 1;
        int consecutive_low = 0;

        for (int i = 0; i < CONSECUTIVE_READS; i++) {
            int value = read_flame_sensor(FLAME_SENSOR_PIN);
            if (value < 0) {
                fprintf(stderr, "Error reading flame sensor, exiting.\n");
                cleanup();
                return EXIT_FAILURE;
            }
            if (value == CONSECUTIVE_THRESHOLD) {
                consecutive_low++;
            } else {
                consecutive_low = 0;
            }
            if (i < CONSECUTIVE_READS - 1) {
                gpioDelay(SAMPLE_INTERVAL_US);
            }
        }

        if (consecutive_low == CONSECUTIVE_READS) {
            flame_detected = 0;
        }

        if (flame_detected) {
            if (log_event("Flame Detected") != 0) {
