#define CONSECUTIVE_READS 3
#define CONSECUTIVE_THRESHOLD 0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flame_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int control_buzzer(int pin, int state) {
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n", pin, state, pigpio_error(state));
        return -1;
    }
    return 0;
}

static int control_led(int pin, int state) {
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n", pin, state, pigpio_error(state));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

