#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25

#define KP 2.0
#define KI 0.1
#define KD 0.5

#define OBSTACLE_DISTANCE 20.0
#define MAX_SPEED 255
#define MIN_SPEED -255
#define LOOP_DELAY_US 50000

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

void stop_motors() {
    gpioPWM(MOTOR_A_FORWARD, 0);
    gpioPWM(MOTOR_A_BACKWARD, 0);
    gpioPWM(MOTOR_B_FORWARD, 0);
    gpioPWM(MOTOR_B_BACKWARD, 0);
}

void set_motor_speed(int motor, int speed) {
    if (speed > MAX_SPEED) speed = MAX_SPEED;
    if (speed < MIN_SPEED) speed = MIN_SPEED;

    if (motor == 'A') {
        if (speed > 0) {
            gpioPWM(MOTOR_A_FORWARD, speed);
            gpioPWM(MOTOR_A_BACKWARD, 0);
        } else {
            gpioPWM(MOTOR_A_FORWARD, 0);
            gpioPWM(MOTOR_A_BACKWARD, -speed);
        }
    } else if (motor == 'B') {
        if (speed > 0) {
            gpioPWM(MOTOR_B_FORWARD, speed);
            gpioPWM(MOTOR_B_BACKWARD, 0);
        } else {
            gpioPWM(MOTOR_B_FORWARD, 0);
            gpioPWM(MOTOR_B_BACKWARD, -speed);
        }
    }
}

float simulate_sensor() {
    return (float)(rand() % 400 + 2);
}

float simulate_tilt_error() {
    return (float)(rand() % 201 - 100) / 10.0;
}

float calculate_pid(float setpoint, float actual, float *integral, float *previous_error) {
    float error = setpoint - actual;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

int main() {
    srand(time(NULL));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    log_file = fopen("balance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,tilt_error,distance,motor_a_speed,motor_b_speed\n");

    float integral_a = 0.0, integral_b = 0.0;
    float previous_error_a = 0.0, previous_error_b = 0.0;

    signal(SIGINT, signal_handler);

    while (program_running) {
        float distance = simulate_sensor();
        float tilt_error = simulate_tilt_error();

        float pid_a = calculate_pid(0.0, tilt_error, &integral_a, &previous_error_a);
        float pid_b = calculate_pid(0.0, tilt_error, &integral_b, &previous_error_b);

        int motor_a_speed = (int)pid_a;
        int motor_b_speed = (int)pid_b;

        if (distance < OBSTACLE_DISTANCE) {
            motor_a_speed = -MAX_SPEED / 2;
            motor_b_speed = -MAX_SPEED / 2;
        }

        set_motor_speed('A', motor_a_speed);
        set_motor_speed('B', motor_b_speed);

        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
        fflush(log_file);

        gpioDelay(LOOP_DELAY_US);
    }

    stop_motors();
    fclose(log_file);
    gpioTerminate();
    return 0;
}

