#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/kd.h>
#include <pigpio.h>
#include <pthread.h>
#include <sndfile.h>

#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define LED_R_PIN 17
#define LED_G_PIN 18
#define LED_B_PIN 27
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SCALE_FACTOR 1.0
#define SINE_AMPLITUDE 128
#define SINE_FREQUENCY 440
#define SINE_SAMPLES 4096
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)
#define LED_UPDATE_US 10000
#define ALSA_AVAILABLE 1

#if ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

#define DEFAULT_DEVICE "default"

static volatile sig_atomic_t running = 1;
static pthread_mutex_t led_mutex = PTHREAD_MUTEX_INITIALIZER;

#if ALSA_AVAILABLE
static snd_pcm_t *alsa_handle = NULL;
static int alsa_opened = 0;
#endif

static int led_r_value = 0;
static int led_g_value = 0;
static int led_b_value = 0;

static int sine_buffer[SINE_SAMPLES];
static int sine_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    pthread_mutex_lock(&led_mutex);
    gpioPWM(LED_R_PIN, 0);
    gpioPWM(LED_G_PIN, 0);
    gpioPWM(LED_B_PIN, 0);
    pthread_mutex_unlock(&led_mutex);
    gpioTerminate();
#if ALSA_AVAILABLE
    if (alsa_opened) {
        snd_pcm_drain(alsa_handle);
        snd_pcm_close(alsa_handle);
        alsa_handle = NULL;
        alsa_opened = 0;
    }
#endif
}

static void set_led_color(int r, int g, int b) {
    pthread_mutex_lock(&led_mutex);
    gpioPWM(LED_R_PIN, r);
    gpioPWM(LED_G_PIN, g);
    gpioPWM(LED_B_PIN, b);
    led_r_value = r;
    led_g_value = g;
    led_b_value = b;
    pthread_mutex_unlock(&led_mutex);
}

static void map_to_color(double rms) {
    double scaled = rms * SCALE_FACTOR;
    int r = (int)(scaled * 255.0);
    int g = (int)(scaled * 255.0);
    int b = (int)(scaled * 255.0);
    if (r < 0) r = 0; if (r > 255) r = 255;
    if (g < 0) g = 0; if (g > 255) g = 255;
    if (b < 0) b = 0; if (b > 255) b = 255;
    set_led_color(r, g, b);
}

#if ALSA_AVAILABLE
static int init_alsa(const char *device) {
    int err;
    snd_pcm_hw_params_t *hw_params;
    unsigned int rate = SAMPLE_RATE;
    snd_pcm_format_t format = SND_PCM_FORMAT_S16_LE;
    snd_pcm_access_t access = SND_PCM_ACCESS_RW_INTERLEAVED;

    err = snd_pcm_open(&alsa_handle, device, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_strerror(err));
        return -1;
    }
    alsa_opened = 1;

    snd_pcm_hw_params_alloca(&hw_params);
    err = snd_pcm_hw_params_any(alsa_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_any failed: %s\n", snd_strerror(err));
        return -1;
    }
    err = snd_pcm_hw_params_set_access(alsa_handle, hw_params, access);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_access failed: %s\n", snd_strerror(err));
        return -1;
    }
    err = snd_pcm_hw_params_set_format(alsa_handle, hw_params, format);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format failed: %s\n", snd_strerror(err));
        return -1;
    }
    err = snd_pcm_hw_params_set_rate_near(alsa_handle, hw_params, &rate, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n", snd_strerror(err));
        return -1;
    }
    err = snd_pcm_hw_params_set_channels(alsa_handle, hw_params, 1);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n", snd_strerror(err));
        return -1;
    }
    err = snd_pcm_hw_params(alsa_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_strerror(err));
        return -1;
    }
    err = snd_pcm_prepare(alsa_handle);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
        return -1;
    }
    return 0;
}

static int read_audio_data(short *buffer, int frames) {
    int err;
    snd_pcm_sframes_t ret = snd_pcm_readi(alsa_handle, buffer, frames);
    if (ret == -EPIPE) {
        fprintf(stderr, "Overrun occurred\n");
        err = snd_pcm_prepare(alsa_handle);
        if (err < 0) {
            fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
            return -1;
        }
        return 0;
    } else if (ret == -ESTRPIPE) {
        fprintf(stderr, "Suspend occurred\n");
        err = snd_pcm_resume(alsa_handle);
        if (err < 0) {
            fprintf(stderr, "snd_pcm_resume failed: %s\n", snd_strerror(err));
            return -1;
        }
        return 0;
    } else if (ret < 0) {
        fprintf(stderr, "Error from readi: %s\n", snd_strerror(ret));
        return -1;
    } else if (ret != (snd_pcm_sframes_t)frames) {
        fprintf(stderr, "Short read, ret=%li\n", ret);
        return 0;
    }
    return 1;
}

static double calculate_rms(const short *buffer, int frames) {
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double val = (double)buffer[i];
        sum_sq += val * val;
    }
    return sqrt(sum_sq / (double)frames);
}
#else
static void generate_sine_wave(void) {
    for (int i = 0; i < SINE_SAMPLES; i++) {
        double t = (double)i / (double)SINE_SAMPLES * 2.0 * M_PI;
        double val = SINE_AMPLITUDE * sin(SINE_FREQUENCY * t);
        sine_buffer[i] = (int)val;
    }
}

static int read_audio_data(short *buffer, int frames) {
    for (int i = 0; i < frames; i++) {
        buffer[i] = (short)sine_buffer[sine_index];
        sine_index = (sine_index + 1) % SINE_SAMPLES;
    }
    return 1;
}

static double calculate_rms(const short *buffer, int frames) {
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double val = (double)buffer[i];
        sum_sq += val * val;
    }
    return sqrt(sum_sq / (double)frames);
}
#endif

int main(int argc, char *argv[]) {
    if (argc > 2) {
        fprintf(stderr, "Usage: %s [scale_factor]\n", argv[0]);
        return 1;
    }
    if (argc == 2) {
        double val = atof(argv[1]);
        if (val > 0.0) {
            SCALE_FACTOR = val;
            printf("Scale factor set to %.2f\n", SCALE_FACTOR);
        } else {
            fprintf(stderr, "Invalid scale factor: %s\n", argv[1]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_R_PIN, PI_OUTPUT);
    gpioSetMode(LED_G_PIN, PI_OUTPUT);
    gpioSetMode(LED_B_PIN, PI_OUTPUT);
    gpioSetPWMrange(LED_R_PIN, PWM_RANGE);
    gpioSetPWMrange(LED_G_PIN, PWM_RANGE);
    gpioSetPWMrange(LED_B_PIN, PWM_RANGE);
    gpioSetPWMfrequency(LED_R_PIN, PWM_FREQ);
    gpioSetPWMfrequency(LED_G_PIN, PWM_FREQ);
    gpioSetPWMfrequency(LED_B_PIN, PWM_FREQ);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

#if ALSA_AVAILABLE
    if (init_alsa(DEFAULT_DEVICE) != 0) {
        fprintf(stderr, "ALSA initialization failed. Simulating sine wave.\n");
        generate_sine_wave();
    } else {
        printf("ALSA initialized on %s\n", DEFAULT_DEVICE);
    }
#else
    printf("ALSA not available. Simulating sine wave.\n");
    generate_sine_wave();
#endif

    short *audio_buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (!audio_buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup();
        return 1;
    }

    printf("Starting audio capture...\n");

    while (running) {
        int ret = read_audio_data(audio_buffer, PERIOD_SIZE);
        if (ret < 0) {
            fprintf(stderr, "Audio read error, exiting\n");
            break;
        }
        if (ret == 0) {
            continue;
        }

        double rms = calculate_rms(audio_buffer, PERIOD_SIZE);
        map_to_color(rms);

        usleep(LED_UPDATE_US);
    }

    free(audio_buffer);
    cleanup();
    printf("Exiting.\n");
    return 0;
}

