static int read_audio_data(short *buffer, int frames) {
    int err;
    snd_pcm_sframes_t ret = snd_pcm_readi(alsa_handle, buffer, frames);
    if (ret == -EPIPE) {
        fprintf(stderr, "Overrun occurred\n");
        err = snd_pcm_prepare(alsa_handle);
        if (err < 0) {
            fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
            return -1;
        }
        return 0;
    } else if (ret == -ESTRPIPE) {
        fprintf(stderr, "Suspend occurred\n");
        err = snd_pcm_resume(alsa_handle);
        if (err < 0) {
            fprintf(stderr, "snd_pcm_resume failed: %s\n", snd_strerror(err));
            return -1;
        }
        return 0;
    } else if (ret < 0) {
        fprintf(stderr, "Error from readi: %s\n", snd_strerror(ret));
        return -1;
    } else if (ret != (snd_pcm_sframes_t)frames) {
        fprintf(stderr, "Short read, ret=%li\n", ret);
        return 0;
    }
    return 1;
}

static double calculate_rms(const short *buffer, int frames) {
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double val = (double)buffer[i];
        sum_sq += val * val;
    }
    return sqrt(sum_sq / (double)frames);
}
