#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

#define ENABLE_PON 0x01
#define ENABLE_AEN 0x02
#define ATIME_154MS 0xFF
#define CONTROL_AGAIN_4X 0x02

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int tcs34725_init(int handle) {
    if (i2c_write_byte(handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000);
    if (i2c_write_byte(handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, ENABLE_PON | ENABLE_AEN) < 0)
        return -1;
    if (i2c_write_byte(handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, ATIME_154MS) < 0)
        return -1;
    if (i2c_write_byte(handle, TCS34725_COMMAND_BIT | TCS34725_CONTROL, CONTROL_AGAIN_4X) < 0)
        return -1;
    return 0;
}

static int tcs34725_read_data(int handle, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (i2c_read_word(handle, TCS34725_CDATA, c) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATA, r) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATA, g) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATA, b) < 0) return -1;
    return 0;
}

static void log_data(FILE *f, uint16_t c, uint16_t r, uint16_t g, uint16_t b) {
    time_t now = time(NULL);
    fprintf(f, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b);
    fflush(f);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        perror("Failed to open color_data.csv");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(fp, "timestamp,C,R,G,B\n");
    fflush(fp);

    while (running) {
        uint16_t c, r, g, b;
        if (tcs34725_read_data(i2c_handle, &c, &r, &g, &b) == 0) {
            log_data(fp, c, r, g, b);
        } else {
            fprintf(stderr, "Failed to read sensor data, logging zeros\n");
            log_data(fp, 0, 0, 0, 0);
        }
        gpioDelay(500000);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (fp) fclose(fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

