#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 50400

#define PWM_RANGE 100

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: Failed to write to GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

void turn_off_all_relays() {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        gpioWrite(pins[i], 1);
    }
}

void cleanup() {
    turn_off_all_relays();
    gpioTerminate();
}

void set_relay_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", pin);
    }
}

void simulate_sunrise(int duration) {
    time_t start_time = time(NULL);
    int current_duty = 0;

    while (running && (time(NULL) - start_time) < duration) {
        current_duty = (int)(((time(NULL) - start_time) / (float)duration) * PWM_RANGE);
        if (current_duty > PWM_RANGE) current_duty = PWM_RANGE;

        set_relay_state(RELAY1_PIN, current_duty > 0 ? 0 : 1);
        set_relay_state(RELAY2_PIN, current_duty > 0 ? 0 : 1);
        set_relay_state(RELAY3_PIN, current_duty > 0 ? 0 : 1);
        set_relay_state(RELAY4_PIN, current_duty > 0 ? 0 : 1);

        gpioDelay(100000);
    }
}

void simulate_daytime(int duration) {
    time_t start_time = time(NULL);

    while (running && (time(NULL) - start_time) < duration) {
        gpioDelay(100000);
    }
}

void simulate_sunset(int duration) {
    time_t start_time = time(NULL);
    int current_duty = PWM_RANGE;

    while (running && (time(NULL) - start_time) < duration) {
        current_duty = PWM_RANGE - (int)(((time(NULL) - start_time) / (float)duration) * PWM_RANGE);
        if (current_duty < 0) current_duty = 0;

        set_relay_state(RELAY1_PIN, current_duty > 0 ? 0 : 1);
        set_relay_state(RELAY2_PIN, current_duty > 0 ? 0 : 1);
        set_relay_state(RELAY3_PIN, current_duty > 0 ? 0 : 1);
        set_relay_state(RELAY4_PIN, current_duty > 0 ? 0 : 1);

        gpioDelay(100000);
    }
}

void simulate_nighttime(int duration) {
    time_t start_time = time(NULL);

    while (running && (time(NULL) - start_time) < duration) {
        gpioDelay(100000);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_gpio() != 0) {
        return 1;
    }

    while (running) {
        simulate_sunrise(SUNRISE_DURATION);
        if (!running) break;

        simulate_daytime(DAYTIME_DURATION);
        if (!running) break;

        simulate_sunset(SUNSET_DURATION);
        if (!running) break;

        simulate_nighttime(NIGHTTIME_DURATION);
    }

    cleanup();
    return 0;
}

