#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <math.h>
#include <pigpio.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

#define SAMPLE_PERIOD_US 10000
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpu6050_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int mpu6050_init(int handle) {
    if (mpu6050_write_reg(handle, PWR_MGMT_1, 0x00) < 0) return -1;
    gpioDelay(100000);
    if (mpu6050_write_reg(handle, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int mpu6050_read_gyro(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, GYRO_XOUT_H, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(FILE *fp, double timestamp, int16_t x, int16_t y, int16_t z) {
    fprintf(fp, "%.3f,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (mpu6050_init(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing MPU6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    fflush(log_file);

    int reinit_count = 0;

    while (running) {
        int16_t x, y, z;
        if (mpu6050_read_gyro(i2c_handle, &x, &y, &z) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
            log_data(log_file, timestamp, x, y, z);
            reinit_count = 0;
        } else {
            fprintf(stderr, "Gyro read failed, attempt %d/%d\n", reinit_count + 1, MAX_REINIT_ATTEMPTS);
            if (reinit_count < MAX_REINIT_ATTEMPTS) {
                if (mpu6050_init(i2c_handle) == 0) {
                    fprintf(stderr, "Re-initialization successful\n");
                } else {
                    fprintf(stderr, "Re-initialization failed\n");
                }
                reinit_count++;
            } else {
                fprintf(stderr, "Max re-initialization attempts reached, continuing...\n");
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "Shutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

