static void log_data(int moisture_level, int relay_states[4]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open\n");
        return;
    }

    fprintf(log_file, "%s, Moisture: %d, Relay 1: %d, Relay 2: %d, Relay 3: %d, Relay 4: %d\n",
            timestamp, moisture_level, relay_states[0], relay_states[1], relay_states[2], relay_states[3]);
    fflush(log_file);
}

static void cleanup(void) {
    int pins[] = {RELAY_1, RELAY_2, RELAY_3, RELAY_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioWrite(pins[i], 1);
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: cannot install SIGINT handler\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_states[4] = {0, 0, 0, 0};

    while (running) {
        int moisture_level = read_moisture_sensor();

        if (moisture_level < MOISTURE_THRESHOLD) {
            control_relay(RELAY_1, 0);
            control_relay(RELAY_2, 0);
            control_relay(RELAY_3, 0);
            control_relay(RELAY_4, 0);
            relay_states[0] = 0;
            relay_states[1] = 0;
            relay_states[2] = 0;
            relay_states[3] = 0;
        } else {
            control_relay(RELAY_1, 1);
            control_relay(RELAY_2, 1);
            control_relay(RELAY_3, 1);
            control_relay(RELAY_4, 1);
            relay_states[0] = 1;
            relay_states[1] = 1;
            relay_states[2] = 1;
            relay_states[3] = 1;
        }

        log_data(moisture_level, relay_states);
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

