#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (SDO tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 registers */
#define ADXL345_REG_DEVID       0x00
#define ADXL345_REG_POWER_CTL   0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID           0xE5

/* Free-fall detection thresholds */
#define FREEFALL_THRESHOLD_G    0.2f
#define FREEFALL_DURATION_S     0.5f
#define FREEFALL_POLL_MS        100

/* Alarm GPIO */
#define ALARM_GPIO              27
#define ALARM_DURATION_S        5.0

/* Scaling factor for +/- 2g range (4 mg/LSB) */
#define SCALE_FACTOR_G          0.004f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* Read a single byte from an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* Read 6 bytes of acceleration data starting at DATAX0; returns 0 on success, -1 on error. */
static int adxl345_read_accel(int handle, float *x, float *y, float *z)
{
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read failed (got %d bytes): %s\n",
                rc, rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);

    *x = (float)raw_x * SCALE_FACTOR_G;
    *y = (float)raw_y * SCALE_FACTOR_G;
    *z = (float)raw_z * SCALE_FACTOR_G;
    return 0;
}

/* Log a free-fall event to freefall.log in CSV format. */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        perror("fopen(freefall.log)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z);
    } else {
        fprintf(fp, "TIMESTAMP_ERROR,%.3f,%.3f,%.3f\n", x, y, z);
    }

    fclose(fp);
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ADXL345 address */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    uint8_t devid = 0;
    if (adxl345_read_reg(g_i2c_handle, ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read DEVID — sensor absent or bus error\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "DEVID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Standby → configure → measure */
    if (adxl345_write_reg(g_i2c_handle, ADXL345_REG_POWER_CTL, 0x00) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (adxl345_write_reg(g_i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (adxl345_write_reg(g_i2c_handle, ADXL345_REG_POWER_CTL, 0x08) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alarm GPIO */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", ALARM_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALARM_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", ALARM_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADXL345 free-fall detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float x, y, z;

        if (adxl345_read_accel(g_i2c_handle, &x, &y, &z) != 0) {
            /* I2C error — keep polling */
            gpioDelay(FREEFALL_POLL_MS * 1000);
            continue;
        }

        /* Detect free-fall: all three axes below threshold for 0.5 s */
        bool freefall = (fabsf(x) < FREEFALL_THRESHOLD_G &&
                         fabsf(y) < FREEFALL_THRESHOLD_G &&
                         fabsf(z) < FREEFALL_THRESHOLD_G);

        if (freefall) {
            /* Confirmation: wait 0.5 s and re-read */
            gpioDelay((int)(FREEFALL_DURATION_S * 1000.0));
            if (!g_running) break;

            if (adxl345_read_accel(g_i2c_handle, &x, &y, &z) != 0) {
                /* I2C error during confirmation — skip this event */
                continue;
            }

            if (fabsf(x) < FREEFALL_THRESHOLD_G &&
                fabsf(y) < FREEFALL_THRESHOLD_G &&
                fabsf(z) < FREEFALL_THRESHOLD_G) {

                printf("Free-fall confirmed — triggering alarm\n");
                log_freefall(x, y, z);

                if (gpioWrite(ALARM_GPIO, 1) != 0) {
                    fprintf(stderr, "gpioWrite(%d, 1) failed\n", ALARM_GPIO);
                }

                /* Hold alarm for 5 s, checking for shutdown every 100 ms */
                for (int i = 0; i < 50 && g_running; i++) {
                    gpioDelay(100000); /* 100 ms */
                }

                if (gpioWrite(ALARM_GPIO, 0) != 0) {
                    fprintf(stderr, "gpioWrite(%d, 0) failed\n", ALARM_GPIO);
                }
            }
        }

        gpioDelay(FREEFALL_POLL_MS * 1000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(ALARM_GPIO, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

