#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 23200
#define LOOP_DELAY_US 200000
#define MAX_VALID_PULSE_US 23200
#define TIMEOUT_ERROR -1
#define INVALID_PULSE_WIDTH -2
#define SUCCESS 0

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_state = 0;
static volatile int pulse_width_valid = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pthread_mutex_lock(&mutex);
        start_tick = tick;
        echo_state = 1;
        pulse_width_valid = 0;
        pthread_mutex_unlock(&mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&mutex);
        end_tick = tick;
        echo_state = 0;
        if (start_tick != 0) {
            uint32_t diff = end_tick - start_tick;
            if (diff <= ECHO_TIMEOUT_US) {
                pulse_width_valid = 1;
            } else {
                pulse_width_valid = 0;
            }
        }
        pthread_mutex_unlock(&mutex);
    }
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN high.\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN low.\n");
        return -1;
    }
    return 0;
}

static int read_distance(void) {
    if (trigger_sensor() < 0) {
        return TIMEOUT_ERROR;
    }

    uint32_t timeout_start = gpioTick();
    int pulse_width = -1;

    while (running) {
        pthread_mutex_lock(&mutex);
        int state = echo_state;
        int valid = pulse_width_valid;
        pthread_mutex_unlock(&mutex);

        if (state == 0 && valid) {
            pthread_mutex_lock(&mutex);
            uint32_t start = start_tick;
            uint32_t end = end_tick;
            pthread_mutex_unlock(&mutex);

            if (start == 0) {
                pulse_width = TIMEOUT_ERROR;
                break;
            }

            uint32_t diff = end - start;
            if (diff > MAX_VALID_PULSE_US) {
                pulse_width = INVALID_PULSE_WIDTH;
                break;
            }
            pulse_width = (int)diff;
            break;
        }

        if (gpioTick() - timeout_start > LOOP_DELAY_US) {
            pulse_width = TIMEOUT_ERROR;
            break;
        }
        gpioDelay(100);
    }

    return pulse_width;
}

static int log_distance(int distance) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%ld.%09ld,%d\n", (long)ts.tv_sec, ts.tv_nsec, distance) < 0) {
