#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x19
#define BUZZER_GPIO 17
#define FREE_FALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 1.5f
#define SAMPLE_DELAY_US 100000
#define RETRY_DELAY_US 10000
#define MAX_RETRIES 3

#define LIS3DH_REG_CTRL_REG1 0x20
#define LIS3DH_REG_CTRL_REG4 0x23
#define LIS3DH_REG_OUT_X_L 0x28

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int rc = i2cWriteByteData(i2c_handle, reg, value);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X), rc=%d, retry %d/%d\n",
                reg, value, rc, retries + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
        retries++;
    }
    return -1;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int rc = i2cReadByteData(i2c_handle, reg);
        if (rc >= 0) { *value = (uint8_t)rc; return 0; }
        fprintf(stderr, "I2C read failed (reg 0x%02X), rc=%d, retry %d/%d\n",
                reg, rc, retries + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
        retries++;
    }
    return -1;
}

static int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int rc = i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L, (char *)buf, 6);
        if (rc == 6) {
            *x = (int16_t)((buf[1] << 8) | buf[0]);
            *y = (int16_t)((buf[3] << 8) | buf[2]);
            *z = (int16_t)((buf[5] << 8) | buf[4]);
            return 0;
        }
        fprintf(stderr, "I2C block read failed, rc=%d, retry %d/%d\n", rc, retries + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
        retries++;
    }
    return -1;
}

static float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float fx = (float)x / 16384.0f;
    float fy = (float)y / 16384.0f;
    float fz = (float)z / 16384.0f;
    return sqrtf(fx * fx + fy * fy + fz * fz);
}

static void activate_buzzer(int duration_ms) {
    if (gpioWrite(BUZZER_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set buzzer GPIO high\n");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(BUZZER_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to set buzzer GPIO low\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float free_fall_threshold = FREE_FALL_THRESHOLD;
    float impact_threshold = IMPACT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "f:i:")) != -1) {
        switch (opt) {
            case 'f':
                free_fall_threshold = atof(optarg);
                if (free_fall_threshold <= 0.0f) {
                    fprintf(stderr, "Invalid free-fall threshold: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            case 'i':
                impact_threshold = atof(optarg);
                if (impact_threshold <= 0.0f) {
                    fprintf(stderr, "Invalid impact threshold: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-f free_fall_threshold] [-i impact_threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg(LIS3DH_REG_CTRL_REG1, 0x57) != 0) {
        fprintf(stderr, "Failed to configure LIS3DH (CTRL_REG1)\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_reg(LIS3DH_REG_CTRL_REG4, 0x08) != 0) {
        fprintf(stderr, "Failed to configure LIS3DH (CTRL_REG4)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Free-fall threshold: %.2f g, Impact threshold: %.2f g\n",
           free_fall_threshold, impact_threshold);
    printf("Press Ctrl+C to exit.\n");

    bool free_fall_detected = false;
    bool impact_detected = false;

    while (program_running) {
        int16_t x, y, z;
        if (read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read acceleration after retries, continuing\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (!free_fall_detected && magnitude < free_fall_threshold) {
            printf("Free-fall detected!\n");
            free_fall_detected = true;
        }

        if (free_fall_detected && magnitude > impact_threshold) {
            printf("Impact detected!\n");
            impact_detected = true;
            free_fall_detected = false;
        }

        if (impact_detected) {
            printf("Activating buzzer for 1 second...\n");
            activate_buzzer(1000);
            impact_detected = false;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

