    for (int i = 0; i < steps && running; i++) {
        set_motor_pins(pins, i % 4);
        gpioDelay(STEP_DELAY_US);
    }
}

static void trace_square(void) {
    int steps = (int)((SQUARE_SIZE_MM / 2.0) * STEPS_PER_REV);
    if (steps <= 0) {
        fprintf(stderr, "Error: invalid square size (%f mm).\n", SQUARE_SIZE_MM);
        return;
    }

    printf("Tracing a %d mm square (%d steps).\n", (int)SQUARE_SIZE_MM, steps);

    /* Move X-axis forward */
    step_motor(motor1_pins, steps);
    if (!running) return;

    /* Move Y-axis forward */
    step_motor(motor2_pins, steps);
    if (!running) return;

    /* Move X-axis backward */
    step_motor(motor1_pins, steps);
    if (!running) return;

    /* Move Y-axis backward */
    step_motor(motor2_pins, steps);
}

static void stop_motors(void) {
    for (int i = 0; i < 4; i++) {
        gpioWrite(motor1_pins[i], 0);
        gpioWrite(motor2_pins[i], 0);
    }
}

static void cleanup(void) {
    stop_motors();
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    trace_square();

    cleanup();
    return EXIT_SUCCESS;
}

