#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LIS3DH_ADDR_DEFAULT 0x19
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D
#define LIS3DH_WHO_AM_I 0x0F
#define LIS3DH_WHO_AM_I_VAL 0x33
#define LIS3DH_SENSITIVITY_2G 0.061f
#define LIS3DH_SENSITIVITY_4G 0.122f
#define LIS3DH_SENSITIVITY_8G 0.244f
#define LIS3DH_SENSITIVITY_16G 0.488f
#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;
    if (read_register(handle, LIS3DH_OUT_X_L, &x_l) < 0) return -1;
    if (read_register(handle, LIS3DH_OUT_X_H, &x_h) < 0) return -1;
    if (read_register(handle, LIS3DH_OUT_Y_L, &y_l) < 0) return -1;
    if (read_register(handle, LIS3DH_OUT_Y_H, &y_h) < 0) return -1;
    if (read_register(handle, LIS3DH_OUT_Z_L, &z_l) < 0) return -1;
    if (read_register(handle, LIS3DH_OUT_Z_H, &z_h) < 0) return -1;
    int16_t raw_x = (int16_t)((x_h << 8) | x_l);
    int16_t raw_y = (int16_t)((y_h << 8) | y_l);
    int16_t raw_z = (int16_t)((z_h << 8) | z_l);
    *x = (float)raw_x * LIS3DH_SENSITIVITY_2G;
    *y = (float)raw_y * LIS3DH_SENSITIVITY_2G;
    *z = (float)raw_z * LIS3DH_SENSITIVITY_2G;
    return 0;
}

static void log_data(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.2f, Y: %.2f, Z: %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    }
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down the system...\n");
    fflush(stdout);
    int rc = system("sudo shutdown -h now");
    if (rc == -1) {
        perror("system");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int i2c_address = LIS3DH_ADDR_DEFAULT;
    float threshold = 2.0f;
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < 0x03 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address: 0x%02X\n", i2c_address);
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address_hex] [-t threshold_g]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 0;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", i2c_address, i2c_handle);
        gpioTerminate();
        return 0;
    }

    uint8_t who_am_i = 0;
    if (read_register(i2c_handle, LIS3DH_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        cleanup();
        return 0;
    }
    if (who_am_i != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, LIS3DH_WHO_AM_I_VAL);
        cleanup();
        return 0;
    }

    if (write_register(i2c_handle, LIS3DH_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        cleanup();
        return 0;
    }
    if (write_register(i2c_handle, LIS3DH_CTRL_REG4, 0x08) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        cleanup();
        return 0;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return 0;
    }

    printf("Monitoring acceleration (threshold: %.2f g)...\n", threshold);
    fflush(stdout);

    while (!terminate) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
            log_data(x, y, z);
            shutdown_system();
            break;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

