#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN    4
#define CENTER_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define ALERT_PIN          22

#define BUFFER_SIZE        5
#define POLL_DELAY_US      10000   /* 10 ms */
#define ALERT_DURATION_US  2000000 /* 2 s  */
#define NO_LINE_THRESHOLD  5

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static CircularBuffer sensor_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void add_to_buffer(CircularBuffer *cb, SensorData sd) {
    cb->data[cb->head] = sd;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

static void move_forward(void) {
    printf("Moving forward\n");
}

static void turn_left(void) {
    printf("Turning left\n");
}

static void turn_right(void) {
    printf("Turning right\n");
}

static void stop_motion(void) {
    printf("Stopping\n");
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(alert HIGH) failed\n");
        return;
    }
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(alert LOW) failed\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0) {
