#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x30
#define RELAY_GPIO 17
#define MAG_THRESHOLD 5.0f
#define SAMPLE_INTERVAL_US 100000
#define POLL_TIMEOUT_MS 50
#define POLL_DELAY_US 1000

#define REG_CONFIG 0x00
#define REG_DATA 0x01
#define REG_STATUS 0x02

#define CONFIG_MAG_EN 0x01
#define STATUS_MAG_RDY 0x01

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *val = (uint8_t)data_buf[0];
    return 0;
}

static int init_sensor(void) {
    if (i2c_write_reg(REG_CONFIG, CONFIG_MAG_EN) != 0) {
        fprintf(stderr, "Error: Failed to enable magnetic sensor\n");
        return -1;
    }
    return 0;
}

static int read_magnetic_field(float *magnetic_field) {
    uint8_t status;
    int retries = 0;
    while (retries < POLL_TIMEOUT_MS) {
        if (i2c_read_reg(REG_STATUS, &status) != 0) return -1;
        if (status & STATUS_MAG_RDY) break;
        gpioDelay(POLL_DELAY_US);
        retries++;
    }
    if (retries >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Error: Magnetic data not ready after %d ms\n", POLL_TIMEOUT_MS);
        return -1;
    }
    uint8_t data_raw;
    if (i2c_read_reg(REG_DATA, &data_raw) != 0) return -1;
    *magnetic_field = (float)data_raw * 0.1f;
    return 0;
}

static void log_event(const char *event_type, float value) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open magnetic_events.txt for appending\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s - %s: %.2f mT\n", timestamp, event_type, value);
    fclose(fp);
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to relay GPIO %d\n", RELAY_GPIO);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed on bus %d addr 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set relay GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    control_relay(0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }
    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");
    while (program_running) {
        float magnetic_field;
        if (read_magnetic_field(&magnetic_field) != 0) {
            fprintf(stderr, "Error: Failed to read magnetic field, deactivating relay\n");
            control_relay(0);
            log_event("ERROR", 0.0f);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        log_event("READING", magnetic_field);
        if (magnetic_field > MAG_THRESHOLD) {
            control_relay(1);
            log_event("RELAY_ACTIVATED", magnetic_field);
        } else {
            control_relay(0);
            log_event("RELAY_DEACTIVATED", magnetic_field);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    control_relay(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    log_event("SHUTDOWN", 0.0f);
    return 0;
}

