#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay state on GPIO %d\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_socket(void) {
    struct sockaddr_in address;
    int opt = 1;

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        return -1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    printf("Listening on port %d...\n", PORT);
    return 0;
}

static void process_command(const char *command) {
    char buffer[BUFFER_SIZE];
    char *token = NULL;
    char *saveptr = NULL;
    int found = 0;

    strncpy(buffer, command, BUFFER_SIZE - 1);
    buffer[BUFFER_SIZE - 1] = '\0';

    token = strtok_r(buffer, " \t\r\n", &saveptr);
    while (token != NULL) {
        if (strcasecmp(token, "ON") == 0) {
            gpioWrite(RELAY_GPIO, 1);
            log_event("Relay turned ON");
            found = 1;
            break;
        } else if (strcasecmp(token, "OFF") == 0) {
            gpioWrite(RELAY_GPIO, 0);
            log_event("Relay turned OFF");
            found = 1;
            break;
        }
        token = strtok_r(NULL, " \t\r\n", &saveptr);
    }

    if (!found) {
        log_event("Invalid command received");
        printf("Invalid command: %s\n", command);
    }
}

