/*
 * Safety valve controller for two Sensirion SLF3S-1300F liquid-flow sensors.
 *
 * Hardware:
 *   - Raspberry Pi Zero W
 *   - Two SLF3S-1300F sensors on I2C bus 1 (addresses 0x22 and 0x23)
 *   - Safety relay on GPIO 18 (BCM), active-high
 *
 * Behavior:
 *   - Polls each sensor every 100 ms.
 *   - Validates CRC-8 (polynomial 0x31, init 0xFF, no final XOR).
 *   - Logs flow rates with millisecond timestamps to flow_log.txt.
 *   - Relay energizes when either sensor reports < 5.0 ml/min.
 *   - De-energizes when both sensors are >= 5.0 ml/min.
 *   - Clean shutdown on SIGINT/SIGTERM.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o safety_valve safety_valve.c -lpigpio -lrt
 *   (pigpio must be installed: sudo apt install pigpio)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define SENSOR1_ADDR         0x22
#define SENSOR2_ADDR         0x23
#define RELAY_GPIO           18
#define FLOW_THRESHOLD_ML_MIN 5.0f
#define POLL_INTERVAL_US     100000          /* 100 ms */
#define LOG_FILE             "flow_log.txt"
#define CRC8_POLY            0x31
#define CRC8_INIT            0xFF

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

/* --------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static void cleanup(void);
static uint8_t crc8(const uint8_t *data, int len);
static int  read_flow_rate(int handle, float *flow_out);
static void log_flow_data(float flow1, float flow2);
static void control_relay(bool on);

/* --------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioWrite(RELAY_GPIO, 0);   /* de-energize relay */
    gpioTerminate();
}

/* --------------------------- CRC-8 (Sensirion) ------------------------- */

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- Read flow rate ---------------------------- */

/*
 * SLF3S-1300F measurement:
 *   1. Start continuous measurement: write 0x36 0x2F (no clock stretching).
 *   2. Read 3 bytes: [MSB, LSB, CRC].
 *   3. CRC covers the two data bytes.
 *
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_flow_rate(int handle, float *flow_out)
{
    uint8_t cmd[2] = { 0x36, 0x2F };
    uint8_t buf[3];
    int rc;

    rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "[handle %d] i2cWriteDevice failed: %d\n", handle, rc);
        return -1;
    }

    /* Wait for the sensor to be ready (~1 ms max) */
    gpioDelay(2000);

    rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "[handle %d] i2cReadDevice returned %d (expected 3)\n",
                handle, rc);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[handle %d] CRC mismatch: calc=0x%02X recv=0x%02X\n",
                handle, crc8(buf, 2), buf[2]);
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 100.0f;   /* 100 LSB per ml/min */
    return 0;
}

/* --------------------------- Log flow data ----------------------------- */

static void log_flow_data(float flow1, float flow2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, flow1, flow2);
    fflush(fp);
    fclose(fp);
}

/* --------------------------- Relay control ----------------------------- */

static void control_relay(bool on)
{
    int rc = gpioWrite(RELAY_GPIO, on ? 1 : 0);
    if (rc < 0)
        fprintf(stderr, "gpioWrite(%d) failed: %d\n", RELAY_GPIO, rc);
}

/* --------------------------- Main -------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);   /* start de-energized */

    /* Open I2C handles */
    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "i2cOpen(bus %d, addr 0x%02X) failed: %d\n",
                I2C_BUS, SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "i2cOpen(bus %d, addr 0x%02X) failed: %d\n",
                I2C_BUS, SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring flow sensors (0x%02X, 0x%02X) on I2C bus %d. "
           "Relay on GPIO %d. Ctrl+C to exit.\n",
           SENSOR1_ADDR, SENSOR2_ADDR, I2C_BUS, RELAY_GPIO);

    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        bool ok1 = false, ok2 = false;

        int rc1 = read_flow_rate(g_i2c_handle1, &flow1);
        if (rc1 == 0)
            ok1 = true;

        int rc2 = read_flow_rate(g_i2c_handle2, &flow2);
        if (rc2 == 0)
            ok2 = true;

        if (ok1 && ok2) {
            log_flow_data(flow1, flow2);

            bool below = (flow1 < FLOW_THRESHOLD_ML_MIN) ||
                         (flow2 < FLOW_THRESHOLD_ML_MIN);
            control_relay(below);
        } else {
            /* On read failure, skip this cycle without changing relay */
            if (!ok1)
                fprintf(stderr, "Sensor 1 read failed (rc=%d)\n", rc1);
            if (!ok2)
                fprintf(stderr, "Sensor 2 read failed (rc=%d)\n", rc2);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

