#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

/* ---- Timing constants (microseconds) ---- */
#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define STUCK_WINDOW_US   3000000  /* 3 s   */
#define STUCK_COUNT       3        /* polls before new trigger */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a GPIO pin; log and return true on success, false on failure. */
static bool gpio_write_checked(unsigned pin, int level, const char *label)
{
    if (gpioWrite(pin, level) != 0) {
        syslog(LOG_ERR, "gpioWrite(%u, %d) failed for %s", pin, level, label);
        return false;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Drive the motor: ENA=1, IN1=1, IN2=0  (forward).                    */
static bool motor_start(void)
{
    if (!gpio_write_checked(MOTOR_ENA_PIN, 1, "MOTOR_ENA")) return false;
    if (!gpio_write_checked(MOTOR_IN1_PIN, 1, "MOTOR_IN1")) return false;
    if (!gpio_write_checked(MOTOR_IN2_PIN, 0, "MOTOR_IN2")) return false;
    return true;
}

/* ------------------------------------------------------------------ */
/* Stop the motor: ENA=0, IN1=0, IN2=0.                                */
static bool motor_stop(void)
{
    if (!gpio_write_checked(MOTOR_ENA_PIN, 0, "MOTOR_ENA")) return false;
    if (!gpio_write_checked(MOTOR_IN1_PIN, 0, "MOTOR_IN1")) return false;
    if (!gpio_write_checked(MOTOR_IN2_PIN, 0, "MOTOR_IN2")) return false;
    return true;
}

