     * chunks so SIGINT/SIGTERM can interrupt us cleanly. */
    for (int elapsed = 0; elapsed < MOTOR_RUN_US && g_running; elapsed += 100000) {
        gpioDelay(100000);
    }

    return motor_stop();
}

/* ------------------------------------------------------------------ */
/* Close the window: motor forward for 5 s, then stop.                 */
static bool close_window(void)
{
    syslog(LOG_INFO, "Closing window (motor forward for %d ms)",
           MOTOR_RUN_US / 1000);
    return run_motor();
}

/* ------------------------------------------------------------------ */
/* Open the window: motor reverse for 5 s, then stop.                  */
static bool open_window(void)
{
    syslog(LOG_INFO, "Opening window (motor reverse for %d ms)",
           MOTOR_RUN_US / 1000);
    if (!gpio_write_checked(MOTOR_IN1_PIN, 0, "MOTOR_IN1")) return false;
    if (!gpio_write_checked(MOTOR_IN2_PIN, 1, "MOTOR_IN2")) return false;

    for (int elapsed = 0; elapsed < MOTOR_RUN_US && g_running; elapsed += 100000) {
        gpioDelay(100000);
    }

    return motor_stop();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting rain-activated window controller");

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN_SENSOR_PIN) failed");
        goto cleanup_gpio;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(RAIN_SENSOR_PIN) failed");
        goto cleanup_gpio;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(MOTOR_ENA_PIN) failed");
        goto cleanup_gpio;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(MOTOR_IN1_PIN) failed");
        goto cleanup_gpio;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(MOTOR_IN2_PIN) failed");
        goto cleanup_gpio;
    }

    /* Start with motor stopped */
    if (!motor_stop()) {
        syslog(LOG_ERR, "Failed to initialise motor to stopped state");
        goto cleanup_gpio;
    }

    /* ---- Main polling loop ---- */
    int stuck_count = 0;
    bool window_closed = false;

    while (g_running) {
        int rain = gpioRead(RAIN_SENSOR_PIN);
        if (rain < 0) {
            syslog(LOG_ERR, "gpioRead(RAIN_SENSOR_PIN) failed");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Sensor: DO low = rain present, DO high = dry */
        if (rain == 0 && !window_closed) {
            syslog(LOG_INFO, "Rain detected (DO low)");
            if (close_window()) {
                syslog(LOG_INFO, "Window closed successfully");
                window_closed = true;
                stuck_count = 0;
