            syslog(LOG_INFO, "Rain cleared (DO high)");
            if (open_window()) {
                syslog(LOG_INFO, "Window opened successfully");
                window_closed = false;
                stuck_count = 0;
            } else {
                syslog(LOG_ERR, "Failed to open window");
            }
