#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_BUTTON   21
#define UNLOCK_BUTTON 22
#define SERVO_PIN     18

#define LOCK_PULSE_US   2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US     200000
#define POLL_SLEEP_US   10000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_set_servo_pulsewidth(int pin, int pulsewidth) {
    if (gpioServo(pin, pulsewidth) < 0) {
        fprintf(stderr, "Error: gpioServo(pin=%d, pulse=%d) failed\n", pin, pulsewidth);
        return -1;
    }
    return 0;
}

static int safe_call_servo(int pin, int pulsewidth) {
    if (gpioServo(pin, pulsewidth) < 0) {
        fprintf(stderr, "Error: gpioServo(pin=%d, pulse=%d) failed\n", pin, pulsewidth);
        return -1;
    }
    return 0;
}

static int read_button(int gpio_pin) {
    int v = gpioRead(gpio_pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(pin=%d) failed\n", gpio_pin);
        return -1;
    }
    return v;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(pin=%d) failed\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(pin=%d) failed\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(pin=%d) failed\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(pin=%d) failed\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(pin=%d) failed\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int lock_state = read_button(LOCK_BUTTON);
        int unlock_state = read_button(UNLOCK_BUTTON);

        if (lock_state == 0) {
            if (safe_set_servo_pulsewidth(SERVO_PIN, LOCK_PULSE_US) == 0) {
                printf("Locking door...\n");
                fflush(stdout);
            }
            gpioDelay(DEBOUNCE_US);
        } else if (unlock_state == 0) {
            if (safe_set_servo_pulsewidth(SERVO_PIN, UNLOCK_PULSE_US) == 0) {
                printf("Unlocking door...\n");
                fflush(stdout);
            }
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_SLEEP_US);
    }

    printf("\nShutting down...\n");
    if (safe_set_servo_pulsewidth(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to stop servo\n");
    }
    gpioTerminate();
    printf("Door lock system stopped.\n");
    return EXIT_SUCCESS;
}

