/*
 * MPR121 Capacitive Touch Relay Controller for Raspberry Pi 5
 *
 * Wiring:
 *   MPR121 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MPR121 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MPR121 VDD -> 3.3V
 *   MPR121 GND -> GND
 *   Relay IN  -> GPIO17 (BCM)
 *   Relay VCC -> 5V (or 3.3V if relay module is 3.3V-safe)
 *   Relay GND -> GND
 *
 * Build: gcc -O2 -Wall -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:   sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPR121 I2C address (7-bit) ---- */
#define MPR121_ADDR 0x5A

/* ---- MPR121 register addresses ---- */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_E0TTH 0x41
#define MPR121_DEBOUNCE 0x5B
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F
#define MPR121_SOFTRESET_RELEASE 0x81

/* ---- GPIO pins (BCM numbering) ---- */
#define RELAY_PIN 17

/* ---- Timing constants ---- */
#define DEBOUNCE_MS 200
#define POLL_DELAY_US 10000  /* 10 ms */
#define RESET_DELAY_US 100000 /* 100 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Write one byte to an MPR121 register ---- */
static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n",
                reg, value, rc);
    }
    return rc;
}

/* ---- Read one byte from an MPR121 register ---- */
static int mpr121_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

/* ---- Initialize MPR121 ---- */
static int mpr121_init(int handle)
{
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(RESET_DELAY_US);

    /* Baseline filtering: rising (MHD, NHD, NCL, FDL) */
    if (mpr121_write_reg(handle, MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_R, 0x00) < 0) return -1;

    /* Debounce: 3 samples for both touch and release */
    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=00, SFI=10 -> 1 sample, 0.5 us rise/fall */
    if (mpr121_write_reg(handle, MPR121_AUTOCONFIG0, 0x10) < 0) return -1;
    /* CDT=00 -> 1 ms charge time */
    if (mpr121_write_reg(handle, MPR121_AUTOCONFIG1, 0x00) < 0) return -1;
    /* USL=16, LSL=0, TL=16 -> 16 us baseline tracking */
    if (mpr121_write_reg(handle, MPR121_USL, 0x10) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_LSL, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_TL, 0x10) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, no auto-config */
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;

    /* Release reset so MPR121 is operational */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET_RELEASE, 0x00) < 0) return -1;

    return 0;
}

/* ---- Read 12-bit touch status ---- */
static int mpr121_read_touch_status(int handle)
{
    int lo = mpr121_read_reg(handle, MPR121_TOUCHSTATUS_L);
    if (lo < 0) return -1;
    int hi = mpr121_read_reg(handle, MPR121_TOUCHSTATUS_H);
    if (hi < 0) return -1;
    return (hi << 8) | lo;
}

/* ---- Toggle relay ---- */
static void toggle_relay(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", pin);
        return;
    }
    if (gpioWrite(pin, !level) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", pin);
    }
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPR121 address */
    g_i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (addr 0x%02X): %d\n", MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Probe: read ELECTRODE_CONFIG to confirm sensor is present */
    int cfg = mpr121_read_reg(g_i2c_handle, MPR121_ELECTRODE_CONFIG);
    if (cfg < 0) {
        fprintf(stderr, "MPR121 not responding at 0x%02X\n", MPR121_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay pin */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", RELAY_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay controller running. Touch electrode 0 to toggle relay.\n");
    printf("Press Ctrl+C to exit.\n");

    bool relay_on = false;
    uint32_t last_touch_tick = 0;

    while (g_running) {
        int status = mpr121_read_touch_status(g_i2c_handle);
        if (status < 0) {
            fprintf(stderr, "Touch status read error; retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint32_t now = gpioTick();

        /* Electrode 0: rising edge with debounce */
        if ((status & 0x0001) && !relay_on) {
            if (now - last_touch_tick >= (uint32_t)(DEBOUNCE_MS * 1000)) {
                toggle_relay(RELAY_PIN);
                relay_on = !relay_on;
                last_touch_tick = now;
                printf("Relay toggled to %s\n", relay_on ? "ON" : "OFF");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

