#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <stdarg.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define SERVO_FREQ 50
#define SERVO_RANGE 180
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);

    if (log_file) {
        time_t t = time(NULL);
        struct tm tm;
        if (localtime_r(&t, &tm)) {
            fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d ",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec);
        }
        vfprintf(log_file, format, args);
        fputc('\n', log_file);
        fflush(log_file);
    }
}

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set servo pin mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set PIR pin mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        log_message(LOG_WARNING, "Failed to set PIR pull-down");
    }
    return 0;
}

static int init_socket(void) {
    struct sockaddr_in address;
    int opt = 1;

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_WARNING, "setsockopt failed: %s", strerror(errno));
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    log_message(LOG_INFO, "Listening on port %d", PORT);
    return 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid angle: %d", angle);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE +
                      (int)((float)angle / SERVO_RANGE * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        log_message(LOG_ERR, "gpioServo failed for angle %d", angle);
        return -1;
    }
    log_message(LOG_INFO, "Servo set to angle %d (pulse %d us)", angle, pulse_width);
    return 0;
}

static int read_pir_sensor(void) {
    int value = gpioRead(PIR_PIN);
    if (value < 0) {
        log_message(LOG_ERR, "gpioRead failed for PIR pin");
        return -1;
    }
    return value;
}

static void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t valread;

    while (running) {
        memset(buffer, 0, sizeof(buffer));
        valread = read(client_socket, buffer, sizeof(buffer) - 1);
        if (valread > 0) {
            buffer[valread] = '\0';
            buffer[strcspn(buffer, "\r\n")] = '\0';
            log_message(LOG_INFO, "Received: %s", buffer);

            if (strncmp(buffer, "PIR", 3) == 0) {
                int pir_value = read_pir_sensor();
                if (pir_value >= 0) {
                    char response[64];
                    snprintf(response, sizeof(response), "PIR:%d", pir_value);
                    if (send(client_socket, response, strlen(response), 0) < 0) {
                        log_message(LOG_ERR, "send failed: %s", strerror(errno));
                    }
                } else {
                    log_message(LOG_ERR, "Failed to read PIR sensor");
                }
            } else if (strncmp(buffer, "the library's API call", 21) == 0) {
                char *token = strtok(buffer, " ");
                if (token && strcmp(token, "the") == 0) {
                    token = strtok(NULL, " ");
                    if (token && strcmp(token, "library's") == 0) {
                        token = strtok(NULL, " ");
                        if (token && strcmp(token, "API") == 0) {
                            token = strtok(NULL, " ");
                            if (token && strcmp(token, "call") == 0) {
                                token = strtok(NULL, " ");
                                if (token) {
                                    int angle = atoi(token);
                                    if (angle >= 0 && angle <= 180) {
                                        if (set_servo_angle(angle) == 0) {
                                            if (send(client_socket, "OK", 2, 0) < 0) {
                                                log_message(LOG_ERR, "send failed: %s", strerror(errno));
                                            }
                                        } else {
                                            log_message(LOG_ERR, "Failed to set servo angle");
                                        }
                                    } else {
                                        log_message(LOG_ERR, "Invalid angle: %s", token);
                                    }
                                } else {
                                    log_message(LOG_ERR, "Missing angle in command");
                                }
                            } else {
                                log_message(LOG_ERR, "Invalid command format");
                            }
                        } else {
                            log_message(LOG_ERR, "Invalid command format");
                        }
                    } else {
                        log_message(LOG_ERR, "Invalid command format");
                    }
                } else {
                    log_message(LOG_ERR, "Invalid command format");
                }
            } else {
                log_message(LOG_ERR, "Unknown command: %s", buffer);
            }
        } else if (valread == 0) {
            log_message(LOG_INFO, "Client disconnected");
            break;
        } else {
            if (errno != EINTR) {
                log_message(LOG_ERR, "read failed: %s", strerror(errno));
            }
            break;
        }
    }
    close(client_socket);
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (init_gpio() != 0) {
        closelog();
        return 1;
    }

    if (init_socket() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Security system started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_socket < 0) {
            if (errno == EINTR && !running) {
                break;
            }
            if (errno != EINTR) {
                log_message(LOG_ERR, "accept failed: %s", strerror(errno));
            }
            continue;
        }
        log_message(LOG_INFO, "New connection from %s:%d",
                    inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
        handle_client(client_socket);
    }

    log_message(LOG_INFO, "Shutting down");
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    closelog();
    return 0;
}

