#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN  24
#define SOLENOID_PIN   25

#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE     1.0
#define DEFAULT_DURATION  200
#define NUM_TARE_READINGS 10
#define NUM_AVG_READINGS  5
#define MAX_RETRIES       3
#define POLL_INTERVAL_US  500000
#define HX711_TIMEOUT_US  1000000

static volatile sig_atomic_t running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale     = DEFAULT_SCALE;
static int    duration  = DEFAULT_DURATION;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int *out_value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int count = 0;
        int timeout = 0;

        /* Wait for DOUT to go LOW (data ready) */
        while (gpioRead(HX711_DOUT_PIN) == 1) {
            if (++timeout > HX711_TIMEOUT_US) {
                syslog(LOG_ERR, "HX711 DOUT timeout (DOUT stuck HIGH)");
                retries++;
                if (retries >= MAX_RETRIES) return -1;
                gpioDelay(1000);
                break;
            }
            gpioDelay(1);
        }
        if (retries >= MAX_RETRIES) return -1;

        /* Read 24 bits MSB-first */
        for (int i = 0; i < 24; i++) {
            gpioWrite(HX711_SCK_PIN, 1);
            gpioDelay(1);
            count <<= 1;
            if (gpioRead(HX711_DOUT_PIN)) count |= 1;
            gpioWrite(HX711_SCK_PIN, 0);
            gpioDelay(1);
        }

        /* 25th pulse selects Channel A, gain 128 */
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);

        /* Convert 24-bit two's complement to signed 32-bit */
        if (count & 0x800000) count |= 0xFF000000;

        *out_value = count;
        return 0;
    }
    return -1;
}

static double tare(int num_readings) {
    long sum = 0;
    for (int i = 0; i < num_readings; i++) {
        int val;
        if (read_hx711(&val) != 0) {
            syslog(LOG_ERR, "Tare read failed at iteration %d", i);
            return 0.0;
        }
        sum += val;
        gpioDelay(10000);
    }
    return (double)sum / num_readings;
}

static double read_weight(int num_readings) {
    long sum = 0;
    for (int i = 0; i < num_readings; i++) {
        int val;
        if (read_hx711(&val) != 0) {
            syslog(LOG_ERR, "Weight read failed at iteration %d", i);
            return 0.0;
        }
        sum += val;
        gpioDelay(10000);
    }
    return (double)sum / num_readings;
}

static void activate_solenoid(void) {
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH");
        return;
    }
    gpioDelay(duration * 1000);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW");
    }
}

static void parse_arguments(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--threshold") == 0 && i + 1 < argc) {
            threshold = atof(argv[++i]);
        } else if (strcmp(argv[i], "--scale") == 0 && i + 1 < argc) {
            scale = atof(argv[++i]);
        } else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc) {
            duration = atoi(argv[++i]);
        } else {
            fprintf(stderr, "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n", argv[0]);
            exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    parse_arguments(argc, argv);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DOUT_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set HX711_DOUT_PIN as input");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set HX711_SCK_PIN as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set SOLENOID_PIN as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        gpioWrite(SOLENOID_PIN, 0);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    double tare_offset = tare(NUM_TARE_READINGS);
    syslog(LOG_INFO, "Tare complete, offset: %.2f", tare_offset);

    while (running) {
        double weight = read_weight(NUM_AVG_READINGS) - tare_offset;
        weight *= scale;

        if (weight > threshold) {
            syslog(LOG_INFO, "Weight %.2f exceeds threshold %.2f", weight, threshold);
            activate_solenoid();
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

