/*
 * relay_controller.c — MQTT-controlled relay on Raspberry Pi 4 Model B
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c -lmosquitto -lgpiod
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>
#include <mosquitto.h>

#define MQTT_BROKER_HOST   "localhost"
#define MQTT_BROKER_PORT   1883
#define MQTT_CLIENT_ID     "relay_controller_1"
#define MQTT_TOPIC         "home/lights/control"
#define MQTT_KEEPALIVE     60
#define GPIO_CHIP_NAME     "gpiochip4"   /* BCM GPIO on Pi 4 */
#define GPIO_LINE_OFFSET   17            /* BCM 17, physical pin 11 */
#define POLL_INTERVAL_MS   100
#define RECONNECT_DELAY_S  5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s) failed: %s",
               GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE_OFFSET);
    if (!g_line) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d) failed: %s",
               GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_line, "relay_controller", 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_output failed: %s", strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_line = NULL;
        return -1;
    }

    syslog(LOG_INFO, "GPIO line %d configured as output, initial state LOW",
           GPIO_LINE_OFFSET);
    return 0;
}

static void gpio_set(int value)
{
    if (gpiod_line_set_value(g_line, value) < 0)
        syslog(LOG_ERR, "gpiod_line_set_value(%d) failed: %s",
               value, strerror(errno));
}

static void gpio_cleanup(void)
{
    if (g_line) {
        gpiod_line_set_value(g_line, 0);
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d (client id %s)",
               MQTT_BROKER_HOST, MQTT_BROKER_PORT, MQTT_CLIENT_ID);
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS)
            syslog(LOG_ERR, "mosquitto_subscribe(%s) failed: %s",
                   MQTT_TOPIC, mosquitto_strerror(rc));
        else
            syslog(LOG_INFO, "Subscribed to topic %s", MQTT_TOPIC);
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_connack_string(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)userdata;
    if (rc == MOSQ_ERR_SUCCESS)
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    else
        syslog(LOG_ERR, "MQTT unexpected disconnect: %s", mosquitto_strerror(rc));
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (!message->payload || message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty MQTT message on %s", message->topic);
        return;
    }

    /* NUL-terminate payload for safe string handling */
    char payload[256];
    size_t copy_len = (size_t)message->payloadlen < sizeof(payload) - 1
                      ? (size_t)message->payloadlen : sizeof(payload) - 1;
    memcpy(payload, message->payload, copy_len);
    payload[copy_len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        syslog(LOG_INFO, "Relay ON received on %s", message->topic);
        gpio_set(1);
    } else if (strcmp(payload, "OFF") == 0) {
        syslog(LOG_INFO, "Relay OFF received on %s", message->topic);
        gpio_set(0);
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' on %s", payload, message->topic);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT setup                                                          */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", strerror(errno));
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_BROKER_HOST,
                               MQTT_BROKER_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect(%s:%d) failed: %s",
               MQTT_BROKER_HOST, MQTT_BROKER_PORT, mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_loop_start(g_mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_loop_start failed: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

static void mqtt_cleanup(void)
{
    if (g_mosq) {
        mosquitto_loop_stop(g_mosq, false);
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_init() < 0) {
        syslog(LOG_ERR, "MQTT initialization failed");
        gpio_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Relay controller started");

    while (g_running) {
        sleep(1);
    }

    syslog(LOG_INFO, "Shutting down...");
    mqtt_cleanup();
    gpio_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

