{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s) failed: %s",
               GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE_OFFSET);
    if (!g_line) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d) failed: %s",
               GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_line, "relay_controller", 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_output failed: %s", strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_line = NULL;
        return -1;
    }

    syslog(LOG_INFO, "GPIO line %d configured as output, initial state LOW",
           GPIO_LINE_OFFSET);
    return 0;
}

static void gpio_set(int value)
{
    if (gpiod_line_set_value(g_line, value) < 0)
        syslog(LOG_ERR, "gpiod_line_set_value(%d) failed: %s",
               value, strerror(errno));
}

static void gpio_cleanup(void)
{
    if (g_line) {
        gpiod_line_set_value(g_line, 0);
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d (client id %s)",
               MQTT_BROKER_HOST, MQTT_BROKER_PORT, MQTT_CLIENT_ID);
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS)
            syslog(LOG_ERR, "mosquitto_subscribe(%s) failed: %s",
                   MQTT_TOPIC, mosquitto_strerror(rc));
        else
            syslog(LOG_INFO, "Subscribed to topic %s", MQTT_TOPIC);
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_connack_string(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)userdata;
    if (rc == MOSQ_ERR_SUCCESS)
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    else
        syslog(LOG_ERR, "MQTT unexpected disconnect: %s", mosquitto_strerror(rc));
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (!message->payload || message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty MQTT message on %s", message->topic);
        return;
    }

