    char payload[256];
    size_t copy_len = (size_t)message->payloadlen < sizeof(payload) - 1
                      ? (size_t)message->payloadlen : sizeof(payload) - 1;
    memcpy(payload, message->payload, copy_len);
    payload[copy_len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        syslog(LOG_INFO, "Relay ON received on %s", message->topic);
        gpio_set(1);
    } else if (strcmp(payload, "OFF") == 0) {
        syslog(LOG_INFO, "Relay OFF received on %s", message->topic);
        gpio_set(0);
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' on %s", payload, message->topic);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT setup                                                          */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", strerror(errno));
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
