#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

#define SERVO_1_TARGET 1000
#define SERVO_2_TARGET 1500
#define SERVO_3_TARGET 2000
#define SERVO_4_TARGET 500
#define SERVO_5_TARGET 2500

#define PWM_FREQUENCY 50
#define PWM_RANGE 1000

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int targets[] = {SERVO_1_TARGET, SERVO_2_TARGET, SERVO_3_TARGET, SERVO_4_TARGET, SERVO_5_TARGET};
    int num_servos = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_servos; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    for (int i = 0; i < num_servos; i++) {
        if (gpioServo(pins[i], targets[i]) != 0) {
            fprintf(stderr, "Failed to start PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    sleep(3);

    for (int i = 0; i < num_servos; i++) {
        gpioServo(pins[i], 0);
    }

    gpioTerminate();
    return 0;
}

