#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM_PIN      17
#define MOTOR_A_DIR_PIN      18
#define MOTOR_B_PWM_PIN      22
#define MOTOR_B_DIR_PIN      23
#define ENCODER_A_PHASE_A_PIN 4
#define ENCODER_A_PHASE_B_PIN 5
#define ENCODER_B_PHASE_A_PIN 6
#define ENCODER_B_PHASE_B_PIN 12

/* ---- Motor parameters ---- */
#define PWM_FREQUENCY_HZ     10000   /* 10 kHz */
#define PWM_RANGE            255
#define TICKS_PER_REVOLUTION 64
#define ENCODER_TO_OUTPUT_RATIO 1.0
#define TARGET_RPM           50.0
#define CONTROL_PERIOD_US    100000  /* 100 ms */
#define STALL_TIMEOUT_S      2

/* ---- Anti-windup parameters ---- */
#define KP                   0.1
#define KI                   0.01
#define INTEGRAL_LIMIT       100.0

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static volatile int32_t g_encoder_a_ticks = 0;
static volatile int32_t g_encoder_b_ticks = 0;
static volatile uint32_t g_encoder_a_stall_start = 0;
static volatile uint32_t g_encoder_b_stall_start = 0;
static volatile bool g_encoder_a_stalled = false;
static volatile bool g_encoder_b_stalled = false;

static pthread_mutex_t g_encoder_a_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t g_encoder_b_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void set_motor_direction(int pwm_pin, int dir_pin, int direction);
static void set_motor_pwm(int pwm_pin, int duty_cycle);
static void stop_motors(void);
static double calculate_rpm(int32_t ticks, double ratio, double period_s);
static void control_loop(void);
static void cleanup(void);

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Encoder ISRs ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        pthread_mutex_lock(&g_encoder_a_mutex);
        g_encoder_a_ticks++;
        pthread_mutex_unlock(&g_encoder_a_mutex);
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        pthread_mutex_lock(&g_encoder_b_mutex);
        g_encoder_b_ticks++;
        pthread_mutex_unlock(&g_encoder_b_mutex);
    }
}

/* ---- Motor helpers ---- */
static void set_motor_direction(int pwm_pin, int dir_pin, int direction) {
    if (direction == 1) {
        gpioWrite(pwm_pin, 1);
        gpioWrite(dir_pin, 0);
    } else if (direction == -1) {
        gpioWrite(pwm_pin, 1);
        gpioWrite(dir_pin, 1);
    } else {
        gpioWrite(pwm_pin, 0);
        gpioWrite(dir_pin, 0);
    }
}

static void set_motor_pwm(int pwm_pin, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(pwm_pin, duty_cycle);
}

static void stop_motors(void) {
    set_motor_pwm(MOTOR_A_PWM_PIN, 0);
    set_motor_pwm(MOTOR_B_PWM_PIN, 0);
    set_motor_direction(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, 0);
    set_motor_direction(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, 0);
}

/* ---- RPM calculation ---- */
static double calculate_rpm(int32_t ticks, double ratio, double period_s) {
    if (period_s <= 0.0) return 0.0;
    return ((double)ticks * ratio * 60.0) / (TICKS_PER_REVOLUTION * period_s);
}

/* ---- Control loop ---- */
static void control_loop(void) {
    double integral_a = 0.0;
    double integral_b = 0.0;
    double last_error_a = 0.0;
    double last_error_b = 0.0;
    double period_s = (double)CONTROL_PERIOD_US / 1e6;

    while (g_running) {
        /* ---- Read and reset encoder ticks ---- */
        int32_t enc_a_ticks = 0;
        int32_t enc_b_ticks = 0;

        pthread_mutex_lock(&g_encoder_a_mutex);
        enc_a_ticks = g_encoder_a_ticks;
        g_encoder_a_ticks = 0;
        pthread_mutex_unlock(&g_encoder_a_mutex);

        pthread_mutex_lock(&g_encoder_b_mutex);
        enc_b_ticks = g_encoder_b_ticks;
        g_encoder_b_ticks = 0;
        pthread_mutex_unlock(&g_encoder_b_mutex);

        /* ---- RPM calculation ---- */
        double rpm_a = calculate_rpm(enc_a_ticks, ENCODER_TO_OUTPUT_RATIO, period_s);
        double rpm_b = calculate_rpm(enc_b_ticks, ENCODER_TO_OUTPUT_RATIO, period_s);

        /* ---- Stall detection ---- */
        uint32_t now = (uint32_t)time(NULL);

        if (enc_a_ticks == 0) {
            if (!g_encoder_a_stalled) {
                g_encoder_a_stalled = true;
                g_encoder_a_stall_start = now;
                fprintf(stderr, "Encoder A stalled (no ticks for %d s)\n", STALL_TIMEOUT_S);
            }
        } else {
            g_encoder_a_stalled = false;
        }

        if (enc_b_ticks == 0) {
            if (!g_encoder_b_stalled) {
                g_encoder_b_stalled = true;
                g_encoder_b_stall_start = now;
                fprintf(stderr, "Encoder B stalled (no ticks for %d s)\n", STALL_TIMEOUT_S);
            }
        } else {
            g_encoder_b_stalled = false;
        }

        /* ---- Anti-windup PI control ---- */
        double error_a = TARGET_RPM - rpm_a;
        double error_b = TARGET_RPM - rpm_b;

        integral_a += error_a * period_s;
        integral_b += error_b * period_s;

        if (integral_a > INTEGRAL_LIMIT) integral_a = INTEGRAL_LIMIT;
        if (integral_a < -INTEGRAL_LIMIT) integral_a = -INTEGRAL_LIMIT;
        if (integral_b > INTEGRAL_LIMIT) integral_b = INTEGRAL_LIMIT;
        if (integral_b < -INTEGRAL_LIMIT) integral_b = -INTEGRAL_LIMIT;

        double pwm_a = (int)(KP * error_a + KI * integral_a);
        double pwm_b = (int)(KP * error_b + KI * integral_b);

        if (pwm_a < 0) { pwm_a = 0; integral_a -= error_a * period_s; }
        if (pwm_a > PWM_RANGE) { pwm_a = PWM_RANGE; integral_a -= error_a * period_s; }
