#define TARGET_RPM           50.0
#define CONTROL_PERIOD_US    100000  /* 100 ms */
#define STALL_TIMEOUT_S      2

/* ---- Anti-windup parameters ---- */
#define KP                   0.1
#define KI                   0.01
#define INTEGRAL_LIMIT       100.0

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static volatile int32_t g_encoder_a_ticks = 0;
static volatile int32_t g_encoder_b_ticks = 0;
static volatile uint32_t g_encoder_a_stall_start = 0;
static volatile uint32_t g_encoder_b_stall_start = 0;
static volatile bool g_encoder_a_stalled = false;
static volatile bool g_encoder_b_stalled = false;

static pthread_mutex_t g_encoder_a_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t g_encoder_b_mutex = PTHREAD_MUTEX_INITIALIZER;

