        enc_b_ticks = g_encoder_b_ticks;
        g_encoder_b_ticks = 0;
        pthread_mutex_unlock(&g_encoder_b_mutex);

        /* ---- RPM calculation ---- */
        double rpm_a = calculate_rpm(enc_a_ticks, ENCODER_TO_OUTPUT_RATIO, period_s);
        double rpm_b = calculate_rpm(enc_b_ticks, ENCODER_TO_OUTPUT_RATIO, period_s);

        /* ---- Stall detection ---- */
        uint32_t now = (uint32_t)time(NULL);

        if (enc_a_ticks == 0) {
            if (!g_encoder_a_stalled) {
