        set_motor_direction(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, dir_a);
        set_motor_direction(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, dir_b);

        set_motor_pwm(MOTOR_A_PWM_PIN, (int)pwm_a);
        set_motor_pwm(MOTOR_B_PWM_PIN, (int)pwm_b);

        printf("Motor A: RPM=%.2f, PWM=%.2f, Dir=%d | Motor B: RPM=%.2f, PWM=%.2f, Dir=%d\n",
               rpm_a, pwm_a, dir_a, rpm_b, pwm_b, dir_b);

