#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define POLL_INTERVAL_SEC 5
#define BH1750_CONV_TIME_MS 180
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_RELAY);
        return -1;
    }
    if (gpioWrite(GPIO_RELAY, 0) != 0) {
        fprintf(stderr, "Error writing 0 to GPIO %d\n", GPIO_RELAY);
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static int read_lux(void) {
    char cmd = 0x10;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing mode command to BH1750\n");
        return -1;
    }
    gpioDelay(BH1750_CONV_TIME_MS * 1000);
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750\n");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static void log_data(int lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0 || init_gpio() != 0 || init_log() != 0) {
        cleanup();
        return 1;
    }

    int relay_state = 0;
    int first_read = 1;

    while (running) {
        int lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Sensor read error, turning relay off for safety\n");
            if (gpioWrite(GPIO_RELAY, 0) != 0) {
                fprintf(stderr, "Error turning relay off\n");
            }
            relay_state = 0;
            log_data(-1, relay_state);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (first_read) {
            relay_state = (lux < LUX_THRESHOLD_DUSK) ? 1 : 0;
            if (gpioWrite(GPIO_RELAY, relay_state) != 0) {
                fprintf(stderr, "Error setting relay initial state\n");
            }
            first_read = 0;
        } else {
            if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
                if (gpioWrite(GPIO_RELAY, 1) == 0) {
                    relay_state = 1;
                    log_data(lux, relay_state);
                } else {
                    fprintf(stderr, "Error turning relay on\n");
                }
            } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
                if (gpioWrite(GPIO_RELAY, 0) == 0) {
                    relay_state = 0;
                    log_data(lux, relay_state);
                } else {
                    fprintf(stderr, "Error turning relay off\n");
                }
            }
        }

        log_data(lux, relay_state);
        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

