    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0 || init_gpio() != 0 || init_log() != 0) {
        cleanup();
        return 1;
    }

    int relay_state = 0;
    int first_read = 1;

    while (running) {
        int lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Sensor read error, turning relay off for safety\n");
            if (gpioWrite(GPIO_RELAY, 0) != 0) {
                fprintf(stderr, "Error turning relay off\n");
            }
            relay_state = 0;
            log_data(-1, relay_state);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (first_read) {
            relay_state = (lux < LUX_THRESHOLD_DUSK) ? 1 : 0;
            if (gpioWrite(GPIO_RELAY, relay_state) != 0) {
                fprintf(stderr, "Error setting relay initial state\n");
            }
            first_read = 0;
        } else {
            if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
                if (gpioWrite(GPIO_RELAY, 1) == 0) {
                    relay_state = 1;
                    log_data(lux, relay_state);
                } else {
                    fprintf(stderr, "Error turning relay on\n");
                }
            } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
                if (gpioWrite(GPIO_RELAY, 0) == 0) {
                    relay_state = 0;
                    log_data(lux, relay_state);
                } else {
                    fprintf(stderr, "Error turning relay off\n");
                }
            }
        }

        log_data(lux, relay_state);
        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

