        if (touch_state < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            debounce_counter = 0;
        } else if (touch_state == 1 && last_touch_state == 1) {
            debounce_counter++;
            if (debounce_counter >= 50) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Failed to write GPIO %d\n", RELAY_PIN);
                    break;
                }
                log_relay_state(relay_state);
                debounce_counter = 0;
            }
        } else if (touch_state == 0) {
            debounce_counter = 0;
        }

        last_touch_state = touch_state;
        gpioDelay(LOOP_DELAY_US);
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to turn off relay during cleanup\n");
    }
    gpioTerminate();
    printf("Touch-toggled relay system stopped.\n");
    return EXIT_SUCCESS;
}

