                fprintf(stderr, "Failed to write solenoid pin\n");
            }
        } else if (lpm < LPM_HYSTERESIS && solenoid_state == 0) {
            if (gpioWrite(SOLENOID_PIN, 1) == 0) {
                solenoid_state = 1;
                log_event("Solenoid valve reopened");
            } else {
                fprintf(stderr, "Failed to write solenoid pin\n");
            }
        }
    }

    log_event("Program terminating");
    gpioWrite(SOLENOID_PIN, 1);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    return EXIT_SUCCESS;
}

