#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int relay_state = 0;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int toggle_relay(void) {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "gpioWrite failed on relay pin %d: %s\n", RELAY_PIN, strerror(errno));
        return -1;
    }
    log_relay_state(relay_state);
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for touch sensor pin %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for relay pin %d: %s\n", RELAY_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite failed to set relay pin %d LOW: %s\n", RELAY_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Invalid debounce value: %s. Using default %d ms.\n", optarg, DEFAULT_DEBOUNCE_MS);
                    debounce_ms = DEFAULT_DEBOUNCE_MS;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started on GPIO %d. Relay on GPIO %d. Debounce: %d ms. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN, debounce_ms);

    int last_touch_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_touch_state < 0) {
        fprintf(stderr, "gpioRead failed on touch sensor pin %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    uint32_t last_toggle_tick = gpioTick();

    while (running) {
        int current_touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_touch_state < 0) {
            fprintf(stderr, "gpioRead failed on touch sensor pin %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
            break;
        }

        if (current_touch_state == 1 && last_touch_state == 0) {
            uint32_t now = gpioTick();
            if ((now - last_toggle_tick) >= (uint32_t)(debounce_ms * 1000)) {
                if (toggle_relay() != 0) {
                    break;
                }
                last_toggle_tick = now;
            }
        }

        last_touch_state = current_touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    cleanup_gpio();
    printf("Touch sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

