#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_DEFAULT_ANGLE 90
#define ANGLE_INCREMENT 10
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000

static volatile sig_atomic_t g_running = 1;
static struct termios g_orig_termios;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_terminal_raw(void) {
    struct termios t;
    if (tcgetattr(STDIN_FILENO, &t) != 0) {
        perror("tcgetattr");
        return -1;
    }
    g_orig_termios = t;
    t.c_lflag &= ~(ICANON | ECHO);
    t.c_cc[VMIN] = 1;
    t.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &t) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static void restore_terminal(void) {
    if (tcsetattr(STDIN_FILENO, TCSANOW, &g_orig_termios) != 0) {
        perror("tcsetattr restore");
    }
}

static int angle_to_pulse_width(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return SERVO_MIN_PULSE_WIDTH +
           (int)((long)angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180);
}

int main(void) {
    int angle = SERVO_DEFAULT_ANGLE;
    int pw;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (set_terminal_raw() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SERVO_PIN);
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", SERVO_PIN);
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", SERVO_PIN);
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pw = angle_to_pulse_width(angle);
    if (gpioServo(SERVO_PIN, pw) != 0) {
        fprintf(stderr, "Failed to start PWM on GPIO %d\n", SERVO_PIN);
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo angle: %d degrees (pulse width: %d us)\n", angle, pw);
    printf("Press +/- to adjust angle, 'q' to quit.\n");
    fflush(stdout);

    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            if (errno != EINTR) {
                perror("getchar");
                break;
            }
            continue;
        }

        if (c == '+') {
            angle += ANGLE_INCREMENT;
            if (angle > 180) angle = 180;
        } else if (c == '-') {
            angle -= ANGLE_INCREMENT;
            if (angle < 0) angle = 0;
        } else if (c == 'q') {
            break;
        } else {
            continue;
        }

        pw = angle_to_pulse_width(angle);
        if (gpioServo(SERVO_PIN, pw) != 0) {
            fprintf(stderr, "Failed to set servo pulse width\n");
            break;
        }
        printf("Servo angle: %d degrees (pulse width: %d us)\n", angle, pw);
        fflush(stdout);
    }

    gpioServo(SERVO_PIN, 0);
    restore_terminal();
    gpioTerminate();
    return EXIT_SUCCESS;
}

