code:
/*
 * Conveyor belt RPM monitor using an A3144 Hall-effect sensor.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: A3144 on GPIO17 (BCM 17, physical pin 11)
 * Wiring:
 *   A3144 VCC -> 3.3 V (pin 1)
 *   A3144 GND -> GND   (pin 9)
 *   A3144 OUT -> GPIO17 (pin 11)
 *   A3144 I/O -> GND   (internal pull-up enabled)
 *
 * Build:  gcc -O2 -Wall -Wextra -o motor_rpm motor_rpm.c -lpigpio -lrt
 * Run:    sudo ./motor_rpm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN          17
#define DEBOUNCE_US       2000          /* 2 ms debounce window            */
#define SAMPLE_PERIOD_S   5             /* 5-second sampling interval       */
#define LOG_FILE          "motor_rpm.log"

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Return monotonic seconds elapsed since program start.
 * clock_gettime() is used with CLOCK_MONOTONIC, which is guaranteed
 * to be a monotonically increasing clock that does not suffer from
 * clock-tick glitches on a single-core Pi.
 */
static double elapsed_seconds(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0.0;
    }
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;
}

/*
 * Write a CSV line: timestamp,rpm\n
 * Returns 0 on success, -1 on failure.
 */
static int log_rpm(FILE *fp, double rpm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, rpm) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int      rc;
    uint32_t last_tick = 0;
    uint32_t pulse_count = 0;
    double   last_sample_time = 0.0;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "gpioInitialise() failed: %d\n", rc);
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input with internal pull-up ---- */
    rc = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed: %d\n", GPIO_PIN, rc);
        gpioTerminate();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    rc = gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (rc != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed: %d\n", GPIO_PIN, rc);
        gpioTerminate();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Register edge-triggered alert ---- */
    rc = gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);   /* deregister first */
    if (rc != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(%d, NULL) failed: %d\n", GPIO_PIN, rc);
        gpioTerminate();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    rc = gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);   /* re-register */
    if (rc != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(%d, NULL) failed: %d\n", GPIO_PIN, rc);
        gpioTerminate();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Main sampling loop ---- */
    while (g_running) {
        double now = elapsed_seconds();

        if (now - last_sample_time >= (double)SAMPLE_PERIOD_S) {
            double elapsed = now - last_sample_time;
            double rpm = (double)pulse_count / elapsed * 60.0;

            printf("RPM: %.2f\n", rpm);
            fflush(stdout);

            if (log_rpm(g_log_fp, rpm) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }

            pulse_count = 0;
            last_sample_time = now;
        }

        /*
         * Sleep for 100 ms to avoid busy-waiting while pigpio's
         * alert callbacks are serviced.
         */
        gpioDelay(100000);   /* 100 ms */
    }

    /* ---- Cleanup ---- */
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);   /* deregister callback */
    gpioTerminate();

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    return EXIT_SUCCESS;
}

