        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input with internal pull-up ---- */
    rc = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed: %d\n", GPIO_PIN, rc);
        gpioTerminate();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    rc = gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (rc != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed: %d\n", GPIO_PIN, rc);
        gpioTerminate();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Register edge-triggered alert ---- */
    rc = gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);   /* deregister first */
    if (rc != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(%d, NULL) failed: %d\n", GPIO_PIN, rc);
        gpioTerminate();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    rc = gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);   /* re-register */
    if (rc != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(%d, NULL) failed: %d\n", GPIO_PIN, rc);
        gpioTerminate();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Main sampling loop ---- */
    while (g_running) {
        double now = elapsed_seconds();

        if (now - last_sample_time >= (double)SAMPLE_PERIOD_S) {
            double elapsed = now - last_sample_time;
            double rpm = (double)pulse_count / elapsed * 60.0;

            printf("RPM: %.2f\n", rpm);
            fflush(stdout);

            if (log_rpm(g_log_fp, rpm) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }

            pulse_count = 0;
            last_sample_time = now;
        }

        /*
         * Sleep for 100 ms to avoid busy-waiting while pigpio's
         * alert callbacks are serviced.
         */
        gpioDelay(100000);   /* 100 ms */
    }

    /* ---- Cleanup ---- */
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);   /* deregister callback */
    gpioTerminate();

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    return EXIT_SUCCESS;
}

