#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define RELEASE_TIMEOUT_S 10     /* 10 s  */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    int relay_state = 0;
    int last_touch_state = 0;
    int touch_held = 0;
    uint32_t touch_held_start = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay to OFF state.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGTERM handler.\n");
    }

    printf("Touch-triggered relay control started.\n");
    printf("  Touch sensor : BCM GPIO%d (active-HIGH)\n", TOUCH_SENSOR_PIN);
    printf("  Relay        : BCM GPIO%d (5 V active-HIGH)\n", RELAY_PIN);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_US / 1000);
    printf("  Release timeout: %d s\n", RELEASE_TIMEOUT_S);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        int touch_value = gpioRead(TOUCH_SENSOR_PIN);

        if (touch_value < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d (rc=%d).\n",
                    TOUCH_SENSOR_PIN, touch_value);
            break;
        }

        if (touch_value == 1) {
            if (last_touch_state == 0) {
                /* Rising edge: toggle relay */
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: gpioWrite failed on GPIO%d.\n", RELAY_PIN);
                    break;
                }
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");

                touch_held = 1;
                touch_held_start = gpioTick();
            } else if (touch_held) {
                uint32_t elapsed = gpioTick() - touch_held_start;
                if (elapsed >= (uint32_t)(RELEASE_TIMEOUT_S * 1000000)) {
                    /* Sensor held too long: force relay OFF */
                    relay_state = 0;
                    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                        fprintf(stderr, "Error: gpioWrite failed on GPIO%d.\n", RELAY_PIN);
                        break;
                    }
                    printf("Relay forced OFF (held too long)\n");
                    touch_held = 0;
                }
            }
        } else {
            if (touch_held) {
                touch_held = 0;
                printf("Touch released (relay remains %s)\n", relay_state ? "ON" : "OFF");
            }
        }

        last_touch_state = touch_value;
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn relay OFF on cleanup.\n");
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

