#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_RANGE          255
#define SAMPLE_PERIOD_US   100000   /* 100 ms */
#define LOG_FILE           "flow_log.csv"

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_flow_count = 0;
static volatile sig_atomic_t g_flow_rate = 0.0;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR: flow sensor rising-edge counter                               */
/* ------------------------------------------------------------------ */
static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_flow_count++;
}

/* ------------------------------------------------------------------ */
/* Compute flow rate from count over the sample period                 */
/* ------------------------------------------------------------------ */
static double compute_flow_rate(void)
{
    int count = g_flow_count;
    g_flow_count = 0;
    return (double)count * 60.0 / (SAMPLE_PERIOD_US / 1000.0);
}

/* ------------------------------------------------------------------ */
/* Proportional controller: Kp = 1.0, clamped to [0, PWM_RANGE]       */
/* ------------------------------------------------------------------ */
static int compute_pwm_duty(double target_flow, double current_flow)
{
    double error = target_flow - current_flow;
    double output = error;

    if (output < 0.0)
        output = 0.0;
    if (output > (double)PWM_RANGE)
        output = (double)PWM_RANGE;

    return (int)output;
}

/* ------------------------------------------------------------------ */
/* Log one data row                                                    */
/* ------------------------------------------------------------------ */
static void log_data(double flow_rate, int pwm_duty)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long timestamp_ms = (long)(ts.tv_sec * 1000L + ts.tv_nsec / 1000000L);

    if (fprintf(g_log_fp, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, pwm_duty) < 0)
        perror("fprintf");
    if (fflush(g_log_fp) != 0)
        perror("fflush");
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        gpioPWM(VALVE_PWM_PIN, 0);
        gpioWrite(VALVE_ENABLE_PIN, 0);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    double target_flow_rate = 0.0;
    int opt;

    /* Parse command-line target flow rate */
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
        case 't':
            target_flow_rate = atof(optarg);
            if (target_flow_rate <= 0.0) {
                fprintf(stderr, "Error: target flow rate must be positive (got %.2f)\n",
                        target_flow_rate);
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Error: missing or invalid target flow rate (-t)\n");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure valve enable line as output, driven high at startup */
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to drive GPIO %d high\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure valve PWM pin */
    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(VALVE_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty cycle on GPIO %d\n",
                VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure flow sensor pin as input with pull-down */
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR on rising edge */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV log file */
    g_log_fp = fopen(LOG_FILE, "w");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (fprintf(g_log_fp, "timestamp_ms,flow_rate_L_min,valve_position\n") < 0) {
        fprintf(stderr, "Error: cannot write CSV header: %s\n", strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error: cannot flush CSV header: %s\n", strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Valve control started. Target flow: %.2f L/min (PWM pin %d, enable pin %d, "
           "flow sensor pin %d). Press Ctrl+C to stop.\n",
           target_flow_rate, VALVE_PWM_PIN, VALVE_ENABLE_PIN, FLOW_SENSOR_PIN);

    /* Main control loop */
    while (g_running) {
        double current_flow = compute_flow_rate();
        int pwm_duty = compute_pwm_duty(target_flow_rate, current_flow);

        if (gpioPWM(VALVE_PWM_PIN, pwm_duty) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on pin %d\n", VALVE_PWM_PIN);
        }

        log_data(current_flow, pwm_duty);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

