    /* Open CSV log file */
    g_log_fp = fopen(LOG_FILE, "w");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (fprintf(g_log_fp, "timestamp_ms,flow_rate_L_min,valve_position\n") < 0) {
        fprintf(stderr, "Error: cannot write CSV header: %s\n", strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error: cannot flush CSV header: %s\n", strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Valve control started. Target flow: %.2f L/min (PWM pin %d, enable pin %d, "
           "flow sensor pin %d). Press Ctrl+C to stop.\n",
           target_flow_rate, VALVE_PWM_PIN, VALVE_ENABLE_PIN, FLOW_SENSOR_PIN);

    /* Main control loop */
    while (g_running) {
        double current_flow = compute_flow_rate();
        int pwm_duty = compute_pwm_duty(target_flow_rate, current_flow);

        if (gpioPWM(VALVE_PWM_PIN, pwm_duty) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on pin %d\n", VALVE_PWM_PIN);
        }

        log_data(current_flow, pwm_duty);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

