#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define SPI_FLAGS 0

#define TAG_LENGTH 10
#define LOG_FILE "/var/log/door_access.log"
#define DEBOUNCE_US 50000
#define DISENGAGE_US 5000000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static const unsigned char VALID_TAG[TAG_LENGTH] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char time_buf[32];
    if (localtime_r(&now, &tm_info) && strftime(time_buf, sizeof(time_buf), "%Y-%m-%dT%H:%M:%S", &tm_info)) {
        fprintf(log_file, "%s: %s\n", time_buf, message);
        fflush(log_file);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rfid_tag(unsigned char *tag) {
    char tx[TAG_LENGTH];
    char rx[TAG_LENGTH];
    memset(tx, 0, TAG_LENGTH);
    memset(rx, 0, TAG_LENGTH);

    int result = spiXfer(spi_handle, tx, rx, TAG_LENGTH);
    if (result != TAG_LENGTH) {
        log_event("RFID read failed: SPI transfer error");
        return -1;
    }

    for (int i = 0; i < TAG_LENGTH; i++) {
        tag[i] = (unsigned char)rx[i];
    }

    if (memcmp(tag, VALID_TAG, TAG_LENGTH) == 0) {
        return 1;
    }
    return 0;
}

static void disengage_locks(void) {
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    log_event("Locks disengaged");
    gpioDelay(DISENGAGE_US);
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
    log_event("Locks re-engaged");
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LOCK2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        log_event("Failed to set GPIO modes");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        log_event("Failed to set pull-up on button pin");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        log_event("Failed to open SPI channel");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_event("Failed to install signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Door access control system started");

    while (running) {
        int button_pressed = (gpioRead(BUTTON_PIN) == 0);
        if (button_pressed) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(BUTTON_PIN) == 0) {
                unsigned char tag[TAG_LENGTH];
                int tag_valid = read_rfid_tag(tag);

                if (tag_valid == 1) {
                    log_event("Access granted: valid tag");
                    disengage_locks();
                } else if (tag_valid == 0) {
                    log_event("Access denied: invalid tag");
                } else {
                    log_event("Access denied: RFID read failure");
                }
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

