#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define TARGET_SPEED 60.0
#define KP 1.0
#define KI 0.01
#define KD 0.1
#define PWM_FREQ 100
#define PWM_RANGE 255
#define SAMPLE_TIME_MS 100
#define LOG_FILE "motor_log.csv"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t enc1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t enc2_mutex = PTHREAD_MUTEX_INITIALIZER;

static int enc1_count = 0;
static int enc2_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void stop_motors(void) {
    gpioPWM(MOTOR1_ENA, 0);
    gpioPWM(MOTOR2_ENB, 0);
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
}

static void set_motor_speed(int motor, float speed) {
    int ena = (motor == 1) ? MOTOR1_ENA : MOTOR2_ENB;
    int in1 = (motor == 1) ? MOTOR1_IN1 : MOTOR2_IN3;
    int in2 = (motor == 1) ? MOTOR1_IN2 : MOTOR2_IN4;

    if (speed > 0) {
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
    } else if (speed < 0) {
        gpioWrite(in1, 0);
        gpioWrite(in2, 1);
    } else {
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
    }

    int duty = (int)((speed / TARGET_SPEED) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(ena, duty);
}

static void encoder_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)tick;
    (void)user;

    if (level != PI_TIMEOUT) {
        int motor = (gpio == ENCODER1_A) ? 1 : 2;
        int a_pin = (gpio == ENCODER1_A) ? ENCODER1_A : ENCODER2_A;
        int b_pin = (gpio == ENCODER1_A) ? ENCODER1_B : ENCODER2_B;

        int b_state = gpioRead(b_pin);
        if (b_state < 0) {
            fprintf(stderr, "Error reading encoder B pin %d\n", b_pin);
            return;
        }

        pthread_mutex_t *mutex = (motor == 1) ? &enc1_mutex : &enc2_mutex;
        pthread_mutex_lock(mutex);

        if (gpio == a_pin) {
            if (level == 1) {
                if (b_state == 1) enc1_count++;
                else enc1_count--;
            } else {
                if (b_state == 0) enc1_count++;
                else enc1_count--;
            }
        } else {
            if (level == 1) {
                if (b_state == 1) enc2_count++;
                else enc2_count--;
            } else {
                if (b_state == 0) enc2_count++;
                else enc2_count--;
            }
        }

        pthread_mutex_unlock(mutex);
    }
}

static float calculate_pid(float current_speed, float target_speed, float *integral, float *previous_error) {
    float error = target_speed - current_speed;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

static void log_data(float motor1_speed, float motor2_speed, float p, float i, float d, float pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, motor1_speed, motor2_speed, p, i, d, pid_output);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Motor1_Speed_RPM,Motor2_Speed_RPM,P,I,D,PID_Output\n");
        fflush(log_file);
    }

    if (gpioSetMode(MOTOR1_ENA, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR1_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR2_ENB, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting motor GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ENCODER1_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER1_B, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER2_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER2_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting encoder GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting encoder pull-ups\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(ENCODER1_A, EITHER_EDGE, 0, encoder_callback, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER1_B, EITHER_EDGE, 0, encoder_callback, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER2_A, EITHER_EDGE, 0, encoder_callback, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER2_B, EITHER_EDGE, 0, encoder_callback, NULL) != 0) {
        fprintf(stderr, "Error setting encoder ISRs\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQ) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float integral1 = 0.0, integral2 = 0.0;
    float prev_error1 = 0.0, prev_error2 = 0.0;

    while (running) {
        pthread_mutex_lock(&enc1_mutex);
        int enc1_count_local = enc1_count;
        pthread_mutex_unlock(&enc1_mutex);

        pthread_mutex_lock(&enc2_mutex);
        int enc2_count_local = enc2_count;
        pthread_mutex_unlock(&enc2_mutex);

        float motor1_speed = (float)enc1_count_local * (60.0 / (SAMPLE_TIME_MS * 1000.0));
        float motor2_speed = (float)enc2_count_local * (60.0 / (SAMPLE_TIME_MS * 1000.0));

        float pid1 = calculate_pid(motor1_speed, TARGET_SPEED, &integral1, &prev_error1);
        float pid2 = calculate_pid(motor2_speed, TARGET_SPEED, &integral2, &prev_error2);

        set_motor_speed(1, pid1);
        set_motor_speed(2, pid2);

        log_data(motor1_speed, motor2_speed, KP, KI, KD, pid1);

        gpioDelay(SAMPLE_TIME_MS * 1000);
    }

    stop_motors();
    fclose(log_file);
    gpioTerminate();
    return 0;
}

