#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x50
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"
#define POLL_DELAY_US 50000

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_F 0x2B
#define MPR121_NHD_F 0x2C
#define MPR121_NCL_F 0x2D
#define MPR121_FDL_F 0x2E
#define MPR121_MHD_R 0x2F
#define MPR121_NHD_R 0x30
#define MPR121_NCL_R 0x31
#define MPR121_FDL_R 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_byte(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_byte(fd, MPR121_MHD_F, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_NHD_F, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_NCL_F, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_FDL_F, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_MHD_R, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_NHD_R, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_NCL_R, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_FDL_R, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (i2c_write_byte(fd, MPR121_E0TTH + (i * 2), 0x0F) < 0) return -1;
        if (i2c_write_byte(fd, MPR121_E0RTH + (i * 2), 0x0A) < 0) return -1;
    }

    if (i2c_write_byte(fd, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_CONFIG2, 0x20) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

static int read_touch_data(int fd, uint16_t *touch_status) {
    uint8_t low, high;
    if (i2c_read_byte(fd, MPR121_TOUCHSTATUS_L, &low) < 0) return -1;
    if (i2c_read_byte(fd, MPR121_TOUCHSTATUS_H, &high) < 0) return -1;
    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Relay State: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, state);
    fclose(fp);
}

static void cleanup() {
    if (i2c_fd >= 0) {
        i2c_write_byte(i2c_fd, MPR121_ECR, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("MPR121 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status;
        if (read_touch_data(i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch data. Retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int any_touched = (touch_status & 0x0FFF) != 0;

        if (any_touched != relay_state) {
            relay_state = any_touched;
            gpioWrite(RELAY_GPIO, relay_state);
            log_relay_state(relay_state);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

