#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define PAUSE_SECONDS 5
#define PAUSE_SECONDS_2 10
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_valve(int gpio, const char *name, int duration_ms) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH for %s\n", gpio, name);
        return -1;
    }
    if (log_event(name) != 0) {
        fprintf(stderr, "Failed to log %s activation\n", name);
    }
    printf("%s activated for %d ms\n", name, duration_ms);
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW for %s\n", gpio, name);
        return -1;
    }
    if (log_event(name) != 0) {
        fprintf(stderr, "Failed to log %s deactivation\n", name);
    }
    printf("%s deactivated\n", name);
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water distribution schedule started. Press Ctrl+C to exit.\n");

    while (running) {
        if (activate_valve(VALVE1_GPIO, "Valve 1", VALVE1_DURATION_MS) != 0) {
            break;
        }
        if (!running) break;
        sleep(PAUSE_SECONDS);
        if (!running) break;
        if (activate_valve(VALVE2_GPIO, "Valve 2", VALVE2_DURATION_MS) != 0) {
            break;
        }
        if (!running) break;
        sleep(PAUSE_SECONDS_2);
    }

    cleanup();
    printf("Water distribution schedule stopped.\n");
    return EXIT_SUCCESS;
}

