#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x50
#define RELAY_GPIO 17
#define STABILIZATION_DELAY_MS 100
#define LOOP_DELAY_MS 100

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_FILTER_CONFIG 0x24
#define MPR121_CHANNEL_CONFIG 0x5B
#define MPR121_ELECTRODE_CURRENT 0x5C
#define MPR121_SOFTRESET 0x80
#define MPR121_MODE_RUN 0x01
#define MPR121_MODE_STOP 0x00

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write(MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_FILTER_CONFIG, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_CHANNEL_CONFIG, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_ELECTRODE_CURRENT, 0x24) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write(MPR121_TOUCHTH_0 + 2 * i, 0x0F) < 0) return -1;
        if (mpr121_write(MPR121_RELEASETH_0 + 2 * i, 0x0A) < 0) return -1;
    }

    if (mpr121_write(MPR121_MODE_RUN, 0x00) < 0) return -1;
    gpioDelay(STABILIZATION_DELAY_MS * 1000);
    return 0;
}

static int mpr121_read_touch_status(uint16_t *status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed: rc=%d\n", rc);
        return -1;
    }
    *status = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    bool relay_state = false;

    while (!terminate) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }

        if (touch_status > 0) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_GPIO, relay_state ? 1 : 0) < 0) {
                fprintf(stderr, "Failed to write relay GPIO\n");
            } else {
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
        }

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    gpioWrite(RELAY_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

