#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_STEP_DURATION_MS 50
#define MAX_STEP_DURATION_MS 200
#define MIN_PATTERN_LENGTH 5
#define MAX_PATTERN_LENGTH 15

typedef struct {
    int motor1_duty_cycle;
    int motor2_duty_cycle;
    int duration_ms;
} HapticStep;

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int generate_random_number(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

int set_motor_pwm(int gpio_pin, int duty_cycle) {
    if (duty_cycle < MIN_DUTY_CYCLE || duty_cycle > MAX_DUTY_CYCLE) {
        fprintf(stderr, "Error: Invalid duty cycle value: %d\n", duty_cycle);
        return -1;
    }
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

int play_haptic_step(HapticStep step) {
    if (set_motor_pwm(MOTOR1_PIN, step.motor1_duty_cycle) != 0) {
        return -1;
    }
    if (set_motor_pwm(MOTOR2_PIN, step.motor2_duty_cycle) != 0) {
        return -1;
    }
    gpioDelay(step.duration_ms * 1000);
    return 0;
}

int generate_haptic_pattern(HapticStep **pattern, int *pattern_length) {
    *pattern_length = generate_random_number(MIN_PATTERN_LENGTH, MAX_PATTERN_LENGTH);
    *pattern = (HapticStep *)malloc((*pattern_length) * sizeof(HapticStep));
    if (*pattern == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for pattern\n");
        return -1;
    }
    for (int i = 0; i < *pattern_length; i++) {
