#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define HX711_TIMEOUT_US 500000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(double *scale, double *offset) {
    int32_t data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_CLOCK_PIN, 0);

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DATA_PIN) && (gpioTick() - start) < HX711_TIMEOUT_US) {
        gpioDelay(100);
    }
    if (gpioTick() - start >= HX711_TIMEOUT_US) {
        fprintf(stderr, "HX711 timeout waiting for data ready\n");
        return -1;
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data |= 1;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    *scale = *scale;
    *offset = *offset;
    return (int32_t)data;
}

static int calibrate_hx711(double *scale, double *offset) {
    double sum = 0.0;
    int i;

    printf("Starting one-time calibration...\n");
    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int32_t raw = read_hx711(scale, offset);
        if (raw == -1) {
            fprintf(stderr, "Calibration read failed at iteration %d\n", i);
            return -1;
        }
        sum += (double)raw;
        gpioDelay(100000);
    }
    *offset = sum / NUM_CALIBRATION_READINGS;
    printf("Calibration complete. Offset: %.2f\n", *offset);
    return 0;
}

static double calculate_weight(int32_t raw, double scale, double offset) {
    return (double)raw - offset;
}

static void log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Weight: %.2f kg\n", s, weight);
    fclose(fp);
}

static void save_calibration(double scale, double offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("Error opening calibration file for writing");
        return;
    }
    fprintf(fp, "%.6f %.6f\n", scale, offset);
    fclose(fp);
}

static int load_calibration(double *scale, double *offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found. Using defaults.\n");
        *scale = 1.0;
        *offset = 0.0;
        return -1;
    }
    if (fscanf(fp, "%lf %lf", scale, offset) != 2) {
        fprintf(stderr, "Error reading calibration file. Using defaults.\n");
        *scale = 1.0;
        *offset = 0.0;
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Calibration loaded: scale=%.6f, offset=%.6f\n", *scale, *offset);
    return 0;
}

int main(void) {
    double scale = 1.0;
    double offset = 0.0;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    signal(SIGINT, signal_handler);

    ret = load_calibration(&scale, &offset);
    if (ret == -1) {
        if (calibrate_hx711(&scale, &offset) != 0) {
            fprintf(stderr, "Initial calibration failed. Exiting.\n");
            gpioTerminate();
            return 1;
        }
        save_calibration(scale, offset);
    }

    printf("Starting weight monitoring...\n");
    while (running) {
        int32_t raw = read_hx711(&scale, &offset);
        if (raw == -1) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight = calculate_weight(raw, scale, offset);
        log_weight(weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight %.2f kg exceeds threshold. Engaging solenoid.\n", weight);
            gpioWrite(SOLENOID_PIN, 1);
            gpioDelay(1000000);
            gpioWrite(SOLENOID_PIN, 0);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

