#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define RAIN_THRESHOLD 3
#define MOTOR_DUTY_CYCLE 150
#define MOTOR_RUN_TIME_S 5
#define CHECK_INTERVAL_S 60
#define POST_CLOSE_DELAY_S 60

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int val = gpioRead(RAIN_SENSOR_PIN);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read rain sensor on GPIO%d", RAIN_SENSOR_PIN);
            return -1;
        }
        if (val == 0) low_count++;
        gpioDelay(DEBOUNCE_DELAY_US);
    }
    return low_count;
}

static int control_motor(int direction) {
    if (direction == 1) {
        if (gpioWrite(MOTOR_IN1_PIN, 1) < 0 || gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to set motor direction to forward");
            return -1;
        }
        if (gpioPWM(MOTOR_PWM_PIN, MOTOR_DUTY_CYCLE) < 0) {
            syslog(LOG_ERR, "Failed to start motor PWM");
            return -1;
        }
        log_event("Motor running forward");
    } else if (direction == 0) {
        if (gpioWrite(MOTOR_IN1_PIN, 0) < 0 || gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to stop motor");
            return -1;
        }
        if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to stop motor PWM");
            return -1;
        }
        log_event("Motor stopped");
    } else {
        syslog(LOG_ERR, "Invalid motor direction: %d", direction);
        return -1;
    }
    return 0;
}

static int close_window(void) {
    if (control_motor(1) < 0) return -1;
    gpioDelay(MOTOR_RUN_TIME_S * 1000000);
    if (control_motor(0) < 0) return -1;
    return 0;
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_WARNING, "Failed to set pull-up on rain sensor pin; continuing without");
    }

    log_event("Program started");

    while (program_running) {
        int rain_count = read_rain_sensor();
        if (rain_count < 0) {
            syslog(LOG_ERR, "Sensor read error, exiting");
            break;
        }

        if (rain_count >= RAIN_THRESHOLD) {
            log_event("Rain detected!");
            if (close_window() < 0) {
                syslog(LOG_ERR, "Motor control error during close");
            } else {
                log_event("Window closed");
            }
            gpioDelay(POST_CLOSE_DELAY_S * 1000000);
        }

        gpioDelay(CHECK_INTERVAL_S * 1000000);
    }

    control_motor(0);
    gpioTerminate();
    log_event("Program terminated");
    closelog();
    return EXIT_SUCCESS;
}

