    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_WARNING, "Failed to set pull-up on rain sensor pin; continuing without");
    }

    log_event("Program started");

    while (program_running) {
        int rain_count = read_rain_sensor();
        if (rain_count < 0) {
            syslog(LOG_ERR, "Sensor read error, exiting");
            break;
        }

        if (rain_count >= RAIN_THRESHOLD) {
            log_event("Rain detected!");
            if (close_window() < 0) {
                syslog(LOG_ERR, "Motor control error during close");
            } else {
                log_event("Window closed");
            }
            gpioDelay(POST_CLOSE_DELAY_S * 1000000);
        }

        gpioDelay(CHECK_INTERVAL_S * 1000000);
    }

    control_motor(0);
    gpioTerminate();
    log_event("Program terminated");
    closelog();
    return EXIT_SUCCESS;
}

