#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define SCALE_FACTOR 100.0
#define WEIGHT_THRESHOLD 100.0
#define LOCK_DURATION_SEC 5
#define LOG_FILE "stock_events.txt"
#define READ_TIMEOUT_US 1000000
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int read_hx711(int *out_value) {
    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) < 0) {
        log_event("Failed to set DT pin as input");
        return -1;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) {
        log_event("Failed to set SCK pin as output");
        return -1;
    }
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        log_event("Failed to initialize SCK low");
        return -1;
    }

    uint32_t start_tick = gpioTick();
    while (gpioRead(HX711_DT_PIN) == 1) {
        if ((gpioTick() - start_tick) > READ_TIMEOUT_US) {
            log_event("HX711 data line stuck high (timeout)");
            return -1;
        }
    }

    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
            log_event("Failed to set SCK high");
            return -1;
        }
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DT_PIN) == 1) {
            data |= 1;
        }
        if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
            log_event("Failed to set SCK low");
            return -1;
        }
        gpioDelay(1);
    }

    if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
        log_event("Failed to set SCK high (25th pulse)");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        log_event("Failed to set SCK low (25th pulse)");
        return -1;
    }
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }
    *out_value = (int32_t)data;
    return 0;
}

static int activate_solenoid(int duration_sec) {
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        log_event("Failed to set solenoid pin as output");
        return -1;
    }
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        log_event("Failed to activate solenoid");
        return -1;
    }
    gpioDelay(duration_sec * 1000000);
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        log_event("Failed to deactivate solenoid");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (program_running) {
        int raw_weight = 0;
        if (read_hx711(&raw_weight) != 0) {
            log_event("HX711 read failed");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double weight = (double)raw_weight / SCALE_FACTOR;
        char log_buf[128];
        snprintf(log_buf, sizeof(log_buf), "Weight: %.2f g", weight);
        log_event(log_buf);

        if (weight < WEIGHT_THRESHOLD) {
            log_event("Weight below threshold, activating solenoid lock");
            if (activate_solenoid(LOCK_DURATION_SEC) != 0) {
                log_event("Solenoid activation failed");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    log_event("Program exiting");
    gpioTerminate();
    return EXIT_SUCCESS;
}

