#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 5.0
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define TIMEOUT_US 100000
#define SAMPLE_DELAY_US 10000
#define SOLENOID_HOLD_US 5000000

static volatile sig_atomic_t running = 1;
static FILE *calibration_file = NULL;
static FILE *security_log_file = NULL;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int32_t *out) {
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;

    uint32_t start_tick = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) return -2;
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(HX711_DATA_PIN)) value |= 1;
        if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    if (value & 0x800000) value |= 0xFF000000;
    *out = value;
    return 0;
}

static double calibrate_hx711(void) {
    printf("Place a known weight on the load cell and enter the weight in kg: ");
    fflush(stdout);

    double known_weight;
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid input. Please enter a positive number.\n");
        return 1.0;
    }

    int32_t raw;
    if (read_hx711(&raw) != 0) {
        fprintf(stderr, "HX711 read error during calibration.\n");
        return 1.0;
    }

    calibration_factor = (double)raw / known_weight;
    if (calibration_factor == 0.0) {
        fprintf(stderr, "Calibration factor is zero. Check your load cell.\n");
        return 1.0;
    }

    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (!calibration_file) {
        perror("Error opening calibration file");
        return 1.0;
    }
    if (fprintf(calibration_file, "%.6lf\n", calibration_factor) < 0) {
        perror("Error writing calibration factor");
        fclose(calibration_file);
        calibration_file = NULL;
        return 1.0;
    }
    fclose(calibration_file);
    calibration_file = NULL;

    printf("Calibration complete. Calibration factor: %.6lf\n", calibration_factor);
    return calibration_factor;
}

static double read_weight(void) {
    int32_t raw;
    if (read_hx711(&raw) != 0) {
        fprintf(stderr, "HX711 read error.\n");
        return -1.0;
    }
    return (double)raw / calibration_factor;
}

static void unlock_solenoid(void) {
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode.\n");
        return;
    }
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        fprintf(stderr, "Failed to activate solenoid.\n");
        return;
    }
    gpioDelay(SOLENOID_HOLD_US);
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Failed to deactivate solenoid.\n");
    }
}

static void log_event(double weight) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Failed to get local time.\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    security_log_file = fopen(SECURITY_LOG_FILE, "a");
    if (!security_log_file) {
        perror("Error opening security log file");
        return;
    }
    if (fprintf(security_log_file, "%s, %.2lf kg\n", timestamp, weight) < 0) {
        perror("Error writing to security log file");
    }
    fclose(security_log_file);
    security_log_file = NULL;
}

static void cleanup(void) {
    if (gpioInitialise() >= 0) {
        gpioWrite(SOLENOID_PIN, 0);
        gpioTerminate();
    }
    if (calibration_file) {
        fclose(calibration_file);
        calibration_file = NULL;
    }
    if (security_log_file) {
        fclose(security_log_file);
        security_log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode.\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file) {
        if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor from file.\n");
            fclose(calibration_file);
            calibration_file = NULL;
            calibration_factor = 1.0;
        } else {
            printf("Calibration factor loaded: %.6lf\n", calibration_factor);
        }
        fclose(calibration_file);
        calibration_file = NULL;
    } else {
        printf("No calibration file found. Starting calibration.\n");
        if (calibrate_hx711() != calibration_factor) {
            fprintf(stderr, "Calibration failed. Using default factor.\n");
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        cleanup();
        return 1;
    }

    printf("Security system started. Press Ctrl+C to exit.\n");

    while (running) {
        double weight = read_weight();
        if (weight < 0.0) {
            fprintf(stderr, "Error reading weight. Retrying in 1 second.\n");
            gpioDelay(1000000);
            continue;
        }

        printf("Weight: %.2lf kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Unlocking solenoid.\n");
            unlock_solenoid();
            log_event(weight);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

