#include <pigpio.h>

#define SENSOR_GPIO 16
#define RELAY_GPIO  20
#define LOG_FILE    "relay_events.log"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Append a timestamped relay-state entry to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_event(int relay_state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s Relay: %s\n", ts, relay_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Toggle the relay to the opposite of the current state.
 * Returns 0 on success, -1 on write failure.
 */
static int toggle_relay(int *relay_state)
{
    int new_state = !(*relay_state);

    if (gpioWrite(RELAY_GPIO, new_state) != 0) {
        fprintf(stderr, "Error writing to relay GPIO %d: %s\n",
                RELAY_GPIO, strerror(errno));
        return -1;
    }

    *relay_state = new_state;
    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pin as input --- */
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sensor GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure relay pin as output --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Ensure relay starts in the OFF state.
     * The KY-022 is active-low: a LOW reading indicates an obstacle.
     * The Songle SRD-05VDC-SL is active-high: a HIGH state turns the
     * relay ON.  We start with the relay OFF.
     */
    int relay_state = 0;
    if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
        fprintf(stderr, "Failed to initialise relay GPIO %d to LOW\n",
                RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main polling loop --- */
    while (running) {
        int sensor_value = gpioRead(SENSOR_GPIO);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor GPIO %d: %s\n",
                    SENSOR_GPIO, strerror(errno));
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /*
         * KY-022 is active-low: a LOW reading indicates an obstacle.
         * Toggle the relay only when the sensor reads LOW and the
         * current relay state is OFF (0).
         */
        if (sensor_value == 0 && relay_state == 0) {
            if (toggle_relay(&relay_state) == 0) {
                if (log_event(relay_state) != 0) {
                    fprintf(stderr, "Warning: failed to log relay event\n");
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(RELAY_GPIO, 0);  /* Ensure relay is OFF on exit */
    gpioTerminate();
    return EXIT_SUCCESS;
}

