#define PIR_PIN 17
#define BUZZER_PIN 18
#define BUZZER_DURATION_US 2000000  /* 2 seconds in microseconds */
#define POLL_DELAY_US 100000        /* 100 ms polling interval */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", PIR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state on GPIO%d.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_pir_sensor(void) {
    int level = gpioRead(PIR_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n", PIR_PIN, level);
        return -1;
    }
    return level;
}

static int activate_buzzer(void) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite failed to turn on buzzer on GPIO%d.\n", BUZZER_PIN);
        return -1;
    }
    gpioDelay(BUZZER_DURATION_US);
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed to turn off buzzer on GPIO%d.\n", BUZZER_PIN);
        return -1;
    }
    return 0;
}

static int log_motion(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[64];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed to format timestamp.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

