    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open motion_log.txt: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int motion = read_pir_sensor();
        if (motion < 0) {
            fprintf(stderr, "Error: PIR sensor read failed, exiting.\n");
            break;
        }

        if (motion == 1) {
            printf("Motion detected!\n");
            if (activate_buzzer() != 0) {
                fprintf(stderr, "Error: buzzer activation failed.\n");
                break;
            }
            if (log_motion() != 0) {
                fprintf(stderr, "Error: motion logging failed.\n");
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Exiting gracefully.\n");
    return 0;
}

