#include <unistd.h>
#include <pigpio.h>

#define CONFIG_FILE "watering.conf"
#define VALVE_GPIO 18
#define MIN_DURATION 1
#define MAX_DURATION 3600
#define DEFAULT_DURATION 60

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static int read_duration(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading config file '%s': %s\n",
                filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *eq = strchr(line, '=');
    if (!eq) {
        fprintf(stderr, "Error: config file '%s' must contain '=' line\n",
                filename);
        return -1;
    }

    *eq = '\0';
    char *key = line;
    char *val = eq + 1;

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Error: config file '%s' must contain 'duration' key\n",
                filename);
        return -1;
    }

    char *endptr = NULL;
    long val_long = strtol(val, &endptr, 10);
    if (endptr == val || *endptr != '\0' || val_long <= 0 || val_long > 3600) {
        fprintf(stderr, "Error: duration must be an integer between %d and %d\n",
                MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)val_long;
    return 0;
}

static int set_valve(int gpio, int on)
{
    int rc = gpioWrite(gpio, on ? 1 : 0);
    if (rc < 0) {
        fprintf(stderr, "Error writing GPIO %d: %s\n", gpio, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static void sleep_interruptible(unsigned seconds)
{
    unsigned remaining = seconds;
    while (remaining > 0 && !g_terminate) {
        unsigned chunk = (remaining > 30) ? 30 : remaining;
        gpioSleep(PI_TIME_RELATIVE, chunk, 0);
        remaining -= chunk;
    }
}

int main(void)
