#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN    4
#define MIDDLE_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27

#define LEFT_MOTOR_PWM_PIN  22
#define RIGHT_MOTOR_PWM_PIN 23
#define LEFT_MOTOR_DIR_PIN  24
#define RIGHT_MOTOR_DIR_PIN 25

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define SAMPLE_US     10000
#define BASE_SPEED    150

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(int left, int middle, int right,
                     int left_speed, int right_speed) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n",
            ts, left, middle, right, left_speed, right_speed);
    fflush(log_file);
}

static void set_motor(int pwm_pin, int dir_pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpioWrite(dir_pin, speed > 0 ? 1 : 0);
    gpioPWM(pwm_pin, speed);
}

static void stop_motors(void) {
    set_motor(LEFT_MOTOR_PWM_PIN, LEFT_MOTOR_DIR_PIN, 0);
    set_motor(RIGHT_MOTOR_PWM_PIN, RIGHT_MOTOR_DIR_PIN, 0);
}

static void drive_straight(void) {
    set_motor(LEFT_MOTOR_PWM_PIN, LEFT_MOTOR_DIR_PIN, BASE_SPEED);
    set_motor(RIGHT_MOTOR_PWM_PIN, RIGHT_MOTOR_DIR_PIN, BASE_SPEED);
}

static void turn_right(void) {
    set_motor(LEFT_MOTOR_PWM_PIN, LEFT_MOTOR_DIR_PIN, BASE_SPEED / 2);
    set_motor(RIGHT_MOTOR_PWM_PIN, RIGHT_MOTOR_DIR_PIN, BASE_SPEED);
}

static void turn_left(void) {
    set_motor(LEFT_MOTOR_PWM_PIN, LEFT_MOTOR_DIR_PIN, BASE_SPEED);
    set_motor(RIGHT_MOTOR_PWM_PIN, RIGHT_MOTOR_DIR_PIN, BASE_SPEED / 2);
}

static void control_robot(int left, int middle, int right) {
    if (middle == 0) {
        drive_straight();
    } else if (left == 0) {
        turn_right();
    } else if (right == 0) {
        turn_left();
    } else {
        stop_motors();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("trace_log.txt", "a");
    if (!log_file) {
        perror("fopen(trace_log.txt)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sensor pin modes\n");
        goto cleanup;
    }

    if (gpioSetMode(LEFT_MOTOR_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(RIGHT_MOTOR_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LEFT_MOTOR_DIR_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(RIGHT_MOTOR_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        goto cleanup;
    }

    if (gpioSetPWMfrequency(LEFT_MOTOR_PWM_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(RIGHT_MOTOR_PWM_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequencies\n");
        goto cleanup;
    }

    if (gpioSetPWMrange(LEFT_MOTOR_PWM_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RIGHT_MOTOR_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM ranges\n");
        goto cleanup;
    }

    stop_motors();

    while (running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error\n");
            break;
        }

        int left_speed  = gpioGetPWMdutycycle(LEFT_MOTOR_PWM_PIN);
        int right_speed = gpioGetPWMdutycycle(RIGHT_MOTOR_PWM_PIN);

        control_robot(left, middle, right);
        log_data(left, middle, right, left_speed, right_speed);

        gpioDelay(SAMPLE_US);
    }

cleanup:
    stop_motors();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

