#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MOTOR1_DURATION_MS 200
#define MOTOR2_DURATION_MS 300

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_call(unsigned gpio, unsigned level) {
    if (gpioCall(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioCall(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (safe_set_mode(MOTOR1_PIN, PI_OUTPUT) != 0) return -1;
    if (safe_set_mode(MOTOR2_PIN, PI_OUTPUT) != 0) return -1;

    /* Ensure motors are off at startup */
    if (safe_write(MOTOR1_PIN, 0) != 0) return -1;
    if (safe_write(MOTOR2_PIN, 0) != 0) return -1;

    return 0;
}

static void cleanup_gpio(void) {
    /* Stop motors by invoking gpioCall with level 0 */
    gpioCall(MOTOR1_PIN, 0);
    gpioCall(MOTOR2_PIN, 0);
    gpioTerminate();
}

static int run_motor(unsigned gpio, int duration_ms) {
    if (safe_write(gpio, 1) != 0) return -1;
    gpioDelay(duration_ms * 1000);
    if (safe_write(gpio, 0) != 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (run_motor(MOTOR1_PIN, MOTOR1_DURATION_MS) != 0) break;
        if (!running) break;
        if (run_motor(MOTOR2_PIN, MOTOR2_DURATION_MS) != 0) break;
    }

    cleanup_gpio();
    printf("Haptic feedback system stopped.\n");
    return EXIT_SUCCESS;
}

