#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <zmq.h>

#define GPIO_CHIP_DEV "/dev/gpiochip0"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_ADDR "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- GPIO helpers (raw character-device access) ---- */

static int gpio_export(int pin) {
    int fd = open(GPIO_CHIP_DEV, O_WRONLY);
    if (fd < 0) { perror("open gpiochip"); return -1; }
    char buf[16];
    int n = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, n) != n) {
        perror("write gpio export"); close(fd); return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    int fd = open(GPIO_CHIP_DEV, O_WRONLY);
    if (fd < 0) { perror("open gpiochip"); return -1; }
    char buf[16];
    int n = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, n) != n) {
        perror("write gpio unexport"); close(fd); return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) { perror("open gpio direction"); return -1; }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        perror("write gpio direction"); close(fd); return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(int pin, int val) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) { perror("open gpio value"); return -1; }
    char buf[2] = { (char)(val ? '1' : '0'), '\n' };
    if (write(fd, buf, 2) != 2) {
        perror("write gpio value"); close(fd); return -1;
    }
    close(fd);
    return 0;
}

static int gpio_read_value(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_RDONLY);
    if (fd < 0) { perror("open gpio value"); return -1; }
    char buf[2] = {0};
    if (read(fd, buf, 1) != 1) {
        perror("read gpio value"); close(fd); return -1;
    }
    close(fd);
    return (buf[0] == '1') ? 1 : 0;
}

/* ---- ZeroMQ helpers ---- */

static void *zmq_publish(const char *addr, const char *topic, const char *msg) {
    void *ctx = zmq_ctx_new();
    if (!ctx) { perror("zmq_ctx_new"); return NULL; }
    void *sock = zmq_socket(ctx, ZMQ_PUB);
    if (!sock) { perror("zmq_socket"); zmq_ctx_destroy(ctx); return NULL; }
    if (zmq_bind(sock, addr) != 0) {
        perror("zmq_bind"); zmq_close(sock); zmq_ctx_destroy(ctx); return NULL;
    }
    char full_msg[256];
    snprintf(full_msg, sizeof(full_msg), "%s %s", topic, msg);
    if (zmq_send(sock, full_msg, strlen(full_msg), 0) != 0) {
        perror("zmq_send");
    }
    zmq_close(sock);
    zmq_ctx_destroy(ctx);
    return NULL;
}

static void *zmq_subscribe(const char *addr, const char *topic) {
    void *ctx = zmq_ctx_new();
    if (!ctx) { perror("zmq_ctx_new"); return NULL; }
    void *sock = zmq_socket(ctx, ZMQ_SUB);
    if (!sock) { perror("zmq_socket"); zmq_ctx_destroy(ctx); return NULL; }
    if (zmq_connect(sock, addr) != 0) {
        perror("zmq_connect"); zmq_close(sock); zmq_ctx_destroy(ctx); return NULL;
    }
    if (zmq_setsockopt(sock, ZMQ_SUBSCRIBE, topic, strlen(topic)) != 0) {
        perror("zmq_setsockopt subscribe"); zmq_close(sock); zmq_ctx_destroy(ctx); return NULL;
    }
    return sock;
}

/* ---- Main ---- */

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor | alarm_node\n");
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* GPIO setup */
    if (gpio_export(SOUND_SENSOR_PIN) != 0) return EXIT_FAILURE;
    if (gpio_export(ALARM_LED_PIN) != 0) { gpio_unexport(SOUND_SENSOR_PIN); return EXIT_FAILURE; }
    if (gpio_set_direction(SOUND_SENSOR_PIN, "in") != 0) {
        gpio_unexport(SOUND_SENSOR_PIN); gpio_unexport(ALARM_LED_PIN); return EXIT_FAILURE;
    }
    if (gpio_set_direction(ALARM_LED_PIN, "out") != 0) {
        gpio_unexport(SOUND_SENSOR_PIN); gpio_unexport(ALARM_LED_PIN); return EXIT_FAILURE;
    }
    if (gpio_set_value(ALARM_LED_PIN, 0) != 0) {
        gpio_unexport(SOUND_SENSOR_PIN); gpio_unexport(ALARM_LED_PIN); return EXIT_FAILURE;
    }

    if (strcmp(mode, "sound_sensor") == 0) {
        printf("Sound sensor mode: polling GPIO%d every %d us. Press Ctrl+C to exit.\n",
               SOUND_SENSOR_PIN, POLL_INTERVAL_US);

        while (g_running) {
            int val = gpio_read_value(SOUND_SENSOR_PIN);
            if (val < 0) {
                fprintf(stderr, "Error reading sound sensor\n");
                break;
            }
            if (val == 0) { /* active-low: 0 = sound detected */
                printf("Sound detected!\n");
                zmq_publish(ZMQ_ADDR, ZMQ_TOPIC, "Sound detected");
            }
            usleep(POLL_INTERVAL_US);
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        printf("Alarm node mode: subscribing to %s on %s. Press Ctrl+C to exit.\n",
               ZMQ_TOPIC, ZMQ_ADDR);

        void *sub = zmq_subscribe(ZMQ_ADDR, ZMQ_TOPIC);
        if (!sub) {
            fprintf(stderr, "Failed to subscribe to ZMQ\n");
            gpio_set_value(ALARM_LED_PIN, 0);
            gpio_unexport(SOUND_SENSOR_PIN);
            gpio_unexport(ALARM_LED_PIN);
            return EXIT_FAILURE;
        }

        while (g_running) {
            zmq_msg_t msg;
            zmq_msg_init(&msg);
            int rc = zmq_recvmsg(sub, &msg, 0);
            if (rc < 0) {
                if (errno == EINTR) continue;
                perror("zmq_recvmsg");
                break;
            }
            if (rc > 0) {
                printf("Alarm triggered!\n");
                if (gpio_set_value(ALARM_LED_PIN, 1) != 0) {
                    fprintf(stderr, "Failed to set alarm LED on\n");
                }
                sleep(ALARM_DURATION_S);
                if (gpio_set_value(ALARM_LED_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to set alarm LED off\n");
                }
            }
            zmq_msg_close(&msg);
        }

        zmq_close(sub);
        zmq_ctx_term(zmq_ctx_get(sub));
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        gpio_set_value(ALARM_LED_PIN, 0);
        gpio_unexport(SOUND_SENSOR_PIN);
        gpio_unexport(ALARM_LED_PIN);
        return EXIT_FAILURE;
    }

    /* Cleanup */
    gpio_set_value(ALARM_LED_PIN, 0);
    gpio_unexport(SOUND_SENSOR_PIN);
    gpio_unexport(ALARM_LED_PIN);
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

