#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 256
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_TOLERANCE 200

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_times[MAX_PULSES];
static volatile int pulse_count = 0;
static volatile uint32_t last_tick = 0;
static MQTTClient mqtt_client = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != PI_OFF && level != PI_ON) return;
    uint32_t diff = tick - last_tick;
    last_tick = tick;
    if (diff > 0 && diff < 1000000) {
        if (pulse_count < MAX_PULSES) {
            pulse_times[pulse_count++] = diff;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow, resetting");
            pulse_count = 0;
        }
    }
}

static int decode_nec(const uint32_t *times, int count, uint32_t *command) {
    if (count < 34) return -1;
    if (times[0] < NEC_HDR_MARK - NEC_TOLERANCE || times[0] > NEC_HDR_MARK + NEC_TOLERANCE) return -1;
    if (times[1] < NEC_HDR_SPACE - NEC_TOLERANCE || times[1] > NEC_HDR_SPACE + NEC_TOLERANCE) return -1;
    uint32_t addr = 0, addr_inv = 0, cmd = 0, cmd_inv = 0;
    for (int i = 0; i < 32; i++) {
        int idx = 2 + i * 2;
        if (idx + 1 >= count) return -1;
        if (times[idx] < NEC_BIT_MARK - NEC_TOLERANCE || times[idx] > NEC_BIT_MARK + NEC_TOLERANCE) return -1;
        if (times[idx + 1] > NEC_ONE_SPACE - NEC_TOLERANCE && times[idx + 1] < NEC_ONE_SPACE + NEC_TOLERANCE) {
            addr = (addr << 1) | 1;
            addr_inv = (addr_inv << 1) | 0;
        } else if (times[idx + 1] > NEC_ZERO_SPACE - NEC_TOLERANCE && times[idx + 1] < NEC_ZERO_SPACE + NEC_TOLERANCE) {
            addr = (addr << 1) | 0;
            addr_inv = (addr_inv << 1) | 1;
        } else return -1;
    }
    for (int i = 0; i < 32; i++) {
        int idx = 2 + (i + 32) * 2;
        if (idx + 1 >= count) return -1;
        if (times[idx] < NEC_BIT_MARK - NEC_TOLERANCE || times[idx] > NEC_BIT_MARK + NEC_TOLERANCE) return -1;
        if (times[idx + 1] > NEC_ONE_SPACE - NEC_TOLERANCE && times[idx + 1] < NEC_ONE_SPACE + NEC_TOLERANCE) {
            cmd = (cmd << 1) | 1;
            cmd_inv = (cmd_inv << 1) | 0;
        } else if (times[idx + 1] > NEC_ZERO_SPACE - NEC_TOLERANCE && times[idx + 1] < NEC_ZERO_SPACE + NEC_TOLERANCE) {
            cmd = (cmd << 1) | 0;
            cmd_inv = (cmd_inv << 1) | 1;
        } else return -1;
    }
    if (addr != (addr_inv & 0xFFFF)) return -1;
    *command = cmd;
    return 0;
}

static int mqtt_publish(uint32_t command) {
    char payload[64];
    snprintf(payload, sizeof(payload), "{\"command\": %u}", command);
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;
    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio init failed");
        closelog();
        return 1;
    }
    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);
    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function");
        gpioTerminate();
        closelog();
        return 1;
    }
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    int rc = MQTTClient_create(&mqtt_client, MQTT_BROKER, "ir_decoder", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT create failed: %s", MQTTClient_strerror(rc));
        gpioTerminate();
        closelog();
        return 1;
    }
    rc = MQTTClient_connect(mqtt_client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&mqtt_client);
        gpioTerminate();
        closelog();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    syslog(LOG_INFO, "IR decoder started");
    while (running) {
        if (pulse_count >= 34) {
            uint32_t command;
            if (decode_nec(pulse_times, pulse_count, &command) == 0) {
                syslog(LOG_INFO, "Decoded command: %u", command);
                mqtt_publish(command);
            }
            pulse_count = 0;
        }
        gpioDelay(100000);
    }
    syslog(LOG_INFO, "Shutting down");
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    gpioTerminate();
    closelog();
    return 0;
}

