#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS    4
#define BH1750_ADDR    0x23
#define BH1750_CMD_OT  0x80  /* One-Time High-Resolution Mode */
#define BH1750_CMD_OT_MSB 0x80
#define BH1750_CMD_OT_LSB 0x00
#define BH1750_CONV_MS  180  /* ms for one-time conversion */
#define LOOP_DELAY_S   1

static volatile sig_atomic_t g_terminate = 0;

static void sig_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/*
 * Open the I2C bus and claim the slave address.
 * Returns a valid file descriptor on success, -1 on failure.
 */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Issue a one-time high-resolution measurement command to the BH1750.
 * Returns 0 on success, -1 on failure.
 */
static int bh1750_start_measurement(int fd)
{
    uint8_t cmd[2] = { BH1750_CMD_OT_MSB, BH1750_CMD_OT_LSB };
    ssize_t n = write(fd, cmd, sizeof(cmd));
    if (n != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "BH1750 write: %s\n", n < 0 ? strerror(errno) : "short write");
        return -1;
    }
    return 0;
}

/*
 * Read the 2-byte result of a one-time conversion.
 * Returns 0 on success and stores the lux value in *lux, or -1 on failure.
 */
static int bh1750_read_lux(int fd, float *lux)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "BH1750 read: %s\n", n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

/*
 * Broadcast a semicolon-separated list of sensor_id,lux pairs over UDP.
 * Returns 0 on success, -1 on failure.
 */
static int broadcast_lux(const float lux[], int num_sensors)
{
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char payload[256];
    size_t len = 0;
    for (int i = 0; i < num_sensors; i++) {
        len += snprintf(payload + len, sizeof(payload) - len, "%d,%.1f;", i + 1, lux[i]);
    }
    payload[len - 1] = '\0'; /* remove trailing semicolon */

    if (sendto(sockfd, payload, len, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
