        for (int i = 0; i < NUM_SENSORS; i++) {
            if (fds[i] >= 0) close(fds[i]);
        }
        return EXIT_FAILURE;
    }

    while (!g_terminate) {
        float lux[NUM_SENSORS];
        int ok_all = 1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (bh1750_start_measurement(fds[i]) < 0) {
                lux[i] = NAN;
                ok_all = 0;
                continue;
            }
            usleep(BH1750_CONV_MS * 1000);
            if (bh1750_read_lux(fds[i], &lux[i]) < 0) {
                lux[i] = NAN;
                ok_all = 0;
            }
        }

        if (ok_all) {
