#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static int i2c_write_zero_length(int fd)
{
    uint8_t zero = 0x00;
    ssize_t n = write(fd, &zero, 0);
    if (n < 0) {
        if (errno == EINTR) return -1;
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == EINTR) return -1;
        return -1;
    }
    if ((size_t)n != len) {
        return -1;
    }
    return 0;
}

static int awm7300v_read_flow(int fd, float *flow_slpm)
{
    uint8_t buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_zero_length(fd) < 0) {
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0) {
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        raw &= 0x3FFF;

        *flow_slpm = (float)raw * 0.003f;
        return 0;
    }

    return -1;
}

static void log_flow_rate(FILE *fp, float flow_slpm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f SLPM\n", ts, flow_slpm);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        if (errno == ENXIO) {
            fprintf(stderr, "No I2C bus found (ENXIO). Check /dev/i2c-1 and i2c enable.\n");
        } else {
            perror("open I2C bus");
        }
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        if (errno == EIO) {
            fprintf(stderr, "Sensor not responding at 0x%02X (EIO). Check wiring.\n", AWM7300V_ADDR);
        } else {
            perror("ioctl I2C_SLAVE");
        }
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        float flow_slpm;

        if (awm7300v_read_flow(g_i2c_fd, &flow_slpm) < 0) {
            fprintf(stderr, "Failed to read flow rate after %d retries.\n", MAX_RETRIES);
            break;
        }

        log_flow_rate(g_log_fp, flow_slpm);
        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting gracefully.\n");
    cleanup();
    return EXIT_SUCCESS;
}

