#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AS7341_ADDR    0x39

#define REG_ENABLE     0x80
#define REG_CFG6       0x71
#define REG_F1DATAL    0x90
#define REG_F1DATAH    0x91
#define REG_F2DATAL    0x92
#define REG_F2DATAH    0x93
#define REG_F3DATAL    0x94
#define REG_F3DATAH    0x95
#define REG_F4DATAL    0x96
#define REG_F4DATAH    0x97
#define REG_F5DATAL    0x98
#define REG_F5DATAH    0x99
#define REG_F6DATAL    0x9A
#define REG_F6DATAH    0x9B
#define REG_F7DATAL    0x9C
#define REG_F7DATAH    0x9D
#define REG_F8DATAL    0x9E
#define REG_F8DATAH    0x9F
#define REG_CDATAL     0xA0
#define REG_CDATAH     0xA1
#define REG_NIRDATAL   0xA2
#define REG_NIRDATAH   0xA3

#define ENABLE_PON     0x01
#define ENABLE_SP_EN   0x02
#define CFG6_SMUX_ALL  0x01

#define LOG_FILE       "spectral_log.csv"
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write reg failed");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg8: read failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write reg failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read failed");
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int as7341_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, 0x00, &id) < 0) {
        fprintf(stderr, "Error: AS7341 not responding on I2C bus.\n");
        return -1;
    }
    if (id != 0x73) {
        fprintf(stderr, "Error: AS7341 ID mismatch (got 0x%02X, expected 0x73).\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_ENABLE, ENABLE_PON) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CFG6, CFG6_SMUX_ALL) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ENABLE, ENABLE_PON | ENABLE_SP_EN) < 0) return -1;
    return 0;
}

static int as7341_read_spectral(int fd, uint16_t *f1, uint16_t *f2, uint16_t *f3,
                                 uint16_t *f4, uint16_t *f5, uint16_t *f6,
                                 uint16_t *f7, uint16_t *f8, uint16_t *clear,
                                 uint16_t *nir) {
    if (i2c_read_reg16(fd, REG_F1DATAL, f1) < 0) return -1;
    if (i2c_read_reg16(fd, REG_F2DATAL, f2) < 0) return -1;
    if (i2c_read_reg16(fd, REG_F3DATAL, f3) < 0) return -1;
    if (i2c_read_reg16(fd, REG_F4DATAL, f4) < 0) return -1;
    if (i2c_read_reg16(fd, REG_F5DATAL, f5) < 0) return -1;
    if (i2c_read_reg16(fd, REG_F6DATAL, f6) < 0) return -1;
    if (i2c_read_reg16(fd, REG_F7DATAL, f7) < 0) return -1;
    if (i2c_read_reg16(fd, REG_F8DATAL, f8) < 0) return -1;
    if (i2c_read_reg16(fd, REG_CDATAL, clear) < 0) return -1;
    if (i2c_read_reg16(fd, REG_NIRDATAL, nir) < 0) return -1;
    return 0;
}

static float calculate_lux(uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4,
                            uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8,
                            uint16_t clear, uint16_t nir) {
    (void)f1; (void)f2; (void)f3; (void)f4; (void)f5; (void)f6; (void)f7; (void)f8;
    (void)nir;
    return (float)clear;
}

static int log_data(FILE *fp, float lux, uint16_t f1, uint16_t f2, uint16_t f3,
                    uint16_t f4, uint16_t f5, uint16_t f6, uint16_t f7,
                    uint16_t f8, uint16_t clear, uint16_t nir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u\n",
                timestamp, lux, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir) < 0) {
        perror("fprintf to log file failed");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush log file failed");
        return -1;
    }
    return 0;
