#define REG_F3DATAL    0x94
#define REG_F3DATAH    0x95
#define REG_F4DATAL    0x96
#define REG_F4DATAH    0x97
#define REG_F5DATAL    0x98
#define REG_F5DATAH    0x99
#define REG_F6DATAL    0x9A
#define REG_F6DATAH    0x9B
#define REG_F7DATAL    0x9C
#define REG_F7DATAH    0x9D
#define REG_F8DATAL    0x9E
#define REG_F8DATAH    0x9F
#define REG_CDATAL     0xA0
#define REG_CDATAH     0xA1
#define REG_NIRDATAL   0xA2
#define REG_NIRDATAH   0xA3

#define ENABLE_PON     0x01
#define ENABLE_SP_EN   0x02
