#define SAMPLE_PERIOD  5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write reg failed");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg8: read failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write reg failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read failed");
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int as7341_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, 0x00, &id) < 0) {
        fprintf(stderr, "Error: AS7341 not responding on I2C bus.\n");
        return -1;
    }
    if (id != 0x73) {
        fprintf(stderr, "Error: AS7341 ID mismatch (got 0x%02X, expected 0x73).\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_ENABLE, ENABLE_PON) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CFG6, CFG6_SMUX_ALL) < 0) return -1;
