#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x30
#define DEFAULT_SAMPLING_INTERVAL 1
#define DEFAULT_OUTPUT_FILE "seismic_data.csv"
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define ERROR_LOG_FILE "seismic_error.log"

#define D7S_REG_X_LSB 0x00
#define D7S_REG_X_MSB 0x01
#define D7S_REG_Y_LSB 0x02
#define D7S_REG_Y_MSB 0x03
#define D7S_REG_Z_LSB 0x04
#define D7S_REG_Z_MSB 0x05
#define D7S_REG_DEVICE_ID 0x06
#define D7S_REG_DEVICE_ID_VALUE 0x01

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static const char *output_filename = DEFAULT_OUTPUT_FILE;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    FILE *error_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_file) {
        fprintf(stderr, "Failed to open error log: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(error_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(error_file);
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int read_d7s_data(int fd, float *x, float *y, float *z) {
    uint8_t x_lsb, x_msb, y_lsb, y_msb, z_lsb, z_msb;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg8(fd, D7S_REG_X_LSB, &x_lsb) == 0 &&
            i2c_read_reg8(fd, D7S_REG_X_MSB, &x_msb) == 0 &&
            i2c_read_reg8(fd, D7S_REG_Y_LSB, &y_lsb) == 0 &&
            i2c_read_reg8(fd, D7S_REG_Y_MSB, &y_msb) == 0 &&
            i2c_read_reg8(fd, D7S_REG_Z_LSB, &z_lsb) == 0 &&
            i2c_read_reg8(fd, D7S_REG_Z_MSB, &z_msb) == 0) {
            int16_t raw_x = (int16_t)((x_msb << 8) | x_lsb);
            int16_t raw_y = (int16_t)((y_msb << 8) | y_lsb);
            int16_t raw_z = (int16_t)((z_msb << 8) | z_lsb);
            *x = (float)raw_x / 1000.0f;
            *y = (float)raw_y / 1000.0f;
            *z = (float)raw_z / 1000.0f;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static int write_to_csv(FILE *file, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    if (fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z) < 0) {
        return -1;
    }
    fflush(file);
    return 0;
}

static void cleanup(void) {
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = (int)strtol(optarg, NULL, 0);
                if (sampling_interval <= 0) {
                    fprintf(stderr, "Invalid sampling interval. Using default.\n");
                    sampling_interval = DEFAULT_SAMPLING_INTERVAL;
                }
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f output_filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handlers");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", i2c_address, strerror(errno));
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t device_id = 0;
    if (i2c_read_reg8(i2c_fd, D7S_REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "Failed to read device ID (sensor absent or bus error)\n");
        log_error("Failed to read device ID");
        cleanup();
        return EXIT_FAILURE;
    }
    if (device_id != D7S_REG_DEVICE_ID_VALUE) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n", device_id, D7S_REG_DEVICE_ID_VALUE);
        log_error("Unexpected device ID");
        cleanup();
        return EXIT_FAILURE;
    }

    csv_file = fopen(output_filename, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file %s: %s\n", output_filename, strerror(errno));
        log_error("Failed to open CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");
    fflush(csv_file);

    printf("Starting seismic data acquisition. Writing to %s\n", output_filename);
    printf("Press Ctrl+C to stop.\n");

    while (running) {
        float x, y, z;
        if (read_d7s_data(i2c_fd, &x, &y, &z) == 0) {
            if (write_to_csv(csv_file, x, y, z) != 0) {
                fprintf(stderr, "Failed to write to CSV file: %s\n", strerror(errno));
                log_error("Failed to write to CSV file");
            }
        } else {
            fprintf(stderr, "Failed to read seismic data after %d retries\n", MAX_RETRIES);
            log_error("Failed to read seismic data");
        }
        sleep(sampling_interval);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

