#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define MAX_OBJECTS 100
#define MAGIC_WORD_SIZE 8
#define FRAME_HEADER_SIZE 40
#define TLV_HEADER_SIZE 8
#define RANGE_VELOCITY_SIZE 8
#define MAX_FRAME_SIZE 8192

static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {
    0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07
};

static int uart_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float range;
    float velocity;
} RadarData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", UART_DEVICE, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_csv(void) {
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file %s: %s\n", CSV_FILE, strerror(errno));
        return -1;
    }
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    return 0;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

static int find_magic_word(const uint8_t *buf, int len) {
    for (int i = 0; i <= len - MAGIC_WORD_SIZE; i++) {
        if (memcmp(buf + i, MAGIC_WORD, MAGIC_WORD_SIZE) == 0) {
            return i;
        }
    }
    return -1;
}

static int parse_frame(const uint8_t *frame, int frame_len, RadarData *data, int *num_objects) {
    if (frame_len < FRAME_HEADER_SIZE) {
        fprintf(stderr, "Frame too short for header\n");
        return -1;
    }
    uint32_t num_detected_obj = *(const uint32_t *)(frame + 20);
    uint32_t num_tlvs = *(const uint32_t *)(frame + 24);
    uint32_t total_tlv_len = *(const uint32_t *)(frame + 28);

    if (num_detected_obj > MAX_OBJECTS) {
        fprintf(stderr, "Too many objects: %u\n", num_detected_obj);
        return -1;
    }
    *num_objects = (int)num_detected_obj;

    int offset = FRAME_HEADER_SIZE;
    int object_idx = 0;

    for (uint32_t i = 0; i < num_tlvs && offset + TLV_HEADER_SIZE <= frame_len; i++) {
        uint32_t tlv_type = *(const uint32_t *)(frame + offset);
        uint32_t tlv_len = *(const uint32_t *)(frame + offset + 4);
        offset += TLV_HEADER_SIZE;

        if (offset + tlv_len > frame_len) {
            fprintf(stderr, "TLV length exceeds frame bounds\n");
            return -1;
        }

        if (tlv_type == 1 && tlv_len >= RANGE_VELOCITY_SIZE) {
            if (object_idx < num_detected_obj) {
                float range = *(const float *)(frame + offset);
                float velocity = *(const float *)(frame + offset + 4);
                data[object_idx].range = range;
                data[object_idx].velocity = velocity;
                object_idx++;
            }
        }
        offset += tlv_len;
    }
    return 0;
}

static void log_data(const RadarData *data, int num_objects) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    for (int i = 0; i < num_objects; i++) {
        fprintf(csv_file, "%s,%d,%.2f,%.2f\n", timestamp, i, data[i].range, data[i].velocity);
    }
    fflush(csv_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_csv() != 0) {
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t *frame_buf = malloc(MAX_FRAME_SIZE);
    if (!frame_buf) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup();
        return 1;
    }

    uint8_t *read_buf = malloc(MAX_FRAME_SIZE);
    if (!read_buf) {
        fprintf(stderr, "Memory allocation failed\n");
        free(frame_buf);
        cleanup();
        return 1;
    }

    int frame_len = 0;
    int bytes_read;

    while (!terminate) {
        bytes_read = serRead(uart_handle, (char *)read_buf, MAX_FRAME_SIZE - frame_len);
        if (bytes_read < 0) {
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 0) {
            gpioDelay(10000);
            continue;
        }

        memcpy(frame_buf + frame_len, read_buf, bytes_read);
        frame_len += bytes_read;

        int magic_pos = find_magic_word(frame_buf, frame_len);
        if (magic_pos < 0) {
            if (frame_len > 16) {
                memmove(frame_buf, frame_buf + frame_len - 16, 16);
                frame_len = 16;
            }
            continue;
        }

        if (magic_pos > 0) {
            memmove(frame_buf, frame_buf + magic_pos, frame_len - magic_pos);
            frame_len -= magic_pos;
        }

        if (frame_len < FRAME_HEADER_SIZE) {
            continue;
        }

        uint32_t total_packet_len = *(const uint32_t *)(frame_buf + 16);
        if (total_packet_len > MAX_FRAME_SIZE) {
            fprintf(stderr, "Packet length %u exceeds max\n", total_packet_len);
            frame_len = 0;
            continue;
        }

        if (frame_len < (int)total_packet_len) {
            continue;
        }

        RadarData data[MAX_OBJECTS];
        int num_objects = 0;

        if (parse_frame(frame_buf, total_packet_len, data, &num_objects) == 0) {
            log_data(data, num_objects);
        }

        int remaining = frame_len - total_packet_len;
        if (remaining > 0) {
            memmove(frame_buf, frame_buf + total_packet_len, remaining);
        }
        frame_len = remaining;
    }

    free(read_buf);
    free(frame_buf);
    cleanup();
    return 0;
}

