    if (num_detected_obj > MAX_OBJECTS) {
        fprintf(stderr, "Too many objects: %u\n", num_detected_obj);
        return -1;
    }
    *num_objects = (int)num_detected_obj;

    int offset = FRAME_HEADER_SIZE;
    int object_idx = 0;

    for (uint32_t i = 0; i < num_tlvs && offset + TLV_HEADER_SIZE <= frame_len; i++) {
        uint32_t tlv_type = *(const uint32_t *)(frame + offset);
        uint32_t tlv_len = *(const uint32_t *)(frame + offset + 4);
        offset += TLV_HEADER_SIZE;

        if (offset + tlv_len > frame_len) {
            fprintf(stderr, "TLV length exceeds frame bounds\n");
            return -1;
        }

        if (tlv_type == 1 && tlv_len >= RANGE_VELOCITY_SIZE) {
            if (object_idx < num_detected_obj) {
                float range = *(const float *)(frame + offset);
                float velocity = *(const float *)(frame + offset + 4);
                data[object_idx].range = range;
                data[object_idx].velocity = velocity;
                object_idx++;
            }
        }
        offset += tlv_len;
    }
    return 0;
}

static void log_data(const RadarData *data, int num_objects) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    for (int i = 0; i < num_objects; i++) {
        fprintf(csv_file, "%s,%d,%.2f,%.2f\n", timestamp, i, data[i].range, data[i].velocity);
    }
    fflush(csv_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_csv() != 0) {
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t *frame_buf = malloc(MAX_FRAME_SIZE);
    if (!frame_buf) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup();
        return 1;
    }

    uint8_t *read_buf = malloc(MAX_FRAME_SIZE);
    if (!read_buf) {
        fprintf(stderr, "Memory allocation failed\n");
        free(frame_buf);
        cleanup();
        return 1;
    }

    int frame_len = 0;
    int bytes_read;

    while (!terminate) {
        bytes_read = serRead(uart_handle, (char *)read_buf, MAX_FRAME_SIZE - frame_len);
        if (bytes_read < 0) {
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 0) {
            gpioDelay(10000);
            continue;
        }

        memcpy(frame_buf + frame_len, read_buf, bytes_read);
        frame_len += bytes_read;

        int magic_pos = find_magic_word(frame_buf, frame_len);
        if (magic_pos < 0) {
            if (frame_len > 16) {
                memmove(frame_buf, frame_buf + frame_len - 16, 16);
                frame_len = 16;
            }
            continue;
        }

        if (magic_pos > 0) {
            memmove(frame_buf, frame_buf + magic_pos, frame_len - magic_pos);
            frame_len -= magic_pos;
        }

        if (frame_len < FRAME_HEADER_SIZE) {
            continue;
        }

        uint32_t total_packet_len = *(const uint32_t *)(frame_buf + 16);
        if (total_packet_len > MAX_FRAME_SIZE) {
            fprintf(stderr, "Packet length %u exceeds max\n", total_packet_len);
            frame_len = 0;
            continue;
        }

        if (frame_len < (int)total_packet_len) {
            continue;
        }

        RadarData data[MAX_OBJECTS];
        int num_objects = 0;

        if (parse_frame(frame_buf, total_packet_len, data, &num_objects) == 0) {
            log_data(data, num_objects);
        }

        int remaining = frame_len - total_packet_len;
        if (remaining > 0) {
            memmove(frame_buf, frame_buf + total_packet_len, remaining);
        }
        frame_len = remaining;
    }

    free(read_buf);
    free(frame_buf);
    cleanup();
    return 0;
}

