#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <termios.h>
#include <time.h>
#include <sys/select.h>
#include <signal.h>

#define UART_DEVICE    "/dev/serial0"
#define BAUD_RATE      B115200
#define LINE_BUF_SIZE  256
#define READ_TIMEOUT_S 2
#define POLL_INTERVAL_S 0.5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int configure_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int parse_line(const char *line, time_t *timestamp, float *range) {
    char *endptr = NULL;
    errno = 0;
    long val = strtol(line, &endptr, 10);
    if (errno != 0 || endptr == line) {
        return -1;
    }
    *timestamp = (time_t)val;

    char *comma = strchr(endptr, ',');
    if (comma == NULL) {
        return -1;
    }
    *comma = '\0';

    errno = 0;
    float r = strtof(comma + 1, &endptr);
    if (errno != 0 || endptr == comma + 1) {
        return -1;
    }
    *range = r;
    return 0;
}

int main(void) {
    int fd = -1;
    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    time_t last_data_time = 0;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open(" UART_DEVICE ")");
        return EXIT_FAILURE;
    }

    if (configure_uart(fd) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("UART initialized on %s at 115200 baud.\n", UART_DEVICE);
    fflush(stdout);

    while (g_running) {
        fd_set readfds;
        struct timeval timeout;

        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        timeout.tv_sec  = READ_TIMEOUT_S;
        timeout.tv_usec = 0;

        int rv = select(fd + 1, &readfds, NULL, NULL, &timeout);
        if (rv == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("select");
            break;
        }
        if (rv == 0) {
            /* Timeout — no data within READ_TIMEOUT_S seconds */
            if (last_data_time != 0) {
                printf("No data received for %d seconds. Sensor may be absent or disconnected.\n",
                       READ_TIMEOUT_S);
                fflush(stdout);
                last_data_time = 0;
            }
            continue;
        }

        ssize_t n = read(fd, line_buf + line_len, LINE_BUF_SIZE - 1 - line_len);
        if (n == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("read");
            break;
        }
        if (n == 0) {
            continue;
        }

        line_len += (size_t)n;

        for (size_t i = 0; i < line_len; i++) {
            if (line_buf[i] == '\n') {
                line_buf[i] = '\0';

                time_t ts;
                float range;
                if (parse_line(line_buf, &ts, &range) == 0) {
                    struct tm tm_info;
                    localtime_r(&ts, &tm_info);
                    char ts_str[32];
                    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
                    printf("Timestamp: %s, Range: %.2f meters\n", ts_str, range);
                    fflush(stdout);
                    last_data_time = ts;
                } else {
                    fprintf(stderr, "Invalid data format: %s\n", line_buf);
                }

                size_t remaining = line_len - (i + 1);
                if (remaining > 0) {
                    memmove(line_buf, line_buf + i + 1, remaining);
                }
                line_len = remaining;
                break;
            }
        }

        sleep((int)POLL_INTERVAL_S);
    }

    if (fd != -1) {
        tcflush(fd, TCIOFLUSH);
        close(fd);
    }

    printf("\nUART closed. Exiting.\n");
    return EXIT_SUCCESS;
}

