    /* Clear O_NDELAY so reads block */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        perror("fcntl F_SETFL");
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;   /* 8-bit chars */
    tty.c_iflag &= ~IGNBRK;                        /* no break processing */
    tty.c_lflag = 0;                               /* no signal chars, no echo, no canonical */
    tty.c_oflag = 0;                               /* raw output */
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;                           /* 0.5 s inter-byte timeout */

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);        /* no software flow control */
    tty.c_cflag |= (CLOCAL | CREAD);               /* ignore modem controls, enable receiver */
    tty.c_cflag &= ~(PARENB | PARODD);             /* no parity */
    tty.c_cflag &= ~CSTOPB;                        /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;                       /* no hardware flow control */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int uart_write_line(int fd, const char *msg)
{
    size_t len = strlen(msg);
    ssize_t n = write(fd, msg, len);
    if (n < 0) {
        perror("write UART");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "UART partial write: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static void uart_close(int fd)
{
    if (fd >= 0) {
        tcflush(fd, TCIOFLUSH);
        close(fd);
    }
}

/* ------------------------------------------------------------------ */
/* Sensor readings                                                     */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Emergency stop                                                      */
/* ------------------------------------------------------------------ */
static void emergency_stop(int fd)
{
    time_t now = time(NULL);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));

    char msg[128];
    snprintf(msg, sizeof(msg), "%s EMERGENCY STOP!\n", ts);

    if (uart_write_line(fd, msg) != 0) {
        fprintf(stderr, "Failed to send emergency stop message\n");
    } else {
        printf("%s", msg);
        fflush(stdout);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    int pins[] = { LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN };
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "gpioSetPullUpDown failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- UART init ---- */
    g_uart_fd = uart_init(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        uart_close(g_uart_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-033 obstacle detection started (10 Hz). Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main loop ---- */
    while (g_running) {
        int left   = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right  = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error — continuing\n");
        } else {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));

            printf("%s  L:%d  M:%d  R:%d\n", ts, left, middle, right);
            fflush(stdout);

            if (left == 0 && middle == 0 && right == 0) {
                emergency_stop(g_uart_fd);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    uart_close(g_uart_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}
